/* 估價錯題複習卷題池（模擬卷 199 題＋歷屆 540 題）。由 tools/mockrec/pool.py 產生，不要手改。 */
window.BXPOOL={"S":"val","papers":{"mockc1":["估價綜合模擬卷一","估價_綜合模擬卷一.html"],"mockc2":["估價綜合模擬卷二","估價_綜合模擬卷二.html"],"mockc3":["估價綜合模擬卷三","估價_綜合模擬卷三.html"],"mockc4":["估價綜合模擬卷四","估價_綜合模擬卷四.html"],"mockc5":["估價綜合模擬卷五","估價_綜合模擬卷五.html"],"mockx1":["估價自編補強卷","估價_自編補強卷.html"],"hs1":["估價來勝模擬試題一","估價_來勝模擬試題一.html"],"vdiag1":["估價診斷卷①","估價_診斷卷一.html"]},"q":[{"id":"mockc1-1","p":"mockc1","src":"估價綜合模擬卷一 第1題","sec":"","stem":"自有資金占40%、要求報酬率6%；借貸資金占60%、利率3%。依加權平均資金成本法，資本化率為多少？","opts":["3.6%","4.2%","4.5%","4.8%"],"ok":[1],"ex":["3.6%＝60%×6%，權重錯置，且只算一種資金","資本化率＝ΣWiKi＝40%×6%＋60%×3%＝2.4%＋1.8%＝4.2%（§43 第3款）","4.5% 是簡單平均（6%＋3%）÷2，未依資金比率加權","4.8%＝40%×3%＋60%×6%，把兩種資金之比率對調"],"tr":""},{"id":"mockc1-2","p":"mockc1","src":"估價綜合模擬卷一 第2題","sec":"","stem":"依技術規則，租金估計應以估計下列何種租金為原則？","opts":["實質租金","契約租金","經濟租金","支付租金"],"ok":[0],"ex":["§130：租金估計以實質租金為原則；實質租金＝承租人每期支付之租金，加計押金或保證金、權利金及其他相關運用收益之總數","契約租金是契約約定之租金，是證券化 DCF 計算各期淨收益之原則，不是租金估計之原則","經濟租金是不動產以最有效利用方式在市場上所能產生之收益，不是規則指定之估計原則","支付租金只是承租人每期實際付出的租金本身，未含押金等之運用收益"],"tr":""},{"id":"mockc1-3","p":"mockc1","src":"估價綜合模擬卷一 第3題","sec":"","stem":"不動產估價應兼採二種以上估價方法。以契約約定租金作為不動產證券化受益證券信託利益分配基礎者，綜合決定價格時，下列何種價格宜賦予相對較大之權重？","opts":["成本法之成本價格","折現現金流量分析法之收益價格","直接資本化法之收益價格","比較法之比較價格"],"ok":[1],"ex":["成本法價格不是此情形下之權重重點","正確：以契約租金作為信託利益分配基礎者，DCF收益價格應賦予相對較大權重（§15；歷屆108-6、109-22、111-10）","直接資本化法以未來平均一年淨收益為基礎，不是此情形下之重點","比較法價格不是證券化契約租金情形下之權重重點"],"tr":""},{"id":"mockc1-4","p":"mockc1","src":"估價綜合模擬卷一 第4題","sec":"","stem":"有關土地分割及土地合併，下列何者正確？","opts":["土地合併之租金種類為限定租金","土地分割之價格種類為限定價格","土地分割之租金種類為限定租金","土地合併之價格種類為特定價格"],"ok":[0],"ex":["正確：限定租金指基於續訂租約或不動產合併為目的所形成之租賃價值（§2）。","僅「違反經濟合理性之不動產分割」才屬限定價格（§2），單說「土地分割」過於籠統，不是最正確選項。","限定租金只有「續訂租約」與「不動產合併」兩種原因（§2），分割不在其中，錯誤。","錯誤：以不動產合併為目的所形成之價值，價格種類是「限定價格」（§2 限定條件之二），不是特定價格。"],"tr":""},{"id":"mockc1-5","p":"mockc1","src":"估價綜合模擬卷一 第5題","sec":"","stem":"依§100，基地權利單價80萬元／坪，平均地價分配率40%，該區分所有建物之地價分配率50%，基地單價為多少？","opts":["100萬元／坪","80萬元／坪","64萬元／坪","32萬元／坪"],"ok":[2],"ex":["100＝80×50%÷40%，分子分母對調","80 是未做地價分配率調整","基地單價＝基地權利單價×平均地價分配率÷該建物之地價分配率＝80×40%÷50%＝64萬元／坪（§100；99-32 同一公式）","32＝80×40%，漏除該建物之地價分配率"],"tr":""},{"id":"mockc1-6","p":"mockc1","src":"估價綜合模擬卷一 第6題","sec":"","stem":"下列有關營造或施工費求取方法之敘述，何者錯誤？","opts":["單位工程法屬於直接法","淨計法屬於直接法","工程造價比較法屬於間接法","單位面積（或體積）比較法屬於直接法"],"ok":[3],"ex":["正確：單位工程法以細部工程單價乘以施工數量，屬直接法","正確：淨計法逐一計算材料與人工數量，屬直接法","正確：工程造價比較法比較標準建物之工程概算，屬間接法","錯誤：單位面積（或體積）比較法是以比較標的單位面積營造費為基礎調整，屬「間接法」。口訣：直淨單、間造面（名稱有「比較」二字的就是間接法）"],"tr":""},{"id":"mockc1-7","p":"mockc1","src":"估價綜合模擬卷一 第7題","sec":"","stem":"依「不動產估價技術規則」，土地開發分析法計算資本利息時，「預售收入」所形成之資金應如何處理？","opts":["不計息","比照借貸資金計息","一律按一年期定存利率計息","比照自有資金計息"],"ok":[0],"ex":["預售收入之資金不計息；資本利息依自有與借貸資金分別計息（§58、§59），再依§79綜合","預售收入並非借款，不比照借貸資金計息","一年期定存利率是自有資金利率之上限，不適用預售收入","自有資金利率介於活存與一年期定存利率之間（§59），預售收入不適用"],"tr":""},{"id":"mockc1-8","p":"mockc1","src":"估價綜合模擬卷一 第8題","sec":"","stem":"下列何者屬於影響不動產價格之「個別因素」？","opts":["地區經常淹水","政府宣布調降房貸利率","附近興建焚化爐","勘估標的為路角地且臨接道路寬度較大"],"ok":[3],"ex":["地區淹水影響整個近鄰地區，屬區域因素","房貸利率政策全面影響市場，屬一般因素","焚化爐設置影響周邊地區，屬區域因素（歷屆99-23將焚化爐列為非個別因素）","個別因素＝不動產本身條件所產生之價格差異因素；路角地、臨路寬度均為標的本身條件"],"tr":""},{"id":"mockc1-9","p":"mockc1","src":"估價綜合模擬卷一 第9題","sec":"","stem":"直接資本化法之公式：P＝a/r，則a代表下列何項？","opts":["比較標的的現在平均一年期間之客觀淨收益","比較標的的未來平均一年期間之客觀淨收益","勘估標的的現在平均一年期間之客觀淨收益","勘估標的的未來平均一年期間之客觀淨收益"],"ok":[3],"ex":["比較標的之淨收益是用來推算資本化率 r 的，不是 a。","比較標的不是 a 的來源。","直接資本化法的 a 是「未來」平均一年之淨收益，不是現在；現行 §29 沒有「現在」之用語（105-19、108-17、109-11、114-6 官方答案皆為「未來平均一年」）。","a＝勘估標的「未來」平均一年期間之客觀淨收益（§29、§30）。直接資本化法：收益價格＝勘估標的未來平均一年期間之客觀淨收益÷收益資本化率；DCF 則是未來「各期」淨收益加期末價值。"],"tr":""},{"id":"mockc1-10","p":"mockc1","src":"估價綜合模擬卷一 第10題","sec":"","stem":"依「不動產估價技術規則」，估價師進行估價時應實地勘察，下列何者非實地勘察之目的？","opts":["瞭解周邊環境與區位條件","確認建物現況與使用狀況","查閱比較案例之成交契約書","核對地籍資料與現況是否一致"],"ok":[2],"ex":["周邊環境（商業密集度、交通、景觀）需實地確認","實地勘察核心目的：確認建物現況（屋齡、維護狀況、設備）","成交契約書為書面資料蒐集工作，非實地勘察之內容；實地勘察係指到現場確認標的及環境狀況","地籍資料與現況核對（面積、地界）需實地查驗"],"tr":""},{"id":"mockc1-11","p":"mockc1","src":"估價綜合模擬卷一 第11題","sec":"","stem":"依債務保障比率法，債務保障比率1.4、貸款常數0.08、貸款資金占不動產價格比率70%，收益資本化率為多少？","opts":["11.20%","8.00%","7.84%","5.60%"],"ok":[2],"ex":["11.20%＝1.4×0.08，漏乘貸款資金比率","8.00% 無對應算式","收益資本化率＝債務保障比率×貸款常數×貸款資金占不動產價格比率＝1.4×0.08×0.7＝7.84%（§43 第4款，三個連乘）","5.60%＝0.08×0.7，漏乘債務保障比率"],"tr":""},{"id":"mockc1-12","p":"mockc1","src":"估價綜合模擬卷一 第12題","sec":"","stem":"價格日期當時勘估標的按法定用途出租或營運，在正常情況下所獲得之租金或收益數額，稱為：","opts":["收益價格","有效總收入","總收入","淨收益"],"ok":[2],"ex":["收益價格：最終估算出的不動產價值，非收益數額。","有效總收入（EGI）：已扣除空租損失後的收入。","總收入（PGI，潛在總收入；§36）：按法定用途、正常情況下可獲得之全額租金或收益，尚未扣除空租損失。","淨收益＝有效總收入－總費用（§42）；總費用包括地價稅或地租、房屋稅、保險費、管理費及維修費等，營運性不動產還要加計營運費用（§38）。"],"tr":""},{"id":"mockc1-13","p":"mockc1","src":"估價綜合模擬卷一 第13題","sec":"","stem":"依技術規則§23，下列何種比較標的之交易情況，應先作情況調整，其影響無法有效掌握及量化調整者，應不予採用？","opts":["親友關係人間之交易","經適當市場行銷、依一般條件成交之買賣","買賣雙方各自精通資訊、謹慎行動之公開交易","依正常付款條件成交且無特殊動機之買賣"],"ok":[0],"ex":["§23 列舉十三款特殊交易情況，第4款即「親友關係人間之交易」，價格常偏離正常，須先作情況調整（口訣：急期債親，畸糾拍公，迷設哄符他）","屬正常交易，不需情況調整","屬正常價格要件（§2），不需情況調整","屬正常交易情況，不需情況調整"],"tr":""},{"id":"mockc1-14","p":"mockc1","src":"估價綜合模擬卷一 第14題","sec":"","stem":"某建物位於高壓電塔附近，因電磁波疑慮導致市場購買意願降低，此現象最符合哪個不動產估價原則？","opts":["外部性原則","適合原則","預期原則","均衡原則"],"ok":[0],"ex":["外部性原則（估價基本原則）：不動產價格受外部因素正面或負面影響。高壓電塔屬「外部嫌惡設施」→負外部性。 113年考法：高壓電塔→外部性原則（113-2）；「房子距大安森林公園約50公尺」→非區域因素（113-18，屬標的本身條件）。","適合原則談不動產與周圍環境是否相稱；電塔屬外部嫌惡設施對價格之影響，較符合外部性原則","預期原則談價格取決於對未來利益之預期，不是本題電塔外部影響所致","均衡原則談各構成要素組合之均衡，與本題無關"],"tr":""},{"id":"mockc1-15","p":"mockc1","src":"估價綜合模擬卷一 第15題","sec":"","stem":"比較法中，「區域因素調整」主要調整下列何者？","opts":["勘估標的與比較標的之土地面積差異","勘估標的與比較標的所在地區環境條件之差異","勘估標的與比較標的之臨路寬度差異","勘估標的與比較標的之建物層數差異"],"ok":[1],"ex":["面積差異屬個別因素調整範疇","區域因素調整係就勘估標的與比較標的所處地區（商業環境、交通、公共設施等）差異進行調整（技術規則§19、§24）","臨路寬度屬個別因素之土地條件","建物層數屬個別因素之建物條件"],"tr":""},{"id":"mockc1-16","p":"mockc1","src":"估價綜合模擬卷一 第16題","sec":"","stem":"依「不動產估價技術規則」，「最有效使用」之判斷準則，下列何者不屬於其要件？","opts":["財務可行","實質可能","合法","主觀上最符合業主期望"],"ok":[3],"ex":["「財務可行」為前提之一（§2第17款）","「實質可能」為前提之一（§2第17款）","「合法」為最有效使用之前提之一（§2第17款）","最有效使用是「客觀上」具良好意識及通常使用能力者，在合法、實質可能、正當合理、財務可行前提下之使用；並無「主觀符合業主期望」這一項"],"tr":""},{"id":"mockc1-17","p":"mockc1","src":"估價綜合模擬卷一 第17題","sec":"","stem":"區域因素，指影響下列何項地區不動產價格水準之因素？","opts":["同一生活圈","類似地區","同一供需圈","近鄰地區"],"ok":[3],"ex":["同一生活圈不是規則用語。","類似地區是同一供需圈內、近鄰地區以外使用性質相近的地區（§2 第13款），不是區域因素的影響範圍。","同一供需圈（§2 第11款）是比較標的與勘估標的能成立替代關係的最適範圍，等於近鄰地區＋類似地區；區域因素的條文用語是「近鄰地區」，不是「同一供需圈」。","近鄰地區：§2 第15款「區域因素，指影響近鄰地區不動產價格水準之因素」。"],"tr":""},{"id":"mockc1-18","p":"mockc1","src":"估價綜合模擬卷一 第18題","sec":"","stem":"「差額分配法」是應用在下列何種估價或估計之方法？","opts":["新訂租約之租金估計","區分地上權估價","租賃權估價","續訂租約之租金估計"],"ok":[3],"ex":["新訂租約依§132採比較法、價格×租金收益率、企業經營總收入三種方式，沒有差額分配法。","地上權估價依§116考量用途、存續期間、地租等因素，條文沒有差額分配法。","租賃權估價依§122考量契約內容、租期、租金支付方式等因素，條文沒有差額分配法。","差額分配法是§133第4款續訂租約的方法：「分析勘估標的原契約租金與市場經濟租金之差額中，應歸屬於出租人之適當部分，加計契約租金」。"],"tr":""},{"id":"mockc1-19","p":"mockc1","src":"估價綜合模擬卷一 第19題","sec":"","stem":"建物總成本1,000萬元，經濟耐用年數30年，殘餘價格率5%，經歷年數15年，則以定額法計算累積折舊額為多少？","opts":["425萬元","450萬元","475萬元","495萬元"],"ok":[2],"ex":["425萬：計算錯誤。","450萬：誤把殘餘價格率當成10%（1,000×90%÷30×15＝450）；本題s＝5%。若忽略殘值則為1,000÷30×15＝500萬。","475萬元。定額法：每年折舊=(1000-1000×5%)÷30=950÷30≈31.67萬。累積15年=31.67×15=475萬。","495萬：計算錯誤。"],"tr":""},{"id":"mockc1-20","p":"mockc1","src":"估價綜合模擬卷一 第20題","sec":"","stem":"依不動產估價技術規則，建物定額折舊法（直線法）累積折舊額Dn之公式，下列何者正確？（C：重建或重置成本；s：殘餘價格率；N：經濟耐用年數；n：經過年數）","opts":["Dn＝C×(1＋s)/N×n","Dn＝C×(1－s)/N×n","Dn＝C×s/N×n","Dn＝C/(1－s)×N×n"],"ok":[1],"ex":["應用「1－s」非「1＋s」。","定額法（直線法）：累積折舊額 Dn＝C×(1－s)/N×n（教材公式；技術規則§68只規定可選擇等速折舊路徑，沒有列出累積折舊額公式；殘餘價格率以不超過10%為原則，§67）。 累積折舊額 Dn ＝ C × (1－s) ÷ N × n","s是留下來的部分，不可直接乘。","式中把殘餘價格率放在分母，與定額法無關；定額法累積折舊額＝C×(1－s)÷N×n"],"tr":""},{"id":"mockc1-21","p":"mockc1","src":"估價綜合模擬卷一 第21題","sec":"","stem":"依「不動產估價技術規則」，成本法求算成本價格時，土地與建物之成本價格各如何計算？","opts":["土地、建物均為總成本減累積折舊","土地為總成本；建物為總成本減累積折舊","土地、建物均為總成本，不減折舊","土地為總成本減累積折舊；建物為總成本"],"ok":[1],"ex":["土地不折舊，錯誤","技術規則§69：土地之成本價格為其總成本；建物之成本價格為總成本減累積折舊額","建物須減累積折舊額","方向顛倒"],"tr":""},{"id":"mockc1-22","p":"mockc1","src":"估價綜合模擬卷一 第22題","sec":"","stem":"依「不動產估價技術規則」，估價報告書應載明之事項共有幾款？","opts":["十五款","十二款","十款","十八款"],"ok":[0],"ex":["§16：估價報告書應載明十五款事項，由不動產估價師簽名或蓋章後交付委託人","十二款非規定數字","十款非規定數字","十八款非規定數字"],"tr":""},{"id":"mockc1-23","p":"mockc1","src":"估價綜合模擬卷一 第23題","sec":"","stem":"不動產估價師在估價過程中，發現比較案例中某筆為「法拍屋」成交，該如何處理？","opts":["依實際需求決定是否採用，無需進行情況調整","直接採用，因法拍屋屬公開市場交易","不得採用，因技術規則明令禁止引用法拍案例","須進行情況調整以排除強迫拍賣之折扣影響"],"ok":[3],"ex":["法拍屋必然存在情況調整之必要性","法拍屋雖為公開市場，但存在強制出售因素，非正常市場條件","並非一概禁止；§23 是「應先作適當之調整；該影響交易價格之情況無法有效掌握及量化調整時，應不予採用」，不是明令禁止引用法拍案例","法拍屬§23 特殊交易情況（第7款拍賣），須先作情況調整以排除強制拍賣之影響；其影響無法有效掌握及量化調整者，應不予採用"],"tr":""},{"id":"mockc1-24","p":"mockc1","src":"估價綜合模擬卷一 第24題","sec":"","stem":"依「不動產估價技術規則」，正常價格之定義，下列何者有誤？","opts":["係指在公開市場上，於買賣雙方均有充分資訊下成交之合理價格","係指強制拍賣情況下之市場成交價格","係假設勘估標的在充分行銷期間後成交之價格","係在交易雙方主觀上均無特殊動機下之客觀合理價格"],"ok":[1],"ex":["可視為正確的描述。§2第1款的用語是「依專業知識、謹慎行動」「經適當市場行銷」；「公開市場、充分資訊」是教材對這些要件的白話說法","✗ 錯誤。強制拍賣情況非屬「不受脅迫、經適當市場行銷及正常交易條件」，不符正常價格定義（§2）","正確，經適當市場行銷為正常價格之要件之一（技術規則§2）","正確，交易雙方無特殊動機（非強迫、急售）"],"tr":""},{"id":"mockc1-25","p":"mockc1","src":"估價綜合模擬卷一 第25題","sec":"","stem":"就勘估標的所需要各種建築材料及人工之數量，逐一乘以價格日期當時之單價及人工工資，並加計管理費、稅捐、資本利息及利潤，以求取營造或施工費之方法，稱為下列何者？","opts":["工程造價比較法","單位工程法","淨計法","單位面積（或體積）比較法"],"ok":[2],"ex":["工程造價比較法是間接法，以概算項目比較調整","單位工程法是以細部工程「各項目單價」乘以施工數量，並非逐一計算材料與人工數量","淨計法（直接法，相對最精細）：逐一以材料及人工之數量乘單價與工資，並加計管理費、稅捐、資本利息及利潤（§55第1款；歷屆106-40、112-12、114-18）","單位面積比較法是間接法，以單位面積營造費調整"],"tr":""},{"id":"mockc2-1","p":"mockc2","src":"估價綜合模擬卷二 第1題","sec":"","stem":"收益法以勘估標的未來之淨收益為基礎推估價格，其理論基礎主要為下列何種估價原則？","opts":["替代原則","變動原則","均衡原則","預期原則"],"ok":[3],"ex":["替代原則是比較法之理論基礎","變動原則談的是價格隨因素變動，並非用未來收益折現之理由","均衡原則談的是各構成要素組合之均衡，不是收益法之基礎","預期原則：不動產價格取決於購買人對其未來可獲得利益之預期，收益法將未來淨收益還原為現值，正是此原則之運用"],"tr":""},{"id":"mockc2-2","p":"mockc2","src":"估價綜合模擬卷二 第2題","sec":"","stem":"依「不動產估價技術規則」，成本法中建物「重建成本」之意義，下列敘述何者正確？","opts":["使用與勘估標的相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製所需成本","建物取得時之歷史成本扣除折舊後之餘額","以現代建材標準、設計及配置，建造相同效用建物所需費用","建物現況如欲繼續使用所需之維修費用"],"ok":[0],"ex":["重建成本＝以相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製之成本；建物估價以重建成本為原則（§48）","此為帳面價值或歷史成本概念，非技術規則定義","此為「重置成本」之定義——以現代建材標準、設計及配置建造相同效用之建物；僅在建材已無生產或施工方法已改變時，才得以重置成本替代（§48）","維修費用係修繕成本，非重建成本之範疇"],"tr":""},{"id":"mockc2-3","p":"mockc2","src":"估價綜合模擬卷二 第3題","sec":"","stem":"下列何者「不是」新訂租約租金之估計方式（§132）？","opts":["以新訂租約實例，運用比較法估計","分析原契約租金與市場經濟租金之差額中應歸屬出租人之適當部分，再加計契約租金（差額分配法）","分析企業經營總收入，估計淨收益再加計必要費用","以勘估標的價格乘以租金收益率估計淨收益，再加計必要費用"],"ok":[1],"ex":["屬新訂租約三方式之一（§132：新訂租約實例比較法）","差額分配法是 §133 第4款「續訂租約」之估計方式，不屬新訂租約；§131 規定新訂與續訂租約之租金應分別估計","屬新訂租約三方式之一（§132：企業經營總收入估計淨收益，再加必要費用）","屬新訂租約三方式之一（§132：價格×租金收益率估計淨收益，再加必要費用）"],"tr":""},{"id":"mockc2-4","p":"mockc2","src":"估價綜合模擬卷二 第4題","sec":"","stem":"依§92，林地之估價方法，下列何者正確？","opts":["一律以收益法為原則","一律以成本法為原則","視林木成長情形，分別採比較法、收益法或成本法","一律以比較法為原則"],"ok":[2],"ex":["林地不是一律收益法","林地不是一律成本法","§92：林地依林木成長情形分別採比較法、收益法或成本法；成本法總費用加計造林費、林地改良費、道路開挖費。最高頻陷阱：不是「比較法為原則」（比較法為原則的是農場牧場、鹽田、池沼、墓地、公共設施用地）","林地不是比較法為原則（常考陷阱）"],"tr":""},{"id":"mockc2-5","p":"mockc2","src":"估價綜合模擬卷二 第5題","sec":"","stem":"依「不動產估價技術規則」§14，估價師採用估價方法之原則，下列何者正確？","opts":["一律只須採用委託人指定之一種方法","一律只採用比較法，因其最貼近市場","原則上應兼採二種以上方法；因情況特殊不能採二種以上並於報告書敘明者，不在此限","一律只採用收益法，因其最能反映價值"],"ok":[2],"ex":["並無「依委託人指定採單一方法」之規定","規則並未限定只採比較法","§14：應兼採二種以上估價方法推算勘估標的價格；但因情況特殊不能採二種以上方法並於報告書敘明者，不在此限（常考「例外」反面題）","規則並未限定只採收益法"],"tr":""},{"id":"mockc2-6","p":"mockc2","src":"估價綜合模擬卷二 第6題","sec":"","stem":"房地總價3,000萬元，土地價值比率70%，基地面積30坪。依§99 第2項，基地單價為多少？","opts":["30萬元／坪","70萬元／坪","90萬元／坪","100萬元／坪"],"ok":[1],"ex":["30＝3,000×30%÷30，誤用了建物價值比率","基地價格＝房地價格×土地價值比率＝3,000×70%＝2,100萬；基地單價＝2,100÷30＝70萬元／坪（§99）","90 無對應算式","100＝3,000÷30，未乘土地價值比率，把房地總價全部當成基地"],"tr":""},{"id":"mockc2-7","p":"mockc2","src":"估價綜合模擬卷二 第7題","sec":"","stem":"依技術規則，應用計量模型分析法時，下列何者符合規定？","opts":["調整後判定係數為0.65","蒐集之比較標的數為自變數個數之3倍","截距項以外各主要影響因素係數估計值同時為零之顯著機率為4%","自變數個數不受限制，只要判定係數高即可"],"ok":[2],"ex":["調整後判定係數不得低於0.7，0.65不符","須為自變數個數「5倍以上」，3倍不足","正確：顯著機率不得大於5%，4%符合（§20；剛好5%亦符合）","規則對樣本數（5倍以上）、判定係數（調整後≥0.7）、顯著機率（≤5%）均有要求，不是只看判定係數"],"tr":""},{"id":"mockc2-8","p":"mockc2","src":"估價綜合模擬卷二 第8題","sec":"","stem":"依§71 估價程序，在「估算總銷售金額」之前，應先完成下列何項？","opts":["估算開發後可銷售之土地或建物面積","計算開發分析價格","選擇適當利潤率及資本利息綜合利率","估算各項成本費用"],"ok":[0],"ex":["§71 程序：確定開發內容及預期時間→調查成本費用及市場行情→現況勘察並調查環境發展程度→估算可銷售面積→估算總銷售金額→估算各項成本費用→選擇利潤率及資本利息綜合利率→計算開發分析價格","是最後一步，在總銷售金額之後","屬總銷售金額之後的步驟（倒數第二步）","估算各項成本費用在總銷售金額之後"],"tr":""},{"id":"mockc2-9","p":"mockc2","src":"估價綜合模擬卷二 第9題","sec":"","stem":"依不動產估價技術規則，蒐集比較實例應符合的四項原則，下列何者不屬於其中之一？","opts":["實例價格形成日期與價格日期接近","實例與勘估標的使用性質或使用管制相同或相近","實例位於同一供需圈之近鄰地區或類似地區","實例之成交價格須高於公告地價以上"],"ok":[3],"ex":["屬 §12 第4款：實例價格形成日期與價格日期接近，正確之原則","屬 §12 第3款：使用性質或使用管制相同或相近，正確之原則","屬 §12 第2款：同一供需圈之近鄰地區或類似地區，正確之原則","蒐集比較實例四原則（技術規則§12）：①價格屬正常價格、可調整為正常價格或價格種類相同 ②同一供需圈之近鄰地區或類似地區 ③使用性質或使用管制相同或相近 ④價格形成日期與價格日期接近。"],"tr":""},{"id":"mockc2-10","p":"mockc2","src":"估價綜合模擬卷二 第10題","sec":"","stem":"下列何種情況，可歸類於不動產估價價格種類中之「正常價格」？","opts":["國家級古蹟之價值","鄰地所有權人為合併使用而欲購買之土地價格","政府辦理土地徵收，依法查估之補償市價","都市邊緣農地以未來變更為建地為前提之價格"],"ok":[2],"ex":["古蹟不具市場性，屬特殊價格","為合併目的所形成之價值屬限定價格","土地徵收補償所查估之市價，是依正常市場交易條件查估之價格，歷屆題（102-2、106-2）判為正常價格","以變更使用為前提屬特定價格，須敘明估價條件並同時估計正常價格（§6 後段）"],"tr":""},{"id":"mockc2-11","p":"mockc2","src":"估價綜合模擬卷二 第11題","sec":"","stem":"公立博物館建物（具文化保存價值，不在市場上買賣）之估價，應採下列何種價格種類？","opts":["正常價格","特殊價格","特定價格","限定價格"],"ok":[1],"ex":["正常價格以具市場性為前提，博物館不在市場交易","特殊價格（技術規則§2第4款：對不具市場性之不動產所估計之價值）：非市場性不動產，因用途特殊或無市場交易（文化財、宗教用地、廟宇、博物館），以外於市場的價值概念決定之價格。","特定價格也是「具市場性」之不動產基於特定條件形成之價值","限定價格仍是「具市場性」之不動產在合併、分割等限定條件下之價值，博物館不具市場性"],"tr":""},{"id":"mockc2-12","p":"mockc2","src":"估價綜合模擬卷二 第12題","sec":"","stem":"某房地年淨收益為120萬元，其中建物年淨收益為70萬元（已扣除折舊提存費）；土地收益資本化率2.5%，建物收益資本化率5%。依技術規則，土地收益價格為何？","opts":["4,800萬元","2,800萬元","2,000萬元","1,000萬元"],"ok":[2],"ex":["120÷2.5%＝4,800萬元，是把房地淨收益全部歸給土地，沒有扣掉建物淨收益","70÷2.5%＝2,800萬元，是拿「建物淨收益」除以土地資本化率，對象搞反","地上有建物者，土地收益價格＝（房地淨收益－建物淨收益）÷土地收益資本化率＝（120－70）÷2.5%＝2,000萬元（§44～§45）。附帶：建物收益價格＝70÷5%＝1,400萬元","（120－70）÷5%＝1,000萬元，是用建物資本化率去除土地淨收益，率用錯"],"tr":""},{"id":"mockc2-13","p":"mockc2","src":"估價綜合模擬卷二 第13題","sec":"","stem":"依§26，各試算價格中最高為1,200萬元、最低為960萬元，其差距（以高低價格之平均值為基礎）及處理方式，下列何者正確？","opts":["差距20.0%，未達門檻，免重新檢討","差距25.0%，直接排除該比較標的","差距約22.2%，直接取兩價格算術平均即可","差距約22.2%，已達20%以上，應先重新檢討；檢討後仍達20%以上者，排除該試算價格"],"ok":[3],"ex":["240÷1,200＝20.0% 是錯用「最高價」當分母；規則以高低價格之平均值為分母","240÷960＝25.0% 是錯用「最低價」當分母；且§26 排除的是試算價格，且須先重新檢討","差距達20%以上不可直接平均，須重新檢討（機械式平均不符規定）","差距＝（1,200－960）÷〔（1,200＋960）÷2〕＝240÷1,080≈22.2%，達20%以上；§26 要求先重新檢討，確認適當合理者始得作為決定比較價格之基礎，檢討後差距仍達20%以上者排除"],"tr":""},{"id":"mockc2-14","p":"mockc2","src":"估價綜合模擬卷二 第14題","sec":"","stem":"依「不動產估價技術規則」，資本化率之求取方式，不包含下列何者？","opts":["市場萃取法（以比較標的淨收益÷價格之商數決定）","債務保障比率法（債務保障比率×貸款常數×貸款資金比率）","加權平均資金成本法（Σ資金比率×資金成本）","成本加成法（重建成本加計利潤率）"],"ok":[3],"ex":["屬§43 五法之一（市場萃取法）","屬§43 五法之一（債務保障比率法）","屬§43 五法之一（加權平均資金成本法）","成本加成法不在§43 五法之內（五法＝風險溢酬、市場萃取、加權平均資金成本、債務保障比率、有效總收入乘數）；重建成本是成本法之概念，與資本化率無關"],"tr":""},{"id":"mockc2-15","p":"mockc2","src":"估價綜合模擬卷二 第15題","sec":"","stem":"比較法估算「價格日期調整」之目的為何？","opts":["將比較標的交易日期之價格水準調整為勘估標的價格日期之價格","調整比較標的個別條件之差異","排除比較標的非正常成交之特殊因素","調整比較標的地區與勘估標的地區之差異"],"ok":[0],"ex":["價格日期調整係將比較標的之成交價格，依市場變動（如地價指數、房價走勢）調整至價格日期（技術規則§19第2款）","調整個別條件差異屬「個別因素調整」","排除非正常成交因素屬「情況調整」","調整地區差異屬「區域因素調整」"],"tr":""},{"id":"mockc2-16","p":"mockc2","src":"估價綜合模擬卷二 第16題","sec":"","stem":"下列何者屬於「個別因素」？","opts":["該重劃區整體房價水準很高","某戶房屋面對公園第一排","政府公告調整房地合一稅制","某生活圈生活機能良好"],"ok":[1],"ex":["整體房價水準屬區域因素","個別因素＝不動產本身條件所產生之價格差異因素（112-1：面對公園第一排屬個別因素）","稅制調整屬一般因素","生活圈機能屬區域因素"],"tr":""},{"id":"mockc2-17","p":"mockc2","src":"估價綜合模擬卷二 第17題","sec":"","stem":"關於資本利息與開發（建築）利潤之計算基礎，下列何者正確？","opts":["利潤與資本利息之計算基礎完全相同","資本利息之計算基礎包含利潤，利潤之計算基礎不含資本利息","土地或包含土地者，兩者之計算基礎均不得加計土地價格","利潤之計算基礎包含資本利息，資本利息之計算基礎則不含利潤"],"ok":[3],"ex":["兩者基礎不同：利潤的基礎多了「資本利息」","方向顛倒：是利潤基礎含資本利息，不是資本利息基礎含利潤","土地或包含土地者，合計額「另加計土地價格」（§58Ⅲ、§60Ⅳ）","§60：利潤＝（營造施工費＋規劃設計費＋廣告費＋銷售費＋管理費＋資本利息＋稅捐及其他負擔）之合計額×利潤率；§58：資本利息之基礎不含利息與利潤。兩者遇土地者皆另加計土地價格（§58Ⅲ、§60Ⅳ）"],"tr":""},{"id":"mockc2-18","p":"mockc2","src":"估價綜合模擬卷二 第18題","sec":"","stem":"某不動產年淨收益為120萬元，土地價格占整體不動產60%，建物價格占40%，土地資本化率4%，建物資本化率8%，則房地綜合資本化率為何？","opts":["5.2%","5.6%","6.0%","6.4%"],"ok":[1],"ex":["5.2%＝4%×70%＋8%×30%，土地、建物價值比率代錯（題目為60%：40%）","綜合資本化率＝4%×60%＋8%×40%＝2.4%＋3.2%＝5.6%（技術規則§46：依土地、建物價值比率加權）","6.0%為50：50之平均，題目給定比例非五五分","6.4%為4%×40%+8%×60%，土建比例互換之錯誤"],"tr":""},{"id":"mockc2-19","p":"mockc2","src":"估價綜合模擬卷二 第19題","sec":"","stem":"建物總成本1,000萬元，經濟耐用年數50年，殘餘價格率10%，已經歷10年。分別以定額法、定率法、償債基金法（利率2%）計算建物現值，結果由小到大排列，何者正確？","opts":["定率法＜償債基金法＜定額法","定率法＜定額法＜償債基金法","定額法＜定率法＜償債基金法","償債基金法＜定額法＜定率法"],"ok":[1],"ex":["償債基金法現值（883.5）高於定額法（820）","正確：定額法現值＝1,000−900×10÷50＝820萬；定率法現值＝1,000×0.1¹⁰⁄⁵⁰≈631萬；償債基金法累積折舊≈900×(1.02¹⁰−1)÷(1.02⁵⁰−1)≈116.5萬，現值≈883.5萬。631＜820＜883.5。定率法先降得多、償債基金法先降得少、定額法走直線，經歷年數介於0與耐用年數之間時順序固定（歷屆102-16）","定額法（820）高於定率法（631），順序錯","償債基金法折舊最慢，現值最高，不會最低"],"tr":""},{"id":"mockc2-20","p":"mockc2","src":"估價綜合模擬卷二 第20題","sec":"","stem":"下列何者屬於影響不動產價格之「一般因素」？①政府調整房地合一稅制 ②央行調整重貼現率 ③社區附近新設捷運站 ④勘估標的屬路角地","opts":["①②","①③","②④","③④"],"ok":[0],"ex":["①②正確：一般因素＝對不動產市場及價格水準發生「全面」影響之自然、政治、社會、經濟等共同因素（§2），稅制與貨幣政策屬之","①正確，但③捷運站設置影響近鄰地區，屬區域因素","④路角地是不動產本身條件，屬個別因素","③區域因素、④個別因素，均非一般因素"],"tr":""},{"id":"mockc2-21","p":"mockc2","src":"估價綜合模擬卷二 第21題","sec":"","stem":"公寓加裝電梯後價格提升，最符合下列何種估價原則？","opts":["外部性原則","替代原則","適合原則","貢獻原則"],"ok":[3],"ex":["外部性原則是外部環境之正負影響（如嫌惡設施、捷運設站）","替代原則是審慎者不會支付高於同滿意度替代財貨之代價（三法之評價基礎）","適合原則是不動產與環境配合協調（如學校旁開書局）","貢獻原則：各生產要素（如電梯設備）對整體價值之貢獻程度（110-4、112-5）"],"tr":""},{"id":"mockc2-22","p":"mockc2","src":"估價綜合模擬卷二 第22題","sec":"","stem":"不動產估價之租金種類有二種，其中一種為正常租金，另一種為何？","opts":["特殊租金","限定租金","特定租金","有效租金"],"ok":[1],"ex":["特殊租金：非正確術語。","限定租金：基於續訂租約或不動產合併為目的所形成之租賃價值（技術規則§2）。租金種類只有正常租金、限定租金兩種（§2 第5、6款）。","特定租金：非技術規則用語。","有效租金：收益法用語（EGI），非租金種類分類。"],"tr":""},{"id":"mockc2-23","p":"mockc2","src":"估價綜合模擬卷二 第23題","sec":"","stem":"依定率法（餘額遞減法）計算折舊，建物重建成本C＝500萬元，折舊率d＝10%，則第2年末之帳面價值為何？","opts":["405萬元","400萬元","450萬元","410萬元"],"ok":[0],"ex":["第1年：折舊500×10%＝50萬，帳面450萬。第2年：折舊450×10%＝45萬，帳面405萬。 第n年帳面 ＝ C × (1－d)ⁿ ＝ 500 × (0.9)² ＝ 405萬 考試陷阱：定率法對「帳面價值」課折舊，非原始成本；第2年折舊額45萬≠第1年50萬。","400萬是把兩年折舊率相加（20%）後直接乘500萬，但定率法是逐年對「前一年末餘額」折舊，第2年應以450萬為基礎","450萬是第1年末之帳面價值，題目問第2年末","與公式 C×(1－d)ⁿ＝500×0.81＝405萬不符，410萬沒有對應算法"],"tr":""},{"id":"mockc2-24","p":"mockc2","src":"估價綜合模擬卷二 第24題","sec":"","stem":"下列何者不屬於「不動產市場特性」？","opts":["不動產市場資訊完整透明，交易效率高","不動產交易成本高（稅費、仲介費）","不動產商品具不可移動性","每筆不動產具有個別性，難以完全標準化"],"ok":[0],"ex":["不動產市場資訊不完整（非透明市場）、交易效率低，是不動產市場之重要特性，與金融市場相比資訊更不對稱","稅費、仲介費等交易成本高確為不動產市場特性","不可移動性（固定性）為不動產基本特性","個別性（每筆標的地點、形狀、條件均不同）為不動產基本特性"],"tr":""},{"id":"mockc2-25","p":"mockc2","src":"估價綜合模擬卷二 第25題","sec":"","stem":"下列何者不屬於「不動產估價技術規則」所列舉之估價方法？","opts":["收益法","成本法","效益法","比較法"],"ok":[2],"ex":["收益法為技術規則明定之基本估價方法之一（§28：直接資本化法、DCF 皆屬收益法）","成本法為技術規則明定之基本估價方法之一","「效益法」不是規則之估價方法（規則另有土地開發分析法，§70）；此為混淆選項","比較法為技術規則明定之基本估價方法之一"],"tr":""},{"id":"mockc3-1","p":"mockc3","src":"估價綜合模擬卷三 第1題","sec":"","stem":"按工程概算項目逐項比較勘估標的與比較標的（或標準建物）之差異，並依工程價格及工程數量比率進行調整，以求取營造或施工費之方法，稱為下列何者？","opts":["單位工程法","工程造價比較法","單位面積（或體積）比較法","淨計法"],"ok":[1],"ex":["單位工程法是以建築細部工程各項目單價乘以施工數量（直接法）","工程造價比較法：按工程概算項目逐項比較、依工程價格及數量比率調整（間接法）；歷屆99-7、101-12出題","單位面積比較法是以單位面積營造費單價為基礎調整後乘以面積，不是逐項概算比較","淨計法是逐一以材料及人工數量乘以單價及工資（直接法）"],"tr":""},{"id":"mockc3-2","p":"mockc3","src":"估價綜合模擬卷三 第2題","sec":"","stem":"某開發案預期總銷售金額為100,000萬元，直接成本與間接成本合計55,000萬元，適當利潤率20%，資本利息綜合利率5%。依§81 公式，土地開發分析價格約為多少？","opts":["35,714萬元","25,000萬元","24,365萬元","21,000萬元"],"ok":[2],"ex":["(100,000－55,000)÷1.2÷1.05≈35,714，是先扣成本再折現，順序錯；應先把 S 除以（1＋R）、再除以（1＋i），最後才減（C＋M）","100,000÷(1＋20%＋5%)－55,000＝25,000，是把利潤率與利息率相加再除；公式是「連除兩次」","V＝S÷(1＋R)÷(1＋i)－(C＋M)＝100,000÷1.2÷1.05－55,000≈79,365－55,000＝24,365萬元（§81）","100,000×(1－20%)×(1－5%)－55,000＝21,000，是用「乘（1－率）」代替「除（1＋率）」"],"tr":""},{"id":"mockc3-3","p":"mockc3","src":"估價綜合模擬卷三 第3題","sec":"","stem":"依「不動產估價技術規則」，建物折舊之計算，原則上應以下列何種年數為主？","opts":["建物已使用年數","物理耐用年數","經濟耐用年數","稅法規定之耐用年數"],"ok":[2],"ex":["已使用年數（經歷年數）是計算累積折舊時之 n，不是折舊所採之耐用年數基準","§65以經濟耐用年數為主，「必要時得以物理耐用年數計算」，所以物理耐用年數是例外，不是原則","技術規則§65：折舊以經濟耐用年數為主；經濟耐用年數表由全聯會公告（§66）","稅法耐用年數係稅務目的，非估價折舊之主要依據"],"tr":""},{"id":"mockc3-4","p":"mockc3","src":"估價綜合模擬卷三 第4題","sec":"","stem":"某建物經濟耐用年數50年、已經歷20年、殘餘價格率10%。依等速折舊型，建物價格日期當時價值未來每年折舊提存率約為多少？","opts":["3.20%","2.81%","2.25%","1.80%"],"ok":[1],"ex":["3.20% 無對應算式，為干擾數字","d＝[(1－s)/N]÷[1－(1－s)n/N]＝(0.9÷50)÷(1－0.9×20÷50)＝0.018÷0.64≈2.81%（§41）","2.25% 是 0.9÷40 之誤（耐用年數代錯）","1.80% 是只算分子（1－s）/N＝0.9÷50，漏除「目前價值成數」0.64；因為分母是現值成數，提存率會大於 1.8%"],"tr":""},{"id":"mockc3-5","p":"mockc3","src":"估價綜合模擬卷三 第5題","sec":"","stem":"下列有關同一供需圈、近鄰地區與類似地區之敘述，何者正確？","opts":["同一供需圈係指比較標的與勘估標的價格互不影響之範圍","類似地區係指近鄰地區內使用性質相近之部分","同一供需圈與近鄰地區為相同概念","同一供需圈包含近鄰地區及類似地區"],"ok":[3],"ex":["同一供需圈之重點是「價格互為影響」（替代關係），不是互不影響","類似地區是近鄰地區「以外」之地區，不在近鄰地區內","同一供需圈範圍較大，不等於近鄰地區","正確：同一供需圈＝比較標的與勘估標的能成立替代關係、價格互為影響之最適範圍，涵蓋近鄰地區及其以外之類似地區（§2第11～13款）"],"tr":""},{"id":"mockc3-6","p":"mockc3","src":"估價綜合模擬卷三 第6題","sec":"","stem":"估價師至現場勘察時，委託人未領勘、無法確認勘估標的範圍，或無法進入室內勘察，依技術規則應如何處理？","opts":["應於估價報告書中敘明","改以公告地價或公告現值代替估價","由委託人切結範圍後視同已完成勘察","不得估價，應退還委託"],"ok":[0],"ex":["§13：委託人未領勘、無法確認勘估標的範圍或無法進入室內勘察時，應於估價報告書敘明","公告地價、公告現值不能取代現場勘察","規則無「切結即視同勘察」之規定","規則並未規定此情形不得估價"],"tr":""},{"id":"mockc3-7","p":"mockc3","src":"估價綜合模擬卷三 第7題","sec":"","stem":"某大廈某層發生命案（凶宅），導致該戶市場價格低於其他相同樓層，此屬於下列何種影響因素？","opts":["區域因素","外部因素","一般因素","個別因素"],"ok":[3],"ex":["凶宅只影響該戶，不是整個近鄰地區之共同條件，故非區域因素","技術規則沒有「外部因素」這個分類，只有一般、區域、個別三類","一般因素是全面影響市場之共同因素，單一住戶事件不屬之","個別因素：影響「個別不動產」本身的因素（地形、座向、樓層、凶宅污名）（112年申論考點）。 凶宅僅影響該「戶」→個別因素。若整棟附近大事→區域因素；全市政策→一般因素。"],"tr":""},{"id":"mockc3-8","p":"mockc3","src":"估價綜合模擬卷三 第8題","sec":"","stem":"不動產估價技術規則有關「正常價格」之定義，下列何項錯誤？","opts":["正常特定條件","經適當市場行銷","具有市場性之不動產","不受任何脅迫"],"ok":[0],"ex":["✗ 錯誤。正常價格是「經適當市場行銷及正常交易條件形成之合理價值」（§2第1款）；「特定條件」是特定價格的要素（§2第3款）。","「經適當市場行銷」為正常價格要件，正確。","正常價格定義包含「具市場性」，正確，本選項無誤。","「不受任何脅迫」為正常價格要件，正確。"],"tr":""},{"id":"mockc3-9","p":"mockc3","src":"估價綜合模擬卷三 第9題","sec":"","stem":"採計量模型分析法估價，自變數個數為7個，依技術規則，至少須蒐集多少件比較標的？","opts":["21件","28件","35件","49件"],"ok":[2],"ex":["21件是3倍","28件是4倍","正確：須蒐集自變數個數5倍以上之比較標的，7×5＝35件（§20；歷屆107-4、111-6同型）","49件是7倍，超過最低要求"],"tr":""},{"id":"mockc3-10","p":"mockc3","src":"估價綜合模擬卷三 第10題","sec":"","stem":"「最有效使用」原則在估價實務上的涵義，下列敘述何者最完整？","opts":["能使不動產所有人獲得最高利潤之使用","建蔽率與容積率用盡的使用方式","市場上最熱門的使用方式","依法令規定、實際使用可能性，於估價當時能產生最高價值之合理使用"],"ok":[3],"ex":["最有效使用是客觀判斷，不是以所有人主觀利潤最高為準","用盡建蔽率、容積率不等於最有效使用，須同時符合合法、實質可能、正當合理、財務可行四項前提","最熱門之使用不等於最有效使用，仍須通過四項前提檢驗","最有效使用（技術規則§2第17款）：客觀上具有良好意識及通常使用能力者，在①合法 ②實質可能 ③正當合理 ④財務可行前提下之使用，所得之最高、最佳使用（非主觀利潤最高、非用盡容積）。"],"tr":""},{"id":"mockc3-11","p":"mockc3","src":"估價綜合模擬卷三 第11題","sec":"","stem":"依「不動產估價技術規則」§2，有關「價格日期」與「勘察日期」之敘述，下列何者正確？","opts":["勘察日期為委託人簽約之日","價格日期與勘察日期必須為同一日","價格日期為表示勘估標的價格之基準日期；勘察日期為赴現場調查分析之日期；二者不必相同","價格日期為估價報告書之完成日"],"ok":[2],"ex":["勘察日期是赴現場調查之日，不是簽約日","兩者定義不同、不必相同","§2第7、8款：價格日期＝表示價格之基準日期；勘察日期＝實際赴勘估標的現場調查分析之日期；二者不必相同（常考陷阱）","價格日期是價格的基準日，不是報告書完成日"],"tr":""},{"id":"mockc3-12","p":"mockc3","src":"估價綜合模擬卷三 第12題","sec":"","stem":"依技術規則，以不動產證券化為估價目的、採折現現金流量分析法估價時，下列敘述何者錯誤？","opts":["各期淨收益應以勘估標的之契約租金計算為原則","契約租金未知者，應以限定租金推估淨收益","總費用應依信託計畫資料加以推算","因情況特殊不宜採契約租金估價者，得敘明理由後另行估計"],"ok":[1],"ex":["正確：證券化DCF各期淨收益以勘估標的之契約租金為原則（§33Ⅱ；歷屆104-13、105-17）","錯誤。§33Ⅲ：「契約租金未知者，應以市場經濟租金推估客觀淨收益」，不是限定租金（歷屆102-8）","正確：總費用依信託計畫資料推算（§38Ⅱ；歷屆110-11）","正確：因情況特殊不宜採契約租金者，得於報告書敘明"],"tr":""},{"id":"mockc3-13","p":"mockc3","src":"估價綜合模擬卷三 第13題","sec":"","stem":"公共設施保留地之估價，以何種估價方法為原則？","opts":["成本法","比較法","土地開發分析法","收益法"],"ok":[1],"ex":["成本法也可以用於土地（§69：土地價格＝土地總成本），但§97明定公共設施用地及公共設施保留地「以比較法估價為原則」，所以不是成本法。","比較法：§97 公共設施用地及保留地估價以比較法為原則，無買賣實例者，比較其與毗鄰土地使用分區及使用強度之差異與土地價值減損情況，並斟酌毗鄰土地平均價格為基礎推算。","土地開發分析法：用於有開發潛力的土地，公設保留地受限制，不適合。","收益法：公共設施保留地通常無收益可計，不適合。"],"tr":""},{"id":"mockc3-14","p":"mockc3","src":"估價綜合模擬卷三 第14題","sec":"","stem":"依不動產估價技術規則，有關土地開發分析法之敘述，下列何者錯誤？","opts":["土地開發分析法係估算開發或建築後總銷售金額，扣除開發期間之直接成本、間接成本、資本利息及利潤後，求得開發前或建築前之土地開發分析價格","開發年數之估計，應自價格日期起至開發完成為止無間斷所需之時間","對以進行開發為前提之宗地，應以土地開發分析法為唯一估價方法，不得再參酌其他估價方法之評估結果","預期總銷售金額之銷售單價，應考量價格日期當時銷售可實現之價值，以比較法或收益法求取之"],"ok":[2],"ex":["正確：§70 定義。扣的是「開發期間」的直接成本、間接成本、資本利息及利潤，求的是「開發前或建築前」的土地價格（99-10、99-37 同一考點）","正確：§80 開發年數＝自價格日期起至開發完成為止「無間斷」所需之時間；它是 §79 資本利息綜合利率公式裡的「開發年數」","錯誤：§87「對以進行開發為前提之宗地，得採土地開發分析法進行估價，並參酌比較法或收益法之評估結果決定其估價額」。是「得採」不是「唯一」，且要參酌比較法或收益法（不是成本法）。104-31 答 ①③ 就是這一條","正確：§75 第 2 項。銷售單價不是用成本法推，而是以比較法或收益法求取，並考量價格日期當時「銷售可實現之價值」"],"tr":""},{"id":"mockc3-15","p":"mockc3","src":"估價綜合模擬卷三 第15題","sec":"","stem":"有效總收入乘數法（GIM法）決定資本化率，其公式為何？（GIM：有效總收入乘數；OER：營運費用率）","opts":["r＝GIM×OER","r＝GIM÷(1－OER)","r＝OER÷GIM","r＝(1－OER)÷GIM"],"ok":[3],"ex":["GIM÷OER 之關係全錯，r＝GIM×OER 單位與意義均不合","分子分母顛倒；資本化率應是（1－OER）÷GIM","少了「1－」：淨收益率是（1－OER），不是 OER","GIM法推導：淨收益率＝(1－OER)；收益價格＝有效總收入×GIM；∴r＝淨收益÷收益價格＝(1－OER)÷GIM。 資本化率 r ＝ (1 － 營運費用率) ÷ 有效總收入乘數 五種資本化率方法都要能辨識與計算（近年高頻）。"],"tr":""},{"id":"mockc3-16","p":"mockc3","src":"估價綜合模擬卷三 第16題","sec":"","stem":"下列何者屬於比較法中「個別因素調整」之項目？","opts":["比較標的所在地區之交通便利性","比較標的所在商圈之商業繁榮程度","勘估標的土地之形狀與臨路條件","比較標的所在地區之公共設施完善度"],"ok":[2],"ex":["地區交通便利性屬區域整體條件，為區域因素","商業繁榮程度屬地區整體環境，為區域因素","土地形狀、臨路條件屬個體特性，為個別因素調整項目（技術規則§19、§24）","公共設施完善度屬地區條件，為區域因素"],"tr":""},{"id":"mockc3-17","p":"mockc3","src":"估價綜合模擬卷三 第17題","sec":"","stem":"比較法之所以成立，主要是基於下列何種估價原則？","opts":["均衡原則","競爭原則","貢獻原則","替代原則"],"ok":[3],"ex":["均衡原則談的是各構成要素組合均衡時效用最大，並非比較法之理由","競爭原則談的是超額利潤會引來競爭、使收益趨於正常，與比較法成立無關（註：估價原則屬學理，技術規則僅於 §2 定義最有效使用）","貢獻原則談的是各生產要素對整體價值之貢獻程度，與比較法成立的理由無關","替代原則：理性的買方不會以高於可替代物之價格購買，因此類似不動產之價格會互相牽制，才能用比較標的之價格推估勘估標的價格（比較法之理論基礎）"],"tr":""},{"id":"mockc3-18","p":"mockc3","src":"估價綜合模擬卷三 第18題","sec":"","stem":"依「不動產估價技術規則」，採比較法估算價格時，至少須蒐集幾件比較標的？","opts":["三件","五件","一件","二件"],"ok":[0],"ex":["技術規則§27規定，決定比較價格應採用三件以上比較標的之試算價格","五件雖更佳，但技術規則最低要求為三件","一件比較標的不具代表性，無法相互驗證","二件不符技術規則最低要求"],"tr":""},{"id":"mockc3-19","p":"mockc3","src":"估價綜合模擬卷三 第19題","sec":"","stem":"下列何者「不是」推算勘估標的總費用之項目？","opts":["所得稅","保險費","維修費及管理費","地價稅（或地租）及房屋稅"],"ok":[0],"ex":["§38：總費用「項目包括地價稅或地租、房屋稅、保險費、管理費及維修費等」；所得稅、土地增值稅、貸款利息等不屬於總費用（歷屆 105-34、106-8、107-2、112-9）","屬總費用項目","屬總費用項目","屬總費用項目"],"tr":""},{"id":"mockc3-20","p":"mockc3","src":"估價綜合模擬卷三 第20題","sec":"","stem":"依不動產估價技術規則，「重建成本」與「重置成本」的差異，下列敘述何者正確？","opts":["重建成本係使用相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製之成本；重置成本係以現代建材標準、設計及配置，建造相同效用建物之成本","兩者均指以估價當時技術重建相同效用之建物","重建成本一定高於重置成本","重建成本係以現代建材標準、設計及配置，建造相同效用之建物；重置成本係以相同或極類似之建材標準、設計複製"],"ok":[0],"ex":["重建成本：相同或極類似之建材標準、設計、配置及施工品質，重新複製（原則）。重置成本：以現代建材標準、設計及配置，建造相同效用之建物（建材已無生產或施工方法已改變時之例外）。","兩者並不相同：重建成本是依相同或極類似之建材標準複製，重置成本才是以現代建材標準重建相同效用建物","兩者高低不一定，重置成本採現代建材，可能較高也可能較低，不能說重建成本一定較高","兩者定義對調了：相同或極類似建材複製者是「重建成本」，以現代建材建造相同效用者是「重置成本」"],"tr":""},{"id":"mockc3-21","p":"mockc3","src":"估價綜合模擬卷三 第21題","sec":"","stem":"依不動產估價技術規則，下列何種情況的比較實例，應不予採用（無法以情況調整處理）？","opts":["買賣雙方情誼特殊（如親友間交易），成交價格偏低","賣方急需資金，售價低於市場行情","附有特殊融資條件，可計算合理之融資調整率","毗鄰地主購買相鄰土地，其獲得之特殊利益無法量化調整"],"ok":[3],"ex":["親友間交易屬 §23 特殊交易情況，若影響可量化即可作情況調整，只有無法有效掌握及量化者才不採用","急買急賣屬 §23 特殊交易情況，可估計折價幅度作情況調整","融資條件之影響若可計算合理調整率，即可作情況調整，不必排除","情況調整目的是還原成「正常交易價格」，但特殊利益無法量化（如毗鄰地主合併增值），連調整都不可能→應直接排除。 毗鄰地主購地屬§23第5款「畸零地或有合併使用之交易」，特殊利益無法有效掌握及量化，依§23應不予採用。A、B雖非正常交易但可量化→可做情況調整；C能算出合理的融資調整率→也可做情況調整。（102年、110年申論考點）"],"tr":""},{"id":"mockc3-22","p":"mockc3","src":"估價綜合模擬卷三 第22題","sec":"","stem":"依「不動產估價技術規則」，以何種價格估價時，應敘明其估價條件，並同時估計其正常價格？","opts":["限定價格","正常價格","特定價格","特殊價格"],"ok":[2],"ex":["限定價格依§2三種限定條件形成，不要求同時估計正常價格","正常價格本身即為基準，無此要求","§6 後段：以特定價格估價者，應敘明其估價條件，並同時估計其正常價格","特殊價格指不具市場性不動產之價值（§2），無此要求"],"tr":""},{"id":"mockc3-23","p":"mockc3","src":"估價綜合模擬卷三 第23題","sec":"","stem":"依「不動產估價技術規則」第9條，「確定估價基本事項」不包含下列何者？","opts":["估價方法","價格日期","勘估標的內容","價格種類及條件"],"ok":[0],"ex":["估價方法是後面「運用估價方法推算」階段（§14）才決定，不在§9四項基本事項內","屬於：§9第二款價格日期","屬於：§9第一款勘估標的內容","屬於：§9第三款價格種類及條件"],"tr":""},{"id":"mockc3-24","p":"mockc3","src":"估價綜合模擬卷三 第24題","sec":"","stem":"續訂租約：原契約租金每月30,000元，市場經濟租金每月40,000元，經分析差額中應歸屬承租人70%、出租人30%。依差額分配法，續訂租約租金每月應為多少？","opts":["31,000元","33,000元","35,000元","37,000元"],"ok":[1],"ex":["31,000元只加了差額之10%，無依據","正確：差額＝40,000−30,000＝10,000；歸屬出租人部分＝10,000×30%＝3,000；續訂租金＝原契約租金＋應歸屬出租人之適當部分＝30,000＋3,000＝33,000元（§133第4款）","35,000元是差額平分，題目未如此分配","37,000元是把70%誤加給出租人（30,000＋7,000），歸屬對象弄反"],"tr":""},{"id":"mockc3-25","p":"mockc3","src":"估價綜合模擬卷三 第25題","sec":"","stem":"下列何者「不屬於」§114 所列之權利估價範圍？","opts":["抵押權","質權","地上權","租賃權"],"ok":[1],"ex":["抵押權屬之（§121）","§114 列舉：地上權、典權、永佃權、農育權、不動產役權、耕作權、抵押權、租賃權、市地重劃、容積移轉及都市更新權利變換；不包含質權（常見陷阱）","地上權屬之（§116）","租賃權屬之"],"tr":""},{"id":"mockc4-1","p":"mockc4","src":"估價綜合模擬卷四 第1題","sec":"","stem":"依技術規則，限定價格係指具市場性之不動產在限定條件之一所形成之價值。下列何者屬於限定條件？①以不動產所有權以外其他權利與所有權合併為目的 ②以不動產合併為目的 ③以違反經濟合理性之不動產分割為前提 ④以變更為其他使用分區為前提","opts":["僅①②","①②③","②③④","①②③④"],"ok":[1],"ex":["少了③，限定條件共三種","①②③ 正確：§2 限定價格之三種限定條件為(一)所有權以外其他權利與所有權合併、(二)不動產合併、(三)違反經濟合理性之分割","④ 是「特定價格」之情形（基於特定條件，如變更使用分區），不屬限定條件","④ 不是限定條件，且此選項多選了 ④"],"tr":""},{"id":"mockc4-2","p":"mockc4","src":"估價綜合模擬卷四 第2題","sec":"","stem":"依技術規則，成本法估計規劃設計費時，得按下列何者之百分之二至百分之三推估之？","opts":["實際營造或施工費","總銷售金額","土地價格","總成本"],"ok":[0],"ex":["規劃設計費得按實際營造或施工費之2%至3%推估（§57；歷屆103-33）","總銷售金額是土地開發分析法中廣告銷售費、管理費、稅捐之計算基礎（§77），不是規劃設計費之基礎","土地價格不是規劃設計費之計算基礎","不是按總成本；廣告費、管理費、稅捐等才是按總成本乘以全聯會公告費率（§61）"],"tr":""},{"id":"mockc4-3","p":"mockc4","src":"估價綜合模擬卷四 第3題","sec":"","stem":"依「不動產估價技術規則」§2，下列何種情形所形成之價值屬於「限定價格」？","opts":["不具市場性之宗教廟宇","一般二手住宅正常市場買賣","經適當市場行銷之公開交易","以不動產合併為目的"],"ok":[3],"ex":["不具市場性不動產所估計之價值屬特殊價格","屬正常價格","屬正常價格之交易條件","限定價格之限定條件有三：①不動產所有權以外其他權利與所有權合併；②不動產合併；③違反經濟合理性之不動產分割"],"tr":""},{"id":"mockc4-4","p":"mockc4","src":"估價綜合模擬卷四 第4題","sec":"","stem":"比較標的成交價1,000萬元，交易日期之價格指數100，價格日期之價格指數110。僅作價格日期調整，調整後價格為多少？","opts":["909萬元","1,000萬元","1,010萬元","1,100萬元"],"ok":[3],"ex":["909＝1,000×100÷110，指數比例上下顛倒","1,000 是未作調整","1,010 無對應算式","調整後價格＝成交價×（價格日期指數÷交易日期指數）＝1,000×110÷100＝1,100萬元（§19 價格日期調整）"],"tr":""},{"id":"mockc4-5","p":"mockc4","src":"估價綜合模擬卷四 第5題","sec":"","stem":"承租人每月支付租金40,000元，並交付押金120,000元（無權利金）；押金運用收益率以年利率1.5%計。該租約一年之實質租金為多少？","opts":["480,000元","481,800元","498,000元","600,000元"],"ok":[1],"ex":["480,000＝40,000×12，只有支付租金，漏加押金之運用收益","實質租金＝支付租金＋押金運用收益＝40,000×12＋120,000×1.5%＝480,000＋1,800＝481,800元（§130）","498,000 是把押金利息誤算成 120,000×15%＝18,000（利率小數點位置錯）","600,000＝480,000＋120,000，是把押金「全額」加入；規則加計的是押金之「運用收益」，不是押金本身"],"tr":""},{"id":"mockc4-6","p":"mockc4","src":"估價綜合模擬卷四 第6題","sec":"","stem":"關於抵押權之估價（§121），下列敘述何者正確？","opts":["估價結果得高於所擔保之債權額","以抵押物之公告現值為基礎，不須考慮其他順位抵押權","不須考慮抵押物之現況使用情形","以實際債權額為基礎，並考慮其他順位抵押權設定狀況、流通性、風險性、增值性及執行難易程度調整"],"ok":[3],"ex":["§121以實際債權額為基礎調整，條文未規定可高於所擔保之債權額（「上限為債權額」屬教材說法）","基礎是實際債權額，且須考慮其他順位設定狀況","錯誤。§121要先「估計價格日期當時勘估標的正常價格」，估正常價格必須到現場調查勘估標的之使用現況（§13第2款），估價報告書也要載明勘估標的使用現況（§16第9款），所以不能說抵押權估價不須考慮抵押物的現況使用情形","§121：估計價格日期當時勘估標的之正常價格，以實際債權額為基礎，考慮其他順位抵押權設定狀況、流通性、風險性、增值性及執行上之難易程度調整"],"tr":""},{"id":"mockc4-7","p":"mockc4","src":"估價綜合模擬卷四 第7題","sec":"","stem":"依不動產估價技術規則，以直接資本化法評估收益價格，下列敘述何者正確？","opts":["資本化率係以市場比較法決定，不得採用其他方法","收益價格＝勘估標的未來平均一年期間之客觀淨收益÷收益資本化率","收益價格以各期淨收益折現加總求得，與折現現金流量分析法相同","收益價格＝淨收益÷（資本化率＋折舊率）"],"ok":[1],"ex":["技術規則規定有五種方法可決定資本化率（風險溢酬法、市場萃取法、WACC法、有效總收入乘數法、債務保障比率法）。","直接資本化法公式：收益價格＝勘估標的未來平均一年期間之客觀淨收益÷收益資本化率（技術規則§29、§30）。","逐期折現是DCF法，非直接資本化法。","§30直接資本化法的分母只有收益資本化率；只有淨收益未扣除折舊提存費時，§45、§46才在建物部分加計「建物價格日期當時價值未來每年折舊提存率」，所以本式不是直接資本化法的一般公式。"],"tr":""},{"id":"mockc4-8","p":"mockc4","src":"估價綜合模擬卷四 第8題","sec":"","stem":"比較標的為公有土地標售，標售價格高於一般市場行情，則運用比較法時，應進行何項調整？","opts":["價格日期調整","個別因素調整","情況調整","區域因素調整"],"ok":[2],"ex":["價格日期調整：用於時間點不同的修正，本題強調的是「非正常交易」而非時間差，非首要調整。","個別因素調整：用於個別條件差異修正。","情況調整：§23第8款「公有土地標售、讓售」屬應先作適當調整的特殊交易，要先作情況調整還原成正常價格；影響無法有效掌握及量化時，應不予採用。","區域因素調整：用於不同區域間的差異修正。"],"tr":""},{"id":"mockc4-9","p":"mockc4","src":"估價綜合模擬卷四 第9題","sec":"","stem":"土地立體空間效用百分率，稱為下列何項？","opts":["深度指數","樓層別效用比","地價分配率","部分別效用比"],"ok":[2],"ex":["深度指數：土地深度對地價之影響，與立體空間無關。","樓層別效用比：是各樓層間「效用高低的比值」（§98、§100、§101），不是「百分率」之名稱。","地價分配率：各樓層（立體空間）分得之地價百分率，§100 以「平均地價分配率÷該建物之地價分配率」調整基地單價。","部分別效用比：非技術規則用語。"],"tr":""},{"id":"mockc4-10","p":"mockc4","src":"估價綜合模擬卷四 第10題","sec":"","stem":"不動產估價技術規則第59條規定，資金中自有資金之計息利率應不高於一年期定期存利率且不低於活存利率。試問此一規定，屬於不動產估價之何種原則？","opts":["貢獻原則","適合原則","均衡原則","機會成本原則"],"ok":[3],"ex":["貢獻原則：各生產要素對整體價值之貢獻程度——本題無關。","適合原則：不動產用途應與周圍環境相稱——本題無關。","均衡原則：各生產要素組合最佳狀態時，不動產效用最大——本題無關。","機會成本原則：自有資金如不投入此項目，可存款獲取利息，此即機會成本。技術規則以定存上限、活存下限框定計息範圍，正是機會成本概念。"],"tr":""},{"id":"mockc4-11","p":"mockc4","src":"估價綜合模擬卷四 第11題","sec":"","stem":"建物之經歷年數大於其經濟耐用年數，應重新調整下列何項？","opts":["經歷年數","物理耐用年數","殘餘年數","經濟耐用年數"],"ok":[3],"ex":["經歷年數：已發生的時間，不能調整。","§65以經濟耐用年數為主，「必要時得以物理耐用年數計算」；本題情形依§65末句應調整的是經濟耐用年數，不是物理耐用年數。","殘餘年數：殘餘=耐用-經歷，調整源頭才是正確做法。","§65末句：「建物之經歷年數大於其經濟耐用年數時，應重新調整經濟耐用年數。」"],"tr":""},{"id":"mockc4-12","p":"mockc4","src":"估價綜合模擬卷四 第12題","sec":"","stem":"依「不動產估價技術規則」，估價師對同一標的進行估價，採用兩種以上方法所得結果不同時，下列處理方式何者正確？","opts":["說明各方法估算差異原因，並決定一合理估計價格","以最高估價結果為準","以最低估價結果為準","取各方法估價結果之算術平均值"],"ok":[0],"ex":["技術規則§15：各方法價格差異顯著者應重新檢討，並綜合考量各方法之適用性與資料可靠性，調和決定價格、敘明理由，而非機械性取平均","取最高值有偏高之虞，不符合客觀估價原則","取最低值有偏低之虞，可能不利於委託人（依目的而定）","算術平均機械性高，未考量各方法之代表性與適用性"],"tr":""},{"id":"mockc4-13","p":"mockc4","src":"估價綜合模擬卷四 第13題","sec":"","stem":"關於不動產「折舊」之特性，下列敘述何者有誤？","opts":["土地與建物均可提列折舊","物理性折舊可透過修繕部分回復","機能性折舊通常無法透過修繕完全回復","經濟性折舊係外部環境因素造成，通常不可回復"],"ok":[0],"ex":["✗ 錯誤。土地不提列折舊（土地具永久性，不發生物理或機能折舊）；只有建物才提列折舊","正確。物理損壞透過修繕可部分甚至完全回復（例如屋頂漏水修繕後功能恢復）","正確。機能性折舊（設計過時、空間配置不合時宜）通常難以透過修繕完全回復","正確。外在環境惡化（工廠污染、鄰近設施廢棄）造成之經濟折舊，非建物所有人可自行消除"],"tr":""},{"id":"mockc4-14","p":"mockc4","src":"估價綜合模擬卷四 第14題","sec":"","stem":"依不動產估價技術規則，比較法「比較修正」之單項調整率與總調整率的限制為何？","opts":["單項不超過20%；總調整率不超過30%","單項不超過15%；總調整率不超過30%","單項不超過15%；總調整率不超過25%","單項不超過10%；總調整率不超過20%"],"ok":[1],"ex":["單項上限是15%（大於15%排除），20%是 §26 試算價格間差距之門檻，不是單項調整率","比較法排除規則（技術規則§25、§26）三道關卡：①§25 單項調整率大於15%排除 ②§25 總調整率大於30%排除（剛好15%、30%仍可採用） ③§26 試算價格間差距達20%以上，應先重新檢討，檢討後仍達20%以上者，排除該試算價格。","總調整率之上限是30%，不是25%","10%、20% 並非條文數字"],"tr":""},{"id":"mockc4-15","p":"mockc4","src":"估價綜合模擬卷四 第15題","sec":"","stem":"下列有關「區域因素」之敘述，何者錯誤？","opts":["係指不動產本身條件所產生之價格差異因素","係影響近鄰地區不動產價格水準之因素","商圈發展、道路系統連接情形，屬區域因素","比較標的與勘估標的不在同一近鄰地區時，須進行區域因素調整"],"ok":[0],"ex":["錯誤：這是「個別因素」之定義（不動產本身條件所產生之價格差異因素），區域因素看的是「近鄰地區」整體","正確：區域因素＝影響近鄰地區不動產價格水準之因素（§2）","正確：這類影響整個近鄰地區之條件屬區域因素","正確：區域因素調整＝比較標的與勘估標的不在同一近鄰地區時，將比較標的價格轉化為勘估標的同一近鄰地區價格水準之調整（§19）"],"tr":""},{"id":"mockc4-16","p":"mockc4","src":"估價綜合模擬卷四 第16題","sec":"","stem":"依不動產估價技術規則，計量模型分析法（CAMA）的「判定係數」（R²）應達多少以上？","opts":["0.7以上","0.5以上","0.8以上","0.6以上"],"ok":[0],"ex":["CAMA法三項門檻（技術規則§20）：①樣本數≥自變數個數×5倍 ②調整後判定係數不得低於0.7 ③截距項以外各主要影響價格因素之係數估計值同時為零之顯著機率不得大於5%。 三項同時達到才可使用。記憶：「5倍、0.7、5%」。","0.5 不符，調整後判定係數不得低於0.7","0.8 雖高於門檻，但規定值是0.7（調整後判定係數不得低於0.7）","0.6 低於門檻，不符"],"tr":""},{"id":"mockc4-17","p":"mockc4","src":"估價綜合模擬卷四 第17題","sec":"","stem":"某商業不動產持有5年，第1-5年淨現金流量分別為100、110、120、130、140萬元，第5年末終值（售出）預估2,500萬元，折現率6%，則其第1年現金流量之現值最接近下列何者？","opts":["100萬","94.3萬","106萬","89.0萬"],"ok":[1],"ex":["100萬為原始現金流量，未折現","第1年現金流量現值 ＝ 100 ÷ (1+6%)¹ ＝ 100 ÷ 1.06 ≈ 94.3萬元","106萬為100×1.06（終值計算），方向錯誤","89.0萬是100÷1.06²，等於把第1年現金流量當第2年折現，期數用錯"],"tr":""},{"id":"mockc4-18","p":"mockc4","src":"估價綜合模擬卷四 第18題","sec":"","stem":"債務保障比率法（DCR法）決定資本化率，其公式為何？（DCR：債務保障比率；MC：抵押貸款常數；LTV：放款成數）","opts":["資本化率＝DCR×MC÷LTV","資本化率＝LTV÷（DCR×MC）","資本化率＝MC×LTV÷DCR","資本化率＝DCR×MC×LTV"],"ok":[3],"ex":["把放款成數放在分母是錯的，DCR法是三項連乘：DCR×貸款常數×貸款資金占不動產價格比率","三項關係全部顛倒，與公式不符","DCR 不能放在分母；DCR 愈高（銀行愈保守）資本化率愈高，應是相乘","DCR法公式（§43第四款）：r＝債務保障比率×貸款常數×貸款資金占不動產價格比率（歷屆104、111～114年選擇題）。 口訣：「三個連乘」。銀行要求的DCR愈高（愈保守），資本化率愈高，不是除。 r ＝ 債務保障比率 × 貸款常數 × 貸款成數"],"tr":""},{"id":"mockc4-19","p":"mockc4","src":"估價綜合模擬卷四 第19題","sec":"","stem":"下列關於「最有效使用原則」之敘述，何者有誤？","opts":["最有效使用必須是目前正在進行之使用方式","最有效使用必須符合法令規定","最有效使用須使不動產產生最高價值","最有效使用應為物理上可能之使用"],"ok":[0],"ex":["✗ 錯誤。最有效使用不一定是目前之使用方式，可能是「潛在最佳使用」；若目前使用並非最有效，可能存在轉換機會","正確。最有效使用需符合法令（如使用分區、建蔽率容積率等）","正確。最有效使用以產生最高不動產價值為標準","正確。物理上可能指考慮基地形狀、地質等實際限制"],"tr":""},{"id":"mockc4-20","p":"mockc4","src":"估價綜合模擬卷四 第20題","sec":"","stem":"資金來源中，借貸資金：自有資金：預售收入＝3：2：1。投入土地部分及建築部分之比例為5：4。借貸資金成本為5%，自有資金機會成本為2%，開發年數3年，則資本利息綜合利率為多少？","opts":["7.14%","7.28%","7.39%","7.42%"],"ok":[2],"ex":["7.14%：計算方式有誤。","7.28%：計算方式有誤。","7.39%。§79：綜合利率＝年利率×（土地比率＋建物比率×½）×開發年數。①年利率（§58、§59，預售收入不計息）＝3/6×5%＋2/6×2%＋1/6×0%≈3.167%；②土地比率5/9、建物比率4/9，故（5/9＋4/9×½）＝7/9；③3.167%×7/9×3年≈7.39%。","7.42%：計算略高。"],"tr":""},{"id":"mockc4-21","p":"mockc4","src":"估價綜合模擬卷四 第21題","sec":"","stem":"某房地年淨收益195萬元，土地價格3,000萬元、土地收益資本化率2.5%，建物收益資本化率6%。以建物殘餘法求建物之收益價格，應為多少？","opts":["1,250萬元","2,000萬元","3,250萬元","4,800萬元"],"ok":[1],"ex":["1,250＝75÷6%，把土地淨收益（75萬）誤當建物淨收益","土地淨收益＝3,000×2.5%＝75萬；建物淨收益＝房地淨收益－土地淨收益＝195－75＝120萬；建物收益價格＝建物淨收益÷建物收益資本化率＝120÷6%＝2,000萬元（殘餘法：房地淨收益扣除其中一部分之淨收益，餘額歸另一部分）","3,250＝195÷6%，把整筆房地淨收益都除以建物資本化率，未扣土地淨收益","4,800＝120÷2.5%，建物淨收益卻用土地資本化率還原，資本化率配錯對象"],"tr":""},{"id":"mockc4-22","p":"mockc4","src":"估價綜合模擬卷四 第22題","sec":"","stem":"依「不動產估價技術規則」，下列何者「不是」營造施工費之估算方法？","opts":["單位工程法","淨計法","工程造價比較法","殘餘法"],"ok":[3],"ex":["單位工程法屬直接法（§55）","淨計法屬直接法（§55）","工程造價比較法屬間接法（§56）","殘餘法是收益法之土地/建物殘餘求法，不是營造施工費估算方法。營造施工費以直接法（淨計法、單位工程法）或間接法（工程造價比較法、單位面積比較法）擇一求取（§54～§56）"],"tr":""},{"id":"mockc4-23","p":"mockc4","src":"估價綜合模擬卷四 第23題","sec":"","stem":"不動產估價，應切合下列何項日期當時之價值？","opts":["勘查日期","出報告日期","價格日期","委託日期"],"ok":[2],"ex":["勘查日期：係實地查看的時間，不等於估價基準。","出報告日期：報告完成時間，非估價基準日。","價格日期：§6Ⅰ「不動產估價，應切合價格日期當時之價值」。","委託日期：非估價基準日期。"],"tr":""},{"id":"mockc4-24","p":"mockc4","src":"估價綜合模擬卷四 第24題","sec":"","stem":"政府公告調漲地價稅（稅率提高），對不動產市場整體價格造成下跌壓力，此屬於哪類影響因素？","opts":["個別因素","區域因素","一般因素","特殊因素"],"ok":[2],"ex":["個別因素是不動產本身條件所產生之價格差異，稅制不屬之","地價稅制影響整個市場，不是限於某一近鄰地區，故不是區域因素","一般因素：影響全國不動產市場的大環境（政策/稅制/利率/總體經濟）。地價稅屬全國性稅制→一般因素。","技術規則只分一般、區域、個別三類因素，沒有「特殊因素」"],"tr":""},{"id":"mockc4-25","p":"mockc4","src":"估價綜合模擬卷四 第25題","sec":"","stem":"依加權平均資金成本法（WACC）決定資本化率，下列公式何者正確？（E：自有資金比率；re：自有資金報酬率；D：借入資金比率；rd：借入資金利率）","opts":["r＝E×rd＋D×re","r＝E÷re＋D÷rd","r＝E×re＋D×rd","r＝(re＋rd)÷2"],"ok":[2],"ex":["混淆自有與借入對應報酬率。","應乘法非除法。","WACC公式：r＝E×re＋D×rd，各資金來源比率乘以各自報酬率後加總（99年申論題考點）。 r ＝ 自有比率×自有資金報酬率 ＋ 借入比率×借入資金利率","簡單平均未考慮各自比率。"],"tr":""},{"id":"mockc5-1","p":"mockc5","src":"估價綜合模擬卷五 第1題","sec":"","stem":"「實質租金」的計算，下列何者正確？","opts":["實質租金＝支付租金×（1＋押金利率）","實質租金＝支付租金（年租金）","實質租金＝支付租金＋押金等之運用收益（押金×利率）","實質租金＝年租金－管理費"],"ok":[2],"ex":["押金之運用收益是「押金×利率」另外加計，不是對租金乘以（1＋利率）","漏加押金、保證金、權利金等之運用收益，這只是「支付租金」","實質租金（技術規則§130）：承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數；押金、保證金、權利金之運用收益，§130未規定利率，計算題依題目所給利率（教材常以一年期定存利率；101-二即用年定存利率2%）計算。 實質租金 ＝ 支付租金 ＋ 押金 × 利率（運用收益） 押金交給房東使用，承租人損失押金可孳生的利息→此為隱性租金成本。（114年、101年申論考點）","管理費不是實質租金之計算項目，也不是用來扣減"],"tr":""},{"id":"mockc5-2","p":"mockc5","src":"估價綜合模擬卷五 第2題","sec":"","stem":"不動產價格隨社會、經濟及環境之變遷而持續變動，故估價須以價格日期當時之價值為準，此最符合下列何種估價原則？","opts":["預期原則","貢獻原則","適合原則","變動原則"],"ok":[3],"ex":["預期原則談的是價格取決於對未來利益之預期，不是強調「價格隨時間變動」","貢獻原則談的是各組成部分對整體價值之貢獻","適合原則談的是不動產與周圍環境之相稱程度","變動原則：價格是各種價格形成因素相互作用之結果，因素變動則價格隨之變動，所以估價應切合價格日期當時之價值（技術規則 §6）"],"tr":""},{"id":"mockc5-3","p":"mockc5","src":"估價綜合模擬卷五 第3題","sec":"","stem":"下列因素：①地區淹水 ②捷運站設置 ③央行調升利率 ④房屋臨路寬度，何者屬於「區域因素」？","opts":["①③","①②","②③④","①②③④"],"ok":[1],"ex":["③利率變動屬一般因素，不是區域因素","區域因素＝影響近鄰地區價格水準之因素：①②屬之；③利率變動屬一般因素；④臨路寬度屬個別因素","③是一般因素、④是個別因素，兩者皆非區域因素","③④不屬區域因素"],"tr":""},{"id":"mockc5-4","p":"mockc5","src":"估價綜合模擬卷五 第4題","sec":"","stem":"土地開發分析法公式 V＝S÷(1＋R)÷(1＋i)－(C＋M)（§81），各符號意義下列何者錯誤？","opts":["S＝開發完銷後不動產總銷售收入","R＝適當利潤率","C＝直接成本（營造施工費等），M＝間接成本","i＝建物完工後銷售期間之空置率"],"ok":[3],"ex":["正確敘述：S＝開發或建築後之總銷售金額","正確敘述：R＝適當之利潤率","正確敘述：C＝直接成本、M＝間接成本","i＝資本利息綜合利率（§79；不是空置率）。V＝開發前土地價值；S＝總銷售金額；R＝適當利潤率；C＝直接成本；M＝間接成本（直接成本＝營造施工費；間接成本＝規劃設計費、廣告銷售費、管理費、稅捐及其他負擔）。 V ＝ S ÷ (1＋R) ÷ (1＋i) － (C＋M)"],"tr":""},{"id":"mockc5-5","p":"mockc5","src":"估價綜合模擬卷五 第5題","sec":"","stem":"附有違章建築之房地估價，其違建部分之評估，下列何者錯誤？","opts":["若委託人要求評估，合法建物及違建部分分開評估，合併標示","若委託人要求評估，合法建物及違建部分分開評估，分別標示。","若委託人要求評估，則違建部分得予以評估","若委託人無要求評估，則違建部分不予以評估"],"ok":[0],"ex":["✗ 錯誤。§103但書：委託人要求評估時，要「就合法建物及違建部分於估價報告書中分別標示各該部分之價格」，不是合併標示。","委託人要求 → 分開評估、分別標示，正確。","委託人要求 → 違建可評，正確。","委託人未要求 → 違建不評，正確。"],"tr":""},{"id":"mockc5-6","p":"mockc5","src":"估價綜合模擬卷五 第6題","sec":"","stem":"建物總成本1,000萬元，殘餘價格率10%，經濟耐用年數20年，計息利率4%。依償債基金型，每年折舊提存費約為多少萬元？","opts":["45.0","36.0","33.6","30.2"],"ok":[3],"ex":["45.0＝1,000×0.9÷20，是等速折舊型（不計利息）之提存費","36.0＝1,000×0.9×4%，只乘利率，漏除〔(1＋i)ᴺ－1〕＝1.1911（i÷〔(1＋i)ᴺ－1〕才是償債基金係數）","33.6＝1,000×0.0336，漏乘（1－s）","C×(1－s)×i÷[(1＋i)ᴺ－1]＝1,000×0.9×0.04÷(1.04²⁰－1)＝36÷1.1911≈30.2萬元（§40-1）"],"tr":""},{"id":"mockc5-7","p":"mockc5","src":"估價綜合模擬卷五 第7題","sec":"","stem":"成本法案例：土地總成本6,000萬元、建物總成本3,000萬元、建物累積折舊額600萬元。依技術規則，房地成本價格為何？","opts":["6,600萬元","8,400萬元","9,000萬元","9,600萬元"],"ok":[1],"ex":["6,600萬元＝土地總成本6,000＋累積折舊600，漏掉建物成本價格，又把累積折舊當成價格加入","正確：房地成本價格＝土地總成本＋建物成本價格；建物成本價格＝總成本−累積折舊＝3,000−600＝2,400；6,000＋2,400＝8,400萬元（歷屆112-21）","9,000萬元是土地總成本加建物「總成本」，漏扣累積折舊","9,600萬元是把累積折舊「加」回去，方向相反"],"tr":""},{"id":"mockc5-8","p":"mockc5","src":"估價綜合模擬卷五 第8題","sec":"","stem":"r₁代表土地收益資本化率，r₂代表建物收益資本化率，r代表房地綜合收益資本化率，則三項大小關係為何？","opts":["r₂>r>r₁","r₁>r₂>r","r₁>r>r₂","r₂>r₁>r"],"ok":[0],"ex":["r₂>r>r₁：建物有折舊、風險較高，資本化率最大；土地無折舊、保值性高，最小；房地綜合資本化率依土地、建物價值比率加權（§46），介於兩者之間。","r₁>r₂>r：房地綜合率不可能小於兩個組成率中的最小者，錯誤。","r₁>r>r₂：土地率不會高於建物率，錯誤。","r₂>r₁>r：綜合率是土地率與建物率的加權平均，必介於兩者之間，不可能最小，錯誤。"],"tr":""},{"id":"mockc5-9","p":"mockc5","src":"估價綜合模擬卷五 第9題","sec":"","stem":"不動產估價技術規則有關「最有效使用」之定義，下列何項錯誤？","opts":["合法使用","主觀上具有良好意識及通常之使用能力者","財務可行","正當合理使用"],"ok":[1],"ex":["合法使用：最有效使用要件之一，正確。","✗ 錯誤：最有效使用強調「客觀上」合理使用能力者，而非「主觀上」。此為考試常見陷阱字眼。","財務可行（財務可行性）：最有效使用要件之一，正確。","正當合理使用：最有效使用要件之一，正確。"],"tr":""},{"id":"mockc5-10","p":"mockc5","src":"估價綜合模擬卷五 第10題","sec":"","stem":"下列關於「機能性折舊」之敘述，何者正確？","opts":["因建物屋頂漏水、壁面龜裂等維護不良造成之減損","因建物周邊環境惡化或供需失衡造成之減損","因自然損壞、腐蝕等物理因素造成建物價值減損","因建物設計落伍、設備過時、空間配置不符需求造成之減損"],"ok":[3],"ex":["仍屬物理性損壞之範疇","描述「經濟性折舊（外在折舊）」，外部環境因素所致","描述「物理性折舊」，係因自然損壞、老化等有形損壞","機能性折舊（功能性過時）係因設計、設備或空間無法滿足現代需求所致之減損"],"tr":""},{"id":"mockc5-11","p":"mockc5","src":"估價綜合模擬卷五 第11題","sec":"","stem":"甲承租店面營業，為擴大規模而一併承租相鄰另一間店面、打通使用，其租賃價值之租金種類為何？","opts":["經濟租金","限定租金","正常租金","特定租金"],"ok":[1],"ex":["經濟租金不是規則之租金種類分類（租金種類只有正常、限定兩種，113-5）","限定租金：基於續訂租約或不動產合併為目的所形成之租賃價值（§2 第6款）；相鄰店面打通使用屬不動產合併（107-1）","正常租金是對應正常價格之租賃合理價值，不是為合併目的而形成","租金種類只有正常租金與限定租金兩種，沒有「特定租金」"],"tr":""},{"id":"mockc5-12","p":"mockc5","src":"估價綜合模擬卷五 第12題","sec":"","stem":"依不動產估價技術規則，建物折舊路徑（Pattern）共有三種，下列何者不屬於技術規則所規定的折舊路徑？","opts":["初期減速折舊路徑（遞增形）","初期加速折舊路徑（遞減形）","後期加速折舊路徑（後段陡升形）","等速折舊路徑（直線形）"],"ok":[2],"ex":["初期減速折舊是 §68 所定三種路徑之一，對應償債基金法","初期加速折舊是 §68 所定三種路徑之一，對應定率法","技術規則三種折舊路徑（§68）：①等速（直線形）→定額法 ②初期加速（遞減形）→定率法 ③初期減速（遞增形）→償債基金法。","等速折舊（直線形）是 §68 所定三種路徑之一，對應定額法"],"tr":""},{"id":"mockc5-13","p":"mockc5","src":"估價綜合模擬卷五 第13題","sec":"","stem":"某公寓大廈各樓層之樓層別效用比如下：1樓100、2樓75、3樓65、4樓60、5樓70，若已知整棟建物（5層）總價為1,500萬元，則3樓之合理價格約為何？","opts":["約256萬","約264萬","約270萬","約290萬"],"ok":[1],"ex":["256萬對應比例約17.1%，低於65/370（17.6%）","效用比合計：100+75+65+60+70＝370；3樓＝65÷370×1,500≈263.5萬，約264萬（區分所有建物依樓層別效用比分攤，§98）","270萬對應18%，略高於65/370","290萬對應比例過高"],"tr":""},{"id":"mockc5-14","p":"mockc5","src":"估價綜合模擬卷五 第14題","sec":"","stem":"估價師受託評估某縣政府管理、不對外交易之古蹟紀念館價值，其價格種類為何？","opts":["限定價格","正常價格","特殊價格","特定價格"],"ok":[2],"ex":["限定價格是具市場性之不動產在合併、分割等限定條件下形成之價值","正常價格以具市場性之不動產為前提，古蹟紀念館不在市場上交易","特殊價格：對「不具市場性」之不動產所估計之價值（§2）；總統府、孔廟、媽祖廟、離島等歷屆題屬此類","特定價格是具市場性之不動產基於特定條件（如變更使用）形成之價值"],"tr":""},{"id":"mockc5-15","p":"mockc5","src":"估價綜合模擬卷五 第15題","sec":"","stem":"依「不動產估價技術規則」，採用二種以上估價方法所得各試算價格差異顯著時，應如何處理？","opts":["直接取算術平均數","重新檢討各估價方法之推算過程及資料，調和後決定價格並敘明理由","一律取最低價格","一律取最高價格"],"ok":[1],"ex":["機械式平均，未檢討差異原因","§15：各方法價格差異顯著者，應重新檢討；並考量各方法之適用性、資料可靠度，調和決定勘估標的價格，於報告書敘明理由（§14要求原則兼採二種以上方法）","取最低價格偏低，無此規定","取最高價格偏高，無此規定"],"tr":""},{"id":"mockc5-16","p":"mockc5","src":"估價綜合模擬卷五 第16題","sec":"","stem":"折現現金流量分析法（DCF）與直接資本化法最主要的差異，在於前者：","opts":["以市場比較法決定折現率，排除其他方法","以總收益而非淨收益為計算基礎","逐期估算各期淨收益及期末處分價值，分別折現後加總求得收益價格","僅適用於商業不動產，不適用於住宅"],"ok":[2],"ex":["折現率之決定方法可採風險溢酬法、市場萃取法等多種方法（§43），並非只能用比較法，也不是兩法最主要之差異","DCF 與直接資本化法都以「淨收益」（有效總收入扣除總費用）為基礎，不是總收益","DCF核心特徵：逐期估算各期淨收益＋保有期間末轉售價值，各別乘以折現因子後加總（113年申論題）。 直接資本化法僅用「勘估標的未來平均一年期間之客觀淨收益÷收益資本化率」，假設未來收益穩定；DCF適合未來收益波動大的情形。","DCF 不限用途，各種收益性不動產（含投資評估）都可適用（§31）"],"tr":""},{"id":"mockc5-17","p":"mockc5","src":"估價綜合模擬卷五 第17題","sec":"","stem":"依技術規則，下列何者「不屬於」營造或施工費之內含項目？","opts":["直接人工費","間接材料費","營造或施工利潤","規劃設計費"],"ok":[3],"ex":["屬於內含項目：直接材料費、直接人工費","屬於內含項目：間接材料費、間接人工費","屬於內含項目：營造或施工利潤（§53營造施工費內含八項：直接材料費、直接人工費、間接材料費、間接人工費、管理費、稅捐、資本利息、營造或施工利潤）；歷屆110-8、113-9","不屬於：規劃設計費是§52第2款總成本裡的獨立項目，不在§53營造或施工費八項之內（另有廣告費、銷售費、開發或建築利潤，亦不含於營造施工費內）"],"tr":""},{"id":"mockc5-18","p":"mockc5","src":"估價綜合模擬卷五 第18題","sec":"","stem":"同一供需圈內，近鄰地區以外而使用性質與勘估標的相近之其他地區，稱為下列何者？","opts":["類似地區","一般地區","近鄰地區","基準地區"],"ok":[0],"ex":["類似地區：同一供需圈內，近鄰地區「以外」而使用性質相近之其他地區（§2第13款）","「一般地區」並非技術規則所定義之用語","近鄰地區是勘估標的或比較標的周圍，供相同或類似用途、同質性較高之地區","「基準地區」並非技術規則所定義之用語"],"tr":""},{"id":"mockc5-19","p":"mockc5","src":"估價綜合模擬卷五 第19題","sec":"","stem":"權利變換前之基地未建築使用者，以下列何種價值推估其土地權利價值？","opts":["裡地價值","空地價值","素地價值","土地貢獻價值"],"ok":[2],"ex":["裡地價值：技術規則條文中沒有「裡地」這個用語，是干擾項。","空地價值：非技術規則用語。","素地價值：§127「權利變換前之基地未建築使用者，以素地價值推估其土地權利價值」。","土地貢獻價值：非此條用語。"],"tr":""},{"id":"mockc5-20","p":"mockc5","src":"估價綜合模擬卷五 第20題","sec":"","stem":"§58 計算資本利息時，其計息基礎（合計額）不包含下列何者？","opts":["稅捐及其他負擔","規劃設計費","開發或建築利潤","營造或施工費"],"ok":[2],"ex":["屬資本利息之計息基礎","屬資本利息之計息基礎","§58：資本利息＝（營造施工費＋規劃設計費＋廣告費＋銷售費＋管理費＋稅捐及其他負擔）之合計額×利率，土地或包含土地者另加計土地價格；不含利息與利潤。口訣：利息的基礎不含利潤，利潤的基礎才含利息","屬資本利息之計息基礎"],"tr":""},{"id":"mockc5-21","p":"mockc5","src":"估價綜合模擬卷五 第21題","sec":"","stem":"下列關於收益資本化率與不動產特性之敘述，何者正確？","opts":["風險性較高之不動產，其收益資本化率較低","增值性較高之不動產，其收益資本化率較高","管理難度較高之不動產，其收益資本化率較低","流通性較高之不動產，其收益資本化率較低"],"ok":[3],"ex":["風險性高→資本化率較「高」","增值性高→資本化率較「低」（常考陷阱，與風險性方向相反）","管理難度高→資本化率較「高」","流通性高→風險較低→資本化率較低（107-20 同一組特性）"],"tr":""},{"id":"mockc5-22","p":"mockc5","src":"估價綜合模擬卷五 第22題","sec":"","stem":"依「不動產估價技術規則」，比較法中，單項調整率與總調整率超過多少者，應排除該比較標的？","opts":["單項調整率大於10%，或總調整率大於20%","單項調整率大於20%，或總調整率大於40%","單項調整率大於15%，或總調整率大於30%","單項調整率大於30%，或總調整率大於50%"],"ok":[2],"ex":["門檻過低，非技術規則之數字","20%/40% 非技術規則數字","§25：單項調整率大於15%，或總調整率大於30%者，應排除該比較標的（剛好等於15%、30%仍可採用）","30%/50% 非技術規則數字"],"tr":""},{"id":"mockc5-23","p":"mockc5","src":"估價綜合模擬卷五 第23題","sec":"","stem":"下列為估價作業程序中擷取之六個步驟，其正確先後順序為何？①蒐集資料 ②確定估價基本事項 ③確認勘估標的狀態 ④擬定估價計畫 ⑤運用估價方法推算勘估標的價格 ⑥製作估價報告書","opts":["②④①③⑤⑥","②④③①⑤⑥","④②①③⑤⑥","②①④③⑤⑥"],"ok":[0],"ex":["正確：§8 八項程序為確定基本事項→擬定估價計畫→蒐集資料→確認勘估標的狀態→整理比較分析→運用方法推算→決定價格→製作報告書（本題只擷取其中六項）","把「確認勘估標的狀態」排在「蒐集資料」之前，是常見陷阱（正確是先蒐集資料，再確認狀態）","估價計畫須在確定基本事項之後才擬定","估價計畫應在蒐集資料之前擬定"],"tr":""},{"id":"mockc5-24","p":"mockc5","src":"估價綜合模擬卷五 第24題","sec":"","stem":"比較法的調整順序依技術規則之規定，正確順序為何？","opts":["情況調整→價格日期調整→區域因素調整→個別因素調整","區域因素調整→個別因素調整→情況調整→價格日期調整","價格日期調整→情況調整→區域因素調整→個別因素調整","個別因素調整→區域因素調整→價格日期調整→情況調整"],"ok":[0],"ex":["四步驟（技術規則§21 比較法程序）：①情況調整（排除非正常成交）→②價格日期調整（時間）→③區域因素調整（地段）→④個別因素調整（個別條件）。 口訣：「情日區個」（情況→日期→區域→個別），由外到內、由大到小。","順序錯：§21 程序是先情況調整、價格日期調整，再區域因素、個別因素調整，不是從區域因素開始","情況調整應先於價格日期調整（先把成交價還原為正常情況價格，再調整時間）","次序完全顛倒，與 §21 不符"],"tr":""},{"id":"mockc5-25","p":"mockc5","src":"估價綜合模擬卷五 第25題","sec":"","stem":"某商業不動產之年有效總收入為800萬，各項費用如下：管理費40萬、財產稅（地價稅、房屋稅）20萬、保險費10萬、建物折舊提存費30萬、修繕費20萬。依規則「總費用應加計建物折舊提存費」之方式，年淨收益為多少萬元？","opts":["680萬","700萬","720萬","760萬"],"ok":[0],"ex":["年淨收益＝有效總收入－總費用＝800－（40＋20＋10＋30＋20）＝680萬元（§38～§42；§40 總費用須加計建物折舊提存費）","700萬代表費用合計100萬，缺少某一費用項目","720萬代表費用合計80萬，計算有誤","760萬代表費用合計40萬，僅計管理費，其他未扣除"],"tr":""},{"id":"mockx1-1","p":"mockx1","src":"估價自編補強卷 第1題","sec":"","stem":"採用定額法（直線法）估算折舊時，下列何者為其特點？","opts":["每年折舊額隨時間遞減，前期折舊較多","折舊率等於1減去殘值率的（1/N）次方","每年折舊額固定相同，計算簡便","反映建物實際老化速度，前期損耗較快"],"ok":[2],"ex":["此為定率遞減法之特點（前期多、後期少），非定額法","此為定率遞減法之年折舊率公式（r = 1－殘值率¹⁄ᴺ）","定額法（等速折舊）每年提列固定金額折舊，計算最為簡便（技術規則§68 等速折舊路徑）","反映前期損耗較快是定率法邏輯；定額法不考慮時間加速因素"],"tr":""},{"id":"mockx1-2","p":"mockx1","src":"估價自編補強卷 第2題","sec":"","stem":"依「不動產估價技術規則」，收益法中「有效總收入」之計算公式，下列何者正確？","opts":["有效總收入 ＝ 總收入 ＋ 閒置及其他原因所致之收入損失","有效總收入 ＝ 淨收益 ＋ 各項費用","有效總收入 ＝ 總收入 － 閒置及其他原因所致之收入損失","有效總收入 ＝ 總收入 ／ 綜合資本化率"],"ok":[2],"ex":["損失應為減項，不是加項","此為淨收益反推有效總收入之算式；規則定義是「總收入減損失」，非此式","有效總收入＝總收入－閒置及其他收入損失（§36）；總收入指按法定用途出租或營運、在正常情況下所獲得之數額","此為資本化之逆算，與有效總收入之計算無關"],"tr":""},{"id":"mockx1-3","p":"mockx1","src":"估價自編補強卷 第3題","sec":"","stem":"折現現金流量分析法（DCF法）適用時機，下列何者最為正確？","opts":["主要適用於土地素地之估價","適用於收益型態不規則或持有期間有明確終值之不動產","僅適用於住宅類不動產","適用於市場交易活絡且可找到充足比較案例之不動產"],"ok":[1],"ex":["素地估價較適用比較法或土地開發分析法","DCF法（§28、§31）將各期淨收益及期末價值折現加總，適用於收益流不規則（如辦公商場之收益變動大）或有明確持有期間及終值估算之收益型不動產","DCF法不限住宅，尤適用商辦、購物中心","此為比較法之適用時機"],"tr":""},{"id":"mockx1-4","p":"mockx1","src":"估價自編補強卷 第4題","sec":"","stem":"依「不動產估價技術規則」，土地開發分析法中，開發完成後之預期收益，係指下列何者？","opts":["開發完成後可能取得之不動產正常銷售總價格","開發後之土地公告現值","開發完成後土地之申報地價","開發完成後建物之重建成本"],"ok":[0],"ex":["土地開發分析法以開發完成後之總銷售金額為基礎，扣除成本、利息及利潤，逆推開發前土地價格（§70、§81）","公告現值為政府公告地價，非市場估算之預期收益","申報地價為地價稅計算基準，非估價之預期收益","重建成本為成本法概念"],"tr":""},{"id":"mockx1-5","p":"mockx1","src":"估價自編補強卷 第5題","sec":"","stem":"某收益性不動產年有效總收入500萬，年費用180萬，資本化率5%，則以直接資本化法求算之不動產價值為何？","opts":["6,400萬","6,200萬","6,000萬","5,800萬"],"ok":[0],"ex":["年淨收益＝500─180＝320萬；不動產價值＝320÷5%＝6,400萬","6,200萬×5%＝310萬≠320萬（淨收益應為500－180＝320萬）；不符","6,000萬對應淨收益300萬，計算有誤","5,800萬對應淨收益290萬，計算有誤"],"tr":""},{"id":"mockx1-6","p":"mockx1","src":"估價自編補強卷 第6題","sec":"","stem":"依「不動產估價技術規則」，收益法中「綜合資本化率」之求取，下列何者為正確方式？","opts":["綜合資本化率 ＝ 土地資本化率 × 土地價值比 ＋ 建物資本化率 × 建物價值比","綜合資本化率 ＝（土地資本化率 ＋ 建物資本化率）÷ 2","綜合資本化率 ＝ 年淨收益 ÷ 不動產市場價格","A 與 C 均正確"],"ok":[3],"ex":["正確。§46Ⅱ第1款：淨收益已扣除折舊提存費者，房地綜合收益資本化率＝土地收益資本化率×土地價值比率＋建物收益資本化率×建物價值比率；未扣除者，建物部分要加計折舊提存率（同項第2款）","簡單平均僅在土建比例各50%時才與A相同，一般情況下不適用","正確。§46Ⅱ明定房地綜合收益資本化率「除依第四十三條決定外」也可用加權式，所以可用市場萃取法（§43第2款）：以案例淨收益除以價格求資本化率","A（§46 價值比率加權）與C（§43 市場萃取法概念）皆正確"],"tr":""},{"id":"mockx1-7","p":"mockx1","src":"估價自編補強卷 第7題","sec":"","stem":"下列關於「收益資本化法」（直接資本化法）之敘述，何者有誤？","opts":["以穩定年淨收益除以資本化率求取不動產價格","資本化率之高低直接影響估價結果","適用於收益流量穩定、具長期持有性質之不動產","DCF法為直接資本化法之簡化特例"],"ok":[3],"ex":["正確。直接資本化法公式：P = 淨收益 ÷ 資本化率","正確。資本化率越低，估算價格越高；資本化率敏感度高","正確。收益穩定之辦公室、商場最適用直接資本化法","✗ 錯誤。DCF法（折現現金流量法）與直接資本化法為並列方法，DCF法較直接資本化法更複雜，可處理不規則現金流，非其簡化特例"],"tr":""},{"id":"mockx1-8","p":"mockx1","src":"估價自編補強卷 第8題","sec":"","stem":"下列關於「折現現金流量分析法」（DCF法）之計算要素，不包含下列何者？","opts":["各期淨現金流量","折現率","年折舊率","期末價值（終值）"],"ok":[2],"ex":["DCF法之核心：各持有期間之淨現金流量逐期折現","折現率為DCF法必要要素，用以將未來現金流折算現值","年折舊率為成本法（定率法或定額法）之計算要素，非DCF法之計算要素","期末價值係分析期間屆滿時之價值，折現後與各期淨收益現值加總（§31～§32）"],"tr":""},{"id":"mockx1-9","p":"mockx1","src":"估價自編補強卷 第9題","sec":"","stem":"依「不動產估價技術規則」，「有效總收入」之計算方式，下列何者正確？","opts":["有效總收入 ＝ 總收入 － 閒置及其他收入損失","有效總收入 ＝ 總收入 ＋ 空租補貼","有效總收入 ＝ 淨收益 ＋ 營運費用","有效總收入 ＝ 年租金 × 出租面積"],"ok":[0],"ex":["有效總收入＝總收入－閒置及其他收入損失（§36）","損失為減項；「空租補貼」也不是規則用語","此為逆推式，不是有效總收入之定義","年租金×面積只是滿租之總收入，尚未扣除損失"],"tr":""},{"id":"mockx1-10","p":"mockx1","src":"估價自編補強卷 第10題","sec":"","stem":"某收益性不動產，土地現值5,000萬元，土地資本化率4%；建物現值2,000萬元，建物資本化率8%。則該不動產之年淨收益為何？","opts":["360萬","380萬","400萬","420萬"],"ok":[0],"ex":["土地年淨收益＝5,000×4%＝200萬；建物年淨收益＝2,000×8%＝160萬；合計＝360萬","380萬：無法由題幹常見誤算得到；正確值 200＋160＝360萬","400萬：土地套用建物資本化率 5,000×8%＝400萬，率用錯（土地應×4%），且漏了建物淨收益","420萬：用簡單平均資本化率（4%＋8%）÷2＝6% 乘總值 7,000萬＝420萬；土地、建物要各乘自己的資本化率"],"tr":""},{"id":"mockx1-11","p":"mockx1","src":"估價自編補強卷 第11題","sec":"","stem":"某建物重建成本1,200萬，耐用年數40年，殘值率0%，已使用10年。採定額法計算，建物現值為何？","opts":["840萬","900萬","800萬","960萬"],"ok":[1],"ex":["840萬對應折舊360萬（12年×30萬），計算年數有誤","定額法年折舊額＝1,200×(1─0%)÷40＝30萬；已提折舊＝30×10＝300萬；建物現值＝1,200─300＝900萬","800萬對應折舊400萬（13.3年×30萬），計算有誤","960萬對應折舊240萬（8年×30萬），計算年數有誤"],"tr":""},{"id":"mockx1-12","p":"mockx1","src":"估價自編補強卷 第12題","sec":"","stem":"下列哪一情況適合採用「假設開發法」（土地開發分析法）估算土地價格？","opts":["已完成開發、穩定收租中之商辦大樓","已全數出售完畢之舊式公寓","空白素地，已取得建照即將開發之土地","正在使用中之工業廠房"],"ok":[2],"ex":["已完成開發且穩定收租，適合收益法","已售完之舊公寓，適合比較法評估個別房屋","空白素地（或即將開發之土地）為土地開發分析法最典型適用情境：以開發後完成銷售總額，扣除開發成本與合理利潤，反推素地價格（技術規則§70）","使用中廠房可採收益法或比較法"],"tr":""},{"id":"mockx1-13","p":"mockx1","src":"估價自編補強卷 第13題","sec":"","stem":"在收益法中，若比較不動產之「總費用率」偏高，通常可能反映下列何種情況？","opts":["不動產維護良好，管理效率高","建物較老舊、設備維護費用高，或管理效率低","出租率高，空租損失低","資本化率偏低，不動產市場需求旺盛"],"ok":[1],"ex":["管理效率高通常使費用率降低，非費用率偏高的原因","費用率（費用/有效總收入）偏高，可能因建物老舊導致修繕費用高、設備耗損快或管理效率低下（如空置率高造成管理成本分攤增加）","出租率高（空租損失低）會提高有效總收入，費用率反而可能降低","資本化率與費用率為不同概念，資本化率偏低反映市場需求，不直接影響費用率"],"tr":""},{"id":"mockx1-14","p":"mockx1","src":"估價自編補強卷 第14題","sec":"","stem":"「不動產估價技術規則」中，規定收益法得採「直接資本化法」或「折現現金流量法」之條文為第幾條？","opts":["第18條","第28條","第48條","第70條"],"ok":[1],"ex":["§18為比較法","§28：「收益法得採直接資本化法、折現現金流量分析法等方法」（§29～§30 直接資本化法；§31～§32 折現現金流量分析法）","§48為成本法","§70為土地開發分析法"],"tr":""},{"id":"mockx1-15","p":"mockx1","src":"估價自編補強卷 第15題","sec":"","stem":"【土地開發分析法】依§71 估價程序，在「估算總銷售金額」之前，應先完成下列何項？","opts":["估算開發後可銷售之土地或建物面積","選擇適當利潤率及資本利息綜合利率","計算開發分析價格","估算各項成本費用"],"ok":[0],"ex":["§71 程序：確定開發內容及預期時間→調查成本費用及市場行情→現況勘察並調查環境發展程度→估算可銷售面積→估算總銷售金額→估算各項成本費用→選擇利潤率及資本利息綜合利率→計算開發分析價格","屬總銷售金額之後的步驟（倒數第二步）","是最後一步，在總銷售金額之後","估算各項成本費用在總銷售金額之後"],"tr":""},{"id":"mockx1-16","p":"mockx1","src":"估價自編補強卷 第16題","sec":"","stem":"【收益法・殘餘法】某房地年淨收益200萬元，建物成本價格1,500萬元，建物收益資本化率6%（淨收益已扣除折舊提存費），土地收益資本化率4%。依規則，土地收益價格為多少？","opts":["5,000萬元","3,500萬元","2,750萬元","1,833萬元"],"ok":[2],"ex":["200÷4%＝5,000，是把房地淨收益全部歸給土地，沒有扣掉建物淨收益","200÷4%－1,500＝3,500，是用「價格相減」；應先扣建物「淨收益」再資本化","建物淨收益＝建物成本價格×建物收益資本化率＝1,500×6%＝90萬；土地淨收益＝200－90＝110萬；土地收益價格＝110÷4%＝2,750萬元（§44～§45）","（200－90）÷6%＝1,833，是用建物資本化率去除土地淨收益，率用錯"],"tr":""},{"id":"mockx1-17","p":"mockx1","src":"估價自編補強卷 第17題","sec":"","stem":"【收益法】下列何者「不是」推算勘估標的總費用之項目？","opts":["地價稅（或地租）及房屋稅","保險費","所得稅","維修費及管理費"],"ok":[2],"ex":["屬總費用項目","屬總費用項目","§38：總費用「項目包括地價稅或地租、房屋稅、保險費、管理費及維修費等」；所得稅、土地增值稅、貸款利息等不屬於總費用（歷屆 105-34、106-8、107-2、112-9）","屬總費用項目"],"tr":""},{"id":"mockx1-18","p":"mockx1","src":"估價自編補強卷 第18題","sec":"","stem":"【收益法・綜合資本化率】土地價值占40%、土地收益資本化率3%；建物價值占60%、建物收益資本化率6%。房地綜合收益資本化率為多少？","opts":["4.2%","4.5%","4.8%","5.0%"],"ok":[2],"ex":["4.2%＝3%×60%＋6%×40%，土地、建物之價值比率權重互換","4.5% 是簡單平均（3%＋6%）÷2，未依價值比率加權","綜合資本化率＝土地率×土地價值比率＋建物率×建物價值比率＝3%×40%＋6%×60%＝1.2%＋3.6%＝4.8%（§46）","5.0% 無對應算式"],"tr":""},{"id":"mockx1-19","p":"mockx1","src":"估價自編補強卷 第19題","sec":"","stem":"【影響因素】下列何者屬於「個別因素」？","opts":["某戶房屋面對公園第一排","該重劃區整體房價水準很高","某生活圈生活機能良好","政府公告調整房地合一稅制"],"ok":[0],"ex":["個別因素＝不動產本身條件所產生之價格差異因素（112-1：面對公園第一排屬個別因素）","整體房價水準屬區域因素","生活圈機能屬區域因素","稅制調整屬一般因素"],"tr":""},{"id":"mockx1-20","p":"mockx1","src":"估價自編補強卷 第20題","sec":"","stem":"【估價原則】公寓加裝電梯後價格提升，最符合下列何種估價原則？","opts":["外部性原則","替代原則","適合原則","貢獻原則"],"ok":[3],"ex":["外部性原則是外部環境之正負影響（如嫌惡設施、捷運設站）","替代原則是審慎者不會支付高於同滿意度替代財貨之代價（三法之評價基礎）","適合原則是不動產與環境配合協調（如學校旁開書局）","貢獻原則：各生產要素（如電梯設備）對整體價值之貢獻程度（110-4、112-5）"],"tr":""},{"id":"mockx1-21","p":"mockx1","src":"估價自編補強卷 第21題","sec":"","stem":"【特殊宗地】依§92，林地之估價方法，下列何者正確？","opts":["一律以比較法為原則","一律以收益法為原則","視林木成長情形，分別採比較法、收益法或成本法","一律以成本法為原則"],"ok":[2],"ex":["林地不是比較法為原則（常考陷阱）","林地不是一律收益法","§92：林地依林木成長情形分別採比較法、收益法或成本法；成本法總費用加計造林費、林地改良費、道路開挖費。最高頻陷阱：不是「比較法為原則」（比較法為原則的是農場牧場、鹽田、池沼、墓地、公共設施用地）","林地不是一律成本法"],"tr":""},{"id":"mockx1-22","p":"mockx1","src":"估價自編補強卷 第22題","sec":"","stem":"【特殊宗地】下列何種宗地，規則僅列舉其估價考量因素，並未指定估價方法？","opts":["溫泉地","林地","鹽田","池沼"],"ok":[0],"ex":["§90 溫泉地（水權內容、開發成本、水量水質水溫、交通、設施、遊客人數）與 §91 高爾夫球場（會員制度、球場設施、收益及營運費用）僅列考量因素，條文未指定估價方法","林地（§92）依林木成長情形分別採比較、收益或成本法","鹽田（§94）以比較法為原則","池沼（§95）以比較法為原則"],"tr":""},{"id":"mockx1-23","p":"mockx1","src":"估價自編補強卷 第23題","sec":"","stem":"【權利估價】下列何者「不屬於」§114 所列之權利估價範圍？","opts":["地上權","抵押權","租賃權","質權"],"ok":[3],"ex":["地上權屬之（§116）","抵押權屬之（§121）","租賃權屬之","§114 列舉：地上權、典權、永佃權、農育權、不動產役權、耕作權、抵押權、租賃權、市地重劃、容積移轉及都市更新權利變換；不包含質權（常見陷阱）"],"tr":""},{"id":"mockx1-24","p":"mockx1","src":"估價自編補強卷 第24題","sec":"","stem":"【權利估價】關於抵押權之估價（§121），下列敘述何者正確？","opts":["以實際債權額為基礎，並考慮其他順位抵押權設定狀況、流通性、風險性、增值性及執行難易程度調整","以抵押物之公告現值為基礎，不須考慮其他順位抵押權","估價結果得高於所擔保之債權額","不須考慮抵押物之現況使用情形"],"ok":[0],"ex":["§121：估計價格日期當時勘估標的之正常價格，以實際債權額為基礎，考慮其他順位抵押權設定狀況、流通性、風險性、增值性及執行上之難易程度調整","基礎是實際債權額，且須考慮其他順位設定狀況","§121以實際債權額為基礎調整，條文未規定可高於所擔保之債權額（「上限為債權額」屬教材說法）","錯誤。§121要先「估計價格日期當時勘估標的正常價格」，估正常價格必須到現場調查勘估標的之使用現況（§13第2款），估價報告書也要載明勘估標的使用現況（§16第9款），所以不能說抵押權估價不須考慮抵押物的現況使用情形"],"tr":""},{"id":"hs1-1","p":"hs1","src":"估價來勝模擬試題一 第1題","sec":"估價原則","stem":"不動產估價技術規則第59條規定，資金中自有資金之計息利率應不高於一年期定期存利率且不低於活存利率。試問此一規定，屬於不動產估價之何種原則？","opts":["均衡原則","適合原則","貢獻原則","機會成本原則"],"ok":[3],"ex":["均衡原則：各生產要素組合最佳狀態時，不動產效用最大——本題無關。","適合原則：不動產用途應與周圍環境相稱——本題無關。","貢獻原則：各生產要素對整體價值之貢獻程度——本題無關。","✓ 機會成本原則：自有資金如不投入此項目，可存款獲取利息，此即機會成本。技術規則以定存上限、活存下限框定計息範圍，正是機會成本概念。"],"tr":"考試陷阱：「計息利率」＝機會成本；不要誤選「均衡原則」（那是組合最佳化概念）。"},{"id":"hs1-2","p":"hs1","src":"估價來勝模擬試題一 第2題","sec":"估價通則","stem":"附有違章建築之房地估價，其違建部分之評估，下列何者錯誤？","opts":["若委託人無要求評估，則違建部分不予以評估","若委託人要求評估，則違建部分得予以評估","若委託人要求評估，合法建物及違建部分分開評估，合併標示","若委託人要求評估，合法建物及違建部分分開評估，分別標示。"],"ok":[2],"ex":["委託人未要求 → 違建不評，正確。","委託人要求 → 違建可評，正確。","✗ 錯誤。§103但書：委託人要求評估時，要「就合法建物及違建部分於估價報告書中分別標示各該部分之價格」，不是合併標示。","委託人要求 → 分開評估、分別標示，正確。"],"tr":"「合併標示」vs「分別標示」——違建一定要「分別」標示，才能讓閱覽者清楚區分合法與違建價值。"},{"id":"hs1-3","p":"hs1","src":"估價來勝模擬試題一 第3題","sec":"租金估計","stem":"不動產估價之租金種類有二種，其中一種為正常租金，另一種為何？","opts":["限定租金","特定租金","特殊租金","有效租金"],"ok":[0],"ex":["✓ 限定租金：基於續訂租約或不動產合併為目的所形成之租賃價值（技術規則§2）。租金種類只有正常租金、限定租金兩種（§2 第5、6款）。","特定租金：非技術規則用語。","特殊租金：非正確術語。","有效租金：收益法用語（EGI），非租金種類分類。"],"tr":"租金種類只有兩種：正常租金、限定租金。不要把「有效總收入（EGI）」混入。"},{"id":"hs1-4","p":"hs1","src":"估價來勝模擬試題一 第4題","sec":"土地開發分析法","stem":"土地開發分析法之精神，下列何者正確？","opts":["造價推求房價","房價推求造價","地價推求房價","房價推求地價"],"ok":[3],"ex":["造價→房價：成本法的方向，非土開法。","房價→造價：無此說法。","地價→房價：與土開法方向相反。","✓ 房價推求地價：已知開發完成後房價，扣除各項成本後，倒推土地價格。此為土地開發分析法核心精神。"],"tr":"口訣：土開法 = 由果推因 = 房價推求地價。"},{"id":"hs1-5","p":"hs1","src":"估價來勝模擬試題一 第5題","sec":"地價種類","stem":"有關土地分割及土地合併，下列何者正確？","opts":["土地分割之價格種類為限定價格","土地分割之租金種類為限定租金","土地合併之價格種類為特定價格","土地合併之租金種類為限定租金"],"ok":[3],"ex":["僅「違反經濟合理性之不動產分割」才屬限定價格（§2），單說「土地分割」過於籠統，不是最正確選項。","限定租金只有「續訂租約」與「不動產合併」兩種原因（§2），分割不在其中，錯誤。","錯誤：以不動產合併為目的所形成之價值，價格種類是「限定價格」（§2 限定條件之二），不是特定價格。","✓ 正確：限定租金指基於續訂租約或不動產合併為目的所形成之租賃價值（§2）。"],"tr":"合併→價格是「限定價格」、租金是「限定租金」；違反經濟合理性之分割→限定價格。特定價格是「基於特定條件」，與合併無關。"},{"id":"hs1-6","p":"hs1","src":"估價來勝模擬試題一 第6題","sec":"價格種類定義","stem":"不動產估價技術規則有關「正常價格」之定義，下列何項錯誤？","opts":["具有市場性之不動產","不受任何脅迫","經適當市場行銷","正常特定條件"],"ok":[3],"ex":["正常價格定義包含「具市場性」，正確，本選項無誤。","「不受任何脅迫」為正常價格要件，正確。","「經適當市場行銷」為正常價格要件，正確。","✗ 錯誤。正常價格是「經適當市場行銷及正常交易條件形成之合理價值」（§2第1款）；「特定條件」是特定價格的要素（§2第3款）。"],"tr":"正常價格的條文要素：具市場性、有意願之買賣雙方、依專業知識、謹慎行動、不受任何脅迫、經適當市場行銷及正常交易條件（§2第1款）。「特定條件」一出現就是特定價格，選「錯誤項」時直接選它。"},{"id":"hs1-7","p":"hs1","src":"估價來勝模擬試題一 第7題","sec":"最有效使用","stem":"不動產估價技術規則有關「最有效使用」之定義，下列何項錯誤？","opts":["主觀上具有良好意識及通常之使用能力者","合法使用","正當合理使用","財務可行"],"ok":[0],"ex":["✗ 錯誤：最有效使用強調「客觀上」合理使用能力者，而非「主觀上」。此為考試常見陷阱字眼。","合法使用：最有效使用要件之一，正確。","正當合理使用：最有效使用要件之一，正確。","財務可行（財務可行性）：最有效使用要件之一，正確。"],"tr":"最有效使用須在「合法、實質可能、正當合理、財務可行」四項前提下，由客觀上具良好意識及通常使用能力者所作之最高利益使用。「主觀」→「客觀」，這個字眼每次必考。"},{"id":"hs1-8","p":"hs1","src":"估價來勝模擬試題一 第8題","sec":"成本法折舊計算","stem":"建物總成本1,000萬元，經濟耐用年數30年，殘餘價格率5%，經歷年數15年，則以定額法計算累積折舊額為多少？","opts":["425萬元","450萬元","475萬元","495萬元"],"ok":[2],"ex":["425萬：計算錯誤。","450萬：誤把殘餘價格率當成10%（1,000×90%÷30×15＝450）；本題s＝5%。若忽略殘值則為1,000÷30×15＝500萬。","✓ 475萬元。定額法：每年折舊=(1000-1000×5%)÷30=950÷30≈31.67萬。累積15年=31.67×15=475萬。","495萬：計算錯誤。"],"tr":"定額法公式：年折舊額 ＝ (建物成本 ─ 殘值) ÷ 耐用年數。殘值 = 總成本 × 殘餘價格率。別忘了扣殘值！"},{"id":"hs1-9","p":"hs1","src":"估價來勝模擬試題一 第9題","sec":"比較法","stem":"比較標的為公有土地標售，標售價格高於一般市場行情，則運用比較法時，應進行何項調整？","opts":["情況調整","價格日期調整","區域因素調整","個別因素調整"],"ok":[0],"ex":["✓ 情況調整：§23第8款「公有土地標售、讓售」屬應先作適當調整的特殊交易，要先作情況調整還原成正常價格；影響無法有效掌握及量化時，應不予採用。","價格日期調整：用於時間點不同的修正，本題強調的是「非正常交易」而非時間差，非首要調整。","區域因素調整：用於不同區域間的差異修正。","個別因素調整：用於個別條件差異修正。"],"tr":"口訣：比較法調整順序 = ①情況調整（先正常化）→ ②價格日期 → ③區域因素 → ④個別因素。公有地標售=非正常=先情況調整。"},{"id":"hs1-10","p":"hs1","src":"估價來勝模擬試題一 第10題","sec":"估價通則","stem":"不動產估價，應切合下列何項日期當時之價值？","opts":["委託日期","勘查日期","價格日期","出報告日期"],"ok":[2],"ex":["委託日期：非估價基準日期。","勘查日期：係實地查看的時間，不等於估價基準。","✓ 價格日期：§6Ⅰ「不動產估價，應切合價格日期當時之價值」。","出報告日期：報告完成時間，非估價基準日。"],"tr":"估價相關四個日期：委託日 / 勘察日期 / 價格日期 / 出報日。「估價金額」只對應「價格日期」，其餘只是程序日期。"},{"id":"hs1-11","p":"hs1","src":"估價來勝模擬試題一 第11題","sec":"收益法名詞","stem":"收益法之下列名詞之數值大小關係？","opts":["有效總收入>總收入>淨收益","總收入>淨收益>有效總收入","總收入>有效總收入>淨收益","淨收益>總收入>有效總收入"],"ok":[2],"ex":["有效總收入不可能大於總收入，錯誤。","淨收益不可能大於有效總收入，錯誤。","✓ 總收入(PGI) > 有效總收入(EGI) > 淨收益(NOI)。關係：EGI = PGI ─ 空租損失；NOI = EGI ─ 總費用（§42；營運性不動產總費用另加計營運費用，§38）。","淨收益最小，不可能排第一，錯誤。"],"tr":"收益法三層樓：PGI（總收入）→扣空租損失→EGI（有效總收入）→扣總費用→NOI（淨收益）。由大到小。"},{"id":"hs1-12","p":"hs1","src":"估價來勝模擬試題一 第12題","sec":"收益法DCF計算","stem":"有一收益不動產，第1年至第3年淨收益分別為100萬、200萬及300萬元，第3年年末之期末值為800萬元，若折現率為5%，則此不動產之收益價格為多少？","opts":["1,214萬元","1,218萬元","1,222萬元","1,227萬元"],"ok":[3],"ex":["1,214萬：無法由題幹常見誤算得到；正確值 1,226.9萬。","1,218萬：接近把「÷1.05」誤做成「×0.95」的結果（100×0.95＋200×0.95²＋1,100×0.95³≈1,218.6萬）；折現要除以（1＋5%）ᵏ，不是乘（1－5%）ᵏ。","1,222萬：無法由題幹常見誤算得到；正確值 1,226.9萬。","✓ 1,227萬元。分項：100÷1.05 + 200÷1.05² + 300÷1.05³ + 800÷1.05³ = 95.24 + 181.41 + 259.15 + 691.07 ≈ 1,226.9萬。一行算法：第3年淨收益與期末值同在第3年年末，先合併 300＋800＝1,100，再由後往前「除、加、除、加、除」：((1,100÷1.05＋200)÷1.05＋100)÷1.05 ≈ 1,226.9萬。一般計算機（由左往右算）直接按 1100 ÷ 1.05 ＋ 200 ÷ 1.05 ＋ 100 ÷ 1.05 ＝，一次到底、不用記中間值。（§31 折現現金流量法）"],"tr":"DCF計算步驟：各期NOI分別折現 + 期末值（復歸值）也要折現。期末值與第n期NOI同期折現，不是另外加一期。按計算機：同期先合併（300＋800），再從最後一年往前「÷1.05、＋前一年、÷1.05…」；科學型計算機會先乘除後加減，要每步按「＝」：1100÷1.05＝、＋200＝、÷1.05＝、＋100＝、÷1.05＝。"},{"id":"hs1-13","p":"hs1","src":"估價來勝模擬試題一 第13題","sec":"直接資本化法","stem":"直接資本化法之公式：P＝a/r，則a代表下列何項？","opts":["比較標的的現在平均一年期間之客觀淨收益","比較標的的未來平均一年期間之客觀淨收益","勘估標的的現在平均一年期間之客觀淨收益","勘估標的的未來平均一年期間之客觀淨收益"],"ok":[3],"ex":["比較標的之淨收益是用來推算資本化率 r 的，不是 a。","比較標的不是 a 的來源。","直接資本化法的 a 是「未來」平均一年之淨收益，不是現在；現行 §29 沒有「現在」之用語（105-19、108-17、109-11、114-6 官方答案皆為「未來平均一年」）。","✓ a＝勘估標的「未來」平均一年期間之客觀淨收益（§29、§30）。直接資本化法：收益價格＝勘估標的未來平均一年期間之客觀淨收益÷收益資本化率；DCF 則是未來「各期」淨收益加期末價值。"],"tr":"關鍵字三件事：勘估標的（不是比較標的）＋「未來」平均一年（不是現在、不是過去）＋客觀淨收益。歷屆考過「過去平均一年」「未來平均三年」當錯誤選項。⚠ 原補習班卷解答為「現在」，與現行 §29 不符，已更正，考試以現行條文為準。"},{"id":"hs1-14","p":"hs1","src":"估價來勝模擬試題一 第14題","sec":"成本法折舊計算","stem":"經濟耐用年數40年，經歷年數30年，殘餘價格率10%，則以等速折舊計算建物價格日期未來每年折舊提存率，答案為何？","opts":["6.84%","6.92%","7.11%","7.15%"],"ok":[1],"ex":["6.84%：計算略有偏差。","✓ 6.92%。等速折舊型（§41）：每年折舊提存率＝每年折舊額÷建物現值成數。每年折舊額＝(1−s)÷N＝0.9÷40＝2.25%；現值成數＝1−(1−s)×n÷N＝1−0.9×30÷40＝32.5%；提存率＝2.25%÷32.5%≈6.92%。老師寫法：折舊提存率＝年折舊率÷(1−累積折舊率)＝[(1−s)/N]÷[1−(1−s)/N×n]＝(1−10%)/40 ÷ [1−(1−10%)/40×30]＝6.92%。另一個算法是折舊提存「費」（§40-1）：C×(1−s)×1/N，假設 C＝1,000 萬 → 1,000×0.9÷40＝22.5 萬元；本題問「率」，答 6.92%，別和「費」混。","7.11%：計算偏高。","7.15%：計算偏高。"],"tr":"等速型＝直線折舊額÷「目前」現值成數（分母是現值，不是原成本）；償債基金型才用年金終值（i＞0）。別把兩型混用。"},{"id":"hs1-15","p":"hs1","src":"估價來勝模擬試題一 第15題","sec":"成本法耐用年數","stem":"建物之經歷年數大於其經濟耐用年數，應重新調整下列何項？","opts":["經歷年數","殘餘年數","經濟耐用年數","物理耐用年數"],"ok":[2],"ex":["經歷年數：已發生的時間，不能調整。","殘餘年數：殘餘=耐用-經歷，調整源頭才是正確做法。","✓ §65末句：「建物之經歷年數大於其經濟耐用年數時，應重新調整經濟耐用年數。」","§65以經濟耐用年數為主，「必要時得以物理耐用年數計算」；本題情形依§65末句應調整的是經濟耐用年數，不是物理耐用年數。"],"tr":"經歷年數 > 經濟耐用年數 → 建物仍在使用 → 說明原本低估了 → 重新評估「經濟耐用年數」（往上調）。"},{"id":"hs1-16","p":"hs1","src":"估價來勝模擬試題一 第16題","sec":"權利估價","stem":"權利變換前之基地未建築使用者，以下列何種價值推估其土地權利價值？","opts":["空地價值","素地價值","裡地價值","土地貢獻價值"],"ok":[1],"ex":["空地價值：非技術規則用語。","✓ 素地價值：§127「權利變換前之基地未建築使用者，以素地價值推估其土地權利價值」。","裡地價值：技術規則條文中沒有「裡地」這個用語，是干擾項。","土地貢獻價值：非此條用語。"],"tr":"未建築基地→素地價值（§127）。素地總價值也用於§126：基地總價值低於素地總價值時，依比率調整分配。"},{"id":"hs1-17","p":"hs1","src":"估價來勝模擬試題一 第17題","sec":"租金估計","stem":"「差額分配法」是應用在下列何種估價或估計之方法？","opts":["租賃權估價","區分地上權估價","新訂租約之租金估計","續訂租約之租金估計"],"ok":[3],"ex":["租賃權估價依§122考量契約內容、租期、租金支付方式等因素，條文沒有差額分配法。","地上權估價依§116考量用途、存續期間、地租等因素，條文沒有差額分配法。","新訂租約依§132採比較法、價格×租金收益率、企業經營總收入三種方式，沒有差額分配法。","✓ 差額分配法是§133第4款續訂租約的方法：「分析勘估標的原契約租金與市場經濟租金之差額中，應歸屬於出租人之適當部分，加計契約租金」。"],"tr":"差額分配法 = 舊租約要續訂 → 契約租金 vs 市場租金有差額 → 雙方協商分配。新租約不需要，直接看市場。"},{"id":"hs1-18","p":"hs1","src":"估價來勝模擬試題一 第18題","sec":"區分所有建物","stem":"土地立體空間效用百分率，稱為下列何項？","opts":["部分別效用比","樓層別效用比","地價分配率","深度指數"],"ok":[2],"ex":["部分別效用比：非技術規則用語。","樓層別效用比：是各樓層間「效用高低的比值」（§98、§100、§101），不是「百分率」之名稱。","✓ 地價分配率：各樓層（立體空間）分得之地價百分率，§100 以「平均地價分配率÷該建物之地價分配率」調整基地單價。","深度指數：土地深度對地價之影響，與立體空間無關。"],"tr":"⚠ 技術規則條文未逐字定義此詞，老師原卷答案請考前核對；判斷依據：「百分率」＝分配率，「效用比」＝比值。"},{"id":"hs1-19","p":"hs1","src":"估價來勝模擬試題一 第19題","sec":"收益法名詞","stem":"價格日期當時勘估標的按法定用途出租或營運，在正常情況下所獲得之租金或收益數額，稱為：","opts":["總收入","有效總收入","淨收益","收益價格"],"ok":[0],"ex":["✓ 總收入（PGI，潛在總收入；§36）：按法定用途、正常情況下可獲得之全額租金或收益，尚未扣除空租損失。","有效總收入（EGI）：已扣除空租損失後的收入。","淨收益＝有效總收入－總費用（§42）；總費用包括地價稅或地租、房屋稅、保險費、管理費及維修費等，營運性不動產還要加計營運費用（§38）。","收益價格：最終估算出的不動產價值，非收益數額。"],"tr":"「按法定用途、正常使用、未扣任何損失」→ 總收入（PGI）。一旦提到扣除空租，就是有效總收入。"},{"id":"hs1-20","p":"hs1","src":"估價來勝模擬試題一 第20題","sec":"收益法資本化率","stem":"r₁代表土地收益資本化率，r₂代表建物收益資本化率，r代表房地綜合收益資本化率，則三項大小關係為何？","opts":["r₁>r₂>r","r₁>r>r₂","r₂>r₁>r","r₂>r>r₁"],"ok":[3],"ex":["r₁>r₂>r：房地綜合率不可能小於兩個組成率中的最小者，錯誤。","r₁>r>r₂：土地率不會高於建物率，錯誤。","r₂>r₁>r：綜合率是土地率與建物率的加權平均，必介於兩者之間，不可能最小，錯誤。","✓ r₂>r>r₁：建物有折舊、風險較高，資本化率最大；土地無折舊、保值性高，最小；房地綜合資本化率依土地、建物價值比率加權（§46），介於兩者之間。"],"tr":"綜合率＝加權平均＝一定夾在土地率與建物率中間：建物率>綜合率>土地率。"},{"id":"hs1-21","p":"hs1","src":"估價來勝模擬試題一 第21題","sec":"估價通則","stem":"實際建築使用之容積率超過法定容積率之房地估價，下列何項最正確？","opts":["以法定建築使用合法部分之現況估價","以法定建築使用合法部分之現況估價，並敘明實際容積對估值之影響","以實際建築使用合法部分之現況估價","以實際建築使用合法部分之現況估價，並敘明法定容積對估值之影響"],"ok":[3],"ex":["以「法定」容積估價並非條文用語，且未敘明影響，錯誤。","以「法定」為估價基礎、敘明「實際」容積影響——主詞與條文整個顛倒，錯誤。","僅以實際建築使用合法部分估價，但未敘明法定容積之影響，不完整。","✓ §102：以「實際建築使用合法部分」之現況估價，並敘明「法定容積」對估值之影響。"],"tr":"§102 口訣：估價看「實際使用的合法部分」，說明看「法定容積」。別和違建（§103：不予評估）搞混。"},{"id":"hs1-22","p":"hs1","src":"估價來勝模擬試題一 第22題","sec":"比較法區域因素","stem":"區域因素，指影響下列何項地區不動產價格水準之因素？","opts":["近鄰地區","類似地區","同一生活圈","同一供需圈"],"ok":[0],"ex":["✓ 近鄰地區：§2 第15款「區域因素，指影響近鄰地區不動產價格水準之因素」。","類似地區是同一供需圈內、近鄰地區以外使用性質相近的地區（§2 第13款），不是區域因素的影響範圍。","同一生活圈不是規則用語。","同一供需圈（§2 第11款）是比較標的與勘估標的能成立替代關係的最適範圍，等於近鄰地區＋類似地區；區域因素的條文用語是「近鄰地區」，不是「同一供需圈」。"],"tr":"一般因素＝全面影響；區域因素＝影響「近鄰地區」價格水準；個別因素＝不動產本身條件。⚠ 原補習班卷解答為「同一供需圈」，與 §2 第15款不符，已更正，考試以現行條文為準。"},{"id":"hs1-23","p":"hs1","src":"估價來勝模擬試題一 第23題","sec":"土地開發分析法資金成本","stem":"資金來源中，借貸資金：自有資金：預售收入＝3：2：1。投入土地部分及建築部分之比例為5：4。借貸資金成本為5%，自有資金機會成本為2%，開發年數3年，則資本利息綜合利率為多少？","opts":["7.14%","7.28%","7.39%","7.42%"],"ok":[2],"ex":["7.14%：計算方式有誤。","7.28%：計算方式有誤。","✓ 7.39%。§79：綜合利率＝年利率×（土地比率＋建物比率×½）×開發年數。①年利率（§58、§59，預售收入不計息）＝3/6×5%＋2/6×2%＋1/6×0%≈3.167%；②土地比率5/9、建物比率4/9，故（5/9＋4/9×½）＝7/9；③3.167%×7/9×3年≈7.39%。","7.42%：計算略高。"],"tr":"三步：①資金比例加權成年利率（預售收入不計息）②土地全期、建物半期（比率×½）③乘開發年數，是單利式不是複利。"},{"id":"hs1-24","p":"hs1","src":"估價來勝模擬試題一 第24題","sec":"公共設施保留地","stem":"公共設施保留地之估價，以何種估價方法為原則？","opts":["比較法","收益法","成本法","土地開發分析法"],"ok":[0],"ex":["✓ 比較法：§97 公共設施用地及保留地估價以比較法為原則，無買賣實例者，比較其與毗鄰土地使用分區及使用強度之差異與土地價值減損情況，並斟酌毗鄰土地平均價格為基礎推算。","收益法：公共設施保留地通常無收益可計，不適合。","成本法也可以用於土地（§69：土地價格＝土地總成本），但§97明定公共設施用地及公共設施保留地「以比較法估價為原則」，所以不是成本法。","土地開發分析法：用於有開發潛力的土地，公設保留地受限制，不適合。"],"tr":"公設保留地估價→比較法（無買賣實例者，比較毗鄰土地使用分區、使用強度差異及價值減損）。這是技術規則明文（§97）；比較標的怎麼選考過 106-13、112-19，兩題官方答案相反，見《特殊標的總整理》§97。"},{"id":"hs1-25","p":"hs1","src":"估價來勝模擬試題一 第25題","sec":"價格種類","stem":"下列何種價格估價，應同時估計其正常價格？","opts":["特定價格","特殊價格","限定價格","特別價格"],"ok":[0],"ex":["✓ 特定價格：技術規則§6 後段明定，以特定價格估價者，應敘明其估價條件，並同時估計其正常價格。","特殊價格：不具市場性不動產之價值（§2），無須同時估正常價格。","限定價格：特定限定條件下之價值（§2），無須同時估正常價格。","特別價格：非技術規則正式用語。"],"tr":"四種價格中，只有「特定價格」（§6 後段）規定必須敘明估價條件並同時估計正常價格；限定、特殊都不用。"},{"id":"vdiag1-1","p":"vdiag1","src":"估價診斷卷① 第1題","sec":"收益法","stem":"依不動產估價技術規則，以直接資本化法評估收益價格，下列敘述何者正確？","opts":["收益價格＝淨收益÷（資本化率＋折舊率）","收益價格＝未來一年之淨收益÷資本化率","收益價格以各期淨收益折現加總求得，與折現現金流量分析法相同","資本化率係以市場比較法決定，不得採用其他方法"],"ok":[1],"ex":["","","",""],"tr":"✅ 正確答案：B\n\n  直接資本化法公式：收益價格＝勘估標的未來平均一年期間之客觀淨收益÷收益資本化率（技術規則§29、§30）。\n\n  ❌ A：§30直接資本化法的分母只有收益資本化率；只有淨收益未扣除折舊提存費時，§45、§46才在建物部分加計折舊提存率，所以不是直接資本化法的一般公式。❌ C：逐期折現是DCF法，非直接資本化法。❌ D：技術規則規定有五種方法可決定資本化率（風險溢酬法、市場萃取法、WACC法、有效總收入乘數法、債務保障比率法）。\n  技術規則§29、§30"},{"id":"vdiag1-2","p":"vdiag1","src":"估價診斷卷① 第2題","sec":"收益法","stem":"依加權平均資金成本法（WACC）決定資本化率，下列公式何者正確？（E：自有資金比率；re：自有資金報酬率；D：借入資金比率；rd：借入資金利率）","opts":["r＝E×rd＋D×re","r＝E÷re＋D÷rd","r＝E×re＋D×rd","r＝(re＋rd)÷2"],"ok":[2],"ex":["","","",""],"tr":"✅ 正確答案：C\n\n  WACC公式：r＝E×re＋D×rd，各資金來源比率乘以各自報酬率後加總（99年申論題考點）。\n\n  ❌ A：混淆自有與借入對應報酬率。❌ B：應乘法非除法。❌ D：簡單平均未考慮各自比率。\n  r ＝ 自有比率×自有資金報酬率 ＋ 借入比率×借入資金利率"},{"id":"vdiag1-3","p":"vdiag1","src":"估價診斷卷① 第3題","sec":"收益法","stem":"債務保障比率法（DCR法）決定資本化率，其公式為何？（DCR：債務保障比率；MC：抵押貸款常數；LTV：放款成數）","opts":["資本化率＝DCR×MC×LTV","資本化率＝DCR×MC÷LTV","資本化率＝MC×LTV÷DCR","資本化率＝LTV÷（DCR×MC）"],"ok":[0],"ex":["","","",""],"tr":"✅ 正確答案：A\n\n  DCR法公式（§43第四款）：r＝債務保障比率×貸款常數×貸款資金占不動產價格比率（歷屆104、111～114年選擇題）。\n\n  口訣：「三個連乘」。銀行要求的DCR愈高（愈保守），資本化率愈高，不是除。\n  r ＝ 債務保障比率 × 貸款常數 × 貸款成數"},{"id":"vdiag1-4","p":"vdiag1","src":"估價診斷卷① 第4題","sec":"收益法","stem":"折現現金流量分析法（DCF）與直接資本化法最主要的差異，在於前者：","opts":["以總收益而非淨收益為計算基礎","以市場比較法決定折現率，排除其他方法","僅適用於商業不動產，不適用於住宅","逐期估算各期淨收益及期末處分價值，分別折現後加總求得收益價格"],"ok":[3],"ex":["","","",""],"tr":"✅ 正確答案：D\n\n  DCF核心特徵：逐期估算各期淨收益＋保有期間末轉售價值，各別乘以折現因子後加總（113年申論題）。\n\n  直接資本化法只用「勘估標的未來平均一年期間之客觀淨收益÷收益資本化率」（§30），假設未來收益穩定；DCF適合未來收益波動大的情形。"},{"id":"vdiag1-5","p":"vdiag1","src":"估價診斷卷① 第5題","sec":"成本法","stem":"依不動產估價技術規則，建物定額折舊法（直線法）累積折舊額Dn之公式，下列何者正確？（C：重建或重置成本；s：殘餘價格率；N：經濟耐用年數；n：經過年數）","opts":["Dn＝C×(1＋s)/N×n","Dn＝C×(1－s)/N×n","Dn＝C×s/N×n","Dn＝C/(1－s)×N×n"],"ok":[1],"ex":["","","",""],"tr":"✅ 正確答案：B\n\n  定額法（直線法）：累積折舊額 Dn＝C×(1－s)/N×n（教材公式；技術規則§68只規定可選擇等速折舊路徑，沒有列出累積折舊額公式；殘餘價格率以不超過10%為原則，§67）。\n  累積折舊額 Dn ＝ C × (1－s) ÷ N × n\n  ❌ A：應用「1－s」非「1＋s」。❌ C：s是留下來的部分，不可直接乘。❌ D：把(1－s)放在分母，又把N當乘數，和直線折舊「每年折舊額＝C×(1－s)÷N」不符。\n  技術規則§68、§67"},{"id":"vdiag1-6","p":"vdiag1","src":"估價診斷卷① 第6題","sec":"成本法","stem":"依不動產估價技術規則，建物折舊路徑（Pattern）共有三種，下列何者不屬於技術規則所規定的折舊路徑？","opts":["等速折舊路徑（直線形）","初期加速折舊路徑（遞減形）","後期加速折舊路徑（後段陡升形）","初期減速折舊路徑（遞增形）"],"ok":[2],"ex":["","","",""],"tr":"✅ 正確答案：C\n\n  技術規則三種折舊路徑（§68）：①等速（直線形）→定額法 ②初期加速（遞減形）→定率法 ③初期減速（遞增形）→償債基金法。\n\n  ❌ C「後期加速折舊」不在三種之列——考試陷阱！（105年申論題考點）"},{"id":"vdiag1-7","p":"vdiag1","src":"估價診斷卷① 第7題","sec":"成本法","stem":"依定率法（餘額遞減法）計算折舊，建物重建成本C＝500萬元，折舊率r＝10%，則第2年末之帳面價值為何？","opts":["405萬元","400萬元","450萬元","410萬元"],"ok":[0],"ex":["","","",""],"tr":"✅ 正確答案：A\n\n  第1年：折舊500×10%＝50萬，帳面450萬。第2年：折舊450×10%＝45萬，帳面405萬。\n  第n年帳面 ＝ C × (1－r)ⁿ ＝ 500 × (0.9)² ＝ 405萬\n  考試陷阱：定率法對「帳面價值」課折舊，非原始成本；第2年折舊額45萬≠第1年50萬。"},{"id":"vdiag1-8","p":"vdiag1","src":"估價診斷卷① 第8題","sec":"成本法","stem":"依不動產估價技術規則，「重建成本」與「重置成本」的差異，下列敘述何者正確？","opts":["重建成本係以現代建材標準、設計及配置，建造相同效用之建物；重置成本係以相同或極類似之建材標準、設計複製","兩者均指以估價當時技術重建相同效用之建物","重建成本一定高於重置成本","重建成本係使用相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製之成本；重置成本係以現代建材標準、設計及配置，建造相同效用建物之成本"],"ok":[3],"ex":["","","",""],"tr":"✅ 正確答案：D\n\n  重建成本：相同或極類似之建材標準、設計、配置及施工品質，重新複製（原則）。重置成本：以現代建材標準、設計及配置，建造相同效用之建物（建材已無生產或施工方法已改變時之例外）。\n\n  ❌ A把兩者定義對調（重建＝複製、重置＝現代材料建同效用）。❌ B：只有重置成本是「現代建材、相同效用」；重建成本是相同或極類似建材的複製（§48），兩者不同。❌ C不一定哪個更高。（技術規則§48，111年申論題）"},{"id":"vdiag1-9","p":"vdiag1","src":"估價診斷卷① 第9題","sec":"比較法","stem":"依不動產估價技術規則，比較法「比較修正」之單項調整率與總調整率的限制為何？","opts":["單項不超過20%；總調整率不超過30%","單項不超過15%；總調整率不超過30%","單項不超過15%；總調整率不超過25%","單項不超過10%；總調整率不超過20%"],"ok":[1],"ex":["","","",""],"tr":"✅ 正確答案：B\n\n  比較法排除規則（技術規則§25、§26）三道關卡：①§25 單項調整率大於15%排除 ②§25 總調整率大於30%排除（剛好15%、30%仍可採用） ③§26 試算價格間差距達20%以上，應先重新檢討，檢討後仍達20%以上者，排除該試算價格。"},{"id":"vdiag1-10","p":"vdiag1","src":"估價診斷卷① 第10題","sec":"比較法","stem":"比較法的調整順序依技術規則之規定，正確順序為何？","opts":["情況調整→價格日期調整→區域因素調整→個別因素調整","區域因素調整→個別因素調整→情況調整→價格日期調整","價格日期調整→情況調整→區域因素調整→個別因素調整","個別因素調整→區域因素調整→價格日期調整→情況調整"],"ok":[0],"ex":["","","",""],"tr":"✅ 正確答案：A\n\n  四步驟（技術規則§21 比較法程序）：①情況調整（排除非正常成交）→②價格日期調整（時間）→③區域因素調整（地段）→④個別因素調整（個別條件）。\n\n  口訣：「情日區個」（情況→日期→區域→個別），由外到內、由大到小。"},{"id":"vdiag1-11","p":"vdiag1","src":"估價診斷卷① 第11題","sec":"比較法","stem":"依不動產估價技術規則，下列何種情況的比較實例，應不予採用（無法以情況調整處理）？","opts":["買賣雙方情誼特殊（如親友間交易），成交價格偏低","賣方急需資金，售價低於市場行情","毗鄰地主購買相鄰土地，其獲得之特殊利益無法量化調整","附有特殊融資條件，可計算合理之融資調整率"],"ok":[2],"ex":["","","",""],"tr":"✅ 正確答案：C\n\n  情況調整目的是還原成「正常交易價格」，但特殊利益無法量化（如毗鄰地主合併增值），連調整都不可能→應直接排除。\n\n  A/B雖非正常但可量化→可做情況調整。D可計算→可做情況調整。（102年、110年申論考點）"},{"id":"vdiag1-12","p":"vdiag1","src":"估價診斷卷① 第12題","sec":"土地開發","stem":"土地開發分析法中，建物興建資金之利息計算方式為何？","opts":["建物興建費用全額乘以建設期間利率","建物興建費用乘以1/2再乘以建設期間利率，因為資金係陸續投入","建物興建費用乘以1/3再乘以建設期間利率","建物興建費用不計算資本利息，僅計土地取得資金之利息"],"ok":[1],"ex":["","","",""],"tr":"✅ 正確答案：B\n\n  資本利息綜合利率（技術規則§79）：i＝資本利息年利率×（土地價值比率＋建物價值比率×1/2）×開發年數；1/2 乘在建物價值比率上，因興建資金係陸續分批投入，平均使用時間約為建設期間的一半。\n  資本利息 ＝ 土地取得資金利息 ＋ 建物興建費×(1/2)×建設期間利率\n  105年、100年申論題均考此公式。"},{"id":"vdiag1-13","p":"vdiag1","src":"估價診斷卷① 第13題","sec":"土地開發","stem":"土地開發分析法公式 V＝S÷(1＋R)÷(1＋i)－(C＋M)（§81），各符號意義下列何者錯誤？","opts":["S＝開發完銷後不動產總銷售收入","R＝適當利潤率","C＝直接成本（營造施工費等），M＝間接成本","i＝建物完工後銷售期間之空置率"],"ok":[3],"ex":["","","",""],"tr":"✅ 正確答案：D\n\n  i＝資本利息綜合利率（§79；不是空置率）。V＝開發前土地價值；S＝總銷售金額；R＝適當利潤率；C＝直接成本；M＝間接成本（直接成本＝營造施工費；間接成本＝規劃設計費、廣告銷售費、管理費、稅捐及其他負擔）。\n  V ＝ S ÷ (1＋R) ÷ (1＋i) － (C＋M)"},{"id":"vdiag1-14","p":"vdiag1","src":"估價診斷卷① 第14題","sec":"估價原則","stem":"某建物位於高壓電塔附近，因電磁波疑慮導致市場購買意願降低，此現象最符合哪個不動產估價原則？","opts":["預期原則","均衡原則","外部性原則","適合原則"],"ok":[2],"ex":["","","",""],"tr":"✅ 正確答案：C\n\n  外部性原則（估價基本原則）：不動產價格受外部因素正面或負面影響。高壓電塔屬「外部嫌惡設施」→負外部性。\n\n  113年考法：高壓電塔→外部性原則（113-2）；「房子距大安森林公園約50公尺」→非區域因素（113-18，屬標的本身條件）。"},{"id":"vdiag1-15","p":"vdiag1","src":"估價診斷卷① 第15題","sec":"估價原則","stem":"「最有效使用」原則在估價實務上的涵義，下列敘述何者最完整？","opts":["依法令規定、實際使用可能性，於估價當時能產生最高價值之合理使用","能使不動產所有人獲得最高利潤之使用","建蔽率與容積率用盡的使用方式","市場上最熱門的使用方式"],"ok":[0],"ex":["","","",""],"tr":"✅ 正確答案：A\n\n  最有效使用（技術規則§2第17款）：客觀上具有良好意識及通常使用能力者，在①合法 ②實質可能 ③正當合理 ④財務可行前提下之使用，所得之最高、最佳使用（非主觀利潤最高、非用盡容積）。"},{"id":"vdiag1-16","p":"vdiag1","src":"估價診斷卷① 第16題","sec":"價格種類","stem":"下列哪種不動產價格種類，在估價時須同時估計正常價格？","opts":["正常價格","特定價格","特殊價格","限定價格"],"ok":[1],"ex":["","","",""],"tr":"✅ 正確答案：B\n\n  特定價格（技術規則§6 後段）：以特定價格估價者，應敘明估價條件，並同時估計其正常價格。\n\n  只有「特定價格」才有此規定；限定價格（§2 三種限定條件）、特殊價格（不具市場性）都不用——考試陷阱！（111年第13題）"},{"id":"vdiag1-17","p":"vdiag1","src":"估價診斷卷① 第17題","sec":"價格種類","stem":"公立博物館建物（具文化保存價值，不在市場上買賣）之估價，應採下列何種價格種類？","opts":["限定價格","特殊價格","特定價格","正常價格"],"ok":[1],"ex":["","","",""],"tr":"✅ 正確答案：B\n\n  特殊價格（技術規則§2第4款：對不具市場性之不動產所估計之價值）：非市場性不動產，因用途特殊或無市場交易（文化財、宗教用地、廟宇、博物館），以外於市場的價值概念決定之價格。\n\n  ❌ 限定價格：市場存在但特定當事人合併。❌ 特定價格：市場存在，但基於特定條件形成（須敘明估價條件並同時估正常價格）。"},{"id":"vdiag1-18","p":"vdiag1","src":"估價診斷卷① 第18題","sec":"影響因素","stem":"政府公告調漲地價稅（稅率提高），對不動產市場整體價格造成下跌壓力，此屬於哪類影響因素？","opts":["區域因素","個別因素","一般因素","特殊因素"],"ok":[2],"ex":["","","",""],"tr":"✅ 正確答案：C\n\n  一般因素：影響全國不動產市場的大環境（政策/稅制/利率/總體經濟）。地價稅屬全國性稅制→一般因素。\n\n  ❌ 「特殊因素」不在技術規則因素分類中（是干擾選項）。（技術規則§2第14～16款：影響因素只有一般因素、區域因素、個別因素三種）"},{"id":"vdiag1-19","p":"vdiag1","src":"估價診斷卷① 第19題","sec":"影響因素","stem":"某大廈某層發生命案（凶宅），導致該戶市場價格低於其他相同樓層，此屬於下列何種影響因素？","opts":["個別因素","區域因素","一般因素","外部因素"],"ok":[0],"ex":["","","",""],"tr":"✅ 正確答案：A\n\n  個別因素：影響「個別不動產」本身的因素（地形、座向、樓層、凶宅污名）（112年申論考點）。\n\n  凶宅僅影響該「戶」→個別因素。若整棟附近大事→區域因素；全市政策→一般因素。"},{"id":"vdiag1-20","p":"vdiag1","src":"估價診斷卷① 第20題","sec":"租金","stem":"「實質租金」的計算，下列何者正確？","opts":["實質租金＝支付租金（年租金）","實質租金＝支付租金×（1＋押金利率）","實質租金＝支付租金＋押金等之運用收益（押金×利率）","實質租金＝年租金－管理費"],"ok":[2],"ex":["","","",""],"tr":"✅ 正確答案：C\n\n  實質租金（技術規則§130）：承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數；押金、保證金、權利金之運用收益，§130未規定利率，計算題依題目所給利率（教材常以一年期定存利率；101-二即用年定存利率2%）計算。\n  實質租金 ＝ 支付租金 ＋ 押金 × 利率（運用收益）\n  押金交給房東使用，承租人損失押金可孳生的利息→此為隱性租金成本。（114年、101年申論考點）"},{"id":"vdiag1-21","p":"vdiag1","src":"估價診斷卷① 第21題","sec":"收益法","stem":"有效總收入乘數法（GIM法）決定資本化率，其公式為何？（GIM：有效總收入乘數；OER：營運費用率）","opts":["r＝GIM×OER","r＝(1－OER)÷GIM","r＝OER÷GIM","r＝GIM÷(1－OER)"],"ok":[1],"ex":["","","",""],"tr":"✅ 正確答案：B\n\n  GIM法推導：淨收益率＝(1－OER)；收益價格＝有效總收入×GIM；∴r＝淨收益÷收益價格＝(1－OER)÷GIM。\n  資本化率 r ＝ (1 － 營運費用率) ÷ 有效總收入乘數\n  五種資本化率方法都要能辨識與計算（近年高頻）。"},{"id":"vdiag1-22","p":"vdiag1","src":"估價診斷卷① 第22題","sec":"估價程序","stem":"依不動產估價技術規則，蒐集比較實例應符合的四項原則，下列何者不屬於其中之一？","opts":["實例價格形成日期與價格日期接近","實例與勘估標的使用性質或使用管制相同或相近","實例位於同一供需圈之近鄰地區或類似地區","實例之成交價格須高於公告地價以上"],"ok":[3],"ex":["","","",""],"tr":"✅ 正確答案：D\n\n  蒐集比較實例四原則（技術規則§12）：①價格屬正常價格、可調整為正常價格或價格種類相同 ②同一供需圈之近鄰地區或類似地區 ③使用性質或使用管制相同或相近 ④價格形成日期與價格日期接近。\n\n  ❌ D「須高於公告地價」不是規定條件——完全是干擾選項。（106年申論考點）"},{"id":"vdiag1-23","p":"vdiag1","src":"估價診斷卷① 第23題","sec":"綜合應用","stem":"依不動產估價技術規則，計量模型分析法（CAMA）的「判定係數」（R²）應達多少以上？","opts":["0.7以上","0.5以上","0.8以上","0.6以上"],"ok":[0],"ex":["","","",""],"tr":"✅ 正確答案：A\n\n  CAMA法三項門檻（技術規則§20）：①樣本數≥自變數個數×5倍 ②調整後判定係數不得低於0.7 ③截距項以外各主要影響價格因素之係數估計值同時為零之顯著機率不得大於5%。\n\n  三項同時達到才可使用。記憶：「5倍、0.7、5%」。"},{"id":"vdiag1-24","p":"vdiag1","src":"估價診斷卷① 第24題","sec":"綜合應用","stem":"依不動產估價技術規則，估價師受託評估含有違章建築之不動產時，應如何處理？","opts":["應拒絕受理估價委託","僅估計合法建物部分，違建不計入","應於估價報告書中敘明，並說明違章建築對不動產價格之影響","違章建築依市場行情直接計入估價結果"],"ok":[1],"ex":["","","",""],"tr":"✅ 正確答案：B\n\n  違章建築（技術規則§103）：違建部分不予評估；但委託人要求評估者，須就合法建物及違建部分於報告書中分別標示各該部分價格。\n\n  ❌ A：規定並未要求拒絕受理。❌ C：§103 的重點是「不予評估」，不是「敘明影響」。❌ D：不得直接合併計入。"},{"id":"vdiag1-25","p":"vdiag1","src":"估價診斷卷① 第25題","sec":"綜合應用","stem":"依不動產估價技術規則§100，區分所有建物「基地單價」依地價分配率調整之方式，下列何者正確？","opts":["基地單價＝基地權利單價×平均地價分配率÷該區分所有建物之地價分配率","基地單價＝基地權利單價×該區分所有建物之地價分配率÷平均地價分配率","各樓層基地單價相同，與地價分配率無關","基地單價＝基地總地價÷樓層數"],"ok":[0],"ex":["","","",""],"tr":"✅ 正確答案：A\n\n  區分所有建物基地單價（技術規則§100）：基地單價＝基地權利單價×平均地價分配率÷該區分所有建物之地價分配率。\n\n  §98 要求區分所有建物合併估價並調整樓層別效用比；§99 由房地價減建物成本價求基地單價；§100 以地價分配率調整；§101 已知價值比率時依比率推估。"},{"id":"h:99-2","p":"h","src":"99年第2題","sec":"A1","stem":"客觀上具有良好意識及通常之使用能力者，在合法、實質可能、正當合理、財務可行前提下，所作得以獲致最高利益之使用的估價原則是指那一種原則呢？","opts":["最有效使用原則","均衡原則","適合原則","競爭原則"],"ok":[0],"ex":["技術規則第2條第17款明定：最有效使用，指客觀上具有良好意識及通常之使用能力者，在合法、實質可能、正當合理、財務可行四項前提下，得以獲致最高利益之使用，與題目敘述完全相符。","均衡原則指生產要素間達最適配置，與題目所述「客觀上良好意識使用能力者」之四項前提定義無關。","適合原則指不動產與其坐落環境協調一致，與題目定義無關。","競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「合法、實質可能、正當合理、財務可行前提下獲致最高利益之使用」與超額利潤之競爭無關（屬最有效使用原則），故非本題答案。"],"tr":"","core":["最有效使用＝四前提下獲致最高利益","均衡原則講生產要素最適配置","適合原則講與坐落環境協調一致","競爭原則講超額利潤引來競爭而消失"],"hl":[[],["均衡原則","生產要素間達最適配置"],["適合原則","不動產與其坐落環境協調一致"],["競爭原則","屬最有效使用原則"]]},{"id":"h:99-15","p":"h","src":"99年第15題","sec":"A1","stem":"要使不動產創造最高價值，其生產要素間要達到最適配置，請問此屬於何種原則？","opts":["貢獻原則","適合原則","均衡原則","收益分配原則"],"ok":[2],"ex":["貢獻原則指局部對整體價值之貢獻（如加裝電梯提升整體價值），與「生產要素間達最適配置」此一定義不同。","適合原則指不動產與坐落環境之協調，與生產要素配置無關。","均衡原則之核心概念即為生產要素（如土地與建物比例）間達最適配置才能創造最高價值，與題目敘述相符。","「收益分配原則」是指營運性不動產應扣除非屬不動產本身之收益，與生產要素配置無關。"],"tr":"","core":["貢獻原則講局部對整體價值之貢獻","適合原則講與坐落環境協調","均衡＝生產要素達最適配置","收益分配原則講扣除非不動產收益"],"hl":[["貢獻原則","局部對整體價值之貢獻"],["適合原則","不動產與坐落環境之協調"],[],["收益分配原則","營運性不動產應扣除非屬不動產本身之收益"]]},{"id":"h:99-19","p":"h","src":"99年第19題","sec":"A1","stem":"不動產估價時，對於土地與建物結合體於市場形成之不動產價格中，扣除土地、建物成本外，其餘部分認為是來自土地與建物之價值，此一原則係指：","opts":["土地貢獻原則","建物貢獻原則","土地建物聯合貢獻原則","均衡原則"],"ok":[2],"ex":["「土地貢獻原則」單獨強調土地對價值之貢獻，題目敘述的是「土地與建物結合體」之聯合貢獻，非單一土地貢獻。","「建物貢獻原則」單獨強調建物對價值之貢獻，同樣與題目所述聯合貢獻概念不符。","題目描述：土地與建物結合體扣除個別成本後的剩餘部分，認為是來自土地與建物「共同聯合」貢獻所致，此即土地建物聯合貢獻原則（聯合貢獻說），是房地價值分配理論中的核心觀點。","均衡原則指生產要素達最適配置，與此處「扣除成本後剩餘價值之歸屬」定義不同。"],"tr":"","core":["土地貢獻原則只強調土地，非聯合","建物貢獻原則只強調建物，非聯合","扣成本後剩餘歸土地建物聯合貢獻","均衡原則講生產要素最適配置"],"hl":[["土地貢獻原則","「土地與建物結合體」之聯合貢獻"],["建物貢獻原則","題目所述聯合貢獻概念"],[],["均衡原則","生產要素達最適配置"]]},{"id":"h:99-24","p":"h","src":"99年第24題","sec":"A1","stem":"下列何種原則強調不動產與其坐落環境間之關係？","opts":["適合原則","均衡原則","預測原則","貢獻原則"],"ok":[0],"ex":["估價理論（教材）之定義：適合原則，強調不動產與其坐落環境達成協調一致，與題目所問「不動產與其坐落環境間之關係」完全相符。","均衡原則強調的是生產要素內部配置，並非不動產與外部環境的關係。","預測（預期）原則強調對未來收益或發展之預期，並非單純坐落環境之關係。","貢獻原則強調局部對整體價值之貢獻，並非不動產與坐落環境之協調關係。"],"tr":"","core":["適合原則＝與坐落環境協調一致","均衡原則講內部生產要素配置","預測原則講對未來收益之預期","貢獻原則講局部對整體之貢獻"],"hl":[[],["均衡原則","生產要素內部配置"],["預測原則","對未來收益或發展之預期"],["貢獻原則","局部對整體價值之貢獻"]]},{"id":"h:99-30","p":"h","src":"99年第30題","sec":"A1","stem":"不動產估價報告中常表明評估價格適用的有效期間，此係下列何種原則的具體考量？","opts":["替代原則","競爭原則","最有效使用原則","變動原則"],"ok":[3],"ex":["替代原則強調比較相同滿意度財貨之代價，與「評估價格適用之有效期間」無關。","競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「估價報告書載明評估價格之有效期間」與超額利潤之競爭無關（屬變動原則），故非本題答案。","最有效使用原則強調合法實質可能等四項前提下獲致最高利益之使用，與「有效期間」之記載無關。","變動原則強調不動產價格隨時間變動，故估價報告書應載明價格日期（§16(3)為價格日期及勘察日期；「評估價格適用之有效期間」屬實務／範本用語，非§16條文），與題目敘述相符。"],"tr":"","core":["替代原則講比較同滿意度財貨代價","競爭原則講超額利潤，與有效期間無關","最有效使用與有效期間記載無關","價格隨時間變動，故需載明價格日期"],"hl":[["替代原則","比較相同滿意度財貨之代價"],["競爭原則","屬變動原則"],["最有效使用原則","合法實質可能等四項前提下獲致最高利益之使用"],[]]},{"id":"h:100-6","p":"h","src":"100年第6題","sec":"A1","stem":"公寓新增電梯設備，提高了該棟建物之價值，屬於：","opts":["貢獻原則","外部性原則","預測原則","適合原則"],"ok":[0],"ex":["貢獻原則指局部（電梯設備）對整體（建物）價值之貢獻，加裝電梯使整體價值提升，正是貢獻原則之典型例子。","外部性原則強調周邊環境設施對價格之影響，電梯設備是建物本身的內部改良，非外部環境因素。","預測（預期）原則強調對未來收益之預期，電梯設備是已完成之既有改良，非預期未來之影響。","適合原則強調不動產與坐落環境之協調，與建物內部設備提升無關。"],"tr":"","core":["加裝電梯＝局部對整體價值之貢獻","電梯是內部改良，非周邊環境","電梯是既有改良，非對未來之預期","適合原則講環境協調，非內部設備"],"hl":[[],["外部性原則","周邊環境設施對價格之影響"],["預測原則","對未來收益之預期"],["適合原則","不動產與坐落環境之協調"]]},{"id":"h:100-7","p":"h","src":"100年第7題","sec":"A1","stem":"下列何者為成本法重置成本之成立依據？","opts":["最有效使用原則","競爭原則","替代原則","均衡原則"],"ok":[2],"ex":["最有效使用原則是估價的整體判斷基準，並非成本法重置成本之直接成立依據。","競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「成本法重置成本之成立依據」與超額利潤之競爭無關（屬替代原則），故非本題答案。","替代原則強調審慎消費者不會支付高於相同滿意度替代財貨之代價，是比較法、成本法、收益法三大方法之共同理論基礎；成本法以重建/重置成本作為價格替代依據，正是替代原則之運用（重置觀點）。","均衡原則指生產要素配置，與成本法之重置成本概念無關。"],"tr":"","core":["最有效使用是整體判斷基準，非依據","競爭原則講超額利潤，與重置成本無關","成本法以重置成本替代，屬替代原則","均衡原則講要素配置，與重置無關"],"hl":[["最有效使用原則","估價的整體判斷基準"],["競爭原則","屬替代原則"],[],["均衡原則","生產要素配置"]]},{"id":"h:100-8","p":"h","src":"100年第8題","sec":"A1","stem":"不動產之特性與其外部環境達成協調一致，是為何種原則？","opts":["外部性原則","適合原則","貢獻原則","最有效使用原則"],"ok":[1],"ex":["外部性原則強調周邊環境設施對價格之影響（如公園、嫌惡設施），與「不動產特性與外部環境達成協調一致」此一定義不同（外部性著重影響，非協調）。","適合原則依估價理論（教材）之定義，不動產與其坐落環境達成協調一致，與題目敘述完全相符。","貢獻原則強調局部對整體價值之貢獻，與外部環境協調無關。","最有效使用原則強調合法實質可能等四項前提下之最高利益使用，與環境協調定義不同。"],"tr":"","core":["外部性著重環境的影響，非協調","適合原則＝與外部環境協調一致","貢獻原則講局部對整體之貢獻","最有效使用講四前提最高利益使用"],"hl":[["外部性原則","周邊環境設施對價格之影響"],[],["貢獻原則","局部對整體價值之貢獻"],["最有效使用原則","合法實質可能等四項前提下之最高利益使用"]]},{"id":"h:100-30","p":"h","src":"100年第30題","sec":"A1","stem":"不動產估價報告中常表明評估價格適用的有效期間，此係下列何種原則的具體考量？","opts":["替代原則","競爭原則","最有效使用原則","變動原則"],"ok":[3],"ex":["替代原則強調比較相同滿意度財貨之代價，與「評估價格適用之有效期間」無關。","競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「估價報告書載明評估價格之有效期間」與超額利潤之競爭無關（屬變動原則），故非本題答案。","最有效使用原則與「有效期間」記載無關。","變動原則強調不動產價格隨時間變動，估價報告書應載明價格日期（§16(3)；「有效期間」屬實務／範本用語，非§16條文），與題目相符。"],"tr":"","core":["替代原則講比較同滿意度財貨代價","競爭原則講超額利潤，與有效期間無關","最有效使用與有效期間記載無關","價格隨時間變動，故需載明價格日期"],"hl":[["替代原則","比較相同滿意度財貨之代價"],["競爭原則","屬變動原則"],["最有效使用原則"],[]]},{"id":"h:101-5","p":"h","src":"101年第5題","sec":"A1","stem":"政府提出桃園航空城開發案，將帶動周邊地價上漲，此係下列何項原則的表現？","opts":["競爭原則","貢獻原則","預期原則","適合原則"],"ok":[2],"ex":["競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「開發案預期帶動地價上漲」與超額利潤之競爭無關（屬預期原則），故非本題答案。","貢獻原則強調局部對整體價值之貢獻，與「未來開發案帶動周邊地價上漲」此一對未來發展之預期效果不同。","預期（預測）原則強調對未來收益或發展之預期影響現在價值，桃園航空城開發案屬於尚未完成、預期未來將帶動地價上漲之情境，正是預期原則之典型運用。","適合原則強調不動產與坐落環境之協調，與未來開發案之預期效果無關。"],"tr":"","core":["競爭原則講超額利潤，與開發預期無關","貢獻原則講局部貢獻，非未來預期","航空城預期帶動地價，屬預期原則","適合原則講環境協調，非開發預期"],"hl":[["競爭原則","屬預期原則"],["貢獻原則","局部對整體價值之貢獻"],[],["適合原則","不動產與坐落環境之協調"]]},{"id":"h:101-6","p":"h","src":"101年第6題","sec":"A1","stem":"下列相關原則的陳述何者最不適宜？","opts":["公園對地價的影響係基於外部性原則","老舊公寓價格飆漲係基於均衡原則","不動產有行無市呈現變動原則","在偏遠地區興建大廈卻無法創造利潤係因未能掌握最有效使用原則"],"ok":[1],"ex":["公園屬於周邊環境設施，對地價產生加值影響，確實是外部性原則之表現，此敘述適宜，非本題答案（本題問「最不適宜」）。","均衡原則強調生產要素間達最適配置，「老舊公寓價格飆漲」是市場供需或區域發展等因素所致之價格上漲現象，與生產要素配置無直接關連，將此現象歸因於均衡原則並不適宜，即本題正解。","「不動產有行無市」反映價格隨時間、市場狀況變動之特性，符合變動原則之精神，此敘述適宜。","在偏遠地區興建大廈卻無法創造利潤，正是因為該開發未能掌握「合法、實質可能、正當合理、財務可行」四項前提中的財務可行性，屬於未能掌握最有效使用原則之表現，此敘述適宜。"],"tr":"","core":["公園影響地價屬外部性，敘述適宜","公寓飆漲是供需等因素，非均衡原則","有行無市反映變動原則，敘述適宜","偏遠大廈未顧財務可行，敘述適宜"],"hl":[[],["均衡原則","市場供需或區域發展等因素所致"],[],[]]},{"id":"h:101-24","p":"h","src":"101年第24題","sec":"A1","stem":"如不動產其中某一條件發生改變，將造成整體不動產價格的提升，此種不動產估價原則稱之為：","opts":["供需原則","最有效使用原則","貢獻原則","均衡原則"],"ok":[2],"ex":["供需原則並非估價理論用來描述「某一條件改變使整體價格提升」之核心概念，供需原則著重市場供給需求對價格水準之影響。","最有效使用原則強調合法實質可能等四項前提下之最高利益使用，與單一條件改變致整體提升之概念不同。","貢獻原則依估價理論（教材）之定義，局部（某一條件）對整體（不動產）價值之貢獻，與題目所述「某一條件發生改變，將造成整體不動產價格的提升」完全相符。","均衡原則強調生產要素配置，並非單一條件改變對整體價格之貢獻效果。"],"tr":"","core":["供需原則講供需對價格水準影響","最有效使用講四前提最高利益使用","某一條件改變提升整體＝貢獻原則","均衡原則講生產要素配置"],"hl":[["供需原則","市場供給需求對價格水準之影響"],["最有效使用原則","合法實質可能等四項前提下之最高利益使用"],[],["均衡原則","生產要素配置"]]},{"id":"h:101-25","p":"h","src":"101年第25題","sec":"A1","stem":"進行不動產估價時，標的不動產如因捷運系統的開通，或鄰近公園的興闢，對其價格產生影響，所採行之不動產估價原則稱之為：","opts":["貢獻原則","外部性原則","收益分配原則","最有效使用原則"],"ok":[1],"ex":["貢獻原則強調局部（不動產本身內部之要素）對整體價值之貢獻，而捷運系統、公園是不動產「外部」之周邊環境設施，性質上屬外部性而非內部貢獻。","外部性原則依估價理論（教材）之定義，周邊環境設施（非標的本身）對價格之影響，捷運系統開通、鄰近公園興闢皆屬於標的外部之環境變化，與題目敘述完全相符。","收益分配原則指營運性不動產應扣除非屬不動產本身之收益，與外部設施對價格之影響無關。","最有效使用原則強調四項前提下之最高利益使用，與外部設施開通之影響無關。"],"tr":"","core":["捷運公園是外部設施，非內部貢獻","周邊設施影響價格＝外部性原則","收益分配講扣除非不動產收益","最有效使用與外部設施影響無關"],"hl":[["貢獻原則","局部（不動產本身內部之要素）對整體價值之貢獻"],[],["收益分配原則","營運性不動產應扣除非屬不動產本身之收益"],["最有效使用原則","四項前提下之最高利益使用"]]},{"id":"h:101-30","p":"h","src":"101年第30題","sec":"A1","stem":"進行不動產估價時，對營運性不動產淨收益，應扣除非屬於不動產所產生的其他淨收益，以免高估不動產本身所產生的淨收益，此估價原則稱之為：","opts":["適合原則","收益分配原則","外部性原則","最有效使用原則"],"ok":[1],"ex":["適合原則強調不動產與坐落環境之協調，與「扣除非屬不動產淨收益以免高估」此一收益計算概念無關。","技術規則第42條第2項：「前項淨收益為營運性不動產之淨收益者，應扣除不屬於不動產所產生之其他淨收益。」教材稱此為收益分配原則，與題目敘述完全相符。","外部性原則強調周邊環境設施對價格之影響，與收益扣除概念無關。","最有效使用原則與淨收益扣除非屬不動產部分之概念無關。"],"tr":"","core":["適合原則講環境協調，與收益扣除無關","營運性淨收益應扣除非不動產收益","外部性講周邊設施，與收益扣除無關","最有效使用與淨收益扣除無關"],"hl":[["適合原則","不動產與坐落環境之協調"],[],["外部性原則","周邊環境設施對價格之影響"],["最有效使用原則"]]},{"id":"h:101-34","p":"h","src":"101年第34題","sec":"A1","stem":"對房地結合所產生之超額利潤之歸屬，採土地貢獻說者，主要係基於下列何者？","opts":["土地經營管理之貢獻","土地區位特性之貢獻","土地取得成本之貢獻","土地開發投資之貢獻"],"ok":[1],"ex":["土地經營管理之貢獻側重後天人為經營行為，並非土地貢獻說所強調的核心要素。","土地貢獻說主張房地結合之超額利潤主要歸因於土地本身的區位特性（地段、稀缺性等先天條件），這正是土地貢獻說的核心論點。","土地取得成本之貢獻側重原始取得成本，並非土地貢獻說強調區位特性之核心論點。","土地開發投資之貢獻側重後天開發投入，並非土地貢獻說強調區位特性之核心論點。"],"tr":"","core":["經營管理是後天人為，非核心","土地貢獻說歸因於土地區位特性","取得成本非核心，核心是區位特性","開發投資是後天投入，非區位特性"],"hl":[["經營管理"],[],["取得成本"],["開發投資"]]},{"id":"h:102-4","p":"h","src":"102年第4題","sec":"A1","stem":"在不考慮時間、高風險或不便利等因素下，審慎的消費者不會支付高於財貨或勞務成本之代價，以取得一相同滿意度的替代性財貨或勞務。以上觀念是屬於何種估價原則？","opts":["競爭原則","供需原則","替代原則","預測原則"],"ok":[2],"ex":["競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「不支付高於相同滿意度替代財貨之代價」與超額利潤之競爭無關（屬替代原則），故非本題答案。","供需原則著重市場供給需求對價格水準之影響，與題目所述比較替代財貨代價之概念不同。","替代原則依估價理論（教材）之定義，審慎消費者不會支付高於相同滿意度替代財貨之代價，與題目敘述完全相符，是比較法、成本法、收益法三大方法之共同基礎。","預測（預期）原則強調對未來之預期影響現在價值，與題目所述「不考慮時間」之當下比較概念不符。"],"tr":"","core":["競爭原則講超額利潤，非比較替代","供需原則講供需，非比較替代財貨","不付高於同滿意度替代財之代價","預測原則講未來，題目不考慮時間"],"hl":[["競爭原則","屬替代原則"],["供需原則","市場供給需求對價格水準之影響"],[],["預測原則","對未來之預期影響現在價值"]]},{"id":"h:102-28","p":"h","src":"102年第28題","sec":"A1","stem":"有關不動產估價之最有效使用原則，下列敘述何者錯誤？","opts":["為消費者主觀效用之認知","具有良好意識及通常之使用能力者之認知","需以合法、實質可能、正當合理、財務可行為前提","得以獲致最高利益之使用"],"ok":[0],"ex":["技術規則第2條第17款：最有效使用指「客觀上具有良好意識及通常之使用能力者，在合法、實質可能、正當合理、財務可行前提下，所作得以獲致最高利益之使用」，判斷主體是客觀上之人，不是消費者主觀效用；本選項把客觀改成主觀，是錯誤敘述，即本題正解。","具有良好意識及通常之使用能力者之認知，是規則明定的正確要件，敘述正確。","需以合法、實質可能、正當合理、財務可行為前提，是規則明定的正確要件，敘述正確。","得以獲致最高利益之使用，是規則明定的正確要件，敘述正確。"],"tr":"","core":["判斷主體是客觀上之人，非主觀效用","良好意識及通常使用能力者為要件","合法等四項前提為明定要件","獲致最高利益之使用為明定要件"],"hl":[["消費者主觀效用","判斷主體是客觀上之人"],[],[],[]]},{"id":"h:103-8","p":"h","src":"103年第8題","sec":"A1","stem":"不動產估價，應切合何時之價值？","opts":["價格日期當時","交易日期當時","交換日期當時","登記日期當時"],"ok":[0],"ex":["技術規則第6條第1項明定：估價應切合價格日期當時之價值，與題目敘述完全相符，這是變動原則於估價程序中的具體落實。","交易日期是交易發生的時間點，並非估價應切合之價值基準時點。","交換日期並非技術規則規定之估價價值基準時點。","登記日期是辦理產權登記之日期，並非估價應切合之價值基準時點。"],"tr":"","core":["估價應切合價格日期當時之價值","交易日期非估價價值基準時點","交換日期非規定之價值基準時點","登記日期非估價價值基準時點"],"hl":[[],["交易日期"],["交換日期"],["登記日期"]]},{"id":"h:103-23","p":"h","src":"103年第23題","sec":"A1","stem":"依路線價法之基本原理，假設其他條件均相同，一宗土地愈接近街道部分，其價值：","opts":["愈低","不受接近街道之影響","愈高","不變"],"ok":[2],"ex":["路線價法基本原理為愈接近主要街道之土地，可及性與商業價值愈高，故價值應愈高而非愈低，本選項方向相反。","路線價法明確認為接近街道部分對價值有正向影響，並非不受影響，本選項與基本原理不符。","依路線價法基本原理，宗地愈接近街道，其交通可及性與使用便利性愈高，價值隨之愈高，與題目假設條件相符。","路線價法的核心精神正是反映接近街道程度造成的價值差異，並非價值不變。"],"tr":"","core":["方向相反，愈近街道價值愈高","接近街道對價值有正向影響","愈近街道可及性愈高，價值愈高","路線價正反映臨街程度之價值差異"],"hl":[["愈低","價值應愈高"],["不受接近街道之影響","對價值有正向影響"],[],["不變","反映接近街道程度造成的價值差異"]]},{"id":"h:103-26","p":"h","src":"103年第26題","sec":"A1","stem":"捷運於某不動產附近設站，該不動產價格因而提高，此屬於何種估價原則？","opts":["供需原則","競爭原則","替代原則","外部性原則"],"ok":[3],"ex":["供需原則著重市場整體供給需求對價格水準之影響，與捷運設站此一鄰近設施之具體影響不同。","競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「捷運設站使價格提高」與超額利潤之競爭無關（屬外部性原則），故非本題答案。","替代原則強調比較相同滿意度替代財貨之代價，與捷運設站之影響無直接關連。","外部性原則依估價理論（教材）之定義，周邊環境設施（捷運站）對價格之影響，捷運設站屬於不動產外部的交通建設改善，使周邊不動產價格提高，與外部性原則定義完全相符。"],"tr":"","core":["供需講整體供需，非鄰近設施影響","競爭原則講超額利潤，與設站無關","替代原則與捷運設站影響無關","捷運設站屬周邊設施＝外部性原則"],"hl":[["供需原則","市場整體供給需求對價格水準之影響"],["競爭原則","屬外部性原則"],["替代原則","比較相同滿意度替代財貨之代價"],[]]},{"id":"h:103-34","p":"h","src":"103年第34題","sec":"A1","stem":"老舊公寓外牆進行更新，該公寓之價格因此增加，此屬於何種估價原則？","opts":["供需原則","替代原則","貢獻原則","外部性原則"],"ok":[2],"ex":["供需原則著重市場整體供給需求，與單一建物外牆更新之內部改良無關。","替代原則著重比較相同滿意度替代財貨之代價，與外牆更新此一具體改良行為無直接關連。","貢獻原則依估價理論（教材）之定義，局部（外牆更新）對整體（公寓）價值之貢獻，外牆更新屬於建物本身內部改良，使整體價值因此提升，與貢獻原則定義相符。","外部性原則強調周邊環境設施（非標的本身）對價格之影響，外牆更新是針對建物本身的改良，並非周邊外部環境因素，性質不符。"],"tr":"","core":["供需講整體市場，與外牆更新無關","替代原則與外牆更新改良無關","外牆更新＝局部對整體價值之貢獻","外牆更新是建物本身改良，非外部"],"hl":[["供需原則","市場整體供給需求"],["替代原則","比較相同滿意度替代財貨之代價"],[],["外部性原則","周邊環境設施（非標的本身）對價格之影響"]]},{"id":"h:103-39","p":"h","src":"103年第39題","sec":"A1","stem":"下列對不動產市場之描述何者有誤？","opts":["產品異質性","人為干預多","為完全競爭市場","交易成本高"],"ok":[2],"ex":["不動產市場確實具有產品異質性高之特性（每筆不動產位置條件皆不同），此敘述正確，非本題答案（本題問「何者有誤」）。","不動產市場確實人為干預多（如政府土地使用管制、稅制政策等），此敘述正確。","不動產市場因產品異質性高、資訊不完全、交易成本高、人為干預多等特性，屬於非完全競爭市場，並非完全競爭市場，本選項描述有誤，即本題正解。","不動產市場交易成本確實偏高（如仲介費、稅費、登記規費等），此敘述正確。"],"tr":"","core":["不動產市場確具產品異質性","不動產市場確實人為干預多","不動產市場為非完全競爭市場","不動產市場交易成本確實偏高"],"hl":[[],[],["完全競爭市場","非完全競爭市場"],[]]},{"id":"h:104-3","p":"h","src":"104年第3題","sec":"A1","stem":"下列有關不動產市場與一般商品市場比較的敘述，何者正確？","opts":["一般商品市場交易成本低，不動產市場交易成本高","一般商品市場資訊不完全，不動產市場資訊極為完全","一般商品市場經常有人為干預，不動產市場完全沒有人為干預","一般商品市場為不完全競爭市場，不動產市場為完全競爭市場"],"ok":[0],"ex":["一般商品市場因標準化程度高、交易程序簡便，交易成本相對較低；不動產市場因產權複雜、稅費登記程序繁瑣，交易成本較高，與題目敘述相符。","一般商品市場通常資訊較為公開透明（如標準定價），不動產市場則因個別差異大而資訊不完全，本選項描述方向相反。","不動產市場同樣存在大量人為干預（如土地使用管制、稅制），並非完全沒有人為干預，本選項描述錯誤。","不動產市場因產品異質性高、進入門檻高等特性，屬於非完全競爭市場，而非完全競爭市場；一般商品市場視產業別而定，本選項描述與市場特性不符。"],"tr":"","core":["一般商品交易成本低，不動產高","方向相反，不動產市場資訊不完全","不動產市場同樣有大量人為干預","不動產市場是非完全競爭市場"],"hl":[[],["資訊極為完全","因個別差異大而資訊不完全"],["完全沒有人為干預","同樣存在大量人為干預"],["不動產市場為完全競爭市場","屬於非完全競爭市場"]]},{"id":"h:105-6","p":"h","src":"105年第6題","sec":"A1","stem":"不動產與其環境配合，以保持協調一致之利用，則其收益才能發揮最大化，例如在學校附近開設餐廳或書局等。此現象就不動產估價原則而言，是屬下列何者？","opts":["貢獻原則","均衡原則","供需原則","適合原則"],"ok":[3],"ex":["貢獻原則強調局部對整體價值之貢獻，與「不動產配合環境保持協調一致」此一定義不同。","均衡原則強調生產要素配置，與不動產配合周邊環境之協調無關。","供需原則著重市場整體供給需求，與不動產配合特定環境（學校附近）之適合度無關。","適合原則依估價理論（教材）之定義，不動產與其坐落環境達成協調一致以發揮收益最大化，學校附近開設餐廳或書局正是配合周邊機能而達成的適合運用，與題目敘述完全相符。"],"tr":"","core":["貢獻原則講局部貢獻，非環境協調","均衡原則講生產要素配置","供需原則與配合環境適合度無關","配合環境協調一致＝適合原則"],"hl":[["貢獻原則","局部對整體價值之貢獻"],["均衡原則","生產要素配置"],["供需原則","市場整體供給需求"],[]]},{"id":"h:105-8","p":"h","src":"105年第8題","sec":"A1","stem":"不動產估價常用之比較法、成本法與收益法，其評價基礎為何？","opts":["均衡原則","適合原則","替代原則","外部性原則"],"ok":[2],"ex":["均衡原則強調生產要素配置，並非比較法成本法收益法三大方法之共同評價基礎。","適合原則強調不動產與環境之協調，並非三大方法之共同基礎。","替代原則依估價理論（教材）之定義，審慎消費者不會支付高於相同滿意度替代財貨之代價，是比較法（交易觀點）、成本法（重置觀點）、收益法（投資觀點）三大估價方法之共同理論基礎。","外部性原則強調周邊環境對價格之影響，並非三大方法之共同評價基礎。"],"tr":"","core":["均衡原則非三大方法共同基礎","適合原則非三大方法共同基礎","替代原則是三大方法共同理論基礎","外部性原則非三大方法共同基礎"],"hl":[["均衡原則","生產要素配置"],["適合原則","不動產與環境之協調"],[],["外部性原則","周邊環境對價格之影響"]]},{"id":"h:105-10","p":"h","src":"105年第10題","sec":"A1","stem":"客觀淨收益之評估，應符合何種估價原則，以作為評估之基準？","opts":["最有效使用原則","替代原則","適合原則","外部性原則"],"ok":[0],"ex":["技術規則第33條第1項：「客觀淨收益應以勘估標的作最有效使用之客觀淨收益為基準，並參酌鄰近類似不動產在最有效使用情況下之收益推算之。」與題目所問相符。","替代原則是三大估價方法之共同基礎，並非客觀淨收益評估之直接基準原則。","適合原則強調不動產與環境之協調，並非客觀淨收益評估之基準。","外部性原則強調周邊環境對價格之影響，並非客觀淨收益評估之基準。"],"tr":"","core":["客觀淨收益以最有效使用為基準","替代原則是三大方法基礎，非此基準","適合原則非客觀淨收益評估基準","外部性原則非客觀淨收益評估基準"],"hl":[[],["替代原則","三大估價方法之共同基礎"],["適合原則","不動產與環境之協調"],["外部性原則","周邊環境對價格之影響"]]},{"id":"h:106-20","p":"h","src":"106年第20題","sec":"A1","stem":"不動產是一種異質的商品，因其下列何種之特徵而分割為許多地區性市場？","opts":["區位","高程","地形","地質"],"ok":[0],"ex":["不動產因其區位（位置）的不可移動性與唯一性，使其無法如一般商品般自由流通替代，因而分割為許多地區性市場，這是不動產異質性最核心的成因，與題目敘述相符。","高程（地勢高低）雖會影響個別不動產之條件，但並非造成「分割為許多地區性市場」此一現象的主要特徵。","地形同樣是影響個別不動產條件的因素之一，但非造成地區性市場分割之主要特徵。","地質屬於影響個別不動產條件的因素，但非造成地區性市場分割之主要特徵。"],"tr":"","core":["區位不可移動，分割為地區性市場","高程非地區性市場分割主因","地形非地區性市場分割主因","地質非地區性市場分割主因"],"hl":[[],["高程","影響個別不動產之條件"],["地形","影響個別不動產條件的因素之一"],["地質","影響個別不動產條件的因素"]]},{"id":"h:106-23","p":"h","src":"106年第23題","sec":"A1","stem":"不動產附近如有公園、圖書館、學校、歌劇院等建設，皆會對其價值產生影響，此種估價時需掌握的原則較適合被稱為：","opts":["供需原則","貢獻原則","外部性原則","社會成本原則"],"ok":[2],"ex":["供需原則著重市場整體供給需求，與周邊公共設施對價值之具體影響不同。","貢獻原則強調局部對整體價值之貢獻，但公園、圖書館等屬於不動產外部之公共設施，並非標的本身內部要素之貢獻。","外部性原則依估價理論（教材）之定義，周邊環境設施（非標的本身）對價格之影響，公園、圖書館、學校、歌劇院等周邊建設正是典型的外部性影響因素，與題目敘述相符。","「社會成本原則」不是估價理論（教材）所列的估價原則；公園、圖書館、學校等周邊設施影響不動產價值，教材歸入外部性原則，故非本題答案。"],"tr":"","core":["供需講整體供需，非周邊設施影響","公園等是外部設施，非內部貢獻","周邊公共設施影響價值＝外部性","社會成本原則非教材所列估價原則"],"hl":[["供需原則","市場整體供給需求"],["貢獻原則","局部對整體價值之貢獻"],[],["社會成本原則","教材歸入外部性原則"]]},{"id":"h:106-35","p":"h","src":"106年第35題","sec":"A1","stem":"有關不動產估價原則中之最有效使用原則，下列敘述何者錯誤？","opts":["具有良好意識及通常之使用能力者","在合法、實質可能、正當合理、財務可行前提下者","所作得以獲致最高利益之使用","係消費者主觀效用上"],"ok":[3],"ex":["具有良好意識及通常之使用能力者，是技術規則明定最有效使用原則的正確要件，敘述正確，非本題答案（本題問「何者錯誤」）。","在合法、實質可能、正當合理、財務可行前提下者，是規則明定的正確要件，敘述正確。","所作得以獲致最高利益之使用，是規則明定的正確要件，敘述正確。","技術規則第2條第17款：最有效使用指「客觀上具有良好意識及通常之使用能力者，在合法、實質可能、正當合理、財務可行前提下，所作得以獲致最高利益之使用」，判斷主體是客觀上之人，不是消費者主觀效用；本選項把客觀改成主觀，是錯誤敘述，即本題正解。"],"tr":"","core":["良好意識及通常使用能力者為要件","合法等四項前提為明定要件","獲致最高利益之使用為明定要件","判斷主體是客觀上之人，非主觀效用"],"hl":[[],[],[],["消費者主觀效用","判斷主體是客觀上之人"]]},{"id":"h:106-37","p":"h","src":"106年第37題","sec":"A1","stem":"在不考慮時間、高風險或不便利等因素下，審慎者不會支付高於財貨或勞務成本之代價，以取得一相同滿意度的替代性財貨或勞務。是指何種不動產價格形成原則？","opts":["預測原則","競爭原則","供需原則","替代原則"],"ok":[3],"ex":["預測（預期）原則強調對未來收益之預期，與題目所述「不考慮時間」之當下比較概念不符。","競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「不支付高於相同滿意度替代財貨之代價」與超額利潤之競爭無關（屬替代原則），故非本題答案。","供需原則著重市場整體供給需求，與題目所述比較替代財貨代價之概念不同。","替代原則依估價理論（教材）之定義，審慎者不會支付高於相同滿意度替代財貨之代價，與題目敘述完全相符。"],"tr":"","core":["預測講未來，題目不考慮時間","競爭原則講超額利潤，非比較替代","供需原則非比較替代財貨代價","不付高於同滿意度替代財之代價"],"hl":[["預測原則","對未來收益之預期"],["競爭原則","屬替代原則"],["供需原則","市場整體供給需求"],[]]},{"id":"h:107-14","p":"h","src":"107年第14題","sec":"A1","stem":"不動產估價報告書中載明價格日期，係立基於下列何種原則？","opts":["最有效使用原則","競爭原則","變動原則","預期原則"],"ok":[2],"ex":["最有效使用原則強調四項前提下之最高利益使用，與「載明價格日期」此一時點性記載無直接關連。","競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「報告書載明價格日期」與超額利潤之競爭無關（屬變動原則），故非本題答案。","變動原則依估價理論（教材）之定義，不動產價格隨時間變動，故估價報告書應載明價格日期（§16(3)；「有效期間」屬實務／範本用語，非§16條文），與題目敘述完全相符。","預期原則強調對未來之預期，與報告書載明價格日期此一基準時點記載之精神不同。"],"tr":"","core":["最有效使用與載明價格日期無關","競爭原則講超額利潤，與日期無關","價格隨時間變動，故載明價格日期","預期講對未來，非基準時點記載"],"hl":[["最有效使用原則","四項前提下之最高利益使用"],["競爭原則","屬變動原則"],[],["預期原則","對未來之預期"]]},{"id":"h:108-9","p":"h","src":"108年第9題","sec":"A1","stem":"勘估標的因位於垃圾掩埋場附近，造成其價格下降，此屬於何種原則？","opts":["替代原則","最有效原則","外部性原則","供需原則"],"ok":[2],"ex":["替代原則強調比較相同滿意度替代財貨之代價，與垃圾掩埋場此一周邊嫌惡設施之具體影響不同。","「最有效原則」即最有效使用原則（§2第17款），判斷的是合法、實質可能、正當合理、財務可行前提下的最高利益使用，與垃圾掩埋場這種周邊嫌惡設施對價格的影響無關，故非本題答案。","外部性原則依估價理論（教材）之定義，周邊環境設施（非標的本身）對價格之影響，垃圾掩埋場屬於典型的嫌惡設施，造成價格減損，與題目敘述完全相符。","供需原則著重市場整體供給需求，與垃圾掩埋場此一具體周邊設施之影響不同。"],"tr":"","core":["替代原則與嫌惡設施影響無關","最有效使用講最高利益，與嫌惡無關","掩埋場屬周邊嫌惡設施＝外部性","供需講整體供需，非周邊設施影響"],"hl":[["替代原則","比較相同滿意度替代財貨之代價"],["最有效原則","合法、實質可能、正當合理、財務可行前提下"],[],["供需原則","市場整體供給需求"]]},{"id":"h:109-13","p":"h","src":"109年第13題","sec":"A1","stem":"不動產市場是一動態的市場，對於估價的變動原則，下列敘述何者錯誤？","opts":["不動產估價應掌握影響價格的一般因素、區域因素與個別因素變動，以切合勘察日期當時之價值","影響不動產價格因素不斷變動，因此估價報告書應載明價格日期與勘察日期","運用成本法估價時，應分析使用建築材料隨時間變動的成本差異對不動產造成的價格影響","分析不動產價格景氣週期性變動，以利不動產價格變動趨勢之掌握"],"ok":[0],"ex":["技術規則第6條明定估價應切合「價格日期」當時之價值，本選項稱「以切合勘察日期當時之價值」，將價格日期誤植為勘察日期，二者定義不同（價格日期為價格基準日期，勘察日期為現場調查日期），此為錯誤敘述，即本題正解。","影響價格因素持續變動，故估價報告書應同時載明價格日期與勘察日期，此為正確敘述。","成本法估價時確實應分析建築材料隨時間變動之成本差異，此屬變動原則於成本法之具體應用，敘述正確。","分析不動產價格景氣週期性變動，以利掌握價格變動趨勢，正是變動原則之具體實踐，敘述正確。"],"tr":"","core":["應切合價格日期，非勘察日期","因素變動，故載明價格及勘察日期","成本法應分析建材成本隨時間變動","分析景氣週期以掌握價格變動趨勢"],"hl":[["勘察日期","估價應切合「價格日期」當時之價值"],[],[],[]]},{"id":"h:110-3","p":"h","src":"110年第3題","sec":"A1","stem":"不動產因鄰近殯儀館，造成價格之減損，此屬於何種原則？","opts":["競爭原則","供需原則","替代原則","外部性原則"],"ok":[3],"ex":["競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「鄰近殯儀館使價格減損」與超額利潤之競爭無關（屬外部性原則），故非本題答案。","供需原則著重市場整體供給需求，與殯儀館此一具體周邊嫌惡設施之影響不同。","替代原則強調比較相同滿意度替代財貨之代價，與殯儀館之影響無直接關連。","外部性原則依估價理論（教材）之定義，周邊環境設施（非標的本身）對價格之影響，殯儀館屬於典型的嫌惡設施，造成價格減損，與題目敘述相符。"],"tr":"","core":["競爭原則講超額利潤，與殯儀館無關","供需講整體供需，非周邊嫌惡設施","替代原則與殯儀館影響無關","殯儀館屬周邊嫌惡設施＝外部性"],"hl":[["競爭原則","屬外部性原則"],["供需原則","市場整體供給需求"],["替代原則","比較相同滿意度替代財貨之代價"],[]]},{"id":"h:110-4","p":"h","src":"110年第4題","sec":"A1","stem":"公寓因加裝電梯而價格提昇，此屬於何種不動產估價原則？","opts":["外部性原則","貢獻原則","替代原則","遞增原則"],"ok":[1],"ex":["外部性原則強調周邊環境設施（非標的本身）對價格之影響，但電梯是建物本身的內部改良設備，非外部周邊環境因素。","貢獻原則依估價理論（教材）之定義，局部（電梯設備）對整體（公寓）價值之貢獻，加裝電梯使整體價值提升，與題目敘述完全相符。","替代原則強調比較相同滿意度替代財貨之代價，與電梯設備加裝此一具體改良行為無直接關連。","「遞增原則」應是教材「收益遞增遞減原則」的片段：講追加投入時單位收益先遞增、超過某點後遞減，著重追加投資與收益增量的關係；本題加裝電梯是局部設備使整體價格提升，屬貢獻原則，故非本題答案。"],"tr":"","core":["電梯是內部改良，非外部環境","加裝電梯＝局部對整體價值之貢獻","替代原則與加裝電梯無關","遞增原則講追加投入收益，非貢獻"],"hl":[["外部性原則","周邊環境設施（非標的本身）對價格之影響"],[],["替代原則","比較相同滿意度替代財貨之代價"],["遞增原則","屬貢獻原則"]]},{"id":"h:111-5","p":"h","src":"111年第5題","sec":"A1","stem":"不動產估價技術規則對「最有效使用」原則有所定義，請問下列敘述何者錯誤？","opts":["得以獲致最高利益之使用","基於合法、實質可能前提","正當合理、財務可行前提下者","具有超凡意識及使用能力者"],"ok":[3],"ex":["得以獲致最高利益之使用，是技術規則明定最有效使用原則之正確要件，敘述正確，非本題答案（本題問「何者錯誤」）。","基於合法、實質可能前提，是規則明定四項前提中之兩項，敘述正確。","正當合理、財務可行前提下者，是規則明定四項前提中之另兩項，敘述正確。","技術規則明定最有效使用係「具有良好意識及通常之使用能力者」，並非「具有超凡意識及使用能力者」，「超凡」一詞誇大且非規則用語，此為錯誤敘述，即本題正解。"],"tr":"","core":["獲致最高利益之使用為明定要件","合法、實質可能為四前提中兩項","正當合理、財務可行為另兩項前提","應為良好意識通常能力，非超凡"],"hl":[[],[],[],["超凡","具有良好意識及通常之使用能力者"]]},{"id":"h:111-20","p":"h","src":"111年第20題","sec":"A1","stem":"某高鐵站周圍地區的新建住宅大樓平均成交價格，由三年前每坪35萬元上漲到現今每坪接近50萬元，此現象可以不動產估價中那一原則加以解釋？","opts":["變動原則","預期原則","貢獻原則","日期原則"],"ok":[0],"ex":["變動原則依估價理論（教材）之定義，不動產價格隨時間變動，題目描述高鐵站周圍住宅大樓成交價格從三年前每坪35萬元上漲至現今接近50萬元，正是價格隨時間經過而產生變動的具體現象，與變動原則完全相符。","預期（預測）原則強調周邊建設或未來發展之「預期」影響「當下」價值；但題目描述的是三年前到現今已實際發生的成交價格上漲，是價格隨時間真實變動的紀錄，不是預期尚未發生之未來收益。⚠️ 辨別重點：變動原則＝已發生的價格時間序列；預期原則＝現在反映對未來的預期。","貢獻原則強調局部對整體價值之貢獻，與題目所述整體市場價格隨時間上漲之現象無直接關連。","「日期原則」不是教材所列的估價原則名稱；價格隨時間經過而漲跌屬變動原則（技術規則要求註明價格日期，正是因應變動原則），故非本題答案。"],"tr":"","core":["價格隨時間實際變動＝變動原則","已發生的漲價，非對未來的預期","貢獻原則與整體市價上漲無關","日期原則非教材所列估價原則"],"hl":[[],["預期原則","價格隨時間真實變動的紀錄"],["貢獻原則","局部對整體價值之貢獻"],["日期原則","價格隨時間經過而漲跌屬變動原則"]]},{"id":"h:112-4","p":"h","src":"112年第4題","sec":"A1","stem":"收益性不動產價值是由現在至將來所能帶給權利人之利潤總計，估價師求取將來的收益據以評估不動產價值，應重視何種不動產估價原則？","opts":["期日原則","外部性原則","預測原則","內部性原則"],"ok":[2],"ex":["「期日原則」不是教材所列的估價原則名稱；本題著重求取將來收益以評估現在價值，屬預測原則，故非本題答案。","外部性原則強調周邊環境設施對價格之影響，與題目所述求取未來收益之概念不同。","預測（預期）原則（估價理論／教材）指不動產價值取決於權利人對未來收益之預期；題目稱收益性不動產價值為「現在至將來」所能帶給權利人之利潤總計，估價師據將來收益評估價值，正是預測原則之應用。","教材有「外部性原則」（周邊環境影響價格），但沒有與之相對的「內部性原則」；本題著重將來收益的預測，屬預測原則，故非本題答案。"],"tr":"","core":["期日原則非教材所列，本題屬預測","外部性講周邊設施，非求取未來收益","依將來收益評估價值＝預測原則","教材無內部性原則，本題屬預測"],"hl":[["期日原則","屬預測原則"],["外部性原則","周邊環境設施對價格之影響"],[],["內部性原則","屬預測原則"]]},{"id":"h:112-5","p":"h","src":"112年第5題","sec":"A1","stem":"老舊公寓因加裝電梯設備，價格也因此提升，此為何種不動產原則？","opts":["收益分配原則","貢獻原則","均衡原則","供需原則"],"ok":[1],"ex":["收益分配原則指營運性不動產應扣除非屬不動產本身之收益，與電梯設備加裝提升整體價值之概念不同。","貢獻原則依估價理論（教材）之定義，局部（電梯設備）對整體（公寓）價值之貢獻，加裝電梯使整體價值提升，與題目敘述完全相符。","均衡原則強調生產要素配置，與電梯設備加裝此一具體改良無關。","供需原則著重市場整體供給需求，與電梯設備加裝此一具體改良行為無關。"],"tr":"","core":["收益分配講扣除非不動產收益","加裝電梯＝局部對整體價值之貢獻","均衡原則講要素配置，與電梯無關","供需講整體供需，與電梯改良無關"],"hl":[["收益分配原則","營運性不動產應扣除非屬不動產本身之收益"],[],["均衡原則","生產要素配置"],["供需原則","市場整體供給需求"]]},{"id":"h:113-1","p":"h","src":"113年第1題","sec":"A1","stem":"不動產市場循環受到諸多經濟因素的影響，評估不動產價格時都訂有價格日期，依價格日期評估時必須掌握那項原則？","opts":["預測原則","變動原則","收益分配原則","外部性原則"],"ok":[1],"ex":["預測原則強調對未來收益之預期，與「依價格日期評估」此一基準時點性質不同。","變動原則依估價理論（教材）之定義，不動產價格隨時間變動，故估價應訂明價格日期，與題目所述「不動產市場循環受經濟因素影響，評估時都訂有價格日期」完全相符。","收益分配原則指扣除非屬不動產本身之收益，與價格日期之訂定無關。","外部性原則強調周邊環境設施對價格之影響，與價格日期之訂定無直接關連。"],"tr":"","core":["預測講未來預期，非價格日期基準","價格隨時間變動，故訂價格日期","收益分配與價格日期之訂定無關","外部性與價格日期之訂定無關"],"hl":[["預測原則","對未來收益之預期"],[],["收益分配原則","扣除非屬不動產本身之收益"],["外部性原則","周邊環境設施對價格之影響"]]},{"id":"h:113-2","p":"h","src":"113年第2題","sec":"A1","stem":"王小姐住家旁有一個高壓電塔，電塔周遭的房子不太容易售出，價格也比較低，不動產估價師評估該嫌惡設施對於房屋價格的影響是基於那一項原則？","opts":["適合原則","外部性原則","貢獻原則","競爭原則"],"ok":[1],"ex":["適合原則強調不動產與坐落環境之協調，與高壓電塔此一具體嫌惡設施之影響定義不同。","外部性原則依估價理論（教材）之定義，周邊環境設施（非標的本身）對價格之影響，高壓電塔屬於典型的嫌惡設施，造成周遭房屋不易售出且價格較低，與題目敘述完全相符。","貢獻原則強調局部對整體價值之貢獻（通常為正向提升），與高壓電塔造成價格減損之負向影響不符。","競爭原則（估價理論／教材）指超額利潤會吸引他人加入競爭，競爭使超額利潤逐漸減少以至消失；本題所述「高壓電塔使價格降低」與超額利潤之競爭無關（屬外部性原則），故非本題答案。"],"tr":"","core":["適合原則講環境協調，非嫌惡設施","高壓電塔屬周邊嫌惡設施＝外部性","貢獻多為正向提升，不符價格減損","競爭原則講超額利潤，與電塔無關"],"hl":[["適合原則","不動產與坐落環境之協調"],[],["貢獻原則","局部對整體價值之貢獻"],["競爭原則","屬外部性原則"]]},{"id":"h:113-4","p":"h","src":"113年第4題","sec":"A1","stem":"某預售建案因取得綠建築黃金級標章，每坪開價比附近未取得標章之建案貴，建商申請綠建築標章的行為是基於不動產估價之何種經濟原則？","opts":["最高最有效原則","貢獻原則","供需原則","外部性原則"],"ok":[1],"ex":["「最高最有效原則」就是最有效使用原則（技術規則§2第17款：合法、實質可能、正當合理、財務可行前提下獲致最高利益之使用），講的是選擇哪一種使用；本題是取得綠建築標章這個局部條件使整體開價提升，屬貢獻原則，故非本題答案。","貢獻原則依估價理論（教材）之定義，局部（綠建築標章認證）對整體（建案）價值之貢獻，建案因取得綠建築黃金級標章而使開價提升，正是貢獻原則之具體應用。","供需原則著重市場整體供給需求，與單一建案取得標章之具體改良行為無直接關連。","外部性原則強調周邊環境設施對價格之影響，但綠建築標章是建案本身的內部品質認證，非外部周邊環境因素，故非外部性原則。⚠️ 陷阱：貢獻原則=標的本身的改良→提升整體價值；外部性原則=周邊設施的存在→影響標的價格。"],"tr":"","core":["最有效使用講選擇使用，本題屬貢獻","綠建築標章＝局部對整體價值貢獻","供需講整體供需，非單一建案改良","標章是建案本身品質，非周邊設施"],"hl":[["最高最有效原則","屬貢獻原則"],[],["供需原則","市場整體供給需求"],["外部性原則","貢獻原則=標的本身的改良→提升整體價值"]]},{"id":"h:114-1","p":"h","src":"114年第1題","sec":"A1","stem":"鄰近國小的店舖，做販賣文具及圖書生意使用，此為何種不動產估價原則之掌握？","opts":["外部性原則","貢獻原則","適合原則","內部性原則"],"ok":[2],"ex":["外部性原則強調周邊環境設施對價格之影響，但題目描述店舖「自身」販賣文具圖書與鄰近國小機能之配合，屬於使用方式與環境之適合度判斷，非單純外部設施影響。","貢獻原則強調局部對整體價值之貢獻，與店舖配合鄰近國小販售特定商品之經營策略無直接關連。","適合原則依估價理論（教材）之定義，不動產與其坐落環境達成協調一致，鄰近國小開設文具圖書店舖，正是配合周邊機能（學生客群）而達成的適合運用，與題目敘述相符。","教材有「外部性原則」，但沒有「內部性原則」；店舖配合鄰近國小經營文具圖書，是不動產用途與周邊環境協調一致，屬適合原則，故非本題答案。"],"tr":"","core":["店舖配合周邊機能，非外部設施影響","貢獻原則與配合國小經營無關","配合周邊機能協調一致＝適合原則","教材無內部性原則，本題屬適合"],"hl":[["外部性原則","使用方式與環境之適合度判斷"],["貢獻原則","局部對整體價值之貢獻"],[],["內部性原則","屬適合原則"]]},{"id":"h:114-15","p":"h","src":"114年第15題","sec":"A1","stem":"下列各項原則中，何者最能說明畸零地價格偏高的現象？","opts":["預期原則","貢獻原則","適合原則","外部性原則"],"ok":[1],"ex":["預期原則強調對未來之預期，與「畸零地價格偏高」此一既有現況之價格現象不符。","貢獻原則：局部對整體價值之貢獻。畸零地（形狀不規則、難以單獨開發）本身利用價值低，但若鄰地需要整合它才能形成完整可開發地塊，畸零地的「貢獻」（對整合後整體地塊的增值貢獻）遠高於其本身單獨的市場價值，因此鄰地所有人願意溢價購買，造成畸零地價格偏高。","適合原則強調不動產與環境之協調，與畸零地價格偏高之現象無直接關連。","外部性原則強調周邊環境設施對價格之影響，與畸零地本身形狀造成之價格現象不同。"],"tr":"","core":["預期講未來，畸零地屬既有現象","畸零地對整合後整體貢獻高而溢價","適合原則與畸零地價格偏高無關","外部性講周邊設施，非畸零地形狀"],"hl":[["預期原則","對未來之預期"],[],["適合原則","不動產與環境之協調"],["外部性原則","周邊環境設施對價格之影響"]]},{"id":"h:99-25","p":"h","src":"99年第25題","sec":"A2","stem":"對都市邊緣未來有可能變更為建地之農地進行估價，其價格種類為何？","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[2],"ex":["正常價格須具備不受特定條件影響、經適當市場行銷形成之一般市場價值，農地以「未來可能變更為建地」此特定前提估價，已附加特定條件，不符正常價格定義。","限定價格係基於①權利與所有權合併②不動產合併③違反經濟合理性之分割三種限定條件之一形成，與「以未來可能變更用途之特定條件估價」之情境不符。","技術規則第2條第3款明定：特定價格係具市場性之不動產，基於特定條件下形成之價值。農地以「未來有可能變更為建地」此一特定條件進行估價，正是特定價格之典型情境。","特殊價格指對不具市場性之不動產所估計之價值，農地本身具有市場性，不適用特殊價格。"],"tr":"","core":["附加變更建地特定條件，非正常價格","限定價格限合併或分割三種情形","特定條件下形成之價值＝特定價格","農地具市場性，不適用特殊價格"],"hl":[["正常價格","不受特定條件影響"],["限定價格","三種限定條件之一形成"],[],["特殊價格","對不具市場性之不動產所估計之價值"]]},{"id":"h:100-9","p":"h","src":"100年第9題","sec":"A2","stem":"不動產估價之價格種類，包括下列那些？①一般價格　②正常價格　③限定價格　④特定價格　⑤特別價格","opts":["②③④","①②③④","①③④⑤","②③④⑤"],"ok":[0],"ex":["正確。§6：「其估計價格種類包括正常價格、限定價格、特定價格及特殊價格」。②正常、③限定、④特定都是法定種類；①「一般價格」、⑤「特別價格」都不是（法定的是「特殊價格」），故只選②③④。","多了①「一般價格」：法定價格種類只有正常、限定、特定、特殊四種（§6），沒有一般價格。","多了①「一般價格」與⑤「特別價格」（都不是 §6 所列種類），又漏了②正常價格。","多了⑤「特別價格」：法定的是「特殊價格」，指「對不具市場性之不動產所估計之價值」（§2④）。「特別」與「特殊」一字之差就是陷阱。"],"tr":"","core":["②③④屬法定，①一般⑤特別皆非","多了①一般價格，非法定種類","多了①⑤，又漏②正常價格","多了⑤，法定的是特殊不是特別"],"hl":[[],["沒有一般價格"],["漏了②正常價格"],["法定的是「特殊價格」"]]},{"id":"h:100-10","p":"h","src":"100年第10題","sec":"A2","stem":"下列何者屬於限定價格？①租賃權與租賃地合併之買賣　②企業資產重估　③違反經濟合理性之不動產分割買賣　④學校或公益使用之不動產估價","opts":["①③","①②③","①③④","①②③④"],"ok":[0],"ex":["①租賃權與租賃地合併之買賣（屬§2(2)第（一）目「以不動產所有權以外其他權利與所有權合併為目的」之情形，並非第（二）目之不動產合併）、③違反經濟合理性之不動產分割買賣（§2(2)第（三）目），皆屬技術規則第2條第2款明定之限定價格形成條件，組合正確。","②企業資產重估屬於會計處理目的之價值評估，並非技術規則所定義限定價格之形成條件（限定價格須基於合併或違反經濟合理性分割等特定情境）。","④學校或公益使用之不動產估價屬於使用目的之分類，並非限定價格之形成條件，限定價格強調「合併」或「分割」之交易情境而非使用目的。","②④皆非限定價格之形成條件，不應列入。"],"tr":"","core":["權利與所有權合併、不經濟分割＝限定","企業資產重估非限定價格形成條件","公益使用屬使用目的，非限定價格","②④皆非限定價格形成條件"],"hl":[[],["並非技術規則所定義限定價格之形成條件"],["並非限定價格之形成條件"],["皆非限定價格之形成條件"]]},{"id":"h:100-13","p":"h","src":"100年第13題","sec":"A2","stem":"雙併公寓同層打通之住宅，其市場出售價格應以何種價格評估？","opts":["正常價格","特定價格","限定價格","特殊價格"],"ok":[0],"ex":["雙併公寓同層打通後作為一般市場出售之住宅，其交易係在正常市場條件下進行，買賣雙方依專業知識謹慎行動，不受特定合併或分割前提之限制，屬於正常價格。","特定價格須基於特定條件（如預期變更）形成，本題並無此類特定前提，僅是物理空間打通後的一般市場出售。","限定價格須基於合併、分割等限定條件形成，本題打通後是作為一般住宅整體出售，並非以「合併」為目的之估價情境（合併已完成，現在是對打通後整體進行一般市場估價）。","特殊價格指不具市場性之不動產，本題仍具一般住宅市場性，不適用。"],"tr":"","core":["打通後一般市場出售屬正常價格","無預期變更等特定前提，非特定","合併已完成，非以合併為目的估價","仍具住宅市場性，非特殊價格"],"hl":[[],["特定價格","基於特定條件（如預期變更）形成"],["限定價格","基於合併、分割等限定條件形成"],["特殊價格","指不具市場性之不動產"]]},{"id":"h:101-11","p":"h","src":"101年第11題","sec":"A2","stem":"下例何者屬於具有市場性之價格？①正常價格　②限定價格　③特殊價格　④特定價格","opts":["①②","①②③","①②④","①②③④"],"ok":[2],"ex":["①②僅列正常與限定價格，遺漏④特定價格，特定價格同樣具有市場性。","①②③包含③特殊價格，但特殊價格定義為「不具市場性」之不動產所估計之價值，與「具有市場性」之題目要求矛盾，不應列入。","正常價格①、限定價格②、特定價格④三者依技術規則定義皆為「具市場性」之不動產所形成之價值，僅特殊價格③為不具市場性，故①②④為正確組合。","①②③④全選，但③特殊價格不具市場性，不應列入，組合錯誤。"],"tr":"","core":["遺漏④特定價格，它也具市場性","③特殊價格不具市場性","正常、限定、特定皆具市場性","③特殊價格不具市場性，不應列入"],"hl":[["①②","特定價格同樣具有市場性"],["特殊價格定義為「不具市場性」"],[],["特殊價格不具市場性"]]},{"id":"h:101-21","p":"h","src":"101年第21題","sec":"A2","stem":"以不動產所有權以外其他權利與所有權合併為目的，如地上權人向地主購買設定地上權之土地，評估該土地之價格稱之為：","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[1],"ex":["正常價格須為一般市場交易形成之價值，本題是地上權人向地主購買設定地上權之土地，屬於權利與所有權合併之特殊交易情境，非一般市場正常交易。","技術規則第2條第2款明定限定價格之第一種形成條件為「以不動產所有權以外其他權利與所有權合併為目的」，地上權人購買設定地上權之土地，正是地上權與土地所有權合併之典型情境，與題目敘述完全相符。","特定價格須基於特定條件（如預期變更）形成，本題是權利合併情境，非特定條件估價。","特殊價格指不具市場性之不動產，本題土地仍具市場性，不適用。"],"tr":"","core":["權利與所有權合併，非一般交易","地上權與所有權合併＝限定價格","權利合併情境，非特定條件估價","土地仍具市場性，非特殊價格"],"hl":[["正常價格","一般市場交易形成之價值"],[],["特定價格","基於特定條件（如預期變更）形成"],["特殊價格","指不具市場性之不動產"]]},{"id":"h:101-23","p":"h","src":"101年第23題","sec":"A2","stem":"甲公司於A市擁有商業區土地一宗，擬將其分割為兩筆土地，一筆做為辦公大樓使用，另一筆做為百貨公司使用，以符合商業區土地的經濟效益。今如就前述兩筆土地進行估價，則價格種類為下列何者？","opts":["正常價格","特殊價格","限定價格","特定價格"],"ok":[0],"ex":["甲公司將商業區土地分割為兩筆分別作辦公大樓與百貨公司使用，此分割係「為符合商業區土地之經濟效益」，並非違反經濟合理性之分割，反而是基於提升使用效益之合理分割，故仍應以正常價格估價（限定價格須以「違反經濟合理性之分割」為前提，本題分割合乎經濟效益，不符限定價格要件）。","特殊價格指不具市場性之不動產，本題土地具市場性，不適用。","限定價格須以「違反經濟合理性之分割」為前提形成，本題分割係為提升土地經濟效益而為，屬合理分割而非違反經濟合理性之分割，不符限定價格要件。","特定價格須基於特定條件（如預期用途變更）形成，本題並無此類特定前提，僅是依法定用途分割兩塊土地分別估價。"],"tr":"","core":["分割合乎經濟效益，仍屬正常價格","土地具市場性，非特殊價格","限定須違反經濟合理性之分割","無預期用途變更等特定前提"],"hl":[[],["特殊價格","指不具市場性之不動產"],["限定價格","須以「違反經濟合理性之分割」為前提形成"],["特定價格","基於特定條件（如預期用途變更）形成"]]},{"id":"h:102-2","p":"h","src":"102年第2題","sec":"A2","stem":"下列何者較接近不動產估價價格種類中之正常價格？","opts":["臺北市精華區標售國有土地價格","實價登錄之價格","奢侈稅經主管機關認定低報之銷售價格","土地徵收補償所查估之市價"],"ok":[3],"ex":["標售國有土地之價格可能受標售程序、底價設定等特殊因素影響，未必完全反映正常市場供需下之合理價值，較難視為典型正常價格代表。","實價登錄價格未經主管機關篩選排除特殊交易（親友間買賣、急售等），可能包含非正常交易情況，不宜直接視為正常價格代表。","奢侈稅低報之銷售價格屬刻意規避稅負之不實申報價格，明顯非正常市場交易價值。","土地徵收補償市價查估辦法第2條第1款：「市價：指市場正常交易價格。」與技術規則第2條第1款正常價格的意旨最接近，故為本題答案。"],"tr":"","core":["標售受程序底價影響，難為正常價格","實價登錄可能含特殊交易","低報價格是規避稅負的不實申報","徵收市價＝市場正常交易價格"],"hl":[["標售國有土地價格","未必完全反映正常市場供需下之合理價值"],["實價登錄之價格","可能包含非正常交易情況"],["經主管機關認定低報","刻意規避稅負之不實申報價格"],[]]},{"id":"h:102-3","p":"h","src":"102年第3題","sec":"A2","stem":"不動產估價應先確定價格種類，如估價師受託辦理釣魚台估價，你認為應屬於何種價格？","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[3],"ex":["釣魚台主權具有爭議性質，且不具一般市場交易性，無法以一般市場條件估算正常價格。","限定價格須基於合併或分割等特定交易情境形成，釣魚台估價並非此類交易情境。","特定價格須基於特定條件（如未來用途變更）形成，與釣魚台不具市場性之本質不符。","技術規則第2條第4款明定特殊價格係對不具市場性之不動產所估計之價值，釣魚台屬不具一般市場交易性質之特殊不動產，與總統府、孔廟、龜山島等同屬特殊價格之典型例子。"],"tr":"","core":["釣魚台不具市場交易性，非正常","非合併或分割交易情境","特定價格與不具市場性本質不符","不具市場性之不動產＝特殊價格"],"hl":[["正常價格","不具一般市場交易性"],["限定價格","基於合併或分割等特定交易情境形成"],["特定價格","基於特定條件（如未來用途變更）形成"],[]]},{"id":"h:103-27","p":"h","src":"103年第27題","sec":"A2","stem":"有一畸零地之地主擬購買鄰地合併開發，委託不動產估價師評估購買價格，此價格種類為何？","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[1],"ex":["畸零地地主擬購買鄰地合併開發，此交易係基於「不動產合併」之特定目的，並非一般市場正常交易，不適用正常價格。","技術規則第2條第2款明定限定價格之第二種形成條件為「以不動產合併為目的」，畸零地地主購買鄰地以合併開發，正是不動產合併目的之典型情境，與題目相符。","特定價格須基於特定條件（如預期用途變更）形成，本題是不動產合併情境，非特定條件估價。","特殊價格指不具市場性之不動產，畸零地與鄰地皆具市場性，不適用。"],"tr":"","core":["購鄰地合併屬特定目的，非正常交易","以不動產合併為目的＝限定價格","合併情境，非特定條件估價","畸零地與鄰地具市場性，非特殊"],"hl":[["正常價格","基於「不動產合併」之特定目的"],[],["特定價格","基於特定條件（如預期用途變更）形成"],["特殊價格","指不具市場性之不動產"]]},{"id":"h:105-2","p":"h","src":"105年第2題","sec":"A2","stem":"請問國內某大專院校擬購買鄰接學校之土地作為擴校之用，此以合併使用為目的之不動產買賣，係屬下列何種價格？","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[1],"ex":["大專院校以擴校為目的購買鄰接學校之土地，此交易係基於合併使用之特定目的，並非一般市場正常交易，不適用正常價格。","技術規則第2條第2款明定限定價格之第二種形成條件為「以不動產合併為目的」，大專院校購買鄰地以合併使用作擴校之用，正是不動產合併目的之典型情境，與題目相符。","特定價格須基於特定條件（如預期用途變更）形成，本題是合併使用情境，非特定條件估價。","特殊價格指不具市場性之不動產，學校與鄰接土地皆具市場性，不適用。"],"tr":"","core":["合併使用之特定目的，非正常交易","購鄰地合併擴校＝限定價格","合併使用情境，非特定條件估價","學校與鄰地具市場性，非特殊"],"hl":[["正常價格","基於合併使用之特定目的"],[],["特定價格","基於特定條件（如預期用途變更）形成"],["特殊價格","指不具市場性之不動產"]]},{"id":"h:105-3","p":"h","src":"105年第3題","sec":"A2","stem":"有關特殊價格的敘述，下列何者錯誤？","opts":["總統府的估價是屬特殊價格","無法以貨幣金額表示","指對不具市場性之不動產所估計之價值","宗教建築物的估價是屬特殊價格"],"ok":[1],"ex":["總統府屬於不具一般市場交易性之指標性建築，其估價確實屬於特殊價格之範疇，此敘述正確，非本題答案（本題問「何者錯誤」）。","技術規則第2條第4款明定特殊價格係對不具市場性之不動產「所估計之價值，並以貨幣金額表示者」，特殊價格仍須以貨幣金額表示，並非無法以貨幣金額表示，此為錯誤敘述，即本題正解。","「指對不具市場性之不動產所估計之價值」是技術規則明定之正確定義，敘述正確。","宗教建築物（如寺廟）通常不具一般市場交易性，其估價確實屬於特殊價格，此敘述正確。"],"tr":"","core":["總統府不具市場性，屬特殊價格","特殊價格仍須以貨幣金額表示","不具市場性之不動產所估價值","宗教建築不具市場性，屬特殊價格"],"hl":[[],["無法以貨幣金額表示","特殊價格仍須以貨幣金額表示"],[],[]]},{"id":"h:105-7","p":"h","src":"105年第7題","sec":"A2","stem":"依不動產估價技術規則之規定，評估何種價格種類時，應同時估計其正常價格？","opts":["限定價格","正常租金","限定租金","特定價格"],"ok":[3],"ex":["限定價格是因合併或分割等前提形成的價格；§6 後段只要求「特定價格」須同時估計正常價格，限定價格沒有此要求。","正常租金是對應正常價格之租賃合理價值概念，並非「應同時估計正常價格」之價格種類本身。","限定租金基於續訂租約或不動產合併形成，並非本題所問「同時估計正常價格」之價格種類。","§6 後段：以特定價格估價者，應敘明其估價條件，並同時估計其正常價格，與題目相符。"],"tr":"","core":["限定價格無須同時估計正常價格","正常租金非應同估正常價格之種類","限定租金非應同估正常價格之種類","特定價格應敘明條件並同估正常價格"],"hl":[["限定價格","只要求「特定價格」須同時估計正常價格"],["正常租金","對應正常價格之租賃合理價值概念"],["限定租金","基於續訂租約或不動產合併形成"],[]]},{"id":"h:105-12","p":"h","src":"105年第12題","sec":"A2","stem":"某塊素地為都市計畫工業區土地，若以其變更為住宅區的前提來估價，請問評估之價格種類為：","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[2],"ex":["正常價格反映一般市場正常交易情況下之價值，本題是以「變更為住宅區的前提」進行估價，已附加特定條件，不符正常價格定義。","限定價格須基於合併或分割等特定交易情境形成，本題是用途變更前提估價，非合併或分割情境。","技術規則第2條第3款明定特定價格係基於特定條件下形成之價值，工業區土地以「變更為住宅區」此一特定前提進行估價，正是特定價格之典型情境（與都市計畫變更相關的預期估價）。","特殊價格指不具市場性之不動產，工業區土地具市場性，不適用。"],"tr":"","core":["附加變更住宅區條件，非正常價格","用途變更前提，非合併或分割","以變更住宅區為前提＝特定價格","工業區土地具市場性，非特殊"],"hl":[["正常價格","反映一般市場正常交易情況下之價值"],["限定價格","基於合併或分割等特定交易情境形成"],[],["特殊價格","指不具市場性之不動產"]]},{"id":"h:106-1","p":"h","src":"106年第1題","sec":"A2","stem":"不動產估價應敘明價格種類，如估價師受託辦理太平島估價，您認為應屬於何種價格？","opts":["限定價格","正常價格","特定價格","特殊價格"],"ok":[3],"ex":["限定價格須基於合併或分割等特定交易情境形成，太平島估價並非此類交易情境。","正常價格須反映一般市場正常交易情況，太平島具有特殊地理及主權性質，不具一般市場交易性，不適用正常價格。","特定價格須基於特定條件（如未來用途變更）形成，與太平島不具市場性之本質不符。","技術規則第2條第4款明定特殊價格係對不具市場性之不動產所估計之價值，太平島與釣魚台、龜山島、東沙島等同屬不具一般市場交易性質之特殊不動產，屬特殊價格。"],"tr":"","core":["非合併或分割交易情境","太平島不具市場交易性，非正常","特定價格與不具市場性本質不符","不具市場性之不動產＝特殊價格"],"hl":[["限定價格","基於合併或分割等特定交易情境形成"],["正常價格","不具一般市場交易性"],["特定價格","基於特定條件（如未來用途變更）形成"],[]]},{"id":"h:106-2","p":"h","src":"106年第2題","sec":"A2","stem":"下列何種情況，可歸類於不動產估價價格種類中之正常價格？","opts":["實價登錄經主管機關篩選之價格","臺北市精華區標售國有土地價格","土地徵收補償所查估之市價","實價課稅經主管機關認定低報之價格"],"ok":[2],"ex":["實價登錄價格若僅是「經主管機關篩選」，未必完全排除特殊交易因素，未必能直接視為正常價格的典型代表。","標售國有土地之價格可能受標售程序、底價設定等特殊機制影響，未必完全反映正常市場供需下之合理價值。","土地徵收補償市價查估辦法第2條第1款：「市價：指市場正常交易價格。」與技術規則第2條第1款正常價格的意旨最接近，故為本題答案。","實價課稅經主管機關認定低報之價格，屬刻意規避稅負之不實申報價格，明顯非正常市場交易價值。"],"tr":"","core":["僅經篩選未必排除特殊交易","標售受程序底價影響，非典型正常","徵收市價＝市場正常交易價格","低報價格是規避稅負的不實申報"],"hl":[["經主管機關篩選","未必完全排除特殊交易因素"],["標售國有土地價格","未必完全反映正常市場供需下之合理價值"],[],["低報之價格","刻意規避稅負之不實申報價格"]]},{"id":"h:107-16","p":"h","src":"107年第16題","sec":"A2","stem":"勘估標的是一都市邊緣之農地，未來極有可能變更為建地，今依委託人要求針對勘估標的未來可能變更為建地情況進行估價，其價格種類為何？","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[2],"ex":["正常價格反映一般市場正常交易情況下之價值，本題依委託人要求以「未來可能變更為建地情況」進行估價，已附加特定條件，不符正常價格定義。","限定價格須基於合併或分割等特定交易情境形成，本題是用途變更前提估價，非合併或分割情境。","技術規則第2條第3款明定特定價格係基於特定條件下形成之價值，都市邊緣農地以「未來極有可能變更為建地」此一特定前提進行估價，正是特定價格之典型情境。","特殊價格指不具市場性之不動產，農地具市場性，不適用。"],"tr":"","core":["附加變更建地條件，非正常價格","用途變更前提，非合併或分割","以變更建地為前提估價＝特定價格","農地具市場性，非特殊價格"],"hl":[["正常價格","反映一般市場正常交易情況下之價值"],["限定價格","基於合併或分割等特定交易情境形成"],[],["特殊價格","指不具市場性之不動產"]]},{"id":"h:108-1","p":"h","src":"108年第1題","sec":"A2","stem":"甲君擬購買相鄰兩塊土地合併建築，請問在此目的下所評估出的價值，以貨幣金額表示者，稱為：","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[1],"ex":["正常價格反映一般市場正常交易情況下之價值，本題是以「合併建築」為目的之估價，已附加特定合併條件，不符正常價格定義。","技術規則第2條第2款明定限定價格之第二種形成條件為「以不動產合併為目的」，甲君擬購買相鄰兩塊土地合併建築，正是不動產合併目的之典型情境，與題目相符。","特定價格須基於特定條件（如預期用途變更）形成，本題是合併目的情境，非特定條件估價。","特殊價格指不具市場性之不動產，本題土地具市場性，不適用。"],"tr":"","core":["以合併建築為目的，非正常價格","購相鄰土地合併建築＝限定價格","合併目的情境，非特定條件估價","土地具市場性，非特殊價格"],"hl":[["正常價格","反映一般市場正常交易情況下之價值"],[],["特定價格","基於特定條件（如預期用途變更）形成"],["特殊價格","指不具市場性之不動產"]]},{"id":"h:108-24","p":"h","src":"108年第24題","sec":"A2","stem":"對具有市場性之不動產，以違反經濟合理性之不動產分割為前提，查估其所形成之價值，並以貨幣金額表示者，屬下列那一種價格？","opts":["特殊價格","特定價格","正常價格","限定價格"],"ok":[3],"ex":["特殊價格指對「不具市場性」之不動產所估計之價值，本題標的具有市場性，不適用特殊價格。","特定價格須基於特定條件（如未來用途變更）形成，本題是分割情境，非特定條件估價。","正常價格反映一般市場正常交易情況下之價值，本題以「違反經濟合理性之分割」為前提估價，已偏離正常交易情況，不符正常價格定義。","技術規則第2條第2款明定限定價格之第三種形成條件為「以違反經濟合理性之不動產分割為前提」，與題目敘述完全相符。"],"tr":"","core":["標的具市場性，非特殊價格","分割情境，非特定條件估價","違反經濟合理性分割，非正常交易","違反經濟合理性之分割＝限定價格"],"hl":[["特殊價格","對「不具市場性」之不動產所估計之價值"],["特定價格","基於特定條件（如未來用途變更）形成"],["正常價格","反映一般市場正常交易情況下之價值"],[]]},{"id":"h:108-25","p":"h","src":"108年第25題","sec":"A2","stem":"下列敘述何者為正確？","opts":["具有市場性之不動產，以不動產所有權以外其他權利與所有權合併為目的，查估其所形成之價值，並以貨幣金額表示者，屬「限定價格」","具有市場性之不動產，基於特定條件下形成之價值，並以貨幣金額表示者，為「特殊價格」","對不具市場性之不動產所估計之價值，並以貨幣金額表示者，為「特定價格」","對不具市場性之不動產，以不動產合併為目的，查估其所形成之價值，並以貨幣金額表示者，屬「限定價格」"],"ok":[0],"ex":["技術規則第2條第2款明定限定價格之第一種形成條件為「以不動產所有權以外其他權利與所有權合併為目的」，與本選項描述完全相符，為正確敘述。","特定價格（而非特殊價格）才是「基於特定條件下形成之價值」，本選項將特定價格之定義誤植為特殊價格，敘述錯誤。","特殊價格才是「對不具市場性之不動產所估計之價值」，本選項將特殊價格之定義誤植為特定價格，敘述錯誤。","限定價格須是「具有市場性」之不動產，本選項描述「對不具市場性之不動產，以不動產合併為目的」，將具市場性與不具市場性的前提混淆，且不具市場性之不動產合併估價應屬特殊價格範疇，敘述錯誤。"],"tr":"","core":["權利與所有權合併為目的＝限定價格","特定條件形成者是特定，非特殊","不具市場性者是特殊，非特定","限定價格須具市場性，混淆前提"],"hl":[[],["特殊價格","特定價格（而非特殊價格）"],["特定價格","特殊價格才是「對不具市場性之不動產"],["對不具市場性之不動產","限定價格須是「具有市場性」之不動產"]]},{"id":"h:109-12","p":"h","src":"109年第12題","sec":"A2","stem":"正常價格的定義中，不包含下列那一要件？","opts":["形成正常價格的不動產具備市場性","係為有意願的買賣雙方，依專業知識分析與謹慎行動的交易","有意願之買賣雙方不受債權債務關係或親友關係人等等壓力或脅迫","經適當市場行銷及交易雙方條件形成之價值"],"ok":[3],"ex":["正常價格定義要件之一為「形成正常價格的不動產具備市場性」，這是正確要件，非本題答案（本題問「不包含」哪一要件）。","「係為有意願的買賣雙方，依專業知識分析與謹慎行動的交易」是技術規則第2條第1款正常價格定義的正確要件之一。","§2(1)正常價格之定義為「不受任何脅迫，經適當市場行銷及正常交易條件形成之合理價值」；「債權債務關係或親友關係人」之壓力屬§23第3、4款（不得採用之交易情況），不在§2(1)條文用語內，但其「不受壓力或脅迫」之意旨與定義一致，故本選項視為正確要件（非本題答案）。","正常價格定義要求「經適當市場行銷及『正常交易條件』形成之價值」，本選項稱「交易雙方條件形成之價值」，缺少§2(1)明定之「正常交易條件」此一要件，為定義中表述不符之選項，即本題正解。"],"tr":"","core":["具備市場性屬正常價格要件","有意願雙方謹慎交易屬定義要件","不受壓力脅迫合乎定義意旨","缺正常交易條件，與定義不符"],"hl":[[],[],[],["交易雙方條件","正常交易條件"]]},{"id":"h:109-24","p":"h","src":"109年第24題","sec":"A2","stem":"依據不動產估價技術規則規定，不動產估價應敘明價格種類，請問辦理東沙島估價，此屬於何種價格？","opts":["正常價格","特殊價格","限定價格","特定價格"],"ok":[1],"ex":["正常價格須反映一般市場正常交易情況，東沙島具特殊地理及主權性質，不具一般市場交易性，不適用正常價格。","技術規則第2條第4款明定特殊價格係對不具市場性之不動產所估計之價值，東沙島與釣魚台、太平島、龜山島等同屬不具一般市場交易性質之特殊不動產，屬特殊價格。","限定價格須基於合併或分割等特定交易情境形成，東沙島估價並非此類交易情境。","特定價格須基於特定條件（如未來用途變更）形成，與東沙島不具市場性之本質不符。"],"tr":"","core":["東沙島不具市場交易性，非正常","不具市場性之不動產＝特殊價格","非合併或分割交易情境","特定價格與不具市場性本質不符"],"hl":[["正常價格","不具一般市場交易性"],[],["限定價格","基於合併或分割等特定交易情境形成"],["特定價格","基於特定條件（如未來用途變更）形成"]]},{"id":"h:110-7","p":"h","src":"110年第7題","sec":"A2","stem":"對不具市場性之不動產所估計之價值，並以貨幣金額表示者，為何種價格？","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[3],"ex":["正常價格須具備市場性並反映一般市場正常交易情況，與「不具市場性」之前提矛盾。","限定價格須是「具有市場性」之不動產基於合併分割等條件形成，與「不具市場性」之前提矛盾。","特定價格須是「具有市場性」之不動產基於特定條件形成，與「不具市場性」之前提矛盾。","技術規則第2條第4款明定特殊價格係對不具市場性之不動產所估計之價值，並以貨幣金額表示者，與題目敘述完全相符。"],"tr":"","core":["正常價格須具市場性","限定價格須具市場性","特定價格須具市場性","不具市場性之不動產＝特殊價格"],"hl":[["正常價格","須具備市場性並反映一般市場正常交易情況"],["限定價格","須是「具有市場性」之不動產"],["特定價格","須是「具有市場性」之不動產"],[]]},{"id":"h:110-16","p":"h","src":"110年第16題","sec":"A2","stem":"土地承租人欲購買所承租土地供未來繼續使用，委託不動產估價師進行估價，其價格種類為何？","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[1],"ex":["正常價格反映一般市場正常交易情況下之價值，本題承租人購買所承租土地供繼續使用，屬於權利與所有權合併之特殊情境，非一般市場正常交易。","技術規則第2條第2款明定限定價格之第一種形成條件為「以不動產所有權以外其他權利與所有權合併為目的」，土地承租人（具租賃權）欲購買所承租土地（取得所有權），正是租賃權與所有權合併之典型情境，與題目敘述相符。","特定價格須基於特定條件（如預期用途變更）形成，本題是權利合併情境，非特定條件估價。","特殊價格指不具市場性之不動產，本題土地具市場性，不適用。"],"tr":"","core":["權利合併情境，非一般正常交易","租賃權與所有權合併＝限定價格","權利合併情境，非特定條件估價","土地具市場性，非特殊價格"],"hl":[["正常價格","屬於權利與所有權合併之特殊情境"],[],["特定價格","基於特定條件（如預期用途變更）形成"],["特殊價格","指不具市場性之不動產"]]},{"id":"h:111-2","p":"h","src":"111年第2題","sec":"A2","stem":"不動產估價應敘明價格種類，當不動產估價師受託辦理龜山島估價，您認為應屬於何種價格種類？","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[3],"ex":["正常價格須反映一般市場正常交易情況，龜山島具特殊地理性質，不具一般市場交易性，不適用正常價格。","限定價格須基於合併或分割等特定交易情境形成，龜山島估價並非此類交易情境。","特定價格須基於特定條件（如未來用途變更）形成，與龜山島不具市場性之本質不符。","技術規則第2條第4款明定特殊價格係對不具市場性之不動產所估計之價值，龜山島與釣魚台、太平島、東沙島等同屬不具一般市場交易性質之特殊不動產，屬特殊價格。"],"tr":"","core":["龜山島不具市場交易性，非正常","非合併或分割交易情境","特定價格與不具市場性本質不符","不具市場性之不動產＝特殊價格"],"hl":[["正常價格","不具一般市場交易性"],["限定價格","基於合併或分割等特定交易情境形成"],["特定價格","基於特定條件（如未來用途變更）形成"],[]]},{"id":"h:111-12","p":"h","src":"111年第12題","sec":"A2","stem":"不動產估價之限定價格指具有市場性之不動產，在下列限定條件之一所形成之價值，並以貨幣金額表示者。請問下列何者非屬限定條件？","opts":["以不動產所有權以外其他權利與所有權合併為目的","以不動產合併為目的","以違反經濟合理性之不動產分割為前提","經適當市場行銷及正常交易條件形成"],"ok":[3],"ex":["「以不動產所有權以外其他權利與所有權合併為目的」是技術規則第2條第2款明定的限定條件之一，非本題答案（本題問「非屬」哪一限定條件）。","「以不動產合併為目的」同樣是規則明定的限定條件之一。","「以違反經濟合理性之不動產分割為前提」同樣是規則明定的限定條件之一。","「經適當市場行銷及正常交易條件形成」是正常價格的定義要件，並非限定價格的限定條件；限定價格恰好是「在限定條件下」形成，與正常市場行銷交易條件形成之概念相反，本選項非屬限定條件，即本題正解。"],"tr":"","core":["權利與所有權合併屬限定條件","不動產合併屬限定條件","違反經濟合理性分割屬限定條件","此為正常價格要件，非限定條件"],"hl":[[],[],[],["經適當市場行銷及正常交易條件形成","正常價格的定義要件"]]},{"id":"h:111-13","p":"h","src":"111年第13題","sec":"A2","stem":"不動產估價，應註明其價格種類；以何種價格估價時應敘明其估價條件，並同時估計其正常價格？","opts":["限定價格","特殊價格","特定價格","特別價格"],"ok":[2],"ex":["限定價格是§2所定三種限定條件（權利合併、不動產合併、違反經濟合理性分割）形成之價值，§6 後段並未要求同時估計正常價格。","特殊價格指不具市場性不動產之估價，不涉及「敘明估價條件並同時估計正常價格」之要求。","技術規則第6條後段明定：「其以特定價格估價者，應敘明其估價條件，並同時估計其正常價格。」（第2條第3款只定義特定價格為「基於特定條件下形成之價值」），與題目敘述完全相符。","「特別價格」並非技術規則明定之正式價格種類名稱，技術規則僅定義正常、限定、特定、特殊四種價格。"],"tr":"","core":["限定價格無須同時估計正常價格","特殊價格不涉同估正常價格要求","特定價格應敘明條件並同估正常價格","特別價格非法定價格種類"],"hl":[["限定價格","§2所定三種限定條件"],["特殊價格","不具市場性不動產之估價"],[],["特別價格","技術規則僅定義正常、限定、特定、特殊四種價格"]]},{"id":"h:111-22","p":"h","src":"111年第22題","sec":"A2","stem":"科學園區附近的農業用地，未來可能變更為建地，土地所有權人要求估價人員針對其農地未來可能變更為建地情況進行估價，請問該筆土地的價格屬於何種類？","opts":["正常價格","特定價格","限定價格","特殊價格"],"ok":[1],"ex":["正常價格反映一般市場正常交易情況下之價值，本題是依土地所有權人要求以「未來可能變更為建地情況」進行估價，已附加特定條件，不符正常價格定義。","技術規則第2條第3款明定特定價格係基於特定條件下形成之價值，科學園區附近農地以「未來可能變更為建地」此一特定前提進行估價，正是特定價格之典型情境。","限定價格須基於合併或分割等特定交易情境形成，本題是用途變更前提估價，非合併或分割情境。","特殊價格指不具市場性之不動產，農地具市場性，不適用。"],"tr":"","core":["附加變更建地條件，非正常價格","以變更建地為前提估價＝特定價格","用途變更前提，非合併或分割","農地具市場性，非特殊價格"],"hl":[["正常價格","反映一般市場正常交易情況下之價值"],[],["限定價格","基於合併或分割等特定交易情境形成"],["特殊價格","指不具市場性之不動產"]]},{"id":"h:112-2","p":"h","src":"112年第2題","sec":"A2","stem":"不動產估價師受託評估總統府價值，此屬於何種價格種類？","opts":["申報價格","特殊價格","特定價格","限定價格"],"ok":[1],"ex":["「申報價格」並非技術規則明定之正式價格種類，屬於混淆選項。","技術規則第2條第4款明定特殊價格係對不具市場性之不動產所估計之價值，總統府屬於指標性公有建築，不具一般市場交易性，與孔廟、媽祖廟等同屬特殊價格之典型例子。","特定價格須基於特定條件（如未來用途變更）形成，與總統府不具市場性之本質不符。","限定價格須基於合併或分割等特定交易情境形成，總統府估價並非此類交易情境。"],"tr":"","core":["申報價格非法定價格種類","總統府不具市場性＝特殊價格","特定價格與不具市場性本質不符","非合併或分割交易情境"],"hl":[["申報價格"],[],["特定價格","基於特定條件（如未來用途變更）形成"],["限定價格","基於合併或分割等特定交易情境形成"]]},{"id":"h:113-17","p":"h","src":"113年第17題","sec":"A2","stem":"下列那種情況評估的是特殊價格？","opts":["估價師受託辦理評估因都市計畫將公園變更為住宅用地之土地價格","估價師受託辦理評估以土地租賃權與租賃地合併為目的之價格","估價師受託辦理評估大甲鎮瀾宮的價格","估價師受託辦理評估都市邊緣未來可能變更為建地的農地價格"],"ok":[2],"ex":["都市計畫將公園變更為住宅用地之土地價格，是基於「特定條件」（都市計畫變更）形成之價值，屬於特定價格而非特殊價格。","土地租賃權與租賃地合併為目的之價格，是「權利與所有權合併」之情境，屬於限定價格而非特殊價格。","大甲鎮瀾宮是著名宗教建築物，與孔廟、媽祖廟同屬不具一般市場交易性之指標性建築，依技術規則第2條第4款屬於特殊價格，與題目敘述相符。","都市邊緣未來可能變更為建地的農地價格，是基於「特定條件」（未來變更）形成之價值，屬於特定價格而非特殊價格。"],"tr":"","core":["公園變更住宅屬特定條件＝特定價格","租賃權與租賃地合併＝限定價格","宗教建築不具市場性＝特殊價格","農地預期變更建地＝特定價格"],"hl":[["公園變更為住宅用地","屬於特定價格"],["租賃權與租賃地合併","屬於限定價格"],[],["未來可能變更為建地","屬於特定價格"]]},{"id":"h:114-16","p":"h","src":"114年第16題","sec":"A2","stem":"評估臺南孔廟的現值，依不動產估價技術規則之規定，其價格種類為下列何者？","opts":["正常價格","限定價格","特定價格","特殊價格"],"ok":[3],"ex":["正常價格須反映一般市場正常交易情況，孔廟具特殊宗教文化性質，不具一般市場交易性，不適用正常價格。","限定價格須基於合併或分割等特定交易情境形成，孔廟估價並非此類交易情境。","特定價格須基於特定條件（如未來用途變更）形成，與孔廟不具市場性之本質不符。","技術規則第2條第4款明定特殊價格係對不具市場性之不動產所估計之價值，臺南孔廟屬於著名宗教文化古蹟，不具一般市場交易性，與總統府、媽祖廟等同屬特殊價格之典型例子。"],"tr":"","core":["孔廟不具市場交易性，非正常","非合併或分割交易情境","特定價格與不具市場性本質不符","不具市場性之不動產＝特殊價格"],"hl":[["正常價格","不具一般市場交易性"],["限定價格","基於合併或分割等特定交易情境形成"],["特定價格","基於特定條件（如未來用途變更）形成"],[]]},{"id":"h:99-4","p":"h","src":"99年第4題","sec":"A3","stem":"直轄市或縣市政府對轄區內之土地，應經常調查其地價動態，繪製地價區段圖並估計區段地價，提經地價評議委員會評議之後，於每年1月1日公告，此乃何種價格？","opts":["公告現值","公告地價","拍賣地價","收購地價"],"ok":[0],"ex":["這才是正解。題幹整段就是平均地權條例§46的文字：「直轄市或縣（市）政府對於轄區內之土地，應經常調查其地價動態，繪製地價區段圖並估計區段地價後，提經地價評議委員會評定，據以編製土地現值表於每年一月一日公告」。決定性的兩個詞是「經常調查」與「每年1月1日」，兩個都只出現在§46。","不是公告地價。公告地價的法源是§15（規定地價、重新規定地價）：分區調查最近一年之買賣價格或收益價格 → 劃分地價區段並估計區段地價後提交地價評議委員會評議 → 計算宗地單位地價 → 公告及申報地價，期限30日，而且是每2年重新規定一次（§14）。§15 沒有「經常調查」，也沒有「每年1月1日」。兩條都有「地價區段」與「地價評議委員會」，差別全在調查頻率與公告日期。","拍賣地價是法院拍賣程序中決定之價格，與政府例行性地價動態調查公告無關。","收購地價是政府收購土地時議定之價格，與例行性地價動態調查公告程序不同。"],"tr":"","core":["經常調查、每年1月1日公告＝公告現值","公告地價每2年規定，無每年1月1日","拍賣地價是法院拍賣所定價格","收購地價是政府收購時議定價格"],"hl":[[],["公告地價","每2年"],["拍賣地價","法院拍賣程序中決定之價格"],["收購地價","政府收購土地時議定之價格"]]},{"id":"h:99-22","p":"h","src":"99年第22題","sec":"A3","stem":"請問對於不動產估價而言，兩岸簽訂ＥＣＦＡ屬於何種因素？","opts":["一般因素","區域因素","個別因素","特定因素"],"ok":[0],"ex":["ECFA（兩岸經濟合作架構協議）屬於全國性、整體經濟政策層面之協議，影響範圍涵蓋全國不動產市場，符合一般因素「對於不動產市場及其價格水準發生全面影響之自然、政治、社會、經濟等共同因素」之定義。","區域因素指影響近鄰地區不動產價格水準之因素，ECFA為全國性政策，非侷限於特定近鄰地區之影響。","個別因素指不動產本身條件所產生之價格差異因素，與ECFA此一總體經濟政策無關。","「特定因素」並非技術規則第2條明定之獨立因素分類名稱，技術規則僅分一般、區域、個別三層次因素。"],"tr":"","core":["ECFA是全國性共同因素＝一般因素","區域因素限近鄰地區，ECFA屬全國","個別因素講標的本身條件","特定因素非法定因素分類"],"hl":[[],["區域因素","ECFA為全國性政策"],["個別因素","個別因素指不動產本身條件所產生之價格差異因素"],["特定因素","技術規則僅分一般、區域、個別三層次因素"]]},{"id":"h:99-23","p":"h","src":"99年第23題","sec":"A3","stem":"下列不動產價格影響因素中何者屬於個別因素？","opts":["興建焚化爐","捷運站規劃","臨街寬度","設置加油站"],"ok":[2],"ex":["興建焚化爐屬於影響特定區域內不動產價格水準之公共設施規劃，性質上是影響近鄰地區之區域因素，非個別因素。","捷運站規劃同樣是影響周邊近鄰地區不動產價格水準之區域因素，非個別因素。","技術規則第2條第16款明定個別因素係不動產本身條件所產生之價格差異因素，「臨街寬度」是勘估標的本身臨接道路的具體寬度條件，屬於標的自身特性，符合個別因素定義。","設置加油站屬於影響周邊區域不動產價格水準之鄰避設施規劃，性質上是區域因素，非個別因素。"],"tr":"","core":["焚化爐影響近鄰地區，屬區域因素","捷運站規劃屬區域因素","臨街寬度是標的本身條件＝個別","加油站影響周邊區域，屬區域因素"],"hl":[["興建焚化爐","影響近鄰地區之區域因素"],["捷運站規劃","影響周邊近鄰地區不動產價格水準之區域因素"],[],["設置加油站","鄰避設施規劃，性質上是區域因素"]]},{"id":"h:99-27","p":"h","src":"99年第27題","sec":"A3","stem":"比較標的與勘估標的間能成立替代關係，且其價格互為影響之最適範圍稱之為何？","opts":["生活圈","類似地區","近鄰地區","同一供需圈"],"ok":[3],"ex":["「生活圈」並非技術規則第2條明定之正式用語，技術規則使用的是近鄰地區、類似地區、同一供需圈等專有名詞。","類似地區指同一供需圈內，近鄰地區以外而使用性質相近之地區，與題目所述「能成立替代關係且價格互為影響之最適範圍」此一更廣泛的定義不符（類似地區是同一供需圈的次集合）。","近鄰地區指勘估標的或比較標的周圍，形成同質性較高之地區，範圍小於同一供需圈，與題目所述「最適範圍」定義不符。","技術規則第2條第11款明定同一供需圈係指比較標的與勘估標的間能成立替代關係，且其價格互為影響之最適範圍，與題目敘述完全相符（同一供需圈＝近鄰地區＋類似地區）。"],"tr":"","core":["生活圈非技術規則用語","類似地區只是同一供需圈的次集合","近鄰地區範圍小於同一供需圈","替代關係且價格互影響之最適範圍"],"hl":[["生活圈","技術規則使用的是近鄰地區、類似地區、同一供需圈"],["類似地區","類似地區是同一供需圈的次集合"],["近鄰地區","範圍小於同一供需圈"],[]]},{"id":"h:100-1","p":"h","src":"100年第1題","sec":"A3","stem":"政策宣示不動產交易將採實價登錄，此於不動產估價中屬於影響價格的何種因素？","opts":["特殊因素","個別因素","區域因素","一般因素"],"ok":[3],"ex":["「特殊因素」並非技術規則第2條明定之獨立因素分類名稱。","個別因素指不動產本身條件所產生之價格差異，實價登錄政策非標的本身條件。","區域因素指影響近鄰地區不動產價格水準之因素，實價登錄屬全國性政策，非侷限特定區域。","技術規則第2條第14款明定一般因素係對不動產市場及價格水準發生全面影響之自然、政治、社會、經濟等共同因素，政策宣示實價登錄屬全國性交易制度變革，影響全國不動產市場，符合一般因素定義。"],"tr":"","core":["特殊因素非法定因素分類","實價登錄非標的本身條件","實價登錄屬全國性，非限特定區域","全國性交易制度變革＝一般因素"],"hl":[["特殊因素","並非技術規則第2條明定之獨立因素分類名稱"],["個別因素","個別因素指不動產本身條件所產生之價格差異"],["區域因素","實價登錄屬全國性政策"],[]]},{"id":"h:100-2","p":"h","src":"100年第2題","sec":"A3","stem":"飛航管制對於建築高度之限制，此於不動產估價中屬於影響價格的何種因素？","opts":["特殊因素","個別因素","區域因素","一般因素"],"ok":[2],"ex":["特殊因素不是技術規則 §2 的因素分類名稱（§2 分一般因素、區域因素、個別因素）。","飛航管制對建築高度的限制是整個機場周邊範圍一體適用，影響的是近鄰地區的價格水準，不是單一標的才有的條件，所以不是個別因素。","考選部標準答案 C。區域因素＝影響近鄰地區不動產價格水準之因素（§2⑮）；飛航管制範圍內的土地都受同一限高，屬區域因素。","一般因素是全國性的經濟、社會、政治環境，飛航管制只限機場周邊，不是一般因素。"],"tr":"","core":["特殊因素非法定因素分類","限高一體適用周邊，非單一標的","限高影響近鄰地區價格水準＝區域","飛航管制只限機場周邊，非全國"],"hl":[["特殊因素","§2 分一般因素、區域因素、個別因素"],["個別因素","影響的是近鄰地區的價格水準"],[],["一般因素","一般因素是全國性的經濟、社會、政治環境"]]},{"id":"h:100-3","p":"h","src":"100年第3題","sec":"A3","stem":"不動產座北朝南，此於不動產估價中屬於影響價格的何種因素？","opts":["特殊因素","個別因素","區域因素","一般因素"],"ok":[1],"ex":["「特殊因素」並非技術規則明文定義之獨立因素分類名稱。","技術規則第2條第16款明定個別因素係不動產本身條件所產生之價格差異因素，「座北朝南」是勘估標的本身之座向條件，屬於標的自身特性，符合個別因素定義。","區域因素指影響近鄰地區不動產價格水準之因素，座向是標的本身特性而非區域共通條件。","一般因素係全國性共同因素，與單一標的之座向條件無關。"],"tr":"","core":["特殊因素非法定因素分類","座向是標的本身條件＝個別因素","座向是標的特性，非區域共通條件","一般因素是全國性，與座向無關"],"hl":[["特殊因素","並非技術規則明文定義之獨立因素分類名稱"],[],["區域因素","座向是標的本身特性"],["一般因素","一般因素係全國性共同因素"]]},{"id":"h:100-4","p":"h","src":"100年第4題","sec":"A3","stem":"下列因素那些屬於影響地價之一般因素？①利率　②位置　③道路寬度　④土地形狀　⑤土地政策","opts":["①③","②④","①⑤","①②③④⑤"],"ok":[2],"ex":["①利率屬於影響全國經濟之金融政策因素，符合一般因素定義；③道路寬度是影響特定區域或標的本身之條件，非全國性一般因素。","②位置是不動產本身或鄰近區域之條件，非全國性一般因素；④土地形狀是標的本身之個別因素，非一般因素。","技術規則第2條第14款明定一般因素係對不動產市場及價格水準發生全面影響之自然、政治、社會、經濟等共同因素，①利率（金融政策）與⑤土地政策（全國性政策）皆屬全國性共同因素，符合一般因素定義。","①②③④⑤全選，但②位置、③道路寬度、④土地形狀皆屬區域或個別因素層次，非一般因素，不應全部列入。"],"tr":"","core":["③道路寬度非全國性一般因素","②位置④形狀皆非一般因素","利率與土地政策皆屬全國共同因素","②③④屬區域或個別，不應全選"],"hl":[["③道路寬度是影響特定區域或標的本身之條件"],["②④","②位置是不動產本身或鄰近區域之條件"],[],["①②③④⑤","皆屬區域或個別因素層次"]]},{"id":"h:100-5","p":"h","src":"100年第5題","sec":"A3","stem":"勘估標的距離捷運車站之遠近為下列何種影響因素？","opts":["區域因素","個別因素","特別因素","一般因素"],"ok":[1],"ex":["區域因素是影響近鄰地區整體價格水準的因素（§2⑮）；題目問的是「這一個標的」離捷運站多遠，是標的自己的條件，不是區域因素。","考選部標準答案 B。個別因素＝不動產因受本身條件影響，而產生價格差異之因素（§2⑯）；同一街廓內各宗地離捷運站遠近不同，價格就不同，屬個別（接近條件）。","「特別因素」不是技術規則的分類名稱。","一般因素是全國性共同因素，與單一標的離車站遠近無關。"],"tr":"","core":["離捷運遠近是標的自身條件，非區域","標的離車站遠近屬個別因素","特別因素非法定分類名稱","一般因素是全國性，與遠近無關"],"hl":[["區域因素","是標的自己的條件"],[],["特別因素","不是技術規則的分類名稱"],["一般因素","一般因素是全國性共同因素"]]},{"id":"h:100-17","p":"h","src":"100年第17題","sec":"A3","stem":"因接近行動電話基地臺而引起之價值減損，屬於下列何種因素？","opts":["物理的因素","功能的因素","特殊的因素","經濟的因素"],"ok":[3],"ex":["物理的因素通常指建物本身結構、材料等實體狀況，與行動電話基地台此一外部嫌惡設施之影響性質不同。","功能的因素通常指建物設計、配置等使用功能層面，與行動電話基地台之影響性質不同。","「特殊的因素」並非估價理論常用之因素分類用語（技術規則亦無此分類）。","因接近行動電話基地臺而引起的價值減損，是外部環境（電磁波疑慮）造成的減價，不是建物本身的實體耗損或功能落後，依估價理論（教材）歸為經濟的（外部性）減價因素。技術規則§2⑭～⑯把價格形成因素分為一般、區域、個別三類；物理、功能、經濟因素則出現在§68Ⅱ建物累積折舊的考量（「除考量物理與功能因素外，並得……考量經濟因素」）。"],"tr":"","core":["物理因素指建物實體狀況，非外部","功能因素指設計配置，非外部嫌惡","特殊的因素非常用分類用語","外部環境造成減價＝經濟的因素"],"hl":[["物理的因素","物理的因素通常指建物本身結構、材料等實體狀況"],["功能的因素","功能的因素通常指建物設計、配置等使用功能層面"],["特殊的因素","並非估價理論常用之因素分類用語"],[]]},{"id":"h:101-1","p":"h","src":"101年第1題","sec":"A3","stem":"下列那些因素屬於影響土地價格之個別因素？①土地形狀　②土地面積　③貸款利率　④地價稅稅率","opts":["①②","③④","①②④","②③④"],"ok":[0],"ex":["①土地形狀、②土地面積皆屬不動產本身條件所產生之價格差異因素，符合技術規則第2條第16款個別因素之定義。","③貸款利率屬於影響全國金融市場之一般因素，④地價稅稅率屬於影響全國稅制之一般因素，皆非個別因素。","①②④組合中含④地價稅稅率，但地價稅稅率是全國性稅制規定，非標的本身條件，不應列入個別因素。","②③④組合中含③④兩項一般因素，且遺漏①土地形狀此一明確個別因素，組合錯誤。"],"tr":"","core":["形狀面積皆標的本身條件＝個別","利率稅率皆屬全國性一般因素","④地價稅率是全國稅制，非個別","含③④一般因素且漏①土地形狀"],"hl":[[],["③④","影響全國金融市場之一般因素","影響全國稅制之一般因素"],["地價稅稅率是全國性稅制規定"],["③④","③④兩項一般因素"]]},{"id":"h:101-2","p":"h","src":"101年第2題","sec":"A3","stem":"歐債風暴對臺灣不動產市場的影響，此於不動產估價中屬於影響價格的何種因素？","opts":["特殊因素","個別因素","區域因素","一般因素"],"ok":[3],"ex":["「特殊因素」並非技術規則明文定義之獨立因素分類名稱。","個別因素指不動產本身條件，歐債風暴屬國際總體經濟事件，非標的本身條件。","區域因素指影響近鄰地區不動產價格水準之因素，歐債風暴影響範圍涵蓋全國甚至全球，非侷限特定近鄰地區。","技術規則第2條第14款明定一般因素係對不動產市場及價格水準發生全面影響之政治、社會、經濟等共同因素，歐債風暴屬國際總體經濟事件，透過總體經濟管道影響臺灣整體不動產市場，符合一般因素定義。"],"tr":"","core":["特殊因素非法定因素分類","歐債是國際總體事件，非標的條件","影響及全國，非限近鄰地區","國際總體經濟事件＝一般因素"],"hl":[["特殊因素","並非技術規則明文定義之獨立因素分類名稱"],["個別因素","個別因素指不動產本身條件"],["區域因素","影響範圍涵蓋全國甚至全球"],[]]},{"id":"h:101-7","p":"h","src":"101年第7題","sec":"A3","stem":"土地徵收補償市價查估與區段式公告土地現值查估相較，兩者主要的差異在於下列那一影響不動產價格因素調整的考量？","opts":["個別因素","區域因素","一般因素","特別因素"],"ok":[0],"ex":["土地徵收補償市價查估辦法§20：預定徵收土地宗地市價，以比準地為基準，參酌宗地條件、道路條件、接近條件、周邊環境條件及行政條件等個別因素調整估計（都市計畫範圍內公共設施保留地除外）。區段式公告土地現值依地價調查估計規則§23②，除繁榮街道路線價區段外，其他地價區段（含一般路線價區段）都以區段地價作為宗地單位地價，沒有逐宗個別因素調整，所以差異在個別因素。","區域因素（技術規則§2⑮）影響近鄰地區價格水準。兩種查估都會調查區域因素（辦法§9、地價調查估計規則§9），劃分區段與比準地的區域因素調整也都有，不是差異所在。","一般因素（技術規則§2⑭）是對不動產市場及其價格水準發生全面影響之共同因素，兩種查估方式皆受其影響，不是差異所在。","技術規則§2⑭⑮⑯只有一般、區域、個別三類因素，沒有「特別因素」。"],"tr":"","core":["徵收逐宗個別調整，公告現值沒有","兩者都調查區域因素，非差異","兩者皆受一般因素影響，非差異","只有一般區域個別三類，無特別"],"hl":[[],["區域因素","兩種查估都會調查區域因素"],["一般因素","兩種查估方式皆受其影響"],["特別因素","只有一般、區域、個別三類因素"]]},{"id":"h:102-1","p":"h","src":"102年第1題","sec":"A3","stem":"特種貨物與勞務稅（俗稱奢侈稅）近日研議之修法動向，對不動產市場之影響，是屬於下列何種因素？","opts":["一般因素","區域因素","個別因素","期待因素"],"ok":[0],"ex":["技術規則第2條第14款明定一般因素係對不動產市場及價格水準發生全面影響之政治、社會、經濟等共同因素，奢侈稅修法動向屬全國性稅制政策變動，影響全國不動產市場，符合一般因素定義。","區域因素指影響近鄰地區不動產價格水準之因素，奢侈稅政策非侷限特定區域。","個別因素指不動產本身條件，與全國性稅制政策無關。","「期待因素」不是§2第14～16款所定之一般、區域、個別三層因素；期待因素係§23第2款「期待因素影響之交易」（交易情況之一），故非本題答案。"],"tr":"","core":["全國性稅制政策變動＝一般因素","奢侈稅非限特定區域","個別因素講標的本身條件","期待因素屬交易情況，非三層因素"],"hl":[[],["區域因素","奢侈稅政策非侷限特定區域"],["個別因素","個別因素指不動產本身條件"],["期待因素","期待因素係§23第2款"]]},{"id":"h:102-23","p":"h","src":"102年第23題","sec":"A3","stem":"下列何者非屬區域因素調整的考量項目？","opts":["交通條件","樓層別條件","商圈發展條件","學區條件"],"ok":[1],"ex":["交通條件是影響近鄰地區整體可及性之共通條件，屬於區域因素調整之考量項目。","樓層別條件是區分所有建物各樓層間使用效益差異之個別條件，與該宗地所在區域之共通條件無關，屬於房地估價中個別樓層之考量項目，非區域因素調整之考量項目，即本題正解。","商圈發展條件是影響近鄰地區整體商業活絡程度之共通條件，屬於區域因素調整之考量項目。","學區條件是影響近鄰地區整體教育資源之共通條件，屬於區域因素調整之考量項目。"],"tr":"","core":["交通條件屬區域因素考量項目","樓層別屬個別條件，非區域因素","商圈發展屬區域因素考量項目","學區條件屬區域因素考量項目"],"hl":[[],["樓層別條件","區分所有建物各樓層間使用效益差異之個別條件"],[],[]]},{"id":"h:102-26","p":"h","src":"102年第26題","sec":"A3","stem":"勘估標的距離變電所遠近為以下何種影響因素？","opts":["特殊因素","個別因素","區域因素","一般因素"],"ok":[1],"ex":["「特殊因素」並非技術規則明文定義之獨立因素分類名稱。","技術規則第2條第16款明定個別因素係不動產本身條件所產生之價格差異因素，「距離變電所遠近」是針對該勘估標的本身與變電所之相對距離所產生之個別差異，屬於個別因素。","區域因素指影響近鄰地區整體不動產價格水準之共通因素，本題所述為單一標的與變電所之相對距離，屬個別條件而非區域共通條件。","一般因素係全國性共同因素，與單一標的距離變電所遠近此一具體個別條件無關。"],"tr":"","core":["特殊因素非法定因素分類","標的距變電所遠近＝個別因素","單一標的相對距離，非區域共通","一般因素是全國性，與距離無關"],"hl":[["特殊因素","並非技術規則明文定義之獨立因素分類名稱"],[],["區域因素","本題所述為單一標的與變電所之相對距離，屬個別條件"],["一般因素","一般因素係全國性共同因素"]]},{"id":"h:103-4","p":"h","src":"103年第4題","sec":"A3","stem":"美國第二輪量化寬鬆（QE2）貨幣政策對臺北市不動產市場的影響，於不動產估價中屬於影響價格的何種因素？","opts":["一般因素","區域因素","個別因素","特殊因素"],"ok":[0],"ex":["技術規則第2條第14款明定一般因素係對不動產市場及價格水準發生全面影響之經濟等共同因素，美國QE2貨幣政策屬國際總體經濟事件，透過總體經濟管道影響臺北市整體不動產市場，符合一般因素定義。","區域因素指影響近鄰地區不動產價格水準之因素，QE2影響範圍涵蓋全國（甚至全球）市場，非侷限特定近鄰地區。","個別因素指不動產本身條件，與國際貨幣政策無關。","「特殊因素」並非技術規則明文定義之獨立因素分類名稱。"],"tr":"","core":["QE2屬國際總體經濟事件＝一般因素","QE2影響全國以上，非限近鄰地區","個別因素講標的本身，與QE2無關","特殊因素非法定因素分類"],"hl":[[],["區域因素","QE2影響範圍涵蓋全國（甚至全球）市場"],["個別因素","個別因素指不動產本身條件"],["特殊因素","並非技術規則明文定義之獨立因素分類名稱"]]},{"id":"h:103-6","p":"h","src":"103年第6題","sec":"A3","stem":"不動產位於路沖，此於不動產估價中屬於影響價格的何種因素？","opts":["一般因素","區域因素","個別因素","特殊因素"],"ok":[2],"ex":["一般因素係全國性共同因素，與單一標的位於路沖此一具體位置條件無關。","區域因素指影響近鄰地區整體不動產價格水準之共通因素，路沖是該特定標的自身之位置特性，非區域共通條件。","技術規則第2條第16款明定個別因素係不動產本身條件所產生之價格差異因素，「位於路沖」是勘估標的本身之位置條件，屬於標的自身特性，符合個別因素定義。","「特殊因素」並非技術規則明文定義之獨立因素分類名稱。"],"tr":"","core":["一般因素是全國性，與路沖無關","路沖是標的自身位置，非區域共通","路沖是標的本身位置條件＝個別","特殊因素非法定因素分類"],"hl":[["一般因素","一般因素係全國性共同因素"],["區域因素","路沖是該特定標的自身之位置特性"],[],["特殊因素","並非技術規則明文定義之獨立因素分類名稱"]]},{"id":"h:103-13","p":"h","src":"103年第13題","sec":"A3","stem":"比較標的與勘估標的間能成立替代關係，且其價格互為影響之最適範圍，稱之為：","opts":["近鄰地區","類似地區","共同生活圈","同一供需圈"],"ok":[3],"ex":["近鄰地區指勘估標的或比較標的周圍，形成同質性較高之地區，範圍小於同一供需圈，與題目所述「最適範圍」定義不符。","類似地區指同一供需圈內，近鄰地區以外而使用性質相近之地區，是同一供需圈的次集合，與題目所述最適範圍定義不符。","「共同生活圈」並非技術規則第2條明定之正式用語。","技術規則第2條第11款明定同一供需圈係指比較標的與勘估標的間能成立替代關係，且其價格互為影響之最適範圍，與題目敘述完全相符。"],"tr":"","core":["近鄰地區範圍小於同一供需圈","類似地區只是同一供需圈的次集合","共同生活圈非技術規則用語","替代關係且價格互影響之最適範圍"],"hl":[["近鄰地區","範圍小於同一供需圈"],["類似地區","是同一供需圈的次集合"],["共同生活圈","並非技術規則第2條明定之正式用語"],[]]},{"id":"h:103-16","p":"h","src":"103年第16題","sec":"A3","stem":"財政部目前正在研擬合理課稅方案，擬將房地合一課稅並納入實價課稅精神。此屬於影響不動產價格之何種因素？","opts":["特殊因素","個別因素","區域因素","一般因素"],"ok":[3],"ex":["「特殊因素」並非技術規則明文定義之獨立因素分類名稱。","個別因素指不動產本身條件，房地合一課稅方案非標的本身條件。","區域因素指影響近鄰地區不動產價格水準之因素，房地合一課稅方案非侷限特定區域。","技術規則第2條第14款明定一般因素係對不動產市場發生全面影響之經濟政策等共同因素，財政部研擬房地合一課稅方案屬全國性稅制政策，影響全國不動產市場，符合一般因素定義。"],"tr":"","core":["特殊因素非法定因素分類","房地合一方案非標的本身條件","房地合一非限特定區域","全國性稅制政策＝一般因素"],"hl":[["特殊因素","並非技術規則明文定義之獨立因素分類名稱"],["個別因素","個別因素指不動產本身條件"],["區域因素","區域因素指影響近鄰地區不動產價格水準之因素"],[]]},{"id":"h:103-25","p":"h","src":"103年第25題","sec":"A3","stem":"不動產位於路角地，雙面採光，此於不動產估價中屬於影響價格之何種因素？","opts":["特殊因素","個別因素","區域因素","一般因素"],"ok":[1],"ex":["「特殊因素」並非技術規則明文定義之獨立因素分類名稱。","技術規則第2條第16款明定個別因素係不動產本身條件所產生之價格差異因素，「位於路角地，雙面採光」是勘估標的本身之位置與採光條件，屬於標的自身特性，符合個別因素定義。","區域因素指影響近鄰地區整體不動產價格水準之共通因素，路角地雙面採光是該特定標的自身特性，非區域共通條件。","一般因素係全國性共同因素，與單一標的之位置採光條件無關。"],"tr":"","core":["特殊因素非法定因素分類","路角地雙面採光是標的本身＝個別","路角採光是標的特性，非區域共通","一般因素是全國性，與採光無關"],"hl":[["特殊因素","並非技術規則明文定義之獨立因素分類名稱"],[],["區域因素","路角地雙面採光是該特定標的自身特性"],["一般因素","一般因素係全國性共同因素"]]},{"id":"h:103-31","p":"h","src":"103年第31題","sec":"A3","stem":"下列有關影響不動產價格的因素，何者屬區域因素？","opts":["地區主要道路的連接性","臨接道路寬度","臨街寬度","宗地臨街情形"],"ok":[0],"ex":["技術規則第2條第15款明定區域因素係影響近鄰地區不動產價格水準之因素，「地區主要道路的連接性」是描述整個地區的交通網絡狀況，影響範圍涵蓋整個近鄰地區，屬於區域因素。","「臨接道路寬度」是針對勘估標的本身臨接道路的具體寬度，屬於標的自身條件，為個別因素而非區域因素。","「臨街寬度」同樣是標的本身臨街部分的寬度條件，屬於個別因素。","「宗地臨街情形」是描述該宗地本身與街道之相對關係，屬於標的自身條件之個別因素。"],"tr":"","core":["地區道路連接性影響整個近鄰地區","臨接道路寬度是標的條件＝個別","臨街寬度是標的條件＝個別","宗地臨街情形是標的條件＝個別"],"hl":[[],["臨接道路寬度","屬於標的自身條件，為個別因素"],["臨街寬度","標的本身臨街部分的寬度條件，屬於個別因素"],["宗地臨街情形","屬於標的自身條件之個別因素"]]},{"id":"h:104-4","p":"h","src":"104年第4題","sec":"A3","stem":"下列有關影響近鄰地區不動產價格水準之區域因素的敘述，何者錯誤？","opts":["軍事禁限建與使用分區管制，影響不動產價值","街道配置與公共設施愈完備，其不動產價值愈高","宗地坵塊面臨街道之寬度愈寬，其不動產價值愈高","瓦斯、上下水道等公用設備愈完備，其不動產價值愈高"],"ok":[2],"ex":["軍事禁限建與使用分區管制，確實會影響整個近鄰地區不動產之使用強度與價值，此敘述正確，非本題答案（本題問「何者錯誤」）。","街道配置與公共設施完備程度，是影響近鄰地區整體不動產價值之區域因素，此敘述正確，街道配置公共設施愈完備則不動產價值愈高，符合常理。","「宗地坵塊面臨街道之寬度」是該宗地「本身」臨街的具體寬度，屬於標的本身之個別因素（§2(16)），而非影響「近鄰地區」整體不動產價格水準之區域因素（§2(15)），本選項將個別因素誤植為區域因素之敘述，即本題正解。","瓦斯、上下水道等公用設備完備程度，是影響近鄰地區整體不動產價值之區域因素，此敘述正確。"],"tr":"","core":["禁限建與分區管制確影響價值","街道公設愈完備，價值愈高","宗地臨街寬度屬個別，非區域因素","公用設備愈完備，價值愈高"],"hl":[[],[],["宗地坵塊面臨街道之寬度","屬於標的本身之個別因素"],[]]},{"id":"h:104-5","p":"h","src":"104年第5題","sec":"A3","stem":"下列何者不屬於鄰避設施（NIMBY）？","opts":["公園","監獄","變電廠","垃圾掩埋場"],"ok":[0],"ex":["公園屬於受民眾歡迎之公共設施，通常對周邊不動產價值產生正向加值效果，並非鄰避設施（NIMBY，Not In My Backyard，指民眾不願其鄰近設置之嫌惡設施），即本題正解。","監獄屬於典型的鄰避設施，民眾普遍不願鄰近居住，會造成周邊不動產價值減損。","變電廠同樣屬於典型的鄰避設施，因電磁波疑慮及景觀影響造成周邊不動產價值減損。","垃圾掩埋場是典型的鄰避設施，因環境污染及異味問題造成周邊不動產價值減損。"],"tr":"","core":["公園受歡迎、正向加值，非鄰避","監獄是典型鄰避設施","變電廠是典型鄰避設施","垃圾掩埋場是典型鄰避設施"],"hl":[["公園","通常對周邊不動產價值產生正向加值效果"],[],[],[]]},{"id":"h:104-6","p":"h","src":"104年第6題","sec":"A3","stem":"房地合一課稅的相關法案，已經立法院三讀通過，總統公布，並訂於2016年1月1日實施，其對不動產市場之影響是屬於下列何種因素？","opts":["一般因素","個別因素","特殊因素","區域因素"],"ok":[0],"ex":["技術規則第2條第14款明定一般因素係對不動產市場發生全面影響之政治社會經濟等共同因素，房地合一課稅相關法案經立法院三讀通過並訂定全國一致實施日期，屬全國性稅制政策變革，符合一般因素定義。","個別因素指不動產本身條件，與全國性稅制立法無關。","「特殊因素」並非技術規則明文定義之獨立因素分類名稱。","區域因素指影響近鄰地區之因素，房地合一課稅是全國一致適用之稅制，非侷限特定區域。"],"tr":"","core":["全國一致實施之稅制＝一般因素","個別因素講標的本身，與立法無關","特殊因素非法定因素分類","全國一致稅制，非限特定區域"],"hl":[[],["個別因素","個別因素指不動產本身條件"],["特殊因素","並非技術規則明文定義之獨立因素分類名稱"],["區域因素","房地合一課稅是全國一致適用之稅制"]]},{"id":"h:104-7","p":"h","src":"104年第7題","sec":"A3","stem":"下列有關比較法估價時之區域分析的敘述，何者正確？","opts":["類似地區係指同一供需圈內，近鄰地區內與勘估標的使用性質相近之地區","同一供需圈係指比較標的與勘估標的間能成立貢獻關係，且其價格互為影響之最適範圍","近鄰地區係指勘估標的或比較標的周圍，供相同或類似用途之不動產，形成異質性較高之地區","區域分析是要分析判定對象不動產屬於何種地區，有何特性，其對該地區內之不動產價格形成有何影響等"],"ok":[3],"ex":["技術規則第2條第13款明定類似地區係指同一供需圈內，「近鄰地區以外」而使用性質相近之地區，本選項稱「近鄰地區內」，將「以外」誤植為「內」，定義方向相反，敘述錯誤。","同一供需圈定義係比較標的與勘估標的間能成立「替代關係」，本選項稱「貢獻關係」，用語錯誤，技術規則明確使用「替代關係」一詞。","近鄰地區定義係供相同或類似用途之不動產，形成「同質性較高」之地區，本選項稱「異質性較高」，定義方向相反，敘述錯誤。","區域分析的目的正是要分析判定對象不動產屬於何種地區，有何特性，其對該地區內不動產價格形成有何影響，此為正確之區域分析定義敘述。"],"tr":"","core":["類似地區在近鄰地區以外，非以內","應為替代關係，非貢獻關係","近鄰地區是同質性較高，非異質","區域分析判定所屬地區及其影響"],"hl":[["近鄰地區內","近鄰地區以外"],["貢獻關係","替代關係"],["異質性較高","同質性較高"],[]]},{"id":"h:104-28","p":"h","src":"104年第28題","sec":"A3","stem":"下列那一個區域比較可能符合不動產估價技術規則中所定義與臺北市信義區的不動產具替代關係，且其價格互為影響之「同一供需圈」？","opts":["香港上環","上海徐家匯區","紐約曼哈頓區","臺北市大安區"],"ok":[3],"ex":["香港上環與臺北市信義區分屬不同國家、不同貨幣與法律制度之市場，難以成立替代關係，不符同一供需圈定義。","上海徐家匯區同樣與信義區分屬不同國家市場制度，難以成立替代關係。","紐約曼哈頓區與信義區地理位置相距遙遠，分屬不同國家市場，難以成立替代關係及價格互為影響之關係。","技術規則第2條第11款明定同一供需圈係比較標的與勘估標的間能成立替代關係，且其價格互為影響之最適範圍。臺北市大安區與信義區地理位置相鄰，同屬臺北市精華區域，購屋者在兩區之間具有實質的替代選擇可能性，價格水準也會互相影響，符合同一供需圈之定義。"],"tr":"","core":["不同國家制度，難成立替代關係","不同國家市場，難成立替代關係","相距遙遠又跨國，難互相影響","大安鄰信義可替代＝同一供需圈"],"hl":[["香港上環","分屬不同國家、不同貨幣與法律制度之市場"],["上海徐家匯區","分屬不同國家市場制度"],["紐約曼哈頓區","相距遙遠，分屬不同國家市場"],[]]},{"id":"h:105-5","p":"h","src":"105年第5題","sec":"A3","stem":"就住宅用地之估價而言，下列何者非屬影響價格水準之區域因素？","opts":["公共設施、公益設施等配置狀態","噪音、空氣污染、土壤污染等公害發生之程度","臨接道路之寬度","離市中心之距離及交通設施狀態"],"ok":[2],"ex":["公共設施、公益設施等配置狀態，是影響近鄰地區整體不動產價值之區域因素，此選項屬於區域因素，非本題答案（本題問「非屬」區域因素）。","噪音、空氣污染、土壤污染等公害發生程度，是影響近鄰地區整體環境品質之區域因素，屬於區域因素。","「臨接道路之寬度」是針對勘估標的本身臨接道路的具體寬度，屬於標的自身條件之個別因素，而非影響近鄰地區整體不動產價格水準之區域因素，即本題正解。","離市中心之距離及交通設施狀態，是影響近鄰地區整體可及性之區域因素，屬於區域因素。"],"tr":"","core":["公共公益設施配置屬區域因素","公害發生程度屬區域因素","臨接道路寬度是標的條件＝個別","離市中心距離及交通屬區域因素"],"hl":[[],[],["臨接道路之寬度","屬於標的自身條件之個別因素"],[]]},{"id":"h:105-9","p":"h","src":"105年第9題","sec":"A3","stem":"影響不動產價格的一般因素，不包含下列何者？","opts":["房地合一稅制之推動","國民所得水準","距離捷運站遠近","兩岸政策之改變"],"ok":[2],"ex":["房地合一稅制之推動屬全國性稅制政策，影響全國不動產市場，是一般因素，此選項屬於一般因素，非本題答案（本題問「不包含」哪一項）。","國民所得水準是反映全國整體經濟發展狀況之指標，屬於一般因素。","「距離捷運站遠近」是這一宗標的自己的接近條件，屬個別因素（100-5 考選部答案），不是全國性的一般因素，即本題正解。口訣：「距離」＝個別因素；「設置／整個地區」＝區域因素。","兩岸政策之改變屬全國性政治經濟政策，影響全國不動產市場，是一般因素。"],"tr":"","core":["房地合一稅制屬全國性一般因素","國民所得水準屬一般因素","距捷運站遠近是標的條件＝個別","兩岸政策改變屬一般因素"],"hl":[[],[],["距離捷運站遠近","這一宗標的自己的接近條件"],[]]},{"id":"h:105-11","p":"h","src":"105年第11題","sec":"A3","stem":"臺灣老年人口的比例正大幅增加，高齡化社會已成為重大議題，此屬於何種影響價格因素？","opts":["一般因素","區域因素","個別因素","特殊因素"],"ok":[0],"ex":["技術規則第2條第14款明定一般因素係對不動產市場發生全面影響之社會等共同因素，臺灣老年人口比例大幅增加、高齡化社會議題，屬全國性社會結構變遷，影響全國不動產市場（如養老宅、無障礙空間需求），符合一般因素定義。","區域因素指影響近鄰地區之因素，高齡化是全國性社會現象，非侷限特定區域。","個別因素指不動產本身條件，與全國人口結構變遷無關。","「特殊因素」並非技術規則明文定義之獨立因素分類名稱。"],"tr":"","core":["高齡化是全國社會變遷＝一般因素","高齡化是全國性，非限特定區域","個別因素講標的本身，與人口無關","特殊因素非法定因素分類"],"hl":[[],["區域因素","高齡化是全國性社會現象"],["個別因素","個別因素指不動產本身條件"],["特殊因素","並非技術規則明文定義之獨立因素分類名稱"]]},{"id":"h:105-36","p":"h","src":"105年第36題","sec":"A3","stem":"依不動產估價技術規則之規定，下列敘述何者正確？","opts":["比較標的與勘估標的間能成立替代關係，且其價格互為影響之最適範圍稱為近鄰地區","勘估標的或比較標的周圍，供相同或類似用途之不動產，形成同質性較高之地區，稱為類似地區","所選用之比較標的與勘估標的不在同一近鄰地區內時，應進行區域因素調整","所選用之比較標的與勘估標的不在同一近鄰地區內時，應進行個別因素調整"],"ok":[2],"ex":["技術規則明定同一供需圈係比較標的與勘估標的間能成立替代關係之最適範圍，本選項稱此為「近鄰地區」，定義名稱誤植，敘述錯誤。","技術規則明定近鄰地區係供相同或類似用途之不動產形成「同質性較高」之地區，本選項描述的內容是§2(12)近鄰地區之定義，名稱卻寫成「類似地區」（§2(13)），名稱與定義不符，故敘述錯誤。","技術規則第19條第3款明定：比較標的與勘估標的不在同一近鄰地區內時，應將比較標的價格轉化為勘估標的同一近鄰地區之價格水準，此調整即為區域因素調整，與本選項描述相符，為正確敘述。","比較標的與勘估標的不在同一近鄰地區內時，應進行的是「區域因素調整」而非「個別因素調整」，本選項調整類型誤植，敘述錯誤。"],"tr":"","core":["替代關係最適範圍是同一供需圈","同質性較高之地區是近鄰地區","不在同一近鄰地區應做區域因素調整","應做區域因素調整，非個別因素"],"hl":[["稱為近鄰地區","同一供需圈係比較標的與勘估標的間能成立替代關係"],["類似地區","近鄰地區"],[],["個別因素調整","區域因素調整"]]},{"id":"h:106-22","p":"h","src":"106年第22題","sec":"A3","stem":"容積移轉及容積調派制度的實施，對不動產價值發生影響的因素被稱為：","opts":["行政條件","政治條件","社會條件","接近條件"],"ok":[0],"ex":["容積移轉及容積調派制度屬於政府透過行政法規調控土地使用強度之政策工具，其對不動產價值之影響歸類為行政條件（即政府行政管制措施對不動產市場之影響），與題目敘述相符。","政治條件通常指更廣泛的政治體制或政局穩定度因素，容積移轉調派制度是具體的行政管理措施，非政治條件。","社會條件通常指人口結構、社會風氣等社會性因素，與容積移轉調派此一具體行政管制工具性質不同。","「接近條件」通常指不動產與特定設施之距離遠近，與容積移轉調派制度性質不同。"],"tr":"","core":["容積移轉是行政管制＝行政條件","政治條件指政局體制，非行政措施","社會條件指人口風氣，非行政管制","接近條件指與設施距離遠近"],"hl":[[],["政治條件","具體的行政管理措施"],["社會條件","社會條件通常指人口結構、社會風氣等社會性因素"],["接近條件","指不動產與特定設施之距離遠近"]]},{"id":"h:108-3","p":"h","src":"108年第3題","sec":"A3","stem":"不動產面臨道路之寬度，此屬於影響不動產價格之何種因素？","opts":["個別因素","區域因素","一般因素","特別因素"],"ok":[0],"ex":["技術規則第2條第16款明定個別因素係不動產本身條件所產生之價格差異因素，「不動產面臨道路之寬度」是該標的本身臨路的具體寬度條件，屬於標的自身特性，符合個別因素定義。","區域因素指影響近鄰地區整體不動產價格水準之共通因素，本題所述為單一標的本身面臨道路之寬度，屬個別條件而非區域共通條件。","一般因素係全國性共同因素，與單一標的面臨道路寬度此一具體個別條件無關。","「特別因素」並非技術規則明文定義之獨立因素分類名稱。"],"tr":"","core":["面臨道路寬度是標的條件＝個別","單一標的臨路寬度，非區域共通","一般因素是全國性，與路寬無關","特別因素非法定分類名稱"],"hl":[[],["區域因素","本題所述為單一標的本身面臨道路之寬度，屬個別條件"],["一般因素","一般因素係全國性共同因素"],["特別因素","並非技術規則明文定義之獨立因素分類名稱"]]},{"id":"h:108-12","p":"h","src":"108年第12題","sec":"A3","stem":"政府宣布實施空屋稅政策，此屬於何種影響價格之因素？","opts":["個別因素","情況因素","一般因素","區域因素"],"ok":[2],"ex":["個別因素指不動產本身條件，空屋稅政策非標的本身條件。","「情況因素」是比較法調整流程中的概念（描述交易非正常情形），並非影響不動產價格之三層次因素分類之一。","技術規則第2條第14款明定一般因素係對不動產市場發生全面影響之政治經濟政策等共同因素，政府實施空屋稅政策屬全國性稅制政策，影響全國不動產市場，符合一般因素定義。","區域因素指影響近鄰地區之因素，空屋稅是全國一致適用之政策，非侷限特定區域。"],"tr":"","core":["空屋稅政策非標的本身條件","情況因素屬比較法調整，非三層","全國性稅制政策＝一般因素","空屋稅全國適用，非限特定區域"],"hl":[["個別因素","個別因素指不動產本身條件"],["情況因素","並非影響不動產價格之三層次因素分類之一"],[],["區域因素","空屋稅是全國一致適用之政策"]]},{"id":"h:110-1","p":"h","src":"110年第1題","sec":"A3","stem":"政府宣布實價登錄2.0新制自110年7月1日施行，此為影響不動產價格之何種因素？","opts":["情況因素","一般因素","區域因素","個別因素"],"ok":[1],"ex":["「情況因素」是比較法調整流程中的概念，並非影響價格之三層次因素分類之一。","技術規則第2條第14款明定一般因素係對不動產市場發生全面影響之政治經濟政策等共同因素，實價登錄2.0新制屬全國一致施行之交易制度變革，影響全國不動產市場，符合一般因素定義。","區域因素指影響近鄰地區之因素，實價登錄新制是全國一致適用之政策，非侷限特定區域。","個別因素指不動產本身條件，與全國性交易制度變革無關。"],"tr":"","core":["情況因素屬比較法調整，非三層","全國一致施行之交易制度＝一般","實價登錄全國適用，非限特定區域","個別因素講標的本身，與新制無關"],"hl":[["情況因素","並非影響價格之三層次因素分類之一"],[],["區域因素","實價登錄新制是全國一致適用之政策"],["個別因素","個別因素指不動產本身條件"]]},{"id":"h:110-2","p":"h","src":"110年第2題","sec":"A3","stem":"不動產所在地區對外連絡道路為中山路，路寬30公尺，並有兩線捷運經過。請問此為影響不動產價格之何種因素？","opts":["情況因素","一般因素","區域因素","個別因素"],"ok":[2],"ex":["「情況因素」是比較法調整流程中的概念，並非影響價格之三層次因素分類之一。","一般因素係全國性共同因素，題目所述對外連絡道路寬度與捷運經過情形，是描述特定地區之具體條件，非全國性政策或現象。","技術規則第2條第15款明定區域因素係影響近鄰地區不動產價格水準之因素，題目描述該不動產所在地區之對外連絡道路（中山路，路寬30公尺）及捷運經過情形，是描述整個地區的交通網絡條件，影響範圍涵蓋整個近鄰地區，屬於區域因素。","個別因素指不動產本身條件，題目描述的是「地區」之對外連絡道路及捷運狀況，而非該特定標的本身之條件，屬於區域因素而非個別因素。"],"tr":"","core":["情況因素屬比較法調整，非三層","描述特定地區條件，非全國性","地區對外道路與捷運＝區域因素","描述地區非標的本身，非個別因素"],"hl":[["情況因素","並非影響價格之三層次因素分類之一"],["一般因素","是描述特定地區之具體條件"],[],["個別因素","題目描述的是「地區」之對外連絡道路及捷運狀況"]]},{"id":"h:110-17","p":"h","src":"110年第17題","sec":"A3","stem":"近年受疫情影響，各地商圈人潮減少、店面空置率提高，此屬於何種價格影響因素？","opts":["一般因素","區域因素","個別因素","總體因素"],"ok":[0],"ex":["技術規則第2條第14款明定一般因素係對不動產市場發生全面影響之社會經濟等共同因素，疫情屬全國性（甚至全球性）公共衛生事件，透過總體經濟與社會行為改變影響全國各地商圈，符合一般因素定義。","區域因素指影響特定近鄰地區之因素，但題目描述「各地商圈」均受影響，屬於全國性現象而非侷限特定區域。","個別因素指不動產本身條件，與疫情此一全國性公共衛生事件無關。","「總體因素」並非技術規則第2條明定之正式因素分類名稱（技術規則僅分一般、區域、個別三層次）。"],"tr":"","core":["疫情是全國性事件＝一般因素","各地商圈皆受影響，非限特定區域","個別因素講標的本身，與疫情無關","總體因素非法定因素分類"],"hl":[[],["區域因素","屬於全國性現象而非侷限特定區域"],["個別因素","個別因素指不動產本身條件"],["總體因素","技術規則僅分一般、區域、個別三層次"]]},{"id":"h:111-1","p":"h","src":"111年第1題","sec":"A3","stem":"平均地權條例近日研議抑制炒房之修法動向，其對不動產市場之影響，是屬於不動產估價影響因素中之下列何種因素？","opts":["市場因素","一般因素","區域因素","個別因素"],"ok":[1],"ex":["「市場因素」並非技術規則第2條明定之正式因素分類名稱。","技術規則第2條第14款明定一般因素係對不動產市場發生全面影響之政治經濟政策等共同因素，平均地權條例修法動向屬全國性土地政策法規變動，影響全國不動產市場，符合一般因素定義。","區域因素指影響近鄰地區之因素，平均地權條例修法是全國一致適用之法規，非侷限特定區域。","個別因素指不動產本身條件，與全國性修法動向無關。"],"tr":"","core":["市場因素非法定因素分類","全國性土地法規變動＝一般因素","全國一致適用法規，非限特定區域","個別因素講標的本身，與修法無關"],"hl":[["市場因素","並非技術規則第2條明定之正式因素分類名稱"],[],["區域因素","平均地權條例修法是全國一致適用之法規"],["個別因素","個別因素指不動產本身條件"]]},{"id":"h:112-1","p":"h","src":"112年第1題","sec":"A3","stem":"不動產售屋廣告中「面對公園第一排」，對不動產之影響，是屬於不動產估價影響因素中之何種因素？","opts":["一般因素","市場因素","區域因素","個別因素"],"ok":[3],"ex":["一般因素係全國性共同因素，「面對公園第一排」是該特定標的本身與公園之相對位置關係，非全國性政策或現象。","「市場因素」並非技術規則第2條明定之正式因素分類名稱。","區域因素指影響近鄰地區整體不動產價格水準之共通因素，「面對公園第一排」是該特定標的自身之位置特性，非區域共通條件。","技術規則第2條第16款明定個別因素係不動產本身條件所產生之價格差異因素，「面對公園第一排」是該標的本身與公園緊鄰之具體位置條件，屬於標的自身特性，符合個別因素定義。"],"tr":"","core":["面對公園是標的位置，非全國性","市場因素非法定因素分類","標的自身位置特性，非區域共通","面對公園第一排是標的條件＝個別"],"hl":[["一般因素","是該特定標的本身與公園之相對位置關係"],["市場因素","並非技術規則第2條明定之正式因素分類名稱"],["區域因素","是該特定標的自身之位置特性"],[]]},{"id":"h:112-3","p":"h","src":"112年第3題","sec":"A3","stem":"各直轄市、縣（市）國土計畫於110年4月30日公告實施，此為影響不動產價格之何種因素？","opts":["一般因素","市場因素","區域因素","個別因素"],"ok":[0],"ex":["技術規則第2條第14款明定一般因素係對不動產市場發生全面影響之政治社會等共同因素，國土計畫於各直轄市縣市同步公告實施，屬全國一致性之國土空間規劃政策，影響全國不動產市場，符合一般因素定義。","「市場因素」並非技術規則第2條明定之正式因素分類名稱。","區域因素指影響近鄰地區之因素，國土計畫雖按各直轄市縣市分別公告，但其本質是全國一致性之國土空間規劃政策架構，屬一般因素而非單一近鄰地區之區域因素。","個別因素指不動產本身條件，與國土計畫此一全國性空間規劃政策無關。"],"tr":"","core":["全國一致之國土空間規劃＝一般因素","市場因素非法定因素分類","本質為全國性政策架構，非區域","個別因素講標的本身，與國土計畫無關"],"hl":[[],["市場因素","並非技術規則第2條明定之正式因素分類名稱"],["區域因素","屬一般因素而非單一近鄰地區之區域因素"],["個別因素","個別因素指不動產本身條件"]]},{"id":"h:113-11","p":"h","src":"113年第11題","sec":"A3","stem":"中央銀行理監事會於113年第3季會議決議調升存款準備率及調整選擇性信用管制措施，此項宣布可能會影響不動產市場與價值，此為影響不動產價值之何種因素？","opts":["一般因素","情況因素","區域因素","個別因素"],"ok":[0],"ex":["技術規則§2第14款：一般因素「指對於不動產市場及其價格水準發生全面影響之自然、政治、社會、經濟等共同因素」。中央銀行調升存款準備率及信用管制屬全國性經濟金融政策，影響全國不動產市場與融資環境，符合一般因素。","「情況因素」是比較法調整流程中的概念，並非影響價格之三層次因素分類之一。","區域因素指影響近鄰地區之因素，中央銀行貨幣政策是全國一致適用之政策，非侷限特定區域。","個別因素指不動產本身條件，與全國性貨幣政策無關。"],"tr":"","core":["全國性經濟金融政策＝一般因素","情況因素屬比較法調整，非三層","央行政策全國適用，非限特定區域","個別因素講標的本身，與貨幣政策無關"],"hl":[[],["情況因素","並非影響價格之三層次因素分類之一"],["區域因素","中央銀行貨幣政策是全國一致適用之政策"],["個別因素","個別因素指不動產本身條件"]]},{"id":"h:113-18","p":"h","src":"113年第18題","sec":"A3","stem":"影響不動產價格的三大因素中區域因素甚為重要，下列敘述何者非屬區域因素的描述？","opts":["王小姐的房子位於信義計畫區內房價水準很高","張先生的房子距離大安森林公園約50公尺條件很好","板橋埔墘生活圈生活機能很好","中正紀念堂周遭的房子有很好的價值條件"],"ok":[1],"ex":["「王小姐的房子位於信義計畫區內房價水準很高」是描述信義計畫區此一近鄰地區之整體房價水準，屬於區域因素之描述，此選項屬於區域因素，非本題答案（本題問「非屬」區域因素）。","「張先生的房子距離大安森林公園約50公尺」是描述該特定標的本身與公園之具體距離關係，屬於標的自身條件之個別因素，而非影響整個近鄰地區之區域因素，即本題正解。","「板橋埔墘生活圈生活機能很好」是描述特定生活圈（近鄰地區）之整體機能水準，屬於區域因素之描述。","「中正紀念堂周遭的房子有很好的價值條件」是描述中正紀念堂周遭此一近鄰地區之整體價值水準，屬於區域因素之描述。"],"tr":"","core":["描述信義計畫區整體房價＝區域","距公園50公尺是標的條件＝個別","描述生活圈整體機能＝區域因素","描述紀念堂周遭整體價值＝區域"],"hl":[[],["距離大安森林公園約50公尺","屬於標的自身條件之個別因素"],[],[]]},{"id":"h:114-13","p":"h","src":"114年第13題","sec":"A3","stem":"下列因素：①地區淹水　②捷運站設置　③利率變動　④離小學距離，那些是屬於影響不動產價格之區域因素？","opts":["①②","①③","②③④","①②③④"],"ok":[0],"ex":["①地區淹水是描述整個地區之共通淹水風險，影響近鄰地區整體不動產價值，屬區域因素；②捷運站設置同樣是影響周邊整個近鄰地區之區域因素，①②組合正確。","①地區淹水正確，但③利率變動屬全國性金融政策，是一般因素而非區域因素，組合錯誤。","②③④組合中，③利率變動是一般因素，④離小學距離是該標的本身之個別因素，皆非區域因素，僅②捷運站設置屬區域因素，組合錯誤過多。","①②③④全選，但③利率變動為一般因素、④離小學距離為個別因素，皆非區域因素，不應全部列入。"],"tr":"","core":["地區淹水、捷運設置皆屬區域因素","③利率變動是一般因素，非區域","③是一般、④是個別，皆非區域","③一般④個別，不應全選"],"hl":[[],["③利率變動屬全國性金融政策，是一般因素"],["③④","③利率變動是一般因素","④離小學距離是該標的本身之個別因素"],["③④","③利率變動為一般因素","④離小學距離為個別因素"]]},{"id":"h:114-14","p":"h","src":"114年第14題","sec":"A3","stem":"下列何者是個別因素之描述？","opts":["甲先生的房子位於重劃區內，房價水準很高","乙小姐的房子距捷運站距離大約50公尺","X大學特定區生活機能佳","大巨蛋球場完工，周圍不動產房價跟著起漲"],"ok":[1],"ex":["「甲先生的房子位於重劃區內，房價水準很高」是描述重劃區此一近鄰地區之整體房價水準，屬於區域因素之描述，非個別因素。","技術規則第2條第16款明定個別因素係不動產本身條件所產生之價格差異因素，「乙小姐的房子距捷運站距離大約50公尺」是該特定標的本身與捷運站之具體距離關係，屬於標的自身條件，符合個別因素定義。","「X大學特定區生活機能佳」是描述特定區（近鄰地區）之整體生活機能水準，屬於區域因素之描述。","「大巨蛋球場完工，周圍不動產房價跟著起漲」是描述周圍整個區域因重大建設完工而房價普遍上漲之現象，屬於影響近鄰地區整體之區域因素，非個別因素。"],"tr":"","core":["重劃區整體房價屬區域因素","距捷運站50公尺是標的條件＝個別","特定區生活機能屬區域因素","巨蛋帶動周圍房價屬區域因素"],"hl":[["位於重劃區內，房價水準很高","描述重劃區此一近鄰地區之整體房價水準"],[],["生活機能佳","描述特定區（近鄰地區）之整體生活機能水準"],["周圍不動產房價跟著起漲","影響近鄰地區整體之區域因素"]]},{"id":"h:99-29","p":"h","src":"99年第29題","sec":"A4","stem":"不動產估價作業程序中應確定之基本事項為：","opts":["委託人","勘察日期","估價條件","估價費用"],"ok":[2],"ex":["委託人是估價委託關係之當事人，並非技術規則第9條明定之估價基本事項項目（基本事項著重於估價本身的條件設定，委託人身分屬於委託關係範疇而非此處所列四項基本事項之一，但實務上仍會記載）。","勘察日期是赴現場調查之日期，技術規則明定基本事項中為「價格日期」而非「勘察日期」，二者不同。","技術規則第9條明定估價基本事項包含：勘估標的內容、價格日期、價格種類及條件（估價條件）、估價目的，「估價條件」是其中明定項目之一，與本選項相符。","估價費用是估價服務之對價，非技術規則明定應確定之估價基本事項項目。"],"tr":"","core":["委託人非明定之估價基本事項","基本事項是價格日期，非勘察日期","估價條件是明定之基本事項","估價費用非應確定之基本事項"],"hl":[["委託人","著重於估價本身的條件設定"],["勘察日期","價格日期"],[],["估價費用","非技術規則明定應確定之估價基本事項項目"]]},{"id":"h:101-8","p":"h","src":"101年第8題","sec":"A4","stem":"下列何者不屬於從事不動產估價前需確定之基本事項？","opts":["價格種類","勘察日期","勘估標的權利狀態","估價條件"],"ok":[1],"ex":["價格種類是技術規則第9條明定應確定之估價基本事項之一，非本題答案（本題問「不屬於」基本事項）。","技術規則第9條明定之基本事項為價格日期，而非勘察日期；勘察日期是赴現場調查之日期，屬於估價程序中「確認勘估標的狀態」階段的工作，非屬「確定基本事項」階段之項目，即本題正解。","勘估標的權利狀態屬於確定勘估標的內容之一環，是基本事項範疇。","估價條件是技術規則第9條明定之基本事項之一。"],"tr":"","core":["價格種類是明定之基本事項","基本事項是價格日期，非勘察日期","權利狀態屬勘估標的內容之一環","估價條件是明定之基本事項"],"hl":[[],["勘察日期","價格日期"],[],[]]},{"id":"h:101-9","p":"h","src":"101年第9題","sec":"A4","stem":"下列那些項目屬於不動產估價技術規則所指之勘估標的？①果樹　②房屋　③智慧財產權　④地上權　⑤租賃權","opts":["③④⑤","②③④⑤","①②④⑤","①②③④⑤"],"ok":[2],"ex":["依技術規則§2⑨，勘估標的是土地、建築改良物、農作改良物及其權利。①果樹是農作改良物（§109明列果樹），②房屋是建築改良物，兩者都是勘估標的。本選項漏掉①②，組合錯誤。","②③④⑤包含③智慧財產權，但智慧財產權非屬不動產估價技術規則所稱之勘估標的範圍（不動產估價著重於土地、建物及其權利，不含智慧財產權此類無形資產）。","依技術規則§2⑨，勘估標的包括土地、建築改良物、農作改良物及其權利：①果樹（農作改良物，§109）、②房屋（建物）、④地上權與⑤租賃權（權利，§114）都是；③智慧財產權不屬於不動產，所以是①②④⑤。","①②③④⑤全選，但③智慧財產權不屬於不動產估價技術規則所稱之勘估標的，不應列入。"],"tr":"","core":["漏掉①果樹②房屋，兩者都是標的","③智慧財產權非勘估標的","果樹房屋地上權租賃權皆為標的","③智慧財產權非勘估標的，不應列入"],"hl":[["③④⑤","勘估標的是土地、建築改良物、農作改良物及其權利"],["不含智慧財產權此類無形資產"],[],["智慧財產權不屬於不動產估價技術規則"]]},{"id":"h:101-10","p":"h","src":"101年第10題","sec":"A4","stem":"不動產估價所稱之價格日期係指：","opts":["接受委託估價之日期","赴勘估標的現場調查之日期","估價報告書提出之日期","估價報告書上勘估標的價格之日期"],"ok":[3],"ex":["接受委託估價之日期是估價委託關係成立之日期，並非技術規則所稱之價格日期。","赴勘估標的現場調查之日期是「勘察日期」，與價格日期定義不同。","估價報告書提出之日期是完成估價作業並提交報告之日期，並非價格基準日期本身。","技術規則§2⑦：「價格日期：指表示不動產價格之基準日期。」估價報告書依§16Ⅰ③必須載明價格日期，所以報告書上勘估標的價格所對應的日期就是價格日期，與本選項相符。"],"tr":"","core":["受託日期非價格日期","現場調查之日期是勘察日期","報告提出日期非價格基準日期","價格日期＝表示價格之基準日期"],"hl":[["接受委託估價之日期","估價委託關係成立之日期"],["赴勘估標的現場調查之日期","勘察日期"],["估價報告書提出之日期","完成估價作業並提交報告之日期"],[]]},{"id":"h:101-19","p":"h","src":"101年第19題","sec":"A4","stem":"都市計畫住宅區現供耕作使用之土地，其地價之查估應依下列何種使用價格查估？","opts":["農業用地","住宅用地","耕作用地","鄉村區用地"],"ok":[1],"ex":["依現況「農業用地」查估，不符合依法定用途／最有效使用估價的原則（教材；技術規則§2⑰最有效使用以合法為前提、§11①要求蒐集法定用途及使用管制資料）。本地的法定用途是住宅區，應依住宅用地查估。","都市計畫住宅區的土地雖然現在供耕作使用，法定使用分區仍是住宅區。依估價理論（教材）「依法定用途／最有效使用估價」的原則（技術規則§2⑰最有效使用以合法為前提；§11①要求蒐集勘估標的之法定用途及使用管制資料），應依住宅用地的價格查估，不是依現況耕作。","「耕作用地」並非都市計畫法定使用分區之正式名稱，且與依法定用途查估之原則不符。","「鄉村區用地」是非都市土地之使用分區類別，與本題都市計畫住宅區之情境不符。"],"tr":"","core":["依現況農用查估，不符依法定用途","法定為住宅區，依住宅用地查估","耕作用地非法定分區名稱","鄉村區屬非都市土地分區，不符"],"hl":[["農業用地","應依住宅用地查估"],[],["耕作用地","並非都市計畫法定使用分區之正式名稱"],["鄉村區用地","非都市土地之使用分區類別"]]},{"id":"h:101-38","p":"h","src":"101年第38題","sec":"A4","stem":"不動產估價為能確切掌握土地所有權、面積、土地界線及鄰地地號，應取得之資料為下列何者？","opts":["土地登記簿謄本及地籍圖","地籍圖及都市計畫圖","土地登記簿謄本及建物登記簿謄本","土地登記簿謄本及地形圖"],"ok":[0],"ex":["技術規則第13條要求確認勘估標的之基本資料及權利狀態：土地登記簿謄本記載所有權、他項權利及面積，地籍圖顯示土地界線及鄰地地號，兩者合併才能完整掌握，與題目相符。","都市計畫圖主要顯示土地使用分區管制，無法提供土地所有權及鄰地地號等具體產權資訊。","建物登記簿謄本記載建物產權狀態，與本題所問「土地」所有權、面積、界線及鄰地地號無直接關連。","地形圖主要呈現地表高低起伏狀況，無法提供土地所有權及鄰地地號等產權資訊。"],"tr":"","core":["謄本載權屬面積，地籍圖示界線鄰號","都市計畫圖示分區，無產權資訊","建物謄本與土地產權界線無關","地形圖示地表起伏，無產權資訊"],"hl":[[],["都市計畫圖","都市計畫圖主要顯示土地使用分區管制"],["建物登記簿謄本","建物登記簿謄本記載建物產權狀態"],["地形圖","地形圖主要呈現地表高低起伏狀況"]]},{"id":"h:102-22","p":"h","src":"102年第22題","sec":"A4","stem":"請問下列對價格日期的敘述，何者正確？","opts":["不動產價格的委託日期","不動產價格的基準日期","不動產價格的查估日期","不動產價格的交易日期"],"ok":[1],"ex":["委託日期是委託估價關係成立之日期，並非價格日期之定義。","技術規則第2條第7款明定價格日期係表示價格之基準日期，與本選項描述相符。","查估日期並非技術規則明定之正式用語，與價格日期定義不符。","交易日期是不動產實際成交之日期，與估價報告書所載價格之基準日期（價格日期）不同，兩者可能不一致。"],"tr":"","core":["委託日期非價格日期","價格日期＝價格之基準日期","查估日期非技術規則用語","交易日期是成交日，非基準日期"],"hl":[["委託日期","委託日期是委託估價關係成立之日期"],[],["查估日期","並非技術規則明定之正式用語"],["交易日期","交易日期是不動產實際成交之日期"]]},{"id":"h:102-29","p":"h","src":"102年第29題","sec":"A4","stem":"不動產估價由三大方法所推估之價值，於綜合決定勘估標的價格時，下列敘述何者錯誤？","opts":["屬於不動產估價程序之後段步驟","過程中應就其中金額顯著差異者重新檢討","應視不同價格所蒐集資料可信度及估價種類目的條件差異，考量價格形成因素之相近程度判斷","以經濟租金作為不動產證券化受益證券信託利益分配基礎者，折現現金流量分析之收益價格應視前項情形賦予相對較大之權重"],"ok":[3],"ex":["綜合決定勘估標的價格確實屬於不動產估價程序中較後段之步驟（蒐集資料、運用方法推算後才綜合決定），此敘述正確，非本題答案（本題問「何者錯誤」）。","技術規則第15條規定，對不同方法所得金額顯著差異者應重新檢討，此敘述正確。","技術規則第15條規定，應視資料可信度及估價種類目的條件差異，考量價格形成因素之相近程度決定價格，此敘述正確。","依技術規則第15條規定，係以「契約租金」（非經濟租金）作為不動產證券化受益證券信託利益分配基礎者，折現現金流量分析之收益價格才應賦予相對較大之權重，本選項誤植為「經濟租金」，與規則規定不符，即本題正解。"],"tr":"","core":["綜合決定價格屬程序後段步驟","金額顯著差異者應重新檢討","依資料可信度及因素相近程度判斷","應為契約租金，非經濟租金"],"hl":[[],[],[],["經濟租金","契約租金"]]},{"id":"h:102-32","p":"h","src":"102年第32題","sec":"A4","stem":"依不動產估價技術規則第7條規定：「依本規則辦理估價所稱之面積，已辦理登記者，以登記之面積為準；其未辦理登記或以部分面積為估價者，應調查註明之。」因此房地產買賣實價登錄時，如屬未登記建物，辦理申報登錄時，應如何辦理？","opts":["仍選擇房地合併申報","如有車位，則選擇房地加車位申報","單純以土地申報即可","以土地申報並應於備註欄註明之"],"ok":[3],"ex":["未登記建物無法併入房地合併申報，因建物本身尚未完成產權登記，無法以建物名義申報。","未登記建物之車位同樣面臨無產權登記問題，無法以房地加車位形式申報。","單純以土地申報雖可行，但技術規則第7條要求未登記或部分面積估價者應「調查註明」，僅以土地申報而未註明建物存在之事實，不完整。","技術規則第7條明定未辦理登記或以部分面積為估價者，應調查註明之，故未登記建物應以土地申報，並於備註欄註明建物存在之事實，與題目敘述及規則精神相符。"],"tr":"","core":["未登記建物無法房地合併申報","未登記車位無法房地加車位申報","僅土地申報未註明建物，不完整","以土地申報並於備註欄註明"],"hl":[["房地合併申報","未登記建物無法併入房地合併申報"],["房地加車位申報","無法以房地加車位形式申報"],["單純以土地申報即可","調查註明"],[]]},{"id":"h:102-35","p":"h","src":"102年第35題","sec":"A4","stem":"以下何者為不動產估價技術規則所稱之勘估標的？①地上權　②專利權　③蘋果樹上的蘋果　④堆置田中已採收之稻穀　⑤未登記建物","opts":["②③④","①②④","①②⑤","①③⑤"],"ok":[3],"ex":["②③④組合中含②專利權，非屬不動產估價技術規則所稱之勘估標的範圍。","①②④組合中含②專利權，同樣非屬勘估標的範圍。","①②⑤組合中含②專利權，非屬勘估標的範圍。","①地上權是權利（§114）。③蘋果樹上的蘋果尚未與土地分離，附著於農作改良物（§109；§111接近孳息成熟期者估計收穫量及市場價格）。⑤未登記建物仍是建物，只是要依§7調查註明面積。三者都在§2⑨勘估標的範圍內。②專利權不是不動產，④已採收的稻穀已與土地分離成為動產，都不是勘估標的。"],"tr":"","core":["含②專利權，非勘估標的","含②專利權，同樣非勘估標的","含②專利權，非勘估標的範圍","地上權、樹上蘋果、未登記建物皆是"],"hl":[["非屬不動產估價技術規則所稱之勘估標的範圍"],["非屬勘估標的範圍"],["非屬勘估標的範圍"],[]]},{"id":"h:102-38","p":"h","src":"102年第38題","sec":"A4","stem":"某房屋受地震損害經鑑定無法居住使用，下列估價原則何者較能掌握其房地價格？","opts":["先估計重建價格，再以重建後房地價格扣掉重建所花費金額","以素地價格估價，並扣除拆除建物費用","以比較法估計一般正常未受損價格，再以特殊情況調整","無法估價"],"ok":[1],"ex":["「先估計重建價格，再以重建後房地價格扣掉重建所花費金額」此一邏輯混亂且非技術規則規定之標準作法，無法妥適反映已嚴重毀損無法居住之房屋現況價值。","房屋因地震受損、經鑑定無法居住，建物已不具備使用價值。依技術規則§106：「建物已不具備使用價值，得將其基地視為素地估價。但應考量建物拆除成本予以調整之。」所以以素地價格估價並扣除拆除費用。","以比較法估計一般正常未受損價格，再以特殊情況調整，此方法未能精確反映建物已無法居住使用、實質上已無建物價值之現況，估價邏輯不夠精確。","受損房屋仍可依素地估價搭配拆除成本調整之方式進行估價，並非無法估價。"],"tr":"","core":["扣重建費邏輯混亂，非標準作法","以素地估價並扣除拆除成本","未反映已無建物價值之現況","可依素地扣拆除成本估價"],"hl":[["先估計重建價格"],[],["一般正常未受損價格","建物已無法居住使用、實質上已無建物價值"],["無法估價","仍可依素地估價搭配拆除成本調整之方式進行估價"]]},{"id":"h:103-1","p":"h","src":"103年第1題","sec":"A4","stem":"何者是地價區段內具代表性，以作為查估公共設施保留地毗鄰非公共設施保留地區段地價之宗地？","opts":["基準地","比準地","標準地","比較標的"],"ok":[1],"ex":["「基準地」不是本題所問宗地的名稱。已核實的三部法規（技術規則、地價調查估計規則、土地徵收補償市價查估辦法）都沒有用這個詞稱呼此種宗地；最接近的是地價調查估計規則§21Ⅰ②的「基準地價區段」，那是已估出區段地價、供修正無實例區段用的「區段」，不是宗地。","依土地徵收補償市價查估辦法§2②：比準地指地價區段內具代表性，以作為查估地價區段內各宗土地市價比較基準之宗地，或作為查估公共設施保留地毗鄰非公共設施保留地區段地價之宗地。題目問的正是第二種用途（辦法§22：公共設施保留地區段地價，以毗鄰非保留地區段的比準地地價為基礎加權平均）。","「標準地」在技術規則、地價調查估計規則、土地徵收補償市價查估辦法的全文中都沒有出現，不是此處用語。","比較標的（技術規則§2⑩）是可供與勘估標的比較的標的、即交易實例。辦法§19 是在同一地價區段內選一至三件比較標的，調整個別因素後去「推估比準地試算價格」，所以比較標的是用來估比準地的材料，不是比準地本身。"],"tr":"","core":["基準地非此種宗地之法規用語","公設保留地毗鄰區段代表宗地＝比準地","標準地不是此處法規用語","比較標的是估比準地的材料"],"hl":[["基準地","基準地價區段"],[],["標準地","全文中都沒有出現"],["比較標的","可供與勘估標的比較的標的、即交易實例"]]},{"id":"h:103-12","p":"h","src":"103年第12題","sec":"A4","stem":"確認勘估標的狀態時，應至現場勘察之事項，何者有誤？","opts":["確定勘估標的內容","確認勘估標的之基本資料及權利狀態","調查勘估標的及比較標的之使用現況","確認影響價格之各項資料"],"ok":[0],"ex":["「確定勘估標的內容」是屬於技術規則第9條「確定估價基本事項」階段之工作項目，並非「確認勘估標的狀態」階段應至現場勘察之事項，本選項階段歸屬有誤，即本題正解（本題問「何者有誤」）。","確認勘估標的之基本資料及權利狀態，是技術規則第13條明定確認勘估標的狀態時應至現場勘察之正確事項。","調查勘估標的及比較標的之使用現況，是現場勘察應辦理之正確事項。","確認影響價格之各項資料，是現場勘察應辦理之正確事項。"],"tr":"","core":["確定標的內容屬確定基本事項階段","基本資料及權利狀態屬現場勘察事項","調查標的及比較標的使用現況","確認影響價格之各項資料"],"hl":[["確定勘估標的內容","「確定估價基本事項」階段之工作項目"],[],[],[]]},{"id":"h:103-14","p":"h","src":"103年第14題","sec":"A4","stem":"依不動產估價技術規則之規定，不動產估價師應經常蒐集何者之相關交易、收益及成本等案例及資料，並詳予求證其可靠性？","opts":["勘估標的","比較標的","買賣標的","估價標的"],"ok":[1],"ex":["「勘估標的」是待估價的標的本身，不是蒐集案例資料的對象；§4 蒐集的是可供比較的案例。","§4Ⅰ 原文：不動產估價師應經常蒐集「比較標的」相關交易、收益及成本等案例及資料，並詳予求證其可靠性。本題考選部標準答案為 B（103 年答案表第 14 題），與條文一致。§4Ⅱ：資料得向當事人、四鄰、其他不動產估價師、不動產經紀人員、地政士、地政機關、金融機構、公有土地管理機關、司法機關、媒體或有關單位蒐集。","「買賣標的」不是技術規則用語；§4 的用語是「比較標的」。（本站舊版曾誤標此項為答案，已依考選部答案表更正。）","「估價標的」不是技術規則 §4 的用語。"],"tr":"","core":["勘估標的是待估標的，非蒐集對象","應經常蒐集比較標的之案例資料","買賣標的非技術規則用語","估價標的非技術規則用語"],"hl":[["勘估標的","§4 蒐集的是可供比較的案例"],[],["買賣標的","§4 的用語是「比較標的」"],["估價標的"]]},{"id":"h:103-29","p":"h","src":"103年第29題","sec":"A4","stem":"不動產估價作業程序中應確定之基本事項為：","opts":["委託人","勘察日期","估價費用","估價條件"],"ok":[3],"ex":["委託人雖為委託關係之當事人，但技術規則第9條明定之四項基本事項並未單獨列出「委託人」一項作為核心基本事項內容（委託人身分屬於委託契約範疇）。","勘察日期是赴現場調查之日期，技術規則第9條明定的是「價格日期」而非勘察日期。","估價費用是估價服務之對價，非技術規則明定應確定之估價基本事項項目。","技術規則第9條明定估價基本事項包含勘估標的內容、價格日期、價格種類及條件（估價條件）、估價目的，「估價條件」是其中明定項目之一，與題目敘述相符。"],"tr":"","core":["委託人非明定之估價基本事項","基本事項是價格日期，非勘察日期","估價費用非應確定之基本事項","估價條件是明定之基本事項"],"hl":[["委託人","委託人身分屬於委託契約範疇"],["勘察日期","價格日期"],["估價費用","非技術規則明定應確定之估價基本事項項目"],[]]},{"id":"h:104-8","p":"h","src":"104年第8題","sec":"A4","stem":"下列有關不動產估價三大基本方法之敘述，何者正確？","opts":["比較法運用重置觀點得出比較價格","收益法運用投資觀點得出收益價格","成本法運用未來成本得出成本價格","比較法運用交易觀點得出成交價格"],"ok":[1],"ex":["比較法運用「交易觀點」（非重置觀點）得出比較價格，本選項將觀點誤植，敘述錯誤。","收益法運用投資觀點，求取未來收益折現或資本化後得出收益價格，與題目敘述完全相符。","成本法運用「重置觀點」（求取重建或重置成本扣除折舊），而非「未來成本」概念，本選項用詞錯誤。","比較法運用交易觀點得出的是「比較價格」，而非「成交價格」，成交價格是實際交易發生之價格，與估價方法所得之比較價格性質不同，本選項用詞錯誤。"],"tr":"","core":["比較法是交易觀點，非重置觀點","收益法以投資觀點得收益價格","成本法是重置觀點，非未來成本","交易觀點得出比較價格，非成交價格"],"hl":[["重置觀點","交易觀點"],[],["未來成本","重置觀點"],["成交價格","比較價格"]]},{"id":"h:104-27","p":"h","src":"104年第27題","sec":"A4","stem":"不動產估價作業程序包含下列8項，請問其正確程序為何？①確定估價基本事項　②擬定估價計畫　③確認勘估標的狀態　④蒐集資料　⑤整理、比較、分析資料　⑥決定勘估標的價格　⑦運用估價方法推算勘估標的價格　⑧製作估價報告書","opts":["①②③④⑤⑥⑦⑧","①②④③⑤⑥⑦⑧","①②③④⑤⑦⑥⑧","①②④③⑤⑦⑥⑧"],"ok":[3],"ex":["①②③④⑤⑥⑦⑧此順序將③確認勘估標的狀態置於④蒐集資料之前，且⑥決定價格置於⑦運用估價方法之前，皆與正確的8步驟順序不符。","①②④③⑤⑥⑦⑧此順序中，⑥決定勘估標的價格置於⑦運用估價方法推算價格之前，順序顛倒，應先運用方法推算（⑦）才能決定價格（⑥），不符正確邏輯。","①②③④⑤⑦⑥⑧此順序將③確認勘估標的狀態置於④蒐集資料之前，順序錯誤（應先蒐集資料才能確認標的狀態）。","技術規則第8條明定8大程序為：①確定估價基本事項→②擬定估價計畫→④蒐集資料→③確認勘估標的狀態→⑤整理比較分析資料→⑦運用估價方法推算價格→⑥決定勘估標的價格→⑧製作估價報告書，與本選項①②④③⑤⑦⑥⑧之順序完全相符。"],"tr":"","core":["③④順序及⑥⑦順序皆顛倒","應先⑦推算方法再⑥決定價格","③④順序錯，應先蒐集資料","先蒐集④再確認③，先推算⑦再決定⑥"],"hl":[["③④"],["⑥⑦","應先運用方法推算（⑦）才能決定價格（⑥）"],["③④","應先蒐集資料才能確認標的狀態"],[]]},{"id":"h:104-38","p":"h","src":"104年第38題","sec":"A4","stem":"下列有關土地建築開發之直接成本及間接成本之敘述，何者正確？①直接成本係指營造或施工費　②規劃設計費、廣告費、銷售費皆為間接成本　③直接成本包含規劃設計費　④間接成本不包含銷售費","opts":["②③","①②","①④","③④"],"ok":[1],"ex":["③錯：規劃設計費是間接成本。","直接成本指營造或施工費（①對）；規劃設計費、廣告費、銷售費等屬間接成本（②對），與本選項相符。","④錯：銷售費屬於間接成本。","③④都錯。"],"tr":"","core":["③錯，規劃設計費是間接成本","直接成本＝營造施工費，設計廣告銷售屬間接","④錯，銷售費屬於間接成本","③④都錯"],"hl":[["規劃設計費是間接成本"],[],["銷售費屬於間接成本"],["③④"]]},{"id":"h:105-4","p":"h","src":"105年第4題","sec":"A4","stem":"於不動產估價作業程序中，下列何者不屬於「確定估價基本事項」的內容？","opts":["估價方法","價格日期","價格種類及條件","估價目的"],"ok":[0],"ex":["技術規則第9條明定之估價基本事項為勘估標的內容、價格日期、價格種類及條件、估價目的，並不包含「估價方法」此一項目（估價方法屬於後續運用估價程序中決定的事項，非事前確定之基本事項），即本題正解。","價格日期是技術規則第9條明定之基本事項之一，非本題答案（本題問「不屬於」基本事項）。","價格種類及條件是規則明定之基本事項之一。","估價目的是規則明定之基本事項之一。"],"tr":"","core":["估價方法非基本事項，屬後續程序決定","價格日期是法定基本事項之一","價格種類及條件是基本事項之一","估價目的是基本事項之一"],"hl":[["估價方法","估價方法屬於後續運用估價程序中決定的事項"],[],[],[]]},{"id":"h:105-13","p":"h","src":"105年第13題","sec":"A4","stem":"地政機關辦理公告土地現值之估價方法，其主要之法令依據為：","opts":["地價調查估計規則","不動產估價技術規則","土地徵收補償市價查估辦法","土地建築改良物估價規則"],"ok":[0],"ex":["地政機關辦理公告土地現值之估價方法，主要法令依據為地價調查估計規則，與不動產估價技術規則（適用於估價師受託估價）係不同法令體系，題目敘述相符。","不動產估價技術規則是適用於不動產估價師受託辦理民間估價業務之規範，並非地政機關辦理公告土地現值之主要法令依據。","土地徵收補償市價查估辦法是適用於土地徵收補償市價查估之專門法令，非公告土地現值估價之主要依據。","「土地建築改良物估價規則」並非地政機關辦理公告土地現值之主要法令依據。"],"tr":"","core":["公告土地現值依地價調查估計規則","技術規則規範估價師受託估價，非公告現值","徵收市價查估辦法專用於徵收補償","此規則非公告土地現值主要依據"],"hl":[[],["不動產估價技術規則","適用於不動產估價師受託辦理民間估價業務之規範"],["土地徵收補償市價查估辦法","適用於土地徵收補償市價查估之專門法令"],["土地建築改良物估價規則","並非地政機關辦理公告土地現值之主要法令依據"]]},{"id":"h:105-22","p":"h","src":"105年第22題","sec":"A4","stem":"依不動產估價技術規則之規定，下列何者並非由不動產估價師公會全國聯合會公告？","opts":["建物經濟耐用年數表","建築改良物標準單價表","營造或施工費標準表","廣告費、銷售費、管理費及稅捐之相關費率"],"ok":[1],"ex":["建物經濟耐用年數表（§66）是技術規則明定由不動產估價師公會全國聯合會公告之項目，非本題答案（本題問「並非」由全聯會公告）。","建築改良物標準單價表由直轄市或縣（市）政府發布（地價調查估計規則§24Ⅰ③；技術規則§56Ⅲ也只說全聯會「未公告前」才以它為準），不是全聯會公告，所以是本題正解。全聯會公告的項目見§82總列：§56營造或施工費標準表、§60利潤率、§61與§77廣告費、銷售費、管理費及稅捐費率、§63建物工程進度營造費用比例表、§66建物經濟耐用年數表、§67殘餘價格率。","營造或施工費標準表（§56Ⅲ）是技術規則明定由全聯會公告之項目。","廣告費、銷售費、管理費及稅捐之相關費率，屬§61、§77所定由全聯會公告之費率項目。"],"tr":"","core":["經濟耐用年數表由全聯會公告","標準單價表由直轄市縣市政府發布","營造或施工費標準表由全聯會公告","廣告銷售管理稅捐費率由全聯會公告"],"hl":[[],["建築改良物標準單價表","由直轄市或縣（市）政府發布"],[],[]]},{"id":"h:105-25","p":"h","src":"105年第25題","sec":"A4","stem":"有關市地重劃估價的敘述，下列何者錯誤？","opts":["相關法令未明定重劃前後地價查估之價格日期","重劃前之地價應分別估計各宗土地地價及區段價","重劃後之地價應估計重劃後各路街之路線價或區段價","估計重劃前後地價應提地價評議委員會評定"],"ok":[1],"ex":["正確。市地重劃實施辦法§20 只規定「應依下列規定查估後，提請地價評議委員會評定」，並未訂明重劃前後地價的價格日期，條文也沒有授權另訂。本選項不是答案。","★本題正解（錯在多了「及區段價」）。市地重劃實施辦法§20①：重劃前之地價應先調查土地位置、地勢、交通、使用狀況、買賣實例及當期公告現值等資料，「分別估計重劃前各宗土地地價」——只估各宗土地地價，沒有區段價。路線價與區段價是§20②「重劃後」才有的。前後對調是本題唯一陷阱：重劃前＝逐宗；重劃後＝路街（路線價或區段價）。","正確。市地重劃實施辦法§20②：重劃後之地價應參酌各街廓土地之位置、地勢、交通、道路寬度、公共設施、土地使用分區及重劃後預期發展情形，估計重劃後「各路街之路線價或區段價」，與本選項相符。","正確。市地重劃實施辦法§20 前導句：「重劃前後之地價應依下列規定查估後，提請地價評議委員會評定之」。"],"tr":"","core":["法令未明定重劃前後地價之價格日期","重劃前只估各宗地價，區段價是重劃後","重劃後估各路街之路線價或區段價","重劃前後地價查估後提地評會評定"],"hl":[[],["及區段價","各宗土地地價"],[],[]]},{"id":"h:105-35","p":"h","src":"105年第35題","sec":"A4","stem":"下列何種估價方法，係以未來期望利益計算不動產價值？","opts":["成本法","收益法","比較法","土地開發分析法"],"ok":[1],"ex":["成本法是以重建或重置成本扣除折舊推算價格，著重於「過去投入成本」而非未來期望利益，與題目敘述不符。","技術規則明定收益法係以勘估標的未來平均一年期間之客觀淨收益除以收益資本化率，或以折現現金流量分析法估算未來各期收益，本質上是以未來期望利益計算不動產價值，與題目敘述完全相符。","比較法是以比較標的之交易價格為基礎，著重於「市場已實現之交易價格」而非未來期望利益。","土地開發分析法雖也涉及未來銷售金額之估算，但其核心是扣除開發成本及利潤後求得當前土地價值，非單純「未來期望利益」之資本化計算。"],"tr":"","core":["成本法看過去投入成本，非未來利益","收益法以未來淨收益資本化或折現","比較法看市場已實現之交易價格","土地開發分析法扣成本利潤求現值"],"hl":[["成本法","以重建或重置成本扣除折舊推算價格"],[],["比較法","以比較標的之交易價格為基礎"],["土地開發分析法","扣除開發成本及利潤後求得當前土地價值"]]},{"id":"h:106-3","p":"h","src":"106年第3題","sec":"A4","stem":"依不動產估價技術規則第7條規定：「依本規則辦理估價所稱之面積，已辦理登記者，以登記之面積為準」但未辦理登記或以部分面積為估價者，應如何處理？","opts":["省略不處理","先探求未登記之原因","當作無價值","調查註明"],"ok":[3],"ex":["技術規則第7條明定未登記或部分面積估價者應「調查註明」，並非省略不處理。","技術規則第7條僅規定應調查註明，並未要求先探求未登記之原因，本選項超出規則規定範圍。","技術規則並未規定未登記面積應當作無價值處理，此與規則精神不符。","技術規則第7條明定：未辦理登記或以部分面積為估價者，應調查註明之，與題目敘述完全相符。"],"tr":"","core":["應調查註明，非省略不處理","規則只要求調查註明，無須探求原因","未登記面積未規定當作無價值","未登記或部分面積應調查註明"],"hl":[["省略不處理","調查註明"],["先探求未登記之原因","僅規定應調查註明"],["當作無價值"],[]]},{"id":"h:106-21","p":"h","src":"106年第21題","sec":"A4","stem":"已開闢道路及其二側或一側帶狀土地，可就具有顯著商業活動之繁榮地區，依當地發展及地價高低情形而劃設為下列那二種地價區段？","opts":["住宅價區段與商業價區段","商業價區段與非商業價區段","基準地價區段與標準地價區段","繁榮街道路線價區段與一般路線價區段"],"ok":[3],"ex":["「住宅價區段與商業價區段」並非地價調查估計規則§18 明定之地價區段名稱。","「商業價區段與非商業價區段」並非正式之地價區段劃分名稱。","「基準地價區段與標準地價區段」並非本題所問已開闢道路依繁榮程度劃設之地價區段正式名稱。","依地價調查估計規則§18Ⅱ：已開闢道路及其二側或一側帶狀土地，其地價與一般地價區段顯著差異者，得就具有顯著商業活動之繁榮地區，依當地發展及地價高低情形劃設「繁榮街道路線價區段」；繁榮街道以外已開闢之道路，鄰接該道路之土地地價顯著較高者，得於適當範圍劃設「一般路線價區段」，此為兩種路線價區段之正式名稱，與題目敘述相符。"],"tr":"","core":["住宅價與商業價區段非法定名稱","商業與非商業價區段非正式名稱","基準與標準地價區段非本題名稱","繁榮街道路線價區段與一般路線價區段"],"hl":[["住宅價區段與商業價區段","並非地價調查估計規則§18 明定之地價區段名稱"],["商業價區段與非商業價區段","並非正式之地價區段劃分名稱"],["基準地價區段與標準地價區段"],[]]},{"id":"h:106-25","p":"h","src":"106年第25題","sec":"A4","stem":"初入社會的陳君預計在往後10年，每年有10萬元的償債能力，假設此時銀行利率為3%，請問其可貸得金額為何？","opts":["134,390元","457,970元","853,020元","1,145,390元"],"ok":[2],"ex":["134,390元＝10萬×1.3439，那是複利終值（把一筆錢滾 10 年），方向相反。","457,970元＝10萬×[1－1.03⁻⁵]÷3%，是把期數錯用成5年的年金現值；本題是10年。","★正解。年金現值：每年一筆 10 萬、連續 10 年，折回現在。\n係數＝[1－(1.03)⁻¹⁰]÷0.03＝(1－0.74409)÷0.03＝8.5302；10 萬×8.5302≈853,020 元。\n白話：每年只還得起 10 萬、還 10 年，3% 利率下現在最多借 85.3 萬。","1,145,390元最接近年金終值：10萬×[(1.03)¹⁰－1]÷3%＝1,146,388元，是把每年10萬滾到第10年末的終值，方向相反。這個數字與精確值差約1千元，無法由題幹常見誤算精確得到，認出它是「終值」量級就能排除。"],"tr":"","core":["134,390是複利終值，方向相反","457,970是誤用5年期年金現值","年金現值10萬×8.5302≈853,020","1,145,390近年金終值，方向相反"],"hl":[["134,390元","複利終值"],["457,970元","是把期數錯用成5年的年金現值"],[],["1,145,390元","年金終值"]]},{"id":"h:106-39","p":"h","src":"106年第39題","sec":"A4","stem":"有關不動產價值的定義，下列何者正確？","opts":["保險價值是不動產用於某種特定壽險用途所產生之價值","營運價值係指特定投資人評估該不動產投資所能產生的主觀價值","市場價值是不動產在營運過程中的既有價值，它是整個企業的一部分","公允價值係指能瞭解實情、有意願之當事人間公平交易所議定之資產交換或還清債務之數額"],"ok":[3],"ex":["保險價值通常指用於保險理賠目的所評估之重置成本相關價值，並非「用於某種特定壽險用途所產生之價值」，本選項定義與保險價值之一般概念不符。","營運價值（或稱企業價值之不動產部分）通常指不動產作為企業整體營運資產之一部分所產生的價值，並非「特定投資人評估之主觀價值」，本選項定義有誤。","市場價值是反映公開市場上買賣雙方合理交易所形成之價值，並非「不動產在營運過程中的既有價值，是整個企業的一部分」，本選項描述的其實更接近營運價值之概念，與市場價值定義不符。","公允價值指「能瞭解實情、有意願之當事人間，公平交易所議定之資產交換或清償債務之數額」，這是估價理論（教材）沿用的舊版國際會計準則定義，與本選項相符（現行 IFRS 13 改以市場參與者在有秩序交易中的出售價格定義，作答時照題目文字判斷即可）。"],"tr":"","core":["保險價值指保險理賠目的之價值","營運價值是企業整體營運資產之價值","市場價值是公開市場合理交易價值","公允價值＝知情有意願者公平交易數額"],"hl":[["特定壽險用途","用於保險理賠目的所評估之重置成本相關價值"],["特定投資人評估","指不動產作為企業整體營運資產之一部分所產生的價值"],["營運過程中的既有價值","反映公開市場上買賣雙方合理交易所形成之價值"],[]]},{"id":"h:107-11","p":"h","src":"107年第11題","sec":"A4","stem":"下列那一項不屬於土地建築開發之間接成本？","opts":["施工費","規劃設計費","銷售費","管理費"],"ok":[0],"ex":["技術規則第76條明定直接成本＝營造施工費（施工費），施工費是直接投入工程本身之成本，屬於直接成本而非間接成本，即本題正解（本題問「不屬於」間接成本）。","規劃設計費依規則明定屬於間接成本之一項。","銷售費依規則明定屬於間接成本之一項（廣告銷售費）。","管理費依規則明定屬於間接成本之一項。"],"tr":"","core":["施工費是直接成本，非間接成本","規劃設計費屬間接成本","銷售費屬間接成本","管理費屬間接成本"],"hl":[["施工費","施工費是直接投入工程本身之成本，屬於直接成本"],[],[],[]]},{"id":"h:108-8","p":"h","src":"108年第8題","sec":"A4","stem":"對於估價目的為不動產買賣交易之參考所為之不動產估價，應評估的價格為：","opts":["買方希望之價格","賣方希望之價格","市場中最可能之成交價格","買賣雙方希望價格之平均數"],"ok":[2],"ex":["買方希望之價格僅反映單方主觀期望，並非市場客觀交易價格，不適合作為買賣交易參考之估價結論。","賣方希望之價格同樣僅反映單方主觀期望，不適合作為客觀估價結論。","估價目的為不動產買賣交易之參考時，應評估市場中最可能之成交價格（即正常價格概念之具體應用），反映買賣雙方在公開市場上依專業知識謹慎行動可能達成之合理交易價格，與題目敘述相符。","買賣雙方希望價格之簡單平均數，未必反映市場實際供需與合理交易條件，並非正確之估價方法論。"],"tr":"","core":["買方希望價只反映單方主觀期望","賣方希望價只反映單方主觀期望","買賣參考應評估市場最可能成交價","雙方希望價平均未必反映市場供需"],"hl":[["買方希望之價格","並非市場客觀交易價格"],["賣方希望之價格","不適合作為客觀估價結論"],[],["買賣雙方希望價格之平均數","未必反映市場實際供需與合理交易條件"]]},{"id":"h:108-22","p":"h","src":"108年第22題","sec":"A4","stem":"下列何者非屬不動產估價師受理委託估價之勘估標的？","opts":["土地及其權利估價","建築改良物及其權利估價","不動產租金估計","不動產稅負之估算"],"ok":[3],"ex":["土地及其權利估價，是不動產估價師依估價師法明定之核心業務範圍，非本題答案（本題問「非屬」受理委託估價之勘估標的）。","建築改良物及其權利估價，同樣是估價師明定業務範圍之一。","不動產租金估計，依技術規則第八章（租金估計）規定，亦屬估價師受理委託估價之業務範圍之一。","不動產稅負之估算（如試算應納地價稅、土地增值稅等稅額）屬於稅務計算範疇，非不動產估價師依估價師法及技術規則明定之估價業務範圍（稅負試算通常屬地政士或會計師之專業範疇），即本題正解。"],"tr":"","core":["土地及其權利估價屬估價師業務","建物及其權利估價屬估價師業務","不動產租金估計屬估價師業務","稅負估算屬稅務計算，非估價業務"],"hl":[[],[],[],["不動產稅負之估算","屬於稅務計算範疇"]]},{"id":"h:108-23","p":"h","src":"108年第23題","sec":"A4","stem":"不動產估價師在收集比較標的相關交易等案例及資料時，得向當事人、四鄰、其他不動產估價師、不動產經紀人員、地政士、地政機關、金融機構、公地管理機關、司法機關、媒體或有關單位收集之。請問：到實價登錄系統查詢交易案例相關資訊，屬向何者收集資料？","opts":["不動產經紀人","地政士","地政機關","媒體"],"ok":[2],"ex":["不動產經紀人是提供仲介或代銷服務之專業人員，並非實價登錄系統之管轄或建置單位。","地政士是辦理土地登記代理業務之專業人員，並非實價登錄系統之管轄單位。","實價登錄系統是由地政機關（內政部及地方地政機關）建置管理之官方交易資訊申報登錄系統，到此系統查詢交易案例資訊，性質上屬於向「地政機關」收集資料，與技術規則第4條明定得向地政機關蒐集資料之規定相符。","媒體通常指新聞報導等公開資訊來源，實價登錄系統屬官方申報登錄資料庫，非媒體性質之資訊來源。"],"tr":"","core":["經紀人非實價登錄系統建置單位","地政士非實價登錄系統管轄單位","實價登錄由地政機關建置管理","實價登錄是官方資料庫，非媒體"],"hl":[["不動產經紀人","並非實價登錄系統之管轄或建置單位"],["地政士","並非實價登錄系統之管轄單位"],[],["媒體","實價登錄系統屬官方申報登錄資料庫"]]},{"id":"h:109-3","p":"h","src":"109年第3題","sec":"A4","stem":"進行宗地估價時，下列敘述何者錯誤？","opts":["以分割為前提之宗地估價，應考慮分割前與分割後之價格變動情形，而予酌量增減","數筆土地合併為一宗進行土地利用之估價，應以合併後土地估價，並以合併前各筆土地價值比例分算其土地價格","一宗土地內有數種不同法定用途時，應考量其最有效使用及各種用途之相關性及分割之難易度後，決定分別估價或依主要用途估價","土地之上下有其他設施通過，致使用受限制之宗地，應先估算其特定價格，再考量該設施通過造成土地利用之影響，並計算其地價減損額後，從特定價格中扣除之，以其餘額為該宗地之價格"],"ok":[3],"ex":["技術規則第83條明定，以分割為前提之宗地估價，應考慮分割前後之價格變動情形酌量增減，此為正確敘述，非本題答案（本題問「何者錯誤」）。","技術規則第84條明定，數筆土地合併為一宗估價，應以合併後土地估價，並以合併前各筆土地價值比例分算其土地價格，此為正確敘述。","技術規則第85條明定，一宗土地內有數種不同法定用途時，應考量最有效使用及各用途相關性與分割難易度，決定分別估價或依主要用途估價，此為正確敘述。","技術規則第88條規定土地上下有其他設施通過致使用受限制之宗地，應「先估算其『正常價格』」（而非特定價格），再扣除地價減損額；本選項將正常價格誤植為特定價格，此為錯誤敘述，即本題正解。"],"tr":"","core":["分割前提應考慮分割前後價格變動","合併後估價，依合併前價值比例分算","數種用途看最有效使用等再決定","應先估正常價格，非特定價格"],"hl":[[],[],[],["特定價格","正常價格"]]},{"id":"h:109-7","p":"h","src":"109年第7題","sec":"A4","stem":"某大樓座落於原為住宅區變更為商業區之土地，依據目前土地使用管制相關法令規定，該大樓應以商業與一般事務所為其法定用途，今勘估標的某層建物未變更為商業區前之原核定用途為住宅使用，請問勘估標的之估價處理方式，下列何者較為適當？","opts":["以現行商業區允許之商業與一般事務所估價，並於估價報告書中敘明","以現行商業區允許之商業與一般事務所估價，並就住宅用途與建物法定用途估價之差額於估價報告書中敘明","以原核定住宅用途估價，並於估價報告書中敘明","以現行商業區允許之商業與一般事務所估價，同時以原核定住宅用途估價，再以兩者平均數為估價結論，並於估價報告書中敘明"],"ok":[1],"ex":["僅以現行商業區允許之用途估價，未敘明原核定住宅用途與現行用途間之差額影響，未完整反映技術規則第105條（原核定用途與現行土地使用管制不符之合法建物）規定的處理原則。","技術規則第105條明定，原核定用途與現行土地使用管制不符之合法建物，應以現行管制允許用途估價，並敘明該用途與原核定用途間之差額，此選項完整描述了「以現行用途估價」並「敘明差額」兩個要件，與規則規定完全相符。","僅以原核定住宅用途估價，未依現行（商業區）管制之允許用途估價，與技術規則第105條「應以現行管制允許用途估價」之原則不符。","將兩種用途估價結果平均作為結論，並非技術規則規定之正確估價方法，規則明定應以現行用途估價並敘明差額，而非簡單平均。"],"tr":"","core":["只以現行用途估，未敘明差額影響","以現行用途估價並敘明與原用途差額","只用原核定住宅用途，不符現行管制","兩用途平均非規則所定方法"],"hl":[["並於估價報告書中敘明"],[],["以原核定住宅用途估價","應以現行管制允許用途估價"],["兩者平均數","應以現行用途估價並敘明差額"]]},{"id":"h:110-19","p":"h","src":"110年第19題","sec":"A4","stem":"勘估標的若為未完工之建物，應依何種方式估價？","opts":["未完工之建物應依比準建物進行估價","未完工之建物應依實際完成部分估價","未完工之建物應待完工後再進行估價","未完工之建物無法產生正常報酬，不予估計"],"ok":[1],"ex":["「比準建物」並非技術規則明定處理未完工建物之估價方法，此為混淆選項。","技術規則第63條明定未完工建物估價，應依實際完成部分估價，或以營造施工費標準表參考工程進度比例估算，與題目敘述相符。","未完工建物可依實際完成部分進行估價，並非須待完工後才能進行估價。","未完工建物雖未完工，但已投入之部分仍具經濟價值，並非無法估計，規則明定應依實際完成部分估價。"],"tr":"","core":["比準建物非未完工建物估價方法","未完工建物依實際完成部分估價","可依完成部分估價，不必待完工","已投入部分有價值，應依完成部分估"],"hl":[["比準建物","並非技術規則明定處理未完工建物之估價方法"],[],["待完工後再進行估價","可依實際完成部分進行估價"],["無法產生正常報酬，不予估計","應依實際完成部分估價"]]},{"id":"h:111-4","p":"h","src":"111年第4題","sec":"A4","stem":"依據不動產估價技術規則之規定，在一宗土地內有不同法定用途時，應如何估價？","opts":["應考量不同用途之合併或分割前後之價格變動情形，予酌量增減","應以合併用途後估價，並以合併用途前各筆土地價值比例分算其土地價格","應考慮不同用途之建築物對宗地價格造成之影響，予以酌量增減","應考量其最有效使用及各種用途之相關性及分割之難易度後，決定分別估價或依主要用途估價"],"ok":[3],"ex":["「合併或分割前後之價格變動情形」是技術規則第83條規範分割或合併前提宗地估價之原則，而非本題所問「一宗土地內有不同法定用途」之處理方式，本選項答非所問。","「應以合併用途後估價，並以合併用途前各筆土地價值比例分算」是技術規則第84條規範「數筆土地合併」之原則，而非「一宗土地內有不同法定用途」此一情境之處理方式。","「考慮建築物對宗地價格造成之影響」改寫自技術規則§86（附有建物之宗地估價），不是§85規範「一宗土地內有數種不同法定用途」的處理方式，答非所問。","技術規則第85條明定，一宗土地內有數種不同法定用途時，應考量最有效使用及各種用途之相關性及分割難易度後，決定分別估價或依主要用途估價，與題目敘述完全相符。"],"tr":"","core":["分割合併前後價格變動是§83情境","合併後估價比例分算是§84情境","建物對宗地價格影響是§86情境","考量最有效使用等決定分別或主要用途"],"hl":[["合併或分割前後之價格變動情形","技術規則第83條規範分割或合併前提宗地估價之原則"],["合併用途後估價","技術規則第84條規範「數筆土地合併」之原則"],["建築物對宗地價格造成之影響","改寫自技術規則§86（附有建物之宗地估價）"],[]]},{"id":"h:111-8","p":"h","src":"111年第8題","sec":"A4","stem":"不動產估價作業程序依不動產估價技術規則規定，總共有八項作業程序，其中第七個步驟為何？","opts":["製作估價報告書","整理、比較、分析資料","運用估價方法推算勘估標的價格","決定勘估標的價格"],"ok":[3],"ex":["製作估價報告書是8步驟中的第⑧（最後）步驟，非第七步驟。","整理、比較、分析資料是8步驟中的第⑤步驟，非第七步驟。","運用估價方法推算勘估標的價格是§8八步驟中的第⑥步驟（順序：①確定基本事項②擬定計畫③蒐集資料④確認標的狀態⑤整理比較分析資料⑥運用估價方法⑦決定價格⑧製作估價報告書），非第七步驟。","決定勘估標的價格是§8八步驟中的第⑦步驟（在運用估價方法之後、製作報告書之前），與本題官方答案相符。"],"tr":"","core":["製作估價報告書是第⑧步","整理比較分析資料是第⑤步","運用估價方法推算是第⑥步","決定勘估標的價格是第⑦步"],"hl":[["製作估價報告書","第⑧（最後）步驟"],["整理、比較、分析資料","第⑤步驟"],["運用估價方法推算勘估標的價格","第⑥步驟"],[]]},{"id":"h:111-18","p":"h","src":"111年第18題","sec":"A4","stem":"不動產估價人員應針對不動產勘估標的之價格日期當時的價值進行估價，而所謂價格日期是指：","opts":["估價人員撰寫估價報告書之日期","勘估標的價格之基準日期","至勘估標的現場從事調查的日期","勘估標的交易之日期"],"ok":[1],"ex":["估價人員撰寫估價報告書之日期，是估價報告書的製作完成日期，並非技術規則所稱之價格日期定義。","技術規則§2⑦：「價格日期：指表示不動產價格之基準日期。」與本選項相符。","至勘估標的現場從事調查的日期是「勘察日期」，與價格日期定義不同（二者不必相同）。","勘估標的交易之日期是實際成交之日期，與估價報告書所載價格之基準日期（價格日期）可能不一致。"],"tr":"","core":["撰寫報告書日期非價格日期","價格日期＝價格之基準日期","現場調查日期是勘察日期","實際成交日期不等於價格日期"],"hl":[["撰寫估價報告書之日期","估價報告書的製作完成日期"],[],["現場從事調查的日期","勘察日期"],["交易之日期","實際成交之日期"]]},{"id":"h:111-21","p":"h","src":"111年第21題","sec":"A4","stem":"依據不動產估價技術規則，在進行不動產估價作業程序時，下列何者屬於估價要確定的基本事項？","opts":["作業所需時間","估價目的","勘估標的之狀態","勘估標的相關交易、收益及成本資料"],"ok":[1],"ex":["作業所需時間是技術規則第10條「擬定估價計畫」階段之要素，非「確定估價基本事項」階段之內容。","技術規則第9條明定估價基本事項包含勘估標的內容、價格日期、價格種類及條件、估價目的，「估價目的」是其中明定項目之一，與題目敘述相符。","勘估標的之狀態是技術規則第13條「確認勘估標的狀態」階段（現場勘察）之工作內容，非「確定基本事項」階段。","勘估標的相關交易、收益及成本資料是技術規則第11條「蒐集資料」階段之內容，非「確定基本事項」階段。"],"tr":"","core":["作業所需時間屬擬定估價計畫","估價目的是法定基本事項之一","標的狀態屬確認勘估標的狀態階段","交易收益成本資料屬蒐集資料階段"],"hl":[["作業所需時間","「擬定估價計畫」階段之要素"],[],["勘估標的之狀態","「確認勘估標的狀態」階段"],["相關交易、收益及成本資料","「蒐集資料」階段之內容"]]},{"id":"h:112-20","p":"h","src":"112年第20題","sec":"A4","stem":"下列何者不屬於土地建築開發之間接成本項目？","opts":["建築開發之施工人員施工費用","建築開發之規劃設計費","建築開發之管理費","建築開發之銷售費"],"ok":[0],"ex":["技術規則第76條明定直接成本＝營造施工費，「建築開發之施工人員施工費用」屬於營造施工費的直接投入，是直接成本而非間接成本，即本題正解（本題問「不屬於」間接成本項目）。","建築開發之規劃設計費依規則明定屬於間接成本之一項。","建築開發之管理費依規則明定屬於間接成本之一項。","建築開發之銷售費依規則明定屬於間接成本之一項（廣告銷售費）。"],"tr":"","core":["施工人員施工費是直接成本","規劃設計費屬間接成本","管理費屬間接成本","銷售費屬間接成本"],"hl":[["施工人員施工費用","屬於營造施工費的直接投入，是直接成本"],[],[],[]]},{"id":"h:112-25","p":"h","src":"112年第25題","sec":"A4","stem":"有關一宗土地內有數種不同法定用途時之估價敘述，下列何者錯誤？","opts":["估價前應先考量其最有效使用再決定估價方式","在考量宗地狀況後可以視不同法定用途採分別估價","估價前應先考量各種用途之相關性及分割之難易度再決定估價方式","估價時無須考量是否有數種不同法定用途，只需依其主要用途估價"],"ok":[3],"ex":["估價前應先考量其最有效使用再決定估價方式，是技術規則第85條規定的正確處理原則，此敘述正確，非本題答案（本題問「何者錯誤」）。","依技術規則§85，考量最有效使用、各種用途之相關性及分割之難易度後，可以決定分別估價，敘述正確。","估價前應先考量各種用途之相關性及分割之難易度再決定估價方式，是規則明定的正確考量因素，敘述正確。","技術規則第85條明定，一宗土地內有數種不同法定用途時，應「考量最有效使用及各種用途之相關性及分割之難易度後，決定分別估價或依主要用途估價」，並非「無須考量，只需依主要用途估價」，本選項與規則規定（須經審慎考量後決定）完全相反，即本題正解。"],"tr":"","core":["應先考量最有效使用再決定方式","考量後可採分別估價","應先考量用途相關性及分割難易度","須審慎考量後決定，非逕依主要用途"],"hl":[[],[],[],["無須考量","只需依其主要用途估價","考量最有效使用及各種用途之相關性及分割之難易度後"]]},{"id":"h:113-3","p":"h","src":"113年第3題","sec":"A4","stem":"下列何者非屬於不動產估價範疇？","opts":["大鵬灣濕地","地上權房屋，如101大樓","種植在山上的果樹","從果樹上摘下來的果實"],"ok":[3],"ex":["大鵬灣濕地屬於具特殊生態與經濟價值之土地，仍屬不動產估價技術規則所稱之土地範疇，可進行估價，此選項屬於估價範疇，非本題答案（本題問「非屬」估價範疇）。","地上權房屋（如101大樓設定於公有土地上之地上權建物）：地上權屬§114權利估價，地上建物屬§2⑨勘估標的（建物估價見§108），都屬估價範疇。","種植在山上的果樹，是附著於土地的農作改良物（技術規則§109明列「果樹」），屬於§2⑨所稱勘估標的，所以屬於估價範疇，不是本題答案。","從果樹上摘下來的果實，已經與土地分離成為獨立動產，不再具有不動產（或其孳息附著於不動產）之性質，已脫離不動產估價技術規則所稱勘估標的之範疇，即本題正解。"],"tr":"","core":["濕地仍屬土地，可以估價","地上權與地上建物都屬估價範疇","果樹是農作改良物，屬勘估標的","摘下果實成為動產，非估價範疇"],"hl":[[],[],[],["從果樹上摘下來的果實","已經與土地分離成為獨立動產"]]},{"id":"h:113-6","p":"h","src":"113年第6題","sec":"A4","stem":"不動產估價技術規則對不動產估價方法運用的規定，下列何者錯誤？","opts":["不動產估價師應兼採二種以上估價方法推算勘估標的價格","不動產估價師應就不同估價方法估價所獲得之價格進行綜合比較，就其中金額顯著差異者重新檢討","評估證券化不動產清算價格時，對於折現現金流量分析法之收益價格應賦予相對較大之權重","對於各方法試算價格應視不同價格所蒐集資料可信度及估價種類目的條件差異，考量價格形成因素之相近程度，決定勘估標的價格，並將決定理由詳予敘明"],"ok":[2],"ex":["技術規則第14條明定原則上應兼採二種以上估價方法推算價格，此敘述正確，非本題答案（本題問「何者錯誤」）。","技術規則第15條規定應就不同方法所得金額顯著差異者重新檢討，此敘述正確。","技術規則§15Ⅱ：以契約約定租金作為不動產證券化受益證券信託利益分配基礎者，DCF收益價格才應賦予相對較大權重；「但不動產證券化標的進行清算時，不在此限」。本選項說評估證券化不動產清算價格時反而加重DCF權重，與但書相反，是錯誤敘述，即本題正解。","技術規則第15條規定，應視資料可信度及估價種類目的條件差異，考量價格形成因素之相近程度決定價格並詳予敘明理由，此敘述正確。"],"tr":"","core":["原則應兼採二種以上估價方法","金額顯著差異者應重新檢討","證券化清算時不在加重DCF權重之列","視可信度及相近程度決定並敘明理由"],"hl":[[],[],["清算價格時","不動產證券化標的進行清算時，不在此限"],[]]},{"id":"h:114-17","p":"h","src":"114年第17題","sec":"A4","stem":"不動產估價報告書中應註明價格日期與勘查日期，就時間發生的先後下列敘述何者正確？","opts":["價格日期先於勘查日期","勘查日期先於價格日期","勘查日期等於價格日期","不一定"],"ok":[3],"ex":["技術規則並未規定價格日期必然先於勘查日期，兩者先後關係視個案情況而定，本選項過於絕對化。","技術規則並未規定勘查日期必然先於價格日期，兩者先後關係視個案情況而定，本選項同樣過於絕對化。","技術規則§2⑦價格日期（表示不動產價格之基準日期）與§2⑧勘察日期（赴勘估標的現場從事調查分析之日期）是兩個不同定義的日期。條文沒有要求兩者是同一天，也沒有規定先後，本選項說兩者「相等」過於絕對。","技術規則第2條第7-8款明定價格日期與勘察日期係不同定義之兩個日期，二者先後關係視個案實際情況而定，並無固定先後順序，「不一定」是最精確的描述，與規則精神相符。"],"tr":"","core":["未規定價格日期必先於勘查日期","未規定勘查日期必先於價格日期","兩日期定義不同，未要求同一天","兩日期先後視個案而定"],"hl":[["價格日期先於勘查日期","兩者先後關係視個案情況而定"],["勘查日期先於價格日期","兩者先後關係視個案情況而定"],["勘查日期等於價格日期","條文沒有要求兩者是同一天"],[]]},{"id":"h:114-25","p":"h","src":"114年第25題","sec":"A4","stem":"估價事務所接受委託展開估價作業前應先確定估價基本事項，於下列各項中應包含那些項目？①確定勘估標的內容　②確定勘查日期　③確定價格種類　④確定估價目的　⑤確定估價條件","opts":["僅①③④","①②③④","①③④⑤","①②③④⑤"],"ok":[2],"ex":["僅①③④遺漏⑤確定估價條件，但估價條件是技術規則第9條明定基本事項之一，不應遺漏。","①②③④組合中含②確定勘查日期，但勘查日期並非技術規則第9條明定之「確定估價基本事項」內容（基本事項明定為價格日期而非勘查日期），不應列入。","技術規則§9：「確定估價基本事項如下：一、勘估標的內容。二、價格日期。三、價格種類及條件。四、估價目的。」①對應第一款，③⑤合起來就是第三款「價格種類及條件」，④對應第四款。②勘查日期不在§9（第二款是價格日期），現場勘察屬§13確認勘估標的狀態的階段，所以選①③④⑤。","①②③④⑤全選，但②確定勘查日期非屬「確定估價基本事項」階段之內容，不應列入。"],"tr":"","core":["漏了⑤估價條件","②勘查日期非基本事項","③⑤合為價格種類及條件，②不列","②勘查日期非基本事項，不能全選"],"hl":[["僅①③④","估價條件是技術規則第9條明定基本事項之一"],["基本事項明定為價格日期而非勘查日期"],[],["非屬「確定估價基本事項」階段之內容"]]},{"id":"h:99-1","p":"h","src":"99年第1題","sec":"B","stem":"勘估標的選取比較標的價格經情況調整、價格日期調整，並比較分析區域因素及個別因素之差異後計算勘估標的之價格，稱為：","opts":["比較價格","成本價格","收益價格","試算價格"],"ok":[3],"ex":["比較價格是試算價格經重新檢討確認適當合理後的最終結果，不是「經情況、價格日期、區域、個別因素調整後」這個調整過程本身得出的價格。","成本價格是成本法的產物（重建/重置成本扣除折舊），與比較法的調整流程無關。","收益價格是收益法的產物（淨收益除以資本化率），與比較法的調整流程無關。","技術規則第21條第2項明定：試算價格＝比較標的價格經情況、價格日期、區域因素及個別因素四項調整後所得之價格。題目描述的正是這個定義。"],"tr":"","core":["比較價格是檢討後的最終結果","成本價格是成本法的產物","收益價格是收益法的產物","四項調整後所得價格＝試算價格"],"hl":[["比較價格","試算價格經重新檢討確認適當合理後的最終結果"],["成本價格","成本法的產物（重建/重置成本扣除折舊）"],["收益價格","淨收益除以資本化率"],[]]},{"id":"h:99-3","p":"h","src":"99年第3題","sec":"B","stem":"運用比較法時，區域因素、個別因素調整或區域因素及個別因素內之任一單獨項目之價格調整率應該以下列何者為原則來判定該比較標的與勘估標的差異過大應排除該比較標的之適用呢？","opts":["任一單獨項目調整率大於30%","任一單獨項目調整率大於15%","總調整率大於15%","總調整率小於30%"],"ok":[1],"ex":["30%是「總調整率」（情況+價格日期+區域+個別因素總和）的上限，不是任一單獨項目的判定標準。","技術規則第25條：區域因素或個別因素內任一單獨項目之價格調整率大於15%，即判定差異過大應排除該比較標的。","15%是單項調整率的上限，不是總調整率的判定標準，本選項把兩者數字對調。","「總調整率大於30%」才是排除條件，「小於30%」方向相反，且本題問的是單項調整率判定基準，與此選項描述對象不符。"],"tr":"","core":["30%是總調整率上限，非單項","單獨項目調整率大於15%應排除","15%是單項上限，非總調整率","總調整率大於30%才排除，方向相反"],"hl":[["30%","30%是「總調整率」"],[],["總調整率大於15%","15%是單項調整率的上限"],["總調整率小於30%","「總調整率大於30%」才是排除條件"]]},{"id":"h:99-11","p":"h","src":"99年第11題","sec":"B","stem":"根據不動產估價技術規則之規定，採取比較法進行區域因素及個別因素差異分析調整時，可以採那種方法為其調整方法呢？","opts":["百分率法","定率法","定額法","差額法"],"ok":[0],"ex":["技術規則第24條：區域因素及個別因素之差異所為之調整，以百分率法為原則，亦得以差額法調整。","定率法是成本法折舊計算方法（如初期加速折舊路徑），不是比較法的因素調整方法。","定額法同樣是折舊計算方法，與比較法的區域/個別因素調整無關。","§24規定調整「以百分率法為原則，亦得以差額法調整」；差額法是條文允許的另一種方法，本題問的是原則，故非答案。"],"tr":"","core":["因素調整以百分率法為原則","定率法是成本法折舊方法","定額法是折舊方法，非因素調整","差額法是亦得採用，非原則"],"hl":[[],["定率法","成本法折舊計算方法"],["定額法","折舊計算方法"],["差額法","本題問的是原則"]]},{"id":"h:99-18","p":"h","src":"99年第18題","sec":"B","stem":"運用比較法進行估價時，將影響勘估標的及比較標的價格差異之區域因素及個別因素逐項比較，並依優劣程度或高低等級所評定之差額進行價格調整之方法，係指：","opts":["百分率法","差額法","區域分析法","個別因素法"],"ok":[1],"ex":["百分率法是依優劣程度評定「差異百分率」進行調整，本題描述的是評定「差額」，方法名稱不符。","技術規則第19條第6款：差額法＝依優劣程度評定之差額進行調整，與題目描述「依優劣程度評定差額進行價格調整」完全相符。","「區域分析法」並非技術規則所定義的調整方法名稱，屬於混淆選項。","「個別因素法」同樣不是技術規則定義的調整方法名稱，區域因素及個別因素之調整，以百分率法為原則，亦得以差額法（§24）；§19(7)另定義計量模型分析法（§20規範其條件），但這些都不是題目所述之「個別因素法」。"],"tr":"","core":["百分率法評定差異百分率，非差額","依優劣程度評定差額調整＝差額法","區域分析法非規則定義之調整方法","個別因素法非規則定義之調整方法"],"hl":[["百分率法","依優劣程度評定「差異百分率」進行調整"],[],["區域分析法","並非技術規則所定義的調整方法名稱"],["個別因素法","亦得以差額法"]]},{"id":"h:99-39","p":"h","src":"99年第39題","sec":"B","stem":"利用比較法進行估價時，若比較標的之個別因素較勘估標的差5%，則個別因素調整率為多少？","opts":["100/95","95/100","100/105","105/100"],"ok":[0],"ex":["個別因素調整公式：勘估標的100 ÷ 比較標的(100-5) ＝ 100/95。比較標的較勘估標的差5%，代表勘估標的條件較佳，調整率應為100/95（將比較標的價格向上修正至勘估標的水準）。","95/100小於1，代表向下修正，但比較標的條件較差，調整方向應該是向上修正比較標的價格，本選項方向錯誤。","100/105是「比較標的較勘估標的佳5%」時的調整率（勘估標的100÷比較標的105），本題是比較標的較差5%，方向相反。","105/100是改以比較標的為100、勘估標的為105的寫法，等於把「比較標的差5%」換成「勘估標的優5%」，基準不同；正確為100/95≈1.0526。"],"tr":"","core":["勘估100÷比較(100－5)＝100/95","95/100向下修，方向錯誤","100/105是比較標的較佳5%時","105/100基準不同，應為100/95"],"hl":[[],["95/100","調整方向應該是向上修正比較標的價格"],["100/105","本題是比較標的較差5%"],["105/100","正確為100/95≈1.0526"]]},{"id":"h:100-15","p":"h","src":"100年第15題","sec":"B","stem":"林君將其所有不動產賣給女兒，成交價格為2,000萬元，經判斷此一價格較正常價格便宜2成。請問在其他條件不變下，該不動產之正常價格為多少？","opts":["1,600萬元","1,666萬元","2,400萬元","2,500萬元"],"ok":[3],"ex":["1,600萬元是用「2,000×0.8」計算，但便宜2成的基準應該是正常價格而非成交價格，此為反向誤算。","1,666萬元是把便宜2成誤當成「成交價比正常價高2成」再用除法：2,000÷(1＋20%)≈1,666.7萬元，方向與基準都錯。","2,400萬元是以成交價為基準加2成：2,000×(1＋20%)＝2,400萬元；但2成的基準是正常價格，應2,000÷(1－20%)＝2,500萬元。","成交價格2,000萬元為正常價格打8折（便宜2成）後的結果，故正常價格＝2,000÷(1-20%)＝2,000÷0.8＝2,500萬元。"],"tr":"","core":["2,000×0.8是反向誤算","誤用2,000÷1.2，方向基準都錯","以成交價為基準加2成的誤算","2,000÷(1－20%)＝2,500萬"],"hl":[["1,600萬元","便宜2成的基準應該是正常價格而非成交價格"],["1,666萬元"],["2,400萬元","應2,000÷(1－20%)＝2,500萬元"],[]]},{"id":"h:100-19","p":"h","src":"100年第19題","sec":"B","stem":"下列有關比較法之敘述，何者正確？","opts":["經檢討後試算價格之間差距達15%以下者，應排除該試算價格之適用","進行個別因素調整時，任一單獨項目之價格調整率大於20%時，不應排除該比較標的之適用","進行區域因素調整時，任一單獨項目之價格調整率大於30%時，不應排除該比較標的之適用","經檢討後試算價格之間差距達20%以上者，應排除該試算價格之適用"],"ok":[3],"ex":["技術規則第26條規定差距達「20%以上」應排除，不是「15%以下」，方向與數字皆錯誤。","技術規則第25條規定任一單獨項目調整率大於15%即應排除，不是「大於20%時不應排除」，本選項邏輯相反。","區域因素調整率大於15%即應排除（非30%），本選項數字錯誤。","技術規則第26條：檢討後試算價格之間差距達20%以上者，應排除該試算價格之適用，與本選項描述相符。"],"tr":"","core":["差距達20%以上才排除，非15%以下","單項大於15%即應排除","區域因素大於15%即應排除，非30%","試算價格差距達20%以上應排除"],"hl":[["15%以下","差距達「20%以上」應排除"],["不應排除","任一單獨項目調整率大於15%即應排除"],["30%","不應排除","區域因素調整率大於15%即應排除"],[]]},{"id":"h:100-21","p":"h","src":"100年第21題","sec":"B","stem":"下列那些價格不宜直接視為正常交易價格，於無法掌握調整時，應不予採用。①親友間之買賣　②法院拍賣　③賣方支付土地增值稅之交易　④期待變更之價格","opts":["①②③","①②④","②③④","①②③④"],"ok":[1],"ex":["①②③含③「賣方支付土地增值稅」：§23 十三款沒有這一項，不能選；而且有償移轉的土地增值稅本來就由原所有權人（賣方）繳納（土地稅法§5Ⅰ①），賣方繳是正常交易。","考選部標準答案 B（①②④）。§23：①親友關係人間之交易（第四款）、②拍賣（第七款）、④期待因素影響之交易（第二款，如期待變更）都應先調整，無法有效掌握及量化調整時不予採用。","②③④含③：§23 沒有「賣方支付土地增值稅」，且漏了①。","①②③④含③：③不在 §23 各款，不能全選。"],"tr":"","core":["③賣方付增值稅是正常交易，不在§23","①親友②拍賣④期待因素都須先調整","含③且漏①","③不在§23各款，不能全選"],"hl":[["賣方繳是正常交易"],[],["§23 沒有「賣方支付土地增值稅」"],["③不在 §23 各款"]]},{"id":"h:100-22","p":"h","src":"100年第22題","sec":"B","stem":"勘估標的與比較標的若因樓層之不同，而有100萬元的價格調整。此調整屬於下列何種方法之運用？","opts":["差額法","定額法","定率法","百分率法"],"ok":[0],"ex":["技術規則第19條第6款：差額法係依優劣程度評定「差額」進行調整。題目明確以「100萬元的價格調整」此一具體金額（差額）描述調整，符合差額法定義。","定額法是成本法折舊計算方式（年折舊額固定），非比較法的因素調整方法。","定率法同樣是成本法折舊計算方式，非比較法調整方法。","百分率法是以「百分比」表示調整幅度，而題目給的是具體金額（100萬元），屬於差額法而非百分率法。"],"tr":"","core":["以100萬具體金額調整＝差額法","定額法是成本法折舊方式","定率法是成本法折舊方式","百分率法用百分比，本題是金額"],"hl":[[],["定額法","成本法折舊計算方式（年折舊額固定）"],["定率法","成本法折舊計算方式"],["百分率法","屬於差額法"]]},{"id":"h:101-13","p":"h","src":"101年第13題","sec":"B","stem":"運用比較法選擇實例的條件，下列何者最不適宜？","opts":["必須與勘估標的使用性質相符","必須為正常價格","必須與勘估標的地點相近","必須為一個月以內之實例"],"ok":[3],"ex":["與勘估標的使用性質相符是技術規則第12條明定之選取比較實例原則之一，屬必要條件。","必須為正常價格（或可調整為正常價格、或與勘估標的價格種類相同）也是第12條明定原則之一，屬必要條件。","位於同一供需圈之近鄰或類似地區同樣是第12條明定原則，屬必要條件。","「必須為一個月以內之實例」並非技術規則第12條所列的選取原則，第12條只要求「價格形成日期與勘估標的之價格日期接近」，沒有設定「一個月內」這種具體期限，此選項是常見混淆陷阱，故為最不適宜（即正解）。"],"tr":"","core":["使用性質相符是必要選取條件","正常價格是必要選取條件","同一供需圈近鄰類似地區是必要條件","規則只要求日期接近，無一個月限制"],"hl":[[],[],[],["一個月以內","價格形成日期與勘估標的之價格日期接近"]]},{"id":"h:101-15","p":"h","src":"101年第15題","sec":"B","stem":"預售屋的開價如高於市價一成，依此價格進行勘估標的價格調整時，此調整屬於下列何種方法之運用？","opts":["差額法","定額法","定率法","百分率法"],"ok":[3],"ex":["差額法是依優劣程度評定差額（具體金額）進行調整，題目給的開價「高於市價一成」是百分比表示，不是金額差額。","定額法是成本法折舊概念，非比較法調整方法。","定率法同樣是成本法折舊概念，非比較法調整方法。","「高於市價一成」是以百分比（10%）表示優劣程度的調整，依技術規則第24條，此類調整以百分率法為原則，符合定義。"],"tr":"","core":["差額法用具體金額，本題是百分比","定額法是成本法折舊概念","定率法是成本法折舊概念","高於市價一成以百分比調整＝百分率法"],"hl":[["差額法","依優劣程度評定差額（具體金額）進行調整"],["定額法","成本法折舊概念"],["定率法","成本法折舊概念"],[]]},{"id":"h:101-22","p":"h","src":"101年第22題","sec":"B","stem":"某甲以1,200萬元將其房屋移轉給弟弟，經判斷正常價格比這價格低二成；於一般不動產估價中，運用此案例進行情況調整後之價格為多少？","opts":["1,440萬元","1,400萬元","1,000萬元","960萬元"],"ok":[3],"ex":["1,440萬元的計算方向錯誤，本題正常價格應低於成交價格，不應向上調整。","1,400萬元無法由題幹常見誤算得到，屬干擾數字（常見誤算為1,440、1,000、1,500，均非1,400）。","1,000萬元是把「低二成」誤用除法：1,200÷(1＋20%)＝1,000萬元；題目的基準是1,200萬元，應1,200×(1－20%)＝960萬元。","題目明確指出「正常價格比這價格（1,200萬元）低二成」，故正常價格＝1,200×(1-20%)＝1,200×0.8＝960萬元。本題與一般「成交價比正常價低幾成」的情境相反，須留意題目敘述的比較基準方向（此處是以成交價1,200萬元為基準，正常價格在其之下打8折，而非以正常價格為基準反推成交價）。"],"tr":"","core":["正常價應低於成交價，不應往上調","1,400萬無法由常見誤算得到","誤用1,200÷1.2的算法","1,200×(1－20%)＝960萬"],"hl":[["1,440萬元","正常價格應低於成交價格"],["1,400萬元"],["1,000萬元","應1,200×(1－20%)＝960萬元"],[]]},{"id":"h:101-29","p":"h","src":"101年第29題","sec":"B","stem":"使用買賣實例比較法，如訪得之買賣實例其交易價格，係因屋主急於脫手而出售，此係：","opts":["一般購買者不易參加，應進行個別因素修正","利害關係人交易，應進行情況修正","交易時具特別動機，應進行情況修正","將負擔由購買者承受，應進行期日修正"],"ok":[2],"ex":["「一般購買者不易參加」描述的是市場競價限制，並非屋主急於脫手這種交易動機異常的情況，與個別因素修正無關。","親友等利害關係人間之交易（§23第4款）固然要作情況調整，但本題是屋主自己急於脫手，並非利害關係人交易，定性錯誤。","技術規則§23第1款列有「急買急賣或急出租急承租」，屬應先作適當調整之比較標的情況；這類價格形成條件非屬一般正常情形，依§19第1款所作之調整即為情況調整，「屋主急於脫手」正屬此類。","「將負擔由購買者承受」描述的是交易條件而非價格本身的時間差異，與價格日期調整（因時間差異致價格水準變動）的定義不符。"],"tr":"","core":["市場競價限制，與急於脫手無關","屋主自己急賣，非利害關係人交易","急買急賣屬特別動機，應情況調整","負擔承受是交易條件，非期日修正"],"hl":[["一般購買者不易參加","屋主急於脫手這種交易動機異常的情況"],["利害關係人交易","本題是屋主自己急於脫手"],[],["期日修正","描述的是交易條件而非價格本身的時間差異"]]},{"id":"h:102-5","p":"h","src":"102年第5題","sec":"B","stem":"依不動產估價技術規則規定，不動產估價師蒐集比較實例應依據之原則，下列敘述何者錯誤？","opts":["實例價格形成日期與勘估標的之價格日期接近者","與勘估標的使用性質或使用分區管制相同或相近者","與勘估標的位於同一供需圈之近鄰地區或類似地區者","實例之價格與勘估標的價格種類相同之特定或限定價格者"],"ok":[3],"ex":["技術規則第12條第4款明定：實例價格形成日期與勘估標的之價格日期接近者，為正確原則。","技術規則第12條第3款明定：與勘估標的使用性質或使用管制相同或相近者，為正確原則。","技術規則第12條第2款明定：與勘估標的位於同一供需圈之近鄰地區或類似地區者，為正確原則。","§12第1款是三擇一：「正常價格、可調整為正常價格或與勘估標的價格種類相同者」；本選項把原則限縮改寫成「價格種類相同之特定或限定價格」，排除了正常價格這個主要原則，與條文不符，即本題正解。"],"tr":"","core":["價格形成日期接近價格日期","使用性質或管制相同相近","位於同一供需圈近鄰或類似地區","原則是正常價格等三擇一，非限縮特定限定"],"hl":[[],[],[],["特定或限定價格","正常價格、可調整為正常價格或與勘估標的價格種類相同者"]]},{"id":"h:102-6","p":"h","src":"102年第6題","sec":"B","stem":"因應財政部查稅及不動產資本利得稅改採實價認定之議題發酵，投資客黃先生於兩個月前，以低於當時市價1成急忙出售房地產一筆，成交價格為新臺幣1000萬元。如近兩個月房價又下跌5%，則目前市價行情為何？","opts":["新臺幣950萬元","新臺幣1100萬元","新臺幣1045萬元","新臺幣1056萬元"],"ok":[3],"ex":["950萬元只做了價格日期調整（1,000×(1－5%)＝950），漏了情況調整（低於市價1成要先除以0.9還原）。","1,100萬元是情況調整誤用乘法（1,000×(1＋10%)＝1,100），且漏做近兩個月下跌5%的價格日期調整；正確為1,000÷0.9×0.95≈1,056萬元。","1,045萬元兩階段都有做，但情況調整誤用乘法：1,000×(1＋10%)×(1－5%)＝1,045萬元；「低於市價1成」應除以(1－10%)，即1,000÷0.9×0.95≈1,056萬元。","成交價1,000萬元是低於市價1成（情況調整），先還原：1,000÷(1-10%)≈1,111.1萬元；該數字代表2個月前的市價，再考慮近2個月房價又下跌5%，目前市價＝1,111.1×(1-5%)≈1,055.6萬元≈1,056萬元。"],"tr":"","core":["只做日期調整，漏了情況調整","情況調整誤乘且漏日期調整","情況調整誤用乘法得1,045萬","1,000÷0.9×0.95≈1,056萬"],"hl":[["950萬元","漏了情況調整（低於市價1成要先除以0.9還原）"],["1100萬元","正確為1,000÷0.9×0.95≈1,056萬元"],["1045萬元","應除以(1－10%)"],[]]},{"id":"h:102-7","p":"h","src":"102年第7題","sec":"B","stem":"某份不動產估價報告書比較法三個比較標的價格為：新臺幣12.9、12.6、13.7萬元/坪，所推估勘估標的之試算價格分別為：新臺幣10、9、11.5萬元/坪，下列敘述何者正確？","opts":["比較標的一調幅違反規定","比較標的二調幅違反規定","比較標的二及比較標的三試算價格差距違反規定","勘估標的整體條件較比較標的佳"],"ok":[2],"ex":["✗ 標的一調幅＝(10－12.9)÷12.9＝−22.5%。這是總調整率（情況＋日期＋區域＋個別四項合計），§25 的總調整率上限是 30%，22.5% 沒超過，不違規。\n★陷阱：22.5% 看起來超過 15%，但 15% 是「單一項目」的上限，不是總調整率。","✗ 標的二調幅＝(9－12.6)÷12.6＝−28.6%，一樣是總調整率，仍未超過 30%，不違規。\n（三個標的的總調整率：一 −22.5%、二 −28.6%、三 −16.1%，全部過關。）","★正解。§26 的差距＝(高－低)÷高低平均值，三組兩兩比：\n一(10) vs 二(9)＝1÷9.5＝10.5%\n一(10) vs 三(11.5)＝1.5÷10.75＝14.0%\n二(9) vs 三(11.5)＝2.5÷10.25＝24.4% → 達 20% 以上，應排除該試算價格。\n※ 比的是試算價格（10、9、11.5），不是比較標的價格（12.9、12.6、13.7）。","✗ 三個試算價格都低於原比較標的價格（12.9→10、12.6→9、13.7→11.5），表示調整方向全是往下修，代表勘估標的條件比比較標的差，不是佳。"],"tr":"","core":["總調整率－22.5%，未超過30%","總調整率－28.6%，未超過30%","二與三試算價格差距24.4%，達20%","試算價格都往下修，勘估標的較差"],"hl":[["違反規定","22.5% 沒超過，不違規"],["違反規定","仍未超過 30%，不違規"],[],["條件較比較標的佳","調整方向全是往下修"]]},{"id":"h:102-31","p":"h","src":"102年第31題","sec":"B","stem":"臺北市政府最近發布之5月份住宅價格指數，中山、松山、南港區標準住宅總價新臺幣1224萬元，萬華、文山、北投區新臺幣1079萬元，其價差達新臺幣145萬元。該價差屬於下列何種方法之運用？","opts":["定額法","差異法","差額法","量化法"],"ok":[2],"ex":["定額法是成本法折舊計算方法（年折舊額固定），與比較法的房價指數金額差異分析無關。","「差異法」並非技術規則定義的調整方法名稱。","兩區域住宅總價直接相減得出具體金額差價（145萬元），依技術規則第19條第6款，以具體差額表示優劣程度差異即為差額法之運用。","「量化法」並非技術規則定義的調整方法名稱，屬混淆選項。"],"tr":"","core":["定額法是成本法折舊方法","差異法非規則定義之方法","兩區總價相減得具體差價＝差額法","量化法非規則定義之方法"],"hl":[["定額法","成本法折舊計算方法"],["差異法","並非技術規則定義的調整方法名稱"],[],["量化法","並非技術規則定義的調整方法名稱"]]},{"id":"h:102-34","p":"h","src":"102年第34題","sec":"B","stem":"請問試算價格之調整運算過程中，區域因素或個別因素調整之任一單獨項目之價格調整率大於多少，即應排除該比較案例之適用？","opts":["5%","10%","15%","20%"],"ok":[2],"ex":["5%遠低於技術規則第25條規定的15%門檻，非本題答案。","10%同樣低於15%門檻，非本題答案。","技術規則第25條明定：區域因素或個別因素內任一單獨項目之價格調整率大於15%，應排除該比較標的之適用。","20%是試算價格差距（技術規則第26條）的判定門檻，並非單項調整率的門檻，本選項混淆了兩條規定的數字。"],"tr":"","core":["5%遠低於15%門檻","10%低於15%門檻","單獨項目調整率大於15%應排除","20%是試算價格差距門檻"],"hl":[["5%","技術規則第25條規定的15%門檻"],["10%","低於15%門檻"],[],["20%","試算價格差距（技術規則第26條）的判定門檻"]]},{"id":"h:103-10","p":"h","src":"103年第10題","sec":"B","stem":"某一不動產於103年3月1日的正常價格為1000萬元，綜合市場調查並參考不動產價格指數，得知103年3月1日至103年4月1日期間價格上漲一成，在其他條件不變情況下，請問103年4月1日的正常價格為何？","opts":["900萬元","909萬元","1100萬元","1111萬元"],"ok":[2],"ex":["900萬元計算方向錯誤，未正確處理「上漲一成」的調整方向。","909萬元同樣計算方向有誤（誤用除法而非乘法處理上漲情境）。","103年3月1日正常價格1,000萬元，期間上漲一成（10%），4月1日正常價格＝1,000×(1+10%)＝1,100萬元，屬於價格日期調整的直接應用。","1,111萬元是把上漲一成誤用除法：1,000÷(1－10%)≈1,111.1萬元；已知的是3月1日的正常價格，往後上漲只要乘1.1。"],"tr":"","core":["900萬方向錯誤","909萬誤用除法處理上漲","1,000×(1＋10%)＝1,100萬","誤用1,000÷0.9，上漲應乘1.1"],"hl":[["900萬元"],["909萬元"],[],["1111萬元","往後上漲只要乘1.1"]]},{"id":"h:103-19","p":"h","src":"103年第19題","sec":"B","stem":"依不動產估價技術規則規定，下列有關勘估標的試算價格之敘述，何者有誤？","opts":["試算價格之間差距達百分之二十以上者，應排除該試算價格之適用","試算價格間的差距，以高低價格之差除以各價格平均值計算","試算價格應就價格偏高或偏低者加以重新檢討","經檢討確認適當合理者，始得作為決定比較價格之基礎"],"ok":[1],"ex":["技術規則第26條明定：試算價格之間差距達20%以上者，應排除該試算價格之適用，本敘述正確，非本題答案（本題問「何者有誤」）。","技術規則第26條規定差距計算方式為「高低價格之差除以『高低價格』平均值」，係指最高與最低兩個試算價格的平均值；本選項改寫為「除以『各』價格平均值」，「各」字暗示是把所有試算價格（可能三個以上）全部平均，與規則明定僅取「最高、最低兩者」平均值的範圍不同，此題屬文字差異題，僅能靠用字差異判斷（§26Ⅱ為「高低價格之差除以高低價格平均值達百分之二十以上」，可與107年第6題對照）。","試算價格應就偏高或偏低者重新檢討，這是技術規則第26條第1項的明文規定，敘述正確。","經檢討確認適當合理者才能作為決定比較價格之基礎，這也是技術規則第26條第1項規定，敘述正確。"],"tr":"","core":["試算價格差距達20%以上應排除","應除以高低價格平均值，非各價格","偏高或偏低者應重新檢討","檢討合理者始得作為比較價格基礎"],"hl":[[],["各價格平均值","高低價格之差除以『高低價格』平均值"],[],[]]},{"id":"h:103-20","p":"h","src":"103年第20題","sec":"B","stem":"甲以2000萬元（比市場行情低二成的價格）買了一戶公寓，請問該公寓之市場行情是多少？","opts":["1600萬元","2200萬元","2400萬元","2500萬元"],"ok":[3],"ex":["1,600萬元的計算方向錯誤（誤用2,000×0.8）。","2,200萬元＝2,000×(1＋10%)，是把二成看成一成，又以成交價為基準加成；正確為2,000÷0.8＝2,500萬元。","2,400萬元是以成交價為基準加二成：2,000×(1＋20%)＝2,400萬元；二成的基準是市場行情，應2,000÷(1－20%)＝2,500萬元。","甲以2,000萬元買入，該價格比市場行情低二成（即2,000萬元＝市場行情×80%），故市場行情＝2,000÷0.8＝2,500萬元。"],"tr":"","core":["誤用2,000×0.8","二成看成一成又以成交價加成","以成交價為基準加二成的誤算","2,000÷0.8＝2,500萬"],"hl":[["1600萬元"],["2200萬元","正確為2,000÷0.8＝2,500萬元"],["2400萬元","應2,000÷(1－20%)＝2,500萬元"],[]]},{"id":"h:103-21","p":"h","src":"103年第21題","sec":"B","stem":"依不動產估價技術規則規定，請問比較法應進行比較、分析及調整之項目為何？①情況調整②價格日期調整③一般因素調整④區域因素調整⑤個別因素調整⑥價格調整","opts":["①②③④","①②④⑤","①②③④⑤","①②③④⑤⑥"],"ok":[1],"ex":["①②③④缺少⑤個別因素調整，比較法調整流程不可缺少個別因素這一項，故不完整。","依技術規則§21第1項第3、4款及第2項，比較法應進行情況調整、價格日期調整、區域因素調整及個別因素調整（①②④⑤）；條文沒有「一般因素調整」及「價格調整」這兩個項目。","①②③④⑤包含了③一般因素調整，但技術規則§21的四項調整中並無「一般因素調整」此一獨立項目，一般因素屬於影響全國性價格水準的因素，不在逐項比較調整的範疇內，本選項多算一項。","全部六項都列入，但③一般因素調整與⑥價格調整皆非技術規則§21所定的調整項目，本選項錯誤更多。"],"tr":"","core":["缺⑤個別因素調整","情況日期區域個別四項調整","③一般因素調整非法定項目","③一般因素⑥價格調整皆非法定項目"],"hl":[["①②③④","缺少⑤個別因素調整"],[],["並無「一般因素調整」此一獨立項目"],["皆非技術規則§21所定的調整項目"]]},{"id":"h:103-24","p":"h","src":"103年第24題","sec":"B","stem":"依不動產估價技術規則，有關試算價格調整率之限制，何者正確？","opts":["區域因素調整之價格調整率不得大於百分之十五","情況調整之價格調整率不得大於百分之十五","價格日期調整之價格調整率不得大於百分之十五","情況、價格日期、區域因素及個別因素調整總調整率不得大於百分之十五"],"ok":[0],"ex":["技術規則第25條明定：區域因素或個別因素內任一單獨項目之價格調整率大於15%時，應排除該比較標的之適用，本選項正確描述此規定的核心數字。","情況調整本身並非單獨設有「不得大於15%」的明文限制，第25條規範的對象是「區域因素或個別因素內之任一單獨項目」，情況調整不在此限制範圍內。","價格日期調整同樣不在第25條單項調整率15%限制的列舉對象內。","情況、價格日期、區域因素及個別因素「總調整率」上限是30%而非15%，本選項數字錯誤。"],"tr":"","core":["區域因素單項調整率上限15%","情況調整不在單項15%限制內","價格日期調整不在單項15%限制內","總調整率上限是30%，非15%"],"hl":[[],["情況調整","情況調整不在此限制範圍內"],["價格日期調整","不在第25條單項調整率15%限制的列舉對象內"],["百分之十五","上限是30%"]]},{"id":"h:104-1","p":"h","src":"104年第1題","sec":"B","stem":"比較、分析勘估標的與比較標的之區域因素及個別因素差異並就其中差異進行價格調整時，其調整以那一種方法為原則？","opts":["比較法","差額法","百分率法","計量模型分析法"],"ok":[2],"ex":["「比較法」是估價的三大方法之一，並非比較法內部用來調整區域/個別因素差異的具體方法名稱，選項邏輯有誤。","§24規定調整「以百分率法為原則，亦得以差額法調整」；差額法是條文允許的另一種方法，本題問的是原則，故非答案。","技術規則第24條明定：區域因素及個別因素之差異所為之價格調整，以百分率法為原則。","§19(7)定義計量模型分析法（§20規範其條件），雖亦為調整方法之一種，但§24明定區域因素及個別因素之價格調整以百分率法為原則，故非本題答案。"],"tr":"","core":["比較法是估價方法，非調整方法","差額法是亦得採用，非原則","因素調整以百分率法為原則","計量模型非原則，原則是百分率法"],"hl":[["比較法"],["差額法","以百分率法為原則，亦得以差額法調整"],[],["計量模型分析法","§24明定區域因素及個別因素之價格調整以百分率法為原則"]]},{"id":"h:104-9","p":"h","src":"104年第9題","sec":"B","stem":"如果同一勘估標的運用比較法估價，所得三個試算價格有相當差距時，下列何者是決定其比較價格最好的方法？","opts":["取中間值","取平均值","就價格偏高或偏低者重新檢討","賦予45%、30%、25%加權決定"],"ok":[2],"ex":["直接取中間值並非技術規則規定的決定方法，未經重新檢討即取中間值缺乏依據。","直接取平均值同樣缺乏技術規則依據，未經偏高偏低檢討的平均並不合理。","技術規則第26條規定：試算價格應就價格偏高或偏低者重新檢討，經檢討確認適當合理者，始得作為決定比較價格之基礎，這正是處理試算價格差距過大時的正確程序。","「賦予45%、30%、25%加權」這種固定權重比例並非技術規則規定的決定方法，屬於虛構的混淆選項。"],"tr":"","core":["直接取中間值缺乏依據","未經檢討的平均不合理","偏高偏低者重新檢討後才採用","固定權重比例是虛構選項"],"hl":[["取中間值"],["取平均值"],[],["45%、30%、25%加權"]]},{"id":"h:104-10","p":"h","src":"104年第10題","sec":"B","stem":"甲君將其所有一棟透天厝以1,275萬元賣給其小舅子，經判斷比正常價格便宜一成五。試問在其他條件不變下，其正常價格應為多少？","opts":["1,083.75萬元","1,147.5萬元","1,500萬元","1,416.7萬元"],"ok":[2],"ex":["1,083.75萬元的計算方向錯誤（誤用1,275×0.85計算而非還原除法）。","1,147.5萬元是把一成五看成一成，又用乘法：1,275×(1－10%)＝1,147.5萬元。","成交價1,275萬元比正常價格便宜一成五（15%），即1,275萬元＝正常價格×(1-15%)＝正常價格×0.85，故正常價格＝1,275÷0.85＝1,500萬元。","1,416.7萬元是把一成五看成一成：1,275÷(1－10%)≈1,416.7萬元；應除以0.85。"],"tr":"","core":["誤用1,275×0.85","一成五看成一成又用乘法","1,275÷0.85＝1,500萬","一成五看成一成，應除以0.85"],"hl":[["1,083.75萬元","還原除法"],["1,147.5萬元"],[],["1,416.7萬元","應除以0.85"]]},{"id":"h:104-11","p":"h","src":"104年第11題","sec":"B","stem":"一比較標的於102年8月以1,000萬元成交，當時的價格指數為90%；勘估標的價格日期104年8月當期之價格指數為95%。假設其他條件相同，試問該勘估標的經價格日期調整後之價格約為多少？","opts":["947.37萬元","950.00萬元","1,000.00萬元","1,055.56萬元"],"ok":[3],"ex":["947.37萬元的計算方向錯誤（誤將指數比例顛倒）。","950萬元是只乘了價格日期的指數95%、沒有除以交易時指數90%：1,000×95%＝950萬元；應1,000×95÷90≈1,055.56萬元。","1,000.00萬元代表未經調整的原始成交價，並非考慮指數變動後的結果。","價格日期調整公式：調整後價格＝比較標的成交價×(勘估標的價格日期指數÷比較標的交易日期指數)＝1,000×(95÷90)≈1,055.56萬元。"],"tr":"","core":["指數比例顛倒的誤算","只乘95%，漏除以90%","1,000萬是未調整原價","1,000×95÷90≈1,055.56萬"],"hl":[["947.37萬元"],["950.00萬元","應1,000×95÷90≈1,055.56萬元"],["1,000.00萬元"],[]]},{"id":"h:104-12","p":"h","src":"104年第12題","sec":"B","stem":"依不動產估價技術規則之規定，下列有關比較法個別因素調整及試算價格求取之敘述，何者正確？","opts":["就勘估標的與比較標的差異進行價格調整時，以差額法為原則","就勘估標的與比較標的差異進行價格調整時，以定性分析法為原則","偏高或偏低檢討後試算價格間差距仍達百分之十以上者，應排除該試算價格之適用","偏高或偏低檢討後試算價格間差距仍達百分之二十以上者，應排除該試算價格之適用"],"ok":[3],"ex":["技術規則第24條規定差異調整以「百分率法」為原則，非「差額法」為原則，本選項方法名稱錯誤。","「定性分析法」並非技術規則所定義的調整方法名稱，屬虛構選項。","技術規則第26條規定差距達20%以上才應排除，非10%以上，本選項數字錯誤。","技術規則第26條明定：偏高或偏低檢討後試算價格間差距仍達20%以上者，應排除該試算價格之適用，與本選項描述相符。"],"tr":"","core":["差異調整以百分率法為原則","定性分析法是虛構方法","差距達20%以上才排除，非10%","檢討後差距仍達20%以上應排除"],"hl":[["差額法為原則","以「百分率法」為原則"],["定性分析法"],["百分之十","差距達20%以上才應排除"],[]]},{"id":"h:104-26","p":"h","src":"104年第26題","sec":"B","stem":"比較標的在不動產估價技術規則中係指可供與勘估標的間，按情況、價格日期及下列那些因素之差異進行比較之標的？①區域因素　②一般因素　③經濟因素　④政治因素　⑤個別因素","opts":["①⑤","②⑤","①②③","②③④⑤"],"ok":[0],"ex":["技術規則§2(10)明定比較標的係可供與勘估標的間按情況、價格日期、區域因素①及個別因素⑤之差異進行比較之標的，故①⑤為正確組合。","②一般因素並非比較標的逐項比較調整的對象，一般因素是影響全國性價格水準的宏觀因素，不在§2(10)所列之比較項目內。","①區域因素正確，但②一般因素、③經濟因素皆非§2(10)所列之比較項目。","②③④皆非技術規則§2(10)所列之比較項目，僅⑤個別因素正確，本選項組合錯誤過多。"],"tr":"","core":["比較標的按區域及個別因素比較","②一般因素非比較項目","②③非比較項目","②③④皆非比較項目"],"hl":[[],["並非比較標的逐項比較調整的對象"],["②③","皆非§2(10)所列之比較項目"],["②③④","②③④皆非技術規則§2(10)所列之比較項目"]]},{"id":"h:104-36","p":"h","src":"104年第36題","sec":"B","stem":"在使用比較法估價時，採用下列那些情況下之交易價格時，應先作適當之調整；該影響交易價格之情況無法有效掌握及量化調整時，則應不予採用？①張先生因債務人無力償債而承接其抵押給張先生的廠房　②父子間之不動產買賣　③王先生因為移民急賣手上的不動產　④財政部國有財產署標售土地　⑤臺中市政府向教育部價購土地","opts":["僅③④⑤","①②③④⑤","僅①②④","僅①②③"],"ok":[1],"ex":["僅③④⑤遺漏了①②兩項，但①（債權人承接抵押廠房，屬受債權債務關係影響之交易）與②（父子間買賣，屬親友間交易）皆屬技術規則第23條列舉之應先調整或不予採用情況，不應遺漏。","技術規則第23條列舉之情況涵蓋：①受債權債務關係影響之交易（§23(3)）、②親友關係人間之交易（§23(4)）、③急買急賣或急出租急承租之交易（§23(1)）、④公有土地標售、讓售（§23(8)）、⑤政府機關間價購（不在第8款所列，可歸§23(13)其他特殊交易），五項皆屬於應先作適當調整、若無法量化調整則不予採用之情況。","僅①②④遺漏③⑤，但③（移民急賣）與⑤（政府機關間價購）同樣屬於應檢視調整之特殊交易情況，不應遺漏。","僅①②③遺漏④⑤，但④⑤之政府機關標售或價購交易，同樣可能因價格形成機制特殊而需要適當調整，不應遺漏。"],"tr":"","core":["漏了①債權債務②親友間交易","五項都須先調整，否則不予採用","漏了③急賣⑤政府間價購","漏了④⑤政府標售或價購"],"hl":[["僅③④⑤","皆屬技術規則第23條列舉之應先調整或不予採用情況"],[],["僅①②④","同樣屬於應檢視調整之特殊交易情況"],["僅①②③","同樣可能因價格形成機制特殊而需要適當調整"]]},{"id":"h:105-24","p":"h","src":"105年第24題","sec":"B","stem":"有關比較法之敘述，下列何者錯誤？","opts":["比較標的價格為基礎，經比較、分析及調整等，以推算勘估標的價格之方法","不動產估價師應採用五件以上比較標的","區域因素及個別因素進行價格調整時，其調整以百分率法為原則","以比較法所求得之價格為比較價格"],"ok":[1],"ex":["技術規則第18條明定比較法之定義即為「以比較標的價格為基礎，經比較、分析及調整等，以推算勘估標的價格之方法」，敘述正確，非本題答案（本題問「何者錯誤」）。","技術規則第27條規定應採用「三件以上」比較標的，而非「五件以上」，此為錯誤敘述，即本題正解。","技術規則第24條規定區域因素及個別因素之調整以百分率法為原則，敘述正確。","技術規則第18條明定以比較法所求得之價格為比較價格，敘述正確。"],"tr":"","core":["以比較標的價格調整推算＝比較法","應採三件以上，非五件以上","因素調整以百分率法為原則","比較法所求價格為比較價格"],"hl":[[],["五件以上","應採用「三件以上」比較標的"],[],[]]},{"id":"h:105-37","p":"h","src":"105年第37題","sec":"B","stem":"依不動產估價技術規則第26條規定，檢討後試算價格之間差距達多少以上者，應排除該試算價格之適用？","opts":["30%","20%","15%","10%"],"ok":[1],"ex":["30%是「總調整率」（情況+價格日期+區域+個別因素總和）的判定門檻（技術規則第25條），不是試算價格差距的門檻。","技術規則第26條明定：檢討後試算價格之間差距達20%以上者，應排除該試算價格之適用。","15%是「單項調整率」（任一單獨項目）的判定門檻（技術規則第25條），不是試算價格差距的門檻。","10%不是比較法的門檻（§25為單項15%、總調整率30%，§26為試算價格差距20%）；技術規則中的10%是§67殘餘價格率的原則上限，與本題無關。"],"tr":"","core":["30%是總調整率門檻","試算價格差距達20%以上應排除","15%是單項調整率門檻","10%非比較法門檻"],"hl":[["30%","30%是「總調整率」"],[],["15%","15%是「單項調整率」"],["10%","§26為試算價格差距20%"]]},{"id":"h:105-38","p":"h","src":"105年第38題","sec":"B","stem":"試算價格之調整運算過程中，下列何者符合不動產估價技術規則第25條之規定？","opts":["各項因素內之任一單獨項目之價格調整率為12%時，必須敘明理由","各項因素內之任一單獨項目之價格調整率為20%時，不須敘明理由","各項因素內之任一單獨項目之價格調整率為30%時，不須敘明理由","各項因素內之任一單獨項目之價格調整率為17%時，必須敘明理由"],"ok":[3],"ex":["12%未超過15%上限，依技術規則第25條規定不須特別敘明理由（僅超過15%時，於「勘估標的性質或區位特殊」前提下才需於報告書敘明），本選項與規則文字不符。","20%已超過15%單項調整率上限，依規則應排除該比較標的之適用（除非性質特殊並敘明理由），本選項稱「不須敘明理由」與規則意旨相反。","30%同樣已超過15%上限甚多，更需審慎處理並敘明，本選項「不須敘明理由」明顯錯誤。","17%已超過技術規則第25條規定的15%單項調整率上限，依規定除非勘估標的性質或區位特殊並於估價報告書中敘明理由，否則應排除該比較標的，故「17%時必須敘明理由」（若性質特殊欲援引例外）符合規則精神，為本題正解。"],"tr":"","core":["12%未超過15%，不須敘明理由","20%超過上限，應排除或敘明理由","30%遠超上限，更需敘明","17%超過15%，例外須敘明理由"],"hl":[["必須敘明理由","不須特別敘明理由"],["不須敘明理由","應排除該比較標的之適用"],["不須敘明理由","更需審慎處理並敘明"],[]]},{"id":"h:106-5","p":"h","src":"106年第5題","sec":"B","stem":"臺北市政府最近發布之10月份住宅價格指數，中山松山南港區標準住宅總價1,224萬元、萬華文山北投區1,080萬元，其價差達144萬元。以上的價差分析，屬下列何種運用？","opts":["定率法","比率法","定額法","差額法"],"ok":[3],"ex":["定率法是成本法折舊計算方法（每年依固定比率對前一年餘值計算），與住宅總價直接相減的金額差異分析無關。","「比率法」並非技術規則明確定義的比較法調整方法名稱。","定額法是成本法折舊計算方法（年折舊額固定），同樣與比較法調整無關。","兩區域住宅總價直接相減得出具體金額差價（144萬元），依技術規則第19條第6款定義，此即差額法之運用——依優劣程度評定具體差額進行價格調整分析。"],"tr":"","core":["定率法是成本法折舊方法","比率法非規則定義之調整方法","定額法是成本法折舊方法","兩區總價相減得差價＝差額法"],"hl":[["定率法","成本法折舊計算方法"],["比率法"],["定額法","成本法折舊計算方法"],[]]},{"id":"h:106-28","p":"h","src":"106年第28題","sec":"B","stem":"勘估土地時蒐集到一個半年前正常情況下之土地交易案例，以每平方公尺30萬元成交，其與價格日期相比跌了2%，區域條件較勘估標的優5%、個別條件較勘估標的優10%，其計算價格為何？","opts":["25.137萬元/㎡","26.163萬元/㎡","35.343萬元/㎡","45.305萬元/㎡"],"ok":[0],"ex":["試算價格（選項的算法）＝30×(1－2%)×(1－5%)×(1－10%)＝30×0.98×0.95×0.90≈25.137萬元/㎡，與本選項相符。比較標的較優，所以往下調。注意：若依99-39 以勘估標的為基準的百分率寫法（100/105、100/110），結果是30×0.98×100/105×100/110≈25.45萬元/㎡，不在選項內。","26.163萬元/㎡是價格日期調整方向弄反（跌2%卻乘1.02），區域、個別往下調是對的：30×1.02×0.95×0.90＝26.163。","35.343萬元/㎡是三項調整全部往上：價格日期乘1.02（跌2%應乘0.98）、區域乘1.05、個別乘1.10（比較標的較優應往下調）：30×1.02×1.05×1.10＝35.343。","45.305萬元/㎡無法由題幹常見誤算得到，屬干擾數字。"],"tr":"","core":["比較標的較優往下調≈25.137萬","價格日期方向弄反的誤算","三項全往上調的誤算","無法由常見誤算得到"],"hl":[[],["26.163萬元/㎡","價格日期調整方向弄反"],["35.343萬元/㎡","跌2%應乘0.98","比較標的較優應往下調"],["45.305萬元/㎡"]]},{"id":"h:106-31","p":"h","src":"106年第31題","sec":"B","stem":"下列有關勘估標的與比較標的調整及試算價格求取之敘述，何者正確？","opts":["差異調整以差額法為原則","差異調整以定性分析法為原則","偏高或偏低檢討後試算價格間差距仍達10%以上者，應排除適用","偏高或偏低檢討後試算價格間差距仍達20%以上者，應排除適用"],"ok":[3],"ex":["技術規則第24條規定差異調整以「百分率法」為原則，本選項稱「差額法」為原則，方法名稱錯誤。","「定性分析法」並非技術規則定義的調整方法，屬虛構選項。","技術規則第26條規定差距達20%以上才排除，非10%以上，本選項數字錯誤。","技術規則第26條明定：偏高或偏低檢討後試算價格間差距仍達20%以上者，應排除適用，與本選項相符。"],"tr":"","core":["差異調整以百分率法為原則","定性分析法是虛構方法","差距達20%以上才排除，非10%","檢討後差距仍達20%以上應排除"],"hl":[["差額法","以「百分率法」為原則"],["定性分析法"],["10%","差距達20%以上才排除"],[]]},{"id":"h:107-3","p":"h","src":"107年第3題","sec":"B","stem":"下列何者不屬不動產估價師蒐集比較實例所應依循之原則？","opts":["實例之價格屬限定價格、可調整為限定價格或與勘估標的價格種類相同者","與勘估標的位於同一供需圈之近鄰地區或類似地區者","與勘估標的使用性質或使用管制相同或相近者","實例價格形成日期與勘估標的之價格日期接近者"],"ok":[0],"ex":["技術規則§12第1款原文為「實例之價格屬正常價格、可調整為正常價格或與勘估標的價格種類相同者」；本選項把前兩處「正常價格」改成「限定價格」，不屬應依循之原則，即本題正解。","與勘估標的位於同一供需圈之近鄰地區或類似地區者，是第12條明定之正確原則。","與勘估標的使用性質或使用管制相同或相近者，是第12條明定之正確原則。","實例價格形成日期與勘估標的之價格日期接近者，是第12條明定之正確原則。"],"tr":"","core":["原則是正常價格，非限定價格","同一供需圈近鄰或類似地區","使用性質或管制相同相近","價格形成日期接近價格日期"],"hl":[["限定價格、可調整為限定價格","實例之價格屬正常價格、可調整為正常價格"],[],[],[]]},{"id":"h:107-5","p":"h","src":"107年第5題","sec":"B","stem":"運用比較法在試算價格之調整運算過程中，區域因素調整、個別因素調整或區域因素及個別因素內之任一單獨項目之價格調整率大於百分之(甲)，或情況、價格日期、區域因素及個別因素調整總調整率大於百分之(乙)時，判定該比較標的與勘估標的差異過大，應排除該比較標的之適用。請問甲與乙各為多少？","opts":["甲為10，乙為20","甲為10，乙為25","甲為15，乙為25","甲為15，乙為30"],"ok":[3],"ex":["甲10、乙20皆與技術規則第25條規定的15%、30%數字不符。","甲10、乙25同樣與規則規定的數字不符。","甲15、乙25，乙的數字應為30而非25，本選項僅甲正確。","技術規則第25條明定：單項調整率上限為15%（甲），總調整率上限為30%（乙），與本選項數字完全相符。"],"tr":"","core":["甲10乙20皆不符，應為15、30","甲10乙25皆不符，應為15、30","乙應為30，非25","單項上限15%，總調整率上限30%"],"hl":[["10","20","15%、30%"],["10","25"],["25","乙的數字應為30"],[]]},{"id":"h:107-6","p":"h","src":"107年第6題","sec":"B","stem":"採用比較法經比較調整後求得之勘估標的試算價格，應就價格偏高或偏低者重新檢討，經檢討確認適當合理者，始得作為決定比較價格之基礎。檢討後試算價格之間差距仍達百分之二十以上者，應排除該試算價格之適用。前者所稱百分之二十以上之差距係指：","opts":["高低價格之差除以高低價格平均值達百分之二十以上者","高低價格之差除以最高價格達百分之二十以上者","高低價格平均值除以最高價格達百分之二十以上者","高低價格平均值除以高低價格之差達百分之二十以上者"],"ok":[0],"ex":["技術規則第26條規定的差距計算方式為「高低價格之差÷高低價格『平均值』」，與本選項描述完全相符。","除以「最高價格」而非平均值，與規則規定的計算基準不符。","「高低價格平均值除以最高價格」是另一種計算邏輯，與規則規定的「差÷平均值」公式不符。","「高低價格平均值除以高低價格之差」是分子分母顛倒，與規則規定不符。"],"tr":"","core":["差距＝高低價差÷高低價平均值","除以最高價格，計算基準不符","平均值÷最高價，邏輯不符","分子分母顛倒"],"hl":[[],["最高價格","而非平均值"],["高低價格平均值除以最高價格","差÷平均值"],["高低價格平均值除以高低價格之差"]]},{"id":"h:107-17","p":"h","src":"107年第17題","sec":"B","stem":"下列有關比較法的敘述，何者錯誤？","opts":["試算價格調整運算過程中，情況因素、價格日期、區域因素、個別因素或區域因素及個別因素內之任一單獨項目之價格調整率不得大於15%，但勘估標的性質或區位特殊，於報告書敘明者，不在此限","試算價格調整運算過程中，情況因素、價格日期、區域因素及個別因素總調整率不得大於30%，但勘估標的性質或區位特殊，於報告書敘明者，不在此限","情況調整係指比較標的之價格形成條件中有非屬於一般正常情形而影響價格時，或有其他足以改變比較標的價格之情況存在時，就該影響部分所作之調整","估價師運用比較法估價時，應採用三件以上比較標的"],"ok":[0],"ex":["本題問「錯誤」。§25 僅就區域因素調整、個別因素調整或其內任一單獨項目之價格調整率大於15%設限；本選項把情況因素、價格日期也併入單項15%之限制，與§25不符，敘述錯誤。考選部標準答案為 A（107 年答案表第 17 題）。","技術規則第25條同樣規定總調整率不得大於30%（但有同樣的例外但書），本選項描述正確。","技術規則第19條第1款明定情況調整之定義，與本選項描述相符，敘述正確。","§27 不動產估價師應採用三件以上比較標的，敘述正確。"],"tr":"","core":["單項15%限區域個別因素，不含情況日期","總調整率不得大於30%，特殊敘明除外","非正常情形影響價格所作調整","應採用三件以上比較標的"],"hl":[["情況因素、價格日期","僅就區域因素調整、個別因素調整"],[],[],[]]},{"id":"h:107-18","p":"h","src":"107年第18題","sec":"B","stem":"王先生手中取得一份不動產估價報告書，比較法推估過程中三個比較案例的價格依序為新臺幣63萬元/坪、64.5萬元/坪、68.5萬元/坪，所推估之試算價格依序分別為新臺幣45萬元/坪、50萬元/坪、57.5萬元/坪，下列敘述何者正確？","opts":["比較案例一總調整率不符規定","比較案例三總調整率不符規定","比較案例一與比較案例三試算價格之差距不符規定","比較案例一與比較案例二之試算價格較接近，應給予較高之權重"],"ok":[2],"ex":["比較案例一的總調整率＝(45－63)÷63≈－28.6%，絕對值未超過§25的30%上限，符合規定，故本敘述錯誤。","比較案例三（68.5萬→57.5萬）調幅約為(68.5-57.5)÷68.5≈16.1%，未超過總調整率30%上限，非本題違規所在。","比較案例一與三之試算價格差距＝(57.5-45)÷[(57.5+45)/2]≈24.4%，已超過技術規則第26條規定的20%上限，應予排除，此為本題正解所在之違規態樣。","§27決定比較價格時，看的是各比較標的資料可信度及與勘估標的價格形成因素的相近程度，不是試算價格彼此是否接近；而且案例一與案例三差距24.4%已達§26的排除標準，本敘述不符規定。"],"tr":"","core":["總調整率約－28.6%，未超過30%","總調整率約16.1%，未超過30%","一與三試算價格差距24.4%，超過20%","權重看可信度及相近程度，非價格接近"],"hl":[["不符規定","絕對值未超過§25的30%上限，符合規定"],["不符規定","未超過總調整率30%上限"],[],["較接近，應給予較高之權重","看的是各比較標的資料可信度及與勘估標的價格形成因素的相近程度"]]},{"id":"h:108-7","p":"h","src":"108年第7題","sec":"B","stem":"經比較調整後求得之勘估標的試算價格，應就價格偏高或偏低者重新檢討，經檢討後試算價格差距如下，何者應排除該試算價格之適用？","opts":["百分之二十五","百分之十五","百分之十","百分之五"],"ok":[0],"ex":["技術規則第26條規定差距達20%以上者應排除，25%已超過20%門檻，符合排除條件。","15%未達20%門檻，依規則不須排除，本選項不符題目「應排除」的條件。","10%同樣未達20%門檻，不符排除條件。","5%遠低於20%門檻，更不符排除條件。"],"tr":"","core":["25%已超過20%門檻，應排除","15%未達20%門檻，不須排除","10%未達20%門檻","5%遠低於20%門檻"],"hl":[[],["百分之十五","15%未達20%門檻"],["百分之十","10%同樣未達20%門檻"],["百分之五","5%遠低於20%門檻"]]},{"id":"h:108-15","p":"h","src":"108年第15題","sec":"B","stem":"有關比較法試算價格之調整運算過程中，遇有下列之情形，須判定該比較標的與勘估標的差異過大，應排除該比較標的之適用。何者為正確？","opts":["區域因素調整率、個別因素調整率，各大於百分之三十","區域因素及個別因素內之任一單獨項目之價格調整率大於百分之十五","區域因素調整率與個別因素調整率之和，大於百分之三十","比較標的性質特殊或區位特殊缺乏市場交易資料，並於估價報告書中敘明者，不在此限"],"ok":[1],"ex":["§25對區域因素調整、個別因素調整本身及其內任一單獨項目的門檻都是大於15%，不是30%；30%是情況、價格日期、區域、個別四項的總調整率門檻。","技術規則第25條明定：區域因素及個別因素內任一單獨項目之價格調整率大於15%，應判定差異過大並排除該比較標的之適用，與本選項完全相符。","規則規範的是「任一單獨項目」分別判斷是否超過15%，而非「調整率之和」大於30%這種加總後再判斷的方式，本選項描述方式與規則原意不符。","§25但書原文是「勘估標的性質特殊或區位特殊缺乏市場交易資料，並於估價報告書中敘明者，不在此限」，本選項把「勘估標的」換成「比較標的」，與條文不符；而且但書是排除規定的例外，不是判定應排除的情形。"],"tr":"","core":["區域個別因素門檻是15%，非30%","單獨項目調整率大於15%應排除","單項分別判斷15%，非兩者加總30%","但書是勘估標的特殊，且屬例外"],"hl":[["百分之三十","門檻都是大於15%"],[],["之和，大於百分之三十","「任一單獨項目」分別判斷是否超過15%"],["比較標的","勘估標的性質特殊或區位特殊缺乏市場交易資料"]]},{"id":"h:108-18","p":"h","src":"108年第18題","sec":"B","stem":"不動產估價師蒐集比較實例時，應依循之原則，下列敘述何者錯誤？","opts":["實例價格形成日期與勘估標的之價格日期接近者","須蒐集與勘估標的使用性質或使用管制相同者之實例","須蒐集與勘估標的位於同一供需圈之近鄰地區或類似地區者之實例","實例價格屬正常價格、可調整為正常價格或與勘估標的價格種類相同者"],"ok":[3],"ex":["技術規則第12條第4款規定「實例價格形成日期與勘估標的之價格日期接近者」，本選項用「接近」與規則§12(4)「接近」用字完全相符，敘述正確。","B選項只說「相同者」，少了「或相近」（規則第12條第3款為「使用性質或使用管制相同或相近者」），與條文不符，是最明確的錯誤選項。","技術規則第12條第2款規定「位於同一供需圈之近鄰地區或類似地區者」，C選項描述正確。","【考選部更正：本題一律給分】本檔答案欄沿用D；但依§12第1款原文「實例之價格屬正常價格、可調整為正常價格或與勘估標的價格種類相同者」，D的敘述與條文一致；對照條文，最明顯的錯誤是B（少了「或相近」）。"],"tr":"","core":["價格形成日期接近，與條文相符","少了「或相近」，與條文不符","同一供需圈近鄰或類似地區，正確","D與條文一致，最明顯錯誤是B"],"hl":[[],["相同者","使用性質或使用管制相同或相近者"],[],[]]},{"id":"h:108-19","p":"h","src":"108年第19題","sec":"B","stem":"有關區域因素之調整，下列敘述何者為正確？","opts":["此項調整，係以比較標的之區域價格水準為基礎，就區域因素不同所產生之價格差異，逐項進行之分析與調整","此項調整為將勘估標的之價格轉化為與比較標的同一近鄰地區內之價格水準","所選用之比較標的係位於同一供需圈但不在同一類似地區內","所謂區域因素，指影響類似地區不動產價格水準之因素"],"ok":[0],"ex":["技術規則§19第3款原文為「區域因素調整：所選用之比較標的與勘估標的不在同一近鄰地區內時，為將比較標的之價格轉化為與勘估標的同一近鄰地區內之價格水準，而以比較標的之區域價格水準為基礎，就區域因素不同所產生之價格差異，逐項進行之分析及調整。」本選項就是條文後段，敘述正確，即本題正解。","區域因素調整的方向是將「比較標的」價格轉化為與「勘估標的」同一近鄰地區內之價格水準，而非反向將勘估標的轉化為比較標的之水準，本選項調整方向與對象顛倒。","§19第3款的前提是比較標的與勘估標的「不在同一近鄰地區內」，本選項改成「不在同一類似地區內」，用語與條文不符。","區域因素的正確定義是「影響『近鄰地區』不動產價格水準之因素」，而非「影響類似地區」，本選項用詞錯誤。"],"tr":"","core":["以比較標的區域價格水準為基礎逐項調整","方向顛倒，應轉化比較標的價格","前提是不在同一近鄰地區","區域因素影響近鄰地區，非類似地區"],"hl":[[],["將勘估標的之價格轉化","「比較標的」價格轉化為與「勘估標的」"],["同一類似地區內","不在同一近鄰地區內"],["類似地區","影響『近鄰地區』不動產價格水準之因素"]]},{"id":"h:108-20","p":"h","src":"108年第20題","sec":"B","stem":"下列敘述何者為正確？","opts":["百分率法與差額法均為將影響勘估標的及比較標的價格差異的一般因素、區域因素與個別因素逐項比較進行價格調整之方法","採比較法估價時，應先進行「情況調整」，再進行「價格日期調整」、「個別因素修正」，最後是「區域因素修正」","對勘估標的價格進行情況調整及價格日期調整","對比較標的價格進行情況調整及價格日期調整"],"ok":[3],"ex":["技術規則第19條規定的調整對象是「區域因素」與「個別因素」，並不包含「一般因素」逐項調整，本選項多列了一般因素，與規則範圍不符。","技術規則§21Ⅰ(3)(4)之調整順序為：情況調整→價格日期調整→區域因素調整→個別因素調整，本選項將區域因素與個別因素順序顛倒（題目稱先個別後區域），與規則規定的順序不符。","情況調整及價格日期調整的對象應為「比較標的」價格（將其轉化為與勘估標的相同條件下之價格），而非對「勘估標的」價格進行調整，本選項調整對象錯誤。","技術規則§21第1項第3款明定「對比較標的價格進行情況調整及價格日期調整」，與本選項逐字相符。"],"tr":"","core":["調整對象是區域個別因素，不含一般因素","順序是先區域再個別，本選項顛倒","調整對象是比較標的，非勘估標的","對比較標的價格作情況及日期調整"],"hl":[["一般因素","調整對象是「區域因素」與「個別因素」"],["個別因素修正","區域因素修正","情況調整→價格日期調整→區域因素調整→個別因素調整"],["對勘估標的價格","情況調整及價格日期調整的對象應為「比較標的」價格"],[]]},{"id":"h:109-6","p":"h","src":"109年第6題","sec":"B","stem":"比較法以比較標的價格為基礎，下列那一項比較標的在正常情況下應排除適用？","opts":["比較標的A的比較因素調整中，情況調整率+5%，價格日期調整率-9%，區域因素調整率-12%，個別因素調整率+10%","比較標的B的比較因素調整中，情況調整率+5%，價格日期調整率-9%，區域因素調整率+12%，個別因素調整率+10%","比較標的C的比較因素調整中，情況調整率+5%，價格日期調整率+9%，區域因素調整率-12%，個別因素調整率-10%","比較標的D的比較因素調整中，情況調整率-5%，價格日期調整率-9%，區域因素調整率-12%，個別因素調整率-10%"],"ok":[3],"ex":["情況+5%、價格日期-9%、區域-12%、個別+10%，總調整率（代數和）＝5-9-12+10＝-6%，絕對值6%遠未超過30%總調整率上限，且任一單項最大值12%未超過15%，不符合排除條件。","情況+5%、價格日期-9%、區域+12%、個別+10%，總調整率＝5-9+12+10＝18%，未超過30%上限，且任一單項最大值12%未超過15%，不符合排除條件。","情況+5%、價格日期+9%、區域-12%、個別-10%，總調整率＝5+9-12-10＝-8%，絕對值8%未超過30%上限，且任一單項最大值12%未超過15%，不符合排除條件。","情況-5%、價格日期-9%、區域-12%、個別-10%，總調整率＝-5-9-12-10＝-36%，絕對值36%已超過技術規則第25條規定的30%總調整率上限，應判定差異過大並排除該比較標的之適用。本題採「出題解讀」：以各項調整率之代數和（取絕對值）計算總調整率（§25並未明定加總方式；若改以各項絕對值加總，A、B、C亦各達36%以上，故答案取決於此解讀），唯有D選項四項調整方向一致（皆為負值），代數和的絕對值才會放大至超標，這正是命題設計的鑑別點。"],"tr":"","core":["總調整率－6%，單項未超過15%","總調整率18%，未超過30%","總調整率－8%，未超過30%","四項同向，總調整率－36%超過30%"]},{"id":"h:109-19","p":"h","src":"109年第19題","sec":"B","stem":"依據不動產估價技術規則規定，試算價格之調整運算過程中，情況、價格日期、區域因素及個別因素等調整的總調整率大於多少幅度時，判定該比較標的與勘估標的差異過大，應排除該比較標的之適用？","opts":["15%","20%","25%","30%"],"ok":[3],"ex":["15%是「單項調整率」（技術規則第25條）的判定門檻，不是總調整率的門檻。","20%是「試算價格差距」（技術規則第26條）的判定門檻，不是總調整率的門檻。","25%並非技術規則規定的任何一道明文門檻數字。","技術規則第25條明定：情況、價格日期、區域因素及個別因素之總調整率大於30%時，判定差異過大應排除該比較標的之適用，與本選項相符。"],"tr":"","core":["15%是單項調整率門檻","20%是試算價格差距門檻","25%非規則任何門檻","總調整率大於30%應排除"],"hl":[["15%","15%是「單項調整率」"],["20%","20%是「試算價格差距」"],["25%"],[]]},{"id":"h:110-12","p":"h","src":"110年第12題","sec":"B","stem":"比較標的於110年1月以2,000萬元成交，當時之價格指數為95；勘估標的之價格日期為110年9月，價格指數為101。假設其他條件皆相同，請問勘估標的經價格日期調整後之價格約為多少？","opts":["2,020萬元","2,105萬元","2,126萬元","2,188萬元"],"ok":[2],"ex":["2,020萬元是把指數101誤當成上漲1%：2,000×101÷100＝2,020萬元，漏了除以交易時指數95。","2,105萬元是只除以交易時指數95、漏乘價格日期指數101：2,000×100÷95≈2,105萬元。","價格日期調整公式：調整後價格＝比較標的成交價×(勘估標的價格日期指數÷比較標的交易日期指數)＝2,000×(101÷95)≈2,126萬元。","2,188萬元無法由題幹常見誤算得到，屬干擾數字。"],"tr":"","core":["101誤當漲1%，漏除以95","只除以95，漏乘101","2,000×101÷95≈2,126萬","無法由常見誤算得到"],"hl":[["2,020萬元","漏了除以交易時指數95"],["2,105萬元","漏乘價格日期指數101"],[],["2,188萬元"]]},{"id":"h:110-18","p":"h","src":"110年第18題","sec":"B","stem":"勘估標的乙之價格日期、勘察日期分別為110年8月15日、110年9月15日，若比較標的交易日期為110年7月10日（經查110年7至9月不動產指數分別為：106%、108%、107%），其價格日期調整百分率為何？","opts":["98%","99%","101%","102%"],"ok":[3],"ex":["98%是指數顛倒：106÷108≈98.1%（把交易日期的指數放在分子）。","99%是誤用勘察日期（9月，指數107），又把指數顛倒：106÷107≈99.1%。","101%是誤用勘察日期（9月）的指數107：107÷106≈100.9%≈101%；價格日期調整要用價格日期（8月15日，對應8月指數108），不是勘察日期。","比較標的交易日期7月10日對應指數106%，勘估標的價格日期8月15日落在7-9月區間需內插或就近取8月指數約108%估算，調整百分率＝108÷106≈102%，與本選項相符。"],"tr":"","core":["指數顛倒：106÷108","誤用勘察日期又顛倒指數","誤用勘察日期9月指數107","價格日期8月指數108÷106≈102%"],"hl":[["98%"],["99%"],["101%","價格日期調整要用價格日期（8月15日，對應8月指數108）"],[]]},{"id":"h:111-11","p":"h","src":"111年第11題","sec":"B","stem":"不動產估價比較法經比較調整後求得之勘估標的試算價格，應就價格偏高或偏低者重新檢討，經檢討確認適當合理者，始得作為決定比較價格之基礎。檢討後試算價格之間差距仍達多少以上者，應排除該試算價格之適用？","opts":["百分之五","百分之十","百分之十五","百分之二十"],"ok":[3],"ex":["5%遠低於技術規則第26條規定的20%門檻。","10%同樣低於20%門檻。","15%仍低於20%門檻，未達排除標準。","技術規則第26條明定：檢討後試算價格之間差距仍達20%以上者，應排除該試算價格之適用，與本選項相符。"],"tr":"","core":["5%遠低於20%門檻","10%低於20%門檻","15%未達20%排除標準","試算價格差距達20%以上應排除"],"hl":[["百分之五","5%遠低於技術規則第26條規定的20%門檻"],["百分之十","10%同樣低於20%門檻"],["百分之十五","15%仍低於20%門檻"],[]]},{"id":"h:111-14","p":"h","src":"111年第14題","sec":"B","stem":"不動產估價比較法於市場成交資訊充足時廣為運用，有關比較法之敘述，下列何者錯誤？","opts":["通常採用三件以上比較標的","試算價格之調整運算過程中，任一單獨項目之價格調整率大於百分之十五，應排除該比較標的之適用","試算價格之調整運算過程中，總調整率大於百分之三十時，應排除該比較標的之適用","其調整以差額法為原則"],"ok":[3],"ex":["技術規則第27條規定應採用「三件以上」比較標的，本選項描述正確，非本題答案（本題問「何者錯誤」）。","技術規則第25條規定任一單獨項目調整率大於15%應排除，本選項描述正確。","技術規則第25條規定總調整率大於30%應排除，本選項描述正確。","技術規則§24明定「其調整以百分率法為原則，亦得以差額法調整」，本選項把原則寫成差額法，即本題正解。"],"tr":"","core":["應採用三件以上比較標的","單獨項目大於15%應排除","總調整率大於30%應排除","調整以百分率法為原則，非差額法"],"hl":[[],[],[],["差額法","其調整以百分率法為原則"]]},{"id":"h:111-24","p":"h","src":"111年第24題","sec":"B","stem":"有一比較標的於110年10月以800萬元成交，當時的價格指數為103.6%，不動產勘估標的之價格日期為111年3月，當時的價格指數為100.3%。假設其他條件相同，請問該勘估標的經價格日期調整後的價格為多少？","opts":["834.7萬元","826.3萬元","789.6萬元","774.5萬元"],"ok":[3],"ex":["834.7萬元無法由題幹常見誤算得到，屬干擾數字。","826.3萬元是指數顛倒：800×103.6÷100.3≈826.3萬元（指數下跌卻往上調）。","789.6萬元無法由題幹常見誤算得到，屬干擾數字（正確為800×100.3÷103.6≈774.5萬元）。","價格日期調整公式：調整後價格＝800×(100.3÷103.6)≈774.5萬元，指數下降代表市場呈現微幅下跌趨勢，調整後價格應低於原成交價。"],"tr":"","core":["無法由常見誤算得到","指數顛倒，下跌卻往上調","干擾數字，正確約774.5萬","800×100.3÷103.6≈774.5萬"],"hl":[["834.7萬元"],["826.3萬元"],["789.6萬元","正確為800×100.3÷103.6≈774.5萬元"],[]]},{"id":"h:112-6","p":"h","src":"112年第6題","sec":"B","stem":"依不動產估價技術規則規定，比較標的為父親賣給兒子之交易，應進行何種調整？","opts":["情況調整","價格日期調整","區域因素調整","個人因素調整"],"ok":[0],"ex":["技術規則§23第4款列有「親友關係人間之交易」，屬應先作適當調整之情況；父親賣給兒子屬親友關係人間交易，依§19第1款所作之調整即為情況調整。","價格日期調整處理的是時間差異致價格水準變動，與交易雙方關係（父子）無關。","區域因素調整處理的是區域位置差異，與交易雙方為父子關係無關。","「個人因素調整」並非技術規則定義的調整項目名稱，技術規則規定的是「個別因素調整」（標的本身條件差異），且與本題交易雙方關係無關。"],"tr":"","core":["父子屬親友交易，作情況調整","日期調整處理時間差，與父子無關","區域調整處理位置差，與父子無關","無個人因素調整，應為個別因素"],"hl":[[],["價格日期調整","處理的是時間差異致價格水準變動"],["區域因素調整","處理的是區域位置差異"],["個人因素調整","技術規則規定的是「個別因素調整」"]]},{"id":"h:112-23","p":"h","src":"112年第23題","sec":"B","stem":"比較法估價試算價格之調整運算過程中，區域因素調整、個別因素調整或區域因素及個別因素內之任一單獨項目之價格調整率大於（甲），或情況、價格日期、區域因素及個別因素調整總調整率大於（乙）時，判定該比較標的與勘估標的差異過大，應排除該比較標的之適用。請問（甲）與（乙）各為多少？","opts":["（甲）為百分之十五，（乙）為百分之十五","（甲）為百分之十五，（乙）為百分之三十","（甲）為百分之三十，（乙）為百分之十五","（甲）為百分之三十，（乙）為百分之三十"],"ok":[1],"ex":["甲乙皆為15%與規則規定的甲15%、乙30%不符，乙的數字錯誤。","技術規則第25條明定：單項調整率上限15%（甲），總調整率上限30%（乙），與本選項完全相符。","甲乙數字對調，與規則規定相反。","甲乙皆設為30%，甲的數字應為15%而非30%，本選項甲的數字錯誤。"],"tr":"","core":["乙應為30%，非15%","單項上限15%，總調整率上限30%","甲乙數字對調","甲應為15%，非30%"],"hl":[["（乙）為百分之十五","甲15%、乙30%"],[],["（甲）為百分之三十","（乙）為百分之十五"],["（甲）為百分之三十","甲的數字應為15%"]]},{"id":"h:113-7","p":"h","src":"113年第7題","sec":"B","stem":"有關比較法的敘述下列何者錯誤？","opts":["比較標的價格經情況調整、價格日期調整、區域因素調整及個別因素調整後所獲得之價格稱為比較價格","比較法指以比較標的價格為基礎，經比較、分析及調整等，以推算勘估標的價格之方法","價格日期調整是指比較標的之交易日期與勘估標的之價格日期因時間之差異，致價格水準發生變動，應以適當之變動率或變動金額，將比較標的價格調整為勘估標的價格日期之價格","比較標的與勘估標的不在同一近鄰地區內時，為將比較標的之價格轉化為與勘估標的同一近鄰地區內之價格水準的調整稱為區域因素調整"],"ok":[0],"ex":["比較標的價格經各項調整後所得之價格，應稱為「試算價格」（§21Ⅱ）；試算價格須經§26檢討，並依§21Ⅰ⑥、§27決定比較價格（§18Ⅱ：依前項方法所求得之價格為比較價格）。本選項把調整後的價格直接稱為比較價格，此為錯誤敘述。","技術規則第18條明定比較法之定義，與本選項描述相符，敘述正確。","技術規則第19條第2款明定價格日期調整之定義，與本選項描述相符，敘述正確。","技術規則第19條第3款明定區域因素調整之定義，與本選項描述相符，敘述正確。"],"tr":"","core":["調整後價格是試算價格，非比較價格","比較標的價格調整推算＝比較法","時間差致價格變動所作調整","比較標的價格轉化為同近鄰地區水準"],"hl":[["稱為比較價格","應稱為「試算價格」"],[],[],[]]},{"id":"h:113-8","p":"h","src":"113年第8題","sec":"B","stem":"不動產估價技術規則第26條第1項：經比較調整後求得之勘估標的試算價格，應就價格偏高或偏低者重新檢討，經檢討確認適當合理者，始得作為決定比較價格之基礎。檢討後試算價格之間差距仍達百分之二十以上者，應排除該試算價格之適用。若比較標的一、二、三之試算價格分別為79萬元/坪，77萬元/坪及95萬元/坪，下列敘述何者正確？","opts":["三個試算價格之間皆符合排除條件","三個試算價格之間皆不符合排除條件","比較標的一與三之間符合排除條件","比較標的二與三之間符合排除條件"],"ok":[3],"ex":["一與二差距＝(79－77)÷78≈2.6%、一與三≈18.4%，都未達20%，只有二與三≈20.9%達標，故並非三者皆符合排除條件。","二與三差距＝(95－77)÷86≈20.9%，已達§26的20%，故並非三者皆不符合排除條件。","比較標的一（79）與三（95）之差距＝(95-79)÷[(95+79)/2]≈18.4%，未達20%門檻，不符合排除條件。","比較標的二（77）與三（95）之差距＝(95-77)÷[(95+77)/2]≈20.9%，已超過技術規則第26條規定的20%門檻，符合排除條件，此為本題正解。"],"tr":"","core":["只有二與三達20.9%，非皆排除","二與三差距20.9%已達20%","一與三差距18.4%，未達20%","二與三差距20.9%，符合排除條件"],"hl":[["皆符合排除條件","只有二與三≈20.9%達標"],["皆不符合排除條件","二與三差距＝(95－77)÷86≈20.9%"],["符合排除條件","≈18.4%，未達20%門檻"],[]]},{"id":"h:113-23","p":"h","src":"113年第23題","sec":"B","stem":"依據不動產估價技術規則規定試算價格的價格決定，那一項不適用？","opts":["試算價格調整過程中，任一單獨項目之價格調整率大於15%時應排除","試算價格調整過程中，總調整率大於20%應排除","試算價格調整過程中，總調整率大於30%應排除","試算價格調整過程中，試算價格之間差距達20%以上應排除"],"ok":[1],"ex":["技術規則第25條規定任一單獨項目調整率大於15%應排除，本選項描述正確，適用本規則，非本題答案（本題問「那一項不適用」）。","技術規則第26條規定的是試算價格「差距」達20%以上應排除，而非「調整過程中總調整率」大於20%應排除，本選項把總調整率的門檻誤植為20%（正確應為30%），與規則規定不符，即本題正解（不適用）。","技術規則第25條規定總調整率大於30%應排除，本選項描述正確，適用本規則。","技術規則第26條規定試算價格之間差距達20%以上應排除，本選項描述正確，適用本規則。"],"tr":"","core":["單獨項目大於15%應排除","總調整率門檻是30%，非20%","總調整率大於30%應排除","試算價格差距達20%以上應排除"],"hl":[[],["總調整率大於20%","正確應為30%"],[],[]]},{"id":"h:113-22","p":"h","src":"113年第22題","sec":"B","stem":"比較標的於112年9月以3,060萬元售出，當時房價指數為102；勘估標的價格日期為113年5月，房價指數上漲至105。假設其他條件相同，勘估標的經價格日期調整後的應該是多少？","opts":["2,970萬元","3,150萬元","3,240萬元","3,210萬元"],"ok":[1],"ex":["2,970萬元是指數顛倒：3,060×102÷105≈2,972.6≈2,970萬元（等於把上漲當成下跌）。","價格日期調整公式：調整後價格＝3,060×(105÷102)≈3,150萬元，房價指數上升代表市場呈現上漲趨勢，調整後價格應高於原成交價。","3,240萬元是把漲幅算成兩倍：3,060×(1＋2×3÷102)＝3,240萬元；正確為3,060×105÷102＝3,150萬元。","3,210萬元是只乘105%、沒有除以交易時指數102：3,060×105%＝3,213≈3,210萬元。"],"tr":"","core":["指數顛倒，上漲當成下跌","漲幅算成兩倍的誤算","3,060×105÷102≈3,150萬","只乘105%，漏除以102"],"hl":[["2,970萬元"],[],["3,240萬元","正確為3,060×105÷102＝3,150萬元"],["3,210萬元","沒有除以交易時指數102"]]},{"id":"h:114-4","p":"h","src":"114年第4題","sec":"B","stem":"比較標的為與法定用途不符之交易，應先作適當之調整才能採用，此為何種調整？","opts":["情況調整","價格日期調整","區域因素調整","個別因素調整"],"ok":[0],"ex":["技術規則第23條第12款明定：比較標的之交易與法定用途不符者，應先作適當調整才能採用，此屬情況調整之範疇。","價格日期調整處理的是時間差異致價格水準變動，與「法定用途不符」這種交易條件異常無關。","區域因素調整處理的是區域位置差異，與「法定用途不符」這種交易本身的異常情況無關。","個別因素調整處理的是標的本身條件差異（面積、形狀等），與交易是否符合法定用途無關，此為交易情況層面的問題，應屬情況調整。"],"tr":"","core":["與法定用途不符屬情況調整","日期調整與用途不符無關","區域調整與交易異常無關","個別因素看標的條件，非交易情況"],"hl":[[],["價格日期調整","處理的是時間差異致價格水準變動"],["區域因素調整","處理的是區域位置差異"],["個別因素調整","應屬情況調整"]]},{"id":"h:114-5","p":"h","src":"114年第5題","sec":"B","stem":"下列價格調整率何者符合不動產估價技術規則之規定？","opts":["區域因素總價格調整率為18%","個別因素總價格調整率為18%","個別因素內之任一單獨項目之價格調整率為18%","情況、價格日期、區域因素及個別因素調整總調整率為18%"],"ok":[3],"ex":["§25明定「區域因素調整、個別因素調整，或其內任一單獨項目」之價格調整率大於15%者應排除；區域因素整體調整率18%即已大於15%，直接不符規定，不必假設是單獨項目。","同理，個別因素整體調整率18%已大於§25之15%限制，直接不符規定。","個別因素內任一單獨項目之價格調整率18%，已明確超過技術規則第25條規定的15%單項調整率上限，不符合規定。","情況、價格日期、區域因素及個別因素「調整總調整率」18%，未超過技術規則第25條規定的30%總調整率上限，符合規定。"],"tr":"","core":["區域因素調整率18%大於15%","個別因素調整率18%大於15%","單項18%超過15%上限","總調整率18%未超過30%"],"hl":[["18%","價格調整率大於15%者應排除"],["18%","§25之15%限制"],["18%","15%單項調整率上限"],[]]},{"id":"h:100-38","p":"h","src":"100年第38題","sec":"B","stem":"兩宗土地合併後整體利用，合併後價格為1,000萬元，其合併前價格分別為300萬元及500萬元，則對於原來500萬元之土地，其合併後價格應為：","opts":["600萬元","700萬元","625萬元","425萬元"],"ok":[2],"ex":["600萬元是把合併增值200萬元（1,000－800）平均分給兩宗：500＋200÷2＝600萬元；應依合併前價格比例分配。","700萬元是把合併增值200萬元全歸500萬元那宗（500＋200，即1,000－300），沒有按比例分配。","合併增值法公式：某宗合併後價格＝合併後總價×(該宗合併前價格÷各宗合併前總和)＝1,000×(500÷800)＝625萬元，與本選項相符。","425萬元無法由題幹常見誤算得到，屬干擾數字（正確為1,000×500÷800＝625萬元；另一宗合併後為375萬元）。"],"tr":"","core":["增值平均分配，應按比例分配","增值全歸一宗，未按比例","1,000×500÷800＝625萬","干擾數字，另一宗才是375萬"],"hl":[["600萬元","應依合併前價格比例分配"],["700萬元"],[],["425萬元","正確為1,000×500÷800＝625萬元"]]},{"id":"h:106-7","p":"h","src":"106年第7題","sec":"B","stem":"不動產估價比較法就「畸零地或有合併使用之交易」所進行之調整，是屬於下列何項調整？","opts":["情況調整","價格日期調整","區域因素調整","個別因素調整"],"ok":[0],"ex":["技術規則§23第5款列有「畸零地或有合併使用之交易」，屬應先作適當調整之比較標的情況，依§19第1款即為情況調整；（教材）這類交易常因買方有合併使用需求而出價偏離正常價格。","價格日期調整處理的是時間差異致價格水準變動，與合併使用動機無關。","區域因素調整處理的是區域位置差異，與合併使用動機無關。","個別因素調整處理的是標的本身條件差異（面積、形狀等），與買方合併使用動機不同（合併使用造成的溢價是情況層面的調整）。"],"tr":"","core":["畸零地或合併使用屬情況調整","日期調整與合併使用動機無關","區域調整與合併使用動機無關","合併溢價是情況層面，非個別因素"],"hl":[[],["價格日期調整","處理的是時間差異致價格水準變動"],["區域因素調整","處理的是區域位置差異"],["個別因素調整","合併使用造成的溢價是情況層面的調整"]]},{"id":"h:107-24","p":"h","src":"107年第24題","sec":"B","stem":"三筆土地分別為1500萬元、2500萬元及6000萬元，今決定將三筆土地合併開發，經評估合併後土地總價值為1億5千萬元，請問相對於原來1500萬元之土地，其合併後價格應為：","opts":["3750萬元","2250萬元","9000萬元","2500萬元"],"ok":[1],"ex":["3,750萬元是誤用2,500萬元那宗的比例：15,000×2,500÷10,000＝3,750萬元。","合併增值法公式：1500萬元那宗合併後價格＝15,000×(1,500÷10,000)＝15,000×0.15＝2,250萬元，與本選項相符。","9,000萬元是誤用6,000萬元那宗的比例：15,000×6,000÷10,000＝9,000萬元。","2,500萬元無法由常見誤算得到（恰為第二宗的合併前價格），屬干擾數字。"],"tr":"","core":["誤用2,500萬那宗的比例","15,000×0.15＝2,250萬","誤用6,000萬那宗的比例","恰為第二宗合併前價格，干擾數字"],"hl":[["3750萬元"],[],["9000萬元"],["2500萬元"]]},{"id":"h:108-4","p":"h","src":"108年第4題","sec":"B","stem":"設三宗土地合併後整體開發利用，其合併後價格為2,500萬元，合併前價格分別為800萬元、500萬元及700萬元。則對於原來700萬元之土地，其合併後之價格應為何？","opts":["825萬元","850萬元","875萬元","895萬元"],"ok":[2],"ex":["825萬元無法由題幹常見誤算得到，屬干擾數字（正確為2,500×700÷2,000＝875萬元）。","850萬元無法由題幹常見誤算得到，屬干擾數字（正確為2,500×700÷2,000＝875萬元）。","合併增值法公式：700萬元那宗合併後價格＝2,500×(700÷2,000)＝2,500×0.35＝875萬元，與本選項相符。","895萬元無法由題幹常見誤算得到，屬干擾數字（正確為2,500×700÷2,000＝875萬元）。"],"tr":"","core":["干擾數字，正確為875萬","干擾數字，正確為875萬","2,500×700÷2,000＝875萬","干擾數字，正確為875萬"],"hl":[["825萬元","正確為2,500×700÷2,000＝875萬元"],["850萬元","正確為2,500×700÷2,000＝875萬元"],[],["895萬元","正確為2,500×700÷2,000＝875萬元"]]},{"id":"h:99-7","p":"h","src":"99年第7題","sec":"C1","stem":"按工程概算項目逐項比較勘估標的與比較標的或標準建物之差異，並依工程價格及工程數量比率進行調整，以求取勘估標的營造或施工費方法，稱之為：","opts":["淨計法","工程造價比較法","單位工程法","單位面積比較法"],"ok":[1],"ex":["淨計法是逐一材料人工數量乘以單價工資之直接法，與題目所述「按工程概算項目逐項比較調整」之間接法性質不同。","技術規則明定工程造價比較法：按工程概算項目逐項比較勘估標的與比較標的或標準建物之差異，並依工程價格及工程數量比率進行調整，與題目敘述完全相符。","單位工程法是建築細部工程各項目單價乘以施工數量之直接法，與題目所述間接法性質不同。","單位面積比較法是以單位面積營造費為基礎乘以勘估標的面積，與題目所述「逐項比較工程概算項目」之具體操作方式不同。"],"tr":"","core":["淨計法逐一材料人工，屬直接法","工程造價比較法按概算項目逐項比較調整","單位工程法是細部項目單價×數量","單位面積比較法以單位面積營造費為準"],"hl":[["淨計法","逐一材料人工數量乘以單價工資之直接法"],[],["單位工程法","建築細部工程各項目單價乘以施工數量之直接法"],["單位面積比較法","以單位面積營造費為基礎乘以勘估標的面積"]]},{"id":"h:99-8","p":"h","src":"99年第8題","sec":"C1","stem":"根據不動產估價技術規則規定，成本法中估算勘估標的資本利息之敘述，何者正確？","opts":["應依分期投入資本數額及資本使用年數","預售收入之資金應計息","若勘估標的包含土地時，不應另加計土地價格","自有資金之計息利率可高於1年以上活存利率"],"ok":[0],"ex":["技術規則明定資本利息應依分期投入資本數額及資本使用年數計息，與題目敘述相符，為正確敘述。","預售收入之資金不計息（§59），故「預售收入之資金應計息」敘述錯誤。","勘估標的為土地或包含土地者，資本利息的計息合計額要另加計土地價格（§58Ⅲ），總成本也要加計土地價格（§52Ⅱ）；本選項「不應另加計」與規定相反，敘述錯誤。","§59 規定自有資金之計息利率「應不高於一年期定存利率且不低於活存利率」，所以高於活存利率本身並不違規；本選項錯在把上限基準寫成「1年以上活存利率」，條文的上限是「一年期定存利率」，用語與條文不符，不選。"],"tr":"","core":["依分期投入資本數額及使用年數計息","預售收入之資金不計息","含土地時應另加計土地價格","上限是一年期定存利率，用語不符"],"hl":[[],["應計息","預售收入之資金不計息"],["不應另加計","資本利息的計息合計額要另加計土地價格"],["可高於","應不高於一年期定存利率且不低於活存利率"]]},{"id":"h:99-21","p":"h","src":"99年第21題","sec":"C1","stem":"若勘估標的同時包含土地與建物，但視為無建物存在之素地進行估價，稱之為何？","opts":["部分估價","獨立估價","限制估價","特殊估價"],"ok":[1],"ex":["部分估價是附有建物之宗地估價，考慮建物對宗地價格造成之影響，與題目所述「視為無建物存在」之定義相反。","教材所稱「獨立估價」，是指土地上有建物，但估價時將土地視為素地估價、不考慮建物的影響；技術規則沒有這個名稱，對應的是§86但書「以素地估價為前提並於估價報告書敘明者，不在此限」，與題目敘述相符。","「限制估價」並非技術規則明定之正式估價類型名稱。","「特殊估價」並非技術規則明定之正式估價類型名稱（特殊價格是價格種類而非估價方法類型）。"],"tr":"","core":["部分估價考慮建物影響，定義相反","有建物但視為素地估價＝獨立估價","限制估價非正式估價類型","特殊估價非正式估價類型"],"hl":[["部分估價","附有建物之宗地估價"],[],["限制估價","並非技術規則明定之正式估價類型名稱"],["特殊估價","特殊價格是價格種類而非估價方法類型"]]},{"id":"h:99-32","p":"h","src":"99年第32題","sec":"C1","stem":"勘估標的如果是區分所有建物時，以其房地價格推估該區分所有建物基地單價時，下列估計方式的敘述何種有誤？","opts":["該區分所有建物基地權利價格＝該區分所有建物房地價格－該區分所有建物之建物成本價格","該區分所有建物之基地權利單價＝該區分所有建物基地權利價格／該區分所有建物之基地持分面積","基地單價＝該區分所有建物之基地權利單價×平均地價分配率／該區分所有建物之地價分配率","基地單價＝該區分所有建物基地持分價格×該區分所有建物之基地持分面積"],"ok":[3],"ex":["技術規則第100條（區分所有建物基地權利價格；§99 為基地價格）明定：基地權利價格＝房地價格－建物成本價格，此為正確之計算公式，非本題答案（本題問「何種有誤」）。","基地權利單價＝基地權利價格÷基地持分面積，此為正確之計算公式。","本公式與§100第1項第3款逐字相同（以地價分配率調整），為正確公式，不選；以樓層別效用比調整的是§101第1項第3款。","「基地單價＝基地持分價格×基地持分面積」此公式邏輯有誤，基地單價應是「單位面積價格」，以總價格乘以面積會得出更大的數值而非單價，正確應為基地持分價格除以面積，本選項運算方式錯誤，即本題正解。"],"tr":"","core":["基地權利價格＝房地價格－建物成本","基地權利單價＝權利價格÷持分面積","以地價分配率調整之正確公式","單價應是價格除以面積，非相乘"],"hl":[[],[],[],["×該區分所有建物之基地持分面積","正確應為基地持分價格除以面積"]]},{"id":"h:99-34","p":"h","src":"99年第34題","sec":"C1","stem":"下列何者非估計勘估標的之營造或施工費時應包括之成本？","opts":["稅捐","間接人工費","資本利息","廣告費"],"ok":[3],"ex":["稅捐是技術規則明定營造施工費應包括之成本項目之一，非本題答案（本題問「非」應包括之成本）。","間接人工費是營造施工費之構成項目，應包括在內。","資本利息是技術規則明定營造施工費應包括之成本項目之一。","廣告費屬於總成本中「間接成本」之廣告銷售費範疇，並非「營造或施工費」本身應包括之項目（營造施工費是直接成本，廣告費是間接成本之另一獨立項目），即本題正解。"],"tr":"","core":["稅捐屬營造施工費應包括項目","間接人工費屬營造施工費構成項目","資本利息屬營造施工費應包括項目","廣告費是間接成本，非營造施工費"],"hl":[[],[],[],["廣告費","廣告費屬於總成本中「間接成本」之廣告銷售費範疇"]]},{"id":"h:99-36","p":"h","src":"99年第36題","sec":"C1","stem":"依建築細部工程之各項目單價，乘以該工程施工數量，並合計之，此方法為何？","opts":["工程造價比較法","單位工程法","淨計法","單位面積比較法"],"ok":[1],"ex":["工程造價比較法是按工程概算項目逐項比較調整之間接法，與題目所述「依細部工程項目單價乘以施工數量」之具體計算方式不同。","技術規則明定單位工程法係依建築細部工程之各項目單價，乘以該工程施工數量，並合計之，與題目敘述完全相符。","淨計法是逐一材料人工數量乘以單價工資，計算單位是材料人工而非建築細部工程項目，與題目敘述不同。","單位面積比較法是以單位面積營造費為基礎乘以面積，計算單位是整體面積而非細部工程項目，與題目敘述不同。"],"tr":"","core":["工程造價比較法是間接法","細部工程單價×施工數量＝單位工程法","淨計法以材料人工為計算單位","單位面積比較法以整體面積計算"],"hl":[["工程造價比較法","按工程概算項目逐項比較調整之間接法"],[],["淨計法","逐一材料人工數量乘以單價工資"],["單位面積比較法","以單位面積營造費為基礎乘以面積"]]},{"id":"h:99-38","p":"h","src":"99年第38題","sec":"C1","stem":"下列有關成本法中估算勘估標的資本利息之敘述何者錯誤？","opts":["應依分期投入資本數額及資本使用年數計息","自有資金不應計息","若勘估標的包含土地時，土地價格亦應計息","資本利息之計算應按各項費用之合計額乘上利率計算"],"ok":[1],"ex":["資本利息應依分期投入資本數額及資本使用年數計息，此為正確敘述，非本題答案（本題問「何者錯誤」）。","技術規則明定自有資金「應」計息（計息利率不高於1年期定存、不低於活存），並非不應計息，本選項與規則規定相反，即本題正解。","若勘估標的包含土地，土地價格亦應計息，此為正確敘述。","§58Ⅱ：按營造施工費、規劃設計費、廣告費、銷售費、管理費、稅捐及其他負擔之合計額乘以利率計算，此為正確敘述（合計額不含資本利息本身與利潤；含土地者另加土地價格）。"],"tr":"","core":["依分期投入資本數額及使用年數計息","自有資金應計息，非不計息","含土地時土地價格亦應計息","按各項費用合計額乘利率計算"],"hl":[[],["不應計息","自有資金「應」計息"],[],[]]},{"id":"h:100-11","p":"h","src":"100年第11題","sec":"C1","stem":"運用成本法進行不動產估價，下列何者不需納入計算？","opts":["土地總成本","建物總成本","建物累積折舊額","土地增值"],"ok":[3],"ex":["土地總成本是成本法房地成本價格計算之必要組成部分，需納入計算，非本題答案（本題問「不需」納入計算）。","建物總成本（扣除折舊後為建物成本價格）是成本法計算之必要組成部分，需納入計算。","建物累積折舊額是計算建物成本價格（重建成本扣除折舊）之必要項目，需納入計算。","土地增值是指土地價格隨時間上漲之金額變化，並非成本法計算房地成本價格時應納入之獨立計算項目（成本法著重於成本之加總，非市場增值幅度之計算），即本題正解。"],"tr":"","core":["土地總成本須納入計算","建物總成本須納入計算","累積折舊額須納入計算","土地增值非成本法計算項目"],"hl":[[],[],[],["土地增值","並非成本法計算房地成本價格時應納入之獨立計算項目"]]},{"id":"h:100-16","p":"h","src":"100年第16題","sec":"C1","stem":"依不動產估價技術規則規定，以成本法推估建物折舊前之價格時，以求取何種成本為原則？","opts":["重製成本","重置成本","重建成本","營造成本"],"ok":[2],"ex":["「重製成本」並非技術規則明定之正式用語（正確用語為重建成本或重置成本）。","重置成本是建材無生產或施工方法改變時之例外替代成本，並非折舊前價格推估之原則性成本。","技術規則明定建物折舊前之價格，以求取重建成本為原則，與題目敘述完全相符。","「營造成本」並非技術規則明定折舊前價格推估之正式專有名詞（營造或施工費是總成本之構成項目之一，非折舊前價格之原則用語）。"],"tr":"","core":["重製成本非規則正式用語","重置成本是例外替代成本","折舊前價格以重建成本為原則","營造成本非規則正式用語"],"hl":[["重製成本","正確用語為重建成本或重置成本"],["重置成本","建材無生產或施工方法改變時之例外替代成本"],[],["營造成本","營造或施工費是總成本之構成項目之一"]]},{"id":"h:100-18","p":"h","src":"100年第18題","sec":"C1","stem":"下列何者不屬於營造或施工費應考量之項目？","opts":["銷售費","稅捐","資本利息","利潤"],"ok":[0],"ex":["銷售費屬於總成本中「間接成本」之廣告銷售費項目，並非「營造或施工費」本身應考量之項目，即本題正解（本題問「不屬於」營造施工費應考量之項目）。","稅捐是技術規則明定營造施工費應考量之項目之一。","資本利息是技術規則明定營造施工費應考量之項目之一。","利潤是技術規則明定營造施工費應考量之項目之一。"],"tr":"","core":["銷售費是間接成本，非營造施工費","稅捐屬營造施工費考量項目","資本利息屬營造施工費考量項目","利潤屬營造施工費考量項目"],"hl":[["銷售費","銷售費屬於總成本中「間接成本」之廣告銷售費項目"],[],[],[]]},{"id":"h:100-32","p":"h","src":"100年第32題","sec":"C1","stem":"不動產估價技術規則規定：「建物已不具備使用價值，將其基地視為素地估價」，此為：","opts":["部分估價","獨立估價","限制估價","特殊估價"],"ok":[1],"ex":["部分估價是考慮建物對宗地價格之影響，與題目所述「建物已不具使用價值，視為素地估價」之定義相反。","題述文字出自技術規則§106「建物已不具備使用價值，得將其基地視為素地估價（但應考量建物拆除成本予以調整）」；將土地視為素地估價，教材稱為「獨立估價」，故選之。","「限制估價」並非技術規則明定之正式估價類型名稱。","「特殊估價」並非技術規則明定之正式估價類型名稱。"],"tr":"","core":["部分估價考慮建物影響，定義相反","建物無使用價值視為素地＝獨立估價","限制估價非正式估價類型","特殊估價非正式估價類型"],"hl":[["部分估價","考慮建物對宗地價格之影響"],[],["限制估價"],["特殊估價"]]},{"id":"h:101-3","p":"h","src":"101年第3題","sec":"C1","stem":"於民國100年評估一棟20年前建造、樓地板面積200坪之建物，該建物之建築成本於民國80年每坪5萬元、100年每坪10萬元，如經濟耐用年數為50年、殘餘價格率為10％。若採定額法折舊，請問該建物之成本價格為何？","opts":["720萬元","1,000萬元","1,280萬元","2,000萬元"],"ok":[2],"ex":["720萬元僅為累積折舊額本身之數值，並非扣除折舊後之成本價格（成本價格須以重建成本減去累積折舊額），混淆了折舊額與最終成本價格。","1,000萬元＝200坪×5萬元（民國80年造價），既沒有改用價格日期（100年）每坪10萬元的重建成本，也沒有扣折舊。","重建成本應採價格日期（民國100年）當時造價標準，即每坪10萬元×200坪＝2,000萬元；年折舊額＝2,000×(1-10%)÷50＝36萬元；累積折舊（20年）＝36×20＝720萬元；成本價格＝2,000－720＝1,280萬元，與本選項相符。","2,000萬元僅為未扣除折舊之重建成本總額，並非扣除累積折舊後之最終成本價格。"],"tr":"","core":["720萬只是累積折舊額","用80年造價且未扣折舊","2,000萬－累積折舊720萬＝1,280萬","2,000萬是未扣折舊的重建成本"],"hl":[["720萬元","累積折舊額本身之數值"],["1,000萬元","沒有改用價格日期（100年）每坪10萬元的重建成本"],[],["2,000萬元","僅為未扣除折舊之重建成本總額"]]},{"id":"h:101-4","p":"h","src":"101年第4題","sec":"C1","stem":"依不動產估價技術規則規定，勘估標的營造費求取方式中稱直接法者分為那兩種？①淨計法　②單位工程法　③工程造價比較法　④單位面積比較法　⑤粗算法","opts":["①②","②③","③④","④⑤"],"ok":[0],"ex":["技術規則明定直接法分為淨計法與單位工程法兩種，與本選項①②組合完全相符。","②單位工程法屬直接法，但③工程造價比較法屬間接法，混合兩類方法，組合錯誤。","③④兩項皆屬間接法（工程造價比較法、單位面積比較法），非直接法之子方法。","④單位面積比較法屬間接法，⑤「粗算法」並非技術規則明定之正式方法名稱，組合錯誤。"],"tr":"","core":["直接法分淨計法與單位工程法","③工程造價比較法屬間接法","③④皆屬間接法","④屬間接法，⑤非正式方法"],"hl":[[],["②③","③工程造價比較法屬間接法"],["③④","皆屬間接法（工程造價比較法、單位面積比較法）"],["④⑤","④單位面積比較法屬間接法"]]},{"id":"h:101-12","p":"h","src":"101年第12題","sec":"C1","stem":"營造費＝［Σ（標準建物工程概算項目每坪單價×單價調整率）］×總面積，此可為下列何種方法之計算公式？","opts":["淨計法","單位工程法","工程造價比較法","單位面積比較法"],"ok":[2],"ex":["淨計法是逐一材料人工數量乘以單價工資，計算單位是材料人工，與題目所述「標準建物工程概算項目每坪單價」之公式結構不同。","單位工程法是建築細部工程各項目單價乘以施工數量，計算單位是工程項目，與題目所述以「標準建物」概算項目單價為基礎之公式不同。","題目公式為：營造費＝［Σ（標準建物工程概算項目每坪單價×單價調整率）］×總面積，此正是工程造價比較法依工程概算項目逐項比較調整之具體計算公式呈現方式。","單位面積比較法是以比較標的單位面積營造費為基礎調整，與題目公式中逐項加總「各工程概算項目」之結構不同（工程造價比較法是逐項計算後加總，單位面積比較法是整體單價調整）。"],"tr":"","core":["淨計法以材料人工為計算單位","單位工程法以細部工程項目計算","標準建物概算項目逐項調整＝工程造價比較","單位面積比較法是整體單價調整"],"hl":[["淨計法","逐一材料人工數量乘以單價工資"],["單位工程法","建築細部工程各項目單價乘以施工數量"],[],["單位面積比較法","以比較標的單位面積營造費為基礎調整"]]},{"id":"h:101-17","p":"h","src":"101年第17題","sec":"C1","stem":"採成本法估價時，必須先求取某一基準日期重新建造對象不動產的原價，該基準日期稱為：","opts":["估價日期","勘察日期","出件日期","試算日期"],"ok":[0],"ex":["題述的基準日期，條文用語是「價格日期」（§2第7款）；「估價日期」並非技術規則用語，四個選項都沒有正確名稱，所以考選部更正本題一律給分。","勘察日期是赴現場調查之日期，與「重新建造原價」之價格基準日期定義不同。","「出件日期」並非技術規則明定之正式用語。","「試算日期」並非技術規則明定之正式用語（試算價格是比較法之概念，非此處之基準日期名稱）。"],"tr":"","core":["條文用語是價格日期，本題一律給分","勘察日期是赴現場調查日期","出件日期非規則正式用語","試算日期非規則正式用語"],"hl":[[],["勘察日期","赴現場調查之日期"],["出件日期"],["試算日期"]]},{"id":"h:101-27","p":"h","src":"101年第27題","sec":"C1","stem":"以定額法計算建築物折舊額時，係假定在不動產耐用期間：","opts":["每年乘以一定比率計算折舊額","期初先確定減價額，累計時呈現減價額遞減","每年之減價額劃一計算，與經過年數逐年累計","每年折舊提存一定金額，以複利計算其總減價額"],"ok":[2],"ex":["「每年乘以一定比率計算折舊額」是定率法之計算邏輯（依固定比率對前一年餘值計算），非定額法。","「期初先確定減價額，累計時呈現減價額遞減」並非定額法之描述，定額法每年折舊額固定不遞減。","定額法假定每年之減價額（折舊額）劃一固定計算，隨經過年數逐年累計，與題目敘述完全相符（這是等速折舊路徑之計算方式）。","「每年折舊提存一定金額，以複利計算總減價額」是償債基金法之計算邏輯（複利提存概念），非定額法。"],"tr":"","core":["每年乘一定比率是定率法","定額法每年折舊額固定不遞減","每年減價額劃一，逐年累計","複利提存是償債基金法"],"hl":[["每年乘以一定比率","定率法之計算邏輯（依固定比率對前一年餘值計算）"],["減價額遞減","定額法每年折舊額固定不遞減"],[],["以複利計算","償債基金法之計算邏輯"]]},{"id":"h:101-33","p":"h","src":"101年第33題","sec":"C1","stem":"從已知投資成分的價值，乘以資本化率，求得其收益後，由總收益中扣除，進而求得未知投資成分之價格的方法，上述方法稱為：","opts":["分配法","積算法","殘餘法","收益倍數法"],"ok":[2],"ex":["分配法（教材用語）是以房地合併的總價格扣除已知部分（如建物）的「價格」，求未知部分的價格，屬比較法案例的處理技巧；題述是以「收益」扣除，屬收益法的殘餘法，不選。","積算法（教材用語）是租金估計方法：以勘估標的之基礎價格乘以期待利率，再加計必要費用求取租金，與題述「由總收益扣除已知成分收益求未知成分價格」不同。","殘餘法之核心邏輯即為從已知投資成分（如土地或建物）價值乘以資本化率求得其應有收益，再從總收益中扣除，剩餘部分即為未知投資成分之收益，據以反推其價格，與題目敘述完全相符（此為土地貢獻說/建物貢獻說背後常用之計算邏輯）。","「收益倍數法」通常指以收益乘數估算價格之簡化方法，與題目所述扣除已知成分收益以求未知成分價格之邏輯不同。"],"tr":"","core":["分配法以價格扣除，屬比較法技巧","積算法是租金估計方法","扣已知成分收益求未知價格＝殘餘法","收益倍數法以收益乘數估價"],"hl":[["分配法","以房地合併的總價格扣除已知部分（如建物）的「價格」"],["積算法","以勘估標的之基礎價格乘以期待利率，再加計必要費用求取租金"],[],["收益倍數法","以收益乘數估算價格之簡化方法"]]},{"id":"h:101-36","p":"h","src":"101年第36題","sec":"C1","stem":"進行不動產估價時，所謂獨立估價，係指：","opts":["土地上有建築物，但估價時將土地與建物併同估價","土地上無建築物，但估價時假設土地與建物併同估價","土地上有建築物，但估價時將土地視為素地加以估價","土地上無建築物，但估價時視為存有地上權加以估價"],"ok":[2],"ex":["土地上有建築物時，獨立估價是將土地「視為素地」估價（不考慮建物），而非「土地與建物併同估價」，本選項描述與獨立估價定義相反。","獨立估價的前提是「土地上有建築物」存在，本選項描述「土地上無建築物」之情境不符獨立估價之適用前提。","教材定義的獨立估價，是土地上有建築物，但估價時將土地視為素地估價、不考慮建物影響（技術規則§86但書「以素地估價為前提」即此情形），與本選項描述完全相符。","獨立估價是不考慮既有建物之影響，而非「視為存有地上權」這種額外假設權利存在之情境，本選項描述與獨立估價定義不符。"],"tr":"","core":["獨立估價是視為素地，非併同估價","前提是土地上有建築物","有建物但視為素地估價","不考慮建物，非假設存有地上權"],"hl":[["併同估價","將土地「視為素地」估價（不考慮建物）"],["土地上無建築物","獨立估價的前提是「土地上有建築物」存在"],[],["土地上無建築物","視為存有地上權","不考慮既有建物之影響"]]},{"id":"h:102-14","p":"h","src":"102年第14題","sec":"C1","stem":"成本法操作中，使用與勘估標的相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製建築所需之成本，係指下列何者？","opts":["重造成本","重建成本","重置成本","提撥成本"],"ok":[1],"ex":["「重造成本」並非技術規則明定之正式用語。","技術規則明定重建成本係使用與勘估標的相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製建築所需之成本，與題目敘述完全相符。","重置成本是以「現代建材標準」（而非相同或極類似建材）建築所需之成本，與題目所述「相同或極類似建材標準」之定義不符。","「提撥成本」並非技術規則明定之正式用語。"],"tr":"","core":["重造成本非規則正式用語","相同或極類似建材複製＝重建成本","重置成本用現代建材標準","提撥成本非規則正式用語"],"hl":[["重造成本"],[],["重置成本","以「現代建材標準」（而非相同或極類似建材）建築所需之成本"],["提撥成本"]]},{"id":"h:102-15","p":"h","src":"102年第15題","sec":"C1","stem":"不動產估價成本法總成本各項推估中，下列敘述何者錯誤？","opts":["規劃設計費按總成本之百分之二至百分之三推估","廣告費、銷售費按總成本之百分之四至百分之五推估","管理費按總成本之百分之三至百分之四推估","稅捐按總成本之百分之零點五至百分之一點二推估"],"ok":[0],"ex":["§57 規定規劃設計費依內政部建築師酬金標準表及工程造價表計算，或按實際營造施工費之2%至3%推估（推估基礎為營造施工費，而非總成本），本選項將推估基礎誤植為總成本，敘述錯誤，即本題正解。","§61 規定廣告費、銷售費按「總成本」乘以全聯會公告的費率計算；本選項以總成本為基礎，方向正確，所列百分比為教材／實務常用費率區間，本題視為正確敘述，不選。","§61 規定管理費按「總成本」乘以全聯會公告的費率計算；本選項以總成本為基礎，方向正確，所列百分比為教材／實務常用費率區間，本題視為正確敘述，不選。","§61 規定稅捐按「總成本」乘以全聯會公告的費率計算；本選項以總成本為基礎，方向正確，所列百分比為教材／實務常用費率區間，本題視為正確敘述，不選。"],"tr":"","core":["規劃設計費按營造施工費2～3%","廣告銷售費以總成本為基礎","管理費以總成本為基礎","稅捐以總成本為基礎"],"hl":[["總成本","按實際營造施工費之2%至3%推估"],[],[],[]]},{"id":"h:102-30","p":"h","src":"102年第30題","sec":"C1","stem":"依不動產估價技術規則規定，某建商蓋到一半的建案，其建物應如何估價？","opts":["依實際完成部分估價","以總銷售金額扣除土地管銷成本及利潤率，再扣除剩餘建築費用","以總銷售金額扣除土地管銷成本及利潤率，再扣除延遲損失及剩餘建築費用","無法估價"],"ok":[0],"ex":["技術規則第63條明定未完工建物應依實際完成部分估價，與題目敘述相符，這是處理興建中建案最直接的估價方式。","「以總銷售金額扣除土地管銷成本及利潤率，再扣除剩餘建築費用」此計算邏輯較接近土地開發分析法之公式架構，並非技術規則規定處理未完工建物估價之方式。","「扣除延遲損失」並非技術規則規定處理未完工建物估價時應計算之項目。","未完工建物雖未完工，但已投入部分仍具經濟價值，技術規則明定得依實際完成部分估價，並非無法估價。"],"tr":"","core":["未完工建物依實際完成部分估價","此近土地開發分析法，非未完工估價","扣除延遲損失非規定項目","已投入部分有價值，非無法估價"],"hl":[[],["扣除剩餘建築費用"],["扣除延遲損失"],["無法估價","技術規則明定得依實際完成部分估價"]]},{"id":"h:102-33","p":"h","src":"102年第33題","sec":"C1","stem":"成本法總成本中營造施工費之求取，估價實務上最常用的方法為何？","opts":["淨計法","單位工程法","工程造價比較法","單位面（體）積比較法"],"ok":[3],"ex":["淨計法須逐一計算各種材料與人工的數量，最精細但最費時，實務上很少採用，不選。","單位工程法須有細部工程項目數量，通常在有設計圖說時才能做，不如單位面積比較法簡便常用，不選。","工程造價比較法須逐項比較工程概算項目，比單位面積比較法繁複，實務上較少採用，不選。","考選部標準答案為 D：單位面（體）積比較法（§56Ⅱ，以比較標的單位面積或體積營造費單價為基礎調整後乘以面積或體積）。"],"tr":"","core":["淨計法最精細但費時，實務少用","單位工程法須有細部數量，較不簡便","工程造價比較法較繁複，少採用","實務最常用單位面（體）積比較法"],"hl":[["淨計法","最精細但最費時，實務上很少採用"],["單位工程法","通常在有設計圖說時才能做"],["工程造價比較法","實務上較少採用"],[]]},{"id":"h:102-40","p":"h","src":"102年第40題","sec":"C1","stem":"依中華民國不動產估價師公會全國聯合會第四號公報規定，目前住宅用鋼筋混凝土造房屋之經濟耐用年限為多少年？","opts":["35年","40年","50年","60年"],"ok":[2],"ex":["35年並非全聯會公報所定鋼筋混凝土造住宅用房屋之經濟耐用年限。","40年並非全聯會公報所定鋼筋混凝土造住宅用房屋之經濟耐用年限。","依不動產估價師公會全國聯合會第四號公報規定，住宅用鋼筋混凝土造房屋之經濟耐用年限為50年，與題目敘述相符。","60年並非全聯會公報所定鋼筋混凝土造住宅用房屋之經濟耐用年限（60年通常用於更耐久之構造類型）。"],"tr":"","core":["35年非RC住宅經濟耐用年限","40年非RC住宅經濟耐用年限","RC住宅經濟耐用年限為50年","60年非RC住宅經濟耐用年限"],"hl":[["35年"],["40年"],[],["60年"]]},{"id":"h:103-3","p":"h","src":"103年第3題","sec":"C1","stem":"建物估價，以何種方法估價為原則？","opts":["收益法","成本法","比較法","殘餘法"],"ok":[1],"ex":["收益法以淨收益折現或資本化估算價格，並非建物估價之原則方法（收益法較適用於收益性不動產，而非單純建物本身之估價原則）。","技術規則明定建物估價以成本法為原則（因建物可明確計算重建/重置成本並扣除折舊），與題目敘述相符。","比較法是估價的三大方法之一，但並非技術規則明定建物估價之原則方法。","殘餘法（教材）是收益法的應用技巧（從總收益扣除已知成分的收益），不是獨立的估價方法；建物估價依§108以成本法為原則，不選。"],"tr":"","core":["收益法非建物估價原則方法","建物估價以成本法為原則","比較法非建物估價原則方法","殘餘法是收益法技巧，非原則方法"],"hl":[["收益法","收益法較適用於收益性不動產"],[],["比較法"],["殘餘法","建物估價依§108以成本法為原則"]]},{"id":"h:103-17","p":"h","src":"103年第17題","sec":"C1","stem":"依不動產估價技術規則規定，下列有關總成本中廣告費之敘述，何者正確？","opts":["計算營造或施工費應考量廣告費","廣告費按營造或施工費乘以相關費率計算","廣告費之相關費率應由不動產估價師公會全國聯合會定期公告之","廣告費視勘估標的之性質，於成本估價時應予計入"],"ok":[2],"ex":["計算營造或施工費並不需考量廣告費，廣告費屬於總成本中獨立的間接成本項目，與營造施工費（直接成本）計算無關。","廣告費是按「總成本」（而非營造或施工費）乘以相關費率計算，本選項計算基礎誤植。","技術規則明定廣告費、銷售費等相關費率，應由不動產估價師公會全國聯合會定期公告之，與題目敘述相符。","廣告費「視勘估標的之性質」於成本估價時得不予計入（並非應予計入），本選項與規則規定相反。"],"tr":"","core":["廣告費是間接成本，與營造費無關","廣告費按總成本乘費率，非營造費","廣告費等費率由全聯會定期公告","視性質得不予計入，非應予計入"],"hl":[["應考量廣告費","計算營造或施工費並不需考量廣告費"],["按營造或施工費乘以","廣告費是按「總成本」"],[],["於成本估價時應予計入","於成本估價時得不予計入"]]},{"id":"h:103-33","p":"h","src":"103年第33題","sec":"C1","stem":"依不動產估價技術規則規定，下列有關總成本中規劃設計費之敘述，何者正確？","opts":["規劃設計費按縣（市）政府發布之建築師酬金標準表計算之","規劃設計費按實際營造施工費之百分之二至百分之三推估之","規劃設計費按縣（市）政府發布之建造執照工程造價表計算之","規劃設計費率由不動產估價師公會全國聯合會定期公告之"],"ok":[1],"ex":["§57 的建築師酬金標準表是「內政部所定」，不是縣（市）政府發布，而且須與建造執照工程造價表「及」併用計算；本選項發布機關寫錯，敘述錯誤。","§57 明定規劃設計費得按「實際營造施工費」之2%至3%推估，本選項正確（官方答案）。","§57 規定須按「內政部所定建築師酬金標準表『及』直轄市或縣（市）政府發布之建造執照工程造價表」計算，本選項只用工程造價表單獨計算，少了建築師酬金標準表，敘述不完整，錯誤。","§57 並未規定規劃設計費率由全聯會公告（§61 由全聯會公告費率者為廣告費、銷售費、管理費及稅捐）；故本選項不選。"],"tr":"","core":["酬金標準表是內政部所定","得按實際營造施工費2～3%推估","須酬金標準表及工程造價表併用","規劃設計費率非由全聯會公告"],"hl":[["縣（市）政府","內政部所定"],[],["建造執照工程造價表","內政部所定建築師酬金標準表"],["公會全國聯合會定期公告","由全聯會公告費率者為廣告費、銷售費、管理費及稅捐"]]},{"id":"h:103-35","p":"h","src":"103年第35題","sec":"C1","stem":"請問「附有建物之宗地估價，應考慮該建物對該宗地價格造成之影響。但以素地估價為前提並於估價報告書敘明者，不在此限。」中，但書之規定屬於何種類型之估價？","opts":["獨立估價","部分估價","正常估價","限定估價"],"ok":[0],"ex":["題述是技術規則§86：但書「以素地估價為前提」不考慮建物影響，教材稱為「獨立估價」（本文考慮建物影響，教材稱為「部分估價」），故選之。","部分估價正是該條文「本文」所規定之內容（考慮建物對宗地價格之影響），而非「但書」規定，題目問的是但書類型，非本文。","「正常估價」並非技術規則明定之正式估價類型名稱。","「限定估價」並非技術規則明定之正式估價類型名稱（限定價格是價格種類，非估價方法類型）。"],"tr":"","core":["但書以素地為前提＝獨立估價","部分估價是本文，非但書","正常估價非正式估價類型","限定估價非正式估價類型"],"hl":[[],["部分估價","部分估價正是該條文「本文」所規定之內容"],["正常估價"],["限定估價"]]},{"id":"h:104-2","p":"h","src":"104年第2題","sec":"C1","stem":"下列何者最適合說明建築物預期的耐用年數期滿時，欲廢棄之資產價值？","opts":["回收價值（salvage value）","清算價值（liquidation value）","剩餘價值（residual value）","殘餘價值（scrap value）"],"ok":[3],"ex":["回收價值（salvage value）通常指資產報廢時可回收再利用部分之價值，與題目所述「廢棄」資產之概念較不直接對應。","清算價值（liquidation value）通常指企業清算情境下急速處分資產之價值，與單純建物耐用年數期滿後之廢棄資產價值概念不同。","剩餘價值（residual value）通常用於描述扣除已知成分後的剩餘部分（如殘餘法概念），與「耐用年數期滿欲廢棄之資產價值」此一特定情境用語不完全對應。","殘餘價值（scrap value）正是技術規則所稱「殘餘價格」之英文對應概念，指建物耐用年數終止後欲廢棄時所餘存之價值，與題目敘述最為相符。"],"tr":"","core":["回收價值指可回收再利用部分","清算價值指清算時急速處分","剩餘價值指扣除後剩餘部分","耐用年數期滿廢棄價值＝殘餘價值"],"hl":[["回收價值","通常指資產報廢時可回收再利用部分之價值"],["清算價值","企業清算情境下急速處分資產之價值"],["剩餘價值","用於描述扣除已知成分後的剩餘部分"],[]]},{"id":"h:104-18","p":"h","src":"104年第18題","sec":"C1","stem":"建物估價以求取重建成本為原則，但建物使用之材料目前已無生產或施工方法已改變者，得採取下列何種成本替代之？","opts":["毛胚成本","比較成本","重置成本","總體成本"],"ok":[2],"ex":["「毛胚成本」並非技術規則明定之正式用語。","「比較成本」並非技術規則明定之正式用語。","技術規則明定建物估價以求取重建成本為原則，但建物使用之材料目前已無生產或施工方法已改變者，得採重置成本替代之，與題目敘述完全相符。","「總體成本」並非技術規則明定之正式用語。"],"tr":"","core":["毛胚成本非規則正式用語","比較成本非規則正式用語","材料無生產或工法改變得採重置成本","總體成本非規則正式用語"],"hl":[["毛胚成本"],["比較成本"],[],["總體成本"]]},{"id":"h:104-19","p":"h","src":"104年第19題","sec":"C1","stem":"營造或施工費，得就同一供需圈內近鄰地區或類似地區中選擇與勘估標的類似之比較標的或標準建物，經比較與勘估標的營造或施工費之條件差異並作價格調整以求取之，下列何者不是其子方法？","opts":["單位工程法","工程造價比較法","單位面積比較法","單位體積比較法"],"ok":[0],"ex":["技術規則明定間接法之子方法為工程造價比較法及單位面積（或體積）比較法，「單位工程法」屬於直接法而非間接法之子方法，即本題正解（本題問「不是」間接法子方法者）。","工程造價比較法是技術規則明定間接法之子方法之一。","單位面積比較法是技術規則明定間接法之子方法之一。","單位體積比較法屬§56「單位面積（或體積）比較法」之範圍，是間接法之子方法之一。"],"tr":"","core":["單位工程法屬直接法，非間接法","工程造價比較法是間接法子方法","單位面積比較法是間接法子方法","單位體積比較法是間接法子方法"],"hl":[["單位工程法","屬於直接法而非間接法之子方法"],[],[],[]]},{"id":"h:105-16","p":"h","src":"105年第16題","sec":"C1","stem":"在成本法中，使用與勘估標的相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製建築所需之成本，稱為下列何者？","opts":["新建成本","建造成本","重置成本","重建成本"],"ok":[3],"ex":["「新建成本」並非技術規則明定之正式用語。","「建造成本」並非技術規則明定之正式用語。","重置成本是以「現代建材標準」（而非相同或極類似建材）建築所需之成本，與題目所述「相同或極類似建材標準」之定義不符。","技術規則明定重建成本係使用與勘估標的相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製建築所需之成本，與題目敘述完全相符。"],"tr":"","core":["新建成本非規則正式用語","建造成本非規則正式用語","重置成本用現代建材標準","相同或極類似建材複製＝重建成本"],"hl":[["新建成本"],["建造成本"],["重置成本","以「現代建材標準」（而非相同或極類似建材）建築所需之成本"],[]]},{"id":"h:105-23","p":"h","src":"105年第23題","sec":"C1","stem":"有關房地估價之敘述，下列何者錯誤？","opts":["實際建築使用之容積率超過法定容積率之房地估價，應以實際建築使用之現況估價，並敘明法定容積對估值之影響","附有違章建築之房地估價，其違建部分不予以評估","未達最有效使用狀態之房地估價，應先求取其最有效使用狀態之正常價格，再視其低度使用情況進行調整","建物已不具備使用價值，得將其基地視為素地估價。但應考量建物拆除成本予以調整之"],"ok":[0],"ex":["技術規則明定實際建築使用之容積率超過法定容積率之房地估價，應以實際建築使用之「合法部分」現況估價，並敘明法定容積對估值之影響，本選項未提及「合法部分」之限定，與規則完整規定有所出入，此為錯誤敘述，即本題正解。","附有違章建築之房地估價，違建部分不予以評估，此為正確敘述，符合技術規則規定。","未達最有效使用狀態之房地估價，應先求取最有效使用狀態之正常價格，再視低度使用情況進行調整，此為正確敘述。","建物已不具備使用價值，得將其基地視為素地估價，但應考量建物拆除成本予以調整之，此為正確敘述。"],"tr":"","core":["應以合法部分現況估價，漏了限定","違建部分不予評估","先求最有效使用正常價格再調整","視為素地估價並考量拆除成本"],"hl":[["現況估價","實際建築使用之「合法部分」現況估價"],[],[],[]]},{"id":"h:105-31","p":"h","src":"105年第31題","sec":"C1","stem":"依不動產估價技術規則之規定，下列何者非屬不動產估價師公會全國聯合會公告之項目？","opts":["建物工程進度營造費用比例表","開發或建築利潤率","建造執照工程造價表","營造或施工費標準表"],"ok":[2],"ex":["建物工程進度營造費用比例表是技術規則明定由全聯會公告之項目，非本題答案（本題問「非屬」全聯會公告項目）。","開發或建築利潤率是技術規則明定由全聯會公告之項目。","依§57，建造執照工程造價表是「直轄市或縣（市）政府發布」，不是全聯會公告，即本題正解。","營造或施工費標準表是技術規則明定由全聯會公告之項目。"],"tr":"","core":["工程進度營造費用比例表由全聯會公告","開發或建築利潤率由全聯會公告","工程造價表由直轄市縣市政府發布","營造或施工費標準表由全聯會公告"],"hl":[[],[],["建造執照工程造價表","直轄市或縣（市）政府發布"],[]]},{"id":"h:105-32","p":"h","src":"105年第32題","sec":"C1","stem":"不動產估價技術規則有關廣告費、銷售費、管理費、稅捐及開發或建築利潤之規定，下列述敘何者正確？","opts":["廣告費、銷售費等，於成本估價時必須計入","開發或建築利潤，可視勘估標的之性質，於成本估價時得不予計入","稅捐於成本估價時必須計入","管理費於成本估價時一律計入"],"ok":[1],"ex":["廣告費、銷售費「視勘估標的之性質」於成本估價時得不予計入（並非必須計入），本選項與規則規定相反。","技術規則明定開發或建築利潤，可視勘估標的之性質，於成本估價時得不予計入，與題目敘述相符。","稅捐同樣是「視勘估標的之性質」決定是否計入，並非必須計入，本選項過於絕對。","管理費同樣非一律計入，應視勘估標的之性質而定，本選項過於絕對。"],"tr":"","core":["視性質得不計入，非必須計入","開發利潤視性質得不予計入","稅捐視性質決定，非必須計入","管理費視性質而定，非一律計入"],"hl":[["必須計入","於成本估價時得不予計入"],[],["必須計入","決定是否計入"],["一律計入","應視勘估標的之性質而定"]]},{"id":"h:106-14","p":"h","src":"106年第14題","sec":"C1","stem":"勘估標的之營造或施工費之求取方法中，「以建築細部工程之各項目單價乘以該工程施工數量，並合計之」之方法，係指何方法？","opts":["淨計法","單位工程法","工程造價比較法","單位面積（或體積）比較法"],"ok":[1],"ex":["淨計法是逐一材料人工數量乘以單價工資，與題目所述「建築細部工程各項目單價乘以施工數量」之計算單位不同。","技術規則明定單位工程法係以建築細部工程之各項目單價乘以該工程施工數量，並合計之，與題目敘述完全相符。","工程造價比較法是按工程概算項目逐項比較調整之間接法，與題目所述直接計算施工數量乘單價之方式不同。","單位面積（或體積）比較法是以單位面積營造費為基礎調整，與題目所述細部工程項目逐項計算之方式不同。"],"tr":"","core":["淨計法以材料人工為計算單位","細部工程單價×施工數量＝單位工程法","工程造價比較法是間接法","單位面積比較法以單位面積營造費調整"],"hl":[["淨計法","逐一材料人工數量乘以單價工資"],[],["工程造價比較法","按工程概算項目逐項比較調整之間接法"],["單位面積（或體積）比較法","以單位面積營造費為基礎調整"]]},{"id":"h:106-30","p":"h","src":"106年第30題","sec":"C1","stem":"附有建物之宗地，考慮建物對宗地價格影響下所為之土地估價，稱之為：","opts":["分割估價","合併估價","部分估價","獨立估價"],"ok":[2],"ex":["技術規則§83、§84是「以合併或分割為前提之宗地估價」（考慮合併或分割前後的價格變動），與題述「考慮建物對宗地價格影響」無關，不選。","技術規則§83、§84是「以合併或分割為前提之宗地估價」（考慮合併或分割前後的價格變動），與題述「考慮建物對宗地價格影響」無關，不選。","教材所稱「部分估價」，是附有建物之宗地在考慮建物對宗地價格影響下所做的土地估價，對應技術規則§86本文「附有建物之宗地估價，應考慮該建物對該宗地價格造成之影響」，與題目敘述相符。","獨立估價是不考慮建物影響、將土地視為素地估價，與題目所述「考慮建物影響」之定義相反。"],"tr":"","core":["分割估價看分割前後價變，與建物無關","合併估價看合併前後價變，與建物無關","考慮建物對宗地影響＝部分估價","獨立估價不考慮建物，定義相反"],"hl":[["分割估價","以合併或分割為前提之宗地估價"],["合併估價","以合併或分割為前提之宗地估價"],[],["獨立估價","不考慮建物影響、將土地視為素地估價"]]},{"id":"h:106-38","p":"h","src":"106年第38題","sec":"C1","stem":"成本法中，指與勘估標的相同效用之建物，以現代建材標準、設計及配置，於價格日期建築所需之成本，是指何種成本？","opts":["重置成本","重建成本","重蓋成本","替換成本"],"ok":[0],"ex":["技術規則明定重置成本係指與勘估標的相同效用之建物，以現代建材標準、設計及配置，於價格日期建築所需之成本，與題目敘述完全相符。","重建成本是使用「相同或極類似」建材標準（而非現代建材標準）複製之成本，與題目所述「現代建材標準」之定義不符。","「重蓋成本」並非技術規則明定之正式用語。","「替換成本」並非技術規則明定之正式用語。"],"tr":"","core":["相同效用、現代建材＝重置成本","重建成本用相同或極類似建材","重蓋成本非規則正式用語","替換成本非規則正式用語"],"hl":[[],["重建成本","使用「相同或極類似」建材標準"],["重蓋成本"],["替換成本"]]},{"id":"h:106-40","p":"h","src":"106年第40題","sec":"C1","stem":"依不動產估價技術規則第55條第1款之規定，就勘估標的所需要各種建築材料及人工之數量，逐一乘以價格日期當時該建築之單價及人工工資，並加計管理費、稅捐、資本利息及利潤之估價方法稱為：","opts":["淨計法","單位法","工程造價比較法","單位面積比較法"],"ok":[0],"ex":["技術規則第55條第1款明定淨計法係就勘估標的所需要各種建築材料及人工之數量，逐一乘以價格日期當時該建築之單價及人工工資，並加計管理費、稅捐、資本利息及利潤之方法，與題目敘述完全相符。","「單位法」並非技術規則明定之正式方法名稱（正確名稱應為單位工程法）。","工程造價比較法是按工程概算項目逐項比較調整之間接法，與題目所述直接逐一計算材料人工數量之方式不同。","單位面積比較法是以單位面積營造費為基礎調整，與題目所述逐一計算材料人工之方式不同。"],"tr":"","core":["材料人工數量×單價工資加計＝淨計法","單位法非正式名稱，應為單位工程法","工程造價比較法是間接法","單位面積比較法以單位面積營造費調整"],"hl":[[],["單位法","正確名稱應為單位工程法"],["工程造價比較法","按工程概算項目逐項比較調整之間接法"],["單位面積比較法","以單位面積營造費為基礎調整"]]},{"id":"h:107-9","p":"h","src":"107年第9題","sec":"C1","stem":"在使用成本法估價時，建物估價以求取(甲)為原則。但建物使用之材料目前已無生產或施工方法已改變者，得採(乙)替代之。請問甲、乙分別為何種成本？","opts":["甲為重建成本、乙為重置成本","甲為重置成本、乙為重建成本","甲為直接成本、乙為間接成本","甲為間接成本、乙為直接成本"],"ok":[0],"ex":["技術規則明定建物估價以求取重建成本為原則（甲），但建物使用之材料已無生產或施工方法已改變者，得採重置成本替代之（乙），與題目敘述（甲為原則、乙為替代）完全相符。","本選項將甲乙順序對調（甲為重置成本、乙為重建成本），與規則規定「重建成本為原則」之順序相反，敘述錯誤。","「直接成本、間接成本」是成本構成之分類（營造施工費vs規劃設計費等），與本題甲乙所問「建物估價基準成本」之原則與替代關係無關。","同C選項，直接成本與間接成本分類與本題所問成本替代關係無關。"],"tr":"","core":["重建成本為原則，重置成本替代","甲乙對調，重建成本才是原則","直接間接成本是構成分類，無關","直接間接成本分類，與替代無關"],"hl":[[],["甲為重置成本、乙為重建成本","重建成本為原則"],["甲為直接成本、乙為間接成本"],["甲為間接成本、乙為直接成本"]]},{"id":"h:107-15","p":"h","src":"107年第15題","sec":"C1","stem":"不動產估價有所謂的獨立估價，請問獨立估價是指：","opts":["土地上原有地上建物，但於估價之價格日期時已頽壞傾倒，估價時仍視為有地上建物，併同土地一併估價","土地上無地上建物，純素地估價","土地上有地上建物，估價時將土地與地上建物併同估價","土地上有地上建物或他項權利存在，但估價時將土地視為素地予以估價，不考慮地上建物或他項權利對該土地的影響"],"ok":[3],"ex":["地上建物已頹壞傾倒、不具使用價值時，依§106「得將其基地視為素地估價，但應考量建物拆除成本予以調整之」，不是「仍視為有地上建物併同估價」，本選項不符獨立估價的概念。","獨立估價的適用前提是「土地上有建築物」存在，本選項描述「純素地估價」（即土地上原本就無建物）不符獨立估價之定義情境（純素地本身就無須做「視為素地」之假設處理）。","獨立估價是「將土地視為素地」估價，而非「土地與建物併同估價」，本選項描述與獨立估價定義相反。","依教材定義，獨立估價是土地上有地上建物或他項權利存在，但估價時將土地視為素地、不考慮其影響（技術規則§86但書「以素地估價為前提」屬此情形），與本選項描述相符。"],"tr":"","core":["頹壞建物得視為素地，非併同估價","前提是土地上有建物，非純素地","獨立估價視為素地，非併同估價","有建物或他項權利仍視為素地估價"],"hl":[["仍視為有地上建物","得將其基地視為素地估價，但應考量建物拆除成本予以調整之"],["土地上無地上建物","獨立估價的適用前提是「土地上有建築物」存在"],["併同估價","獨立估價是「將土地視為素地」估價"],[]]},{"id":"h:108-10","p":"h","src":"108年第10題","sec":"C1","stem":"使用與勘估標的相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製建築所需之成本，稱為：","opts":["重建成本","重置成本","直接成本","間接成本"],"ok":[0],"ex":["技術規則明定重建成本係使用與勘估標的相同或極類似之建材標準、設計、配置及施工品質，於價格日期重新複製建築所需之成本，與題目敘述完全相符。","重置成本是以「現代建材標準」（而非相同或極類似建材）建築所需之成本，與題目所述「相同或極類似建材標準」之定義不符。","直接成本是指營造或施工費，與題目所述「重新複製建築所需成本」之完整定義層次不同（直接成本是構成重建成本的其中一部分）。","間接成本是指規劃設計費、廣告銷售費等，與題目所述「重新複製建築」之核心成本定義不同。"],"tr":"","core":["相同或極類似建材複製＝重建成本","重置成本用現代建材標準","直接成本僅指營造或施工費","間接成本指規劃設計廣告銷售等"],"hl":[[],["重置成本","以「現代建材標準」（而非相同或極類似建材）建築所需之成本"],["直接成本","直接成本是指營造或施工費"],["間接成本","間接成本是指規劃設計費、廣告銷售費等"]]},{"id":"h:108-13","p":"h","src":"108年第13題","sec":"C1","stem":"就勘估標的之構成部分或全體，調查其使用材料之種別、品級、數量及所需勞力種別、時間等，並以勘估標的所在地區於價格日期之各種單價為基礎，計算其營造或施工費的方法為：","opts":["直接法","間接法","工程造價比較法","單位面積比較法"],"ok":[0],"ex":["技術規則明定直接法係就勘估標的之構成部分或全體，調查其使用材料之種別、品級、數量及所需勞力種別、時間等，並以勘估標的所在地區於價格日期之各種單價為基礎，計算其營造或施工費，與題目敘述完全相符。","間接法是選擇比較標的或標準建物進行比較調整，與題目所述「就勘估標的本身逐一調查材料人工」之直接計算方式不同。","工程造價比較法屬間接法之子方法，與題目所述直接調查計算之方式不同。","單位面積比較法屬間接法之子方法，與題目所述直接調查計算之方式不同。"],"tr":"","core":["就標的調查材料勞力計算＝直接法","間接法是選比較標的比較調整","工程造價比較法屬間接法","單位面積比較法屬間接法"],"hl":[[],["間接法","選擇比較標的或標準建物進行比較調整"],["工程造價比較法","屬間接法之子方法"],["單位面積比較法","屬間接法之子方法"]]},{"id":"h:108-16","p":"h","src":"108年第16題","sec":"C1","stem":"不動產估價技術規則第99條之計算公式，勘估標的之基地價格＝勘估標的之房地價格－勘估標的之建物成本價格。請問此為何種學說之主張？","opts":["土地貢獻說","建物貢獻說","聯合貢獻說","合併貢獻說"],"ok":[0],"ex":["技術規則第99條明定基地價格＝房地價格－建物成本價格之公式，正是土地貢獻說的核心主張（房地結合之超額利潤歸屬於土地，扣除建物成本後之剩餘部分視為土地之貢獻價值），與題目敘述相符。","建物貢獻說主張超額利潤應歸屬於建物，與本公式「扣除建物成本求基地價格」（即超額利潤歸於土地）之邏輯相反。","聯合貢獻說主張房地結合之超額利潤是土地與建物共同聯合貢獻所致，與本公式單純將剩餘部分全歸於土地（基地價格）之邏輯不同。","「合併貢獻說」並非技術規則或估價理論明定之正式學說名稱。"],"tr":"","core":["房地價格－建物成本＝土地貢獻說","建物貢獻說將超額利潤歸建物","聯合貢獻說歸土地建物共同貢獻","合併貢獻說非正式學說名稱"],"hl":[[],["建物貢獻說","主張超額利潤應歸屬於建物"],["聯合貢獻說","房地結合之超額利潤是土地與建物共同聯合貢獻所致"],["合併貢獻說","並非技術規則或估價理論明定之正式學說名稱"]]},{"id":"h:109-17","p":"h","src":"109年第17題","sec":"C1","stem":"依據不動產估價技術規則，有關成本法資本利息的敘述，下列敘述何者錯誤？","opts":["資金中自有資金之計息利率應不高於1年期定存利率","資金中自有資金之計息利率應不低於活存利率","借款則以銀行短期放款利率計息","預售收入之資金以定存利率計息"],"ok":[3],"ex":["自有資金之計息利率應不高於1年期定存利率，此為正確敘述，非本題答案（本題問「何者錯誤」）。","自有資金之計息利率應不低於活存利率，此為正確敘述。","借款則以銀行短期放款利率計息，此為正確敘述。","§59 規定預售收入之資金不計息，並非以定存利率計息，本選項敘述錯誤，即本題正解。"],"tr":"","core":["自有資金利率不高於一年期定存","自有資金利率不低於活存利率","借款以銀行短期放款利率計息","預售收入之資金不計息"],"hl":[[],[],[],["以定存利率計息","預售收入之資金不計息"]]},{"id":"h:109-18","p":"h","src":"109年第18題","sec":"C1","stem":"成本法營造施工費求取方式，有分為直接法及間接法兩大類，其中以建築細部工程之各項目單價乘以該工程施工數量合計之方法係指下列何者？","opts":["淨計法","單位工程法","工程造價比較法","單位面積（或體積）比較法"],"ok":[1],"ex":["淨計法是逐一材料人工數量乘以單價工資，與題目所述「建築細部工程各項目單價乘以施工數量」之計算單位不同。","技術規則明定單位工程法係以建築細部工程之各項目單價乘以該工程施工數量合計之，與題目敘述完全相符。","工程造價比較法屬間接法，與題目所述直接逐項計算施工數量乘單價之方式不同。","單位面積（或體積）比較法屬間接法，與題目所述細部工程項目逐項計算之方式不同。"],"tr":"","core":["淨計法是材料人工逐一計價，非細部工程","單位工程法＝細部工程單價×施工數量","工程造價比較法屬間接法，非逐項計算","單位面積比較法屬間接法，非逐項計算"],"hl":[["淨計法","逐一材料人工數量乘以單價工資"],[],["工程造價比較法","屬間接法"],["單位面積（或體積）比較法","屬間接法"]]},{"id":"h:109-21","p":"h","src":"109年第21題","sec":"C1","stem":"估價人員就某建物使用與勘估標的相同之建材標準、設計、配置及施工品質，於價格日期重新複製建築所需之成本，是指下列何者？","opts":["重置成本","重製成本","重建成本","複舊成本"],"ok":[2],"ex":["重置成本是以「現代建材標準」（而非相同建材標準）建築所需之成本，與題目所述「相同之建材標準」之定義不符。","「重製成本」並非技術規則明定之正式用語。","技術規則明定重建成本係使用與勘估標的相同之建材標準、設計、配置及施工品質，於價格日期重新複製建築所需之成本，與題目敘述完全相符。","「複舊成本」並非技術規則明定之正式用語。"],"tr":"","core":["重置成本用現代建材，非相同建材","重製成本非技術規則正式用語","重建成本＝相同建材設計重新複製","複舊成本非技術規則正式用語"],"hl":[["重置成本","以「現代建材標準」（而非相同建材標準）建築所需之成本"],["重製成本"],[],["複舊成本"]]},{"id":"h:109-23","p":"h","src":"109年第23題","sec":"C1","stem":"依據不動產估價技術規則，有關成本法建築工期係指自申請建造執照開始至那個時間點為止無間斷所需之時間？","opts":["變更建照執照","擬定權利變換計畫","銷售完竣","建築完成達到可交屋使用"],"ok":[3],"ex":["「變更建照執照」並非建築工期計算之終止時間點，這是建照變更程序而非完工概念。","「擬定權利變換計畫」是都市更新程序之專有概念，與一般建築工期之終止時間點無關。","「銷售完竣」是預售屋銷售完成之時間點，並非建築完成之時間點，建築工期關注的是「建造」過程而非銷售過程。","技術規則明定建築工期係指自申請建造執照開始至建築完成達到可交屋使用為止無間斷所需之時間，與題目敘述完全相符。"],"tr":"","core":["變更建照屬變更程序，非工期終點","權利變換計畫屬都更程序，與工期無關","銷售完竣是銷售時點，非建築完成","工期算至建築完成達可交屋使用"],"hl":[["變更建照執照","建照變更程序而非完工概念"],["擬定權利變換計畫","都市更新程序之專有概念"],["銷售完竣","建築工期關注的是「建造」過程而非銷售過程"],[]]},{"id":"h:110-8","p":"h","src":"110年第8題","sec":"C1","stem":"勘估標的之營造或施工費，依不動產估價技術規則之規定，不包含下列那一項目？","opts":["間接材料費","稅捐","資本利息","廣告費"],"ok":[3],"ex":["間接材料費是技術規則明定營造施工費應包括之成本項目之一，非本題答案（本題問「不包含」之項目）。","稅捐是技術規則明定營造施工費應包括之成本項目之一。","資本利息是技術規則明定營造施工費應包括之成本項目之一。","廣告費屬於總成本中「間接成本」之廣告銷售費項目，並非「營造或施工費」本身應包括之項目，即本題正解。"],"tr":"","core":["間接材料費屬營造施工費應含項目","稅捐屬營造施工費應含項目","資本利息屬營造施工費應含項目","廣告費屬間接成本，不在營造施工費"],"hl":[[],[],[],["廣告費","廣告費屬於總成本中「間接成本」之廣告銷售費項目"]]},{"id":"h:110-9","p":"h","src":"110年第9題","sec":"C1","stem":"就同一供需圈內近鄰地區或類似地區中，選擇與勘估標的類似之比較標的或標準建物，經比較與勘估標的營造或施工費之條件差異並作價格調整，以求取勘估標的營造或施工費的方法為何？","opts":["直接法","間接法","淨計法","單位工程法"],"ok":[1],"ex":["直接法是就勘估標的本身逐一調查材料人工計算（淨計法、單位工程法），與題目所述「選擇比較標的或標準建物進行比較調整」之間接計算方式不同。","技術規則明定間接法係就同一供需圈內近鄰地區或類似地區中，選擇與勘估標的類似之比較標的或標準建物，經比較與勘估標的營造或施工費之條件差異並作價格調整，以求取勘估標的營造或施工費，與題目敘述完全相符。","淨計法屬直接法之子方法，與題目所述間接比較調整之方式不同。","單位工程法屬直接法之子方法，與題目所述間接比較調整之方式不同。"],"tr":"","core":["直接法是就標的本身逐一計算，非比較","間接法＝選比較標的或標準建物調整","淨計法屬直接法，非比較調整","單位工程法屬直接法，非比較調整"],"hl":[["直接法","就勘估標的本身逐一調查材料人工計算"],[],["淨計法","屬直接法之子方法"],["單位工程法","屬直接法之子方法"]]},{"id":"h:111-7","p":"h","src":"111年第7題","sec":"C1","stem":"不動產估價成本法對勘估標的之營造或施工費，其中「指以類似勘估標的之比較標的或標準建物之單位面積（或體積）營造或施工費單價為基礎，經比較並調整價格後，乘以勘估標的之面積（或體積）總數，以求取勘估標的營造或施工費。」方法，係指何方法？","opts":["單位工程法","淨計法","單位面積（或體積）比較法","工程造價比較法"],"ok":[2],"ex":["單位工程法是以建築細部工程各項目單價乘以施工數量，屬直接法，與題目所述「以比較標的單位面積營造費為基礎調整」之間接法定義不同。","淨計法是逐一材料人工數量乘以單價工資，屬直接法，與題目所述間接比較調整方式不同。","技術規則明定單位面積（或體積）比較法係以類似勘估標的之比較標的或標準建物之單位面積（或體積）營造或施工費單價為基礎，經比較並調整價格後，乘以勘估標的之面積（或體積）總數，以求取勘估標的營造或施工費，與題目敘述完全相符。","工程造價比較法是按工程概算項目逐項比較調整，與題目所述「以單位面積（或體積）營造費單價為基礎」之整體單價調整方式不同。"],"tr":"","core":["單位工程法屬直接法，非單價比較","淨計法屬直接法，非比較調整","比較標的單位面積單價調整後×面積","工程造價比較法按概算項目逐項比較"],"hl":[["單位工程法","以建築細部工程各項目單價乘以施工數量，屬直接法"],["淨計法","逐一材料人工數量乘以單價工資，屬直接法"],[],["工程造價比較法","按工程概算項目逐項比較調整"]]},{"id":"h:112-11","p":"h","src":"112年第11題","sec":"C1","stem":"目前銀行之一年期定存利率為1.57%，活存利率為0.58%，短期放款利率為7.11%，下列之敘述何者正確？","opts":["資金中自有資金之計息利率為7.11%","資金中預售收入之計息利率為0.58%","資金中自有資金之計息利率為1.52%","資金中借款之計息利率為1.57%"],"ok":[2],"ex":["自有資金之計息利率應不高於1年期定存利率1.57%，7.11%（短期放款利率）已超過此上限，不符規定。","§59 規定預售收入之資金不計息，並非以活存利率0.58%計息，本選項敘述錯誤。","技術規則規定自有資金之計息利率應介於活存利率（0.58%）與1年期定存利率（1.57%）之間，1.52%恰好落在此區間內，符合規定，與本選項相符。","技術規則規定借款應以「短期放款利率」（7.11%）計息，而非1年期定存利率1.57%，本選項計息基礎誤植。"],"tr":"","core":["自有資金利率不高於定存1.57%","預售收入資金不計息，非按活存計","1.52%介於活存與定存利率之間","借款以短期放款利率7.11%計息"],"hl":[["7.11%","不高於1年期定存利率1.57%"],["0.58%","預售收入之資金不計息"],[],["1.57%","借款應以「短期放款利率」（7.11%）計息"]]},{"id":"h:112-12","p":"h","src":"112年第12題","sec":"C1","stem":"就勘估標的所需要各種建築材料及人工之數量，逐一乘以價格日期當時該建築材料之單價及人工工資，並加計管理費、稅捐、資本利息及利潤，以求取勘估標的營造施工費之方法為何？","opts":["間接法","淨計法","工程造價比較法","單位面積比較法"],"ok":[1],"ex":["間接法是選擇比較標的或標準建物進行比較調整，與題目所述「逐一計算材料人工數量並加計管理費等」之直接計算方式不同。","技術規則明定淨計法係就勘估標的所需要各種建築材料及人工之數量，逐一乘以價格日期當時該建築材料之單價及人工工資，並加計管理費、稅捐、資本利息及利潤，以求取勘估標的營造施工費，與題目敘述完全相符。","工程造價比較法屬間接法，與題目所述逐一計算材料人工之直接方式不同。","單位面積比較法屬間接法，與題目所述逐一計算材料人工之直接方式不同。"],"tr":"","core":["間接法是比較調整，非逐一計算","淨計法＝材料人工逐一計價加計管理費等","工程造價比較法屬間接法，非逐一計算","單位面積比較法屬間接法，非逐一計算"],"hl":[["間接法","選擇比較標的或標準建物進行比較調整"],[],["工程造價比較法","屬間接法"],["單位面積比較法","屬間接法"]]},{"id":"h:112-21","p":"h","src":"112年第21題","sec":"C1","stem":"有關房地成本價格之計算公式，下列何者正確？","opts":["房地成本價格＝土地總成本＋建物成本價格","房地成本價格＝土地總成本＋建物總成本","房地成本價格＝土地價格＋建物成本價格－建物累積折舊額","房地成本價格＝土地價格＋建物成本價格＋建物累積折舊額"],"ok":[0],"ex":["依技術規則§69，房地成本價格＝土地價格＋建物成本價格，其中土地價格以土地總成本求取（土地價格求取有困難者，得以比較法或收益法計算），故以土地總成本代入土地價格之本選項最切合（建物成本價格係已扣除折舊之建物現值），為本題標準答案。","「房地成本價格＝土地總成本＋建物總成本」中之建物總成本若未扣除折舊，將高估建物實際價值，與正確公式「建物成本價格（已扣除折舊）」不符。","土地價格與建物成本價格加總後再「減去建物累積折舊額」會造成折舊重複扣除（因建物成本價格本身已扣除折舊），公式邏輯錯誤。","土地價格與建物成本價格相加後再「加上建物累積折舊額」，會使已扣除折舊的建物現值再加回折舊額，等同於恢復未折舊狀態，公式邏輯錯誤。"],"tr":"","core":["土地總成本＋已扣折舊的建物成本價格","建物總成本未扣折舊，會高估","再減累積折舊會重複扣除","再加累積折舊等於回復未折舊"],"hl":[[],["建物總成本","建物成本價格（已扣除折舊）"],["－建物累積折舊額","建物成本價格本身已扣除折舊"],["＋建物累積折舊額","已扣除折舊的建物現值"]]},{"id":"h:113-9","p":"h","src":"113年第9題","sec":"C1","stem":"下列何者非屬營造或施工費的內含項目？","opts":["直接人工費","間接材料費","開發商的合理利潤","資本利息"],"ok":[2],"ex":["直接人工費是技術規則明定營造施工費之內含項目之一，非本題答案（本題問「非屬」內含項目）。","間接材料費是技術規則明定營造施工費之內含項目之一。","§53 的是營造或施工利潤（屬營造施工費內含）；開發或建築利潤屬§52 總成本之獨立項目，不在營造或施工費內，故「開發商的合理利潤」為本題正解。","資本利息是技術規則明定營造施工費之內含項目之一。"],"tr":"","core":["直接人工費屬營造施工費內含項目","間接材料費屬營造施工費內含項目","開發利潤屬總成本獨立項，非營造費內","資本利息屬營造施工費內含項目"],"hl":[[],[],["開發商的合理利潤","開發或建築利潤屬§52 總成本之獨立項目，不在營造或施工費內"],[]]},{"id":"h:113-10","p":"h","src":"113年第10題","sec":"C1","stem":"有關營造或施工費的敘述何者錯誤？","opts":["營造或施工費屬於建物總成本的一部分，房屋愈舊，營造或施工費就愈低","勘估標的之營造或施工費，得按直接法或間接法擇一求取之。功能性退化造成的折舊屬於房屋折舊的一部分","淨計法屬於直接法的一種，是指就勘估標的所需要各種建築材料及人工之數量，逐一乘以價格日期當時該建築材料之單價及人工工資，並加計管理費、稅捐、資本利息及利潤","單位工程法也屬於直接法，係以建築細部工程之各項目單價乘以該工程施工數量，並合計之"],"ok":[0],"ex":["依§48，重建成本是「於價格日期」重新複製建築所需的成本，所以營造或施工費反映的是價格日期當時的造價，不會因屋齡而降低；屋齡增加反映在累積折舊額（§69），本選項錯誤，即本題正解。","勘估標的之營造或施工費，得按直接法或間接法擇一求取之，此為正確敘述；功能性退化造成的折舊屬於房屋折舊的一部分，此亦為正確敘述。","淨計法屬於直接法的一種，其定義（逐一材料人工數量乘以單價工資，並加計管理費稅捐資本利息利潤）與技術規則規定相符，敘述正確。","單位工程法也屬於直接法，其定義（建築細部工程各項目單價乘以施工數量並合計）與技術規則規定相符，敘述正確。"],"tr":"","core":["營造費反映價格日期造價，不因屋齡降低","直接法間接法擇一；功能退化屬折舊","淨計法屬直接法，逐一材料人工計價","單位工程法屬直接法，細部單價×數量"],"hl":[["房屋愈舊，營造或施工費就愈低","營造或施工費反映的是價格日期當時的造價"],[],[],[]]},{"id":"h:114-2","p":"h","src":"114年第2題","sec":"C1","stem":"以成本法進行不動產估價，下列何者非為總成本應包括之項目？","opts":["營造或施工費","出售不動產之所得稅","資本利息","建築利潤"],"ok":[1],"ex":["營造或施工費是技術規則明定總成本應包括之項目之一，非本題答案（本題問「非」總成本應包括之項目）。","出售不動產之所得稅是處分不動產後的稅務負擔，與成本法估算「建造」當下所需投入之總成本性質不同，並非技術規則明定總成本應包括之項目（這與收益法估算淨收益時排除所得稅之邏輯一致），即本題正解。","資本利息是技術規則明定總成本應包括之項目之一。","建築利潤是技術規則明定總成本應包括之項目之一（視性質得不予計入，但屬性上仍是總成本構成項目之一）。"],"tr":"","core":["營造或施工費屬總成本項目","所得稅是處分後稅負，非總成本項目","資本利息屬總成本項目","建築利潤屬總成本構成項目"],"hl":[[],["出售不動產之所得稅","處分不動產後的稅務負擔"],[],[]]},{"id":"h:114-18","p":"h","src":"114年第18題","sec":"C1","stem":"勘估標的營造或施工費之求取得採直接法或間接法，下列各方法中何者相對精細？","opts":["工程造價比較法","淨計法","單位工程法","單位面積比較法"],"ok":[1],"ex":["工程造價比較法屬間接法，精確度不及直接法，非本題答案（本題問「相對精細」之方法）。","淨計法是逐一材料人工數量乘以單價工資的最精細計算方式（逐項計算每一種材料與人工），屬直接法中最精細之方法，與題目敘述相符。","單位工程法雖屬直接法，但其計算單位是「工程項目」而非逐一材料人工，精細度不及淨計法。","單位面積比較法屬間接法，是較粗略的整體估算方式，精確度最低。"],"tr":"","core":["工程造價比較法屬間接法，精確度較低","淨計法逐一計算材料人工，最精細","單位工程法以工程項目計，不及淨計法","單位面積比較法屬間接法，精確度最低"],"hl":[["工程造價比較法","屬間接法，精確度不及直接法"],[],["單位工程法","精細度不及淨計法"],["單位面積比較法","屬間接法，是較粗略的整體估算方式"]]},{"id":"h:99-13","p":"h","src":"99年第13題","sec":"C2","stem":"建物經過一定時間會產生折舊，有關建物累積折舊額之計算，根據不動產估價技術規則規定應該以何為原則呢？","opts":["定額法","定率法","償債基金法","觀察法"],"ok":[0],"ex":["99年官方答案為A（定額法）。現行§68 規定累積折舊額應視建物特性及市場動態，選擇等速折舊、初期加速折舊或初期減速折舊三種路徑之折舊方法（現行法無「以定額法為原則」之規定；定額法即等速折舊路徑）。⚠️答案與現行法衝突，考試以官方公告答案為準。","定率法（每年依固定比率對前一年餘值計算）是折舊計算方法之一，但並非規則明定之原則方法。","償債基金法（複利提存概念）是折舊計算方法之一，但並非規則明定之原則方法。","「觀察法」並非技術規則明定之正式折舊計算方法名稱。"],"tr":"","core":["99年官方答案；現行法改選三種折舊路徑","定率法非規則明定之原則方法","償債基金法非規則明定之原則方法","觀察法非正式折舊計算方法"],"hl":[[],["定率法"],["償債基金法"],["觀察法","並非技術規則明定之正式折舊計算方法名稱"]]},{"id":"h:99-14","p":"h","src":"99年第14題","sec":"C2","stem":"當估價師進行不動產估價時，對於附有違章建築之房地估價，有關違建部分是否需要評估呢？","opts":["違建部分一定要評估。並需就合法建物及違建部分於估價報告書中合併計算其價值","違建部分不予以評估。但委託人要求評估其價值，並就合法建物及違建部分於估價報告書中分別標示各該部分之價格者，不在此限","違建部分一定要評估。但委託人要求評估其價值，可就合法建物及違建部分於估價報告書中分別標示各該部分之價格者","違建部分不予以評估。但受託人可自行斟酌其價值"],"ok":[1],"ex":["技術規則明定違建部分「不予以評估」，並非「一定要評估並合併計算」，本選項與規則規定相反。","技術規則明定附有違章建築之房地估價，違建部分不予以評估，但委託人要求評估其價值者，應就合法建物及違建部分分別標示各該部分之價格，與題目敘述完全相符。","違建部分原則上「不予以評估」（而非「一定要評估」），本選項對原則之描述與規則相反。","委託人要求評估時，應依規則規定分別標示價格，並非由受託人「自行斟酌」決定是否評估，本選項與規則明確規定不符。"],"tr":"","core":["違建原則不評估，非一定要合併計算","違建不評估；委託人要求則分別標示","違建原則不予評估，非一定要評估","委託人要求時分別標示，非受託人斟酌"],"hl":[["一定要評估","合併計算","違建部分「不予以評估」"],[],["一定要評估","違建部分原則上「不予以評估」"],["受託人可自行斟酌其價值","應依規則規定分別標示價格"]]},{"id":"h:99-16","p":"h","src":"99年第16題","sec":"C2","stem":"根據不動產估價技術規則規定，實際建築使用之容積率超過法定容積率之房地估價，應以何種容積估價呢？","opts":["以法定容積估價","以實際建築使用合法部分之現況估價","根據法定容積或是實際建築使用合法部分擇一估價","根據重新測量所得面積估價"],"ok":[1],"ex":["技術規則並非以「法定容積」估價（這會忽略實際已建成且合法之使用現況），與規則規定不符。","技術規則明定實際建築使用之容積率超過法定容積率之房地估價，應以實際建築使用合法部分之現況估價，並敘明法定容積對估值之影響，與題目敘述相符。","規則並非「擇一」估價，而是明確規定以實際建築使用合法部分之現況估價為準。","「根據重新測量所得面積估價」並非技術規則規定處理容積超限情形之方式。"],"tr":"","core":["非以法定容積，以合法部分現況估價","以實際建築使用合法部分現況估價","非擇一，明定以合法部分現況估價","重新測量面積非容積超限處理方式"],"hl":[["以法定容積估價"],[],["擇一估價"],["重新測量所得面積"]]},{"id":"h:99-26","p":"h","src":"99年第26題","sec":"C2","stem":"建築物因功能或效益衰退至不值得使用所經歷之年數，稱之為何？","opts":["物理耐用年數","化學耐用年數","經濟耐用年數","建築耐用年數"],"ok":[2],"ex":["物理耐用年數指建物因自然耗損或外力破壞至結構脆弱而不堪使用所經歷之年數，與題目所述「功能或效益衰退」之定義不同。","「化學耐用年數」並非技術規則明定之正式用語。","技術規則明定經濟耐用年數係建物因功能或效益衰退至不值得使用所經歷之年數，與題目敘述完全相符。","「建築耐用年數」並非技術規則明定之正式用語。"],"tr":"","core":["物理耐用年數是結構耗損，非效益衰退","化學耐用年數非技術規則正式用語","經濟耐用年數＝功能效益衰退至不值得用","建築耐用年數非技術規則正式用語"],"hl":[["物理耐用年數","建物因自然耗損或外力破壞至結構脆弱而不堪使用所經歷之年數"],["化學耐用年數"],[],["建築耐用年數"]]},{"id":"h:100-12","p":"h","src":"100年第12題","sec":"C2","stem":"依不動產估價技術規則之規定，計算建物折舊額時應以何種年數為主？","opts":["物理耐用年數","經濟耐用年數","資本使用年數","調整耐用年數"],"ok":[1],"ex":["物理耐用年數是結構層面之耐用年數概念，技術規則明定折舊計算應以經濟耐用年數為主，非物理耐用年數。","技術規則明定建物折舊額計算應以經濟耐用年數為主，與題目敘述相符。","「資本使用年數」是資本利息計算之相關概念，非建物折舊計算所採用之耐用年數類型。","「調整耐用年數」並非技術規則明定之正式用語。"],"tr":"","core":["折舊以經濟耐用年數為主，非物理","建物折舊額以經濟耐用年數為主","資本使用年數屬資本利息概念，非折舊","調整耐用年數非技術規則正式用語"],"hl":[["物理耐用年數","折舊計算應以經濟耐用年數為主"],[],["資本使用年數","是資本利息計算之相關概念"],["調整耐用年數"]]},{"id":"h:101-14","p":"h","src":"101年第14題","sec":"C2","stem":"運用成本法估計建築物價格時，如採定額法折舊，則求取建築物累積折舊之公式為：Dn = C × [(1 - s )/N] × n，其中N優先採用下列何者？","opts":["物理耐用年數","殘餘年數","經濟耐用年數","已經歷年數"],"ok":[2],"ex":["物理耐用年數是結構層面之概念，技術規則明定折舊計算公式中N應優先採用經濟耐用年數，非物理耐用年數。","「殘餘年數」並非折舊公式中N所代表之正確變數名稱（N代表的是耐用年數本身）。","技術規則明定定額法折舊公式中之N（總耐用年數）應優先採用經濟耐用年數，與題目敘述相符，這是因為經濟耐用年數較能反映建物實際喪失市場價值之時點。","「已經歷年數」是公式中之變數n（小寫，已使用年數），與公式中N（大寫，總耐用年數）為不同變數，本選項混淆兩者。"],"tr":"","core":["公式N優先採經濟耐用年數，非物理","N代表耐用年數本身，非殘餘年數","N優先採經濟耐用年數","已經歷年數是小寫n，與N不同"],"hl":[["物理耐用年數","N應優先採用經濟耐用年數"],["殘餘年數","N代表的是耐用年數本身"],[],["已經歷年數","是公式中之變數n（小寫，已使用年數）"]]},{"id":"h:101-26","p":"h","src":"101年第26題","sec":"C2","stem":"於不動產估價時，所謂物理的耐用年數，係指：","opts":["建築改良物從興建完成，至不堪使用的期間","建築改良物對不動產價值具有貢獻的一段期間","建築改良物從興建完成，至毀損的期間","建築改良物從興建完成，至其經濟壽命結束的期間"],"ok":[0],"ex":["§65定義物理耐用年數為「建物因自然耗損或外力破壞至結構脆弱而不堪使用所經歷之年數」，與本選項「從興建完成至不堪使用的期間」相符。","「對不動產價值具有貢獻的一段期間」較接近經濟耐用年數之概念（強調效益與價值貢獻），非物理耐用年數定義。","「至毀損的期間」描述較為片面，技術規則之正式定義是「至不堪使用」，毀損僅是不堪使用的其中一種成因。","「至其經濟壽命結束的期間」是經濟耐用年數之定義，非物理耐用年數。"],"tr":"","core":["物理耐用＝興建完成至不堪使用","價值貢獻期間較接近經濟耐用年數","規則用語是不堪使用，非僅毀損","經濟壽命結束是經濟耐用年數定義"],"hl":[[],["對不動產價值具有貢獻的一段期間","較接近經濟耐用年數之概念"],["至毀損的期間","技術規則之正式定義是「至不堪使用」"],["經濟壽命結束","是經濟耐用年數之定義"]]},{"id":"h:101-35","p":"h","src":"101年第35題","sec":"C2","stem":"某棟建物耐用年數為50年，殘價率為10％，該建物每年折舊率為：","opts":["1.8％","2.0％","1.5％","2.4％"],"ok":[0],"ex":["依定額法折舊率公式：(1－殘價率)÷耐用年數＝(1－10%)÷50＝0.9÷50＝1.8%，與本選項相符。","2.0%的計算未正確扣除殘價率10%，直接以100%÷50年計算，未考慮殘餘部分。","1.5%無法由題幹常見誤算得到；正確為(1－10%)÷50＝1.8%。","2.4%無法由題幹常見誤算得到；正確為(1－10%)÷50＝1.8%。"],"tr":"","core":["(1－10%)÷50＝1.8%","未扣殘價率，100%÷50的誤算","非常見誤算，正確為1.8%","非常見誤算，正確為1.8%"],"hl":[[],["2.0％","直接以100%÷50年計算"],["1.5％","正確為(1－10%)÷50＝1.8%"],["2.4％","正確為(1－10%)÷50＝1.8%"]]},{"id":"h:102-16","p":"h","src":"102年第16題","sec":"C2","stem":"建物累積折舊額之計算，以採下列何種方法之建物成本價格結果最低？","opts":["定額法","定率法","償債基金法","逆年數合計法"],"ok":[1],"ex":["定額法是每年折舊額固定之等速折舊，建物成本價格（現值）在折舊期間內呈線性遞減，並非各方法中結果最低者。","定率法每年折舊＝「前一年餘值×固定比率」，餘值逐年變小，所以第1年折舊額最大、之後逐年遞減（初期加速）。算例：總成本1,000萬、耐用年數50年、殘價率10%、經歷10年——定額法現值＝1,000−900×10÷50＝820萬；定率法現值＝1,000×0.1¹⁰⁄⁵⁰≈631萬；償債基金法（提存利率2%）累積折舊≈900×(1.02¹⁰−1)÷(1.02⁵⁰−1)≈116.5萬，現值≈883.5萬。631＜820＜883.5，所以定率法現值（成本價格）最低、累積折舊額最大。為什麼一定如此（不只是「通常」）：三法起點都是1,000、耐用年數終了都剛好降到殘值100，差別只在中間路徑。定額法是兩端連成的直線；定率法是在直線下方的彎曲線（先降得多）；償債基金法是在直線上方的彎曲線（先降得少）。只要經歷年數介於0與耐用年數之間，三者順序固定：定率法現值＜定額法現值＜償債基金法現值。（本題問的是「成本價格最低」，即累積折舊最大，不是「年折舊額最大」。）","償債基金法是初期減速折舊（複利提存概念），初期折舊較慢，建物現值通常高於定率法之結果。","逆年數合計法（教材）屬初期減速型（前期折舊少、後期多），同一經歷年數下累積折舊比定率法少，成本價格不會最低，不選。"],"tr":"","core":["定額法線性遞減，現值非最低","定率法初期加速，成本價格最低","償債基金法初期減速，現值較高","逆年數合計法初期減速，現值不最低"],"hl":[["定額法","並非各方法中結果最低者"],[],["償債基金法","初期減速折舊（複利提存概念），初期折舊較慢"],["逆年數合計法","同一經歷年數下累積折舊比定率法少"]]},{"id":"h:102-17","p":"h","src":"102年第17題","sec":"C2","stem":"某建物於10年前興建，面積50坪，目前建材單價新臺幣10萬元/坪，殘餘價格率4%、經濟耐用年數40年，請問該建物累積折舊額為新臺幣多少萬元？","opts":["140萬元","120萬元","100萬元","80萬元"],"ok":[1],"ex":["140萬元＝500－500×(1－4%)÷40×30，誤把剩餘年數30年當成經歷年數，又算成現值；正確累積折舊額為120萬元。","重建成本＝10萬元×50坪＝500萬元；年折舊額＝500×(1-4%)÷40＝12萬元；累積折舊額（10年）＝12×10＝120萬元，與本選項相符。","100萬元無法由題幹常見誤算得到（不扣殘價率為500÷40×10＝125萬元）；正確為120萬元。","80萬元無法由題幹常見誤算得到；正確為500×(1－4%)÷40×10＝120萬元。"],"tr":"","core":["誤把剩餘30年當經歷年數，正確120萬","500×(1－4%)÷40×10＝120萬","非常見誤算，正確為120萬","非常見誤算，正確為120萬"],"hl":[["140萬元","誤把剩餘年數30年當成經歷年數"],[],["100萬元","正確為120萬元"],["80萬元","正確為500×(1－4%)÷40×10＝120萬元"]]},{"id":"h:102-37","p":"h","src":"102年第37題","sec":"C2","stem":"依不動產估價技術規則規定，實際建築使用的容積率超過法定容積率時，應如何估價？","opts":["以實際建築使用合法部分之現況估價","以法定容積之使用方式估價，再依使用狀況調整","僅能依法定容積估價","實際使用部分全部均可以估價"],"ok":[0],"ex":["技術規則明定實際建築使用之容積率超過法定容積率之房地估價，應以實際建築使用合法部分之現況估價，並敘明法定容積對估值之影響，與題目敘述相符。","規則並非「以法定容積之使用方式估價再依使用狀況調整」，而是直接以實際建築使用合法部分之現況估價。","規則並非「僅能依法定容積估價」，這會忽略實際已合法建成之使用現況。","規則並非「實際使用部分全部均可估價」，違建部分仍應排除，僅以「合法部分」之現況估價。"],"tr":"","core":["以實際建築使用合法部分現況估價","非依法定容積再調整，直接以合法現況","非僅依法定容積，以合法部分現況估價","違建仍排除，僅以合法部分估價"],"hl":[[],["以法定容積之使用方式估價","直接以實際建築使用合法部分之現況估價"],["僅能依法定容積估價"],["全部均可以估價","違建部分仍應排除，僅以「合法部分」之現況估價"]]},{"id":"h:102-39","p":"h","src":"102年第39題","sec":"C2","stem":"依不動產估價技術規則規定，建物殘餘價格率之上限為多少？","opts":["5%","10%","15%","20%"],"ok":[1],"ex":["5%並非技術規則規定之殘餘價格率上限。","技術規則明定建物殘餘價格率以不超過10%為原則，與題目敘述相符。","15%並非技術規則規定之殘餘價格率上限。","20%並非技術規則規定之殘餘價格率上限。"],"tr":"","core":["5%並非殘餘價格率上限","殘餘價格率以不超過10%為原則","15%並非殘餘價格率上限","20%並非殘餘價格率上限"],"hl":[["5%"],[],["15%"],["20%"]]},{"id":"h:103-7","p":"h","src":"103年第7題","sec":"C2","stem":"建物之殘餘價格率應由何者公告之？","opts":["內政部地政司","不動產估價師公會全國聯合會","全國建築師公會","內政部營建署"],"ok":[1],"ex":["「內政部地政司」並非技術規則明定公告建物殘餘價格率之單位。","技術規則明定建物殘餘價格率應由不動產估價師公會全國聯合會公告，與題目敘述相符。","「全國建築師公會」並非技術規則明定公告殘餘價格率之單位。","「內政部營建署」並非技術規則明定公告殘餘價格率之單位。"],"tr":"","core":["地政司非公告殘餘價格率之單位","殘餘價格率由估價師全聯會公告","建築師公會非公告殘餘價格率單位","營建署非公告殘餘價格率之單位"],"hl":[["內政部地政司"],[],["全國建築師公會"],["內政部營建署"]]},{"id":"h:103-9","p":"h","src":"103年第9題","sec":"C2","stem":"有一建物耐用年限40年，年限屆滿時之殘餘價格率為10%，若以定額法計算折舊額，則每年之折舊率為：","opts":["2%","2.25%","2.5%","2.75%"],"ok":[1],"ex":["2%無法由題幹常見誤算得到；正確為(1－10%)÷40＝2.25%。","依定額法折舊率公式：(1－殘價率)÷耐用年數＝(1－10%)÷40＝0.9÷40＝2.25%，與本選項相符。","2.5%＝100%÷40年，是沒有扣除殘餘價格率10%的陷阱數字；定額法要先乘(1－殘餘價格率)：0.9÷40＝2.25%。","2.75%＝(1＋10%)÷40，誤把殘餘價格率「加上」而不是扣除；正確為(1－10%)÷40＝2.25%。"],"tr":"","core":["非常見誤算，正確為2.25%","(1－10%)÷40＝2.25%","100%÷40未扣殘價率的誤算","誤把殘價率加上，(1＋10%)÷40"],"hl":[["2%","正確為(1－10%)÷40＝2.25%"],[],["2.5%","定額法要先乘(1－殘餘價格率)"],["2.75%","誤把殘餘價格率「加上」而不是扣除"]]},{"id":"h:103-11","p":"h","src":"103年第11題","sec":"C2","stem":"請問計算建物累積折舊額，下列何者不屬於不動產估價技術規則規範之折舊路徑？","opts":["等速折舊","初期加速折舊","初期減速折舊","後期減速折舊"],"ok":[3],"ex":["等速折舊是技術規則明定規範之三種折舊路徑之一（對應定額法），非本題答案（本題問「不屬於」之路徑）。","初期加速折舊是技術規則明定規範之三種折舊路徑之一（對應定率法）。","初期減速折舊是技術規則明定規範之三種折舊路徑之一（對應償債基金法）。","技術規則僅明定等速折舊、初期加速折舊、初期減速折舊三種路徑，並無「後期減速折舊」此一路徑，這是常見混淆陷阱，即本題正解。"],"tr":"","core":["等速折舊屬規範路徑（定額法）","初期加速折舊屬規範路徑（定率法）","初期減速折舊屬規範路徑（償債基金法）","無後期減速折舊，規範僅三種路徑"],"hl":[[],[],[],["後期減速折舊","技術規則僅明定等速折舊、初期加速折舊、初期減速折舊三種路徑"]]},{"id":"h:103-22","p":"h","src":"103年第22題","sec":"C2","stem":"某一屋齡20年的40坪建物，經調查，其目前之重置成本為每坪10萬元，假設其經濟耐用年數為50年、殘餘價格率為10%，請問其建物成本價格為何？","opts":["184萬元","216萬元","240萬元","256萬元"],"ok":[3],"ex":["184萬元＝400－400×(1－10%)÷50×30，誤用剩餘年數30年計算累積折舊；正確為400－144＝256萬元。","216萬元＝400×(1－10%)×(1－20/50)，把(1－s)乘到整個現值上，等於殘餘價格也被折掉；正確為256萬元。","240萬元＝400×(1－20/50)，沒有扣除殘餘價格率10%（折舊多算）；正確為256萬元。","重建成本＝10萬元×40坪＝400萬元；年折舊額＝400×(1-10%)÷50＝7.2萬元；累積折舊額（20年）＝7.2×20＝144萬元；建物成本價格＝400－144＝256萬元，與本選項相符。"],"tr":"","core":["誤用剩餘年數30年，正確256萬","(1－s)乘到整個現值，殘值也被折掉","未扣殘價率10%，折舊多算","400－累積折舊144＝256萬"],"hl":[["184萬元","正確為400－144＝256萬元"],["216萬元","把(1－s)乘到整個現值上"],["240萬元","沒有扣除殘餘價格率10%"],[]]},{"id":"h:103-32","p":"h","src":"103年第32題","sec":"C2","stem":"下列有關耐用年數之敘述，何者有誤？","opts":["建物耐用年數終止後確實無殘餘價格者，於計算折舊時不予提列","建物折舊額計算應以經濟耐用年數為主","建物經濟耐用年數表由不動產估價師公會全國聯合會公告之","物理耐用年數指建物因功能或效益衰退至不值得使用所經歷之年數"],"ok":[3],"ex":["建物耐用年數終止後確實無殘餘價格者，於計算折舊時不予提列，此為正確敘述，非本題答案（本題問「何者有誤」）。","建物折舊額計算應以經濟耐用年數為主，此為正確敘述。","建物經濟耐用年數表由不動產估價師公會全國聯合會公告之，此為正確敘述。","技術規則明定物理耐用年數係指建物因「自然耗損或外力破壞」至結構脆弱不堪使用所經歷之年數，本選項稱「因功能或效益衰退」（此為經濟耐用年數之定義），定義誤植，敘述錯誤，即本題正解。"],"tr":"","core":["確無殘餘價格者，折舊時不予提列","折舊額計算以經濟耐用年數為主","經濟耐用年數表由全聯會公告","功能效益衰退是經濟耐用年數定義"],"hl":[[],[],[],["因功能或效益衰退","因「自然耗損或外力破壞」","結構脆弱不堪使用所經歷之年數"]]},{"id":"h:104-20","p":"h","src":"104年第20題","sec":"C2","stem":"下列有關建物殘餘價格率之敘述，何者正確？","opts":["建物之殘餘價格率應由全聯會公告之，並以不超過百分之二十為原則","建物耐用年數終止後確實無殘餘價格者，於計算折舊時應酌予推估提列","殘餘價格率計算建物殘餘價格時，應考量建物耐用年數終止後所需清理或清除成本","殘餘價格率指建物於物理耐用年數屆滿後，其所賸餘之結構材料及內部設備預定出售之價格占建物總成本之比率"],"ok":[2],"ex":["技術規則明定建物殘餘價格率應由全聯會公告，並以不超過10%（而非20%）為原則，本選項數字錯誤。","建物耐用年數終止後確實無殘餘價格者，於計算折舊時「不予提列」（而非酌予推估提列），本選項與規則規定相反。","技術規則明定計算建物殘餘價格時，應考量建物耐用年數終止後所需清理或清除成本，與題目敘述相符，此為正確敘述。","技術規則明定殘餘價格率係指建物於「經濟」耐用年數屆滿後（而非物理耐用年數），其所賸餘之結構材料及內部設備仍能於市場上出售（§67 Ⅲ 用語，本選項寫「預定出售」，用語略異）之價格占建物「總成本」之比率；本選項錯在「物理耐用年數屆滿」。"],"tr":"","core":["殘價率上限是10%，不是20%","確無殘價者不予提列，非推估提列","計算殘價須考量清理或清除成本","是經濟耐用年數屆滿，非物理"],"hl":[["百分之二十","不超過10%"],["酌予推估提列","「不予提列」"],[],["物理耐用年數屆滿後","「經濟」耐用年數屆滿後"]]},{"id":"h:104-21","p":"h","src":"104年第21題","sec":"C2","stem":"一棟透天厝因緊鄰施工中工地而發生牆壁龜裂現象，估價時最可能將此一情形列為下列何種折舊？","opts":["功能性折舊","物理性折舊","經濟性折舊","破壞性折舊"],"ok":[1],"ex":["功能性折舊是因技術革新、設計過時等致使建物效用衰退之折舊，與緊鄰施工造成的物理性損害不同。","依教材折舊分類，緊鄰施工中工地造成牆壁龜裂，是建物本身受到外力破壞致結構受損之現象，屬於物理性折舊（自然耗損或外力破壞所致），與題目敘述相符。","經濟性折舊是因外部環境變化（如嫌惡設施、區域衰退）致使價值減損，而非建物本身結構直接受損之物理性損害。","「破壞性折舊」並非技術規則明定之正式折舊分類名稱。"],"tr":"","core":["功能性是設計過時，非外力損害","緊鄰施工致龜裂屬外力破壞＝物理性","經濟性是外部環境變化，非結構受損","破壞性折舊非正式折舊分類"],"hl":[["功能性折舊","因技術革新、設計過時等致使建物效用衰退之折舊"],[],["經濟性折舊","因外部環境變化（如嫌惡設施、區域衰退）"],["破壞性折舊"]]},{"id":"h:104-32","p":"h","src":"104年第32題","sec":"C2","stem":"實際建築使用之容積率超過法定容積率之房地估價，應以那些部分之現況估價，並敘明法定容積對估值之影響？","opts":["以所有實際建築使用部分估價","以實際建築使用合法部分再扣除違章建築部分後估價","以實際建築使用合法部分估價","不論是否合法皆以法定容積率部分估價"],"ok":[2],"ex":["「以所有實際建築使用部分估價」未排除違章建築部分，與規則規定僅就「合法部分」估價之原則不符。","「實際建築使用合法部分再扣除違章建築部分」此描述邏輯重複（合法部分本身即不含違章部分），雖結果相同但描述方式較為迂迴，非規則明確用語。","技術規則明定實際建築使用之容積率超過法定容積率之房地估價，應以實際建築使用合法部分之現況估價，並敘明法定容積對估值之影響，與題目敘述完全相符。","「不論是否合法皆以法定容積率部分估價」與規則規定應以「合法部分」之「現況」（而非法定容積率部分）估價之原則不符。"],"tr":"","core":["未排除違建，應僅就合法部分估價","描述迂迴重複，非規則明確用語","以實際建築使用合法部分現況估價","應以合法部分現況，非法定容積部分"],"hl":[["所有實際建築使用部分","僅就「合法部分」估價"],["再扣除違章建築部分","合法部分本身即不含違章部分"],[],["皆以法定容積率部分估價","應以「合法部分」之「現況」"]]},{"id":"h:105-18","p":"h","src":"105年第18題","sec":"C2","stem":"因同種類不動產，由於技術革新、設計變化等，致使勘估標的落伍了，由此發生之建物折舊減價，屬於下列何種折舊因素？","opts":["物理性","外部性","功能性","經濟性"],"ok":[2],"ex":["物理性折舊是因自然耗損或外力破壞致結構受損，與題目所述「技術革新、設計變化致使標的落伍」之性質不同。","「外部性」並非技術規則明定折舊分類之正式用語（外部性是估價原則概念，非折舊分類）。","教材定義（§68 僅提及物理、功能、經濟因素，未逐類定義）：功能性折舊係因同種類不動產，由於技術革新、設計變化等，致使勘估標的之效用較同類最新建物相對落伍所生之減價，與題目敘述完全相符。","經濟性折舊是因外部環境變化（如周邊嫌惡設施、區域發展衰退）所致，與題目所述「技術革新、設計變化」之內部功能落伍性質不同。"],"tr":"","core":["物理性是耗損或外力，非設計落伍","外部性非折舊分類正式用語","技術革新設計變化致落伍＝功能性","經濟性是外部環境變化，非功能落伍"],"hl":[["物理性","因自然耗損或外力破壞致結構受損"],["外部性","外部性是估價原則概念，非折舊分類"],[],["經濟性","因外部環境變化（如周邊嫌惡設施、區域發展衰退）所致"]]},{"id":"h:105-21","p":"h","src":"105年第21題","sec":"C2","stem":"有關建物殘餘價格率之敘述，下列何者錯誤？","opts":["殘餘價格率是指建物於物理耐用年數屆滿後，其所賸餘之結構材料及內部設備仍能於市場上出售之價格占建物總成本之比率","建物之殘餘價格率應由不動產估價師公會全國聯合會公告","建物之殘餘價格率以不超過百分之十為原則","依殘餘價格率計算建物殘餘價格時，應考量建物耐用年數終止後所需清理或清除成本"],"ok":[0],"ex":["技術規則明定殘餘價格率係指建物於「經濟」耐用年數屆滿後（而非物理耐用年數），其所賸餘之結構材料及內部設備仍能於市場上出售（§67 Ⅲ 用語）之價格占建物「總成本」之比率，本選項將「經濟耐用年數」誤植為「物理耐用年數」，定義有誤，即本題正解。","建物之殘餘價格率應由不動產估價師公會全國聯合會公告，此為正確敘述。","建物之殘餘價格率以不超過10%為原則，此為正確敘述。","依殘餘價格率計算建物殘餘價格時，應考量建物耐用年數終止後所需清理或清除成本，此為正確敘述。"],"tr":"","core":["是經濟耐用年數屆滿，非物理","殘餘價格率由全聯會公告","殘餘價格率以不超過10%為原則","計算殘價須考量清理或清除成本"],"hl":[["物理耐用年數屆滿後","「經濟」耐用年數屆滿後"],[],[],[]]},{"id":"h:105-30","p":"h","src":"105年第30題","sec":"C2","stem":"不動產估價技術規則有關耐用年數之敘述，下列何者最為正確？","opts":["建物折舊額計算應以經濟耐用年數為主","建物折舊額計算應以物理耐用年數為主","經濟耐用年數指建物因自然耗損或外力破壞至結構脆弱而不堪使用所經歷之年數","物理耐用年數指建物因功能或效益衰退至不值得使用所經歷之年數"],"ok":[0],"ex":["技術規則明定建物折舊額計算應以經濟耐用年數為主，與題目敘述相符，此為正確敘述。","建物折舊額計算應以經濟耐用年數（而非物理耐用年數）為主，本選項與規則規定相反。","技術規則明定「經濟」耐用年數係因功能或效益衰退至不值得使用所經歷之年數，本選項將此定義誤植為物理耐用年數，定義對調錯誤。","技術規則明定「物理」耐用年數係因自然耗損或外力破壞至結構脆弱不堪使用所經歷之年數，本選項將此定義誤植為功能或效益衰退（此為經濟耐用年數之定義），定義對調錯誤。"],"tr":"","core":["折舊額計算以經濟耐用年數為主","應以經濟耐用年數為主，非物理","經濟耐用是效益衰退，定義對調","物理耐用是耗損外力，定義對調"],"hl":[[],["物理耐用年數為主","應以經濟耐用年數（而非物理耐用年數）為主"],["因自然耗損或外力破壞","因功能或效益衰退至不值得使用所經歷之年數"],["因功能或效益衰退","自然耗損或外力破壞至結構脆弱不堪使用"]]},{"id":"h:105-33","p":"h","src":"105年第33題","sec":"C2","stem":"某建物樓地板面積為100坪，重建每坪10萬元，若耐用年數為50年，殘值率為10%，目前已使用10年，採定額法折舊，請問該建物之現值為幾萬元？","opts":["820","720","620","520"],"ok":[0],"ex":["重建成本＝10萬元×100坪＝1,000萬元；年折舊額＝1,000×(1-10%)÷50＝18萬元；累積折舊額（10年）＝18×10＝180萬元；建物現值＝1,000－180＝820萬元，與本選項相符。","720萬元＝1,000×(1－10%)×(1－10/50)，把(1－殘餘價格率)乘到整個現值上；正確為1,000－180＝820萬元。","620萬元無法由題幹常見誤算得到；正確為820萬元。","520萬元無法由題幹常見誤算得到；正確為820萬元。"],"tr":"","core":["1,000－18×10＝820萬","(1－s)乘到整個現值的誤算","非常見誤算，正確為820萬","非常見誤算，正確為820萬"],"hl":[[],["720","把(1－殘餘價格率)乘到整個現值上"],["620","正確為820萬元"],["520","正確為820萬元"]]},{"id":"h:106-12","p":"h","src":"106年第12題","sec":"C2","stem":"下列有關成本法耐用年數之敘述，何者正確？","opts":["建物折舊額計算應以物理耐用年數為主","物理耐用年數指建物因功能或效益衰退至不值得使用所經歷之年數","經濟耐用年數指建物因自然耗損或外力破壞至結構脆弱而不堪使用所經歷之年數","建物之經歷年數大於其經濟耐用年數時，應重新調整經濟耐用年數"],"ok":[3],"ex":["建物折舊額計算應以經濟耐用年數（而非物理耐用年數）為主，本選項與規則規定相反。","技術規則明定「經濟」耐用年數係因功能或效益衰退至不值得使用所經歷之年數，本選項將此定義誤植為物理耐用年數。","技術規則明定「物理」耐用年數係因自然耗損或外力破壞至結構脆弱不堪使用所經歷之年數，本選項將此定義誤植為經濟耐用年數。","技術規則明定建物之經歷年數大於其經濟耐用年數時，應重新調整經濟耐用年數（因原訂之經濟耐用年數顯然低估該建物實際可使用之期間），與題目敘述相符，此為正確敘述。"],"tr":"","core":["應以經濟耐用年數為主，非物理","效益衰退是經濟耐用年數定義","耗損外力是物理耐用年數定義","經歷年數超過經濟耐用年數應重調"],"hl":[["物理耐用年數為主","經濟耐用年數（而非物理耐用年數）為主"],["因功能或效益衰退","因功能或效益衰退至不值得使用所經歷之年數"],["因自然耗損或外力破壞","自然耗損或外力破壞至結構脆弱不堪使用"],[]]},{"id":"h:106-17","p":"h","src":"106年第17題","sec":"C2","stem":"某建物於10年前興建，重建成本500萬元，殘餘價格率4%、經濟耐用年數40年，請問等速折舊型之建物成本價格為何？","opts":["120萬元","240萬元","300萬元","380萬元"],"ok":[3],"ex":["120萬元是累積折舊額，不是建物成本價格。","240萬元無法由題幹常見誤算得到；正確為500－500×(1－4%)÷40×10＝380萬元。","300萬元無法由題幹常見誤算得到；正確為500－500×(1－4%)÷40×10＝380萬元。","依§68、§69：年折舊額＝500×(1－4%)÷40＝12萬元，累積折舊額＝12×10＝120萬元，建物成本價格＝500－120＝380萬元，與本選項相符。"],"tr":"","core":["120萬是累積折舊額，非成本價格","非常見誤算，正確為380萬","非常見誤算，正確為380萬","500－12×10＝380萬"],"hl":[["120萬元","120萬元是累積折舊額"],["240萬元","正確為500－500×(1－4%)÷40×10＝380萬元"],["300萬元","正確為500－500×(1－4%)÷40×10＝380萬元"],[]]},{"id":"h:106-26","p":"h","src":"106年第26題","sec":"C2","stem":"依不動產估價技術規則第68條規定，建物累積折舊額之計算，應視下列何者選擇屬於等速折舊、初期加速折舊或初期減速折舊路徑之折舊方法？","opts":["建商信譽","建管單位要求","建物特性及市場動態","建築設計及建築投資公會"],"ok":[2],"ex":["「建商信譽」與折舊路徑之選擇判斷無直接關連，非技術規則規定之依據。","「建管單位要求」並非技術規則第68條規定選擇折舊路徑之依據。","技術規則第68條明定，建物累積折舊額之計算，應視建物特性及市場動態，選擇屬於等速折舊、初期加速折舊或初期減速折舊路徑之折舊方法，與題目敘述完全相符。","「建築設計及建築投資公會」並非技術規則規定選擇折舊路徑之依據。"],"tr":"","core":["建商信譽與折舊路徑選擇無關","建管單位要求非折舊路徑依據","依建物特性及市場動態選折舊路徑","建築公會非折舊路徑選擇依據"],"hl":[["建商信譽"],["建管單位要求"],[],["建築設計及建築投資公會"]]},{"id":"h:106-27","p":"h","src":"106年第27題","sec":"C2","stem":"某建物已完工5年，面積100m2，目前重建成本單價為新臺幣3萬元/m2，殘餘價格率為5%、經濟耐用年數為50年，請問該建物累積折舊額為多少？","opts":["28.5萬元","30萬元","25萬元","27萬元"],"ok":[0],"ex":["重建成本＝3萬元/m2×100m2＝300萬元；年折舊額＝300×(1-5%)÷50＝5.7萬元；累積折舊額（5年）＝5.7×5＝28.5萬元，與本選項相符。","30萬元的計算未正確扣除殘餘價格率5%之影響。","25萬元無法由題幹常見誤算得到；正確為300×(1－5%)÷50×5＝28.5萬元。","27萬元＝300×(1－10%)÷50×5，誤把殘餘價格率當成10%；正確為28.5萬元。"],"tr":"","core":["300×(1－5%)÷50×5＝28.5萬","未扣殘價率5%的誤算","非常見誤算，正確為28.5萬","誤把殘價率當10%，正確28.5萬"],"hl":[[],["30萬元","未正確扣除殘餘價格率5%之影響"],["25萬元","正確為300×(1－5%)÷50×5＝28.5萬元"],["27萬元","誤把殘餘價格率當成10%"]]},{"id":"h:107-13","p":"h","src":"107年第13題","sec":"C2","stem":"附有違章建築之房地估價，有關違建部分之處理方式，下列何者正確？","opts":["違建部分不予以評估","委託人要求評估違建部分之價值時，只需就合法建物及違建部分於估價報告書中標示合併之總價格即可","委託人如果要求評估違建部分之價值時，應拒絕之","不論委託人有無要求，皆應就合法建物及違建部分於估價報告書中標示合併之總價格"],"ok":[0],"ex":["技術規則明定附有違章建築之房地估價，違建部分原則上不予以評估，與題目敘述相符，此為正確敘述。","委託人要求評估違建部分價值時，應「分別標示」合法建物及違建部分之各別價格（而非合併標示總價格），本選項與規則規定相反。","委託人要求評估違建部分價值時，技術規則允許「分別標示」評估，並非應拒絕之，本選項與規則規定不符。","規則並非「不論有無要求皆應合併標示總價格」，而是原則上不評估違建，僅於委託人要求時才分別標示評估，本選項與規則規定不符。"],"tr":"","core":["違建部分原則不予評估","應分別標示，非合併總價","可分別標示評估，非應拒絕","原則不評估，要求時才分別標示"],"hl":[[],["合併之總價格","應「分別標示」合法建物及違建部分之各別價格"],["應拒絕之","技術規則允許「分別標示」評估"],["不論委託人有無要求","合併之總價格","原則上不評估違建，僅於委託人要求時才分別標示評估"]]},{"id":"h:109-1","p":"h","src":"109年第1題","sec":"C2","stem":"下列有關成本法之建物殘餘價格之敘述，何者正確？","opts":["建物之殘餘價格率以不超過百分之二十為原則","建物耐用年數終止後無殘餘價格者，於計算折舊時以最低殘餘價格率提列","殘餘價格率，指建物於經濟耐用年數屆滿後，於市場上出售之價格占房地總價格之比率","計算建物殘餘價格時，應考量建物耐用年數終止後所需清理或清除成本"],"ok":[3],"ex":["技術規則明定建物之殘餘價格率應由全聯會公告，並以不超過10%（而非20%）為原則，本選項數字錯誤。","建物耐用年數終止後無殘餘價格者，於計算折舊時「不予提列」（而非以最低殘餘價格率提列），本選項與規則規定相反。","殘餘價格率係指建物於耐用年數屆滿後，出售之價格占建物「總成本」（本選項稱「占房地總價格」，未精確對應規則所稱之「建物總成本」這一基準），本選項定義基準誤植。","技術規則明定計算建物殘餘價格時，應考量建物耐用年數終止後所需清理或清除成本，與題目敘述相符，此為正確敘述。"],"tr":"","core":["殘價率上限是10%，不是20%","無殘價者不予提列，非最低率提列","基準是建物總成本，非房地總價格","計算殘價須考量清理或清除成本"],"hl":[["百分之二十","不超過10%"],["最低殘餘價格率提列","「不予提列」"],["占房地總價格","占建物「總成本」"],[]]},{"id":"h:109-2","p":"h","src":"109年第2題","sec":"C2","stem":"某一建築物重建成本為800萬元，經濟耐用年數為40年，物理耐用年數為50年，該建築物殘餘價格為80萬元，現已完工使用經過10年，請問該建築物以等速折舊計算時，每年折舊額為多少？","opts":["14.4萬元","16萬元","18萬元","20萬元"],"ok":[2],"ex":["14.4萬元＝(800－80)÷50，是誤用物理耐用年數50年的結果；折舊應以經濟耐用年數40年計算。","16萬元＝800÷50，既誤用物理耐用年數50年，也沒扣殘餘價格80萬元；正確為(800－80)÷40＝18萬元。","本題之殘餘價格為「80萬元」之絕對金額（而非比率），應採經濟耐用年數40年計算：年折舊額＝(重建成本800萬元－殘餘價格80萬元)÷經濟耐用年數40年＝720÷40＝18萬元，與本選項相符。注意本題雖同時給出物理耐用年數50年，但折舊計算應以「經濟耐用年數」為主。","20萬元＝800÷40，是沒有扣除殘餘價格80萬元的結果；應以(800－80)÷40＝18萬元計算。"],"tr":"","core":["誤用物理耐用50年，應用經濟40年","誤用50年又未扣殘價，正確18萬","(800－80)÷經濟耐用40年＝18萬","800÷40未扣殘餘價格80萬"],"hl":[["14.4萬元","折舊應以經濟耐用年數40年計算"],["16萬元","正確為(800－80)÷40＝18萬元"],[],["20萬元","應以(800－80)÷40＝18萬元計算"]]},{"id":"h:110-5","p":"h","src":"110年第5題","sec":"C2","stem":"建物總成本1,000萬元，經濟耐用年數50年，建物殘餘價格率10%。若每年折舊額皆相同，請問每年折舊率為何？","opts":["1.5%","1.8%","2%","2.2%"],"ok":[1],"ex":["1.5%無法由題幹常見誤算得到；正確為(1－10%)÷50＝1.8%。","依定額法折舊率公式：(1－殘價率)÷耐用年數＝(1－10%)÷50＝0.9÷50＝1.8%，與本選項相符。","2%的計算未正確扣除殘餘價格率10%之影響。","2.2%＝(1＋10%)÷50，誤把殘餘價格率加上去；正確為1.8%。"],"tr":"","core":["非常見誤算，正確為1.8%","(1－10%)÷50＝1.8%","未扣殘價率10%的誤算","誤把殘價率加上，正確1.8%"],"hl":[["1.5%","正確為(1－10%)÷50＝1.8%"],[],["2%","未正確扣除殘餘價格率10%之影響"],["2.2%","誤把殘餘價格率加上去"]]},{"id":"h:110-24","p":"h","src":"110年第24題","sec":"C2","stem":"實際建築使用之容積率超過法定容積率之房地，應以何種方式估價？","opts":["以原規定之法定容積進行估價","以原規定法定容積的上限進行估價","以實際建築使用部分之現況進行估價","以實際建築使用合法部分之現況估價"],"ok":[3],"ex":["「以原規定之法定容積進行估價」未反映實際合法建築使用現況，與規則規定不符。","「以原規定法定容積的上限進行估價」同樣未反映實際合法使用現況，與規則規定不符。","「以實際建築使用部分之現況進行估價」未排除違章建築部分，與規則規定僅就「合法部分」估價之原則不符。","技術規則明定實際建築使用之容積率超過法定容積率之房地估價，應以實際建築使用合法部分之現況估價，並敘明法定容積對估值之影響，與題目敘述完全相符。"],"tr":"","core":["法定容積未反映合法使用現況","法定容積上限亦未反映合法現況","未排除違建，應僅就合法部分估價","以實際建築使用合法部分現況估價"],"hl":[["以原規定之法定容積","實際合法建築使用現況"],["法定容積的上限","實際合法使用現況"],["實際建築使用部分","僅就「合法部分」估價"],[]]},{"id":"h:111-15","p":"h","src":"111年第15題","sec":"C2","stem":"某建物於五年前取得使用執照，目前重建成本1,000萬元，殘餘價格率5%，經濟耐用年數50年，請問以定額法估算之建物成本價格為何？","opts":["850萬元","865萬元","895萬元","905萬元"],"ok":[3],"ex":["850萬元無法由題幹常見誤算得到；正確為1,000－1,000×(1－5%)÷50×5＝905萬元。","865萬元無法由題幹常見誤算得到；正確為1,000－1,000×(1－5%)÷50×5＝905萬元。","895萬元＝1,000－1,000×(1＋5%)÷50×5，誤把殘餘價格率加上去；正確為905萬元。","年折舊額＝1,000×(1-5%)÷50＝19萬元；累積折舊額（5年）＝19×5＝95萬元；建物成本價格＝1,000－95＝905萬元，與本選項相符。"],"tr":"","core":["非常見誤算，正確為905萬","非常見誤算，正確為905萬","誤把殘價率加上，正確905萬","1,000－19×5＝905萬"],"hl":[["850萬元","正確為1,000－1,000×(1－5%)÷50×5＝905萬元"],["865萬元","正確為1,000－1,000×(1－5%)÷50×5＝905萬元"],["895萬元","誤把殘餘價格率加上去"],[]]},{"id":"h:111-23","p":"h","src":"111年第23題","sec":"C2","stem":"某甲有一棟5層透天住宅，其中第一層到第四層為合法建築物，頂樓層為違章建築物，某甲委託估價人員進行房地估價，並要求估價人員對所有樓層進行估價，估價人員應如何估價較為恰當？","opts":["僅針對合法建築物進行估價","拒絕對建築物估價","就合法建築物與違章建築物分別標示各該部分之價格","合法建築物以成本法估價，違章建築物則以加速折舊方式估價"],"ok":[2],"ex":["「僅針對合法建築物進行估價」未回應委託人對違章建築部分估價之要求，技術規則允許委託人要求評估違建部分。","技術規則並未規定遇有違章建築即應拒絕估價，仍可依規定方式進行估價，本選項過於消極。","技術規則明定附有違章建築之房地估價，違建部分不予以評估，但委託人要求評估其價值者，應就合法建物及違建部分分別標示各該部分之價格，本題某甲明確要求對所有樓層進行估價，符合此例外情形，與題目敘述相符。","技術規則並未規定違章建築部分應以「加速折舊方式」估價，這並非規則明定之正確估價方法，本選項屬虛構描述。"],"tr":"","core":["委託人要求時可評估違建部分","未規定遇違建應拒絕估價","委託人要求則分別標示各部分價格","規則未定違建以加速折舊估價"],"hl":[["僅針對合法建築物","技術規則允許委託人要求評估違建部分"],["拒絕對建築物估價","仍可依規定方式進行估價"],[],["以加速折舊方式"]]},{"id":"h:112-7","p":"h","src":"112年第7題","sec":"C2","stem":"下列之建物殘餘價格率，何者符合不動產估價技術規則之規定？","opts":["20%","18%","12%","8%"],"ok":[3],"ex":["20%已超過技術規則規定建物殘餘價格率不超過10%之上限，不符合規定。","18%同樣已超過10%上限，不符合規定。","12%同樣已超過10%上限，不符合規定。","技術規則明定建物殘餘價格率以不超過10%為原則，8%未超過此上限，符合規定，與本選項相符。"],"tr":"","core":["20%超過10%上限","18%超過10%上限","12%超過10%上限","8%未超過10%上限，符合規定"],"hl":[["20%","建物殘餘價格率不超過10%之上限"],["18%","已超過10%上限"],["12%","已超過10%上限"],[]]},{"id":"h:113-20","p":"h","src":"113年第20題","sec":"C2","stem":"某公寓因為隔壁基地正在興建危老建案造成外牆龜裂現象，此現象屬於那一種折舊類型？","opts":["物理性折舊","功能性折舊","經濟性折舊","外部性折舊"],"ok":[0],"ex":["依教材折舊分類，隔壁基地興建危老建案施工造成的外牆龜裂，是建物本身受到外力破壞致結構受損之現象，屬於物理性折舊（自然耗損或外力破壞所致），與題目敘述相符。","功能性折舊是因技術革新、設計過時等致使建物效用衰退之折舊，與施工造成的物理性結構損害不同。","經濟性折舊是因外部環境變化（如嫌惡設施、區域衰退）致使價值減損，而非建物本身結構直接受損之物理性損害。","「外部性折舊」並非技術規則明定之正式折舊分類名稱（外部性是估價原則概念，非折舊分類）。"],"tr":"","core":["施工致外牆龜裂屬外力破壞＝物理性","功能性是設計過時，非施工損害","經濟性是外部環境變化，非結構受損","外部性折舊非正式折舊分類"],"hl":[[],["功能性折舊","因技術革新、設計過時等致使建物效用衰退之折舊"],["經濟性折舊","因外部環境變化（如嫌惡設施、區域衰退）"],["外部性折舊","外部性是估價原則概念，非折舊分類"]]},{"id":"h:113-21","p":"h","src":"113年第21題","sec":"C2","stem":"一棟屋齡30年的公寓，假設現在重建成本是3,000萬元，耐用年數為50年，殘餘價格率為10%，以定額法計算折舊的情況下，目前公寓的價值是多少？","opts":["1,620萬元","1,380萬元","1,080萬元","1,200萬元"],"ok":[1],"ex":["1,620萬元是累積折舊額（3,000×0.9÷50×30），不是扣除折舊後的公寓價值。","年折舊額＝3,000×(1-10%)÷50＝54萬元；累積折舊額（30年）＝54×30＝1,620萬元；公寓現值＝3,000－1,620＝1,380萬元，與本選項相符。","1,080萬元＝3,000×(1－10%)×(1－30/50)，把(1－殘餘價格率)乘到整個現值上；正確為1,380萬元。","1,200萬元＝3,000×(1－30/50)，沒有扣除殘餘價格率（折舊多算）；正確為1,380萬元。"],"tr":"","core":["1,620萬是累積折舊額，非現值","3,000－54×30＝1,380萬","(1－s)乘到整個現值的誤算","未扣殘價率，折舊多算"],"hl":[["1,620萬元","1,620萬元是累積折舊額"],[],["1,080萬元","把(1－殘餘價格率)乘到整個現值上"],["1,200萬元","沒有扣除殘餘價格率"]]},{"id":"h:114-3","p":"h","src":"114年第3題","sec":"C2","stem":"建築物屋齡10年，重建成本2,000萬元，若殘價率為10%，經濟耐用年數50年，選擇等速折舊路徑的方法計算累積折舊額為多少萬元？","opts":["400","40","360","36"],"ok":[2],"ex":["400萬元的計算未正確扣除殘餘價格率10%之影響，直接以重建成本÷耐用年數×經歷年數計算。","40萬元＝2,000÷50，是沒有扣除殘餘價格率10%的單一年度折舊額（正確的單年折舊額是36萬），也不是10年累積值。","年折舊額＝2,000×(1-10%)÷50＝36萬元；累積折舊額（10年）＝36×10＝360萬元，與本選項相符。","36萬元僅為單一年度之折舊額，並非累積10年之折舊額。"],"tr":"","core":["未扣殘價率10%的誤算","2,000÷50是未扣殘價的單年額","年折舊36萬×10年＝360萬","36萬僅單年折舊額，非10年累積"],"hl":[["400","未正確扣除殘餘價格率10%之影響"],["40","是沒有扣除殘餘價格率10%的單一年度折舊額"],[],["36","僅為單一年度之折舊額"]]},{"id":"h:114-11","p":"h","src":"114年第11題","sec":"C2","stem":"下列有關成本法之敘述何者正確？","opts":["建物估價以求取重置成本為原則","預售收入之資金應計息","建物折舊額計算應以物理耐用年數為主","建物之殘餘價格率以不超過百分之十為原則"],"ok":[3],"ex":["建物估價以求取「重建成本」（而非重置成本）為原則，重置成本是建材無生產或施工方法改變時之例外替代成本，本選項與規則規定相反。","§59 規定預售收入之資金不計息，故本選項「預售收入之資金應計息」敘述錯誤。","建物折舊額計算應以「經濟」耐用年數（而非物理耐用年數）為主，本選項與規則規定相反。","技術規則明定建物之殘餘價格率以不超過10%為原則，與題目敘述完全相符。"],"tr":"","core":["建物以求重建成本為原則，非重置","預售收入之資金不計息","應以經濟耐用年數為主，非物理","殘餘價格率以不超過10%為原則"],"hl":[["重置成本","「重建成本」（而非重置成本）為原則"],["應計息","預售收入之資金不計息"],["物理耐用年數為主","「經濟」耐用年數（而非物理耐用年數）為主"],[]]},{"id":"h:99-31","p":"h","src":"99年第31題","sec":"D1","stem":"應用收益法進行不動產估價時，勘估標的總費用之計算，不包括下列何種項目？","opts":["地價稅","房屋稅","所得稅","建物之折舊提存費"],"ok":[2],"ex":["地價稅是技術規則明定總費用應包括之成本項目之一，非本題答案（本題問「不包括」之項目）。","房屋稅是技術規則明定總費用應包括之成本項目之一。","所得稅是收益取得後之稅務負擔，並非經營不動產所需投入之客觀成本，§38 僅列舉總費用包括之項目（地價稅或地租、房屋稅、保險費、管理費及維修費等），所得稅不在其內，依教材／實務說法不計入總費用，即本題正解。","建物之折舊提存費是技術規則明定總費用應包括之成本項目之一（反映建物隨時間損耗之經濟成本）。"],"tr":"","core":["地價稅屬總費用應含項目","房屋稅屬總費用應含項目","所得稅是收益後稅負，不計入總費用","折舊提存費屬總費用應含項目"],"hl":[[],[],["所得稅","不計入總費用"],[]]},{"id":"h:99-35","p":"h","src":"99年第35題","sec":"D1","stem":"下列有關收益法之敘述，何者有誤？","opts":["有效總收入減總費用即為淨收益","營運性不動產之總費用應加計營運費用","勘估標的包含建物時，不應加計建物之折舊提存費","應蒐集勘估標的及與其特性相同或相似之比較標的最近三年間總收入、總費用及收益資本化率或折現率等資料"],"ok":[2],"ex":["有效總收入減總費用即為淨收益，此為正確之收益法基本計算公式，非本題答案（本題問「何者有誤」）。","營運性不動產之總費用應加計營運費用，此為正確敘述。","技術規則明定勘估標的包含建物時，應加計建物之折舊提存費（反映建物隨時間損耗之經濟成本），本選項稱「不應加計」，與規則規定相反，敘述錯誤，即本題正解。","應蒐集勘估標的及比較標的最近三年間總收入、總費用及收益資本化率或折現率等資料，此為正確敘述。"],"tr":"","core":["有效總收入－總費用＝淨收益","營運性不動產總費用應加計營運費用","含建物時應加計折舊提存費","應蒐集最近三年收支及資本化率資料"],"hl":[[],[],["不應加計","應加計建物之折舊提存費"],[]]},{"id":"h:100-20","p":"h","src":"100年第20題","sec":"D1","stem":"有一土地平均每年之淨收益為50萬元整，而土地的資本化率皆為年利率5%，請問該土地之價格？","opts":["2,100萬元","900萬元","1,000萬元","1,800萬元"],"ok":[2],"ex":["2,100萬元無法由題幹常見誤算得到；正確為50萬÷5%＝1,000萬元（§30）。","900萬元無法由題幹常見誤算得到；正確為50萬÷5%＝1,000萬元（§30）。","直接資本化法公式：收益價格＝淨收益÷收益資本化率＝50萬元÷5%＝1,000萬元，與本選項相符。","1,800萬元無法由題幹常見誤算得到；正確為50萬÷5%＝1,000萬元（§30）。"],"tr":"","core":["非常見誤算，50萬÷5%＝1,000萬","非常見誤算，50萬÷5%＝1,000萬","50萬÷5%＝1,000萬","非常見誤算，50萬÷5%＝1,000萬"],"hl":[["2,100萬元","50萬÷5%＝1,000萬元"],["900萬元","50萬÷5%＝1,000萬元"],[],["1,800萬元","50萬÷5%＝1,000萬元"]]},{"id":"h:100-23","p":"h","src":"100年第23題","sec":"D1","stem":"某店面每月租金8萬元，押金為3個月租金額，銀行定存年利率3%，空置損失約占總收入之8%，該不動產之有效總收入為：","opts":["88.98萬元／年","96萬元／年","96.72萬元／年","120萬元／年"],"ok":[0],"ex":["年租金收入＝8萬×12＝96萬元；押金運用收益＝(8×3)萬×3%＝0.72萬元；總收入（實質租金）＝96＋0.72＝96.72萬元；有效總收入＝96.72×(1-8%)＝88.9824萬元，約88.98萬元，與本選項相符。","96萬元僅為未計入押金收益與空置損失之單純年租金收入，並非有效總收入。","96.72萬元是總收入（實質租金），尚未扣除空置損失8%，並非有效總收入。","120萬元＝8萬×(12＋3)，把押金本金24萬元當成收入加進去；押金只能計入它的運用收益（24萬×3%＝0.72萬元），而且還沒扣空置損失。"],"tr":"","core":["總收入96.72萬扣空置8%≈88.98萬","96萬僅年租金，未計押金收益與空置","96.72萬是總收入，未扣空置8%","誤把押金本金加入，僅計運用收益"],"hl":[[],["96萬元","未計入押金收益與空置損失之單純年租金收入"],["96.72萬元","尚未扣除空置損失8%"],["120萬元","押金只能計入它的運用收益（24萬×3%＝0.72萬元）"]]},{"id":"h:100-25","p":"h","src":"100年第25題","sec":"D1","stem":"下列何者不宜列入收益法中總費用之項目？","opts":["地租","貸款利息","保險費","維修費"],"ok":[1],"ex":["地租是技術規則明定總費用應計入之項目之一（土地承租成本），非本題答案（本題問「不宜列入」之項目）。","§38 列舉之總費用項目不含貸款利息，依教材／實務說法貸款利息（債務利息）不計入總費用，因其屬於融資結構之財務成本，而非經營不動產本身所需投入之客觀營運成本，與題目敘述相符，即本題正解。","保險費是技術規則明定總費用應計入之項目之一。","維修費是技術規則明定總費用應計入之項目之一。"],"tr":"","core":["地租屬總費用應計項目","貸款利息屬融資成本，不計總費用","保險費屬總費用應計項目","維修費屬總費用應計項目"],"hl":[[],["貸款利息","不計入總費用"],[],[]]},{"id":"h:100-27","p":"h","src":"100年第27題","sec":"D1","stem":"對具永續性固定收益之土地，以直接資本化法評估其價值，如於第0年年初評得其價值為A、第5年年初評得其價值為B，則兩者關係如何？","opts":["A＞B","A＝B","A＜B","不一定"],"ok":[1],"ex":["對具永續性固定收益之土地，因收益恆定且資本化率不變，依直接資本化法公式（價值＝固定淨收益÷資本化率），不同年份評估之價值應相等，並非A大於B。","由於該土地收益具永續性且固定，資本化率亦不變，依公式價值＝淨收益÷資本化率，第0年與第5年評估之價值理論上應相等（A＝B），與本選項相符。","同A選項說明，並非A小於B。","在收益與資本化率皆固定不變的前提下，價值關係是確定的（A＝B），並非「不一定」。"],"tr":"","core":["收益與資本化率固定，價值應相等","固定淨收益÷固定資本化率，A＝B","價值應相等，非A小於B","前提固定時價值確定相等"],"hl":[["A＞B","不同年份評估之價值應相等"],[],["A＜B"],["不一定","價值關係是確定的（A＝B）"]]},{"id":"h:100-31","p":"h","src":"100年第31題","sec":"D1","stem":"應用直接資本化法推算不動產淨收益時，下列那些項目不應列入費用項？①地價稅及房屋稅　②房屋貸款的利息　③改良性資本支出　④土地增值稅　⑤租金收入所產生的所得稅","opts":["②③⑤","③④⑤","②③④⑤","①②③④⑤"],"ok":[2],"ex":["②③⑤只漏了④土地增值稅（處分時的稅負，不是經營成本，依教材也不列入總費用），所以不完整；①地價稅、房屋稅本來就應列入總費用（§38），不選它是對的。","③④⑤組合遺漏②房屋貸款利息，不完整。","§38 僅列舉總費用包括之項目；依教材／實務說法，總費用不應列入：②房屋貸款利息（融資財務成本）、③改良性資本支出（資本性支出非經常性費用）、④土地增值稅（處分稅負非經營成本）、⑤租金收入所產生之所得稅（收益稅負非經營成本），與本選項②③④⑤完全相符，①地價稅及房屋稅則應列入費用項，不應排除。","①②③④⑤全選，但①地價稅及房屋稅是應列入費用項之正常項目，不應與其他應排除項目併列。"],"tr":"","core":["漏了④土地增值稅，不完整","漏了②房屋貸款利息，不完整","貸款利息、資本支出、增值稅、所得稅皆不列","①地價稅房屋稅應列入費用"],"hl":[["②③⑤","只漏了④土地增值稅"],["③④⑤","遺漏②房屋貸款利息"],[],["①②③④⑤","①地價稅及房屋稅是應列入費用項之正常項目"]]},{"id":"h:101-31","p":"h","src":"101年第31題","sec":"D1","stem":"以收益為目的而出租之不動產在進行不動產估價時，何者應列入總費用，加以扣除？","opts":["抵押債務利息","租賃所得稅","維護修繕費","自有資本之利息"],"ok":[2],"ex":["抵押債務利息屬於融資財務成本，§38 列舉之總費用項目不含此項，依教材／實務說法不列入總費用。","租賃所得稅是收益取得後之稅務負擔，§38 列舉之總費用項目不含此項，依教材／實務說法不列入總費用。","技術規則明定維護修繕費是經營不動產所需投入之客觀營運成本，應列入總費用加以扣除，與題目敘述相符。","自有資本之利息是業主資金成本之概念，非經營不動產所需投入之客觀營運成本，不應列入總費用。"],"tr":"","core":["抵押債務利息屬融資成本，不列入","租賃所得稅屬收益後稅負，不列入","維護修繕費屬客觀營運成本，應列入","自有資本利息非客觀營運成本"],"hl":[["抵押債務利息","不列入總費用"],["租賃所得稅","不列入總費用"],[],["自有資本之利息","不應列入總費用"]]},{"id":"h:101-37","p":"h","src":"101年第37題","sec":"D1","stem":"以收益法估價時，對於折舊前及折舊後的純收益，使用資本化率還原，應如何處理？","opts":["折舊前的純收益，應僅以資本化率還原","折舊後的純收益，應僅以資本化率還原","折舊後的純收益，應以資本化率加折舊率還原","折舊前的純收益，應僅以折舊率加以還原"],"ok":[1],"ex":["折舊「前」的純收益應以「資本化率加折舊提存率」還原，而非僅以資本化率還原，本選項與規則規定相反。","技術規則明定折舊後的純收益，僅須以收益資本化率還原即可（因折舊已從淨收益中扣除），與題目敘述相符。","折舊「後」的純收益僅需以資本化率還原即可，不需另加折舊率，本選項多加了折舊率，敘述錯誤。","折舊前的純收益應以資本化率「加」折舊率還原（而非僅以折舊率還原），本選項遺漏資本化率部分，敘述錯誤。"],"tr":"","core":["折舊前應以資本化率加折舊提存率還原","折舊後純收益僅以資本化率還原","折舊後不需另加折舊率","折舊前應資本化率加折舊率，非僅折舊率"],"hl":[["僅以資本化率還原","資本化率加折舊提存率"],[],["資本化率加折舊率","僅需以資本化率還原即可"],["僅以折舊率","應以資本化率「加」折舊率還原"]]},{"id":"h:101-39","p":"h","src":"101年第39題","sec":"D1","stem":"乙將房屋出租與丙，每月租金10,000元，押金30,000元，押金利率為1％，若該區房屋空置率為25％，則乙出租房屋的年有效總收入為：","opts":["120,000元","95,000元","90,300元","90,000元"],"ok":[2],"ex":["120,000元僅為單純年租金收入，未考量押金運用收益與空置率之影響。","95,000元無法由題幹常見誤算得到（就算押金收益也一併扣空置，也只得120,300×75%＝90,225元）；正確為120,000×(1－25%)＋30,000×1%＝90,300元。","年租金收入＝10,000×12＝120,000元；空置率影響租金部分＝120,000×(1-25%)＝90,000元；押金運用收益＝30,000×1%＝300元（本題官方答案只對租金部分扣空置；若押金收益也一併扣空置＝120,300×75%＝90,225，不在選項內。注意 100-23 的官方答案則是押金收益也一併扣空置，兩題處理不同，依選項判斷）；有效總收入＝90,000＋300＝90,300元，與本選項相符。","90,000元僅計入扣除空置率後之租金收入，漏未加計押金運用收益300元。"],"tr":"","core":["120,000僅年租金，未計押金與空置","非常見誤算，正確為90,300元","租金扣空置90,000＋押金收益300","漏加押金運用收益300元"],"hl":[["120,000元","未考量押金運用收益與空置率之影響"],["95,000元","120,000×(1－25%)＋30,000×1%＝90,300元"],[],["90,000元","漏未加計押金運用收益300元"]]},{"id":"h:102-9","p":"h","src":"102年第9題","sec":"D1","stem":"依不動產估價技術規則規定，收益法估價程序有六個項目如下：①計算收益價格　②推算有效總收入　③蒐集總收入、總費用及收益資本化率或折現率等資料　④推算總費用　⑤計算淨收益　⑥決定收益資本化率或折現率。其估價步驟順序以下何者正確？","opts":["⑤③①⑥④②","②①⑤⑥④③","⑥④③①⑤②","③②④⑤⑥①"],"ok":[3],"ex":["⑤③①⑥④②此排列順序將①計算收益價格置於過早位置，與正確的「先蒐集資料，最後才計算收益價格」之邏輯不符。","②①⑤⑥④③此排列順序將②推算有效總收入置於最前面，未先蒐集資料（③），順序錯誤。","⑥④③①⑤②此排列順序將⑥決定收益資本化率置於最前面，但決定資本化率應在推算淨收益之後，順序錯誤。","技術規則明定收益法估價程序為：③蒐集總收入總費用及收益資本化率等資料→②推算有效總收入→④推算總費用→⑤計算淨收益→⑥決定收益資本化率→①計算收益價格，與本選項③②④⑤⑥①完全相符。"],"tr":"","core":["①計算收益價格應在最後","未先蒐集資料③，順序錯誤","資本化率應在淨收益之後決定","③②④⑤⑥①：先蒐集資料，最後算價格"],"hl":[["⑤③①⑥④②","先蒐集資料，最後才計算收益價格"],["②①⑤⑥④③","未先蒐集資料（③）"],["⑥④③①⑤②","決定資本化率應在推算淨收益之後"],[]]},{"id":"h:102-10","p":"h","src":"102年第10題","sec":"D1","stem":"不動產估價收益法之總費用估算項目，不包含下列何者？","opts":["地價稅或地租","房屋稅","所得稅","維修費"],"ok":[2],"ex":["地價稅或地租是技術規則明定總費用應計入之項目之一，非本題答案（本題問「不包含」之項目）。","房屋稅是技術規則明定總費用應計入之項目之一。","所得稅是收益取得後之稅務負擔，§38 列舉之總費用項目不含此項，依教材／實務說法不計入總費用，即本題正解。","維修費是技術規則明定總費用應計入之項目之一。"],"tr":"","core":["地價稅或地租屬總費用項目","房屋稅屬總費用項目","所得稅是收益後稅負，不計總費用","維修費屬總費用項目"],"hl":[[],[],["所得稅","不計入總費用"],[]]},{"id":"h:102-12","p":"h","src":"102年第12題","sec":"D1","stem":"若某不動產之建物經濟耐用年數50年、經歷年數20年、殘價率10%，於收益法估價時，建物價格日期當時價值未來每年折舊提存率為何？","opts":["0.018","0.036","0.05","0.028"],"ok":[3],"ex":["0.018只是折舊率(1－s)/N＝0.9/50，不是§41的折舊提存率。","0.036無法由題幹常見誤算得到；正確d＝0.018÷(1－0.9×20/50)＝0.018÷0.64≈0.028（§41）。","0.05＝1÷20，是拿經歷年數直接倒數，跟§41公式無關。","§41 等速折舊型 d＝[(1－s)/N]÷[1－(1－s)×n/N]＝0.018÷[1－0.9×20/50]＝0.018÷0.64≈0.028，與考選部標準答案 D 一致。"],"tr":"","core":["0.018只是折舊率，非折舊提存率","非常見誤算，正確≈0.028","1÷20經歷年數倒數，與公式無關","0.018÷0.64≈0.028"],"hl":[["0.018","不是§41的折舊提存率"],["0.036","0.018÷(1－0.9×20/50)＝0.018÷0.64≈0.028"],["0.05","拿經歷年數直接倒數"],[]]},{"id":"h:102-13","p":"h","src":"102年第13題","sec":"D1","stem":"土地徵收補償估價時，因無買賣實例而採徵收區段內透天租賃實例，如折舊前房地淨收益每年新臺幣25萬元、建物價格日期當時價值未來每年折舊提存率2.5%、建物淨收益推算為每年新臺幣10萬元、土地收益資本化率3%，則土地收益價格為新臺幣多少萬元？","opts":["500萬元","833萬元","455萬元","273萬元"],"ok":[0],"ex":["土地淨收益＝折舊前房地淨收益－建物淨收益＝25－10＝15萬元；土地收益價格＝15÷3%（土地收益資本化率）＝500萬元（§44Ⅰ②）。題目給的建物淨收益 10 萬元，應與「折舊前」房地淨收益同口徑，即建物折舊前淨收益＝建物成本價格×(建物收益資本化率＋折舊提存率)（§44Ⅱ②），所以 2.5% 已含在那 10 萬元裡；土地不折舊，分母只用土地收益資本化率，不加 2.5%。","833萬元＝25÷3%，把整筆房地淨收益都當成土地淨收益，漏扣建物淨收益10萬元。","455萬元＝25÷(3%＋2.5%)，錯在把房地淨收益直接用「土地資本化率＋折舊提存率」還原，沒先扣建物淨收益。","273萬元＝15÷(3%＋2.5%)，土地淨收益算對了，卻多加了建物的折舊提存率；土地收益價格只除以土地收益資本化率3%（§44）。"],"tr":"","core":["(25－10)÷3%＝500萬","25÷3%漏扣建物淨收益10萬","未先扣建物淨收益又加提存率","土地不加折舊提存率，只除3%"],"hl":[[],["833萬元","漏扣建物淨收益10萬元"],["455萬元","沒先扣建物淨收益"],["273萬元","土地收益價格只除以土地收益資本化率3%"]]},{"id":"h:103-18","p":"h","src":"103年第18題","sec":"D1","stem":"下列有關收益法之敘述，何者有誤？","opts":["保險費可計入總費用之推算","地價稅或地租可計入總費用之推算","營運性不動產者，不可加計營運費用","有效總收入減總費用即為淨收益"],"ok":[2],"ex":["保險費可計入總費用之推算，此為正確敘述，非本題答案（本題問「何者有誤」）。","地價稅或地租可計入總費用之推算，此為正確敘述。","技術規則明定營運性不動產者，「應」加計營運費用（而非不可加計），本選項與規則規定相反，敘述錯誤，即本題正解。","有效總收入減總費用即為淨收益，此為正確之基本計算公式。"],"tr":"","core":["保險費可計入總費用","地價稅或地租可計入總費用","營運性不動產應加計營運費用","有效總收入－總費用＝淨收益"],"hl":[[],[],["不可加計","「應」加計營運費用"],[]]},{"id":"h:103-28","p":"h","src":"103年第28題","sec":"D1","stem":"依不動產估價技術規則規定，於收益法之建物折舊提存費，得依下列何種方式計算？①等速折舊型②初期減速折舊型③初期加速折舊型④償債基金型","opts":["①④","②③","①②③","①②③④"],"ok":[0],"ex":["§40-1 明定建物折舊提存費得依①等速折舊型：C×(1－s)×(1/N)、④償債基金型：C×(1－s)×i÷[(1＋i)^N－1] 兩種方式計算（§41 的折舊提存率 d 也是這兩型），與本選項①④相符。","②初期減速、③初期加速是成本法計算累積折舊額時可選的「折舊路徑」（§68Ⅰ：等速、初期加速、初期減速），不是收益法折舊提存費的計算方式；§40-1 只有等速折舊型與償債基金型。","①②③混入成本法 §68 的兩種路徑（初期減速、初期加速），又漏了 §40-1 的④償債基金型。","①②③④全選，把成本法 §68 的折舊路徑（②③）也算進來；收益法折舊提存費依 §40-1 只有①等速折舊型、④償債基金型。"],"tr":"","core":["折舊提存費只有等速折舊型與償債基金型","初期減速、加速是成本法折舊路徑","混入成本法路徑，又漏了④償債基金型","②③屬成本法路徑，不應全選"],"hl":[[],["②③","§40-1 只有等速折舊型與償債基金型"],["①②③","漏了 §40-1 的④償債基金型"],["①②③④","只有①等速折舊型、④償債基金型"]]},{"id":"h:103-40","p":"h","src":"103年第40題","sec":"D1","stem":"運用收益法進行不動產估價時，下列何者可列入費用項目估計？","opts":["改良性資本支出","保險費","貸款債務利息","所得稅"],"ok":[1],"ex":["改良性資本支出屬於資本性支出（增加資產價值之投資），非經常性營運成本，§38 列舉之總費用項目不含此項，依教材／實務說法不列入總費用。","技術規則明定保險費是經營不動產所需投入之客觀營運成本，應列入總費用，與題目敘述相符。","貸款債務利息屬於融資財務成本，§38 列舉之總費用項目不含此項，依教材／實務說法不列入總費用。","所得稅是收益取得後之稅務負擔，§38 列舉之總費用項目不含此項，依教材／實務說法不列入總費用。"],"tr":"","core":["改良性資本支出屬資本性支出，不列入","保險費屬客觀營運成本，應列總費用","貸款債務利息屬融資成本，不列入","所得稅屬收益後稅負，不列入"],"hl":[["改良性資本支出","不列入總費用"],[],["貸款債務利息","不列入總費用"],["所得稅","不列入總費用"]]},{"id":"h:104-14","p":"h","src":"104年第14題","sec":"D1","stem":"某不動產之總收益為200萬元，若總費用為總收益的30%，資本化率為5%，則該不動產之純收益應為多少？","opts":["60萬元","70萬元","130萬元","140萬元"],"ok":[3],"ex":["60萬元是總費用（200×30%）本身，不是純收益。","70萬元無法由題幹常見誤算得到（數值上等於用35%算）；正確為200－60＝140萬元。","130萬元無法由題幹常見誤算得到（數值上等於用35%算）；正確為200－60＝140萬元。","總費用＝200萬元×30%＝60萬元；純收益＝總收益－總費用＝200萬元－60萬元＝140萬元，與本選項相符（注意：本題已知資本化率5%是用於其他延伸計算之資訊，求純收益本身僅需總收益減總費用即可，無需使用資本化率）。"],"tr":"","core":["60萬是總費用本身，非純收益","非常見誤算，正確為200－60＝140萬","非常見誤算，正確為200－60＝140萬","200－60＝140萬，不需資本化率"],"hl":[["60萬元","是總費用（200×30%）本身"],["70萬元","200－60＝140萬元"],["130萬元","200－60＝140萬元"],[]]},{"id":"h:104-15","p":"h","src":"104年第15題","sec":"D1","stem":"下列有關直接資本化法計算收益價格公式之敘述，何者正確？","opts":["勘估標的未來平均一年期間之客觀總收益×收益資本化率","勘估標的未來平均一年期間之客觀總收益÷收益資本化率","勘估標的過去平均一年期間之客觀總收益×收益資本化率","勘估標的過去平均一年期間之客觀總收益÷收益資本化率"],"ok":[1],"ex":["收益價格是收益「除以」資本化率，不是乘。","官方答案B。直接資本化法看「未來」平均一年期間的收益，並以「除以」收益資本化率求價格，四個選項中只有B同時符合。（§30條文用的是「客觀淨收益」，本題選項都寫總收益，比較時抓「未來」和「÷」兩個關鍵。）","看的是「過去」收益，又用乘法，兩處都錯。","看的是「過去」收益，直接資本化法要用「未來」平均一年期間的收益。"],"tr":"","core":["收益價格是除以資本化率，不是乘","未來平均一年收益÷收益資本化率","過去收益又用乘法，兩處都錯","應用未來收益，非過去平均一年"],"hl":[["×收益資本化率","收益「除以」資本化率"],[],["過去"],["過去","要用「未來」平均一年期間的收益"]]},{"id":"h:104-16","p":"h","src":"104年第16題","sec":"D1","stem":"下列有關收益法估價程序的排列，何者正確？①計算淨收益　②推算總費用　③計算收益價格　④推算有效總收入　⑤決定收益資本化率　⑥蒐集收入、費用及資本化率等資料","opts":["⑤⑥①②④③","⑤⑥④②①③","⑥④②①⑤③","⑥⑤②①④③"],"ok":[2],"ex":["⑤⑥①②④③此排列順序中，①計算淨收益置於②推算總費用之前，順序錯誤（應先推算總費用才能計算淨收益）。","⑤⑥④②①③此排列順序將⑤決定收益資本化率置於最前面，但決定資本化率應在計算淨收益之後，順序錯誤。","技術規則明定收益法估價程序為：⑥蒐集收入費用及資本化率等資料→④推算有效總收入→②推算總費用→①計算淨收益→⑤決定收益資本化率→③計算收益價格，與本選項⑥④②①⑤③完全相符。","⑥⑤②①④③此排列順序將⑤決定收益資本化率置於④推算有效總收入之前，順序錯誤（應先推算總收入及費用、計算淨收益後才決定資本化率）。"],"tr":"","core":["淨收益應在推算總費用之後","決定資本化率應在淨收益之後","⑥④②①⑤③：先蒐集資料，最後算價格","資本化率應在總收入與淨收益之後"],"hl":[["⑤⑥①②④③","應先推算總費用才能計算淨收益"],["⑤⑥④②①③","決定資本化率應在計算淨收益之後"],[],["⑥⑤②①④③","應先推算總收入及費用、計算淨收益後才決定資本化率"]]},{"id":"h:105-19","p":"h","src":"105年第19題","sec":"D1","stem":"有關直接資本化法的敘述，下列何者錯誤？","opts":["直接資本化法所求得之價格為收益價格","指勘估標的過去平均一年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法","直接資本化法之收益資本化率可由加權平均資金成本法求取","直接資本化法之客觀淨收益應以勘估標的作最有效使用之客觀淨收益為基準，並參酌鄰近類似不動產在最有效使用情況下之收益推算之"],"ok":[1],"ex":["技術規則明定直接資本化法所求得之價格即為收益價格，此為正確敘述，非本題答案（本題問「何者錯誤」）。","技術規則明定直接資本化法係指勘估標的「未來」（而非過去）平均一年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法，本選項將「未來」誤植為「過去」，敘述錯誤，即本題正解。","直接資本化法之收益資本化率可由加權平均資金成本法（WACC）求取，此為正確敘述（WACC是技術規則明定的資本化率決定方法之一）。","直接資本化法之客觀淨收益應以勘估標的作最有效使用之客觀淨收益為基準，並參酌鄰近類似不動產在最有效使用情況下之收益推算之，此為正確敘述。"],"tr":"","core":["直接資本化法所求價格即收益價格","應為未來平均一年，非過去","資本化率可由加權平均資金成本法求","淨收益以最有效使用之客觀淨收益為準"],"hl":[[],["過去","勘估標的「未來」"],[],[]]},{"id":"h:105-34","p":"h","src":"105年第34題","sec":"D1","stem":"應用直接資本化法進行不動產估價時，勘估標的總費用計算，不包括下列何者？","opts":["地價稅","房屋稅","管理費","土地增值稅"],"ok":[3],"ex":["地價稅是技術規則明定總費用應計入之項目之一，非本題答案（本題問「不包括」之項目）。","房屋稅是技術規則明定總費用應計入之項目之一。","管理費是技術規則明定總費用應計入之項目之一。","土地增值稅是處分不動產時之稅務負擔，§38 列舉之總費用項目不含此項，依教材／實務說法不計入經營期間之總費用，即本題正解。"],"tr":"","core":["地價稅屬總費用應計項目","房屋稅屬總費用應計項目","管理費屬總費用應計項目","土地增值稅是處分稅負，不計總費用"],"hl":[[],[],[],["土地增值稅","不計入經營期間之總費用"]]},{"id":"h:106-6","p":"h","src":"106年第6題","sec":"D1","stem":"某出租型不動產之年總收益為100萬元，若總費用率為總收益的40%，收益資本化率4%，則該不動產之收益價格應為多少？","opts":["1,000萬元","1,200萬元","1,500萬元","2,500萬元"],"ok":[2],"ex":["1,000萬元＝40÷4%，是把總費用當成淨收益去資本化。","1,200萬元無法由題幹常見誤算得到；正確為(100－40)÷4%＝1,500萬元。","總費用＝100萬元×40%＝40萬元；淨收益＝100萬元－40萬元＝60萬元；收益價格＝淨收益÷收益資本化率＝60萬元÷4%＝1,500萬元，與本選項相符。","2,500萬元＝100÷4%，沒扣總費用。"],"tr":"","core":["40÷4%是把總費用當淨收益","非常見誤算，正確為1,500萬","(100－40)÷4%＝1,500萬","100÷4%沒扣總費用"],"hl":[["1,000萬元","把總費用當成淨收益去資本化"],["1,200萬元","(100－40)÷4%＝1,500萬元"],[],["2,500萬元","沒扣總費用"]]},{"id":"h:106-8","p":"h","src":"106年第8題","sec":"D1","stem":"關於不動產估價收益法之總費用估算項目，下列何者正確？","opts":["只能算地價稅，如地上權地租不能算","房屋稅只適用於保存登記之建物","所得稅亦應計算","維修費、保險費亦應計算"],"ok":[3],"ex":["技術規則並未規定地租不可計算（地租同樣是總費用應計入之項目，地上權之地租與地價稅性質相當，皆應列入），本選項描述過於武斷。","房屋稅之計算與是否完成保存登記無直接關連（未保存登記建物之房屋稅仍可能依現值課徵），本選項描述不符技術規則或稅法常理。","所得稅是收益取得後之稅務負擔，§38 列舉之總費用項目不含所得稅，依教材／實務說法不計入總費用，本選項與此相反。","技術規則明定維修費、保險費皆是經營不動產所需投入之客觀營運成本，應計入總費用，與題目敘述相符。"],"tr":"","core":["地租同屬總費用，非不能算","房屋稅與是否保存登記無直接關連","所得稅不計入總費用","維修費、保險費屬營運成本，應計入"],"hl":[["如地上權地租不能算","地租同樣是總費用應計入之項目"],["只適用於保存登記之建物","與是否完成保存登記無直接關連"],["所得稅亦應計算","不計入總費用"],[]]},{"id":"h:106-11","p":"h","src":"106年第11題","sec":"D1","stem":"若某房屋經濟耐用年數45年、經歷年數20年、殘餘價格率10%，於收益法估價時，等速折舊型，建物價格日期當時價值未來每年折舊提存率為何？","opts":["0.02","0.05","0.03","0.033"],"ok":[3],"ex":["0.02只是(1－s)÷N＝0.9÷45，是「新建時」的年折舊率，沒有換算成價格日期當時價值的提存率。","0.05＝1÷20（經歷年數直接倒數），跟§41公式無關。","0.03無法由題幹常見誤算得到（正解0.0333截到小數兩位才會是0.03，跟正解選項0.033不同）。","依§41等速折舊型：d＝[(1－s)÷N]÷[1－(1－s)×n÷N]＝(0.9÷45)÷(1－0.9×20÷45)＝0.02÷0.6≈0.033，與本選項相符。"],"tr":"","core":["0.02只是新建時年折舊率，非提存率","1÷20經歷年數倒數，與公式無關","非常見誤算，正解為0.033","0.02÷0.6≈0.033"],"hl":[["0.02","沒有換算成價格日期當時價值的提存率"],["0.05","經歷年數直接倒數"],["0.03"],[]]},{"id":"h:107-2","p":"h","src":"107年第2題","sec":"D1","stem":"有關勘估標的總費用之推算項目，不包括下列那一項？","opts":["管理費及維修費","地價稅或地租、房屋稅","保險費","貸款利息"],"ok":[3],"ex":["管理費及維修費是技術規則明定總費用應推算之項目之一，非本題答案（本題問「不包括」之項目）。","地價稅或地租、房屋稅是技術規則明定總費用應推算之項目之一。","保險費是技術規則明定總費用應推算之項目之一。","貸款利息屬於融資財務成本，§38 列舉之總費用項目不含貸款利息（屬教材／實務之排除項），即本題正解。"],"tr":"","core":["管理費及維修費屬總費用項目","地價稅或地租、房屋稅屬總費用項目","保險費屬總費用項目","貸款利息屬融資成本，不列總費用"],"hl":[[],[],[],["貸款利息","屬於融資財務成本"]]},{"id":"h:107-7","p":"h","src":"107年第7題","sec":"D1","stem":"收益法估價應蒐集勘估標的及與其特性相同或相似之比較標的最近幾年間總收入、總費用及收益資本化率或折現率等資料？","opts":["2年","3年","4年","5年"],"ok":[1],"ex":["2年並非技術規則規定之蒐集資料年限。","技術規則明定收益法估價應蒐集勘估標的及比較標的最近3年間總收入、總費用及收益資本化率或折現率等資料，與題目敘述相符。","4年並非技術規則規定之蒐集資料年限。","5年並非技術規則規定之蒐集資料年限。"],"tr":"","core":["蒐集年限是3年，不是2年","應蒐集最近3年收支及資本化率資料","蒐集年限是3年，不是4年","蒐集年限是3年，不是5年"],"hl":[["2年"],[],["4年"],["5年"]]},{"id":"h:107-19","p":"h","src":"107年第19題","sec":"D1","stem":"依不動產估價技術規則之規定，下列收益法之估價步驟中，何種排列次序較為正確？①計算淨收益　②推算總費用　③決定收益資本化率或折現率　④推算有效總收入　⑤蒐集總收入、總費用及收益資本化率或折現率等資料　⑥計算收益價格","opts":["①⑤②③④⑥","⑤①②④③⑥","⑤④①②⑥③","⑤④②①③⑥"],"ok":[3],"ex":["①⑤②③④⑥此排列順序將①計算淨收益置於最前面，但計算淨收益應在蒐集資料、推算總收入總費用之後，順序錯誤。","⑤①②④③⑥此排列順序將①計算淨收益置於④推算有效總收入之前，順序錯誤（應先推算總收入才能計算淨收益）。","⑤④①②⑥③此排列順序將⑥計算收益價格置於③決定收益資本化率之前，順序顛倒（應先決定資本化率才能計算收益價格）。","技術規則明定收益法估價程序為：⑤蒐集總收入總費用及收益資本化率或折現率等資料→④推算有效總收入→②推算總費用→①計算淨收益→③決定收益資本化率或折現率→⑥計算收益價格，與本選項⑤④②①③⑥完全相符。"],"tr":"","core":["淨收益不能排第一，應在收支推算後","淨收益應在推算有效總收入之後","應先決定資本化率再算收益價格","⑤④②①③⑥：先蒐集資料，最後算價格"],"hl":[["①⑤②③④⑥","計算淨收益應在蒐集資料、推算總收入總費用之後"],["⑤①②④③⑥","應先推算總收入才能計算淨收益"],["⑤④①②⑥③","應先決定資本化率才能計算收益價格"],[]]},{"id":"h:108-11","p":"h","src":"108年第11題","sec":"D1","stem":"下列敘述何者為正確？建物價格日期當時價值未來每年折舊提存率，得依下列方式計算：等速折舊型與償債基金型公式；建物折舊提存費，得依等速折舊型與償債基金型公式計算；不動產構成項目中於耐用年數內需重置部分之重置提撥費，按其利息及按該支出之有效使用年期及耗損比率分年攤提；勘估標的總費用之推算，除推算勘估標的之各項費用外，勘估標的包含建物者，應加計建物之折舊提存費，或於計算收益價格時，除考量建物收益資本化率或折現率外，應加計建物價格日期當時價值未來每年折舊提存率","opts":["（原試題公式選項因OCR辨識排版錯亂，無法準確呈現）","（原試題公式選項因OCR辨識排版錯亂，無法準確呈現）","（原試題公式選項因OCR辨識排版錯亂，無法準確呈現）","（原試題公式選項因OCR辨識排版錯亂，無法準確呈現）"],"ok":[0],"ex":["本題原始試題選項因PDF文件OCR辨識排版錯亂，無法準確呈現各選項完整公式內容，故略過逐選項解析。","同上，選項內容無法辨識。","同上，選項內容無法辨識。","本題考選部一律給分；可對照的地方是：重置提撥費依§39只「按該支出之有效使用年期及耗損比率分年攤提」，條文沒有「按其利息」。相關條文：§39、§40、§40-1、§41。"],"tr":"","core":["原題選項排版錯亂，略過逐選項解析","選項內容無法辨識","選項內容無法辨識","重置提撥費條文無「按其利息」"]},{"id":"h:108-14","p":"h","src":"108年第14題","sec":"D1","stem":"推算總收入及有效總收入時，應與相關資料校核比較，下列何者非屬該相關資料？","opts":["目前或未來可能之計畫收入","相同產業或具替代性比較標的總收入及有效總收入","期末價值","勘估標的往年之總收入及有效總收入"],"ok":[2],"ex":["目前或未來可能之計畫收入是推算總收入時應與相關資料校核比較之項目之一，非本題答案（本題問「非屬」相關資料）。","相同產業或具替代性比較標的總收入及有效總收入是應校核比較之項目之一。","技術規則明定推算總收入及有效總收入時應校核比較之相關資料，並不包含「期末價值」（期末價值是DCF折現現金流量分析法中之概念，與直接資本化法之總收入推算無關），即本題正解。","勘估標的往年之總收入及有效總收入是應校核比較之項目之一。"],"tr":"","core":["計畫收入屬應校核比較之資料","比較標的收入屬應校核比較之資料","期末價值屬DCF概念，非校核資料","往年收入屬應校核比較之資料"],"hl":[[],[],["期末價值","期末價值是DCF折現現金流量分析法中之概念"],[]]},{"id":"h:108-17","p":"h","src":"108年第17題","sec":"D1","stem":"有關直接資本化法，下列敘述何者為正確？","opts":["指勘估標的過去平均一年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法","指勘估標的過去平均三年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法","指勘估標的未來平均一年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法","指勘估標的未來平均三年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法"],"ok":[2],"ex":["「過去平均一年期間」與技術規則規定的「未來平均一年期間」方向相反，敘述錯誤。","「過去平均三年期間」同時時間方向與期間長度皆與規則規定不符。","技術規則明定直接資本化法係指勘估標的「未來平均一年期間」之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法，與題目敘述完全相符。","「未來平均三年期間」期間長度與規則規定的一年期間不符。"],"tr":"","core":["應為未來平均一年，非過去","應為未來一年，時間方向與期間皆錯","未來平均一年客觀淨收益÷資本化率","期間應為一年，非三年"],"hl":[["過去平均一年","未來平均一年期間"],["過去平均三年"],[],["未來平均三年","規則規定的一年期間"]]},{"id":"h:109-9","p":"h","src":"109年第9題","sec":"D1","stem":"勘估標的為辦公大樓之第10層，建物登記面積50坪，每月每坪正常租金收入為2,000元，該建物大樓經合理市場分析推算空置率為5%，勘估標的每年地價稅、房屋稅及保險費等相關總費用推算為200,000元。請問該建物以直接資本化法估價時，推算其有效總收入為多少？","opts":["940,000元","1,000,000元","1,140,000元","1,200,000元"],"ok":[2],"ex":["940,000元＝1,140,000－200,000，是再扣掉總費用後的淨收益，不是有效總收入。","1,000,000元＝1,200,000－200,000，是沒扣空置損失、卻先扣了總費用的結果；總費用不是計算有效總收入的減項。","年租金總收入＝50坪×2,000元/坪/月×12月＝1,200,000元；有效總收入＝1,200,000×(1-5%)＝1,140,000元，與本選項相符。地價稅房屋稅保險費等屬於總費用項目，非計算有效總收入之減項。","1,200,000元僅為未扣除空置率之單純年租金總收入，並非有效總收入。"],"tr":"","core":["940,000是再扣總費用後的淨收益","先扣總費用又沒扣空置，非有效總收入","總收入扣空置5%＝1,140,000","1,200,000未扣空置，非有效總收入"],"hl":[["940,000元","是再扣掉總費用後的淨收益"],["1,000,000元","總費用不是計算有效總收入的減項"],[],["1,200,000元","未扣除空置率之單純年租金總收入"]]},{"id":"h:109-11","p":"h","src":"109年第11題","sec":"D1","stem":"以下直接資本化法之定義敘述，何者為正確？","opts":["係指勘估標的未來平均1年期間之客觀淨收益，應用調查日期當時適當之收益資本化率推算勘估標的價格之方法","係指勘估標的未來平均1年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法","係指比較標的未來平均1年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法","係指比較標的未來平均3年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法"],"ok":[1],"ex":["技術規則明定應用「價格日期」（而非調查日期）當時適當之收益資本化率，本選項用詞誤植。","技術規則明定直接資本化法係指「勘估標的」未來平均1年期間之客觀淨收益，應用價格日期當時適當之收益資本化率推算勘估標的價格之方法，與題目敘述完全相符。","規則明定計算之基準是「勘估標的」之客觀淨收益（而非比較標的），本選項主體誤植。","規則明定期間為「未來平均1年」（而非3年），且基準應為勘估標的（而非比較標的），本選項雙重錯誤。"],"tr":"","core":["應用價格日期，非調查日期","勘估標的未來1年淨收益，價格日期資本化率","基準是勘估標的，非比較標的","應為勘估標的、未來1年，雙重錯誤"],"hl":[["調查日期","「價格日期」"],[],["比較標的","計算之基準是「勘估標的」"],["比較標的","3年","期間為「未來平均1年」"]]},{"id":"h:109-15","p":"h","src":"109年第15題","sec":"D1","stem":"估價人員應用收益法估價時，若某建物經濟耐用年數45年、經歷年數10年、殘價率10%，當採取等速折舊型時，建物價格日期當時價值未來每年折舊提存率為何？","opts":["2%","2.25%","2.5%","3%"],"ok":[2],"ex":["2%只是(1－s)÷N＝0.9÷45，是新建時的年折舊率，沒有換算成價格日期當時價值的提存率。","2.25%無法由題幹常見誤算得到；正確為0.02÷(1－0.9×10/45)＝0.02÷0.8＝2.5%（§41）。","依§41等速折舊型：d＝[(1－s)÷N]÷[1－(1－s)×n÷N]＝0.02÷(1－0.9×10÷45)＝0.02÷0.8＝2.5%，與本選項相符。","3%無法由題幹常見誤算得到；正確為0.02÷(1－0.9×10/45)＝0.02÷0.8＝2.5%（§41）。"],"tr":"","core":["2%只是新建時年折舊率，非提存率","非常見誤算，正確為2.5%","0.02÷0.8＝2.5%","非常見誤算，正確為2.5%"],"hl":[["2%","沒有換算成價格日期當時價值的提存率"],["2.25%","0.02÷(1－0.9×10/45)＝0.02÷0.8＝2.5%"],[],["3%","0.02÷(1－0.9×10/45)＝0.02÷0.8＝2.5%"]]},{"id":"h:110-10","p":"h","src":"110年第10題","sec":"D1","stem":"100坪之辦公室出租，每月每坪正常租金為1,000元，推估該辦公室合理空置率為8%，每年之地價稅、房屋稅、保險費、管理費及維修費為120,000元，貸款支出為200,000元。該辦公室每年之淨收益為多少？","opts":["1,080,000元","984,000元","880,000元","784,000元"],"ok":[1],"ex":["1,080,000元＝1,200,000－120,000，總費用扣對了，但漏扣8%空置損失。","年租金總收入＝100坪×1,000元/坪/月×12月＝1,200,000元；有效總收入＝1,200,000×(1-8%)＝1,104,000元；淨收益＝有效總收入－總費用（地價稅房屋稅保險費管理費維修費）120,000元＝1,104,000－120,000＝984,000元；貸款支出200,000元屬融資財務成本，依教材／實務說法不計入總費用扣除，與本選項相符。","880,000元＝1,200,000－120,000－200,000，既沒扣空置損失8%，又誤將貸款支出200,000元一併扣除。","784,000元＝1,104,000－120,000－200,000，空置與總費用都算對，只錯在把貸款支出200,000元也扣掉（貸款支出不是總費用）。"],"tr":"","core":["漏扣8%空置損失","沒扣空置又誤扣貸款支出","有效總收入－總費用＝984,000","貸款支出非總費用，不應扣除"],"hl":[["1,080,000元","漏扣8%空置損失"],[],["880,000元","誤將貸款支出200,000元一併扣除"],["784,000元","只錯在把貸款支出200,000元也扣掉"]]},{"id":"h:110-20","p":"h","src":"110年第20題","sec":"D1","stem":"某房地之淨收益100萬元/年，其中建物淨收益60萬元/年。假設土地、建物之收益資本化率分別為2%、4%，請問土地收益價格為？","opts":["1,000萬元","2,000萬元","2,500萬元","5,000萬元"],"ok":[1],"ex":["1,000萬元＝40÷4%，土地淨收益算對了，但誤用建物資本化率4%；土地收益價格應除以土地收益資本化率2%。","土地淨收益＝房地淨收益－建物淨收益＝100萬元－60萬元＝40萬元；土地收益價格＝土地淨收益÷土地收益資本化率＝40萬元÷2%＝2,000萬元，與本選項相符。","2,500萬元＝100÷4%，錯在用房地淨收益除以建物資本化率，既沒扣建物淨收益，也用錯了資本化率。","5,000萬元＝100÷2%，是沒有先扣除建物淨收益60萬元、直接用房地淨收益除以土地資本化率的結果。"],"tr":"","core":["土地應除以土地資本化率2%，非4%","(100－60)÷2%＝2,000萬","沒扣建物淨收益又用錯資本化率","100÷2%未先扣建物淨收益60萬"],"hl":[["1,000萬元","誤用建物資本化率4%"],[],["2,500萬元","用錯了資本化率"],["5,000萬元","沒有先扣除建物淨收益60萬元"]]},{"id":"h:111-19","p":"h","src":"111年第19題","sec":"D1","stem":"以收益法估價時，對於客觀淨收益的計算應以何種情形為計算基準？","opts":["以比較標的作最有效使用為計算基準","以勘估標的作最大效益使用為計算基準","以比較標的作最大效益使用為計算基準","以勘估標的作最有效使用為計算基準"],"ok":[3],"ex":["技術規則明定客觀淨收益之計算基準是「勘估標的」（而非比較標的）作最有效使用，本選項主體誤植。","技術規則明定基準是「最有效使用」（而非最大效益使用），本選項用詞誤植（雖意涵相近，但規則明確使用「最有效使用」此一專有名詞）。","本選項同時將主體誤植為比較標的、用詞誤植為最大效益使用，雙重錯誤。","技術規則明定客觀淨收益之評估，應以勘估標的作最有效使用之客觀淨收益為基準，與題目敘述完全相符。"],"tr":"","core":["基準是勘估標的，非比較標的","規則用語是最有效使用，非最大效益","主體與用語皆誤植，雙重錯誤","以勘估標的最有效使用為基準"],"hl":[["比較標的","計算基準是「勘估標的」"],["最大效益使用","基準是「最有效使用」"],["比較標的","最大效益使用"],[]]},{"id":"h:112-8","p":"h","src":"112年第8題","sec":"D1","stem":"有一不動產平均每年每坪之淨收益為3,000元，若收益資本化率為5%，該不動產每坪之收益價格為：","opts":["8萬元","7萬元","6萬元","5萬元"],"ok":[2],"ex":["8萬元無法由題幹常見誤算得到；正確為3,000÷5%＝60,000元（§30）。","7萬元無法由題幹常見誤算得到；正確為3,000÷5%＝60,000元（§30）。","依直接資本化法公式：每坪收益價格＝每坪淨收益÷收益資本化率＝3,000元÷5%＝60,000元＝6萬元，與本選項相符。","5萬元無法由題幹常見誤算得到；正確為3,000÷5%＝60,000元（§30）。"],"tr":"","core":["非常見誤算，3,000÷5%＝6萬","非常見誤算，3,000÷5%＝6萬","3,000÷5%＝60,000元＝6萬","非常見誤算，3,000÷5%＝6萬"],"hl":[["8萬元","3,000÷5%＝60,000元"],["7萬元","3,000÷5%＝60,000元"],[],["5萬元","3,000÷5%＝60,000元"]]},{"id":"h:112-9","p":"h","src":"112年第9題","sec":"D1","stem":"下列何者不是收益法推算勘估標的總費用之項目？","opts":["地價稅","房屋稅","土地增值稅","維修費"],"ok":[2],"ex":["地價稅是技術規則明定收益法總費用應計入之項目之一，非本題答案（本題問「不是」總費用項目）。","房屋稅是技術規則明定收益法總費用應計入之項目之一。","土地增值稅是處分不動產時之稅務負擔，§38 列舉之總費用項目不含此項，依教材／實務說法不計入經營期間之總費用，即本題正解。","維修費是技術規則明定收益法總費用應計入之項目之一。"],"tr":"","core":["地價稅屬總費用應計項目","房屋稅屬總費用應計項目","土地增值稅是處分稅負，不計總費用","維修費屬總費用應計項目"],"hl":[[],[],["土地增值稅","不計入經營期間之總費用"],[]]},{"id":"h:113-12","p":"h","src":"113年第12題","sec":"D1","stem":"下列對於有效總收入與總收入之間關係的敘述何者正確？","opts":["總收入必定大於或等於有效總收入","有效總收入與總收入只是說法上不同，兩者在實質的意義上一樣","總收入減去總費用等於淨收益","總收入＝有效總收入＋總費用"],"ok":[0],"ex":["技術規則§36明定有效總收入＝總收入扣除閒置及其他原因所造成之收入損失，該損失不為負值，故總收入必定大於或等於有效總收入，與題目敘述完全相符。","有效總收入與總收入是「不同」概念（有效總收入是總收入扣除空置損失後之結果），並非說法上不同但意義相同，本選項描述錯誤。","總收入減去總費用並不等於淨收益，正確公式應為「有效總收入減去總費用」才等於淨收益，本選項用詞誤植，混淆了總收入與有效總收入。","正確關係是「總收入＝有效總收入＋閒置及其他原因所造成之收入損失」（§36），不是加總費用；總費用是有效總收入的減項，用來求淨收益（§42）。"],"tr":"","core":["空置等損失不為負，總收入≥有效總收入","兩者不同，有效總收入已扣空置損失","應是有效總收入減總費用才是淨收益","總收入＝有效總收入＋收入損失"],"hl":[[],["兩者在實質的意義上一樣","有效總收入是總收入扣除空置損失後之結果"],["總收入減去總費用","「有效總收入減去總費用」"],["有效總收入＋總費用","總收入＝有效總收入＋閒置及其他原因所造成之收入損失"]]},{"id":"h:113-14","p":"h","src":"113年第14題","sec":"D1","stem":"有關收益法的公式，下列何者錯誤？","opts":["淨收益未扣除折舊提存費者，建物收益價格＝建物淨收益／建物收益資本化率","直接資本化法之收益價格＝勘估標的未來平均一年期間之客觀淨收益／收益資本化率","地上有建物者，土地收益價格＝（房地淨收益－建物淨收益）／土地收益資本化率","淨收益已扣除折舊提存費者，房地綜合收益資本化率＝土地收益資本化率×土地價值比率＋建物收益資本化率×建物價值比率"],"ok":[0],"ex":["技術規則明定淨收益「未扣除」折舊提存費者，建物收益價格應以「建物收益資本化率＋折舊提存率」（而非僅以收益資本化率）還原，本選項公式遺漏折舊提存率，敘述錯誤，即本題正解。","直接資本化法之收益價格＝未來平均一年期間之客觀淨收益÷收益資本化率，此為正確之基本公式。","地上有建物者，土地收益價格＝(房地淨收益－建物淨收益)÷土地收益資本化率，此為正確之公式。","淨收益已扣除折舊提存費者，房地綜合收益資本化率＝土地收益資本化率×土地價值比率＋建物收益資本化率×建物價值比率，此為正確之加權平均公式。"],"tr":"","core":["未扣折舊提存費應加折舊提存率還原","收益價格＝未來一年客觀淨收益÷資本化率","土地價格＝(房地－建物淨收益)÷土地率","已扣提存費者，依價值比率加權平均"],"hl":[["建物淨收益／建物收益資本化率","建物收益資本化率＋折舊提存率"],[],[],[]]},{"id":"h:114-10","p":"h","src":"114年第10題","sec":"D1","stem":"下列有關直接資本化法之敘述何者正確？","opts":["屬於比較法之一種","應以勘估標的作最合理使用之客觀淨收益為基準","應用價格日期當時適當之收益資本化率推算","計算過程應另加計期末價值"],"ok":[2],"ex":["直接資本化法屬於「收益法」之一種（非比較法），收益法是以未來收益折現或資本化求取價格，與比較法（以交易實例為基礎）性質不同，本選項分類錯誤。","技術規則明定應以勘估標的作「最有效使用」（而非最合理使用）之客觀淨收益為基準，本選項用詞誤植，規則使用之專有名詞為最有效使用。","技術規則明定直接資本化法應用「價格日期」當時適當之收益資本化率推算勘估標的價格，與題目敘述完全相符。","直接資本化法「不」考慮期末處分價值（這是DCF折現現金流量分析法才會加計期末處分價值之特徵），本選項與直接資本化法之定義不符。"],"tr":"","core":["直接資本化法屬收益法，非比較法","規則用語是最有效使用，非最合理","應用價格日期當時適當之資本化率","期末價值是DCF特徵，直接資本化法不加"],"hl":[["比較法","屬於「收益法」之一種"],["最合理使用","作「最有效使用」"],[],["另加計期末價值","「不」考慮期末處分價值"]]},{"id":"h:99-9","p":"h","src":"99年第9題","sec":"D2","stem":"如果有一個不動產每年可以獲得的淨收益是10萬元，該不動產之建築物興建成本是100萬，根據調查，該不動產的土地部分之資本化率是5%，建物部分之資本化率是1%，請問該不動產的價格是多少呢？","opts":["100萬","130萬","160萬","190萬"],"ok":[1],"ex":["本題一律給分；照收益分離法算：建物淨收益＝100×1%＝1萬，土地淨收益＝10－1＝9萬，土地價格＝9÷5%＝180萬，房地合計280萬元，四個選項都不是這個數，這可能就是一律給分的原因。","考選部《測驗題標準答案更正》：99 年不動產估價概要第 9 題「一律給分」（答案欄標 #）。原公告答案為 B（130萬元），已被更正；本題每個選項都算對，不計入正確率判讀。","本題一律給分（見選項A說明：依收益分離法算得280萬元，不在選項中）。","本題一律給分（見選項A說明：依收益分離法算得280萬元，不在選項中）。"],"tr":"","core":["本題一律給分，依算法得280萬","本題一律給分，原答案130萬已更正","本題一律給分，算得280萬不在選項","本題一律給分，算得280萬不在選項"]},{"id":"h:100-24","p":"h","src":"100年第24題","sec":"D2","stem":"某一不動產之土地價格為600萬元，建築物價格為400萬元，已知土地之個別資本化率為5%，建築物之個別資本化率為8%，請問該不動產之綜合資本化率為：","opts":["13%","3%","6.2%","7.2%"],"ok":[2],"ex":["13%的計算誤將土地與建物資本化率直接相加（5%+8%），未依價值比例加權平均，計算方式錯誤。","3%＝5%×60%，只算了土地部分，漏加建物部分8%×40%＝3.2%。","綜合資本化率＝土地資本化率×(土地價值÷總價值)＋建物資本化率×(建物價值÷總價值)＝5%×(600/1000)＋8%×(400/1000)＝3%＋3.2%＝6.2%，與本選項相符。","7.2%無法由題幹常見誤算得到（權重對調算出來是6.8%）。"],"tr":"","core":["誤將兩率直接相加，未依價值加權","只算土地部分，漏加建物3.2%","5%×60%＋8%×40%＝6.2%","非常見誤算，權重對調也只得6.8%"],"hl":[["13%","未依價值比例加權平均"],["3%","漏加建物部分8%×40%＝3.2%"],[],["7.2%"]]},{"id":"h:100-28","p":"h","src":"100年第28題","sec":"D2","stem":"直接資本化法之資本化率為下列何者間關係？","opts":["自有資金與貸款額","有效收益與價值","毛收益與價值","淨收益與價值"],"ok":[3],"ex":["「自有資金與貸款額」之關係是融資結構之概念，並非直接資本化法資本化率之定義。","「有效收益與價值」之關係並非資本化率之精確定義，資本化率應為「淨收益」而非「有效收益」與價值之關係。","「毛收益與價值」之關係同樣並非資本化率之精確定義，毛收益尚未扣除費用，與淨收益不同。","技術規則明定直接資本化法之收益價格＝淨收益÷收益資本化率，故資本化率即為「淨收益與價值」之關係（淨收益除以價值），與題目敘述相符。"],"tr":"","core":["自有資金與貸款屬融資結構概念","應為淨收益，非有效收益","毛收益未扣費用，非淨收益","資本化率＝淨收益與價值的關係"],"hl":[["自有資金與貸款額"],["有效收益","資本化率應為「淨收益」"],["毛收益","與淨收益不同"],[]]},{"id":"h:100-36","p":"h","src":"100年第36題","sec":"D2","stem":"應用直接資本化法估價時，已知獲利率為5%、收益年增率為2%，則直接資本化率應採下列何者較佳？","opts":["7%","5%","3%","2%"],"ok":[2],"ex":["7%的計算誤將獲利率與收益年增率相加，與正確之資本化率調整邏輯相反。","5%僅為原始獲利率本身，未考量收益年增率之調整。","依資本化率與成長率關係之概念，直接資本化率應為獲利率扣除收益年增率（因未來收益持續成長，當期資本化率應相對較低以反映未來成長潛力）＝5%－2%＝3%，與本選項相符。","2%僅為收益年增率本身，並非正確之資本化率調整結果。"],"tr":"","core":["誤將年增率加上，方向相反","5%僅原始獲利率，未扣收益年增率","獲利率5%－收益年增率2%＝3%","2%僅收益年增率本身"],"hl":[["7%"],["5%","未考量收益年增率之調整"],[],["2%"]]},{"id":"h:102-11","p":"h","src":"102年第11題","sec":"D2","stem":"收益資本化率之擇定如採風險溢酬法，下列敘述何者錯誤？","opts":["應考慮銀行定期存款利率、政府公債利率、不動產投資之風險性、貨幣變動狀況及不動產價格之變動趨勢等因素","選擇最具特殊性財貨之投資報酬率為基準","比較觀察該投資財貨與勘估標的個別特性之差異","需就流通性、風險性、增值性及管理上之難易程度等因素加以比較決定之"],"ok":[1],"ex":["風險溢酬法應考慮銀行定期存款利率、政府公債利率、不動產投資之風險性、貨幣變動狀況及不動產價格之變動趨勢等因素，此為正確敘述，非本題答案（本題問「何者錯誤」）。","技術規則明定風險溢酬法應選擇最具「一般性」財貨（而非特殊性財貨）之投資報酬率為基準，本選項將一般性誤植為特殊性，敘述錯誤，即本題正解。","比較觀察該投資財貨與勘估標的個別特性之差異，是風險溢酬法正確之操作程序，敘述正確。","需就流通性、風險性、增值性及管理上之難易程度等因素加以比較決定之，此為正確敘述。"],"tr":"","core":["應考慮定存公債利率、風險等因素","應選最具一般性財貨，非特殊性","比較投資財貨與標的個別特性差異","就流通性風險性增值性等比較決定"],"hl":[[],["特殊性","最具「一般性」財貨"],[],[]]},{"id":"h:104-17","p":"h","src":"104年第17題","sec":"D2","stem":"下列有關收益資本化率決定之敘述，何者正確？","opts":["依加權平均資金成本方式決定之方法謂之市場萃取法","有效總收入乘數法之公式為：淨收益率÷有效總收入乘數","債務保障比率法之公式為：債務保障比率×貸款常數÷貸款資金占不動產價格比率","選擇數個與勘估標的相同或相似之比較標的，以其淨收益除以價格後，以所得之商數加以比較決定之方法謂之風險溢酬法"],"ok":[1],"ex":["依加權平均資金成本方式決定之方法稱為「加權平均資金成本法（WACC）」，並非市場萃取法，本選項方法名稱誤植。","技術規則明定有效總收入乘數法之公式為：收益資本化率＝淨收益率÷有效總收入乘數，與本選項完全相符。","技術規則明定債務保障比率法之公式為：收益資本化率＝債務保障比率×貸款常數×貸款資金占不動產價格比率（為「乘以」而非「除以」貸款資金占比），本選項運算符號誤植，敘述錯誤。","選擇數個比較標的以淨收益除以價格之商數比較決定資本化率之方法，稱為「市場萃取法」，並非風險溢酬法，本選項方法名稱誤植。"],"tr":"","core":["加權平均資金成本方式稱WACC法","資本化率＝淨收益率÷有效總收入乘數","貸款資金占比應相乘，非相除","淨收益÷價格比較是市場萃取法"],"hl":[["市場萃取法","稱為「加權平均資金成本法（WACC）」"],[],["÷貸款資金占不動產價格比率","債務保障比率×貸款常數×貸款資金占不動產價格比率"],["風險溢酬法","稱為「市場萃取法」"]]},{"id":"h:104-37","p":"h","src":"104年第37題","sec":"D2","stem":"當比較標的收益價格為500萬元，勘估標的收益價格為800萬元，比較標的未來平均一年期間之客觀淨收益為48萬元，勘估標的未來平均一年期間之客觀淨收益為40萬元，此時其收益資本化率為何？","opts":["5%","6%","8%","9.6%"],"ok":[0],"ex":["題目問的是勘估標的的收益資本化率：40÷800＝5%，與本選項相符。","6%＝48÷800，錯把比較標的的淨收益除以勘估標的的收益價格。","8%＝40÷500，錯把勘估標的的淨收益除以比較標的的收益價格。","9.6%是比較標的的資本化率（48÷500），題目問的是勘估標的。"],"tr":"","core":["勘估標的40÷800＝5%","48÷800錯用比較標的淨收益","40÷500錯用比較標的收益價格","9.6%是比較標的資本化率"],"hl":[[],["6%","錯把比較標的的淨收益除以勘估標的的收益價格"],["8%","錯把勘估標的的淨收益除以比較標的的收益價格"],["9.6%","題目問的是勘估標的"]]},{"id":"h:104-39","p":"h","src":"104年第39題","sec":"D2","stem":"當債務保障比率為1.3，貸款常數為0.1，貸款以外的資金占不動產價格比率為40%時，請問此時收益資本化率為何？","opts":["3.1%","5.2%","6.5%","7.8%"],"ok":[3],"ex":["3.1%≈0.1×40%÷1.3，債務保障比率用除、貸款占比也用錯。","5.2%＝1.3×0.1×40%，錯把「貸款以外資金」比率40%當成貸款資金占比，應該用60%。","6.5%無法由題幹常見誤算得到；正確為1.3×0.1×60%＝7.8%（§43第4款）。","貸款資金占不動產價格比率＝1－貸款以外資金占比＝1－40%＝60%；依債務保障比率法公式：收益資本化率＝債務保障比率×貸款常數×貸款資金占比＝1.3×0.1×60%＝7.8%，與本選項相符。"],"tr":"","core":["保障比率用除、貸款占比也用錯","40%是貸款以外資金，應用60%","非常見誤算，正確為7.8%","1.3×0.1×(1－40%)＝7.8%"],"hl":[["3.1%","債務保障比率用除、貸款占比也用錯"],["5.2%","應該用60%"],["6.5%","1.3×0.1×60%＝7.8%"],[]]},{"id":"h:105-15","p":"h","src":"105年第15題","sec":"D2","stem":"收益資本化率或折現率之計算中，選擇數個與勘估標的相同或相似之比較標的，以其淨收益除以價格後，以所得之商數加以比較決定之方法，為下列何者？","opts":["風險溢酬法","市場萃取法","加權平均資金成本法","有效總收入乘數法"],"ok":[1],"ex":["風險溢酬法是以一般性財貨投資報酬率為基準並考量風險溢酬調整之方法，與題目所述「以淨收益除以價格之商數比較決定」之操作方式不同。","技術規則明定市場萃取法係選擇數個與勘估標的相同或相似之比較標的，以其淨收益除以價格後，以所得之商數加以比較決定之方法，與題目敘述完全相符。","加權平均資金成本法是以自有資金與借貸資金之比重及各自報酬率加權計算，與題目所述淨收益除以價格之操作方式不同。","有效總收入乘數法是以淨收益率除以有效總收入乘數計算，與題目所述直接以淨收益除以價格之操作方式不同。"],"tr":"","core":["風險溢酬法以一般性財貨報酬為基準","市場萃取法＝比較標的淨收益÷價格","WACC是資金比重加權，非淨收益÷價格","乘數法是淨收益率÷乘數，非直接相除"],"hl":[["風險溢酬法","以一般性財貨投資報酬率為基準並考量風險溢酬調整之方法"],[],["加權平均資金成本法","以自有資金與借貸資金之比重及各自報酬率加權計算"],["有效總收入乘數法","以淨收益率除以有效總收入乘數計算"]]},{"id":"h:106-10","p":"h","src":"106年第10題","sec":"D2","stem":"「考慮銀行定期存款利率、政府公債利率、不動產投資之風險性、貨幣變動狀況及不動產價格之變動趨勢等因素，選擇最具一般性財貨之投資報酬率為基準，比較觀察該投資財貨與勘估標的個別特性之差異，並就流通性、風險性、增值性及管理上之難易程度等因素加以比較決定之。」係指收益資本化率何種方式？","opts":["債務保障比率法","風險溢酬法","市場萃取法","有效總收入乘數法"],"ok":[1],"ex":["債務保障比率法是以債務保障比率乘以貸款常數及貸款資金占比計算，與題目所述「考慮銀行定存利率公債利率等因素並比較流通性風險性等」之操作方式不同。","技術規則明定風險溢酬法係考慮銀行定期存款利率、政府公債利率、不動產投資之風險性、貨幣變動狀況及不動產價格之變動趨勢等因素，選擇最具一般性財貨之投資報酬率為基準，比較觀察該投資財貨與勘估標的個別特性之差異，並就流通性、風險性、增值性及管理上之難易程度等因素加以比較決定之，與題目敘述完全相符。","市場萃取法是直接以比較標的淨收益除以價格之商數決定，與題目所述風險溢酬調整之操作方式不同。","有效總收入乘數法是以淨收益率除以有效總收入乘數計算，與題目所述操作方式不同。"],"tr":"","core":["債務保障比率法是比率×常數×占比","風險溢酬法＝一般性財貨報酬加以比較","市場萃取法是淨收益÷價格商數","乘數法是淨收益率÷有效總收入乘數"],"hl":[["債務保障比率法","以債務保障比率乘以貸款常數及貸款資金占比計算"],[],["市場萃取法","直接以比較標的淨收益除以價格之商數決定"],["有效總收入乘數法","以淨收益率除以有效總收入乘數計算"]]},{"id":"h:106-29","p":"h","src":"106年第29題","sec":"D2","stem":"某一不動產每年營業淨收益60萬元，貸款成數80%，貸款利率5%，貸款年數20年，債權保障比率1.5，若以這些條件計算下之不動產價格應為：","opts":["404萬元","631萬元","909萬元","1,420萬元"],"ok":[1],"ex":["404萬元＝60÷(1.5×0.0792÷0.8)：把貸款成數 0.8 當成除數。正確是三個數相乘：r＝1.5×0.0792×0.8≈9.5%，價格＝60÷r≈631萬元。","①先求貸款常數＝每年要還的本利÷借的本金。題目沒給，只給利率5%、20年，要用本利均等攤還自己算：按月攤還(0.05/12)÷[1－(1＋0.05/12)⁻²⁴⁰]×12≈0.0792（按年攤還5%÷[1－1.05⁻²⁰]≈0.0802）。②r＝債務保障比率×貸款常數×貸款成數＝1.5×0.0792×0.8≈9.5%（§43第4款；貸款成數就是條文的「貸款資金占不動產價格比率」，乘的順序不影響）。③價格＝淨收益÷r＝60÷9.5%≈631萬元，與本選項相符（按年攤還算得≈623萬元，四個選項仍以631最接近）。","909萬元＝60×1.5×0.8÷0.0792：把公式上下顛倒，拿淨收益去乘。正確是先求r＝1.5×0.0792×0.8≈9.5%，再用60÷r≈631萬元。","1,420萬元＝60÷(0.0792×0.8÷1.5)：把債務保障比率當除數。銀行要求的保障比率越高，r越大、價格越低，所以1.5要乘，正確r≈9.5%、價格≈631萬元。"],"tr":"","core":["誤把貸款成數當除數，正確≈631萬","r≈9.5%，價格＝60÷r≈631萬","公式上下顛倒，拿淨收益去乘","誤把保障比率當除數，應相乘"],"hl":[["404萬元","r＝1.5×0.0792×0.8≈9.5%"],[],["909萬元","r＝1.5×0.0792×0.8≈9.5%"],["1,420萬元","所以1.5要乘"]]},{"id":"h:106-32","p":"h","src":"106年第32題","sec":"D2","stem":"蒐集市場上僅有的5個交易案例之資本化率分別為10%、19%、5%、4.5%、4.9%，經估價師判斷應去掉差距過大之異常值，試問若依市場萃取法，勘估標的之資本化率應為：","opts":["3.85%","4.5%","4.8%","5.04%"],"ok":[2],"ex":["3.85%：比留下來最低的4.5%還低，三個數的平均不可能比每一個都小，一看就能刪。正確是去掉10%、19%後取平均：(5＋4.5＋4.9)÷3＝4.8%。","4.5%只是留下三個案例中最低的一個，沒有取平均。市場萃取法要把幾個案例的「淨收益÷價格」拿來比較決定（§43第2款），本題去掉異常值後取平均＝4.8%。","①先找異常值：5%、4.5%、4.9%都擠在4.5%～5%之間，10%是它們的2倍、19%將近4倍，明顯離群，就是題目說的「差距過大之異常值」。②市場萃取法依§43第2款「以其淨收益除以價格後，以所得之商數加以比較決定之」，去掉異常值後把剩下的商數平均：(5＋4.5＋4.9)÷3＝14.4÷3＝4.8%，與本選項相符。","5.04%沒有對應的常見算法（五個全部平均是(10＋19＋5＋4.5＋4.9)÷5＝8.68%，也不是5.04%）。正確是去掉10%、19%後取平均：(5＋4.5＋4.9)÷3＝4.8%。"],"tr":"","core":["低於最低的4.5%，平均不可能更小","4.5%只取最低值，沒有取平均","去掉異常值後三者平均＝4.8%","無對應算法，正確為4.8%"],"hl":[["3.85%","(5＋4.5＋4.9)÷3＝4.8%"],["4.5%","去掉異常值後取平均＝4.8%"],[],["5.04%","(5＋4.5＋4.9)÷3＝4.8%"]]},{"id":"h:107-8","p":"h","src":"107年第8題","sec":"D2","stem":"當建物價格日期當時價值未來每年折舊提存率大於零時，下列對淨收益已扣除折舊提存費之房地綜合收益資本化率與淨收益未扣除折舊提存費之房地綜合收益資本化率兩者間之敘述，何者正確？","opts":["淨收益已扣除折舊提存費之房地綜合收益資本化率高於淨收益未扣除折舊提存費之房地綜合收益資本化率","淨收益已扣除折舊提存費之房地綜合收益資本化率等於淨收益未扣除折舊提存費之房地綜合收益資本化率","淨收益已扣除折舊提存費之房地綜合收益資本化率小於淨收益未扣除折舊提存費之房地綜合收益資本化率","無法判斷"],"ok":[2],"ex":["淨收益已扣除折舊提存費之資本化率「高於」未扣除者，方向與正確答案相反。","兩者資本化率「相等」之敘述忽略了折舊提存率大於零時對房地綜合收益資本化率產生之影響差異。","當折舊提存率大於零時，淨收益已扣除折舊提存費之房地綜合收益資本化率，小於淨收益未扣除折舊提存費之房地綜合收益資本化率（因為未扣除折舊提存費之淨收益較大，但對應之不動產價值不變，根據淨收益除以價值之關係，分子較大時對應的資本化率亦較大；已扣除折舊提存費後淨收益較小，對應資本化率較小），與本選項相符。","兩者間之大小關係依折舊提存率影響邏輯是可判斷的，並非無法判斷。"],"tr":"","core":["方向相反，已扣者應較低","提存率大於零時兩者不相等","已扣提存費淨收益較小，資本化率較小","大小關係可判斷，非無法判斷"],"hl":[["高於"],["等於"],[],["無法判斷","依折舊提存率影響邏輯是可判斷的"]]},{"id":"h:107-20","p":"h","src":"107年第20題","sec":"D2","stem":"下列關於收益資本化率之敘述，何者錯誤？","opts":["增值性較高的不動產，其收益資本化率較高","流通性高的不動產，其收益資本化率較低","風險性較高的不動產，其收益資本化率較高","管理度較難的不動產，其收益資本化率較高"],"ok":[0],"ex":["依風險溢酬法之邏輯，增值性較高的不動產，因未來增值潛力高，投資人願意接受較低之當期收益報酬，其收益資本化率應「較低」（而非較高），本選項與正確關係相反，即本題正解。","流通性高的不動產，交易變現容易、風險較低，其收益資本化率較低，此為正確敘述。","風險性較高的不動產，投資人要求較高報酬以補償風險，其收益資本化率較高，此為正確敘述。","管理較難的不動產，管理成本及複雜度增加投資風險，其收益資本化率較高，此為正確敘述。"],"tr":"","core":["增值性高者資本化率應較低","流通性高、風險低，資本化率較低","風險性高要求較高報酬，資本化率高","管理較難增加風險，資本化率較高"],"hl":[["收益資本化率較高","收益資本化率應「較低」"],[],[],[]]},{"id":"h:107-21","p":"h","src":"107年第21題","sec":"D2","stem":"選擇數個與勘估標的相同或相似之比較標的，以其淨收益除以價格後，以所得之商數加以比較決定收益資本化率之方法為：","opts":["加權平均資金成本法","有效總收入乘數法","債務保障比率法","市場萃取法"],"ok":[3],"ex":["加權平均資金成本法是以自有資金與借貸資金之比重及各自報酬率加權計算，與題目所述以淨收益除以價格之商數比較決定之操作方式不同。","有效總收入乘數法是以淨收益率除以有效總收入乘數計算，與題目所述操作方式不同。","債務保障比率法是以債務保障比率乘以貸款常數及貸款資金占比計算，與題目所述操作方式不同。","技術規則明定市場萃取法係選擇數個與勘估標的相同或相似之比較標的，以其淨收益除以價格後，以所得之商數加以比較決定之方法，與題目敘述完全相符。"],"tr":"","core":["WACC是資金比重加權，非淨收益÷價格","乘數法操作方式不同","債務保障比率法是比率×常數×占比","市場萃取法＝比較標的淨收益÷價格"],"hl":[["加權平均資金成本法","以自有資金與借貸資金之比重及各自報酬率加權計算"],["有效總收入乘數法","以淨收益率除以有效總收入乘數計算"],["債務保障比率法","以債務保障比率乘以貸款常數及貸款資金占比計算"],[]]},{"id":"h:109-4","p":"h","src":"109年第4題","sec":"D2","stem":"經分析考量市場上類似不動產之正常租金為每年每坪12,000元，合理空置率為5%，淨收益率為75%，貸款資金占不動產價格比率80%，有效總收入乘數為15，請以有效總收入乘數法計算出收益資本化率為多少？","opts":["4.27%","4.67%","5.0%","5.33%"],"ok":[2],"ex":["4.27%無法由題幹常見誤算得到；正確為75%÷15＝5%（§43第5款）。","4.67%無法由題幹常見誤算得到；正確為75%÷15＝5%（§43第5款）。","依有效總收入乘數法公式：收益資本化率＝淨收益率÷有效總收入乘數＝75%÷15＝5.0%，與本選項相符。注意：題目所給「正常租金」「合理空置率」「貸款資金占比」等資料是此情境之背景資訊，核心計算僅需淨收益率與有效總收入乘數兩項數值即可。","5.33%＝80%÷15，錯把貸款資金占比80%當成淨收益率。"],"tr":"","core":["非常見誤算，正確為75%÷15＝5%","非常見誤算，正確為75%÷15＝5%","淨收益率75%÷乘數15＝5%","誤把貸款占比80%當淨收益率"],"hl":[["4.27%","正確為75%÷15＝5%"],["4.67%","正確為75%÷15＝5%"],[],["5.33%","錯把貸款資金占比80%當成淨收益率"]]},{"id":"h:109-14","p":"h","src":"109年第14題","sec":"D2","stem":"某商用不動產之自有資金要求報酬率8%、向銀行融資之利率4%，當自有資金的比重為50%，以加權平均資金成本法估算之收益法折現率為何？","opts":["4%","6%","8%","10%"],"ok":[1],"ex":["4%僅為融資利率本身，未考量自有資金與借貸資金之加權。","依加權平均資金成本法（WACC）公式：折現率＝自有資金比重×自有資金報酬率＋借貸資金比重×融資利率＝50%×8%＋50%×4%＝4%＋2%＝6%，與本選項相符。","8%僅為自有資金要求報酬率本身，未考量借貸資金之加權。","10%＝8%＋50%×4%，自有資金報酬率沒乘上權重50%；正確為50%×8%＋50%×4%＝6%（§43第3款）。"],"tr":"","core":["4%僅融資利率，未加權","50%×8%＋50%×4%＝6%","8%僅自有資金報酬率，未加權","自有資金報酬率漏乘權重50%"],"hl":[["4%","未考量自有資金與借貸資金之加權"],[],["8%","未考量借貸資金之加權"],["10%","正確為50%×8%＋50%×4%＝6%"]]},{"id":"h:110-21","p":"h","src":"110年第21題","sec":"D2","stem":"依不動產估價技術規則第43條規定，收益資本化率應考慮之因素不包括下列何者？","opts":["貨幣變動之狀況","銀行定期存款利率","不動產投資之損益","不動產價格變動趨勢"],"ok":[2],"ex":["貨幣變動之狀況是技術規則第43條明定收益資本化率應考慮之因素之一，非本題答案（本題問「不包括」之因素）。","銀行定期存款利率是技術規則明定應考慮之因素之一。","「不動產投資之損益」並非技術規則第43條明定應考慮之因素（規則明定的是「不動產投資之風險性」，而非投資損益本身），即本題正解。","不動產價格變動趨勢是技術規則明定應考慮之因素之一。"],"tr":"","core":["貨幣變動狀況屬應考慮因素","銀行定期存款利率屬應考慮因素","規定是投資風險性，非投資損益","價格變動趨勢屬應考慮因素"],"hl":[[],[],["不動產投資之損益","「不動產投資之風險性」"],[]]},{"id":"h:111-3","p":"h","src":"111年第3題","sec":"D2","stem":"收益資本化率或折現率應綜合評估最適宜之方法決定，如採用債務保障比率方式決定，其計算式債務保障比率除了乘以貸款資金占不動產價格比率外，應再乘以下列何者？","opts":["債務保障常數","市場常數","存款常數","貸款常數"],"ok":[3],"ex":["「債務保障常數」並非技術規則明定債務保障比率法計算式中所使用之正式用語。","「市場常數」並非技術規則明定債務保障比率法計算式中所使用之正式用語。","「存款常數」並非技術規則明定債務保障比率法計算式中所使用之正式用語。","技術規則明定債務保障比率法公式為：收益資本化率＝債務保障比率×貸款常數×貸款資金占不動產價格比率，與題目敘述完全相符。"],"tr":"","core":["債務保障常數非正式用語","市場常數非正式用語","存款常數非正式用語","資本化率＝保障比率×貸款常數×占比"],"hl":[["債務保障常數"],["市場常數"],["存款常數"],[]]},{"id":"h:112-14","p":"h","src":"112年第14題","sec":"D2","stem":"決定收益資本化率之方法中，選擇數個與勘估標的相同或相似之比較標的，以其淨收益除以價格後，以所得之商數加以比較決定之方法為何？","opts":["風險溢酬法","市場萃取法","債務保障比率法","折現現金流量分析法"],"ok":[1],"ex":["風險溢酬法是以一般性財貨投資報酬率為基準並考量風險溢酬調整之方法，與題目所述以淨收益除以價格之操作方式不同。","技術規則明定市場萃取法係選擇數個與勘估標的相同或相似之比較標的，以其淨收益除以價格後，以所得之商數加以比較決定之方法，與題目敘述完全相符。","債務保障比率法是以債務保障比率乘以貸款常數及貸款資金占比計算，與題目所述操作方式不同。","折現現金流量分析法（DCF）是估算多期現金流量並折現之方法，並非收益資本化率之決定方法本身，且操作方式與題目所述不同。"],"tr":"","core":["風險溢酬法以一般性財貨報酬為基準","市場萃取法＝比較標的淨收益÷價格","債務保障比率法是比率×常數×占比","DCF非資本化率之決定方法"],"hl":[["風險溢酬法","以一般性財貨投資報酬率為基準並考量風險溢酬調整之方法"],[],["債務保障比率法","以債務保障比率乘以貸款常數及貸款資金占比計算"],["折現現金流量分析法","估算多期現金流量並折現之方法"]]},{"id":"h:112-18","p":"h","src":"112年第18題","sec":"D2","stem":"當債務保障比率要求為1.5倍，貸款常數為0.1，不動產價格為新臺幣60億元，自有資金為新臺幣15億元，不足資金則跟銀行貸款。請問在前述情況下收益資本化率（折現率）為何？","opts":["15%","11.25%","5%","3.75%"],"ok":[1],"ex":["15%＝1.5×0.1，漏乘貸款資金占比75%。","貸款資金占不動產價格比率＝(不動產價格60億－自有資金15億)÷不動產價格60億＝45億÷60億＝75%；依債務保障比率法公式：收益資本化率＝債務保障比率×貸款常數×貸款資金占比＝1.5×0.1×75%＝11.25%，與本選項相符。","5%＝0.1÷1.5×75%，把債務保障比率錯當除數。","3.75%＝1.5×0.1×25%，錯用自有資金占比（15÷60）。"],"tr":"","core":["1.5×0.1漏乘貸款占比75%","1.5×0.1×75%＝11.25%","誤把債務保障比率當除數","誤用自有資金占比25%"],"hl":[["15%","漏乘貸款資金占比75%"],[],["5%","把債務保障比率錯當除數"],["3.75%","錯用自有資金占比（15÷60）"]]},{"id":"h:112-22","p":"h","src":"112年第22題","sec":"D2","stem":"下列那一種方法不屬於計算收益資本化率或折現率之方法？","opts":["加權平均資金成本法","有效總收入乘數法","折現現金流量分析法","風險溢酬法"],"ok":[2],"ex":["加權平均資金成本法（WACC）是技術規則明定計算收益資本化率之方法之一，非本題答案（本題問「不屬於」計算資本化率之方法）。","有效總收入乘數法是技術規則明定計算收益資本化率之方法之一。","折現現金流量分析法（DCF）是「估算不動產未來多期現金流量並折現」之獨立估價方法，並非用以「決定收益資本化率」之計算方法（DCF本身使用的是折現率而非資本化率之決定機制），即本題正解。","風險溢酬法是技術規則明定計算收益資本化率之方法之一。"],"tr":"","core":["WACC屬計算資本化率之方法","有效總收入乘數法屬計算資本化率方法","DCF是獨立估價方法，非決定資本化率","風險溢酬法屬計算資本化率之方法"],"hl":[[],[],["折現現金流量分析法","估算不動產未來多期現金流量並折現"],[]]},{"id":"h:113-13","p":"h","src":"113年第13題","sec":"D2","stem":"收益資本化率決定的方法中與銀行貸款成數相關的是那一個方法？","opts":["市場萃取法","有效總收入乘數法","債務保障比率法","風險溢酬法"],"ok":[2],"ex":["市場萃取法是以淨收益除以價格之商數決定，與銀行貸款成數無直接關連。","有效總收入乘數法是以淨收益率除以有效總收入乘數計算，與銀行貸款成數無直接關連。","技術規則明定債務保障比率法之公式為：收益資本化率＝債務保障比率×貸款常數×「貸款資金占不動產價格比率」，此公式直接涉及銀行貸款成數（貸款資金占比），與題目敘述完全相符。","風險溢酬法是考量流通性風險性等因素調整，與銀行貸款成數無直接關連。"],"tr":"","core":["市場萃取法與貸款成數無關","乘數法與貸款成數無關","公式含貸款資金占比，與貸款成數相關","風險溢酬法與貸款成數無關"],"hl":[["市場萃取法","以淨收益除以價格之商數決定"],["有效總收入乘數法","以淨收益率除以有效總收入乘數計算"],[],["風險溢酬法","考量流通性風險性等因素調整"]]},{"id":"h:113-24","p":"h","src":"113年第24題","sec":"D2","stem":"某一開發案自有資金比例是30%，其餘資金向銀行貸款，貸款利率為3%，自有資金報酬率為2%，其資本化率為何？","opts":["2.3%","2.7%","2.5%","2.6%"],"ok":[1],"ex":["2.3%＝30%×3%＋70%×2%，權重對調了。","依加權平均資金成本法（WACC）公式：資本化率＝自有資金比重×自有資金報酬率＋借貸資金比重×貸款利率＝30%×2%＋70%×3%＝0.6%＋2.1%＝2.7%，與本選項相符。","2.5%＝(2%＋3%)÷2，用簡單平均，沒有加權。","2.6%無法由題幹常見誤算得到；正確為70%×3%＋30%×2%＝2.7%。"],"tr":"","core":["權重對調的誤算","簡單平均，沒有加權","30%×2%＋70%×3%＝2.7%","非常見誤算，正確為2.7%"],"hl":[["2.3%","權重對調了"],[],["2.5%","沒有加權"],["2.6%","70%×3%＋30%×2%＝2.7%"]]},{"id":"h:114-6","p":"h","src":"114年第6題","sec":"D2","stem":"勘估標的未來平均1年期間之客觀淨收益為100萬元，收益價格為2,000萬元，收益資本化率為：","opts":["3%","5%","8%","10%"],"ok":[1],"ex":["3%無法由題幹常見誤算得到；正確為100÷2,000＝5%。","依直接資本化法公式：收益資本化率＝淨收益÷收益價格＝100萬元÷2,000萬元＝5%，與本選項相符。","8%無法由題幹常見誤算得到；正確為100÷2,000＝5%。","10%無法由題幹常見誤算得到；正確為100÷2,000＝5%。"],"tr":"","core":["非常見誤算，100÷2,000＝5%","淨收益÷收益價格＝100÷2,000＝5%","非常見誤算，100÷2,000＝5%","非常見誤算，100÷2,000＝5%"],"hl":[["3%","100÷2,000＝5%"],[],["8%","100÷2,000＝5%"],["10%","100÷2,000＝5%"]]},{"id":"h:114-8","p":"h","src":"114年第8題","sec":"D2","stem":"債務保障比率為1.3、貸款常數為0.055、貸款資金占不動產價格比率為70%，收益資本化率約為：","opts":["3%","4%","5%","6%"],"ok":[2],"ex":["3%≈0.055×70%÷1.3，把債務保障比率錯當除數。","4%≈0.055×70%＝3.85%，漏乘債務保障比率1.3。","依債務保障比率法公式：收益資本化率＝債務保障比率×貸款常數×貸款資金占比＝1.3×0.055×70%≈5.0%，與本選項相符。","6%無法由題幹常見誤算得到；正確為1.3×0.055×70%≈5%（§43第4款）。"],"tr":"","core":["誤把債務保障比率當除數","漏乘債務保障比率1.3","1.3×0.055×70%≈5%","非常見誤算，正確約5%"],"hl":[["3%","把債務保障比率錯當除數"],["4%","漏乘債務保障比率1.3"],[],["6%","1.3×0.055×70%≈5%"]]},{"id":"h:114-19","p":"h","src":"114年第19題","sec":"D2","stem":"收益法中對於收益的資本化可採收益資本化率或折現率，下列對於兩者數值高低關係之敘述何者正確？","opts":["收益資本化率高於折現率","收益資本化率低於折現率","收益資本化率等於折現率","不一定"],"ok":[3],"ex":["收益資本化率與折現率之數值高低關係並非恆定「收益資本化率高於折現率」，需視市場條件而定，本選項過於絕對。","同樣地，並非恆定「收益資本化率低於折現率」，本選項過於絕對。","兩者並非恆定相等，需視個案計算條件而定，本選項過於絕對。","收益資本化率與折現率之數值高低關係，依不同評估方法、市場條件及收益成長預期等因素而異，並無固定之高低關係，「不一定」是最精確的描述，與題目敘述相符。"],"tr":"","core":["高低關係非恆定，過於絕對","高低關係非恆定，過於絕對","兩者非恆定相等，過於絕對","兩者無固定高低關係，視條件而定"],"hl":[["高於","需視市場條件而定"],["低於","本選項過於絕對"],["等於","需視個案計算條件而定"],[]]},{"id":"h:114-20","p":"h","src":"114年第20題","sec":"D2","stem":"不動產相對一般性財貨具低流通、高風險、高增值及管理較難等特性；於採風險溢酬法決定收益資本化率時，上述特性中何者與收益資本化率高低呈反向變動？","opts":["流通性","風險性","增值性","管理難度"],"ok":[2],"ex":["依風險溢酬法之邏輯，流通性與資本化率呈「同向」關係（流通性低，資本化率較高，以補償變現困難之風險），並非反向變動。","風險性與資本化率呈「同向」關係（風險性高，資本化率較高，以補償投資風險），並非反向變動。","增值性與收益資本化率呈「反向」變動關係：增值性愈高，投資人願意接受較低之當期收益報酬（因預期未來增值可彌補），故收益資本化率愈低，與題目敘述相符，即本題正解。","管理難度與資本化率呈「同向」關係（管理愈難，資本化率較高，以補償管理成本及複雜度），並非反向變動。"],"tr":"","core":["流通性與資本化率同向，非反向","風險性與資本化率同向，非反向","增值性愈高，資本化率愈低","管理難度與資本化率同向，非反向"],"hl":[["流通性","流通性與資本化率呈「同向」關係"],["風險性","風險性與資本化率呈「同向」關係"],[],["管理難度","管理難度與資本化率呈「同向」關係"]]},{"id":"h:114-21","p":"h","src":"114年第21題","sec":"D2","stem":"以直接資本化法對同一不動產之土地、建物及不動產分別評估其價值，則三者之收益資本化率數值何者最高？","opts":["土地","建物","不動產","不一定"],"ok":[1],"ex":["土地通常無實體折舊耗損風險（土地不會像建物一樣隨時間損耗），相對風險較低，其收益資本化率通常最低，並非最高。","建物因有折舊耗損、維護成本及使用年限限制等風險因素，其收益資本化率通常高於土地，三者中以建物之收益資本化率最高，與本選項相符。","不動產（房地綜合）之收益資本化率是土地與建物資本化率之加權平均值，數值會介於土地與建物資本化率之間，並非三者中最高者。","依一般估價理論及實務經驗法則，建物資本化率高於土地及房地綜合之資本化率，此關係具有相對穩定之邏輯依據（建物折舊風險），並非「不一定」。"],"tr":"","core":["土地無折舊風險，資本化率通常最低","建物有折舊耗損風險，資本化率最高","房地綜合率介於土地與建物之間","建物最高有穩定邏輯，非不一定"],"hl":[["土地","其收益資本化率通常最低"],[],["不動產","介於土地與建物資本化率之間"],["不一定","建物資本化率高於土地及房地綜合之資本化率"]]},{"id":"h:101-16","p":"h","src":"101年第16題","sec":"D3","stem":"不動產估價技術規則第31條規定，何種估價方法得適用於以投資為目的之不動產投資評估？","opts":["直接資本化法","折現現金流量分析","剩餘法","分配法"],"ok":[1],"ex":["直接資本化法是以未來平均一年期間之客觀淨收益除以資本化率，適用於一般收益性不動產估價，並非規則明定專門適用於「以投資為目的」之不動產投資評估方法。","技術規則第31條明定折現現金流量分析法得適用於以投資為目的之不動產投資評估，因其能反映多期現金流量及期末處分價值，更貼近投資決策之考量，與題目敘述相符。","剩餘法在教材上通常指土地開發分析法（假設開發法）的概念，不是§31明定適用於以投資為目的之評估方法；§31明定的是折現現金流量分析法。","「分配法」並非技術規則明定之正式估價方法名稱。"],"tr":"","core":["直接資本化法非投資評估專用方法","DCF得適用於以投資為目的之評估","剩餘法非§31明定，§31是DCF","分配法非正式估價方法名稱"],"hl":[["直接資本化法","適用於一般收益性不動產估價"],[],["剩餘法","§31明定的是折現現金流量分析法"],["分配法","並非技術規則明定之正式估價方法名稱"]]},{"id":"h:101-18","p":"h","src":"101年第18題","sec":"D3","stem":"請問折現現金流量分析之計算公式P＝Σ[CFk/(1＋Y)ᵏ]＋Pn'/(1＋Y)ⁿ′中，Pn'為下列何者？","opts":["收益價格","淨收益","折現率","期末價值"],"ok":[3],"ex":["「收益價格」是估價結果之名稱，並非公式中Pn'這個特定變數所代表之意義。","「淨收益」在公式中是以CFk表示（各期現金流量），並非Pn'所代表之意義。","「折現率」在公式中是以Y表示，並非Pn'所代表之意義。","技術規則明定DCF公式P＝Σ[CFk/(1+Y)ᵏ]＋Pn'/(1+Y)ⁿ′中，Pn'代表「期末價值」（即分析期間結束時，勘估標的之處分價值），與題目敘述相符。"],"tr":"","core":["收益價格是估價結果，非Pn'","淨收益在公式中是CFk","折現率在公式中是Y","Pn'代表期末價值"],"hl":[["收益價格","是估價結果之名稱"],["淨收益","在公式中是以CFk表示（各期現金流量）"],["折現率","在公式中是以Y表示"],[]]},{"id":"h:102-8","p":"h","src":"102年第8題","sec":"D3","stem":"依不動產估價技術規則規定，以不動產證券化為估價目的，採折現現金流量分析估價時，下列敘述何者錯誤？","opts":["各期淨收益應以勘估標的之契約租金計算為原則","因情況特殊不宜採契約租金估價者得敘明","契約租金未知者，應以限定租金推估淨收益","總費用應依信託計畫資料加以推算"],"ok":[2],"ex":["各期淨收益應以勘估標的之契約租金計算為原則，此為正確敘述，非本題答案（本題問「何者錯誤」）。","因情況特殊不宜採契約租金估價者得敘明，此為正確敘述（規則允許例外情形之敘明）。","§33明定契約租金未知者，「應以市場經濟租金推估客觀淨收益」，不是用限定租金；本選項敘述錯誤，就是本題的答案。","總費用應依信託計畫資料加以推算，此為正確敘述。"],"tr":"","core":["各期淨收益以契約租金為原則","特殊不宜採契約租金者得敘明","應以市場經濟租金推估，非限定租金","總費用依信託計畫資料推算"],"hl":[[],[],["限定租金","應以市場經濟租金推估客觀淨收益"],[]]},{"id":"h:102-27","p":"h","src":"102年第27題","sec":"D3","stem":"對具永續性固定收益之土地，以直接資本化法評估其價值，如於折現現金流量分析之公式P＝Σ[CFk/(1+Y)ᵏ]+Pn'/(1+Y)ⁿ′，n'為下列何者？","opts":["物理耐用年數","經濟耐用年數","殘餘耐用年數","折現現金流量分析期間"],"ok":[3],"ex":["「物理耐用年數」指建物因自然耗損或外力破壞至結構脆弱而不堪使用所經歷之年數（§65），跟DCF公式中的n′（折現現金流量分析期間）不同。","「經濟耐用年數」是建物因功能或效益衰退至不值得使用所經歷之年數，與DCF公式中n'之定義不同。","「殘餘耐用年數」並非技術規則明定DCF公式中n'所代表之正式用語。","技術規則明定DCF公式P＝Σ[CFk/(1+Y)ᵏ]＋Pn'/(1+Y)ⁿ′中，n'代表「折現現金流量分析期間」，即估價人員所設定預估未來現金流量之分析年限，與題目敘述相符。"],"tr":"","core":["物理耐用年數與DCF分析期間不同","經濟耐用年數與n'定義不同","殘餘耐用年數非n'正式用語","n'代表折現現金流量分析期間"],"hl":[["物理耐用年數","因自然耗損或外力破壞至結構脆弱而不堪使用所經歷之年數"],["經濟耐用年數","因功能或效益衰退至不值得使用所經歷之年數"],["殘餘耐用年數"],[]]},{"id":"h:103-37","p":"h","src":"103年第37題","sec":"D3","stem":"某甲擬投資購買一不動產，預計每年可以獲得10萬元淨收益，第三年年底預計可以200萬元出售，假設折現率為5%，請問合理的價格約為多少？","opts":["173萬元","200萬元","227萬元","232萬元"],"ok":[1],"ex":["173萬元為期末出售價值200萬元之現值（≈172.77萬元），漏計各期淨收益現值（約27.23萬元），計算不完整。","依DCF公式：各期淨收益現值總和＝Σ[10萬÷(1.05)ᵏ]（k=1至3）≈27.23萬元；期末出售價值現值＝200萬÷(1.05)³≈172.77萬元；合理價格＝27.23＋172.77＝200萬元，與本選項相符（不是巧合：10÷200＝5%正好等於折現率，期末又以同價200萬元出售，所以現值必等於200萬元）。","227萬元＝各期淨收益現值27.23萬元＋期末售價200萬元，錯在期末價值沒有用(1.05)³折現；依§32，Pn′要除以(1＋Y)ⁿ′，現值只有172.77萬元。","232萬元≈200×(1.05)³＝231.5萬元，方向弄反了：把期末價值往後複利，而不是往前折現。"],"tr":"","core":["只算期末售價現值，漏計各期淨收益","淨收益現值27.23＋期末現值172.77","期末價值沒有用(1.05)³折現","把期末價值往後複利，方向弄反"],"hl":[["173萬元","漏計各期淨收益現值（約27.23萬元）"],[],["227萬元","Pn′要除以(1＋Y)ⁿ′"],["232萬元","而不是往前折現"]]},{"id":"h:104-13","p":"h","src":"104年第13題","sec":"D3","stem":"依不動產估價技術規則之規定，以不動產證券化為估價目的，採折現現金流量分析法估價時，各期淨收益應以下列何者為計算原則？","opts":["勘估標的之契約租金","勘估標的之經濟租金","比較標的之契約租金","比較標的之經濟租金"],"ok":[0],"ex":["技術規則明定以不動產證券化為估價目的，採DCF估價時，各期淨收益應以「勘估標的」之契約租金計算為原則，與題目敘述完全相符。","§33的原則是勘估標的的「契約租金」；「市場經濟租金」只在契約租金未知時才用來推估客觀淨收益，不是原則。","規則明定計算基準是「勘估標的」（而非比較標的）之租金，本選項主體誤植。","同C選項，主體與租金種類皆與規則規定不符。"],"tr":"","core":["以勘估標的之契約租金為原則","經濟租金僅契約租金未知時才用","基準是勘估標的，非比較標的","主體與租金種類皆不符"],"hl":[[],["經濟租金","勘估標的的「契約租金」"],["比較標的","計算基準是「勘估標的」"],["比較標的","經濟租金"]]},{"id":"h:105-17","p":"h","src":"105年第17題","sec":"D3","stem":"依不動產估價技術規則之規定，以不動產證券化為估價目的，採折現現金流量分析法估價時，各期淨收益應以勘估標的之何種租金為計算原則？","opts":["實質租金","經濟租金","支付租金","契約租金"],"ok":[3],"ex":["「實質租金」是支付租金加計押金等運用收益之總數概念，並非規則明定不動產證券化DCF估價各期淨收益計算之原則租金種類。","「經濟租金」是契約租金「未知」時之替代推估方式，並非規則明定之原則性計算基準。","「支付租金」是承租人實際支付之租金本身，並非規則明定之原則性計算基準。","技術規則明定以不動產證券化為估價目的，採DCF估價時，各期淨收益應以勘估標的之「契約租金」計算為原則，與題目敘述完全相符。"],"tr":"","core":["實質租金非證券化DCF原則租金","經濟租金是契約租金未知時的替代","支付租金非規則明定原則基準","以勘估標的之契約租金為原則"],"hl":[["實質租金","是支付租金加計押金等運用收益之總數概念"],["經濟租金","契約租金「未知」時之替代推估方式"],["支付租金","承租人實際支付之租金本身"],[]]},{"id":"h:108-6","p":"h","src":"108年第6題","sec":"D3","stem":"不動產估價師應兼採二種以上估價方法推算勘估標的價格。以契約約定租金作為不動產證券化受益證券信託利益分配基礎者，何種方法之價格應賦予相對較大之權重？","opts":["成本法","土地開發分析法","折現現金流量分析法","比較法"],"ok":[2],"ex":["成本法是以重建/重置成本扣除折舊推算價格，並非規則明定於此特定情境下應賦予較大權重之方法。","土地開發分析法是以進行開發為前提之估價方法，並非規則明定於此特定情境下應賦予較大權重之方法。","技術規則明定以契約約定租金作為不動產證券化受益證券信託利益分配基礎者，折現現金流量分析法之收益價格應賦予相對較大之權重（因DCF能完整反映契約租金所產生之多期現金流量，與信託利益分配機制最為契合），與題目敘述相符。","比較法是以交易實例為基礎，並非規則明定於此特定情境下應賦予較大權重之方法。"],"tr":"","core":["成本法非此情境應加重權重之方法","土地開發分析法非此情境加重之方法","契約租金作分配基礎者，DCF權重較大","比較法非此情境應加重權重之方法"],"hl":[["成本法","以重建/重置成本扣除折舊推算價格"],["土地開發分析法","以進行開發為前提之估價方法"],[],["比較法","以交易實例為基礎"]]},{"id":"h:109-22","p":"h","src":"109年第22題","sec":"D3","stem":"國內已有不動產證券化的個案，依據不動產估價技術規則規定，以契約約定租金作為不動產證券化受益證券信託利益分配基礎者，何種價格應視不同價格所蒐集資料可信度及估價種類目的條件差異，考量價格形成因素之相近程度情形賦予相對較大之權重？","opts":["比較法之實例價格","土地開發分析價格","直接資本化法之收益價格","折現現金流量分析法之收益價格"],"ok":[3],"ex":["比較法之實例價格並非規則明定於此特定情境下應賦予較大權重之價格。","土地開發分析價格並非規則明定於此特定情境下應賦予較大權重之價格。","直接資本化法之收益價格僅反映未來平均一年期間之單一年度收益，並非規則明定於此特定情境下應賦予較大權重之價格。","技術規則明定以契約約定租金作為不動產證券化受益證券信託利益分配基礎者，折現現金流量分析法之收益價格應賦予相對較大之權重，因其能完整反映多期現金流量與信託利益分配機制最為契合，與題目敘述相符。"],"tr":"","core":["比較法實例價格非此情境加重者","土地開發分析價格非此情境加重者","直接資本化法僅反映單一年度收益","契約租金作分配基礎者，DCF權重較大"],"hl":[["比較法之實例價格"],["土地開發分析價格"],["直接資本化法之收益價格","僅反映未來平均一年期間之單一年度收益"],[]]},{"id":"h:110-11","p":"h","src":"110年第11題","sec":"D3","stem":"依不動產估價技術規則規定，以不動產證券化為估價目的者，其折現現金流量分析法之總費用應依何種資料加以推算？","opts":["市場相關資料","信託計畫資料","類似產品資料","歷史費用資料"],"ok":[1],"ex":["「市場相關資料」並非技術規則明定不動產證券化估價目的下總費用推算所應依據之特定資料來源。","技術規則明定以不動產證券化為估價目的者，其DCF之總費用應依「信託計畫資料」加以推算（因信託計畫詳細記載該證券化案件之收支安排），與題目敘述完全相符。","「類似產品資料」並非規則明定之特定依據資料來源。","「歷史費用資料」並非規則明定不動產證券化估價總費用推算之特定依據來源。"],"tr":"","core":["市場相關資料非規則明定依據","總費用依信託計畫資料推算","類似產品資料非規則明定依據","歷史費用資料非規則明定依據"],"hl":[["市場相關資料"],[],["類似產品資料"],["歷史費用資料"]]},{"id":"h:111-10","p":"h","src":"111年第10題","sec":"D3","stem":"不動產估價由三大方法所推估之價值，於綜合決定勘估標的價格時，若以契約約定租金作為不動產證券化受益證券信託利益分配基礎者，何種方法應視前項情形賦予相對較大之權重？","opts":["比較法","直接資本化法之收益價格","折現現金流量分析法之收益價格","成本法"],"ok":[2],"ex":["比較法並非規則明定於「以契約約定租金作為信託利益分配基礎」情境下應賦予較大權重之方法。","直接資本化法之收益價格僅反映單一年度收益，並非規則明定於此特定情境下應賦予較大權重之方法。","技術規則明定以契約約定租金作為不動產證券化受益證券信託利益分配基礎者，折現現金流量分析法之收益價格應賦予相對較大之權重，與題目敘述完全相符。","成本法並非規則明定於此特定情境下應賦予較大權重之方法。"],"tr":"","core":["比較法非此情境應加重權重之方法","直接資本化法僅反映單一年度收益","契約租金作分配基礎者，DCF權重較大","成本法非此情境應加重權重之方法"],"hl":[["比較法"],["直接資本化法之收益價格","僅反映單一年度收益"],[],["成本法"]]},{"id":"h:114-7","p":"h","src":"114年第7題","sec":"D3","stem":"以投資為目的之不動產投資評估，最適合的估價方法為：","opts":["比較法","折現現金流量分析法","成本法","土地開發分析法"],"ok":[1],"ex":["比較法是以交易實例為基礎推算價格，並非規則明定專門適用於投資評估之方法。","技術規則明定折現現金流量分析法得適用於以投資為目的之不動產投資評估，因其能完整反映多期現金流量及期末處分價值，最貼近投資決策考量，與題目敘述相符。","成本法是以重建/重置成本扣除折舊推算價格，並非規則明定專門適用於投資評估之方法。","土地開發分析法是以進行開發為前提之估價方法，並非規則明定專門適用於一般投資評估之方法（其適用情境是「以進行開發為前提之宗地估價」）。"],"tr":"","core":["比較法非投資評估專用方法","DCF得適用於以投資為目的之評估","成本法非投資評估專用方法","土地開發分析法以開發為前提"],"hl":[["比較法","以交易實例為基礎推算價格"],[],["成本法","以重建/重置成本扣除折舊推算價格"],["土地開發分析法","以進行開發為前提之宗地估價"]]},{"id":"h:114-23","p":"h","src":"114年第23題","sec":"D3","stem":"依不動產估價技術規則第32條之規定，若期末處分價值已知，以折現現金流量分析法計入該價值時，應採取那一種資本化率？","opts":["直接資本化率","綜合資本化率","折現率","利率"],"ok":[2],"ex":["「直接資本化率」是直接資本化法（單一年期淨收益除以資本化率）所採用之概念，並非DCF公式中計入期末處分價值時所採用之利率。","「綜合資本化率」是土地與建物資本化率加權平均之概念，並非DCF公式中計入期末處分價值時所採用之利率。","技術規則第32條明定，DCF公式中計入期末處分價值Pn'時，應以「折現率」Y進行折現（即Pn'÷(1+Y)ⁿ′），與題目敘述相符。","「利率」泛指一般借貸或存款之利息率概念，並非DCF公式中明確指定計入期末處分價值所應採用之專有名詞。"],"tr":"","core":["直接資本化率屬直接資本化法，非DCF","綜合資本化率是土地建物加權，非DCF","期末處分價值應以折現率折現","利率是一般借貸概念，非指定用語"],"hl":[["直接資本化率","是直接資本化法（單一年期淨收益除以資本化率）所採用之概念"],["綜合資本化率","土地與建物資本化率加權平均之概念"],[],["利率","泛指一般借貸或存款之利息率概念"]]},{"id":"h:99-10","p":"h","src":"99年第10題","sec":"E1","stem":"根據土地法定用途、使用強度進行開發與改良所導致土地效益之變化，估算開發或建築後總銷售金額，扣除開發期間之直接成本、間接成本、資本利息及利潤後，求得之土地價格，此估價方法是依據那一種方式呢？","opts":["比較法","直接資本化法","土地開發分析法","現金流量分析法"],"ok":[2],"ex":["比較法是以比較標的之交易價格為基礎，與題目所述「依開發內容估算總銷售金額並扣除成本利潤」之操作邏輯不同。","直接資本化法是以淨收益除以資本化率求取價格，與題目所述土地開發成本利潤計算邏輯不同。","技術規則§70：「土地開發分析法，指根據土地法定用途、使用強度進行開發與改良所導致土地效益之變化，估算開發或建築後總銷售金額，扣除開發期間之直接成本、間接成本、資本利息及利潤後，求得開發前或建築前土地開發分析價格。」與題目敘述完全相符。","現金流量分析法（DCF）是收益法之延伸應用，著重於多期現金流量折現，與題目所述土地開發成本利潤計算邏輯不同。"],"tr":"","core":["比較法以交易價格為基礎，邏輯不同","直接資本化法是淨收益÷資本化率","銷售金額扣成本利息利潤＝土地開發分析法","DCF屬收益法，著重多期折現"],"hl":[["比較法","以比較標的之交易價格為基礎"],["直接資本化法","以淨收益除以資本化率求取價格"],[],["現金流量分析法","收益法之延伸應用"]]},{"id":"h:99-33","p":"h","src":"99年第33題","sec":"E1","stem":"土地開發分析法屬於何種不動產估價方法？","opts":["比較法","收益法","成本法","計量模型分析法"],"ok":[2],"ex":["比較法是以交易實例為基礎，土地開發分析法之核心邏輯（扣除成本與利潤反推土地價值）並非比較法之延伸。","收益法是以淨收益折現或資本化求取價格，土地開發分析法雖也涉及銷售金額估算，但核心邏輯仍著重於成本之扣除推算，非收益法之延伸。","依教材，土地開發分析法以「開發後總銷售金額扣除成本及利潤」反推土地價值，計算邏輯與成本法相近，歸類為成本法之延伸應用（技術規則則將其另列第三章第四節），故選成本法。","計量模型分析法（§19第7款）是蒐集相當數量比較標的、以計量模型求出影響價格因素調整率及調整額的方法，屬比較法範疇，與土地開發分析法無關。"],"tr":"","core":["扣成本利潤反推地價，非比較法延伸","核心在扣除成本推算，非收益法延伸","依教材歸類為成本法之延伸應用","計量模型屬比較法範疇，無關"],"hl":[["比較法","以交易實例為基礎"],["收益法","以淨收益折現或資本化求取價格"],[],["計量模型分析法","屬比較法範疇"]]},{"id":"h:99-37","p":"h","src":"99年第37題","sec":"E1","stem":"下列有關土地開發分析法之敘述，何者正確？","opts":["主要估計開發或建築前之土地開發分析價格","不應將開發期間的資本利息列入成本考量","不應將開發利潤列入考量","預期總銷售金額應按法定容積面積乘上推定之銷售單價計算"],"ok":[0],"ex":["技術規則明定土地開發分析法主要估計開發或建築「前」（而非後）之土地開發分析價格，即以開發完成後之預期銷售金額反推「現在」（開發前）之土地價值，與題目敘述相符。","技術規則明定應將開發期間之資本利息列入成本考量（V公式中之i即為資本利息綜合利率），本選項與規則規定相反。","技術規則明定應將開發利潤列入考量（V公式中之r即為適當之利潤率），本選項與規則規定相反。","依§75，預期總銷售金額應按「開發或建築後可銷售之土地或建物面積」乘以推定之銷售單價計算，不是按法定容積面積；可銷售面積（依§74按建照圖說或最有效使用估算）與法定容積面積不同。"],"tr":"","core":["估的是開發或建築「前」的土地價格","資本利息應列入成本考量","開發利潤應列入考量","按可銷售面積計算，非法定容積面積"],"hl":[[],["不應","應將開發期間之資本利息列入成本考量"],["不應","應將開發利潤列入考量"],["法定容積面積","開發或建築後可銷售之土地或建物面積"]]},{"id":"h:101-28","p":"h","src":"101年第28題","sec":"E1","stem":"採土地開發分析法進行不動產估價時，其基本之假設前提為：","opts":["必須符合法定容積之規定為上限進行開發","必須以預售方式為前提","必須以個別投資廠商之利潤率為依據","必須於開發完成時取得全部房地銷售金額"],"ok":[3],"ex":["技術規則並未規定必須「符合法定容積之規定為上限」進行開發，土地開發分析法之開發內容應依最有效使用評估，非必然以法定容積為唯一上限假設。","依教材，基本假設前提並非「必須以預售方式為前提」，而是相反——必須於開發完成時取得「全部」房地銷售金額。","技術規則並未規定須以「個別投資廠商」之利潤率為依據，而是應以「適當」之利潤率（具一般市場代表性）為依據。","依教材，土地開發分析法之基本假設前提為必須於開發完成時取得全部房地銷售金額（即假設整批完銷，非分期或預售情境），與題目敘述完全相符。"],"tr":"","core":["開發內容依最有效使用，非以容積為限","非以預售為前提，須完工全部銷售","應採適當利潤率，非個別廠商利潤率","前提是開發完成時取得全部銷售金額"],"hl":[["必須符合法定容積之規定為上限","開發內容應依最有效使用評估"],["必須以預售方式為前提","必須於開發完成時取得「全部」房地銷售金額"],["個別投資廠商","「適當」之利潤率"],[]]},{"id":"h:102-18","p":"h","src":"102年第18題","sec":"E1","stem":"某建商擬開發建地，預計興建樓板面積 1000 坪，另雨遮外加 50 坪，若推定銷售單價平均新臺幣 60 萬元/坪，利潤率 20%、資本利息綜合利率 5%、直接成本新臺幣 2 億元、間接成本新臺幣 5 千萬元，則土地開發分析價格為新臺幣多少萬元？","opts":["22619 萬元","23480 萬元","25000 萬元","26814 萬元"],"ok":[0],"ex":["考選部標準答案 A。§81：V＝S÷(1＋R)÷(1＋i)－(C＋M)。S＝1000 坪×60 萬＝60000 萬（雨遮 50 坪不計價）；60000÷1.2÷1.05＝47619；C＋M＝20000＋5000＝25000 萬；V＝47619－25000＝22619 萬元。","23,480萬元無法由題幹常見誤算得到；正確為60,000÷1.2÷1.05－25,000≈22,619萬元。","25000 萬是把雨遮 50 坪也算進銷售面積的結果（1050 坪×60＝63000 萬；63000÷1.2÷1.05＝50000，再減 25000＝25000），是陷阱：雨遮不計價。","26,814萬元無法由題幹常見誤算得到；正確為60,000÷1.2÷1.05－25,000≈22,619萬元。"],"tr":"","core":["雨遮不計價，算得22,619萬","非常見誤算，應約22,619萬","雨遮算入銷售面積的誤算","非常見誤算，應約22,619萬"],"hl":[[],["23480","22,619萬元"],["25000","雨遮不計價"],["26814","22,619萬元"]]},{"id":"h:102-24","p":"h","src":"102年第24題","sec":"E1","stem":"某建商欲以土地開發分析法評估某土地作為住宅銷售個案之土地價值，請問下列何者非建商運用該方法應蒐集的資料？","opts":["資本利率","廣告費","利潤率","資本化率"],"ok":[3],"ex":["資本利率是§72第6款明列土地開發分析法得蒐集之資料（用以依§79計算資本利息綜合利率），非本題答案。","廣告費屬於間接成本之一項，是技術規則明定應蒐集之資料項目之一。","利潤率是技術規則明定應蒐集之資料項目之一（V公式中之r）。","「資本化率」是收益法（直接資本化法）之核心概念，並非技術規則明定土地開發分析法應蒐集之資料項目，即本題正解。"],"tr":"","core":["資本利率是應蒐集資料之一","廣告費屬間接成本，應蒐集","利潤率是應蒐集資料（公式之r）","資本化率屬收益法，非應蒐集資料"],"hl":[[],[],[],["資本化率","收益法（直接資本化法）之核心概念"]]},{"id":"h:102-36","p":"h","src":"102年第36題","sec":"E1","stem":"土地開發分析法公式V＝S÷(1+R)÷(1+i)－(C+M)，其中i為開發或建築所需總成本之資本利息綜合利率，則R為：","opts":["資本化率","土地價值率","營業稅率","適當之利潤率"],"ok":[3],"ex":["「資本化率」是收益法之概念，並非V公式中R所代表之意義。","「土地價值率」並非技術規則明定V公式中R所代表之正式用語。","「營業稅率」並非V公式中R所代表之意義，技術規則之開發成本利潤計算並非聚焦於營業稅率。","§81 規定土地開發分析法公式V＝S÷(1＋R)÷(1＋i)－(C＋M)中，R代表「適當之利潤率」，與題目敘述相符。"],"tr":"","core":["資本化率屬收益法，非公式中的R","土地價值率非R的正式用語","R不是營業稅率","公式中R代表適當之利潤率"],"hl":[["資本化率"],["土地價值率"],["營業稅率"],[]]},{"id":"h:104-22","p":"h","src":"104年第22題","sec":"E1","stem":"下列有關土地開發分析估價程序的排列，何者正確？①計算土地開發分析價格　②估算各項成本及相關費用　③估算開發後總銷售金額　④確定土地開發內容及預期開發時間　⑤選擇適當之利潤率及資本利息綜合利率　⑥估算開發後可銷售之土地或建物面積　⑦現況勘察並進行環境發展程度之調查及分析　⑧調查各項成本及相關費用並蒐集市場行情等資料","opts":["⑧⑦⑥⑤④③②①","⑦⑧④②③⑥⑤①","⑥③②⑤⑧⑦④①","④⑧⑦⑥③②⑤①"],"ok":[3],"ex":["⑧⑦⑥⑤④③②①此排列順序將⑧調查成本費用置於④確定開發內容之前，順序錯誤（應先確定開發內容才能調查相關成本）。","⑦⑧④②③⑥⑤①此排列順序將⑦現況勘察置於④確定開發內容之前，且⑥估算可銷售面積置於③估算總銷售金額之後，順序皆與技術規則規定不符。","⑥③②⑤⑧⑦④①此排列順序將⑥估算可銷售面積置於最前面，且④確定開發內容置於極後段，順序嚴重錯誤。","技術規則明定土地開發分析法估價程序為：④確定土地開發內容及預期開發時間→⑧調查各項成本費用並蒐集市場行情等資料→⑦現況勘察並進行環境發展程度之調查分析→⑥估算開發後可銷售之土地或建物面積→③估算開發後總銷售金額→②估算各項成本及相關費用→⑤選擇適當之利潤率及資本利息綜合利率→①計算土地開發分析價格，與本選項④⑧⑦⑥③②⑤①完全相符。"],"tr":"","core":["⑧調查成本不能排在④確定內容之前","⑦⑥位置皆與規定順序不符","⑥排最前、④排後段，順序錯","確定內容→調查→勘察→面積→金額…→計算"],"hl":[["⑧⑦","應先確定開發內容才能調查相關成本"],["⑦⑧④"],["⑥③②"],[]]},{"id":"h:104-23","p":"h","src":"104年第23題","sec":"E1","stem":"土地開發分析法之資本利息綜合利率，應依不動產估價技術規則第58條及第59條規定計算資本利息年利率，並參考下列那一項公式計算之？","opts":["資本利息年利率×（土地價值比率+建物價值比率）×1/2×開發年數","資本利息年利率×（土地價值比率+建物價值比率×1/2）×開發年數","資本利息年利率×（土地價值比率×1/2+建物價值比率）×開發年數","資本利息年利率×（土地價值比率+建物價值比率）×1/4×開發年數"],"ok":[1],"ex":["1/2是只對建物打折，不是整體合計後打折。","依§79：資本利息綜合利率＝資本利息年利率×（土地價值比率＋建物價值比率×1/2）×開發年數，與本選項相符。土地一開始就要全額投入，建物是施工期間陸續投入，所以只有建物乘1/2。","1/2放錯位置：要打折的是建物，不是土地。","技術規則沒有×1/4的公式。"],"tr":"","core":["1/2只對建物打折，非整體打折","土地全額＋建物×1/2，乘開發年數","1/2放錯位置，該打折的是建物","技術規則沒有×1/4的公式"],"hl":[["（土地價值比率+建物價值比率）×1/2","只對建物打折"],[],["土地價值比率×1/2","要打折的是建物"],["×1/4"]]},{"id":"h:104-31","p":"h","src":"104年第31題","sec":"E1","stem":"下列對以進行開發為前提之宗地估價，何者正確？①得採土地開發分析法進行估價　②得採收益法進行估價　③並參酌比較法之評估結果決定其估價額　④並參酌成本法之評估結果決定其估價額","opts":["①③","②④","③④","①②"],"ok":[0],"ex":["§87 規定：以進行開發為前提之宗地，得採土地開發分析法進行估價，並參酌比較法或收益法之評估結果決定其估價額。①③符合（官方答案）。","④「參酌成本法」不見於§87（§87 為參酌比較法或收益法）；②條文僅言「參酌」收益法結果，並非以收益法為估價方法，故本組合不選。","④「參酌成本法」不在§87 條文中，故本組合錯誤。","②§87 僅規定「參酌」收益法之評估結果，而非「得採收益法進行估價」；官方答案以①③為準，故①②不選。"],"tr":"","core":["得採土地開發分析法，參酌比較法","④參酌成本法不見於條文","參酌成本法不在條文中","收益法僅供參酌，非估價方法"],"hl":[[],["②④","§87 為參酌比較法或收益法"],[],["§87 僅規定「參酌」收益法之評估結果"]]},{"id":"h:104-35","p":"h","src":"104年第35題","sec":"E1","stem":"依土地開發分析法評估不動產價格時，如果開發後預期總銷售金額為1億元，適當之利潤率為10%，開發所需之直接成本為5,000萬元，開發所需之間接成本為3,000萬元，開發所需總成本之資本利息綜合利率為4%，請問土地開發分析價格為何？（萬元以後四捨五入）","opts":["741萬元","772萬元","1,091萬元","1,615萬元"],"ok":[0],"ex":["依公式V＝[S÷(1+r)÷(1+i)]－(C+M)＝[10,000÷(1+10%)÷(1+4%)]－(5,000+3,000)≈8,741.26－8,000＝741.26萬元，四捨五入約741萬元，與本選項相符。","772萬元是把利潤率與資本利息綜合利率相加後一次除：10,000÷(1＋10%＋4%)－8,000≈771.9萬元；§81應連除(1＋R)與(1＋i)。","1,091萬元是只除利潤率、漏除資本利息綜合利率：10,000÷1.1－8,000≈1,090.9萬元；§81須先除(1＋R)再除(1＋i)。","1,615萬元是漏除利潤率、只除資本利息綜合利率：10,000÷1.04－8,000≈1,615.4萬元。"],"tr":"","core":["連除兩率再減8,000≈741萬","兩率相加一次除的誤算","只除利潤率、漏除資本利息的誤算","漏除利潤率、只除資本利息的誤算"],"hl":[[],["772萬元","應連除(1＋R)與(1＋i)"],["1,091萬元","須先除(1＋R)再除(1＋i)"],["1,615萬元","漏除利潤率"]]},{"id":"h:105-29","p":"h","src":"105年第29題","sec":"E1","stem":"資本利息年利率為2%，土地價值：建物價值＝6：4，開發年數3年，資本利息綜合利率為：","opts":["2.4%","3.6%","4.8%","6%"],"ok":[2],"ex":["2.4%是把正確結果4.8%整體再乘1/2（2%×0.8×3×1/2），或只用建物比率（2%×0.4×3）；§79只有建物價值比率乘1/2，土地比率全額計入。","3.6%是只算土地價值比率、漏了建物價值比率×1/2：2%×0.6×3＝3.6%。","依資本利息綜合利率公式：資本利息年利率×(土地價值比率＋建物價值比率×1/2)×開發年數＝2%×(0.6+0.4×0.5)×3＝2%×0.8×3＝4.8%，與本選項相符。","6%的計算未正確套用建物價值比率之折半係數。"],"tr":"","core":["整體再乘1/2或只用建物比率的誤算","漏算建物價值比率×1/2的誤算","2%×(0.6＋0.4×½)×3＝4.8%","未套用建物比率折半的誤算"],"hl":[["2.4%","§79只有建物價值比率乘1/2，土地比率全額計入"],["3.6%","漏了建物價值比率×1/2"],[],["6%","建物價值比率之折半係數"]]},{"id":"h:105-40","p":"h","src":"105年第40題","sec":"E1","stem":"某一住宅用地，面積1000坪，建蔽率50%，容積率225%，擬規劃地上7層地下2層之集合住宅。假設本案完工後總銷售金額為80000萬元，資本利息綜合利率為12%、利潤率為20%、開發或建築所需之直接成本為20000萬元、開發或建築所需之間接成本為8400萬元，以土地開發分析法估計本住宅用地的價格，請問下列何者最接近？","opts":["46267萬元","42859萬元","38393萬元","31124萬元"],"ok":[3],"ex":["46,267萬元無法由題幹常見誤算得到；正確為80,000÷1.2÷1.12－28,400≈31,124萬元。","42,859萬元無法由題幹常見誤算得到；正確為80,000÷1.2÷1.12－28,400≈31,124萬元。","38,393萬元是先把成本從總銷售金額扣掉再除利潤率與利率：(80,000－28,400)÷1.2÷1.12≈38,393萬元；§81應先除(1＋R)(1＋i)、最後才減(C＋M)。","依公式V＝[S÷(1+r)÷(1+i)]－(C+M)＝[80,000÷(1+20%)÷(1+12%)]－(20,000+8,400)≈59,523.8－28,400＝31,123.8萬元，約31124萬元，與本選項最接近。"],"tr":"","core":["非常見誤算，應約31,124萬","非常見誤算，應約31,124萬","先減成本再除兩率的誤算","連除兩率再減28,400≈31,124萬"],"hl":[["46267萬元","31,124萬元"],["42859萬元","31,124萬元"],["38393萬元","應先除(1＋R)(1＋i)、最後才減(C＋M)"],[]]},{"id":"h:106-19","p":"h","src":"106年第19題","sec":"E1","stem":"某建商擬開發建地，預計興建樓板面積1,000坪，若推定銷售單價平均80萬元/坪，利潤率20%、資本利息綜合利率5%、直接成本3億元、間接成本6千萬元，則土地開發分析價格為何？","opts":["26,582萬元","27,215萬元","27,492萬元","28,200萬元"],"ok":[2],"ex":["26,582萬元無法由題幹常見誤算得到；正確為80,000÷1.2÷1.05－36,000≈27,492萬元。","27,215萬元無法由題幹常見誤算得到；正確為80,000÷1.2÷1.05－36,000≈27,492萬元。","S＝1,000坪×80萬＝80,000萬元；C＋M＝30,000＋6,000＝36,000萬元。依§81：V＝S÷(1＋R)÷(1＋i)－(C＋M)＝80,000÷1.2÷1.05－36,000≈63,492－36,000≈27,492萬元，與本選項相符。","28,200萬元無法由題幹常見誤算得到；正確為80,000÷1.2÷1.05－36,000≈27,492萬元。"],"tr":"","core":["非常見誤算，應約27,492萬","非常見誤算，應約27,492萬","連除兩率再減36,000≈27,492萬","非常見誤算，應約27,492萬"],"hl":[["26,582萬元","27,492萬元"],["27,215萬元","27,492萬元"],[],["28,200萬元","27,492萬元"]]},{"id":"h:106-36","p":"h","src":"106年第36題","sec":"E1","stem":"有關土地開發分析法之估價程序中，最後四個步驟順序如何？","opts":["估算開發或建築後總銷售金額。選擇適當之利潤率及資本利息綜合利率。估算各項成本及相關費用。計算土地開發分析價格","估算各項成本及相關費用。估算開發或建築後總銷售金額。選擇適當之利潤率及資本利息綜合利率。計算土地開發分析價格","選擇適當之利潤率及資本利息綜合利率。估算開發或建築後總銷售金額。估算各項成本及相關費用。計算土地開發分析價格","估算開發或建築後總銷售金額。估算各項成本及相關費用。選擇適當之利潤率及資本利息綜合利率。計算土地開發分析價格"],"ok":[3],"ex":["「估算總銷售金額→選擇利潤率及資本利息綜合利率→估算成本費用→計算價格」此順序將選擇利潤率資本化率置於估算成本費用之前，與規則規定順序不符。","「估算成本費用→估算總銷售金額→選擇利潤率資本化率→計算價格」此順序將估算成本費用置於估算總銷售金額之前，順序顛倒。","「選擇利潤率資本化率→估算總銷售金額→估算成本費用→計算價格」此順序將選擇利潤率置於最前面，與規則規定應最後決定利潤率及資本化率之順序不符。","技術規則明定土地開發分析法估價程序最後四個步驟為：估算開發或建築後總銷售金額→估算各項成本及相關費用→選擇適當之利潤率及資本利息綜合利率→計算土地開發分析價格，與本選項完全相符。"],"tr":"","core":["利潤率與利率不應排在成本之前","估算成本不應排在總銷售金額之前","選擇利潤率不應排在最前面","銷售金額→成本→利潤率利率→計算價格"],"hl":[["選擇適當之利潤率及資本利息綜合利率。估算各項成本"],["估算各項成本及相關費用。估算開發或建築後總銷售金額"],["選擇適當之利潤率及資本利息綜合利率。估算開發","應最後決定利潤率及資本化率"],[]]},{"id":"h:107-10","p":"h","src":"107年第10題","sec":"E1","stem":"於採土地開發分析法之資本利息綜合利率之計算中，如果資本利息年利率為3%，土地價值比率為40%，建物價值比率為60%，開發年數為3年，請問資本利息綜合利率為何？","opts":["9%","6.3%","4.5%","3%"],"ok":[1],"ex":["9%的計算誤將土地與建物價值比率直接相加未打折（40%+60%=100%×3%×3年=9%），未正確套用建物比率折半之規定。","依資本利息綜合利率公式：資本利息年利率×(土地價值比率＋建物價值比率×1/2)×開發年數＝3%×(40%+60%×0.5)×3＝3%×0.7×3＝6.3%，與本選項相符。","4.5%是把土地與建物比率合計後整體乘1/2：3%×(40%＋60%)×1/2×3＝4.5%；§79只有建物比率乘1/2。","3%僅為資本利息年利率本身，未經過完整公式計算。"],"tr":"","core":["比率直接相加未打折的誤算","3%×(0.4＋0.6×½)×3＝6.3%","比率合計後整體乘1/2的誤算","只是年利率本身，未經公式計算"],"hl":[["9%","建物比率折半之規定"],[],["4.5%","§79只有建物比率乘1/2"],["3%"]]},{"id":"h:107-12","p":"h","src":"107年第12題","sec":"E1","stem":"當某土地開發後預期總銷售金額為1000萬元，適當之利潤率為12%，開發所需之直接成本為300萬元，開發所需之間接成本為250萬元，開發所需總成本之資本利息綜合利率為4%時，請問土地開發分析法價格大約為何？","opts":["433萬元","402萬元","386萬元","309萬元"],"ok":[3],"ex":["433萬元是先減成本再只除資本利息綜合利率：(1,000－550)÷1.04≈432.7萬元。","402萬元是先減成本再只除利潤率：(1,000－550)÷1.12≈401.8萬元。","386萬元是先減成本再連除兩率：(1,000－550)÷1.12÷1.04≈386.3萬元；§81應先除再減。","依公式V＝[S÷(1+r)÷(1+i)]－(C+M)＝[1,000÷(1+12%)÷(1+4%)]－(300+250)≈858.5－550＝308.5萬元，約309萬元，與本選項最接近。"],"tr":"","core":["先減成本再只除利率的誤算","先減成本再只除利潤率的誤算","先減成本再連除兩率，應先除再減","連除兩率再減550≈309萬"],"hl":[["433萬元"],["402萬元"],["386萬元","應先除再減"],[]]},{"id":"h:108-2","p":"h","src":"108年第2題","sec":"E1","stem":"有一筆建地面積1,000坪，預期興建為住宅大樓後的總銷售金額為3.8億元，若營建施工費為1億元，管理銷售及規劃設計等費用為1,100萬元，合理利潤率為16%，資本利息綜合利率為2%，請問該筆建地每坪單價約為：","opts":["210萬元","420萬元","21萬元","42萬元"],"ok":[2],"ex":["210萬元是單位換算錯一位（總價21,016萬÷100），正確為21,016萬÷1,000坪≈21萬元/坪。","420萬元的計算結果明顯偏高，與正確公式計算不符。","依公式V＝[S÷(1+r)÷(1+i)]－(C+M)，S＝38,000萬元，r＝16%，i＝2%，C＝10,000萬元（營建施工費即直接成本），M＝1,100萬元（管理銷售規劃設計費即間接成本），代入計算：[38,000÷1.16÷1.02]－11,100≈32,116.3－11,100＝21,016.3萬元；每坪單價＝21,016.3÷1,000≈21萬元，與本選項相符。","42萬元的計算結果是正確答案的兩倍，可能誤算面積基準。"],"tr":"","core":["單位換算錯一位的誤算","結果明顯偏高，與公式不符","總價約21,016萬÷1,000坪≈21萬","為答案的兩倍，誤算面積基準"],"hl":[["210萬元","21,016萬÷1,000坪≈21萬元/坪"],["420萬元"],[],["42萬元"]]},{"id":"h:109-10","p":"h","src":"109年第10題","sec":"E1","stem":"某一筆建築用地將以土地開發分析法推估價格，其資本利息綜合利率為4.8%，該土地開發之土地價值比率占60%，建物價值比率占40%，預計開發年數為2年，請問資本利息年利率應為多少？","opts":["2.4%","3.0%","7.68%","9.6%"],"ok":[1],"ex":["2.4%是4.8%÷2，只除了開發年數，漏了價值比率。","依§79：綜合利率＝年利率×(土地價值比率＋建物價值比率×½)×開發年數；4.8%＝年利率×(0.6＋0.4×½)×2＝年利率×1.6，年利率＝4.8%÷1.6＝3.0%，與本選項相符。","7.68%是4.8%×1.6，方向乘反了。","9.6%是4.8%×2，方向乘反了。"],"tr":"","core":["只除開發年數、漏了價值比率","年利率＝4.8%÷1.6＝3.0%","4.8%×1.6，方向乘反了","4.8%×2，方向乘反了"],"hl":[["2.4%","漏了價值比率"],[],["7.68%"],["9.6%"]]},{"id":"h:109-16","p":"h","src":"109年第16題","sec":"E1","stem":"某建築開發公司擬開發建地，開發或建築後預期總銷售金額估計8.8億元，開發直接成本3億元、間接成本8千萬元，開發商要求利潤率20%、資本利息綜合利率4%，試問土地開發分析價格多少？","opts":["32513萬元","31083萬元","30886萬元","30562萬元"],"ok":[0],"ex":["依公式V＝[S÷(1+r)÷(1+i)]－(C+M)＝[88,000÷(1+20%)÷(1+4%)]－(30,000+8,000)≈70,512.8－38,000＝32,512.8萬元，約32513萬元，與本選項相符。","31,083萬元無法由題幹常見誤算得到；正確為88,000÷1.2÷1.04－38,000≈32,513萬元。","30,886萬元無法由題幹常見誤算得到；正確為88,000÷1.2÷1.04－38,000≈32,513萬元。","30,562萬元無法由題幹常見誤算得到；正確為88,000÷1.2÷1.04－38,000≈32,513萬元。"],"tr":"","core":["連除兩率再減38,000≈32,513萬","非常見誤算，應約32,513萬","非常見誤算，應約32,513萬","非常見誤算，應約32,513萬"],"hl":[[],["31083萬元","32,513萬元"],["30886萬元","32,513萬元"],["30562萬元","32,513萬元"]]},{"id":"h:110-6","p":"h","src":"110年第6題","sec":"E1","stem":"有一500坪建地可興建大樓出售，預期新大樓之總銷售金額為10億元，若營建施工費為3億元、管理銷售費用等間接成本為9千萬元、要求的利潤率為18%、資本綜合利率為5%。請問該建地每坪價格約為多少？","opts":["100.5萬元","83.4萬元","65.8萬元","41.7萬元"],"ok":[1],"ex":["100.5萬元無法由題幹常見誤算得到；正確為(100,000÷1.18÷1.05－39,000)÷500≈83.4萬元/坪。","依公式V＝[S÷(1+r)÷(1+i)]－(C+M)，S＝100,000萬元，r＝18%，i＝5%，C＝30,000萬元（營建施工費即直接成本），M＝9,000萬元（管理銷售費用即間接成本），代入計算：[100,000÷1.18÷1.05]－39,000≈80,710.25－39,000＝41,710.25萬元；每坪價格＝41,710.25÷500≈83.42萬元，與本選項相符。","65.8萬元無法由題幹常見誤算得到；正確為(100,000÷1.18÷1.05－39,000)÷500≈83.4萬元/坪。","41.7萬元僅為總價格（41,710萬元）之數值近似誤用，並非每坪正確單價。"],"tr":"","core":["非常見誤算，應約83.4萬/坪","總價約41,710萬÷500坪≈83.4萬","非常見誤算，應約83.4萬/坪","總價數值誤當每坪單價"],"hl":[["100.5萬元","83.4萬元"],[],["65.8萬元","83.4萬元"],["41.7萬元","並非每坪正確單價"]]},{"id":"h:111-16","p":"h","src":"111年第16題","sec":"E1","stem":"某開發商擬於新開發區開發建築，預計興建樓板面積2,000坪。若推定銷售單價平均60萬元/坪，利潤率20%、資本利息綜合利率5%、直接成本2億元、間接成本4千萬元，請問土地開發分析價格多少萬元？","opts":["71,238","69,526","64,878","62,106"],"ok":[0],"ex":["依公式V＝[S÷(1+r)÷(1+i)]－(C+M)，S＝2,000坪×60萬元/坪＝120,000萬元，r＝20%，i＝5%，C＝20,000萬元，M＝4,000萬元，代入計算：[120,000÷1.2÷1.05]－24,000≈95,238.1－24,000＝71,238.1萬元，與本選項相符。","69,526萬元無法由題幹常見誤算得到；正確為120,000÷1.2÷1.05－24,000≈71,238萬元。","64,878萬元無法由題幹常見誤算得到；正確為120,000÷1.2÷1.05－24,000≈71,238萬元。","62,106萬元無法由題幹常見誤算得到；正確為120,000÷1.2÷1.05－24,000≈71,238萬元。"],"tr":"","core":["連除兩率再減24,000≈71,238萬","非常見誤算，應約71,238萬","非常見誤算，應約71,238萬","非常見誤算，應約71,238萬"],"hl":[[],["69,526","71,238萬元"],["64,878","71,238萬元"],["62,106","71,238萬元"]]},{"id":"h:111-25","p":"h","src":"111年第25題","sec":"E1","stem":"在土地開發分析法之估價程序中，應進行現況勘查與環境發展程度調查與分析，下列何者不屬於要勘查與調查分析的事項：","opts":["影響總銷售金額、成本及費用等因素","勘估標的之工程進度、施工及環境狀況","比較標的之工程進度、施工及環境狀況","週遭環境土地建物及公共設施開發程度"],"ok":[2],"ex":["影響總銷售金額、成本及費用等因素，是技術規則明定現況勘查應調查分析之事項之一，非本題答案（本題問「不屬於」應調查分析之事項）。","勘估標的之工程進度、施工及環境狀況，是技術規則明定應調查分析之事項之一。","技術規則明定現況勘查應調查分析之事項是「勘估標的」（而非比較標的）之工程進度施工及環境狀況，土地開發分析法並無蒐集「比較標的」工程進度之規定，即本題正解。","週遭環境土地建物及公共設施開發程度，是技術規則明定應調查分析之事項之一。"],"tr":"","core":["影響銷售金額成本因素應調查分析","勘估標的工程進度應調查分析","應調查勘估標的，非比較標的","週遭土地建物公設開發程度應調查"],"hl":[[],[],["比較標的","勘估標的"],[]]},{"id":"h:112-24","p":"h","src":"112年第24題","sec":"E1","stem":"如果一開發案開發後預期總銷售金額為新臺幣10億元，適當之利潤率為10%，開發所需之直接成本為新臺幣6億元，開發所需之間接成本為新臺幣2億元，開發所需總成本之資本利息綜合利率為5%。請問下列何者最接近此一開發案之土地開發分析價格？","opts":["新臺幣2億元","新臺幣1.5億元","新臺幣1.091億元","新臺幣0.658億元"],"ok":[3],"ex":["2億元是總銷售金額直接減成本（10－8），漏除(1＋R)(1＋i)。","1.5億元是只扣5%利息（10×95%－8），漏了利潤率，而且把除法誤用成乘法。","1.091億元是只除利潤率、漏除資本利息綜合利率（10÷1.1－8）。","依公式V＝[S÷(1+r)÷(1+i)]－(C+M)＝[10÷(1+10%)÷(1+5%)]－(6+2)（單位：億元）≈8.658－8＝0.658億元，與本選項最接近。"],"tr":"","core":["直接減成本，漏除(1＋R)(1＋i)","漏利潤率且把除法誤用成乘法","只除利潤率、漏除資本利息的誤算","10÷1.1÷1.05－8≈0.658億"],"hl":[["2億元","漏除(1＋R)(1＋i)"],["1.5億元","漏了利潤率"],["1.091億元","漏除資本利息綜合利率"],[]]},{"id":"h:114-12","p":"h","src":"114年第12題","sec":"E1","stem":"有關土地開發分析法之資本利息綜合利率之敘述何者正確？","opts":["資本利息綜合利率＝貸款利息年利率×（建物價值比率＋土地價值比率×1/2）×開發年數","資本利息綜合利率＝資本利息年利率×（建物價值比率＋土地價值比率×1/2）×開發年數","資本利息綜合利率＝資本利息年利率×（土地價值比率＋建物價值比率×1/2）×開發年數","資本利息綜合利率＝貸款利息年利率×（土地價值比率＋建物價值比率×1/2）×開發年數"],"ok":[2],"ex":["「貸款利息年利率」並非技術規則明定資本利息綜合利率公式所使用之變數名稱，規則使用之專有名詞為「資本利息年利率」；且括號內比例結構（建物比率＋土地比率×1/2）方向亦有誤。","公式中比例結構錯誤，技術規則明定應為「土地價值比率＋建物價值比率×1/2」（建物打折），本選項將建物與土地角色對調，方向錯誤。","§79 規定資本利息綜合利率公式為（§59 為自有資金與借款之計息利率）：資本利息年利率×(土地價值比率＋建物價值比率×1/2)×開發年數，與本選項完全相符。","「貸款利息年利率」用詞誤植（應為資本利息年利率），且雖然比例結構正確，但變數名稱誤植仍屬錯誤敘述。"],"tr":"","core":["應為資本利息年利率，且比例方向錯","土地建物角色對調，應建物打折","土地全額＋建物×1/2，乘開發年數","應為資本利息年利率，用詞誤植"],"hl":[["貸款利息年利率","建物價值比率＋土地價值比率×1/2","資本利息年利率"],["建物價值比率＋土地價值比率×1/2","土地價值比率＋建物價值比率×1/2"],[],["貸款利息年利率","應為資本利息年利率"]]},{"id":"h:99-5","p":"h","src":"99年第5題","sec":"F1","stem":"下列有關不動產租金估算之敘述，何者有誤？","opts":["以勘估標的之實質租金為原則","應視新訂租約與續訂租約分別為之","不可將權利金之收益列入計算","應將押金或保證金之收益列入計算"],"ok":[2],"ex":["技術規則明定不動產租金估計以勘估標的之實質租金為原則，此為正確敘述，非本題答案（本題問「何者有誤」）。","技術規則明定應視新訂租約與續訂租約分別為之，此為正確敘述。","技術規則明定實質租金應加計權利金及其他相關運用收益，本選項稱「不可將權利金收益列入計算」，與規則規定相反，敘述錯誤，即本題正解。","技術規則明定實質租金應將押金或保證金之收益列入計算，此為正確敘述。"],"tr":"","core":["租金估計以實質租金為原則","新訂與續訂租約應分別為之","實質租金應加計權利金收益","押金或保證金收益應列入計算"],"hl":[[],[],["不可","實質租金應加計權利金及其他相關運用收益"],[]]},{"id":"h:99-20","p":"h","src":"99年第20題","sec":"F1","stem":"根據不動產估價技術規則之規定，基於續定租約或不動產合併為目的形成之租賃價值，並以貨幣金額表示者，稱為：","opts":["正常租金","特定租金","限定租金","特殊價格"],"ok":[2],"ex":["正常租金是對應正常價格之概念，反映一般市場正常交易情況下之租賃價值，與題目所述「基於續訂租約或合併目的」之特定情境不符。","「特定租金」並非技術規則明定之正式租金種類名稱。","技術規則明定限定租金係基於續訂租約或不動產合併為目的形成之租賃價值，並以貨幣金額表示者，與題目敘述完全相符。","特殊價格是「價格」種類（非租金種類），指不具市場性之不動產所估計之價值，與題目所述租賃情境不符。"],"tr":"","core":["正常租金對應正常價格，情境不符","特定租金非正式租金種類名稱","續訂租約或合併目的＝限定租金","特殊價格是價格種類，非租金"],"hl":[["正常租金","反映一般市場正常交易情況下之租賃價值"],["特定租金"],[],["特殊價格","「價格」種類（非租金種類）"]]},{"id":"h:100-33","p":"h","src":"100年第33題","sec":"F1","stem":"不動產於市場上以最有效利用方式利用所能產生的收益，稱為：","opts":["支付租金","實質租金","差額租金","經濟租金"],"ok":[3],"ex":["支付租金是承租人實際支付予出租人之租金本身，並非「最有效利用方式所能產生之收益」此一市場概念。","實質租金是支付租金加計押金等運用收益之總數，並非市場最有效利用所能產生之收益概念。","「差額租金」並非技術規則明定之正式租金種類名稱（差額分配法是續訂租約估計方法之一，非租金種類本身）。","依教材，經濟租金係指不動產於市場上以最有效利用方式利用所能產生的收益，與題目敘述完全相符。"],"tr":"","core":["支付租金是實際支付的租金本身","實質租金是支付租金加運用收益","差額租金非正式租金種類名稱","最有效利用所能產生收益＝經濟租金"],"hl":[["支付租金","承租人實際支付予出租人之租金本身"],["實質租金","支付租金加計押金等運用收益之總數"],["差額租金","差額分配法是續訂租約估計方法之一"],[]]},{"id":"h:100-37","p":"h","src":"100年第37題","sec":"F1","stem":"以差額租金還原法所得出之價格為：","opts":["所有權價格","經濟租金","實質租金","租賃權價格"],"ok":[3],"ex":["「所有權價格」是不動產所有權本身之價值概念，與差額租金還原法（用於估算租賃權相關價值之方法）所得出之價格性質不同。","經濟租金是差額分配法計算過程中之輸入變數之一，並非還原法所得出之最終結果。","實質租金同樣是計算過程中之概念，並非還原法之最終結果。","差額租金還原法是將市場經濟租金與原契約租金之差額（承租人因租賃關係所獲得之超額利益）資本化還原所得出之價值，性質上即為承租人享有之「租賃權價格」，與題目敘述相符。"],"tr":"","core":["所有權價格與租賃權價值性質不同","經濟租金是計算過程的輸入變數","實質租金是計算過程中的概念","租金差額資本化還原＝租賃權價格"],"hl":[["所有權價格","估算租賃權相關價值"],["經濟租金","差額分配法計算過程中之輸入變數"],["實質租金"],[]]},{"id":"h:100-39","p":"h","src":"100年第39題","sec":"F1","stem":"林乙向王甲承租房屋，每月支付的實質租金為10,000元，這棟房屋如於市場上重新出租，合理租金為16,000元。假設王甲、林乙對該租金增加的貢獻各半，請問於王甲考慮續約的情況下，其合理的租金應該調整為多少？","opts":["10,000元","13,000元","16,000元","19,000元"],"ok":[1],"ex":["10,000元僅為原契約租金本身，未反映續約時租金應有之合理調整。","差額分配法計算：市場租金與原租金之差額＝16,000－10,000＝6,000元；雙方貢獻各半，出租人應分得差額之一半＝6,000×50%＝3,000元；續約合理租金＝原租金10,000＋出租人應分得差額3,000＝13,000元，與本選項相符。","16,000元是完全採用市場新訂租金，未考量承租人對租金上漲之貢獻，與差額分配法精神不符。","19,000元是把出租人應分得的差額3,000元誤加在市場租金16,000元上；§133第4款是把差額中應歸屬於出租人的部分「加計契約租金」10,000元。"],"tr":"","core":["只是原租金，未反映續約調整","差額6,000×50%加原租＝13,000","全採市場租金，未考量承租人貢獻","差額誤加在市場租金上的誤算"],"hl":[["10,000元"],[],["16,000元","未考量承租人對租金上漲之貢獻"],["19,000元","差額中應歸屬於出租人的部分「加計契約租金」"]]},{"id":"h:100-40","p":"h","src":"100年第40題","sec":"F1","stem":"依不動產估價技術規則規定，承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數，稱為？","opts":["純租金","支付租金","實質租金","經濟租金"],"ok":[2],"ex":["「純租金」並非技術規則明定之正式租金種類名稱。","支付租金是承租人每期實際支付之租金本身，並未加計押金保證金等其他運用收益，與題目所述「加計」之完整定義不符。","技術規則明定實質租金係承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數，與題目敘述完全相符。","經濟租金是以最有效利用方式所能產生之市場收益概念，與題目所述「支付租金加計押金等運用收益」之加總定義不同。"],"tr":"","core":["純租金非正式租金種類名稱","支付租金未加計押金等運用收益","支付租金加計押金權利金等＝實質租金","經濟租金是最有效利用的市場收益"],"hl":[["純租金"],["支付租金","每期實際支付之租金本身"],[],["經濟租金","以最有效利用方式所能產生之市場收益概念"]]},{"id":"h:101-20","p":"h","src":"101年第20題","sec":"F1","stem":"新訂租約租金之估計，得分析企業經營之總收入，據以估計勘估標的在一定期間內之何種收益，再加計必要費用？","opts":["總收益","毛收益","有效總收益","淨收益"],"ok":[3],"ex":["「總收益」是未扣除費用之毛收入概念，與技術規則明定新訂租約估計應求取「淨收益」之概念不同。","「毛收益」同樣是未扣除費用之概念，與淨收益定義不同。","「有效總收益」是扣除空置損失後之收入概念，但仍非完全等同於扣除總費用後之「淨收益」。","技術規則明定新訂租約租金之估計，得分析企業經營之總收入，據以估計勘估標的在一定期間內之淨收益，再加計必要費用，與題目敘述完全相符。"],"tr":"","core":["總收益未扣費用，應求淨收益","毛收益未扣費用，非淨收益","有效總收益仍非扣總費用後淨收益","估計淨收益，再加計必要費用"],"hl":[["總收益","未扣除費用之毛收入概念"],["毛收益","未扣除費用之概念"],["有效總收益","扣除空置損失後之收入概念"],[]]},{"id":"h:101-32","p":"h","src":"101年第32題","sec":"F1","stem":"下列何者能反映租賃不動產經濟價值的租金？","opts":["實質租金","經濟租金","支付租金","差額租金"],"ok":[1],"ex":["實質租金是支付租金加計押金等運用收益之總數，反映的是「租賃契約安排下」的租金總額，非直接反映市場經濟價值。","依教材，經濟租金係指不動產於市場上以最有效利用方式利用所能產生的收益，直接反映租賃不動產之經濟價值，與題目敘述相符。","支付租金是承租人實際支付之租金本身，反映的是契約安排下之金額，非市場經濟價值。","「差額租金」並非技術規則明定之正式租金種類名稱。"],"tr":"","core":["實質租金反映契約安排，非經濟價值","經濟租金反映租賃不動產經濟價值","支付租金反映契約金額，非經濟價值","差額租金非正式租金種類名稱"],"hl":[["實質租金","支付租金加計押金等運用收益之總數"],[],["支付租金","承租人實際支付之租金本身"],["差額租金"]]},{"id":"h:102-21","p":"h","src":"102年第21題","sec":"F1","stem":"T市東區某店面於5年前出租經營，現到期擬續租，當年簽約契約租金每年新臺幣250萬元，目前市場經濟租金每年可達新臺幣350萬元，若分析此租金上漲應有60%歸功於承租經營者，在相關必要費用不增加情況下，最合理之續租租約年租金為何？","opts":["新臺幣250萬元","新臺幣290萬元","新臺幣310萬元","新臺幣350萬元"],"ok":[1],"ex":["新臺幣250萬元僅為原契約租金本身，未反映續約時租金應有之合理調整。","差額分配法計算：市場經濟租金與原契約租金之差額＝350－250＝100萬元；承租經營者應有貢獻60%，故出租人應分得差額之40%＝100×40%＝40萬元；續租合理租金＝原契約租金250＋出租人應分得差額40＝290萬元，與本選項相符。","310萬元是把承租人應得的60%誤歸給出租人：250＋100×60%＝310萬元；出租人只應分得40%。","新臺幣350萬元是完全採用市場經濟租金，未考量承租經營者之貢獻，與差額分配法精神不符。"],"tr":"","core":["只是原契約租金，未反映續約調整","250＋100×40%＝290萬","承租人應得60%誤歸出租人","全採市場經濟租金，未考量承租人貢獻"],"hl":[["250萬元"],[],["310萬元","出租人只應分得40%"],["350萬元","未考量承租經營者之貢獻"]]},{"id":"h:103-2","p":"h","src":"103年第2題","sec":"F1","stem":"不動產租金估計，以估計勘估標的之何種租金為原則？","opts":["支付租金","契約租金","實質租金","押租金"],"ok":[2],"ex":["支付租金是承租人實際支付之租金本身，並非規則明定租金估計之原則性基準（實質租金才是包含支付租金及其他運用收益之完整概念）。","契約租金是依租賃契約約定之租金，並非規則明定租金估計之原則性基準。","技術規則明定不動產租金估計，以估計勘估標的之實質租金為原則，與題目敘述完全相符。","「押租金」並非技術規則明定租金估計之原則性基準用語。"],"tr":"","core":["支付租金非租金估計的原則基準","契約租金非租金估計的原則基準","租金估計以實質租金為原則","押租金非租金估計的原則用語"],"hl":[["支付租金","實質租金才是包含支付租金及其他運用收益之完整概念"],["契約租金"],[],["押租金"]]},{"id":"h:103-38","p":"h","src":"103年第38題","sec":"F1","stem":"甲向其好友乙承租房屋乙棟，約定每月租金為25,000元，此租金低於合理租金5,000元，押金為2個月租金，押金運用收益率2%。請問該房屋每年之支付租金為何？","opts":["361,000元","360,000元","301,000元","300,000元"],"ok":[3],"ex":["361,000元是誤用合理租金30,000元×12，再加押金運用收益1,000元。","360,000元是誤用合理租金（25,000＋5,000）×12。","301,000元是支付租金300,000元加押金運用收益1,000元，即「實質租金」，不是題目問的支付租金。","支付租金係承租人每期實際支付予出租人之租金本身，即月租金25,000元×12個月＝300,000元，與本選項相符。注意：題目所述「低於合理租金5,000元」「押金2個月」「押金運用收益率2%」等資訊是計算「實質租金」或「合理租金」時才需要的條件，本題問的是「支付租金」，僅需單純的月租×12即可，不應將其他因素納入。"],"tr":"","core":["誤用合理租金再加押金收益","誤用合理租金30,000×12","加了押金收益是實質租金","支付租金＝月租25,000×12"],"hl":[["361,000元"],["360,000元"],["301,000元","即「實質租金」"],[]]},{"id":"h:104-24","p":"h","src":"104年第24題","sec":"F1","stem":"某甲將透天厝出租於某乙使用，雙方約定每月租金為35,000元，押金兩個月，定存年利率設為1.5%，則下列何者為其一年之實質租金？","opts":["71,050元","420,000元","421,050元","701,050元"],"ok":[2],"ex":["71,050元是押金加上利息，不是租金。","420,000元只是一年的支付租金，漏加押金運用收益。","實質租金＝支付租金＋押金運用收益＝35,000×12＋35,000×2×1.5%＝420,000＋1,050＝421,050元，與本選項相符。","701,050元無法由題幹常見誤算得到；正確為35,000×12＋35,000×2×1.5%＝421,050元。"],"tr":"","core":["押金加利息，不是租金","只是支付租金，漏加押金運用收益","支付租金加押金收益1,050＝421,050","非常見誤算，應為421,050元"],"hl":[["71,050元"],["420,000元","漏加押金運用收益"],[],["701,050元","421,050元"]]},{"id":"h:104-25","p":"h","src":"104年第25題","sec":"F1","stem":"下列何者不是不動產租金估計時應考慮的因素？","opts":["出租人數","使用目的","租期長短","稅費負擔"],"ok":[0],"ex":["技術規則§129明定租金估計應考慮之因素為契約內容、租期長短、使用目的、稅費負擔、租金水準、變遷狀態、租約更新、變更條件及其他相關因素，「出租人數」並非規則明定應考慮之因素，即本題正解。","使用目的是技術規則明定應考慮之因素之一，非本題答案（本題問「不是」應考慮之因素）。","租期長短是技術規則明定應考慮之因素之一。","稅費負擔是技術規則明定應考慮之因素之一。"],"tr":"","core":["出租人數非應考慮之因素","使用目的是應考慮因素之一","租期長短是應考慮因素之一","稅費負擔是應考慮因素之一"],"hl":[["出租人數","契約內容、租期長短、使用目的、稅費負擔"],[],[],[]]},{"id":"h:104-33","p":"h","src":"104年第33題","sec":"F1","stem":"續訂租約之租金估計，得採下列那些方式為之？①以續訂租約之租賃實例為標的，運用收益法估計之　②勘估標的價格乘以租金收益率，以估計淨收益，再加計必要費用　③以勘估標的原契約租金之淨收益，就其租金變動趨勢調整後，再加計必要費用　④分析企業經營之總收入，據以估計勘估標的在一定期間內之淨收益，再加計必要費用。","opts":["①②④","①③","僅③","③④"],"ok":[2],"ex":["①②④含①與④：①寫「收益法」，§133一規定的是以續訂租約租賃實例為標的、採比較法；④分析企業經營總收入屬新訂租約方式（§132），不屬續訂。","①③含①：①把「比較法」寫成「收益法」，用語錯誤，不可選。","考選部標準答案。續訂租約§133：一、續訂租約租賃實例→比較法；二、價格日期當時正常價格乘租金收益率；三、原契約租金之淨收益依租金變動趨勢調整後加必要費用；四、差額分配法。題幹①誤寫收益法、②寫「勘估標的價格」而非「價格日期當時之正常價格」、④屬新訂（§132），故只有③完全符合。","③④含④：企業經營總收入屬新訂租約（§132），不屬續訂。"],"tr":"","core":["①應採比較法，④屬新訂租約","①把比較法寫成收益法","續訂只有③原契約租金調整法符合","④企業經營總收入屬新訂租約"],"hl":[["①②④","以續訂租約租賃實例為標的"],[],[],["企業經營總收入屬新訂租約（§132）"]]},{"id":"h:104-34","p":"h","src":"104年第34題","sec":"F1","stem":"不動產租金估計，以估計勘估標的之實質租金為原則。此處實質租金指包括下列那些收益？①承租人每期支付予出租人之租金　②押金運用收益　③保證金運用收益　④權利金運用收益","opts":["僅②④","①②③④","僅①③","僅①②"],"ok":[1],"ex":["僅②④遺漏①③，①承租人支付租金本身與③保證金運用收益皆是實質租金應包含之內容，不應遺漏。","技術規則明定實質租金包含①承租人每期支付予出租人之租金、②押金運用收益、③保證金運用收益、④權利金運用收益，與本選項①②③④全選完全相符。","僅①③遺漏②④，押金運用收益與權利金運用收益皆是實質租金應包含之內容，不應遺漏。","僅①②遺漏③④，保證金運用收益與權利金運用收益皆是實質租金應包含之內容，不應遺漏。"],"tr":"","core":["漏了①支付租金與③保證金收益","實質租金＝支付租金＋三項運用收益","漏了②押金與④權利金收益","漏了③保證金與④權利金收益"],"hl":[["僅②④","皆是實質租金應包含之內容"],[],["僅①③","皆是實質租金應包含之內容"],["僅①②","皆是實質租金應包含之內容"]]},{"id":"h:104-40","p":"h","src":"104年第40題","sec":"F1","stem":"下列何者最適合用來推估不動產租金？","opts":["殘餘法","資本化率法","還原利率法","差額分配法"],"ok":[3],"ex":["殘餘法是成本法或收益法延伸應用之計算技巧（如土地建物價值分離計算），並非規則明定用以推估不動產租金之專屬方法。","「資本化率法」並非技術規則明定推估不動產租金之正式方法名稱。","「還原利率法」並非技術規則明定推估不動產租金之正式方法名稱。","差額分配法（教材名稱）即§133第4款續訂租約租金估計方式：分析原契約租金與市場經濟租金之差額中應歸屬於出租人之適當部分，加計契約租金，是專用於租金估計的方法，故選之。"],"tr":"","core":["殘餘法是計算技巧，非租金專屬方法","資本化率法非正式租金估計方法","還原利率法非正式租金估計方法","差額分配法專用於續訂租金估計"],"hl":[["殘餘法","成本法或收益法延伸應用之計算技巧"],["資本化率法"],["還原利率法"],[]]},{"id":"h:105-20","p":"h","src":"105年第20題","sec":"F1","stem":"有關租金估價的敘述，下列何者正確？","opts":["續訂租約之租金屬正常租金","不動產租金估計，應視新訂租約與續訂租約分別為之","淨租金指承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數","不動產租金估計，以估計勘估標的之支付租金為原則"],"ok":[1],"ex":["續訂租約之租金屬於「限定租金」（基於續訂租約之特定情境形成），而非正常租金，本選項與規則規定不符。","技術規則明定不動產租金估計，應視新訂租約與續訂租約分別為之（因兩者估計方式不同），與題目敘述完全相符。","技術規則明定的是「實質租金」（而非淨租金）之定義為承租人每期支付租金加計押金保證金權利金等運用收益之總數，本選項用詞誤植。","技術規則明定不動產租金估計以估計勘估標的之「實質租金」（而非支付租金）為原則，本選項與規則規定不符。"],"tr":"","core":["續訂租約租金屬限定租金","新訂與續訂租約應分別估計","該定義是實質租金，非淨租金","以實質租金為原則，非支付租金"],"hl":[["正常租金","限定租金"],[],["淨租金","「實質租金」"],["支付租金","「實質租金」"]]},{"id":"h:105-26","p":"h","src":"105年第26題","sec":"F1","stem":"有一不動產每月租金5000元，押金2個月，押金存款年利率5%，請計算其一年實質租金。","opts":["60000元","5500元","60500元","70000元"],"ok":[2],"ex":["60,000元僅為單純年租金收入（5,000×12），未加計押金運用收益。","5,500元是把1個月租金5,000元加押金運用收益500元（5,000×2×5%），漏乘12個月；年實質租金應為60,000＋500＝60,500元。","年租金收入＝5,000×12＝60,000元；押金運用收益＝(5,000×2)×5%＝500元；實質租金＝60,000＋500＝60,500元，與本選項相符。","70,000元是把押金2個月當租金加入（5,000×14），押金本身不是租金，只計其運用收益500元。"],"tr":"","core":["只算年租金，未加押金運用收益","漏乘12個月的誤算","60,000＋押金收益500＝60,500","押金誤當租金，只計運用收益"],"hl":[["60000元","未加計押金運用收益"],["5500元","年實質租金應為60,000＋500＝60,500元"],[],["70000元","押金本身不是租金，只計其運用收益500元"]]},{"id":"h:105-27","p":"h","src":"105年第27題","sec":"F1","stem":"有關不動產租金之估計，以估計勘估標的之何種租金為原則？","opts":["契約租金","實質租金","支付租金","押租金"],"ok":[1],"ex":["契約租金是依租賃契約約定之租金，並非規則明定租金估計之原則性基準。","技術規則明定不動產租金之估計，以估計勘估標的之實質租金為原則，與題目敘述完全相符。","支付租金是承租人實際支付之租金本身，並非規則明定租金估計之原則性基準。","「押租金」並非技術規則明定租金估計之原則性基準用語。"],"tr":"","core":["契約租金非租金估計的原則基準","租金估計以實質租金為原則","支付租金非租金估計的原則基準","押租金非租金估計的原則用語"],"hl":[["契約租金"],[],["支付租金"],["押租金"]]},{"id":"h:106-4","p":"h","src":"106年第4題","sec":"F1","stem":"如您於捷運地下街承租營運中，隔壁店家因故不與捷運局續租，此時您打算一併承租擴大經營，所承租之租金屬性應屬下列何者？","opts":["市場租金","正常租金","經濟租金","限定租金"],"ok":[3],"ex":["「市場租金」並非技術規則明定之正式租金種類名稱。","正常租金反映一般市場正常交易情況下之租賃價值，本題承租人因隔壁店家不續租而擴大承租，屬於「不動產合併」之特定情境，非一般正常交易。","經濟租金是以最有效利用方式所能產生之市場收益概念，與題目所述「合併承租」之特定情境定義不同。","技術規則明定限定租金係基於續訂租約或「不動產合併」為目的形成之租賃價值，原承租店面與隔壁店家合併擴大經營，正是不動產合併目的之典型情境，與題目敘述相符。"],"tr":"","core":["市場租金非正式租金種類名稱","合併承租屬特定情境，非正常租金","經濟租金是最有效利用的市場收益","不動產合併為目的＝限定租金"],"hl":[["市場租金"],["正常租金","屬於「不動產合併」之特定情境"],["經濟租金","「合併承租」之特定情境"],[]]},{"id":"h:106-18","p":"h","src":"106年第18題","sec":"F1","stem":"西門町某店面於3年前出租經營，到期擬續租，當年契約租金每年200萬元，目前市場經濟租金每年可達250萬元，若分析此租金上漲應有60%歸功於承租經營者，在必要費用不增加情況下，合理續租年租金多少？","opts":["220萬元","230萬元","240萬元","250萬元"],"ok":[0],"ex":["差額分配法計算：市場經濟租金與原契約租金之差額＝250－200＝50萬元；承租經營者應有貢獻60%，故出租人應分得差額之40%＝50×40%＝20萬元；合理續租年租金＝原契約租金200＋出租人應分得差額20＝220萬元，與本選項相符。","230萬元是把承租人應得的60%誤歸出租人：200＋50×60%＝230萬元。","240萬元無法由題幹常見誤算得到；正確為200＋50×40%＝220萬元。","250萬元是完全採用市場經濟租金，未考量承租經營者之貢獻，與差額分配法精神不符。"],"tr":"","core":["200＋50×40%＝220萬","承租人應得60%誤歸出租人","非常見誤算，應為220萬","全採市場經濟租金，未考量承租人貢獻"],"hl":[[],["230萬元","把承租人應得的60%誤歸出租人"],["240萬元","200＋50×40%＝220萬元"],["250萬元","未考量承租經營者之貢獻"]]},{"id":"h:106-24","p":"h","src":"106年第24題","sec":"F1","stem":"某私立學校為達校產活化目的，二年前將校舍之一部分出租予另一間外語學校，今年屆期想再續約，教育主管機構要求須附估價報告書供審查，此時所估之租金在目前的估價法規被歸類為下列何者﹖","opts":["正常租金","限定租金","特定租金","特殊租金"],"ok":[1],"ex":["正常租金反映一般市場正常交易情況下之租賃價值，本題校產出租再續約之估價，屬於續訂租約之特定情境，非一般正常交易。","技術規則明定限定租金係基於「續訂租約」或不動產合併為目的形成之租賃價值，私立學校校產出租到期擬續約之估價情境，正是續訂租約之典型應用，與題目敘述相符。","「特定租金」並非技術規則明定之正式租金種類名稱。","「特殊租金」並非技術規則明定之正式租金種類名稱。"],"tr":"","core":["續約屬特定情境，非正常租金","續訂租約為目的＝限定租金","特定租金非正式租金種類名稱","特殊租金非正式租金種類名稱"],"hl":[["正常租金","屬於續訂租約之特定情境"],[],["特定租金"],["特殊租金"]]},{"id":"h:107-1","p":"h","src":"107年第1題","sec":"F1","stem":"某便利商店需承租兩間相鄰之店面，兩間店面打通後合併使用之總面積方符合公司之需求。請問此二間店面合併為目的形成之租賃價值，以貨幣金額表示者稱為：","opts":["正常租金","特殊租金","限定租金","合併租金"],"ok":[2],"ex":["正常租金反映一般市場正常交易情況下之租賃價值，本題兩間店面為合併使用而承租，已附加特定合併條件，非一般正常交易。","「特殊租金」並非技術規則明定之正式租金種類名稱。","技術規則明定限定租金係基於續訂租約或「不動產合併」為目的形成之租賃價值，並以貨幣金額表示者，兩間相鄰店面合併承租正是不動產合併目的之典型情境，與題目敘述相符。","「合併租金」並非技術規則明定之正式租金種類名稱（雖描述了合併情境，但規則正式用語為限定租金）。"],"tr":"","core":["合併使用屬特定條件，非正常租金","特殊租金非正式租金種類名稱","不動產合併為目的＝限定租金","正式用語是限定租金，非合併租金"],"hl":[["正常租金","已附加特定合併條件"],["特殊租金"],[],["合併租金","規則正式用語為限定租金"]]},{"id":"h:107-25","p":"h","src":"107年第25題","sec":"F1","stem":"依不動產估價技術規則規定，承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數，稱為：","opts":["純租金","支付租金","實質租金","經濟租金"],"ok":[2],"ex":["「純租金」並非技術規則明定之正式租金種類名稱。","支付租金是承租人每期實際支付之租金本身，並未加計押金保證金等其他運用收益，與題目所述「加計」之完整定義不符。","技術規則明定實質租金係承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數，與題目敘述完全相符。","經濟租金是以最有效利用方式所能產生之市場收益概念，與題目所述「支付租金加計押金等運用收益」之加總定義不同。"],"tr":"","core":["純租金非正式租金種類名稱","支付租金未加計押金等運用收益","支付租金加計押金權利金等＝實質租金","經濟租金是最有效利用的市場收益"],"hl":[["純租金"],["支付租金","每期實際支付之租金本身"],[],["經濟租金","以最有效利用方式所能產生之市場收益概念"]]},{"id":"h:110-13","p":"h","src":"110年第13題","sec":"F1","stem":"依不動產估價技術規則規定，下列有關租金之兩種敘述，何者正確？","opts":["不動產租金估計，以估計勘估標的之實質租金為原則；以不動產證券化為估價目的，採折現現金流量分析法估價時，各期淨收益應以勘估標的之經濟租金計算為原則","不動產租金估計，以估計勘估標的之契約租金為原則；以不動產證券化為估價目的，採折現現金流量分析法估價時，各期淨收益應以勘估標的之經濟租金計算為原則","不動產租金估計，以估計勘估標的之實質租金為原則；以不動產證券化為估價目的，採折現現金流量分析法估價時，各期淨收益應以勘估標的之契約租金計算為原則","不動產租金估計，以估計勘估標的之契約租金為原則；以不動產證券化為估價目的，採折現現金流量分析法估價時，各期淨收益亦以勘估標的之契約租金計算為原則"],"ok":[2],"ex":["技術規則明定不動產證券化DCF估價各期淨收益應以「契約租金」（而非經濟租金）計算為原則，本選項後半段租金種類誤植。","技術規則明定不動產租金估計以「實質租金」（而非契約租金）為原則，本選項前半段租金種類誤植。","技術規則明定不動產租金估計以勘估標的之實質租金為原則；以不動產證券化為估價目的，採DCF估價時，各期淨收益應以勘估標的之契約租金計算為原則，與本選項完全相符。","前半段「以契約租金為原則」與規則明定之「實質租金」不符，本選項雙重錯誤。"],"tr":"","core":["證券化DCF應以契約租金，非經濟租金","租金估計以實質租金，非契約租金","實質租金為原則；證券化DCF用契約租金","前半應以實質租金為原則"],"hl":[["經濟租金","應以「契約租金」"],["契約租金為原則","經濟租金","「實質租金」"],[],["契約租金為原則","「實質租金」"]]},{"id":"h:110-22","p":"h","src":"110年第22題","sec":"F1","stem":"勘估標的丙之市場價格1,000萬元，經分析當地同類型不動產之租金收益率5%，必要費用20萬元/年，租賃所得稅約2萬元。若丙為新訂租約，根據上開資料估計之年租金為？","opts":["50萬元","52萬元","70萬元","72萬元"],"ok":[2],"ex":["50萬元僅為市場價格×租金收益率之結果（1,000×5%），未加計必要費用，計算不完整。","52萬元是把租賃所得稅2萬元誤當必要費用加計、卻漏加真正的必要費用20萬元（50＋2）。","依§132第2款，年租金＝勘估標的價格×租金收益率＋必要費用＝1,000×5%＋20＝70萬元；租賃所得稅是出租人個人所得的課稅，依教材不屬於不動產的必要費用（§38列舉的總費用項目也不含所得稅），所以不加計。","72萬元是把租賃所得稅2萬元也當必要費用加進去（50＋20＋2）；依教材，所得稅屬出租人個人稅負，不是租金估計應加計的必要費用。"],"tr":"","core":["只算價格×收益率，未加必要費用","所得稅誤當必要費用，漏加20萬","1,000×5%＋必要費用20＝70萬","所得稅屬個人稅負，不應加計"],"hl":[["50萬元","未加計必要費用"],["52萬元","漏加真正的必要費用20萬元"],[],["72萬元","所得稅屬出租人個人稅負"]]},{"id":"h:110-23","p":"h","src":"110年第23題","sec":"F1","stem":"續訂租約之租金估計方法中，差額分配法係指下列何種差額？","opts":["市場經濟租金與原契約租金之差額","原實質租金與市場經濟租金之差額","市場正常租金與原實質租金之差額","原契約租金與市場正常租金之差額"],"ok":[0],"ex":["依§133第4款（教材稱差額分配法），係分析勘估標的「原契約租金與市場經濟租金之差額」中應歸屬於出租人之適當部分，加計契約租金，與本選項相符。","「原實質租金與市場經濟租金之差額」並非技術規則明定差額分配法之正確定義，規則明定的比較對象是原契約租金而非原實質租金。","「市場正常租金與原實質租金之差額」同樣與規則明定之差額分配法定義不符。","「原契約租金與市場正常租金之差額」順序描述雖接近，但規則明定的對比對象是「市場經濟租金」（而非市場正常租金），用詞誤植。"],"tr":"","core":["差額＝市場經濟租金與原契約租金","比較對象是原契約租金，非實質租金","與差額分配法定義不符","對比對象是市場經濟租金，非正常租金"],"hl":[[],["原實質租金","規則明定的比較對象是原契約租金"],["市場正常租金與原實質租金"],["市場正常租金","市場經濟租金"]]},{"id":"h:112-13","p":"h","src":"112年第13題","sec":"F1","stem":"不動產租金估計，以估計勘估標的之何種租金為原則？","opts":["市場租金","差額租金","實質租金","經濟租金"],"ok":[2],"ex":["「市場租金」並非技術規則明定租金估計之原則性基準用語。","「差額租金」並非技術規則明定之正式租金種類名稱。","技術規則明定不動產租金估計，以估計勘估標的之實質租金為原則，與題目敘述完全相符。","經濟租金（依教材，指不動產以最有效使用方式所能產生的市場租金）不是§130所定的原則；§130明定租金估計以估計勘估標的之「實質租金」為原則。"],"tr":"","core":["市場租金非租金估計的原則用語","差額租金非正式租金種類名稱","租金估計以實質租金為原則","原則是實質租金，非經濟租金"],"hl":[["市場租金"],["差額租金"],[],["經濟租金","以估計勘估標的之「實質租金」為原則"]]},{"id":"h:112-17","p":"h","src":"112年第17題","sec":"F1","stem":"有關不動產租金估計之敘述，下列何者正確？","opts":["不動產租金估計，以估計勘估標的之承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數為原則","新訂租約之租金估計得以勘估標的預估契約租金之淨收益，估計租金未來變動趨勢調整後，再加計必要費用","續訂租約之租金估計得以勘估標的價格乘以租金收益率，以估計淨收益，再加計必要費用","不動產之租金估計不應考慮使用目的"],"ok":[0],"ex":["技術規則明定不動產租金估計，以估計勘估標的之承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數（即實質租金）為原則，與題目敘述完全相符。","本選項描述的「以勘估標的預估契約租金之淨收益，估計租金未來變動趨勢調整後加計必要費用」較接近續訂租約之估計方式（依原契約租金調整趨勢），而非新訂租約之估計方式，本選項適用情境誤植。","本選項描述的「以勘估標的價格乘以租金收益率估計淨收益」是新訂租約之估計方式之一，並非續訂租約之估計方式，本選項適用情境誤植。","技術規則明定租金估計應考慮使用目的等因素，本選項稱「不應考慮使用目的」，與規則規定相反。"],"tr":"","core":["以支付租金加計各項運用收益為原則","原契約租金趨勢調整屬續訂租約","價格×租金收益率屬新訂租約","租金估計應考慮使用目的"],"hl":[[],["新訂租約","續訂租約之估計方式"],["續訂租約","新訂租約之估計方式"],["不應","應考慮使用目的"]]},{"id":"h:113-5","p":"h","src":"113年第5題","sec":"F1","stem":"下列有關租金估計的敘述何者錯誤？","opts":["租金估價的價格種類包括正常租金與限定租金兩種","名目租金，指承租人每期支付予出租人之租金，加計押金或保證金、權利金及其他相關運用收益之總數","續訂租金與正常市場租金不同，故續訂租金屬於限定租金","積算法用於評估正常租金"],"ok":[1],"ex":["技術規則明定租金估價之價格種類包括正常租金與限定租金兩種，此為正確敘述，非本題答案（本題問「何者錯誤」）。","技術規則明定的是「實質租金」（而非名目租金）之定義為承租人每期支付租金加計押金保證金權利金等運用收益之總數，本選項將實質租金誤植為名目租金，敘述錯誤，即本題正解。","續訂租金與正常市場租金不同（因受原契約租金及承租人貢獻等因素影響），故續訂租金屬於限定租金，此為正確敘述。","積算法（教材名稱，即§132第2款「勘估標的價格乘以租金收益率，以估計淨收益，再加計必要費用」）用於估計新訂租約之正常租金，此為正確敘述。"],"tr":"","core":["租金種類包括正常租金與限定租金","該定義是實質租金，非名目租金","續訂租金不同於市場租金，屬限定租金","積算法用於估計新訂正常租金"],"hl":[[],["名目租金","「實質租金」"],[],[]]},{"id":"h:113-19","p":"h","src":"113年第19題","sec":"F1","stem":"A把忠孝東路五段鄰近市政府的店面出租給一間連鎖咖啡店，每月租金100,000元，押金2個月，假設年利率2.5%，約定每年管理費120,000元由咖啡店支付，請問其一年支付之實質租金為多少元？","opts":["1,200,000","1,205,000","1,085,000","1,080,000"],"ok":[1],"ex":["1,200,000元僅為單純年租金收入（100,000×12），未加計押金運用收益。","年租金收入＝100,000×12＝1,200,000元；押金運用收益＝(100,000×2)×2.5%＝5,000元；實質租金＝1,200,000＋5,000＝1,205,000元，與本選項相符。注意：管理費120,000元由咖啡店另行支付，屬於租金以外之費用負擔約定，不影響出租人收取之實質租金計算。","1,085,000元的計算誤將管理費120,000元自租金中扣除，但管理費並非租金之減項，計算邏輯有誤。","1,080,000元同樣誤將管理費納入扣除計算，且未加計押金運用收益，計算邏輯有誤。"],"tr":"","core":["只算年租金，未加押金運用收益","1,200,000＋押金收益5,000","管理費誤當租金減項的誤算","誤扣管理費且漏加押金收益"],"hl":[["1,200,000","未加計押金運用收益"],[],["1,085,000","管理費並非租金之減項"],["1,080,000","未加計押金運用收益"]]},{"id":"h:114-22","p":"h","src":"114年第22題","sec":"F1","stem":"依不動產估價技術規則第130條之規定，不動產租金估計以估計勘估標的之何種租金為原則？","opts":["經濟租金","支付租金","合理租金","實質租金"],"ok":[3],"ex":["經濟租金（依教材，指不動產以最有效使用方式所能產生的市場租金）不是§130所定的原則；§130明定租金估計以估計勘估標的之「實質租金」為原則。","支付租金是承租人實際支付之租金本身，並非規則明定租金估計之原則性基準。","「合理租金」並非技術規則明定租金估計之原則性正式用語。","技術規則第130條明定不動產租金估計以估計勘估標的之實質租金為原則，與題目敘述完全相符。"],"tr":"","core":["原則是實質租金，非經濟租金","支付租金非租金估計的原則基準","合理租金非原則性正式用語","第130條：以實質租金為原則"],"hl":[["經濟租金","以估計勘估標的之「實質租金」為原則"],["支付租金","承租人實際支付之租金本身"],["合理租金"],[]]},{"id":"h:114-24","p":"h","src":"114年第24題","sec":"F1","stem":"於不動產租金估計中有所謂的經濟租金與支付租金，兩者的大小關係為何？","opts":["經濟租金高於支付租金","經濟租金低於支付租金","經濟租金等於支付租金","不一定"],"ok":[3],"ex":["經濟租金與支付租金之大小關係並非恆定「經濟租金高於支付租金」，需視市場行情與契約約定租金孰高孰低而定，本選項過於絕對。","同樣地，並非恆定「經濟租金低於支付租金」，本選項過於絕對。","兩者並非恆定相等，需視個案實際租賃條件而定，本選項過於絕對。","經濟租金（市場最有效利用所能產生之收益）與支付租金（承租人實際支付之租金）之大小關係，視市場行情與契約約定租金水準而定，並無固定之高低關係，「不一定」是最精確的描述，與題目敘述相符。"],"tr":"","core":["兩者大小非恆定，過於絕對","兩者大小非恆定，過於絕對","兩者非恆定相等，過於絕對","大小視市場行情與契約租金而定"],"hl":[["經濟租金高於支付租金","視市場行情與契約約定租金孰高孰低而定"],["經濟租金低於支付租金"],["經濟租金等於支付租金","需視個案實際租賃條件而定"],[]]},{"id":"h:99-40","p":"h","src":"99年第40題","sec":"G1","stem":"有關樓層別效用比之敘述，下列何者錯誤？","opts":["反映各樓層間使用效益之差異","通常以一樓或地面層之效用為基準","樓層愈高，效用比一定愈高","得依各樓層之單價或租金水準訂定之"],"ok":[2],"ex":["反映各樓層間使用效益之差異為正確敘述。","§98Ⅱ 條文未規定樓層別效用比之基準樓層（只說依市場行情及地方習慣推估）；依官方答案，本選項視為正確敘述，非最明顯錯誤。","技術規則未規定「樓層愈高效用比一定愈高」，商業大樓地面層通常效用最高，此為錯誤敘述，即本題正解。","得依各樓層之單價或租金水準訂定為正確敘述。"],"tr":"","core":["反映各樓層使用效益差異","以一樓為基準，依官方答案成立","非樓層愈高效用愈高，地面層常最高","得依各樓層單價或租金水準訂定"],"hl":[[],[],["愈高，效用比一定愈高","商業大樓地面層通常效用最高"],[]]},{"id":"h:100-34","p":"h","src":"100年第34題","sec":"G1","stem":"樓層別效用比之計算，主要係依循下列何種估價學說為基礎？","opts":["建物貢獻原則","土地貢獻原則","聯合貢獻原則","收益分配原則"],"ok":[0],"ex":["官方答案為「建物貢獻原則」（學理說法，§98 條文未明定）；與題目敘述相符。","土地貢獻原則指超額利潤歸屬土地（如基地價格＝房地價格－建物成本），與樓層別效用比理論基礎不同。","聯合貢獻原則指超額利潤是土地與建物共同貢獻所致，與此不同。","收益分配原則指扣除非屬不動產本身之收益，與此不同。"],"tr":"","core":["官方答案採建物貢獻原則","土地貢獻原則指超額利潤歸土地","聯合貢獻原則指土地建物共同貢獻","收益分配原則指扣除非不動產收益"],"hl":[[],["土地貢獻原則","超額利潤歸屬土地"],["聯合貢獻原則","超額利潤是土地與建物共同貢獻所致"],["收益分配原則","扣除非屬不動產本身之收益"]]},{"id":"h:100-35","p":"h","src":"100年第35題","sec":"G1","stem":"某十層樓建物，地面層之地價分配率為100，二樓以上之樓層地價分配率依序遞減。若該建物總價為5,000萬元，土地總價分配比率為40%，地面層樓地板面積100坪，地價分配率為100，請問地面層之土地分配價格約為多少（假設各樓層面積相同，分配率總和為550）？","opts":["350萬元","364萬元","400萬元","420萬元"],"ok":[1],"ex":["350萬元無法由題幹常見誤算得到，屬干擾數字。","（簡化比例分配：土地總價×該層效用比÷效用比總和，非§100Ⅱ 地價分配率法公式，算術正確。）土地總價＝5,000×40%＝2,000萬元；地面層土地分配價格＝2,000×(100÷550)＝363.6≈364萬元，與本選項相符。","400萬元是把效用比總和誤用500：2,000×100÷500＝400萬元（題目給的總和是550）。","420萬元無法由題幹常見誤算得到，屬干擾數字。"],"tr":"","core":["非常見誤算，屬干擾數字","2,000×100÷550≈364萬","效用比總和誤用500的誤算","非常見誤算，屬干擾數字"],"hl":[["350萬元"],[],["400萬元","題目給的總和是550"],["420萬元"]]},{"id":"h:101-40","p":"h","src":"101年第40題","sec":"G1","stem":"樓層別效用比之計算原則，係基於下列何種原則？","opts":["建物貢獻原則","土地貢獻原則","收益分配原則","適合原則"],"ok":[0],"ex":["官方答案為「建物貢獻原則」（學理說法，§98 條文未明定）；與題目敘述相符。","（教材）土地貢獻原則指超額利潤歸屬土地（例：基地價格＝房地價格－建物成本），與官方答案「建物貢獻原則」不同。","（教材）收益分配原則指不動產收益扣除勞動、資本、經營等其他要素應得部分後，剩餘歸屬不動產，與樓層別效用比的理論基礎不同。","適合原則指不動產與坐落環境協調，與此不同。"],"tr":"","core":["官方答案採建物貢獻原則","土地貢獻原則指超額利潤歸土地","收益分配原則與效用比理論基礎不同","適合原則講與坐落環境協調"],"hl":[[],["土地貢獻原則","超額利潤歸屬土地"],["收益分配原則","剩餘歸屬不動產"],["適合原則","不動產與坐落環境協調"]]},{"id":"h:103-30","p":"h","src":"103年第30題","sec":"G1","stem":"某商業大樓地面層之效用比為100，二樓為70，三樓為50。若該大樓土地總價為3,000萬元，地面層、二樓、三樓面積各為50坪，請問二樓之土地分配價格約為多少（效用比總和為220）？","opts":["670萬元","750萬元","818萬元","955萬元"],"ok":[3],"ex":["670萬元無法由題幹常見誤算得到，屬干擾數字（二樓正確為3,000×70÷220≈955萬元）。","750萬元無法由題幹常見誤算得到，屬干擾數字（二樓正確為3,000×70÷220≈955萬元）。","818萬元無法由題幹常見誤算得到，屬干擾數字（二樓正確為3,000×70÷220≈955萬元）。","（簡化比例分配：土地總價×該層效用比÷效用比總和，非§100Ⅱ 地價分配率法公式，算術正確。）二樓土地分配價格＝3,000×(70÷220)＝954.5≈955萬元，與本選項相符。（注意本題問二樓效用比70，非地面層100或三樓50。）"],"tr":"","core":["非常見誤算，二樓應約955萬","非常見誤算，二樓應約955萬","非常見誤算，二樓應約955萬","3,000×70÷220≈955萬"],"hl":[["670萬元","3,000×70÷220≈955萬元"],["750萬元","3,000×70÷220≈955萬元"],["818萬元","3,000×70÷220≈955萬元"],[]]},{"id":"h:105-14","p":"h","src":"105年第14題","sec":"G1","stem":"有關樓層別效用比之敘述，下列何者正確？","opts":["樓層別效用比恆為樓層愈高、效用愈高","樓層別效用比係指各樓層相對地面層之效用差異比率","樓層別效用比僅適用於住宅用途","樓層別效用比與基地分配無關"],"ok":[1],"ex":["「恆為樓層愈高效用愈高」並不正確，依市場而異。","官方答案為B。§98Ⅱ 只規定樓層別效用比由全聯會按不同地區蒐集案例公告供參考，並依市場行情及地方習慣推估，條文未規定基準樓層；「各樓層相對地面層之效用差異比率」為官方答案採用之描述（與107年第23題官方答案之基準說法不同，各題以官方公告答案為準）。","規則並未限制只適用住宅用途，各類建物均可適用。","樓層別效用比之目的正是用於各樓層基地分配計算，「與基地分配無關」完全相反。"],"tr":"","core":["非恆為樓層愈高效用愈高","依官方答案：各樓層相對地面層之比","不限住宅，各類建物均可適用","效用比正是用於各樓層基地分配"],"hl":[["恆為樓層愈高、效用愈高","依市場而異"],[],["僅適用於住宅用途","各類建物均可適用"],["與基地分配無關","用於各樓層基地分配計算"]]},{"id":"h:106-15","p":"h","src":"106年第15題","sec":"G1","stem":"某公寓1至4樓之單價分別為100、70、60、70萬元/坪，若全棟建物成本價格占棟房地總價格比率為30%，若以3樓為基準，1至4樓之樓層別效用比分別為下列何者？","opts":["100%、70%、60%、70%","100%、70%、70%、60%","167%、117%、117%、100%","167%、117%、100%、117%"],"ok":[3],"ex":["這是各樓層單價本身，沒有以3樓為基準換算。","這是把各樓單價直接當成效用比（沒有換算成以3樓為100%），而且3樓、4樓的數字對調（3樓應為60、4樓為70）。","3樓與4樓的效用比順序錯置：3樓是基準應為100%。","樓層別效用比＝各樓層單價÷基準樓層單價：100÷60≈167%、70÷60≈117%、60÷60＝100%、70÷60≈117%，與本選項相符。建物成本比率30%在本題用不到。"],"tr":"","core":["各樓單價本身，未以3樓為基準","單價直接當效用比且3、4樓對調","3樓為基準應為100%，順序錯置","各樓單價÷3樓單價60"],"hl":[["100%、70%、60%、70%","以3樓為基準換算"],["100%、70%、70%、60%","換算成以3樓為100%"],["167%、117%、117%、100%","3樓是基準應為100%"],[]]},{"id":"h:107-23","p":"h","src":"107年第23題","sec":"G1","stem":"樓層別效用比之計算，原則上以下列何者作為基準（效用比為100者）？","opts":["各層中價格或租金最低之樓層","地面層","各層中價格或租金最高之樓層","屋頂層"],"ok":[0],"ex":["官方答案為A；§98Ⅱ 條文未載基準樓層（條文只說依市場行情及地方習慣推估），此為依官方答案之說法。","官方答案認為地面層非固定基準；惟105年第14題官方答案另採「相對地面層」說法，條文均未載，各題以官方公告答案為準。","「各層中最高之樓層」方向完全相反。","屋頂層並非規則明定之基準。"],"tr":"","core":["依官方答案：價格或租金最低之樓層","依官方答案地面層非固定基準","最高之樓層，方向完全相反","屋頂層並非規則明定之基準"],"hl":[[],["地面層","地面層非固定基準"],["各層中價格或租金最高之樓層"],["屋頂層"]]},{"id":"h:108-5","p":"h","src":"108年第5題","sec":"G1","stem":"某商辦大樓共8層，地面層效用比為100，地下一層效用比為60，二樓以上各層效用比依序遞減10。若土地總價為4,000萬元，各樓層面積均為30坪，試求三樓之土地分配價格（效用比總和假設為540）？","opts":["444萬元","481萬元","519萬元","593萬元"],"ok":[3],"ex":["444萬元是誤取效用比60的樓層（地下一層或五樓）：4,000×60÷540≈444.4萬元。","481萬元無法由題幹常見誤算得到，屬干擾數字。","519萬元是誤取四樓的效用比70：4,000×70÷540≈518.5萬元。","（簡化比例分配，非§100Ⅱ 地價分配率法公式。）依題目給定總和540，三樓效用比80；三樓土地分配價格＝4,000×(80÷540)≈592.6≈593萬元，與本選項相符。"],"tr":"","core":["誤取效用比60樓層的誤算","非常見誤算，屬干擾數字","誤取四樓效用比70的誤算","4,000×三樓80÷540≈593萬"],"hl":[["444萬元"],["481萬元"],["519萬元","誤取四樓的效用比70"],[]]},{"id":"h:109-5","p":"h","src":"109年第5題","sec":"G1","stem":"對於區分所有建物估價運用樓層別效用比時，下列敘述何者正確？","opts":["樓層別效用比是各層樓區分所有建物之立體地價差異所形成的樓層別效用比率","樓層別效用比可從各層樓出售價格案例，扣除開發利潤與土地成本費用後，推算區分所有建物各層樓效用比","樓層別效用比包含區分所有建物的土地效用與建築物效用","樓層別效用比通常地面層是最高，4樓為最低；當樓層數越高，樓層別效用比就越高"],"ok":[2],"ex":["立體地價差異形成的是「地價分配率」，樓層別效用比反映的是整個房地（土地＋建物）在各樓層的效用差異。","樓層別效用比是直接比較各樓層的房地價格（或租金）求得，不是扣掉開發利潤與土地成本後推算。","樓層別效用比是各樓層「房地」整體效用的比率，同時包含土地效用與建物效用，與本選項相符。","地面層通常最高，但不是越高樓層就一定越高，也不是固定4樓最低，要看實際市場。"],"tr":"","core":["立體地價差異形成的是地價分配率","直接比較各樓層房地價格求得","包含土地效用與建物效用","非越高越高，也非固定4樓最低"],"hl":[["立體地價差異","整個房地（土地＋建物）在各樓層的效用差異"],["扣除開發利潤與土地成本費用後","直接比較各樓層的房地價格（或租金）求得"],[],["4樓為最低","樓層數越高，樓層別效用比就越高","不是越高樓層就一定越高","要看實際市場"]]},{"id":"h:109-25","p":"h","src":"109年第25題","sec":"G1","stem":"某三層樓獨棟透天新成屋，建物登記面積為40坪，坐落基地登記面積為20坪，房地之正常價格為1200萬元，經參酌當地市場調查資料，運用估價方法計算出建物價值比率為占房地價格的30%，請問該基地單價應為多少？","opts":["18萬元/坪","30萬元/坪","42萬元/坪","60萬元/坪"],"ok":[2],"ex":["18萬元/坪是建物價格360萬（1,200×30%）÷基地面積20坪的算法：拿建物價格去除基地面積，求的不是基地單價。","30萬元/坪是房地總價1,200萬÷建物面積40坪，沒有先拆出土地價格。","土地價值比率＝1－30%＝70%；土地價格＝1,200×70%＝840萬元；基地單價＝840÷基地面積20坪＝42萬元/坪，與本選項相符。","60萬元/坪是房地總價1,200萬÷基地面積20坪，沒有扣掉建物價值。"],"tr":"","core":["建物價格÷基地面積，非基地單價","總價÷建物面積，未拆出土地價格","1,200×70%÷基地20坪＝42萬/坪","總價÷基地面積，未扣建物價值"],"hl":[["18萬元/坪","求的不是基地單價"],["30萬元/坪","沒有先拆出土地價格"],[],["60萬元/坪","沒有扣掉建物價值"]]},{"id":"h:110-25","p":"h","src":"110年第25題","sec":"G1","stem":"某六層樓建物，地面層效用比100，二至六樓依序為65、60、55、50、48。若土地總價2,500萬元，各樓層面積均為25坪，求二樓之土地分配價格（效用比總和378）？","opts":["350萬元","390萬元","430萬元","470萬元"],"ok":[2],"ex":["350萬元無法由題幹常見誤算得到，屬干擾數字。","390萬元無法由題幹常見誤算得到，屬干擾數字。","（簡化比例分配：土地總價×該層效用比÷效用比總和，非§100Ⅱ 地價分配率法公式，算術正確。）二樓土地分配價格＝2,500×(65÷378)≈429.9≈430萬元，與本選項相符。","470萬元無法由題幹常見誤算得到，屬干擾數字。"],"tr":"","core":["非常見誤算，屬干擾數字","非常見誤算，屬干擾數字","2,500×65÷378≈430萬","非常見誤算，屬干擾數字"],"hl":[["350萬元"],["390萬元"],[],["470萬元"]]},{"id":"h:111-17","p":"h","src":"111年第17題","sec":"G1","stem":"某住宅大樓地面層效用比100，二樓80，三樓75。若土地總價1,800萬元，各樓層面積均為35坪，求三樓之土地分配價格（效用比總和255）？","opts":["459萬元","529萬元","600萬元","635萬元"],"ok":[1],"ex":["459萬元無法由題幹常見誤算得到，屬干擾數字。","（簡化比例分配：土地總價×該層效用比÷效用比總和，非§100Ⅱ 地價分配率法公式，算術正確。）三樓土地分配價格＝1,800×(75÷255)≈529.4≈529萬元，與本選項相符。","600萬元＝1,800÷3，是三層平均分配、沒有依效用比分配的結果。","635萬元無法由題幹常見誤算得到，屬干擾數字。"],"tr":"","core":["非常見誤算，屬干擾數字","1,800×75÷255≈529萬","三層平均分配，未依效用比","非常見誤算，屬干擾數字"],"hl":[["459萬元"],[],["600萬元","沒有依效用比分配"],["635萬元"]]},{"id":"h:112-10","p":"h","src":"112年第10題","sec":"G1","stem":"某七層樓建物，地面層效用比100，二樓以上各層依序遞減8。若土地總價3,200萬元，各樓層面積均為28坪，求地面層之土地分配價格（效用比依序為100、92、84、76、68、60、52，總和532）？","opts":["502萬元","601萬元","678萬元","720萬元"],"ok":[1],"ex":["502萬元無法由題幹常見誤算得到，屬干擾數字。","（簡化比例分配：土地總價×該層效用比÷效用比總和，非§100Ⅱ 地價分配率法公式，算術正確。）地面層土地分配價格＝3,200×(100÷532)≈601.5≈601萬元，與本選項相符。","678萬元無法由題幹常見誤算得到，屬干擾數字。","720萬元無法由題幹常見誤算得到，屬干擾數字。"],"tr":"","core":["非常見誤算，屬干擾數字","3,200×100÷532≈601萬","非常見誤算，屬干擾數字","非常見誤算，屬干擾數字"],"hl":[["502萬元"],[],["678萬元"],["720萬元"]]},{"id":"h:113-25","p":"h","src":"113年第25題","sec":"G1","stem":"某八層樓建物，各樓層效用比依序為100、75、70、65、60、58、55、52。若土地總價2,800萬元，各樓層面積均為20坪，求第5層之土地分配價格（效用比總和535）？","opts":["280萬元","305萬元","287萬元","314萬元"],"ok":[3],"ex":["280萬元無法由題幹常見誤算得到，屬干擾數字。","305萬元是效用比總和誤用550：2,800×60÷550≈305.5萬元（題目給的總和是535）。","287萬元接近誤取效用比55那一層的結果：2,800×55÷535≈287.9萬元，屬近似干擾數字。","（簡化比例分配：土地總價×該層效用比÷效用比總和，非§100Ⅱ 地價分配率法公式，算術正確。）第5層效用比60；分配價格＝2,800×(60÷535)≈314.0萬元，與本選項相符。"],"tr":"","core":["非常見誤算，屬干擾數字","效用比總和誤用550的誤算","誤取效用比55樓層的近似值","2,800×第5層60÷535≈314萬"],"hl":[["280萬元"],["305萬元","題目給的總和是535"],["287萬元","誤取效用比55那一層"],[]]},{"id":"h:99-6","p":"h","src":"99年第6題","sec":"H1H2","stem":"以擔保債務為目的，於債務人或第三人之不動產上所設定之他項權利，並於不履行債務時得就該不動產賣得價金優先受償者，稱為：","opts":["抵押權","地上權","永佃權","不動產役權"],"ok":[0],"ex":["此為民法§860 之抵押權定義（以擔保債務為目的，就債務人或第三人供擔保之不動產，於不履行債務時得就賣得價金優先受償），出自民法，非技術規則條文；與題目相符。","地上權是以在他人土地上設定建物或工作物為目的，非擔保債務。","永佃權是以在他人土地上為耕作或牧畜為目的，非擔保債務。","不動產役權是以他人不動產供自己不動產便宜之用，非擔保債務。"],"tr":"","core":["擔保債務、優先受償＝抵押權","地上權以建物或工作物為目的","永佃權以耕作或牧畜為目的","不動產役權供自己不動產便宜之用"],"hl":[[],["地上權","在他人土地上設定建物或工作物為目的"],["永佃權","在他人土地上為耕作或牧畜為目的"],["不動產役權","他人不動產供自己不動產便宜之用"]]},{"id":"h:99-17","p":"h","src":"99年第17題","sec":"H1H2","stem":"下列何者非屬不動產估價技術規則所稱權利估價之範圍？","opts":["地上權","抵押權","質權","永佃權"],"ok":[2],"ex":["地上權為§114 所列權利估價之項目。","抵押權為§114 所列權利估價之項目（另有§121 專條）。","§114 權利估價包括地上權、典權、永佃權、農育權、不動產役權、耕作權、抵押權、租賃權、市地重劃、容積移轉及都市更新權利變換；「質權」不在其中（質權之標的為動產或權利），即本題正解。","永佃權為§114 所列權利估價之項目（§118 有專條）。"],"tr":"","core":["地上權屬權利估價項目","抵押權屬權利估價項目","質權標的為動產或權利，不在範圍","永佃權屬權利估價項目"],"hl":[[],[],["質權","質權之標的為動產或權利"],[]]},{"id":"h:102-19","p":"h","src":"102年第19題","sec":"H1H2","stem":"下列不動產權利估價之相關敘述，何者錯誤？","opts":["地上權估價，應考慮其用途、權利存續期間、支付地租之有無、權利讓與之限制及地上權設定之空間位置等因素","抵押權估價，應直接以實際債權額為基礎，考慮其他順位抵押權設定狀況、流通性、風險性、增值性及執行上之難易程度等因素調整","租賃權估價，應考慮契約內容、用途、租期、租金支付方式、使用目的及使用情形等因素","容積移轉估價，應考慮容積送出基地、接受基地及其他影響不動產價格及相關法令等因素"],"ok":[1],"ex":["與 §116 逐字相符，敘述正確，不是答案（本題問錯誤）。","考選部標準答案 B。§121：抵押權估價，應先估計價格日期當時勘估標的正常價格，再以實際債權額為基礎，考慮其他順位抵押權設定狀況、流通性、風險性、增值性及執行上之難易程度等因素調整。選項寫「應直接以實際債權額為基礎」，漏掉「先估正常價格」這一步，所以錯。","與 §122 相符，敘述正確。","與 §123 相符，敘述正確。"],"tr":"","core":["地上權估價考慮用途、存續期間等","應先估正常價格，再以債權額為基礎","租賃權估價考慮契約內容、租期等","容積移轉考慮送出與接受基地等"],"hl":[[],["應直接以實際債權額為基礎","先估計價格日期當時勘估標的正常價格","再以實際債權額為基礎"],[],[]]},{"id":"h:103-5","p":"h","src":"103年第5題","sec":"H1H2","stem":"下列何者非屬不動產估價技術規則所稱權利估價之範圍？","opts":["地上權","抵押權","市地重劃","永佃權"],"ok":[2],"ex":["地上權為§114 所列權利估價之項目。","抵押權為§114 所列權利估價之項目。","官方答案為C（市地重劃非屬權利估價範圍）；現行§114 已將市地重劃列入權利估價範圍（另有§122-1 市地重劃估價專條），考試以官方公告答案為準。⚠️答案與現行法衝突。","永佃權為§114 所列權利估價之項目。"],"tr":"","core":["地上權屬權利估價項目","抵押權屬權利估價項目","依官方答案不屬，惟現行法已列入","永佃權屬權利估價項目"],"hl":[[],[],["市地重劃","市地重劃非屬權利估價範圍"],[]]},{"id":"h:106-34","p":"h","src":"106年第34題","sec":"H1H2","stem":"以在他人土地上為耕作或牧畜為目的，而設定之他項權利，稱為：","opts":["地上權","永佃權","耕作權","農育權"],"ok":[1],"ex":["地上權是以在他人土地上設定建物或工作物為目的，非耕作或牧畜。","官方答案B，與題目敘述相符。永佃權之定義出自民法（舊§842，現已刪除），並非技術規則條文；技術規則§118 只規定永佃權估價應考慮佃租支付情形、民間習俗。","耕作權為§114 所列權利估價項目之一（§120 有專條）；惟題幹之定義（在他人土地上為耕作或牧畜為目的）官方答案為永佃權，故不選。","農育權為民法修正後取代永佃權之他項權利（§118-1 為其估價規定），範圍包含農作、森林、養殖等農育目的；官方答案不選。"],"tr":"","core":["地上權以建物或工作物為目的","耕作或牧畜為目的＝永佃權","此定義官方答案為永佃權","農育權取代永佃權，官方答案不選"],"hl":[["地上權","在他人土地上設定建物或工作物為目的"],[],["耕作權","§114 所列權利估價項目之一"],["農育權","農作、森林、養殖等農育目的"]]},{"id":"h:113-16","p":"h","src":"113年第16題","sec":"H1H2","stem":"進行地上權估價時，下列何者非屬應考量之要素？","opts":["設定地上權之目的及使用方式","地上權存續期間","抵押權人之徵信資料","地租之有無及高低"],"ok":[2],"ex":["§116 地上權估價應考慮用途、權利存續期間、支付地租之有無、權利讓與之限制、空間位置等；「設定目的及使用方式」近於「用途」，屬應考量要素。","地上權存續期間為§116 所列應考量要素。","§116 所列考量要素（用途、權利存續期間、支付地租之有無、權利讓與之限制、空間位置等）不含「抵押權人之徵信資料」，即本題正解。","§116 為「支付地租之有無」（「及高低」為§118-1 農育權之用語）；地租仍屬地上權估價考量因素，官方答案不選本項。"],"tr":"","core":["設定目的及使用方式近於用途","存續期間是應考量要素","抵押權人徵信資料不在考量要素","地租仍屬地上權估價考量因素"],"hl":[[],[],["抵押權人之徵信資料","權利存續期間、支付地租之有無"],[]]},{"id":"h:99-12","p":"h","src":"99年第12題","sec":"H1H2","stem":"農地上種植之農作改良物，於不動產估價時應如何處理？","opts":["不予估價","應單獨估價，並於估價報告書中區分土地與農作改良物之價格","併入土地價格估計，不另區分","僅估計收穫後之市場價格"],"ok":[1],"ex":["農作改良物並非不予估價，§109–§111 有農作改良物之估價規定。","官方答案B。惟§109–§111 只規範農作改良物之估價方法，並無「應單獨估價並於估價報告書區分」之明文，此為依官方答案處理（教材說法，非技術規則條文）。","併入土地價格不另區分，與官方答案不符。","§111依生長階段分三種方式：幼小者依種植及培育費用、接近成熟期者估計收穫量及市場價格、距成熟期一年以上者以產地價格推估後折算。本選項「僅」估計收穫後市場價格，以偏概全。"],"tr":"","core":["農作改良物有估價規定，非不予估價","依官方答案：單獨估價並區分價格","併入土地不另區分，與官方答案不符","依生長階段分三種，非僅收穫後價格"],"hl":[["不予估價","§109–§111 有農作改良物之估價規定"],[],["併入土地價格估計，不另區分"],["依生長階段分三種方式"]]},{"id":"h:100-26","p":"h","src":"100年第26題","sec":"H1H2","stem":"墳場用地之估價，下列何者較不適宜？","opts":["成本法","收益法","比較法","依其特殊性質個別判斷"],"ok":[2],"ex":["成本法可用於特殊宗地估算改良成本，並非較不適宜。","收益法可依墳場使用收益推算，並非較不適宜。","官方答案為C（比較法較不適宜）；惟現行§95 規定池沼、墓地之估價以比較法為原則，與官方答案衝突，考試以官方公告答案為準。⚠️答案與現行法衝突。","依特殊性質個別判斷是合理方向，並非較不適宜。"],"tr":"","core":["成本法可估改良成本，非不適宜","收益法可依墳場收益推算","依官方答案比較法較不適宜","依特殊性質個別判斷是合理方向"],"hl":[[],[],["比較法"],[]]},{"id":"h:103-15","p":"h","src":"103年第15題","sec":"H1H2","stem":"農場或牧場之估價，以何種方法估價為原則？","opts":["收益法","成本法","比較法","殘餘法"],"ok":[2],"ex":["§93 規定農場或牧場之估價「以比較法估價為原則」，不是收益法。","成本法不是§93規定的原則方法；以成本法為原則的是建物（§108）及工事、水利土壤改良（§112），林地則依§92視林木成長情形，分別採比較法、收益法及成本法。§93：農場或牧場之估價，以比較法估價為原則。","考選部標準答案 C。§93：農場或牧場之估價，以比較法估價為原則；無買賣實例者，得以附近土地價格為基礎，考慮其位置、形狀、地形、土壤特性及利用狀況等差異，比較推估之。","殘餘法不是 §93 所定方法。"],"tr":"","core":["農場牧場以比較法為原則，非收益法","成本法原則是建物與工事改良","農場或牧場以比較法估價為原則","殘餘法不是規定方法"],"hl":[["收益法","以比較法估價為原則"],["成本法","以比較法估價為原則"],[],["殘餘法"]]},{"id":"h:105-1","p":"h","src":"105年第1題","sec":"H1H2","stem":"公共設施保留地之估價，依不動產估價技術規則規定，原則上以下列何種方法估價？","opts":["收益法","成本法","比較法","土地開發分析法"],"ok":[2],"ex":["收益法可用，但非技術規則明定公共設施保留地之原則方法。","成本法可用，但非技術規則明定之原則方法。","公共設施保留地估價以比較法為原則（§97），得比較其與毗鄰土地使用分區及使用強度差異及價值減損，與題目相符。","土地開發分析法適用於以開發為前提之宗地估價，非此之原則方法。"],"tr":"","core":["收益法可用，但非原則方法","成本法可用，但非原則方法","公共設施保留地以比較法為原則","土地開發分析法用於開發前提宗地"],"hl":[["收益法"],["成本法"],[],["土地開發分析法"]]},{"id":"h:105-28","p":"h","src":"105年第28題","sec":"H1H2","stem":"依不動產估價技術規則之規定，林地採成本法估價時，其總費用之計算，何者不是應考量之項目？","opts":["造林費","營運費用","林地改良費","道路開挖費用"],"ok":[1],"ex":["造林費是 §92 明列應考量項目，不是答案（本題問「不是」）。","考選部標準答案 B。§92：林地採成本法估價時，總費用之計算，應考量造林費、林地改良費及道路開挖費用三項；「營運費用」是 §38 收益法總費用中營運性不動產另加的項目，不在林地成本法之列。","林地改良費是 §92 明列項目。","道路開挖費用是 §92 明列項目。"],"tr":"","core":["造林費是應考量項目","林地總費用不含營運費用","林地改良費是應考量項目","道路開挖費用是應考量項目"],"hl":[[],["營運費用","造林費、林地改良費及道路開挖費用"],[],[]]},{"id":"h:105-39","p":"h","src":"105年第39題","sec":"H1H2","stem":"受地層下陷、土壤液化等地質不良情況影響之土地估價，得採何種估價方法評估其工事水利或土壤改良所需成本？","opts":["比較法","收益法","成本法","土地開發分析法"],"ok":[2],"ex":["比較法是以交易實例為基礎，非評估改良成本之主要方法。","收益法是以淨收益折現或資本化求取價值，非評估改良成本之方法。","官方答案為成本法。§112 規定附著於土地之工事及水利土壤改良，以成本法為原則，得斟酌比較法及收益法；「地層下陷、土壤液化」等為官方答案題幹用語，非條文字樣。","土地開發分析法適用於以開發為前提之宗地估價，非評估改良成本之方法。"],"tr":"","core":["比較法非評估改良成本的方法","收益法非評估改良成本的方法","工事水利土壤改良以成本法為原則","開發分析法用於開發前提宗地"],"hl":[["比較法"],["收益法"],[],["土地開發分析法"]]},{"id":"h:106-13","p":"h","src":"106年第13題","sec":"H1H2","stem":"公共設施保留地估價，依不動產估價技術規則規定，得以下列何者為比較標的？","opts":["一般建築用地","鄰近之公共設施保留地或毗鄰非公共設施保留地","農業用地","都市計畫保護區土地"],"ok":[3],"ex":["§97未列舉比較標的類型；本題官方答案為D，本選項不選（112年第19題官方答案則不同，各題以官方公告為準）。","§97 只規定公共設施保留地以比較法為原則，得比較其與毗鄰土地使用分區及使用強度差異及價值減損；條文並無「選取鄰近之公共設施保留地或毗鄰非公共設施保留地」之文字。官方答案不選本項。","§97未列舉比較標的類型；本題官方答案為D，本選項不選。","官方答案D（都市計畫保護區土地）；與112年第19題官方答案（A）相反，§97 並未列舉比較標的類型，各題以官方公告答案為準。"],"tr":"","core":["本題官方答案不選一般建築用地","條文無此文字，本題官方答案不選","本題官方答案不選農業用地","依本題官方答案：都市計畫保護區"],"hl":[["一般建築用地"],["鄰近之公共設施保留地或毗鄰非公共設施保留地","比較其與毗鄰土地使用分區及使用強度差異及價值減損"],["農業用地"],[]]},{"id":"h:106-16","p":"h","src":"106年第16題","sec":"H1H2","stem":"依不動產估價技術規則第89條規定，受有土壤或地下水污染之土地，應先估算其未受污染之正常價格，再依委託人提供之土壤污染檢測資料，考量該土壤或地下水污染之影響，並計算其減損額後，從正常價格中扣除，以其餘額為該宗地之價格。假設受汙染宗地，未受汙染正常價格2,000萬元，經勘估地價減損額500萬元，則受汙染地價格多少？","opts":["500萬元","1,000萬元","1,500萬元","2,000萬元"],"ok":[2],"ex":["500萬元是地價減損額，不是受污染地的價格。","1,000萬元是把減損額扣了兩次（2,000－500×2）的誤算；依§89只扣一次：2,000－500＝1,500萬元。","依§89：受污染宗地價格＝未受污染正常價格－地價減損額＝2,000－500＝1,500萬元，與本選項相符。","2,000萬元是未受污染的正常價格，還沒扣除減損額。"],"tr":"","core":["500萬是減損額，不是價格","減損額扣了兩次的誤算","正常價格2,000－減損500＝1,500萬","2,000萬是未扣減損的正常價格"],"hl":[["500萬元","是地價減損額"],["1,000萬元","2,000－500＝1,500萬元"],[],["2,000萬元","未受污染的正常價格，還沒扣除減損額"]]},{"id":"h:106-33","p":"h","src":"106年第33題","sec":"H1H2","stem":"鹽田之估價，原則上採下列何種估價方法？","opts":["收益法","成本法","土地開發分析法","比較法"],"ok":[3],"ex":["收益法可用，但非技術規則明定鹽田之原則方法。","成本法可用，但非技術規則明定之原則方法。","土地開發分析法適用於以開發為前提之宗地估價，非鹽田之原則方法。","§94明定鹽田之估價以比較法估價為原則，與題目相符。"],"tr":"","core":["收益法可用，但非原則方法","成本法可用，但非原則方法","開發分析法用於開發前提宗地","鹽田之估價以比較法為原則"],"hl":[["收益法"],["成本法"],["土地開發分析法"],[]]},{"id":"h:107-22","p":"h","src":"107年第22題","sec":"H1H2","stem":"受水患或土壤液化影響之土地進行工事水利或土壤改良所需成本估算時，宜採何種估價方法？","opts":["比較法","成本法","收益法","土地開發分析法"],"ok":[1],"ex":["比較法是以交易實例為基礎，非評估改良成本之主要方法。","官方答案為成本法。§112 規定附著於土地之工事及水利土壤改良，以成本法為原則，得斟酌比較法及收益法；「水患、土壤液化」等為官方答案題幹用語，非條文字樣。","收益法是以淨收益折現或資本化求取價值，非評估改良成本之方法。","土地開發分析法適用於以開發為前提之宗地估價，非評估改良成本之方法。"],"tr":"","core":["比較法非評估改良成本的方法","工事水利土壤改良以成本法為原則","收益法非評估改良成本的方法","開發分析法用於開發前提宗地"],"hl":[["比較法"],[],["收益法"],["土地開發分析法"]]},{"id":"h:110-15","p":"h","src":"110年第15題","sec":"H1H2","stem":"墳墓用地之估價，下列敘述何者正確？","opts":["適合採用比較法估價","因不具一般市場性，較難以比較法估價","應優先採用收益法估價","應優先採用土地開發分析法估價"],"ok":[1],"ex":["本選項「適合採用比較法」其實符合現行§95（墓地以比較法為原則），但官方答案為B，與現行法衝突；考試以官方公告答案為準。","官方答案為B（因不具一般市場性，較難以比較法估價）；現行§95 以比較法為原則，答案與現行法衝突，考試以官方公告答案為準。⚠️","「應優先採用收益法」並非技術規則對墳墓用地之明確規定。","「應優先採用土地開發分析法」並非技術規則對墳墓用地之明確規定。"],"tr":"","core":["符合現行法，但官方答案不選","依官方答案：不具市場性難用比較法","非規則對墳墓用地的明確規定","非規則對墳墓用地的明確規定"],"hl":[["適合採用比較法"],[],["應優先採用收益法"],["應優先採用土地開發分析法"]]},{"id":"h:112-15","p":"h","src":"112年第15題","sec":"H1H2","stem":"高爾夫球場用地之估價，原則上較適合採用下列何種估價方法？","opts":["收益法","成本法","比較法","土地開發分析法"],"ok":[2],"ex":["§91 未規定以收益法為原則方法。","§91 未規定以成本法為原則方法。","官方答案C。惟§91 高爾夫球場估價為考慮會員制度、球場設施、開發成本、收益及營運費用，並未規定以比較法為原則，官方答案與條文不盡一致，考試以官方公告為準。","§91 未規定以土地開發分析法為原則方法。"],"tr":"","core":["未規定以收益法為原則","未規定以成本法為原則","依官方答案採比較法","未規定以土地開發分析法為原則"],"hl":[["收益法"],["成本法"],[],["土地開發分析法"]]},{"id":"h:112-19","p":"h","src":"112年第19題","sec":"H1H2","stem":"公共設施保留地原則上採比較法估價，其比較標的應如何選取？","opts":["選取鄰近之公共設施保留地或毗鄰非公共設施保留地","選取一般建築用地","選取農業用地","選取都市計畫保護區土地"],"ok":[0],"ex":["官方答案A。§97 只規定公共設施保留地以比較法為原則，得比較其與毗鄰土地使用分區及使用強度差異及價值減損，條文未逐字規定比較標的之選取方式；與106年第13題官方答案不同，以官方公告答案為準。","一般建築用地，官方答案不選此項。","農業用地，官方答案不選此項。","都市計畫保護區土地，本題官方答案不選此項（106年第13題官方答案則選此項，各題以官方公告為準）。"],"tr":"","core":["依官方答案：鄰近公設保留地等","官方答案不選一般建築用地","官方答案不選農業用地","本題官方答案不選保護區土地"],"hl":[[],["選取一般建築用地"],["選取農業用地"],["選取都市計畫保護區土地"]]},{"id":"h:113-15","p":"h","src":"113年第15題","sec":"H1H2","stem":"高爾夫球場、農場、牧場等特殊用途之土地估價，原則上採何種估價方法？","opts":["收益法","比較法","成本法","土地開發分析法"],"ok":[1],"ex":["§91、§93 均未規定以收益法為原則。","官方答案B。農場、牧場部分：§93 以比較法為原則，相符；高爾夫球場部分：§91 未規定以比較法為原則（考慮會員制度、球場設施、開發成本、收益及營運費用），⚠️與§91 不盡一致，考試以官方公告答案為準。","成本法非§93 農場牧場之原則方法。","土地開發分析法非此類土地之原則方法。"],"tr":"","core":["均未規定以收益法為原則","依官方答案採比較法","成本法非農場牧場原則方法","非此類土地之原則方法"],"hl":[["收益法"],[],["成本法"],["土地開發分析法"]]},{"id":"h:114-9","p":"h","src":"114年第9題","sec":"H1H2","stem":"受地層下陷影響之土地，若需估算其工事水利或土壤改良所需成本，宜採何種估價方法？","opts":["比較法","收益法","成本法","土地開發分析法"],"ok":[2],"ex":["比較法是以交易實例為基礎，非評估改良成本之主要方法。","收益法是以淨收益折現或資本化求取價值，非評估改良成本之方法。","官方答案為成本法。§112 規定附著於土地之工事及水利土壤改良，以成本法為原則，得斟酌比較法及收益法；「地層下陷」等為官方答案題幹用語，非條文字樣。","土地開發分析法適用於以開發為前提之宗地估價，非評估改良成本之方法。"],"tr":"","core":["比較法非評估改良成本的方法","收益法非評估改良成本的方法","工事水利土壤改良以成本法為原則","開發分析法用於開發前提宗地"],"hl":[["比較法"],["收益法"],[],["土地開發分析法"]]},{"id":"h:100-29","p":"h","src":"100年第29題","sec":"H3I1","stem":"都市更新權利變換中，各權利人應分配之權利價值，係依其更新前權利價值占全部權利人更新前權利價值總和之比率，乘以下列何者計算？","opts":["更新前總成本","更新後實施者實際分配之權利價值總和","更新前公告地價總額","更新後總銷售金額"],"ok":[1],"ex":["「更新前總成本」並非權利變換分配公式（都市更新條例及權利變換實施辦法）所乘之基準金額。","各權利人應分配之權利價值＝(該權利人更新前權利價值÷全部權利人更新前權利價值總和)×更新後實施者實際分配之權利價值總和；此公式出自都市更新條例及其權利變換實施辦法，並非不動產估價技術規則條文。與本選項相符。","「更新前公告地價總額」並非上述分配公式之基準金額。","「更新後總銷售金額」是毛銷售額，未扣除實施者應得部分，並非上述分配公式之基準金額。"],"tr":"","core":["更新前總成本非分配基準金額","權利價值比率×更新後實際分配總和","公告地價總額非分配基準金額","總銷售額未扣實施者應得部分"],"hl":[["更新前總成本"],[],["更新前公告地價總額"],["更新後總銷售金額"]]},{"id":"h:102-20","p":"h","src":"102年第20題","sec":"H3I1","stem":"都市更新權利變換範圍內，土地及建物所有權人應分配之權利價值，依其權利價值占全部權利價值之比率，乘以更新後何種價格估算之總額？","opts":["新成屋之市場價格","重建成本價格","土地公告現值","房屋現值"],"ok":[0],"ex":["§128 規定權利變換後區分所有建物及其土地應有部分，以新成屋價格查估；本選項「新成屋之市場價格」與§128 相符，依官方答案為正確選項。至於各所有權人應分配之權利價值＝權利價值比率×更新後價值總額，該分配方式出自都市更新條例及權利變換實施辦法，非技術規則條文。","「重建成本價格」是成本法概念，並非§128 所採之新成屋價格。","「土地公告現值」是稅賦計算基準，並非§128 所採價格。","「房屋現值」是稅賦計算概念，並非§128 所採價格。"],"tr":"","core":["權利變換後以新成屋價格查估","重建成本屬成本法，非新成屋價格","公告現值是稅賦基準","房屋現值是稅賦計算概念"],"hl":[[],["重建成本價格","§128 所採之新成屋價格"],["土地公告現值"],["房屋現值"]]},{"id":"h:103-36","p":"h","src":"103年第36題","sec":"H3I1","stem":"都市更新權利變換中，基地價值比率係指土地所有權人應分配之土地價值占下列何者之比率？","opts":["更新後總銷售金額","更新前公告地價","更新前正常市價","權利變換前各土地所有權人權利價值之總和"],"ok":[3],"ex":["「更新後總銷售金額」包含實施者應得利潤，並非基地價值比率之正確分母。","「更新前公告地價」是稅賦基準，並非技術規則明定之計算分母。","「更新前正常市價」，官方答案不選；現行§125Ⅱ 基地價值比率＝素地單價×基地總面積÷(素地單價×基地總面積＋營造或施工費單價×(1－累積折舊率)×全棟建物面積)，分母為素地總價加建物成本。","官方答案D（分母為權利變換前各土地所有權人權利價值之總和）。⚠️惟現行§125Ⅱ 基地價值比率＝素地單價×基地總面積÷(素地單價×基地總面積＋營造或施工費單價×(1－累積折舊率)×全棟建物面積)，分母為素地總價加建物成本。並非「權利變換前各土地所有權人權利價值之總和」，官方答案與現行法衝突，考試以官方公告答案為準。"],"tr":"","core":["總銷售金額含實施者利潤，非分母","公告地價是稅賦基準，非分母","依官方答案不選此分母","依官方答案：變換前權利價值總和"],"hl":[["更新後總銷售金額"],["更新前公告地價"],["更新前正常市價"],[]]},{"id":"h:109-8","p":"h","src":"109年第8題","sec":"H3I1","stem":"有關都市更新權利變換估價，下列敘述何者錯誤？","opts":["權利變換前為區分所有建物者，應以全棟建物價值比率，分算各區分所有建物房地總價之基地權利價值","權利變換前區分所有建物之基地總價值低於區分所有建物坐落基地之素地總價值者，應以各區分所有建物房地總價乘上基地價值比率，計算出各區分所有建物之基地權利價值","權利變換前之基地未建築使用者，以素地價值推估其土地權利價值","權利變換前為非屬區分所有之建物者，應以該建物之房地總價乘以基地價值比率計算基地權利價值"],"ok":[0],"ex":["錯誤：區分所有建物應以全棟的「土地（基地）價值比率」分算基地權利價值，不是「建物價值比率」，即本題答案。","本選項是§126第1、2款的計算步驟（之後還要依第3、4款以素地總價值乘各區分所有建物基地權利價值比率調整），敘述本身沒有錯，官方答案不選，非本題答案。","基地未建築使用者，以素地價值推估土地權利價值，敘述正確。","非區分所有建物：房地總價×基地價值比率＝基地權利價值，敘述正確。"],"tr":"","core":["應以土地價值比率，非建物價值比率","房地總價×基地價值比率為計算步驟","未建築使用者以素地價值推估","非區分所有：房地總價×基地價值比率"],"hl":[["全棟建物價值比率","全棟的「土地（基地）價值比率」"],[],[],[]]},{"id":"h:110-14","p":"h","src":"110年第14題","sec":"H3I1","stem":"都市更新權利變換範圍內，某土地所有權人之基地權利價值占全部權利人權利價值總和之比率為10%，若更新後實施者實際分配之權利價值總和為5億元，則該所有權人應分配之權利價值為何？","opts":["4,000萬元","4,500萬元","5,000萬元","5,500萬元"],"ok":[2],"ex":["4,000萬元＝5億×8%，與題幹的10%不符；正確為5億×10%＝5,000萬元。","4,500萬元＝5億×9%（或5,000萬再打九折），題幹沒有任何折扣依據；正確為5億×10%＝5,000萬元。","應分配之權利價值＝10%×5億元＝5,000萬元，與本選項相符。","5,500萬元＝5億×11%，無法由題幹數字的常見誤算得到；正確為5億×10%＝5,000萬元。"],"tr":"","core":["5億×8%，與題幹10%不符","無折扣依據，應為5,000萬","10%×5億＝5,000萬","5億×11%，應為5,000萬"],"hl":[["4,000萬元","正確為5億×10%＝5,000萬元"],["4,500萬元","正確為5億×10%＝5,000萬元"],[],["5,500萬元","正確為5億×10%＝5,000萬元"]]},{"id":"h:99-28","p":"h","src":"99年第28題","sec":"H3I1","stem":"計量模型分析法應用於不動產估價時，主要係作為下列何種估價方法之輔助工具？","opts":["成本法","比較法","收益法","土地開發分析法"],"ok":[1],"ex":["計量模型分析法並非成本法之輔助工具。","計量模型分析法規定於技術規則比較法節（§19第7款），用來推算比較法各主要影響價格因素的調整率及調整額，屬比較法的輔助工具（「輔助工具」為教材用語），與題目相符。","計量模型分析法並非收益法之輔助工具。","計量模型分析法並非土地開發分析法之輔助工具。"],"tr":"","core":["非成本法之輔助工具","規定於比較法節，屬比較法輔助工具","非收益法之輔助工具","非土地開發分析法之輔助工具"],"hl":[["成本法"],[],["收益法"],["土地開發分析法"]]},{"id":"h:100-14","p":"h","src":"100年第14題","sec":"H3I1","stem":"計量模型分析法於不動產估價中之應用，性質上屬於下列何種估價方法之延伸？","opts":["成本法","收益法","比較法","土地開發分析法"],"ok":[2],"ex":["計量模型分析法性質上屬於比較法之延伸，並非成本法之延伸。","計量模型分析法並非收益法之延伸。","計量模型分析法定義於技術規則比較法節（§19第7款），以比較標的資料推算調整率及調整額，性質上屬比較法之延伸（教材用語），與題目相符。","計量模型分析法並非土地開發分析法之延伸。"],"tr":"","core":["屬比較法之延伸，非成本法","非收益法之延伸","以比較標的推算調整率，屬比較法","非土地開發分析法之延伸"],"hl":[["成本法","性質上屬於比較法之延伸"],["收益法"],[],["土地開發分析法"]]},{"id":"h:102-25","p":"h","src":"102年第25題","sec":"H3I1","stem":"採計量模型分析法進行不動產估價時，自變數之樣本數應為自變數個數之多少倍以上？","opts":["3倍","4倍","5倍","10倍"],"ok":[2],"ex":["3倍並非§20(一) 之門檻。","4倍並非§20(一) 之門檻。","§20(一) 規定比較標的件數須為自變數個數五倍以上（題幹「樣本數」即指比較標的件數），與題目相符。","10倍超出§20(一) 規定之最低門檻（5倍），並非強制要求。"],"tr":"","core":["門檻是5倍，不是3倍","門檻是5倍，不是4倍","比較標的須為自變數個數5倍以上","10倍超出最低門檻5倍"],"hl":[["3倍"],["4倍"],[],["10倍","最低門檻（5倍）"]]},{"id":"h:104-29","p":"h","src":"104年第29題","sec":"H3I1","stem":"計量模型分析法之適用條件，下列敘述何者正確？","opts":["樣本數應為自變數個數之3倍以上","樣本數應為自變數個數之5倍以上","判定係數應大於0.5即可採用","顯著機率應大於5%"],"ok":[1],"ex":["§20(一) 為比較標的件數須為自變數個數之「5倍以上」，並非3倍。","§20(一) 規定比較標的件數須為自變數個數五倍以上，與本選項相符，為正確敘述。","§20(二) 規定採迴歸分析者，調整後判定係數不得低於0.7，並非大於0.5即可。","§20(三) 規定截距項以外各主要影響價格因素之係數估計值同時為零之顯著機率「不得大於5%」，並非大於5%，方向相反。"],"tr":"","core":["應為5倍以上，不是3倍","比較標的須為自變數個數5倍以上","調整後判定係數不得低於0.7","顯著機率不得大於5%，方向相反"],"hl":[["3倍","5倍以上"],[],["大於0.5即可","調整後判定係數不得低於0.7"],["應大於5%","不得大於5%"]]},{"id":"h:104-30","p":"h","src":"104年第30題","sec":"H3I1","stem":"下列那幾項條件違反不動產估價技術規則中對應用計量模型分析法之要求？①須蒐集應用計量模型分析關係式應變數個數五倍以上之比較標的　②計量模型分析採迴歸分析者，其調整後判定係數不得高於零點七　③截距項以外其他各主要影響價格因素之係數估計值同時為零之顯著機率不得小於百分之五","opts":["僅①②","僅①③","僅②③","①②③"],"ok":[3],"ex":["③也違反規定，不只①②。","②也違反規定，不只①③。","①也違反規定，不只②③。","三項都違反§20：①應為「自變數」個數五倍以上，不是應變數；②調整後判定係數應「不得低於」0.7，不是不得高於；③顯著機率應「不得大於」5%，不是不得小於。與本選項相符。"],"tr":"","core":["③也違反規定，不只①②","②也違反規定，不只①③","①也違反規定，不只②③","三項都違反規定"],"hl":[["僅①②","③也違反規定"],["僅①③","②也違反規定"],["僅②③","①也違反規定"],[]]},{"id":"h:106-9","p":"h","src":"106年第9題","sec":"H3I1","stem":"計量模型分析法中，用以衡量模型解釋能力高低之統計指標，稱為：","opts":["樣本數","判定係數","顯著機率","殘差值"],"ok":[1],"ex":["樣本數是觀察值數量，用以判斷資料量是否足夠，非衡量模型解釋能力之指標。","判定係數（R²）是衡量迴歸模型解釋能力的統計指標，R²愈高解釋能力愈好（統計學／教材說法）；技術規則§20第2款只規定採迴歸分析者，調整後判定係數不得低於0.7，與題目相符。","顯著機率是用以檢定各自變數係數是否具統計顯著性之指標，非衡量整體模型解釋能力之主要指標。","殘差值是實際觀測值與預測值之差，非規則明定衡量模型解釋能力之正式指標。"],"tr":"","core":["樣本數看資料量，非解釋能力指標","判定係數衡量模型解釋能力","顯著機率檢定係數顯著性","殘差值是實際與預測之差"],"hl":[["樣本數","用以判斷資料量是否足夠"],[],["顯著機率","檢定各自變數係數是否具統計顯著性"],["殘差值","實際觀測值與預測值之差"]]},{"id":"h:107-4","p":"h","src":"107年第4題","sec":"H3I1","stem":"採計量模型分析法估價，若自變數個數為6個，依規則規定樣本數至少應為多少？","opts":["30","18","24","36"],"ok":[0],"ex":["§20(一) 規定比較標的件數須為自變數個數五倍以上，6×5＝30，與本選項相符。","18＝6×3，未正確套用5倍規定。","24＝6×4，未正確套用5倍規定。","36＝6×6，超過規則規定5倍之最低要求，本選項數值偏高。"],"tr":"","core":["6×5＝30","6×3，未套用5倍規定","6×4，未套用5倍規定","6×6，超過5倍最低要求"],"hl":[[],["18","未正確套用5倍規定"],["24","未正確套用5倍規定"],["36","超過規則規定5倍之最低要求"]]},{"id":"h:108-21","p":"h","src":"108年第21題","sec":"H3I1","stem":"計量模型分析法中，判定係數應達多少以上方屬模型解釋能力良好？","opts":["0.5","0.6","0.7","0.9"],"ok":[2],"ex":["0.5並非§20(二) 之門檻，標準過低。","0.6並非§20(二) 之門檻。","§20(二) 規定採迴歸分析者，調整後判定係數不得低於0.7，與題目相符。","0.9雖更嚴格，但§20(二) 之門檻是0.7（不得低於0.7），並非0.9。"],"tr":"","core":["門檻是0.7，0.5過低","門檻是0.7，不是0.6","調整後判定係數不得低於0.7","門檻是0.7，不是0.9"],"hl":[["0.5"],["0.6"],[],["0.9","門檻是0.7"]]},{"id":"h:109-20","p":"h","src":"109年第20題","sec":"H3I1","stem":"內政部近年積極試辦電腦輔助大量估價(CAMA)，於應用計量模型分析法應符合之條件，下列敘述何者錯誤？","opts":["計量模型分析採迴歸分析者，相關係數不得低於零點八","須蒐集應用計量模型分析關係式自變數個數五倍以上之比較標的","計量模型分析採迴歸分析者，其調整後判定係數不得低於零點七","截距項以外其他各主要影響價格因素之係數估計值同時為零之顯著機率不得大於百分之五"],"ok":[0],"ex":["錯誤：§20規定的是「調整後判定係數不得低於0.7」，沒有「相關係數不得低於0.8」的條件，即本題答案。","比較標的應達自變數個數5倍以上，敘述正確。","調整後判定係數不得低於0.7，敘述正確。","顯著機率不得大於5%，敘述正確。"],"tr":"","core":["規定是判定係數0.7，無相關係數0.8","比較標的達自變數個數5倍以上","調整後判定係數不得低於0.7","顯著機率不得大於5%"],"hl":[["相關係數不得低於零點八","調整後判定係數不得低於0.7"],[],[],[]]},{"id":"h:111-6","p":"h","src":"111年第6題","sec":"H3I1","stem":"採計量模型分析法估價，若自變數個數為8個，依規則規定樣本數至少應為多少？","opts":["40","32","24","48"],"ok":[0],"ex":["§20(一) 規定比較標的件數須為自變數個數五倍以上，8×5＝40，與本選項相符。","32＝8×4，未正確套用5倍規定。","24＝8×3，未正確套用5倍規定。","48＝8×6，超過規則規定5倍之最低要求，本選項數值偏高。"],"tr":"","core":["8×5＝40","8×4，未套用5倍規定","8×3，未套用5倍規定","8×6，超過5倍最低要求"],"hl":[[],["32","未正確套用5倍規定"],["24","未正確套用5倍規定"],["48","超過規則規定5倍之最低要求"]]},{"id":"h:111-9","p":"h","src":"111年第9題","sec":"H3I1","stem":"計量模型分析法中，用以檢定模型中各自變數係數是否具統計顯著性之指標，稱為：","opts":["顯著機率","判定係數","樣本數","自變數個數"],"ok":[0],"ex":["官方答案A（顯著機率）。§20(三) 規定截距項以外各主要影響價格因素之係數估計值同時為零之顯著機率（即整體模型F檢定）不得大於5%；§20 係就係數整體同時為零作檢定，「逐一檢定各自變數係數」為題幹用語，結論仍以顯著機率為準。","判定係數（R²）是衡量整體模型解釋能力之指標，非檢定各自變數係數是否顯著之指標。","樣本數是觀察值數量，非用以檢定各自變數係數統計顯著性之指標。","自變數個數是模型中解釋變數之數量，非統計顯著性指標。"],"tr":"","core":["依官方答案：顯著機率","判定係數衡量整體解釋能力","樣本數是觀察值數量","自變數個數非顯著性指標"],"hl":[[],["判定係數","衡量整體模型解釋能力之指標"],["樣本數","觀察值數量"],["自變數個數","模型中解釋變數之數量"]]},{"id":"h:112-16","p":"h","src":"112年第16題","sec":"H3I1","stem":"有關計量模型分析法之敘述，下列何者錯誤？","opts":["樣本數應為自變數個數之5倍以上","判定係數越低代表模型解釋能力越好","顯著機率不得大於5%","模型用以估計不動產價格與各影響因素間之量化關係"],"ok":[1],"ex":["樣本數應為自變數個數之5倍以上，是規則明定之正確適用條件，非本題答案（本題問「何者錯誤」）。","判定係數愈「高」代表模型解釋能力愈好（統計學／教材說法；技術規則§20第2款只規定調整後判定係數不得低於0.7）。本選項說「愈低愈好」，方向相反，即本題正解。","顯著機率不得大於5%，是規則明定之正確適用條件，敘述正確。","模型用以估計不動產價格與各影響因素間之量化關係，為正確敘述。"],"tr":"","core":["樣本數應為自變數個數5倍以上","判定係數愈高解釋能力愈好","顯著機率不得大於5%","估計價格與影響因素之量化關係"],"hl":[[],["越低代表模型解釋能力越好","愈「高」代表模型解釋能力愈好"],[],[]]},{"id":"h:VI2_01","p":"h","src":"刷題補充題 VI2_01","sec":"I2J1","stem":"依不動產估價技術規則§107（準用土地法第5條），土地改良物分為哪兩類？","opts":["建築改良物及農作改良物","建築改良物及土壤改良物","建築改良物及林木竹木","農作改良物及水產養殖物"],"ok":[0],"ex":["§107：土地改良物之分類，依土地法第五條規定。土地法§5：土地改良物分為建築改良物及農作改良物（附著於土地之建築物或工事為建築改良物；附著於土地之農作物及其他植物與水利土壤之改良為農作改良物）。本選項正確。補習班口訣「建農林水土」五大類是教材說法，不是條文分類。","土地法§5把「水利土壤之改良」歸入農作改良物，不是另立一類；條文只有建築改良物、農作改良物兩類。","林木竹木屬「附著於土地之農作物及其他植物」，歸入農作改良物（§109也列竹類、造林木），不是另立一類。","技術規則與土地法§5都沒有「水產養殖物」這一類；且漏了建築改良物。"],"tr":"","core":["分為建築改良物及農作改良物","水利土壤改良歸入農作改良物","林木竹木歸入農作改良物","無水產養殖物這類，且漏建築改良物"],"hl":[[],["土壤改良物","「水利土壤之改良」歸入農作改良物"],["林木竹木","歸入農作改良物"],["水產養殖物"]]},{"id":"h:VI2_02","p":"h","src":"刷題補充題 VI2_02","sec":"I2J1","stem":"依不動產估價技術規則，建物之估價方法以何者為原則？","opts":["比較法","成本法","收益法","直接資本化法"],"ok":[1],"ex":["依§108，建物估價以成本法為原則，不是比較法。","技術規則明定建物之估價以成本法（重建或重置成本扣除折舊）為原則，本選項正確。","收益法適用於具收益性之不動產，但建物本身通常以成本法估算價值，再配合房地整體收益法估算。","直接資本化法屬於收益法之一種，非建物估價之原則方法。"],"tr":"","core":["建物以成本法為原則，非比較法","建物估價以成本法為原則","建物本身通常以成本法估算","直接資本化法屬收益法，非原則"],"hl":[["比較法","建物估價以成本法為原則"],[],["收益法","建物本身通常以成本法估算價值"],["直接資本化法","屬於收益法之一種"]]},{"id":"h:VI2_03","p":"h","src":"刷題補充題 VI2_03","sec":"I2J1","stem":"農作改良物應單獨估算的情況，下列何者正確？","opts":["土地及農作改良物所有人不同時","農作改良物成熟可採收時","農作改良物種植未滿一年時","土地所有人要求時"],"ok":[0],"ex":["（教材說法，非技術規則條文）所有人不同時應單獨估算農作改良物，乃補習班/教材之觀念；§109–§111 只規範農作改良物之估價方法，並無「應單獨估算」之明文。","農作改良物是否成熟可採收與應否單獨估算無關，技術規則並無此項規定。","種植年限長短與應否單獨估算無關，技術規則並無此項規定。","是否單獨估算農作改良物屬教材觀念（技術規則§109–§111無規定）；教材以「土地與農作改良物所有人不同」為判斷標準，不是看土地所有人的主觀要求。"],"tr":"","core":["依教材：所有人不同時應單獨估算","成熟可採收與應否單獨估算無關","種植年限與應否單獨估算無關","標準是所有人不同，非土地所有人要求"],"hl":[[],["成熟可採收時"],["種植未滿一年時"],["土地所有人要求時","土地與農作改良物所有人不同"]]},{"id":"h:VI2_04","p":"h","src":"刷題補充題 VI2_04","sec":"I2J1","stem":"林木之估算，成熟林（達採收期）與未成熟林分別適用何種方式？","opts":["成熟林用成本法；未成熟林用市場法","成熟林用市場銷售價值法；未成熟林用成本法","成熟林與未成熟林均用成本法","成熟林與未成熟林均用市場法"],"ok":[1],"ex":["本選項顛倒：§111 接近孳息成熟期者以收穫量及市場價格估計，幼小者則依種植及培育費用（成本導向）。","本選項正確，方向與§111 大致相符：§111（農作改良物，§109 含造林木）三款為：①幼小且距孳息成熟期尚長者，依其種植及培育費用，並視作物生長情況估計；②接近孳息成熟期者，應估計其收穫量及市場價格，必要時得扣減收成所應投入之費用；③距成熟期一年以上且有期待收穫價值者，得以產地價格為基礎，推估未來收穫價格後折算為價格日期之價格，並扣除收成所應投入之費用。「成熟林」「未成熟林」「市場銷售價值法」並非條文用語（教材簡化說法）。","並非均用成本法：§111 接近孳息成熟期者，應估計其收穫量及市場價格。","並非均用市場法：§111 幼小且距孳息成熟期尚長者，依其種植及培育費用估計。"],"tr":"","core":["方向顛倒，幼小者依培育費用","成熟看市場價格，未成熟依成本","接近成熟期者應估收穫量及市價","幼小者依種植及培育費用估計"],"hl":[["成熟林用成本法；未成熟林用市場法","接近孳息成熟期者以收穫量及市場價格估計","幼小者則依種植及培育費用"],[],["均用成本法","接近孳息成熟期者，應估計其收穫量及市場價格"],["均用市場法","幼小且距孳息成熟期尚長者，依其種植及培育費用估計"]]},{"id":"h:VI2_05","p":"h","src":"刷題補充題 VI2_05","sec":"I2J1","stem":"土壤改良物估價以何種方式為主？需考慮哪些因素？","opts":["成本法，考慮改良費用現值及效益殘存年限","比較法，考慮同區域農地改良後成交價","收益法，考慮改良後農業收益增加額","市場法，考慮同類改良物市場交易價格"],"ok":[0],"ex":["§112 規定附著於土地之工事及水利土壤之改良，以成本法估價為原則，但得斟酌比較法及收益法估價之結果，決定其估價額，本選項「成本法」符合；至於「改良費用現值」「效益殘存年限」等考慮因素，§112 並無列舉，屬教材說法。","§112 只規定得斟酌比較法之結果，並非以比較法為原則。","§112 只規定得斟酌收益法之結果，並非以收益法為主。","「市場法」非§112 用語，且§112 以成本法為原則。"],"tr":"","core":["工事及水利土壤改良以成本法為原則","比較法僅供斟酌，非原則","收益法僅供斟酌，非為主","市場法非條文用語，原則是成本法"],"hl":[[],["比較法"],["收益法"],["市場法","以成本法為原則"]]},{"id":"h:VI2_06","p":"h","src":"刷題補充題 VI2_06","sec":"I2J1","stem":"依技術規則，建物估價時「重建成本」與「重置成本」的差異為何？","opts":["重建成本是估計重新建造之成本；重置成本是估計維修現有建物之成本","重建成本是以原材料重新建造；重置成本是以現代替代材料建造","重建成本較重置成本為高，因原材料更昂貴","重置成本是指建物殘值，重建成本是指總造價"],"ok":[1],"ex":["重建成本並非維修成本，而是指以相同或極類似建材重新複製原建物之成本。","技術規則明定：重建成本是以相同或極類似建材標準重新複製之成本（原則）；重置成本是當建材已無生產或施工方法改變時，以現代替代建材標準建造之成本（例外適用）。本選項正確。","兩者成本高低需視個案情況，並無必然高低關係。","重置成本並非殘值之概念，而是以現代材料替代的新建成本。"],"tr":"","core":["重建成本是重新複製，非維修成本","重建用原材料，重置用現代替代材料","兩者高低視個案，無必然關係","重置成本是現代材料新建，非殘值"],"hl":[["估計維修現有建物之成本","以相同或極類似建材重新複製原建物之成本"],[],["重建成本較重置成本為高","兩者成本高低需視個案情況"],["重置成本是指建物殘值","以現代材料替代的新建成本"]]},{"id":"h:VI2_07","p":"h","src":"刷題補充題 VI2_07","sec":"I2J1","stem":"建物折舊之計算，技術規則明定可採何種方法？","opts":["僅定額法（直線法）","定額法或定率法，由估價師自由選擇","應視建物特性及市場動態，選擇等速折舊、初期加速折舊或初期減速折舊路徑之折舊方法","市場萃取法，以市場成交數據推算折舊率"],"ok":[2],"ex":["§68Ⅰ 並非僅限單一方法，而是依建物特性及市場動態，選擇等速、初期加速或初期減速折舊路徑之方法。","定額法約相當等速折舊、定率法約相當初期加速折舊，但§68Ⅰ 之用語為三種折舊路徑，且須視建物特性及市場動態選擇，並非由估價師任意選擇。","§68Ⅰ逐字：「建物累積折舊額之計算，應視建物特性及市場動態，選擇屬於等速折舊、初期加速折舊或初期減速折舊路徑之折舊方法。」本選項正確。（教材另有耐用年數法、觀察折舊法、分解法等分類，不是條文用語。）","市場萃取法是推算資本化率等之方式，並非§68 之折舊計算方法。"],"tr":"","core":["非僅限單一方法，有三種折舊路徑","須視建物特性及市場動態，非任意選","視特性選等速、初期加速或減速路徑","市場萃取法非折舊計算方法"],"hl":[["僅定額法（直線法）","選擇等速、初期加速或初期減速折舊路徑"],["由估價師自由選擇","須視建物特性及市場動態選擇"],[],["市場萃取法"]]},{"id":"h:VI2_08","p":"h","src":"刷題補充題 VI2_08","sec":"I2J1","stem":"依教材（技術規則無水產養殖物專條），水產養殖物之估算原則為何？","opts":["以飼養成本估算","以市場銷售價值估算（扣除採收成本）","以收益法，以年漁獲量折現估算","以比較法，比較同類養殖場成交價"],"ok":[1],"ex":["（條文無規定，補習班/教材說法）飼養成本屬成本法概念；技術規則全文無水產養殖物之估價規定。","教材類推§111農作改良物接近成熟期之作法：以市場銷售價值扣除採收成本估算（技術規則無水產養殖物專條）。","（教材說法）年漁獲量折現屬收益法概念，條文無此規定。","（教材說法）比較法需有可比較案例；條文無水產養殖物之規定。"],"tr":"","core":["飼養成本屬成本法，條文無規定","依教材：市場銷售價值扣採收成本","年漁獲量折現屬收益法，無此規定","條文無水產養殖物之規定"],"hl":[["飼養成本"],[],["收益法"],["比較法"]]},{"id":"h:VJ1_01","p":"h","src":"刷題補充題 VJ1_01","sec":"I2J1","stem":"依不動產估價技術規則，數筆土地合併為一宗進行土地利用之估價，各筆土地之價格如何求得？","opts":["以合併後宗地面積平均分配","以合併後土地估價，並以合併前各筆土地價值比例分算其土地價格","以各宗地地目類別決定分配比例","由估價師依估價目的自由決定"],"ok":[1],"ex":["面積平均分配未考量各筆土地合併前之價值差異，不符§84。","§84Ⅰ明定：數筆土地合併為一宗進行土地利用之估價，應以合併後土地估價，並以合併前各筆土地價值比例分算其土地價格，本選項正確。","地目雖影響價值，但分算比例依「合併前各筆土地價值」，非單純以地目決定。","§84有明定分算方式，估價師不得自由決定。"],"tr":"","core":["面積平均未考量合併前價值差異","合併後估價，依合併前價值比例分算","分算依合併前價值，非地目","條文有明定分算方式，不得自由決定"],"hl":[["平均分配"],[],["地目類別","合併前各筆土地價值"],["自由決定","§84有明定分算方式"]]},{"id":"h:VJ1_02","p":"h","src":"刷題補充題 VJ1_02","sec":"I2J1","stem":"依不動產估價技術規則，以合併或分割為前提之宗地估價，應如何處理？","opts":["不必考慮合併或分割，僅依現況估價","應考慮合併或分割前後之價格變動情形，而予酌量增減","一律以合併後價格為準","一律評估為特殊價格"],"ok":[1],"ex":["§83 明定須考慮合併或分割前後之價格變動，不可僅依現況。","§83：以合併或分割為前提之宗地估價，應考慮合併或分割前後之價格變動情形，而予酌量增減，本選項正確。","合併不一定增值，分割也可能減值，須依前後價格變動酌量增減，非一律以合併後價格為準。","特殊價格指不具市場性之不動產（§2），與合併分割無關；合併、分割依§2可能形成限定價格。"],"tr":"","core":["須考慮合併分割前後價格變動","考慮前後價格變動而酌量增減","非一律以合併後價格為準","特殊價格指不具市場性，與此無關"],"hl":[["不必考慮合併或分割","須考慮合併或分割前後之價格變動"],[],["一律以合併後價格為準","須依前後價格變動酌量增減"],["一律評估為特殊價格","合併、分割依§2可能形成限定價格"]]},{"id":"h:VJ1_03","p":"h","src":"刷題補充題 VJ1_03","sec":"I2J1","stem":"依技術規則§85，一宗土地內有數種不同法定用途時，應如何估價？","opts":["取各種用途估價結果之平均值","以面積最大之使用部分之單位價格估算全部","考量最有效使用、各種用途之相關性及分割難易度後，決定分別估價或依主要用途估價","以最高價值之使用目的估算全部"],"ok":[2],"ex":["取各種用途之平均值，無法反映不同使用目的之實際價值差異，不符合估價原則。","以面積最大部分之單位價格估算全部，與§85「依主要用途估價」相近，但須先考量最有效使用、各用途相關性及分割難易度，並非單純取面積最大者。","§85逐字：「一宗土地內有數種不同法定用途時，應考量其最有效使用及各種用途之相關性及分割之難易度後，決定分別估價或依主要用途估價。」本選項正確。","以最高價值用途估算全部，不是§85的處理方式；§85要求先考量最有效使用、各用途相關性及分割難易度，再決定分別估價或依主要用途估價。"],"tr":"","core":["平均值無法反映用途價值差異","須先考量最有效使用等，非取最大面積","考量後決定分別估價或依主要用途","非以最高價值用途估算全部"],"hl":[["平均值"],["以面積最大之使用部分之單位價格估算全部","須先考量最有效使用、各用途相關性及分割難易度"],[],["以最高價值之使用目的估算全部","再決定分別估價或依主要用途估價"]]},{"id":"h:VJ1_04","p":"h","src":"刷題補充題 VJ1_04","sec":"I2J1","stem":"宗地上有建物時，「獨立估價」與「部分估價」之差異為何？","opts":["獨立估價考量建物對地價之影響；部分估價不考量","獨立估價不考量建物影響（視為素地）；部分估價考量建物影響","獨立估價指土地與建物分開估價；部分估價指房地合一估價","獨立估價只估土地；部分估價只估建物"],"ok":[1],"ex":["與§86 意旨相反：附有建物宗地原則上應考慮建物對宗地價格之影響。","§86：附有建物之宗地估價，應考慮該建物對該宗地價格造成之影響；但以素地估價為前提並於估價報告書敘明者，不在此限。「獨立估價」「部分估價」非條文用語（教材說法）；本選項「視為素地 vs 考量建物影響」之對照，與§86 本文及但書意旨相符。","並非房地合一與分開之概念，重點是是否考慮建物對宗地價格之影響（§86）。","兩種方式均是針對土地的估價，而非限定只估建物。"],"tr":"","core":["意旨相反，原則上應考慮建物影響","獨立估價視為素地，部分估價考量建物","重點在是否考慮建物對地價影響","兩者均是針對土地的估價"],"hl":[["獨立估價考量建物對地價之影響","附有建物宗地原則上應考慮建物對宗地價格之影響"],[],["分開估價","房地合一估價","重點是是否考慮建物對宗地價格之影響"],["只估建物","兩種方式均是針對土地的估價"]]},{"id":"h:VJ1_05","p":"h","src":"刷題補充題 VJ1_05","sec":"I2J1","stem":"依技術規則§88，宗地受架空線路或地下埋設管線等設施限制時，其估價程序為何？","opts":["直接以成本法估算設施修建成本","先估計無設施限制之正常價格，再扣除設施限制造成之減損金額","以受限制之宗地直接比較附近無限制地之交易案例","由相關主管機關公告補償標準，直接適用"],"ok":[1],"ex":["§88 為先估算正常價格，再扣除地價減損額，並非採成本法估算設施修建成本。","§88：土地之上下因有其他設施通過致使用受限制之宗地，應先估算其正常價格，再考量該設施通過造成土地利用之影響，並計算其地價減損額後，從正常價格中扣除之，以其餘額為該宗地之價格，本選項正確。","§88 要求先估算正常價格，再計算地價減損額後扣除，並非直接以受限宗地與無限制地之交易案例比較了事。","主管機關補償標準可作參考，但§88 之估價程序為先估正常價格再扣除地價減損額。"],"tr":"","core":["先估正常價格再扣減損，非成本法","先估正常價格，再扣地價減損額","須先估正常價格再扣減損額","程序是先估正常價格再扣減損額"],"hl":[["成本法估算設施修建成本","先估算正常價格，再扣除地價減損額"],[],["直接比較附近無限制地之交易案例","先估算正常價格，再計算地價減損額後扣除"],["直接適用","先估正常價格再扣除地價減損額"]]},{"id":"h:VJ1_06","p":"h","src":"刷題補充題 VJ1_06","sec":"I2J1","stem":"依技術規則§89，受有土壤或地下水污染之土地，其估價程序為何？","opts":["比較法（以附近相似污染地為比較標的）","收益法（以污染後之預期收益折現）","先估算未受污染之正常價格，再依委託人提供之檢測資料計算地價減損額後扣除","殘餘法（以未受污染時之價值回推）"],"ok":[2],"ex":["§89沒有規定以污染地為比較標的；而是先估「未受污染」之正常價格，再扣地價減損額。","§89沒有規定以污染後收益折現；而是先估「未受污染」之正常價格，再扣地價減損額。","§89：「應先估算其未受污染之正常價格，再依據委託人提供之土壤污染檢測資料，考量該土壤或地下水污染之影響，並計算其地價減損額後，從正常價格中扣除之，以其餘額為該宗地之價格。」本選項正確。","殘餘法是收益法中推算未知部分價值的技巧（教材），不是§89的程序；§89是正常價格扣地價減損額。"],"tr":"","core":["先估未受污染正常價格，再扣減損","先估未受污染正常價格，再扣減損","先估未受污染正常價格，再扣減損額","殘餘法非此程序，應扣地價減損額"],"hl":[["以附近相似污染地為比較標的","先估「未受污染」之正常價格，再扣地價減損額"],["以污染後之預期收益折現","先估「未受污染」之正常價格，再扣地價減損額"],[],["殘餘法","正常價格扣地價減損額"]]},{"id":"h:VJ1_07","p":"h","src":"刷題補充題 VJ1_07","sec":"I2J1","stem":"下列有關宗地分割之敘述，何者正確？","opts":["分割通常增加各分割後宗地之總價值","分割前應確認是否違反最有效使用原則","違反經濟合理性之分割，分割後各宗地應出具正常價格","技術規則不規範宗地分割之估價程序"],"ok":[1],"ex":["違反經濟合理性之分割通常造成價值損失（學理說法）；§83 規定以分割為前提之估價，應考慮分割前後價格變動情形而酌量增減。","§83 規定以分割為前提之宗地估價，應考慮分割前後價格變動；§2 第二款第（三）目規定「以違反經濟合理性之不動產分割為前提」所形成之價值為限定價格。故分割估價需先判斷分割是否合理（「最有效使用原則」為學理用語），本選項大致相符。","與§2 不符：以違反經濟合理性之不動產分割為前提者形成限定價格（§2 第二款第（三）目），並非「出具正常價格」；且§6 後段 只有特定價格須同時估計正常價格，限定價格不須。","§83 規範以合併或分割為前提之宗地估價，本選項有誤。"],"tr":"","core":["違反經濟合理性的分割常致價值損失","分割估價須先判斷分割是否合理","違反經濟合理性分割形成限定價格","有規範合併或分割為前提之估價"],"hl":[["通常增加","違反經濟合理性之分割通常造成價值損失"],[],["應出具正常價格","形成限定價格"],["技術規則不規範","§83 規範以合併或分割為前提之宗地估價"]]},{"id":"h:VJ1_08","p":"h","src":"刷題補充題 VJ1_08","sec":"I2J1","stem":"有關設施限制宗地（§88）與污染宗地（§89）估價方式，下列比較何者正確？","opts":["兩者均採成本法估算","設施限制採成本法；污染宗地採比較法","兩者均先估算（未受污染之）正常價格，再扣除地價減損額，以其餘額為宗地價格","兩者均採比較法"],"ok":[2],"ex":["§88、§89 條文均未稱「成本法」，兩者機制相同。","§88、§89 條文均為先估正常價格再扣除地價減損額，並無「設施限制採成本法；污染採比較法」之區分。","§88、§89機制相同：均先估算（未受污染之）正常價格，再計算地價減損額後自正常價格中扣除，以其餘額為該宗地之價格。本選項正確。","§88、§89 條文均未稱「比較法」，兩者為正常價格減地價減損額之方式。"],"tr":"","core":["條文未稱成本法，兩者機制相同","兩者皆正常價格扣減損，無此區分","均先估正常價格，再扣地價減損額","條文未稱比較法，兩者機制相同"],"hl":[["兩者均採成本法估算"],["設施限制採成本法","污染宗地採比較法","先估正常價格再扣除地價減損額"],[],["兩者均採比較法","正常價格減地價減損額"]]},{"id":"h:VJ1_09","p":"h","src":"刷題補充題 VJ1_09","sec":"I2J1","stem":"依§83、§2，宗地分割後，面積較小之分割地如無法獨立使用，其估價應如何處理？","opts":["以其面積比例分配分割前宗地之正常價格","出具限定價格，以與相鄰土地合併使用為前提估算其價值","以特殊價格估算，反映其不具市場性","由主管機關公告土地價格"],"ok":[1],"ex":["面積比例分配未反映小地塊因無法獨立使用而產生之價值損失。","§83：以分割為前提之宗地估價，應考慮分割前後價格變動情形；§2 第二款規定以不動產合併為目的（第(二)目）或以違反經濟合理性之不動產分割為前提（第(三)目）所形成之價值為限定價格。故分割後無法獨立使用之小地，以與相鄰土地合併使用為前提估算，出具限定價格，大致符合。","特殊價格適用於不具市場性之情形，此類土地雖難以獨立交易，但在特定合併目的下仍具市場性，故非特殊價格。","土地估價為估價師之職責，非由主管機關公告個別土地價格。"],"tr":"","core":["面積比例未反映無法獨立使用之損失","以合併使用為前提，出具限定價格","特定合併目的下仍具市場性","土地估價是估價師職責"],"hl":[["面積比例分配"],[],["特殊價格","在特定合併目的下仍具市場性"],["由主管機關公告土地價格","土地估價為估價師之職責"]]},{"id":"h:VJ1_10","p":"h","src":"刷題補充題 VJ1_10","sec":"I2J1","stem":"依技術規則，違章建築應如何處理於估價過程中？","opts":["違章建築部分以重建成本×50%估算，反映其法律風險","違章建築部分一律不予評估；如委託人要求，則就合法建物及違章建築分別標示價格","違章建築影響地價，應自土地估價中扣除拆除費用","違章建築需取得主管機關同意後，方可估算其價值"],"ok":[1],"ex":["以重建成本×50%估算並非技術規則之規定，無此種比例折算規定。","§103明定違建部分不予評估；但委託人要求評估時，應就合法建物及違建部分於估價報告書中分別標示各該部分之價格，本選項正確。","§103對違章建築的處理是「違建部分不予以評估」（委託人要求時分別標示價格），沒有規定從土地估價中扣除拆除費用；要考量拆除成本的是§106「建物已不具備使用價值」得將基地視為素地估價的情形，兩者不同。","估價師估算違章建築不需取得主管機關同意，是否估算及如何呈現由技術規則規定。"],"tr":"","core":["無重建成本×50%的折算規定","違建不予評估，要求時分別標示","違建不予評估，無扣拆除費用規定","不需取得主管機關同意"],"hl":[["重建成本×50%"],[],["自土地估價中扣除拆除費用","違建部分不予以評估"],["需取得主管機關同意後","不需取得主管機關同意"]]},{"id":"h:VI2_J1_综合1","p":"h","src":"刷題補充題 VI2_J1_综合1","sec":"I2J1","stem":"依不動產估價技術規則，下列有關土地改良物之敘述，何者有誤？","opts":["土地改良物之分類，依土地法第五條規定","建物估價以成本法為原則，惟得採收益法或比較法","農作改良物接近孳息成熟期者，應估計其收穫量及市場價格","土壤改良物之估價以收益法為主，考量改良後農業收益增加額"],"ok":[3],"ex":["與§107逐字相符，敘述正確，非本題答案。","§108規定建物估價以成本法為原則；依§14須兼採二種以上估價方法，所以得併採收益法或比較法，敘述正確，非本題答案。","與§111第2款相符，敘述正確，非本題答案。","§112 規定附著於土地之工事及水利土壤之改良，以成本法估價為原則，但得斟酌比較法及收益法；本選項稱以收益法為主、考量農業收益增加額，與§112 不符，即本題正解。"],"tr":"","core":["分類依土地法第五條規定","以成本法為原則，得併採他法","接近成熟期估收穫量及市場價格","土壤改良以成本法為原則，非收益法"],"hl":[[],[],[],["以收益法為主","以成本法估價為原則"]]},{"id":"h:VI2_J1_综合2","p":"h","src":"刷題補充題 VI2_J1_综合2","sec":"I2J1","stem":"甲所有A地（正常地價500萬）與乙所有B地（正常地價300萬）合併後，總價值共900萬元（合併增值100萬）。請問甲之A地合併後應分配之限定價格為何？","opts":["500萬元","450萬元","562.5萬元","600萬元"],"ok":[2],"ex":["500萬元為A地合併前之正常地價，未反映合併後之增值分配，不符合限定價格計算結果。","450萬元是把合併後總價900萬元由甲乙平均分配（900÷2）的誤算；依§84應按合併前價值比例5/8分算：900×5/8＝562.5萬元。","按合併前價值比例分配增值：甲分配比例=500/800=5/8；甲分配增值=100×5/8=62.5萬；A地限定價格=500+62.5=562.5萬元，本選項正確。","600萬元是把合併增值100萬元全部歸給甲（500＋100）的誤算；依§84應按合併前價值比例分配，甲只分得增值62.5萬元，合計562.5萬元。"],"tr":"","core":["只是合併前地價，未分配增值","平均分配的誤算，應按價值比例","500＋增值100×5/8＝562.5萬","增值全歸甲的誤算"],"hl":[["500萬元","A地合併前之正常地價"],["450萬元","900×5/8＝562.5萬元"],[],["600萬元","甲只分得增值62.5萬元，合計562.5萬元"]]}]};
